    couch_open_keys = "GAMEPAD_BACK", -- Gamepad / remote key(s) that open and close the poster browser (not used with couch_mode=no)
    remember_tracks = true,         -- Remember the audio + subtitle language per show (pick once, every episode starts that way)
    next_episode_card = true,       -- "Next episode in 10..." card near the end credits / ED chapter (Esc = stay, Enter = play now)
    next_episode_secs = 10,         -- Length of that countdown
    now_playing_card = true,        -- a small card for a few seconds when a file starts from the browser / add screen
    now_playing_secs = 4,           -- how long it stays
    -- New in 23: where the cards and the startup toast sit: top-left, top, top-right, bottom-left, bottom, bottom-right
    next_card_position = "bottom-right",
    now_playing_position = "bottom-left",
    startup_toast_position = "top-right",
    torrent_fallback = "auto",      -- Real-Debrid refuses a release or its link won't play: auto = stream it as a torrent
