    glass_blur = true,              -- the cards blur the video behind them (needs vo=gpu-next; otherwise they are tinted)
    animation_fps = 0,              -- animations: 0 = the display's refresh rate, at most 90
    ui_size_steps = true,           -- sizes in steps of the window height: resizing reflows the grid instead of re-converting pictures
    next_episode_timing = "auto",   -- auto | credits | before : before = the countdown ends where the ED / credits begin (for
                                    -- chapter-skip scripts like op-ed-pv-skip); auto = before when such a script is loaded
    experimental_backdrop = false,  -- Title page: large TMDB backdrop beside the text, faded into the background
    -- New in 14 (EXPERIMENTAL): add releases to Real-Debrid from Stremio add-ons (AIOStreams, Comet...)
    addon_urls = "",                -- add-on manifest URLs separated by spaces / ";" (they may contain your RD key: keep private)
    aiostreams_password = "",       -- AIOStreams: your config password -> its search API (real file / pack names and sizes)
    nyaa_url = "https://nyaa.si",   -- Add screen, Nyaa.si search (Tab): the site (or a mirror)
    startup_toast = true,           -- a short glass note when mpv starts: ready, the key, and whether ffmpeg was found
    nyaa_category = "1_0",          -- 0_0 everything, 1_0 anime, 1_2 anime English-translated, 1_4 anime raw, 4_0 live action
    add_key = "n",                  -- Home / title page: open "Add from add-ons"
    -- New in 19
    addon_region = "US",            -- Add screen home: the country for the streaming-services row (2 letters: US, GB, DE, NL...)
    addon_providers = "Netflix=8; Prime Video=9|119; HBO Max=1899|384; Apple TV+=350",   -- that row: name=TMDB provider id(s)
    torrent_client = "rqbit",       -- rqbit (github.com/ikatson/rqbit): streams a torrent Real-Debrid refuses ("" = off)
    torrent_port = 3030,            -- rqbit's local HTTP port (an rqbit that already runs there is used as it is)
    torrent_client_args = "",       -- extra rqbit options, e.g. "--ratelimit-download 20000000"
    torrent_start_mb = 50,          -- MB of the file downloaded (progress bar on screen) before playback starts
    torrent_trackers = "udp://tracker.opentrackr.org:1337/announce udp://open.stealth.si:80/announce udp://tracker.torrent.eu.org:451/announce udp://exodus.desync.com:6969/announce udp://open.demonii.com:1337/announce http://nyaa.tracker.wf:7777/announce",
    -- New in 17: keys inside the browser (space-separated mpv key names; empty = no key). They only exist while the
