-- ============================================================
-- BACKGROUND BLUR (real video filter, not just an overlay effect)
-- ============================================================
local function apply_background_blur()
    if blur_applied then return end
    if not o.background_blur_enabled then MS.blur_state = "disabled"; return end
    if not blur_supported then MS.blur_state = "unsupported by this mpv build"; return end
    local mode = tostring(o.background_blur_mode or "auto"):lower()
    if mode ~= "auto" and mode ~= "lite" and mode ~= "full" and mode ~= "off" then mode = "auto" end
    if mode == "off" then MS.blur_state = "off"; return end
    local sigma = tonumber(o.background_blur_strength) or 0
    if sigma <= 0 then MS.blur_state = "off (strength 0)"; return end
    if not mp.get_property("video-format") then MS.blur_state = "off (no video)"; return end

    if mode == "auto" then
        -- A software video filter on heavy video is costly, and on hardware-decoded video (without
        -- -copy) it can push mpv back to software decoding. auto mode skips blur in those cases.
        local vh = mp.get_property_number("height") or 0
        if vh > (tonumber(o.background_blur_max_height) or 1440) then
            MS.blur_state = string.format("skipped (%dp video)", vh); return
        end
        local hw = mp.get_property("hwdec-current") or ""
        if not o.background_blur_force and hw ~= "" and hw ~= "no" and not hw:find("%-copy$") then
            MS.blur_state = "skipped (hardware decoding: " .. hw .. ")"; return
        end
        mode = "lite"
    end

    local filter_str
    if mode == "lite" then
        -- shrink 4x, blur lightly, and let mpv's own scaler stretch it back up: looks the same, ~16x cheaper
        filter_str = string.format("@webdav_blur:lavfi=[scale=iw/4:-2:flags=fast_bilinear,gblur=sigma=%g:steps=1]",
            math.max(1, sigma / 4))
    else
        filter_str = string.format("@webdav_blur:lavfi=[gblur=sigma=%s]", tostring(sigma))
    end
    local ok_call, ok_result = pcall(function() return mp.commandv("vf", "add", filter_str) end)
    if ok_call and ok_result ~= false then
        blur_applied = true
        MS.blur_state = mode
    else
        blur_supported = false
        MS.blur_state = "unsupported by this mpv build"
        msg.warn("webdav-browser: background blur unsupported on this mpv build (needs libavfilter)")
    end
end

-- True if our blur filter is really in mpv's filter chain (independent of our own bookkeeping).
local function blur_in_chain()
    local ok, chain = pcall(mp.get_property_native, "vf")
    if not ok or type(chain) ~= "table" then return blur_applied end
    for _, f in ipairs(chain) do
        if type(f) == "table" and f.label == "webdav_blur" then return true end
    end
    return false
end

local function remove_background_blur()
    if blur_applied or blur_in_chain() then
        pcall(function() mp.commandv("vf", "remove", "@webdav_blur") end)
    end
    blur_applied = false
    MS.blur_state = "off"
end

-- ============================================================
-- MEDIA TYPE DETECTION
-- ============================================================
U.video_exts = {
    mp4=true, mkv=true, avi=true, mov=true, wmv=true, flv=true, webm=true,
    ts=true, m2ts=true, mpg=true, mpeg=true, vob=true, rm=true, rmvb=true,
    ["3gp"]=true, m4v=true, ogv=true,
}
U.audio_exts = {
    mp3=true, flac=true, ogg=true, oga=true, wav=true, aac=true,
    m4a=true, opus=true, wma=true, mka=true,
}

function U.ext_of(name) return name:match("%.([%w]+)$") end
function U.is_video(name) local e = U.ext_of(name); return e ~= nil and U.video_exts[e:lower()] == true end
function U.is_audio(name) local e = U.ext_of(name); return e ~= nil and U.audio_exts[e:lower()] == true end
function U.is_media(name) return U.is_video(name) or U.is_audio(name) end

-- ============================================================
-- SMALL UTILS
-- ============================================================
-- Accented Latin letters to plain ASCII ("Pokémon" -> "Pokemon", "Kyōkai" -> "Kyokai"), so a title written with or
-- without accents / macrons compares equal. Other characters are left as they are.
U.FOLD = {}
do
    local function set(lead, from, to, ascii) for b = from, to do U.FOLD[string.char(lead, b)] = ascii end end
    set(195, 128, 133, "A"); set(195, 134, 134, "AE"); set(195, 135, 135, "C"); set(195, 136, 139, "E"); set(195, 140, 143, "I")
    set(195, 144, 144, "D"); set(195, 145, 145, "N"); set(195, 146, 150, "O"); set(195, 152, 152, "O"); set(195, 153, 156, "U")
    set(195, 157, 157, "Y"); set(195, 159, 159, "ss"); set(195, 160, 165, "a"); set(195, 166, 166, "ae"); set(195, 167, 167, "c")
    set(195, 168, 171, "e"); set(195, 172, 175, "i"); set(195, 177, 177, "n"); set(195, 178, 182, "o"); set(195, 184, 184, "o")
    set(195, 185, 188, "u"); set(195, 189, 189, "y"); set(195, 191, 191, "y")
    set(196, 128, 128, "A"); set(196, 129, 129, "a"); set(196, 140, 140, "C"); set(196, 141, 141, "c"); set(196, 146, 146, "E")
    set(196, 147, 147, "e"); set(196, 170, 170, "I"); set(196, 171, 171, "i")
    set(197, 129, 129, "L"); set(197, 130, 130, "l"); set(197, 140, 140, "O"); set(197, 141, 141, "o"); set(197, 154, 154, "S")
    set(197, 155, 155, "s"); set(197, 160, 160, "S"); set(197, 161, 161, "s"); set(197, 170, 170, "U"); set(197, 171, 171, "u")
    set(197, 189, 189, "Z"); set(197, 190, 190, "z")
end
function U.fold(s)
    return (tostring(s or ""):gsub("[\195-\197][\128-\191]", U.FOLD))
end

function U.url_encode_segment(seg)
    return (seg:gsub("([^%w%-%_%.%~])", function(c) return string.format("%%%02X", string.byte(c)) end))
end

-- NOTE: no "+" -> " " step. That only applies to query strings / form data, never to URL
-- paths, and it used to turn names like "DD+5.1" into "DD 5.1".
function U.percent_decode(s)
    return (s:gsub("%%(%x%x)", function(h) return string.char(tonumber(h, 16)) end))
end

function U.xml_unescape(s)
    return s:gsub("&lt;", "<"):gsub("&gt;", ">"):gsub("&quot;", '"')
            :gsub("&apos;", "'"):gsub("&amp;", "&")
end

function U.basename(path)
    path = path:gsub("/+$", "")
    local name = path:match("([^/]+)$") or path
    return U.percent_decode(name)
end

U.http_months = {Jan=1,Feb=2,Mar=3,Apr=4,May=5,Jun=6,Jul=7,Aug=8,Sep=9,Oct=10,Nov=11,Dec=12}
function U.parse_http_date(s)
    if not s then return nil end
    local day, mon, year, hh, mm, ss = s:match("(%d+)%s+(%a+)%s+(%d+)%s+(%d+):(%d+):(%d+)")
    if not day or not U.http_months[mon] then return nil end
    local ok, t = pcall(os.time, {
        year=tonumber(year), month=U.http_months[mon], day=tonumber(day),
        hour=tonumber(hh), min=tonumber(mm), sec=tonumber(ss),
    })
    return ok and t or nil
end

function U.utf8_len(s)
    local n = 0
    for _ in s:gmatch("[\1-\127\194-\253][\128-\191]*") do n = n + 1 end
    return n
end

function U.utf8_sub(s, max_chars)
    if max_chars <= 0 then return "" end
    local out, n = {}, 0
    for ch in s:gmatch("[\1-\127\194-\253][\128-\191]*") do
        n = n + 1
        if n > max_chars then return table.concat(out) .. "…" end
        table.insert(out, ch)
    end
    return table.concat(out)
end


-- Natural ordering: "ep2" < "ep10", case-insensitive. Sorting a big folder compares the same names thousands of
-- times, so each name is turned ONCE into a key that plain string comparison orders the same way (lower case; every
-- run of digits written as its length, its value and its count of leading zeros) and the keys are kept.
-- Numbers of 10+ digits (hashes, dates with times) use the comparison below instead.
U.NK, U.NKn = {}, 0
function U.nat_key(s)
    local k = U.NK[s]
    if k ~= nil then return k end
    local long = false
    k = s:lower():gsub("%d+", function(d)
        local v = d:match("^0*(.-)$")
        local z = #d - #v
        if #v > 9 or z > 9 then long = true; return d end
        return string.char(48 + #v) .. v .. string.char(48 + z)
    end)
    if long then k = false end
    if U.NKn > 40000 then U.NK, U.NKn = {}, 0 end
    U.NK[s], U.NKn = k, U.NKn + 1
    return k
end
function U.natural_less(a, b)
    local ka, kb = U.nat_key(a), U.nat_key(b)
    if ka and kb then return ka < kb end
    return U.natural_less0(a, b)
end
function U.natural_less0(a, b)
    a, b = a:lower(), b:lower()
    local i, j = 1, 1
    local la, lb = #a, #b
    while i <= la and j <= lb do
        local ad, bd = a:match("^%d+", i), b:match("^%d+", j)
        if ad and bd then
            local an, bn = tonumber(ad), tonumber(bd)
            if an ~= bn then return an < bn end
            if #ad ~= #bd then return #ad < #bd end
            i, j = i + #ad, j + #bd
        else
            local ac, bc = a:sub(i, i), b:sub(j, j)
            if ac ~= bc then return ac < bc end
            i, j = i + 1, j + 1
        end
    end
    return (la - i) < (lb - j)
end

-- Search normalisation: release names use dots/underscores/dashes as word separators.
function U.norm_text(s)
    return (" " .. s:lower():gsub("[%._%-%[%]%(%)]+", " "):gsub("%s+", " ") .. " ")
end
function U.query_tokens(q)
    local toks = {}
    for w in U.norm_text(q):gmatch("%S+") do toks[#toks + 1] = w end
    return toks
end
-- Returns a score (higher = better) when EVERY token occurs in the name, else nil.
function U.match_score(name, toks)
    if #toks == 0 then return 0 end
    local hay = U.norm_text(name)
    local score = 0
    for _, tok in ipairs(toks) do
        local pos = hay:find(tok, 1, true)
        if not pos then return nil end
        if hay:sub(pos - 1, pos - 1) == " " then score = score + 3 else score = score + 1 end
    end
    return score
end

function U.fmt_time(sec)
    sec = math.max(0, math.floor(sec or 0))
    local h, m, s = math.floor(sec / 3600), math.floor(sec % 3600 / 60), sec % 60
    if h > 0 then return string.format("%d:%02d:%02d", h, m, s) end
    return string.format("%d:%02d", m, s)
end

function U.fmt_age(ts)
    if not ts then return "never" end
    local d = os.time() - ts
    if d < 0 then d = 0 end
    if d < 90 then return d .. "s ago" end
    if d < 5400 then return math.floor(d / 60) .. "m ago" end
    if d < 172800 then return math.floor(d / 3600) .. "h ago" end
    return math.floor(d / 86400) .. "d ago"
end

-- Parent directory href of a file/folder href ("/a/b/c.mkv" -> "/a/b/", "/a/b/" -> "/a/")
function U.dirname(href)
    local h = href:gsub("/+$", "")
    return h:match("^(.*/)[^/]+$") or "/"
end

function U.now_s() return mp.get_time() end

function U.ass_escape(s)
    -- a raw line break would end the ASS event and spill the rest on screen as a giant unstyled line
    -- a backslash is followed by an invisible zero-width character (as mpv's own OSC does): doubling it showed both
    -- ("C:\\Users\\..."), a single one could start an ASS tag ("\N")
    return (tostring(s):gsub("[\r\n]+", " "):gsub("\\", "\\\239\187\191"):gsub("{", "\\{"):gsub("}", "\\}"))
end

function U.fit_text(s, max_px, fs)
    local max_chars = math.max(1, math.floor(max_px / (fs * 0.62)))
    if U.utf8_len(s) <= max_chars then return s end
    return U.utf8_sub(s, math.max(1, max_chars - 1))
end

-- sizes and speeds: one decimal below 10 (3.4 MB, 8.1 GB), whole numbers above (31 MB), KB for small amounts
function U.fmt_bytes(n)
    n = tonumber(n) or 0
    if n >= 1073741824 then return string.format("%.1f GB", n / 1073741824) end
    if n >= 10485760 then return string.format("%.0f MB", n / 1048576) end
    if n >= 1048576 then return string.format("%.1f MB", n / 1048576) end
    return string.format("%.0f KB", n / 1024)
end

-- The window size comes from a property observer (cached), never a synchronous read: right after a burst of overlay
-- commands a synchronous read waits for mpv to finish drawing, which made every key press stall for a frame or more.
U.osd_w, U.osd_h = 0, 0
mp.observe_property("osd-dimensions", "native", function(_, v)
    if type(v) == "table" then U.osd_w, U.osd_h = tonumber(v.w) or 0, tonumber(v.h) or 0 end
end)
function U.canvas_size()
    local w, h = U.osd_w, U.osd_h
    if w >= 64 and h >= 64 then return math.floor(w), math.floor(h) end
    w = mp.get_property_number("osd-width") or 0
    h = mp.get_property_number("osd-height") or 0
    if w < 64 or h < 64 then
        local ow, oh = mp.get_osd_size()
        w, h = ow or 0, oh or 0
    end
    if w < 64 then w = 1280 end
    if h < 64 then h = 720 end
    return math.floor(w), math.floor(h)
end

-- ============================================================
-- PERSISTENCE (watch history, watched set, sort memory, directory cache / index)
-- ============================================================
local persist_status = { path = nil, ok = nil, last_save = nil, err = nil, bytes = 0 }
local sort_by_dir = {}                 -- directory href -> "name" | "recent"   (per-folder sort memory)
local index_meta = { last_full = nil } -- when the library index was last crawled completely

-- mp.get_script_directory() returns NOTHING for a single-file script (one that sits directly in
-- mpv's scripts/ folder), which silently disabled every save in earlier versions. Fall back to
-- <mpv config dir>/script-opts/, which exists for anyone who has a .conf file.
local function data_dir()
    if MS.ddir then return MS.ddir end           -- looked up once (each lookup is a round trip to mpv)
    local d = mp.get_script_directory()
    if d and d ~= "" then MS.ddir = d; return d end
    local ok, r = pcall(mp.command_native, { "expand-path", "~~/script-opts" })
    if ok and type(r) == "string" and r ~= "" then MS.ddir = r; return r end
    if mp.find_config_file then
        local ok2, r2 = pcall(mp.find_config_file, "script-opts")
        if ok2 and type(r2) == "string" and r2 ~= "" then return r2 end
    end
    return nil
end

local function history_file_path()
    local dir = data_dir()
    if not dir then return nil end
    return utils.join_path(dir, "webdav_browser_data.json")
end

-- Writes via a temp file so a crash mid-write can't corrupt the data. Windows' rename() refuses
-- to overwrite an existing file, so the old file is moved aside to .bak first (and load falls
-- back to .bak if the main file ever fails to parse).
local function atomic_write(path, content)
    local tmp, bak = path .. ".tmp", path .. ".bak"
    local f, err = io.open(tmp, "wb")
    if not f then return false, tostring(err) end
    local okw, werr = f:write(content)
    f:close()
    if not okw then os.remove(tmp); return false, tostring(werr) end
    os.remove(bak)
    local had_old = os.rename(path, bak)
    if not os.rename(tmp, path) then
        if had_old then os.rename(bak, path) end
        local f2 = io.open(path, "wb")
        if not f2 then return false, "could not replace " .. path end
        f2:write(content); f2:close(); os.remove(tmp)
    end
    return true
end

local function try_load_json(path)
    local f = io.open(path, "rb")
    if not f then return nil end
    local content = f:read("*a")
    f:close()
    if not content or content == "" then return nil end
    local ok, data = pcall(utils.parse_json, content)
    if ok and type(data) == "table" then return data end
    return nil
end

-- ROOT CAUSE of "history is gone after a restart": mpv's JSON parser returns "[]" as an ARRAY-flagged table, and
-- format_json then writes an array-flagged table as [] no matter what string keys were added afterwards. The very
-- first save wrote "history": [] (empty table), every later session loaded that flagged table, and all history
-- written into it vanished again at the next save. Maps read from disk are therefore always copied into plain tables.
function U.plain(t)
    local r = {}
    if type(t) == "table" then for k, v in pairs(t) do r[k] = v end end
    return r
end

-- Invalid UTF-8 (odd file names on a server) makes utils.format_json fail, which used to silently lose the
-- whole save. This replaces every byte that is not part of a valid UTF-8 sequence with "?".
function U.clean_utf8(s)
    if not s:find("[\128-\255]") then return s end
    local out, i, n = {}, 1, #s
    while i <= n do
        local b = s:byte(i)
        local len = (b < 128 and 1) or (b >= 194 and b <= 223 and 2) or (b >= 224 and b <= 239 and 3) or (b >= 240 and b <= 244 and 4) or 0
        local ok = len > 0 and i + len - 1 <= n
        if ok then
            for k = 1, len - 1 do
                local c = s:byte(i + k)
                if c < 128 or c > 191 then ok = false break end
            end
        end
        if ok then out[#out + 1] = s:sub(i, i + len - 1); i = i + len
        else out[#out + 1] = "?"; i = i + 1 end
    end
    return table.concat(out)
end

function U.clean_tree(v, depth)
    depth = depth or 0
    if depth > 12 then return nil end
    if type(v) == "string" then return U.clean_utf8(v) end
    if type(v) ~= "table" then return v end
    local t = {}
    for k, x in pairs(v) do
        t[type(k) == "string" and U.clean_utf8(k) or k] = U.clean_tree(x, depth + 1)
    end
    return t
end

local function safe_json(payload)
    local ok, json = pcall(utils.format_json, payload)
    if ok and type(json) == "string" then return json end
    ok, json = pcall(utils.format_json, U.clean_tree(payload))
    if ok and type(json) == "string" then return json end
    return nil
end

-- ---------- journaled JSON files ----------
-- Big caches (folder listings, TMDB matches, season data) used to be rewritten as a whole after every change, which
-- with a large library is a noticeable hitch. Now a change appends one line {"k": key, "v": value} to "<file>.log"
-- (no "v" = deleted); the full file is only rewritten ("compacted") when the log gets long, or at load time.
-- Changes are found by comparing a cheap per-entry signature (table identity + a touch counter), not the content.
function U.jl_apply(path, map)
    local f = io.open(path .. ".log", "rb")
    if not f then return 0 end
    local n = 0
    for line in f:lines() do
        local ok, rec = pcall(utils.parse_json, line)
        if ok and type(rec) == "table" and rec.k ~= nil then
            map[rec.k] = rec.v
            n = n + 1
        end
    end
    f:close()
    return n
end
function U.jl_sig(v)
    if type(v) ~= "table" then return tostring(v) end
    return tostring(v) .. "|" .. tostring(v._t or 0)
end
-- state = { sig = {}, lines = 0 }; returns true when only the log was written
function U.jl_sync(state, path, map)
    state.sig = state.sig or {}
    local out = {}
    for k, v in pairs(map) do
        local s = U.jl_sig(v)
        if state.sig[k] ~= s then
            local line = safe_json({ k = k, v = v })
            if line then out[#out + 1] = line end
            state.sig[k] = s
        end
    end
    for k in pairs(state.sig) do
        if map[k] == nil then
            out[#out + 1] = safe_json({ k = k })
            state.sig[k] = nil
        end
    end
    if #out == 0 then return true end
    local f = io.open(path .. ".log", "ab")
    if not f then return false end
    f:write(table.concat(out, "\n") .. "\n")
    f:close()
    state.lines = (state.lines or 0) + #out
    return true
end
U.JL_MAX, U.JL_FOLD = 4000, 300
-- at quit / idle: a log of a few hundred lines, or half the size of its file, is folded into the file (loading is
-- faster next time)
function U.jl_fold(state, path, payload, map)
    if type(state) ~= "table" or not path or (state.lines or 0) == 0 then return end
    local big = (state.lines or 0) >= U.JL_FOLD
    if not big then
        local li, fi = utils.file_info(path .. ".log"), utils.file_info(path)
        big = li ~= nil and (not fi or li.size > fi.size / 2)
    end
    if big then pcall(U.jl_compact, state, path, payload, map) end
end
-- rewrites the full file and drops the log
function U.jl_compact(state, path, payload, map)
    local txt = safe_json(payload)
    if not txt or not atomic_write(path, txt) then return false end
    pcall(os.remove, path .. ".log")
    state.sig, state.lines = {}, 0
    for k, v in pairs(map) do state.sig[k] = U.jl_sig(v) end
    return true
end

-- The big, re-creatable cache (folder listings) lives in the cache folder next to the posters, NOT in the
-- history file: a problem with it can never cost you your watch history, and "clear cache" never touches history.
local function dircache_path()
    local ok, d = pcall(function() return PS.dir() end)
    if ok and d then return d .. "/dirs.json" end
    return nil
end

local function load_persistence()
    local path = history_file_path()
    persist_status.path = path
    if not path then
        persist_status.ok, persist_status.err = false, "no writable data directory (needs mpv 'expand-path')"
        msg.warn("webdav-browser: persistence disabled - no data directory available")
        return
    end
    local data = try_load_json(path) or try_load_json(path .. ".bak")
    if data then
        watch_history = U.plain(data.history)
        watched_set   = U.plain(data.watched)
        sort_by_dir   = U.plain(data.sort)
        index_meta    = U.plain(data.index)
        MS.hints      = U.plain(data.hints)
        MS.tracks     = U.plain(data.tracks)
        MS.tracked    = U.plain(data.tracked)    -- the poster edition's tracked shows (kept by both editions)
        MS.rev        = tonumber(data.rev) or 0
        MS.disk_mark(path)
    end
    if o.persist_dir_cache then
        -- the folder cache (it can be a few MB) is read just after mpv has finished loading the scripts, not while
        -- mpv waits for them - or on first use, should anything ask for it sooner (an event queued at startup)
        MS.dirs_old = data and type(data.dir_cache) == "table" and data.dir_cache or nil   -- older versions kept it in the history file
        MS.dirs_pending = true
        mp.add_timeout(0, function() MS.load_dirs() end)
    end
    persist_status.ok = true
end
function MS.load_dirs()
    if not MS.dirs_pending then return end
    MS.dirs_pending = nil
    local old = MS.dirs_old
    MS.dirs_old = nil
    if MS.dcj then return end
    local cp = dircache_path()
    local c = cp and try_load_json(cp)
    if type(c) == "table" and type(c.dir_cache) == "table" then dir_cache = U.plain(c.dir_cache)
    elseif old then dir_cache = U.plain(old) end
    MS.dcj = { sig = {}, lines = 0 }
    if cp then MS.dcj.lines = U.jl_apply(cp, dir_cache) end
    for k, v in pairs(dir_cache) do MS.dcj.sig[k] = U.jl_sig(v) end
    MS.cache_version = MS.cache_version + 1
end

-- History file: small, written often, only ever by the instance that owns playback (MS.active).
save_persistence = function(force)
    if MS.active == false and not force then return end
    local path = persist_status.path or history_file_path()
    if not path then return end
    MS.rev = (MS.rev or 0) + 1
    local json = safe_json({ v = 3, rev = MS.rev, history = watch_history, watched = watched_set, sort = sort_by_dir,
        index = index_meta, hints = MS.hints, tracks = MS.tracks, tracked = MS.tracked })
    if not json then
        persist_status.ok, persist_status.err = false, "format_json failed"
        return
    end
    local wok, werr = atomic_write(path, json)
    persist_status.path = path
    persist_status.ok = wok
    persist_status.err = wok and nil or werr
    if wok then
        persist_status.last_save, persist_status.bytes = os.time(), #json
        MS.prog_dirty = false
        MS.disk_mark(path)
    else msg.warn("webdav-browser: could not save data: " .. tostring(werr)) end
end
-- what the history file looked like when this script last read or wrote it: unchanged on disk = nothing to re-read
function MS.disk_mark(path)
    local i = path and utils.file_info(path)
    MS.disk_sig = i and (tostring(i.size) .. "|" .. tostring(i.mtime)) or nil
end
function MS.disk_same(path)
    local i = path and utils.file_info(path)
    return i ~= nil and MS.disk_sig ~= nil and MS.disk_sig == (tostring(i.size) .. "|" .. tostring(i.mtime))
end

-- the long logs folded into their files: at quit, and while mpv sits idle with the browser closed
function MS.fold_journals()
    if o.persist_dir_cache and MS.dcj and MS.active ~= false then U.jl_fold(MS.dcj, dircache_path(), { v = 1, dir_cache = dir_cache }, dir_cache) end
    if PS.idx and PS.idxj then U.jl_fold(PS.idxj, PS.dir() .. "/index.json", PS.idx, PS.idx) end
    if PS.eps and PS.epsj then U.jl_fold(PS.epsj, PS.dir() .. "/episodes.json", PS.eps, PS.eps) end
end
mp.add_periodic_timer(60, function()
    if not browser_active and MS.P["idle-active"] then MS.fold_journals() end
end)
local function save_dircache()
    if not o.persist_dir_cache or MS.active == false then return end
    local cp = dircache_path()
    if not cp then return end
    if MS.dirs_pending then return end          -- not read yet: nothing of it may be written over
    MS.dcj = MS.dcj or { sig = {}, lines = 1e9 }
    -- changed listings are appended to the log; the file itself is rewritten when mpv quits or sits idle (U.jl_fold),
    -- or straight away only when the log has grown very long
    local ok
    if MS.dcj.lines < U.JL_MAX and utils.file_info(cp) then ok = U.jl_sync(MS.dcj, cp, dir_cache) end
    if not ok then
        ok = U.jl_compact(MS.dcj, cp, { v = 1, dir_cache = dir_cache }, dir_cache)
        if not ok then
            PS.mkdir()          -- the cache folder may not exist yet
            ok = U.jl_compact(MS.dcj, cp, { v = 1, dir_cache = dir_cache }, dir_cache)
        end
    end
    if ok then MS.cache_dirty = false end
end

-- Directory-cache writes are batched: the first dirty change schedules ONE flush; further changes
-- inside that window ride along. Watch-history saves (end-file) stay immediate.
local persist_debounce_timer = nil
-- what = "cache" (a folder listing changed) only rewrites dirs.json; anything else also saves the history file.
local function debounced_save_persistence(delay, what)
    if what ~= "cache" then MS.hist_dirty = true end
    MS.cache_dirty = MS.cache_dirty or (what == "cache")
    if persist_debounce_timer then return end
    persist_debounce_timer = mp.add_timeout(delay or 3, function()
        persist_debounce_timer = nil
        if MS.hist_dirty then MS.hist_dirty = false; save_persistence() end
        if MS.cache_dirty then save_dircache() end
    end)
end

-- A cached listing is "fresh" for cache_ttl seconds (<=0 = forever). Stale listings are still shown
-- instantly and, with revalidate_stale, silently re-fetched in the background.
cache_is_fresh = function(entry)
    if not entry then return false end
    if entry.stale then return false end
    if o.cache_ttl <= 0 then return true end
    return (os.time() - (entry.ts or 0)) < o.cache_ttl
end

-- ============================================================
-- WEBDAV
-- ============================================================
-- Request statistics, shown in the debug overlay ('d').
local req_stats = { last = nil, pending = 0, total = 0, failures = 0 }

function U.curl_quote(s)
    s = s:gsub("\\", "\\\\"):gsub('"', '\\"'):gsub("\n", "\\n"):gsub("\r", "\\r")
    return '"' .. s .. '"'
end

-- mpv documents subprocess stdin_data as unreliable on Windows, so "auto" passes -u there and
-- uses curl's config-on-stdin (-K -) elsewhere (keeps the password out of the process list).
function U.auth_mode()
    local m = tostring(o.curl_auth_mode or "auto"):lower()
    if m ~= "arg" and m ~= "stdin" then
        m = (package.config:sub(1, 1) == "\\") and "arg" or "stdin"
    end
    return m
end

-- The WebDAV login for curl: written once to webdav_browser_curl.cfg (next to the data file) and passed with -K,
-- so it never shows in mpv's log (which records every command with its arguments and stdin). Adds to args, returns
-- the stdin text for the old ways when the file can't be written.
function U.curl_auth(args)
    if o.user == "" and o.pass == "" then return nil end
    local body = "user = " .. U.curl_quote(o.user .. ":" .. o.pass) .. "\n"
    local dir = data_dir()
    local p = dir and utils.join_path(dir, "webdav_browser_curl.cfg")
    if p and (U.auth_body ~= body or not utils.file_info(p)) then
        local f = io.open(p, "wb")
        if f then f:write(body); f:close(); U.auth_body = body else p = nil end
    end
    if p then args[#args + 1] = "-K"; args[#args + 1] = p; return nil end
    if U.auth_mode() == "arg" then args[#args + 1] = "-u"; args[#args + 1] = o.user .. ":" .. o.pass; return nil end
    args[#args + 1] = "-K"; args[#args + 1] = "-"
    return body
end

-- Runs curl asynchronously. The HTTP status code is appended to
-- the output via -w and split off again here.
-- callback(stdout_or_nil, err_or_nil, info{ms, exit, code})
local function run_curl_async(args, callback)
    local full_args = {
        o.curl_path, "-s", "-S",
        "--max-time", tostring(o.request_timeout),
        "--connect-timeout", tostring(math.min(10, o.request_timeout)),
        "-w", "\\n%{http_code}",
    }
    local stdin_data = U.curl_auth(full_args)
    for _, a in ipairs(args) do table.insert(full_args, a) end

    local t0 = U.now_s()
    req_stats.pending = req_stats.pending + 1
    req_stats.total = req_stats.total + 1
    return mp.command_native_async({
        name = "subprocess", args = full_args, stdin_data = stdin_data,
        capture_stdout = true, capture_stderr = true, playback_only = false,
    }, function(success, result, err_msg)
        req_stats.pending = math.max(0, req_stats.pending - 1)
        local info = { ms = math.floor((U.now_s() - t0) * 1000 + 0.5) }
        if not success or not result then
            callback(nil, err_msg or "failed to launch curl", info); return
        end
        info.exit = result.status
        local out = result.stdout or ""
        local body, code = out:match("^(.*)\n(%d%d%d)$")
        if code then info.code = tonumber(code); out = body end
        if result.status ~= 0 then
            local e = (result.stderr and result.stderr ~= "" and result.stderr)
                or ("curl exited with status " .. tostring(result.status))
            callback(nil, e, info); return
        end
        callback(out, nil, info)
    end)
end

local function sort_mode_for(href)
    return sort_by_dir[href] or ((o.default_sort == "recent") and "recent" or "name")
end

-- Folders first, then the directory's own sort mode (name = natural order, so ep2 < ep10).
local function sort_entries(list, mode)
    table.sort(list, function(a, b)
        if a.is_dir ~= b.is_dir then return a.is_dir end
        if mode == "recent" then
            local am, bm = a.mtime, b.mtime
            if am and bm and am ~= bm then return am > bm end
            if am and not bm then return true end
            if bm and not am then return false end
        end
        return U.natural_less(a.name, b.name)
    end)
end

-- an href without the WebDAV address's own path (compared segment by segment, %-decoded)
function U.dav_rel(p)
    local base = tostring(o.url or ""):match("^https?://[^/]+(/.-)/*$")
    if not base or base == "" or base == "/" then return p end
    local pos = 1
    for seg in base:gmatch("[^/]+") do
        local s1, e1 = p:find("[^/]+", pos)
        if not s1 or U.percent_decode(p:sub(s1, e1)) ~= U.percent_decode(seg) then return p end
        pos = e1 + 1
    end
    local rest = p:sub(pos)
    return (rest == "") and "/" or rest
end
local function parse_propfind(xml, request_path)
    local results, seen = {}, {}
    if not xml then return results end
    for block in xml:gmatch("<[^>]-:?response[^>]*>(.-)</[^>]-:?response>") do
        local href = block:match("<[^>]-:?href[^>]*>(.-)</[^>]-:?href>")
        if href then
            href = U.xml_unescape(href)
            local path_only = U.dav_rel(href:gsub("^https?://[^/]+", ""))
            local is_collection = block:match("<[^>/]-:?collection[%s/>]") ~= nil
            local norm_req  = request_path:gsub("/+$", "")
            local norm_href = path_only:gsub("/+$", "")
            if norm_href ~= norm_req then
                local size = block:match("<[^>]-:?getcontentlength[^>]*>(%d+)</[^>]-:?getcontentlength>")
                local mtime_str = block:match("<[^>]-:?getlastmodified[^>]*>(.-)</[^>]-:?getlastmodified>")
                local name = U.basename(path_only)
                local key = (is_collection and "D:" or "F:") .. name:lower() .. "|" .. tostring(size or "")
                if not seen[key] then
                    seen[key] = true
                    table.insert(results, {
                        name = name, href = path_only, is_dir = is_collection,
                        size = tonumber(size),
                        mtime = U.parse_http_date(mtime_str and U.xml_unescape(mtime_str) or nil),
                    })
                end
            end
        end
    end
    return results
end

-- Fetches one folder listing. Timeouts, HTTP 429 and 5xx are retried (attempt N waits N x
-- request_retry_delay). callback(entries_or_nil, err_or_nil, info{ms, code, exit, attempts})
function MS.fetch_dir_now(path, callback)
    if o.url == "" then callback(nil, "WebDAV URL not configured", {}); return end
    local attempt = 0
    local function try()
        attempt = attempt + 1
        local args = { "-X", "PROPFIND", "-H", "Depth: 1", "-H", "Content-Type: application/xml", o.url .. path }
        run_curl_async(args, function(stdout, err, info)
            info.attempts = attempt
            local problem, retriable = nil, false
            if err then
                local ex = info.exit
                if ex == 28 then
                    problem, retriable = "Timed out after " .. o.request_timeout .. "s (raise request_timeout)", true
                elseif ex == 6 or ex == 7 then
                    problem, retriable = "Can't reach the server", true
                elseif ex == 35 or ex == 58 or ex == 60 then
                    problem = "TLS / certificate problem"
                else
                    problem = "Request failed: " .. (tostring(err):gsub("%s+$", ""))
                end
            else
                local code = info.code
                if code == 401 then problem = "Unauthorized (check user/pass)"
                elseif code == 403 then problem = "Forbidden (HTTP 403)"
                elseif code == 404 then problem = "Not found (HTTP 404) - folder may have been removed"
                elseif code == 429 then problem, retriable = "Rate limited (HTTP 429)", true
                elseif code and code >= 500 then problem, retriable = "Server error (HTTP " .. code .. ")", true
                elseif not stdout or stdout == "" then problem = "Empty response"
                elseif not stdout:match("^%s*<%?xml") and not stdout:match("<[^>]-multistatus") then
                    problem = "Invalid response from server" .. (code and (" (HTTP " .. code .. ")") or "")
                end
            end
            if problem and retriable and attempt <= o.request_retries then
                mp.add_timeout(o.request_retry_delay * attempt, try)
                return
            end
            req_stats.last = { path = path, ms = info.ms, code = info.code, exit = info.exit,
                               attempts = attempt, ts = os.time(), err = problem }
            if problem then
                req_stats.failures = req_stats.failures + 1
                callback(nil, problem, info)
            else
                local okp, entries = pcall(parse_propfind, stdout, path)
                if okp then callback(entries, nil, info) else callback(nil, "Unreadable answer from the server", info) end
            end
        end)
    end
    try()
end

-- Several listings waiting at once (a title page's season folders, the re-check of folders still filling) go out in
-- ONE curl process: one connection, the transfers side by side, each with its own answer (a process and a TLS handshake
-- per folder cost a few hundred ms each on Windows). Anything but a clean answer is asked again on its own, with the
-- usual retries and error messages (MS.fetch_dir_now); so is everything when curl is older than 7.75.
function MS.fetch_dirs(group, done)
    local dir = data_dir()
    MS.dav_n = (MS.dav_n or 0) + 1
    local base = dir and utils.join_path(dir, "webdav_browser_dav" .. (MS.dav_n % 16))
    local lines = {}
    local auth = (o.user ~= "" or o.pass ~= "") and ("user = " .. U.curl_quote(o.user .. ":" .. o.pass)) or nil
    for i, g in ipairs(group) do
        g.out = base and (base .. "_" .. i .. ".xml")
        if i > 1 then lines[#lines + 1] = "next" end
        lines[#lines + 1] = "url = " .. U.curl_quote(o.url .. g.path)
        lines[#lines + 1] = 'request = "PROPFIND"'
        lines[#lines + 1] = 'header = "Depth: 1"'
        lines[#lines + 1] = 'header = "Content-Type: application/xml"'
        lines[#lines + 1] = "output = " .. U.curl_quote(tostring(g.out))
        lines[#lines + 1] = "max-time = " .. tostring(o.request_timeout)
        lines[#lines + 1] = "connect-timeout = " .. tostring(math.min(10, o.request_timeout))
        lines[#lines + 1] = 'write-out = "%{http_code} %{exitcode} %{filename_effective}\\n"'
        lines[#lines + 1] = "silent"
        lines[#lines + 1] = "show-error"
        if auth then lines[#lines + 1] = auth end          -- per transfer: "next" starts each one afresh
    end
    local cfg = base and (base .. ".cfg")
    local f = cfg and io.open(cfg, "wb")
    local function singly()
        for k = #group, 1, -1 do group[k].single = true; table.insert(MS.dav_q, 1, group[k]) end
        done()
    end
    if not f then return singly() end
    f:write(table.concat(lines, "\n") .. "\n"); f:close()
    local t0 = U.now_s()
    req_stats.pending = req_stats.pending + #group
    req_stats.total = req_stats.total + #group
    mp.command_native_async({ name = "subprocess", args = { o.curl_path, "--parallel", "--parallel-max", "3", "-K", cfg },
        capture_stdout = true, capture_stderr = true, playback_only = false }, function(_, result)
        pcall(os.remove, cfg)                  -- it holds the login
        req_stats.pending = math.max(0, req_stats.pending - #group)
        local res = {}
        for code, ex, fname in tostring(result and result.stdout or ""):gmatch("(%d%d%d) (%d+) ([^\r\n]*)") do
            res[(fname:gsub("\\", "/"))] = { code = tonumber(code), exit = tonumber(ex) }
        end
        local ms = math.floor((U.now_s() - t0) * 1000 + 0.5)
        local again = {}
        local answers = {}
        for _, g in ipairs(group) do
            local r = res[(tostring(g.out):gsub("\\", "/"))]
            local body
            local fh = io.open(g.out, "rb")
            if fh then body = fh:read("*a"); fh:close() end
            pcall(os.remove, g.out)
            local okp, entries = false, nil
            if r and r.exit == 0 and r.code and r.code < 300 and body and (body:match("^%s*<%?xml") or body:match("<[^>]-multistatus")) then
                okp, entries = pcall(parse_propfind, body, g.path)
            end
            if okp then
                req_stats.last = { path = g.path, ms = ms, code = r.code, exit = 0, attempts = 1, ts = os.time() }
                answers[#answers + 1] = { g = g, entries = entries, info = { ms = ms, code = r.code, exit = 0, attempts = 1 } }
            else
                g.single = true
                again[#again + 1] = g
            end
        end
        for k = #again, 1, -1 do table.insert(MS.dav_q, 1, again[k]) end
        done()
        for _, a in ipairs(answers) do
            local okc, err = pcall(a.g.cb, a.entries, nil, a.info)
            if not okc then msg.error("folder listing: " .. tostring(err)) end
        end
    end)
end

-- At most 3 folder requests run at once; the rest wait their turn (the title page of a show with many season
-- folders used to fire them all together, and the server refused part of the burst). Listings you are looking at
-- (urgent) go to the front of the line.
MS.dav_q, MS.dav_running = {}, 0
function MS.dav_pump()
    -- a listing you are waiting for may also start beside a running background batch (one at a time)
    while #MS.dav_q > 0 and (MS.dav_running < 3 or (MS.dav_q[1].urgent and not MS.dav_boost)) do
        if MS.dav_running >= 3 then
            local g = table.remove(MS.dav_q, 1)
            MS.dav_boost = true
            MS.fetch_dir_now(g.path, function(a, b, c) MS.dav_boost = nil; MS.dav_pump(); g.cb(a, b, c) end)
            return
        end
        local can = PS and PS.H and PS.H.par and (PS.H.cv or 0) >= 775
        local group = { table.remove(MS.dav_q, 1) }
        -- a batch runs 3 transfers side by side, so it takes all 3 places (the server sees no more than before); it
        -- only holds listings of one kind (what you opened, or background re-checks): its answers come back together
        if can and not group[1].single and MS.dav_running == 0 then
            local i = 1
            while i <= #MS.dav_q and #group < 6 do
                local x = MS.dav_q[i]
                if x.single or (x.urgent or false) ~= (group[1].urgent or false) then i = i + 1 else group[#group + 1] = table.remove(MS.dav_q, i) end
            end
        end
        local wgt = (#group > 1) and 3 or 1
        MS.dav_running = MS.dav_running + wgt
        local function done() MS.dav_running = MS.dav_running - wgt; MS.dav_pump() end
        if #group == 1 then
            local g = group[1]
            MS.fetch_dir_now(g.path, function(a, b, c) done(); g.cb(a, b, c) end)
        else
            MS.fetch_dirs(group, done)
        end
    end
end
local function fetch_dir_async(path, callback, urgent)
    if PS and PS.http_probe then PS.http_probe() end          -- learns curl's version (for the batches)
    local item = { path = path, cb = callback, urgent = urgent and true or nil }
    if urgent then
        local at = #MS.dav_q + 1
        for i, x in ipairs(MS.dav_q) do if not x.urgent then at = i; break end end
        table.insert(MS.dav_q, at, item)
    else MS.dav_q[#MS.dav_q + 1] = item end
    -- requests made together are gathered for a moment, then sent
    if not MS.dav_t then MS.dav_t = mp.add_timeout(0.02, function() MS.dav_t = nil; MS.dav_pump() end) end
end

-- ============================================================
-- TREE HELPERS
-- ============================================================
function U.with_slash(href) return (href:gsub("/+$", "")) .. "/" end

-- cached listing for a directory, tolerant of a missing/extra trailing slash
local function find_cached_dir(href)
    if MS.dirs_pending then MS.load_dirs() end
    return dir_cache[href] or dir_cache[U.with_slash(href)] or dir_cache[(href:gsub("/+$", ""))]
end

get_or_create_node = function(href, name, depth, parent_href)
    local existing = tree[href]
    if existing then return existing end
    local node = {
        href = href, name = name, depth = depth, parent_href = parent_href,
        expanded = false, loaded = false, loading = false, children = {},
    }
    tree[href] = node
    return node
end

local function prune_tree(href)
    local node = tree[href]
    if node then
        for _, c in ipairs(node.children) do prune_tree(c) end
        tree[href] = nil
    end
end

local function drop_cached_prefix(href)
    local prefix = U.with_slash(href)
    for k in pairs(dir_cache) do
        if k:sub(1, #prefix) == prefix then dir_cache[k] = nil end
    end
end

-- the same entries (names, sizes, dates), in any order
function U.same_listing(a, b)
    if #a ~= #b then return false end
    local by = {}
    for _, e in ipairs(a) do by[e.href] = e end
    for _, e in ipairs(b) do
        local x = by[e.href]
        if not x or x.name ~= e.name or x.is_dir ~= e.is_dir or x.size ~= e.size or x.mtime ~= e.mtime then return false end
    end
    return true
end
-- Continue Watching only looks inside folders that hold a file you watched or left part-way
function U.cw_touches(list)
    if type(list) ~= "table" then return false end
    for _, e in ipairs(list) do
        if not e.is_dir and (watched_set[e.href] or watch_history[e.href]) then return true end
    end
    return false
end

-- Stores a freshly fetched listing. Sub-folders that existed in the previous listing but are gone
-- now are pruned (tree nodes AND their cached listings), so deleted folders no longer linger in the
-- tree, in folder search, or in the library index.
-- Returns the entries to use (the stored table when nothing changed) and whether anything changed.
local function store_listing(href, entries)
    local old = dir_cache[href]
    local same = old and type(old.entries) == "table" and U.same_listing(old.entries, entries)
    if same then
        -- the same listing again (a re-check, a revalidation): the stored table is kept, so nothing keyed on it
        -- (the page, Continue Watching, the journal, the search index) sees a change - only its age is renewed
        entries = old.entries
        if os.time() - (old.ts or 0) > 300 or old.stale then old._t = (old._t or 0) + 1 end
        old.ts, old.stale = os.time(), nil
    else
        if old and type(old.entries) == "table" then
            local still = {}
            for _, e in ipairs(entries) do if e.is_dir then still[e.href] = true end end
            for _, e in ipairs(old.entries) do
                if e.is_dir and not still[e.href] then
                    prune_tree(e.href)
                    drop_cached_prefix(e.href)
                    dir_cache[e.href] = nil
                    mark_continue_dirty()          -- Continue Watching may have used a listing that went with it
                end
            end
        end
        dir_cache[href] = { entries = entries, ts = os.time() }
        MS.cache_version = MS.cache_version + 1
        if U.cw_touches(old and old.entries) or U.cw_touches(entries) then mark_continue_dirty() end
    end
    -- Real-Debrid fills a big torrent folder gradually (it prepares the links one by one): a listing that grew since
    -- the last look is "still filling" - it is re-checked every few seconds while you look at it and never counts
    -- as fresh in the cache until two checks in a row return the same number of entries.
    local oldn = old and type(old.entries) == "table" and #old.entries or nil
    MS.seen[href] = (MS.seen[href] or 0) + 1
    local g = MS.grow[href]
    if oldn and #entries > oldn then
        MS.grow[href] = { n = #entries, stable = 0, t = os.time() }
        dir_cache[href].stale = true
        dir_cache[href]._t = (dir_cache[href]._t or 0) + 1
    elseif g then
        g.stable = g.stable + 1
        if g.stable >= 2 then MS.grow[href] = nil else dir_cache[href].stale = true; dir_cache[href]._t = (dir_cache[href]._t or 0) + 1 end
    end
    if href == current_path then
        if MS.grow[href] then status_line = string.format("Real-Debrid is still adding files to this folder…  %d so far", #entries)
        elseif g and status_line:find("still adding files", 1, true) then status_line = string.format("All %d entries listed", #entries) end
    end
    return entries, not same
end

apply_dir_result = function(href, entries)
    sort_entries(entries, sort_mode_for(href))

    local depth_of_href
    if href == root_href then
        depth_of_href = -1
    else
        depth_of_href = (tree[href] and tree[href].depth) or 0
    end

    local dirs, files = {}, {}
    for _, e in ipairs(entries) do
        if e.is_dir then table.insert(dirs, e) else table.insert(files, e) end
    end

    local ordered = {}
    for _, e in ipairs(dirs) do
        get_or_create_node(e.href, e.name, depth_of_href + 1, href)
        table.insert(ordered, e.href)
    end

    if href == root_href then
        root_children = ordered
    else
        local node = tree[href]
        if node then
            node.children = ordered
            node.loaded = true
        end
    end
    return files
end

-- Virtual "Continue Watching" row, always first in the Folders panel (when it has anything to show).
local CW_NODE = { href = CW_HREF, name = "Continue Watching", depth = 0, virtual = true,
                  expanded = false, loaded = true, loading = false, children = {} }

flatten_visible = function()
    local out = {}
    if o.continue_row and #get_continue_list() > 0 then table.insert(out, CW_NODE) end
    local function walk(hrefs)
        for _, href in ipairs(hrefs) do
            local node = tree[href]
            if node then
                table.insert(out, node)
                if node.expanded then walk(node.children) end
            end
        end
    end
    walk(root_children)
    return out
end

-- Folder-name search across the whole loaded tree (expanded or not); words match across . _ - separators.
collect_matching_folders = function(query)
    local toks = U.query_tokens(query)
    local out = {}
    for _, node in pairs(tree) do
        if U.match_score(node.name, toks) then table.insert(out, node) end
    end
    table.sort(out, function(a, b)
        if a.depth ~= b.depth then return a.depth < b.depth end
        return U.natural_less(a.name, b.name)
    end)
    return out
end

-- ============================================================
-- DIRECTORY LOADING
-- ============================================================
local function loading_delta(d)
    loading_count = math.max(0, loading_count + d)
    is_loading = loading_count > 0
end

-- The ONE place a folder listing is fetched, stored and applied.
--   opts.silent  : no spinner / status text (background revalidation, index crawl)
--   opts.status  : status line text while loading
-- Replies for a folder are only applied if no NEWER request for the same folder was issued, and the
-- Files panel is only touched if that folder is still the open one (so a slow reply for folder A
-- can never overwrite the file list of folder B you opened afterwards).
-- on_done(ok, err) is always called exactly once.
fetch_listing = function(href, opts, on_done)
    opts = opts or {}
    -- A background (silent) request for a folder that is already being fetched just waits for that
    -- request instead of replacing it (otherwise the index crawl or a revalidation could cancel
    -- the listing you are actually waiting for).
    if opts.silent and MS.inflight[href] then
        if on_done then table.insert(MS.inflight[href], on_done) end
        return
    end
    local waiters = {}
    MS.inflight[href] = waiters
    local function finish(ok, err)
        if MS.inflight[href] == waiters then MS.inflight[href] = nil end
        if on_done then on_done(ok, err) end
        for _, w in ipairs(waiters) do w(ok, err) end
    end

    req_seq[href] = (req_seq[href] or 0) + 1
    local seq = req_seq[href]
    local node = tree[href]
    if not opts.silent then
        loading_delta(1)
        if node then node.loading = true end
        if opts.status then status_line = opts.status end
        render()
    end

    fetch_dir_async(href, function(entries, err)
        if MS.on_listing then MS.on_listing(href, err) end
        if not opts.silent then
            loading_delta(-1)
            local n = tree[href]
            if n then n.loading = false end
        end
        if seq ~= req_seq[href] then          -- superseded by a newer request for this folder
            if not opts.silent then render() end
            finish(false, "superseded")
            return
        end
        if err then
            listing_error[href] = err
            if not opts.silent or href == current_path then
                status_line = "Couldn't load this folder: " .. err .. "  ·  " .. U.kname("refresh") .. " to retry" .. "  ·  " .. U.kname("doctor") .. " setup check"
            end
            render()
            finish(false, err)
            return
        end
        local had_err = listing_error[href] ~= nil
        listing_error[href] = nil
        local st0, changed = status_line, nil
        entries, changed = store_listing(href, entries)
        changed = changed or had_err             -- an error that cleared: the page must lose its "couldn't load"
        if had_err and href == current_path and tostring(status_line):find("^Couldn't load") then status_line = "Ready" end
        -- Only build tree nodes for folders that are part of the tree already (or the root). The
        -- background index also fetches deep folders whose ancestors aren't loaded; creating nodes
        -- for those would leave orphans with wrong depths.
        local files
        if href == root_href or tree[href] then
            files = apply_dir_result(href, entries)
        end
        if current_path == href then
            if not files then
                sort_entries(entries, sort_mode_for(href))
                files = {}
                for _, e in ipairs(entries) do if not e.is_dir then files[#files + 1] = e end end
            end
            file_entries = files
            after_files_set()
        end
        if not opts.silent and opts.status and not MS.grow[href] then status_line = "Loaded: " .. (U.basename(href) ~= "" and U.basename(href) or "root") end
        -- a background listing that changed nothing draws nothing; one that did is drawn with the next frame
        -- (several replies in a row are one redraw), not on the spot
        if not opts.silent then render()
        elseif changed or status_line ~= st0 then (MS.redraw_soon or render)() end
        -- during a library crawl write less often (every ~30 s): the data file holds the whole index
        debounced_save_persistence(opts.silent and (MS.idx_running and 30 or 8) or 3, "cache")
        finish(true)
    end, opts.urgent or not opts.silent)
end

after_files_set = function()
    if pending_select_href then
        local items = get_panel_items("episodes")
        for i, e in ipairs(items) do
            if e.href == pending_select_href then
                selected_episode = i
                free_scroll.episodes = false
                break
            end
        end
        pending_select_href = nil
    end
    local n = #get_panel_items("episodes")
    if selected_episode > n then selected_episode = math.max(1, n) end
end

-- Show a cached listing instantly (even a stale one, when revalidate_stale is on) and refresh stale
-- ones silently; otherwise fetch with a visible spinner.
local function show_dir(href, status_text)
    local cached = dir_cache[href]
    if cached and (cache_is_fresh(cached) or o.revalidate_stale) then
        listing_error[href] = nil
        file_entries = apply_dir_result(href, cached.entries)
        after_files_set()
        render()
        if not cache_is_fresh(cached) then fetch_listing(href, { silent = true }) end
        return
    end
    file_entries = {}
    fetch_listing(href, { status = status_text })
end

load_root = function()
    current_path = root_href
    if search_scope ~= "sidebar" then
        search_query = ""
        search_scope = nil
    end
    show_dir(root_href, "Loading library")
end

open_folder_node = function(node)
    if node.virtual then open_continue_view(); return end
    if node.loading then return end
    node.expanded = true
    if current_path ~= node.href then
        selected_episode, scroll_offset_episodes = 1, 0
        free_scroll.episodes = false
    end
    current_path = node.href
    status_line = "Opening: " .. node.name

    if search_scope ~= "sidebar" then
        search_query = ""
        search_scope = nil
    end
    if o.auto_focus_files_on_open then set_focus("episodes") end
    show_dir(node.href, "Opening: " .. node.name)
end

-- Refreshes a list of folders one after another (gentle on the server) with a progress readout.
local function refresh_many(hrefs, label, on_done)
    local idx, total = 0, #hrefs
    local failed = 0
    local function step(ok)
        if idx > 0 and ok == false then failed = failed + 1 end
        idx = idx + 1
        if idx > total then
            status_line = (failed > 0) and (string.format("Couldn't load %d folder%s  ·  %s to retry", failed, failed == 1 and "" or "s", U.kname("refresh")) .. "  ·  " .. U.kname("doctor") .. " setup check")
                or (label .. ": done")
            render()
            if on_done then on_done() end
            return
        end
        status_line = string.format("%s %d/%d", label, idx, total)
        render()
        fetch_listing(hrefs[idx], { silent = true }, step)
    end
    step(true)
end

-- Root + every expanded folder + the highlighted/open one: i.e. everything the Folders panel shows.
local function visible_tree_hrefs()
    local list, seen = { root_href }, { [root_href] = true }
    local function add(h)
        if h and not seen[h] and h ~= CW_HREF then seen[h] = true; table.insert(list, h) end
    end
    local nodes = {}
    for _, node in pairs(tree) do
        if node.expanded and node.loaded then table.insert(nodes, node) end
    end
    table.sort(nodes, function(a, b)
        if a.depth ~= b.depth then return a.depth < b.depth end
        return a.href < b.href
    end)
    for _, n in ipairs(nodes) do add(n.href) end
    local hl = get_panel_items("sidebar")[sidebar_selected_index]
    if hl and not hl.virtual and hl.loaded then add(hl.href) end
    add(current_path)
    return list
end

-- 'r'  : Folders panel -> refresh the whole visible folder tree
--        Files panel   -> refresh the open folder
-- 'R'  : everything (see refresh_all)
refresh_current = function()
    if current_path == CW_HREF and focus_panel == "episodes" then
        mark_continue_dirty()
        open_continue_view()
        return
    end
    if focus_panel == "sidebar" then
        refresh_many(visible_tree_hrefs(), "Refreshing folders")
    else
        local nm = U.basename(current_path)
        fetch_listing(current_path, { status = "Refreshing: " .. (nm ~= "" and nm or "root") })
    end
end

-- Refreshes the visible tree, then marks every other cached listing stale (so it revalidates the
-- next time it is opened) and kicks off a full re-index of the library.
refresh_all = function()
    local hrefs = visible_tree_hrefs()
    local done = {}
    for _, h in ipairs(hrefs) do done[h] = true end
    refresh_many(hrefs, "Refreshing all", function()
        for h, c in pairs(dir_cache) do
            if not done[h] then c.stale = true; c._t = (c._t or 0) + 1 end
        end
        if o.index_enabled and o.index_mode == "full" then index_start(true) end
        debounced_save_persistence()
    end)
end

-- ============================================================
-- PLAYBACK
-- ============================================================
U.b64_chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
function U.base64_encode(data)
    local out, len, i = {}, #data, 1
    while i <= len do
        local b1, b2, b3 = data:byte(i, i + 2)
        b2, b3 = b2 or 0, b3 or 0
        local n = b1 * 65536 + b2 * 256 + b3
        local c1 = math.floor(n / 262144) % 64
        local c2 = math.floor(n / 4096) % 64
        local c3 = math.floor(n / 64) % 64
        local c4 = n % 64
        local chunk = U.b64_chars:sub(c1+1,c1+1) .. U.b64_chars:sub(c2+1,c2+1)
        chunk = chunk .. ((i+1<=len) and U.b64_chars:sub(c3+1,c3+1) or "=")
        chunk = chunk .. ((i+2<=len) and U.b64_chars:sub(c4+1,c4+1) or "=")
        table.insert(out, chunk)
        i = i + 3
    end
    return table.concat(out)
end

local function file_stream_url(href)
    if o.embed_credentials_in_url and (o.user ~= "" or o.pass ~= "") then
        local scheme, rest = o.url:match("^(https?://)(.+)$")
        if scheme then
            return scheme .. U.url_encode_segment(o.user) .. ":" .. U.url_encode_segment(o.pass) .. "@" .. rest .. href
        end
    end
    return o.url .. href
end

local function auth_header_value()
    return "Authorization: Basic " .. U.base64_encode(o.user .. ":" .. o.pass)
end

local function is_our_url(u)
    return o.url ~= "" and type(u) == "string" and u:sub(1, #o.url) == o.url
end

-- Credentials are sent ONLY for files on your server: this hook runs before mpv opens each
-- file/URL and sets file-local options (they reset when that file ends), so playing any other
-- http(s) URL in the same mpv session never sees your Authorization header.
-- scoped_auth = false falls back to one session-wide header (see ensure_http_options).
mp.add_hook("on_load", 50, function()
    if not MS.active and not now_playing then return end   -- the other webdav-browser script owns playback right now
    if not o.scoped_auth or o.embed_credentials_in_url then return end
    if o.user == "" and o.pass == "" then return end
    local url = mp.get_property("stream-open-filename") or ""
    if is_our_url(url) then
        pcall(mp.set_property_native, "file-local-options/http-header-fields", { auth_header_value() })
        if o.user_agent ~= "" then pcall(mp.set_property, "file-local-options/user-agent", o.user_agent) end
    end
end)

-- Runs once per mpv session: demuxer cache sizing (+ the old session-wide auth header when
-- scoped_auth is off).
local function ensure_http_options()
    if auth_configured then return end
    auth_configured = true
    if not o.scoped_auth then
        if not o.embed_credentials_in_url and (o.user ~= "" or o.pass ~= "") then
            pcall(mp.set_property_native, "http-header-fields", { auth_header_value() })
        end
        if o.user_agent ~= "" then pcall(mp.set_property, "user-agent", o.user_agent) end
    end
    -- Bigger demuxer cache so slow/unstable WebDAV connections stutter less.
    pcall(mp.set_property, "cache", "yes")
    pcall(mp.set_property_number, "demuxer-readahead-secs", tonumber(o.demuxer_readahead_secs) or 300)
    pcall(mp.set_property, "demuxer-max-bytes", string.format("%dMiB", math.floor(tonumber(o.demuxer_max_bytes_mb) or 1024)))
    pcall(mp.set_property, "demuxer-max-back-bytes", string.format("%dMiB", math.floor(tonumber(o.demuxer_max_back_bytes_mb) or 256)))
end

-- Playlist entries get the FILE NAME as their title (instead of the long stream link) by loading
-- them through an in-memory m3u ("#EXTINF:-1,<name>"). mpv shows that title in the playlist and
-- as the media title. Falls back to a plain loadfile when loadlist refuses (very old mpv).
local function m3u_title(t)
    t = tostring(t or ""):gsub("[\r\n]+", " ")
    return t
end
local function queue_many(items, mode)
    ensure_http_options()
    if #items == 0 then return end
    local lines = { "#EXTM3U" }
    for _, it in ipairs(items) do
        if it.title and it.title ~= "" then lines[#lines + 1] = "#EXTINF:-1," .. m3u_title(it.title) end
        lines[#lines + 1] = it.url
    end
    local list = "memory://" .. table.concat(lines, "\n")
    local insert = mode:find("^insert%-next") ~= nil
    -- mpv < 0.38 has no insert-next for loadlist: append instead (keeps the titles). Known from mpv's version (asking
    -- it first left an error line in the log on every older mpv), else asked once and remembered
    if insert and MS.no_insert_next == nil then
        local a, b = tostring(mp.get_property("mpv-version") or ""):match("(%d+)%.(%d+)")
        if a and (tonumber(a) == 0 and tonumber(b) < 38) then MS.no_insert_next = true end
    end
    if not (insert and MS.no_insert_next) then
        if mp.commandv("loadlist", list, mode) then return end
        if insert then MS.no_insert_next = true end
    end
    if insert and mp.commandv("loadlist", list, mode == "insert-next-play" and "append-play" or "append") then return end
    -- fallback: plain loadfile (no titles)
    local first = true
    for _, it in ipairs(items) do
        local m = mode
        if not first then m = "append" end
        if not mp.commandv("loadfile", it.url, m) and m:find("^insert%-next") then
            mp.commandv("loadfile", it.url, m == "insert-next-play" and "append-play" or "append")
        end
        first = false
    end
end
local function queue_load(url, mode, title)
    queue_many({ { url = url, title = title } }, mode)
end

-- Queue `url` directly AFTER the current file (so it plays next even if you queued other things
-- with 'a'); older mpv without "insert-next" falls back to appending.
local function queue_next(url, title)
    queue_many({ { url = url, title = title } }, "insert-next")
end

-- ---------- Continue Watching (virtual list) ----------
local cw_cache, cw_dirty = nil, true
mark_continue_dirty = function() cw_dirty = true end
MS.cw_sorted = setmetatable({}, { __mode = "k" })     -- a folder's media files in name order, per listing table

-- Two kinds of rows: files you left part-way ("resume", newest first) and, per folder you have
-- been watching, the first not-yet-watched file after the last one you finished ("next").
get_continue_list = function()
    if not cw_dirty and cw_cache then return cw_cache end
    local resume, nxt = {}, {}

    for href, rec in pairs(watch_history) do
        if rec.pos and not watched_set[href] then
            table.insert(resume, {
                name = rec.name or U.basename(href), href = href, is_dir = false, cw = "resume",
                dirpath = rec.dirpath or U.dirname(href), ts = rec.last_played or 0, pos = rec.pos,
            })
        end
    end
    table.sort(resume, function(a, b) return a.ts > b.ts end)

    local dirs = {}
    for href, v in pairs(watched_set) do
        local d = U.dirname(href)
        local ts = (type(v) == "number") and v or 0
        if not dirs[d] or ts > dirs[d] then dirs[d] = ts end
    end
    for d, ts in pairs(dirs) do
        local cached = find_cached_dir(d)
        local hint = MS.hints[d]
        if not (cached and type(cached.entries) == "table") and hint and hint.href
           and not watched_set[hint.href] and not watch_history[hint.href] then
            table.insert(nxt, { name = hint.name or U.basename(hint.href), href = hint.href, is_dir = false,
                size = hint.size, cw = "next", dirpath = d, ts = ts })
        elseif cached and type(cached.entries) == "table" then
            local media = MS.cw_sorted[cached.entries]
            if not media then
                media = {}
                for _, e in ipairs(cached.entries) do
                    if not e.is_dir and U.is_media(e.name) then media[#media + 1] = e end
                end
                table.sort(media, function(a, b) return U.natural_less(a.name, b.name) end)
                MS.cw_sorted[cached.entries] = media
            end
            local last_watched = 0
            for i, e in ipairs(media) do if watched_set[e.href] then last_watched = i end end
            for i = last_watched + 1, #media do
                local e = media[i]
                if watch_history[e.href] then break end            -- already listed above as "resume"
                if not watched_set[e.href] then
                    table.insert(nxt, {
                        name = e.name, href = e.href, is_dir = false, size = e.size, cw = "next",
                        dirpath = d, ts = ts,
                    })
                    break
                end
            end
        end
    end
    table.sort(nxt, function(a, b) return a.ts > b.ts end)

    local out = {}
    for _, e in ipairs(resume) do out[#out + 1] = e end
    for _, e in ipairs(nxt) do out[#out + 1] = e end
    while #out > o.continue_max_items do out[#out] = nil end
    -- the same rows as before: the old list is kept, so the page (which keys on it) is not rebuilt for nothing
    if cw_cache and #cw_cache == #out then
        local same = true
        for i, e in ipairs(out) do
            local c = cw_cache[i]
            if c.href ~= e.href or c.cw ~= e.cw or c.ts ~= e.ts or c.dirpath ~= e.dirpath or c.pos ~= e.pos then same = false break end
        end
        if same then cw_dirty = false; return cw_cache end
    end
    cw_cache, cw_dirty = out, false
    return out
end

open_continue_view = function()
    current_path = CW_HREF
    file_entries = get_continue_list()
    selected_episode, scroll_offset_episodes = 1, 0
    free_scroll.episodes = false
    search_query, search_scope = "", nil
    status_line = "Continue Watching"
    if o.auto_focus_files_on_open then set_focus("episodes") end
    render()
end

-- 'm': manual watched / unwatched toggle (automatic tracking still works as before).
local function toggle_watched(entry)
    if not entry or entry.is_dir then return end
    if watched_set[entry.href] then
        watched_set[entry.href] = nil
        status_line = "Marked unwatched: " .. entry.name
    else
        watched_set[entry.href] = os.time()
        watch_history[entry.href] = nil
        status_line = "Marked watched: " .. entry.name
    end
    mark_continue_dirty()
    if current_path == CW_HREF then file_entries = get_continue_list(); after_files_set() end
    save_persistence()
    render()
end

-- Sidebar = tree nodes (all, or filtered if a sidebar-scoped search is active).
-- Episodes = files (optionally minus watched ones; filtered if an episodes-scoped search is active;
-- or the global index search results).
get_panel_items = function(panel_name)
    if panel_name == "sidebar" then
        if search_scope == "sidebar" and search_query ~= "" then
            return collect_matching_folders(search_query)
        end
        return flatten_visible()
    end
    if search_scope == "global" then return search_results end
    local base = file_entries
    if hide_watched and current_path ~= CW_HREF then
        local kept = {}
        for _, e in ipairs(base) do
            if not watched_set[e.href] then kept[#kept + 1] = e end
        end
        base = kept
    end
    if search_scope == "episodes" and search_query ~= "" then
        local toks = U.query_tokens(search_query)
        local out = {}
        for _, e in ipairs(base) do
            if U.match_score(e.name, toks) then out[#out + 1] = e end
        end
        return out
    end
    return base
end

-- Next MEDIA file after `current_href`, in natural filename order within that file's own folder
-- (from the cached listing) -- independent of what is on screen or how it is sorted, so
-- "Recent first" can never make auto-play go backwards.
find_next_media_href = function(current_href)
    local d = find_cached_dir(U.dirname(current_href))
    if not d or type(d.entries) ~= "table" then return nil end
    local media = {}
    for _, e in ipairs(d.entries) do
        if not e.is_dir and U.is_media(e.name) then media[#media + 1] = e end
    end
    table.sort(media, function(a, b) return U.natural_less(a.name, b.name) end)
    for i, e in ipairs(media) do
        if e.href == current_href then return media[i + 1] end
    end
    return nil
end

local loading_meta = nil   -- meta of the file most recently sent to loadfile (set before mpv confirms it opened)

-- Media files that come AFTER `href` in its own folder (natural filename order), from the cached listing.
local function folder_followers(href)
    local d = find_cached_dir(U.dirname(href))
    if not d or type(d.entries) ~= "table" then return {} end
    local media = {}
    for _, e in ipairs(d.entries) do
        if not e.is_dir and U.is_media(e.name) then media[#media + 1] = e end
    end
    table.sort(media, function(a, b) return U.natural_less(a.name, b.name) end)
    for i, e in ipairs(media) do
        if e.href == href then
            local out = {}
            for j = i + 1, #media do out[#out + 1] = media[j] end
            return out
        end
    end
    return {}
end

-- the stream URL of a library file - or its copy on your computer when you downloaded it (play_local_first)
function MS.play_url(entry)
    local l = MS.local_for and MS.local_for(entry)        -- HV.DL.local_for (HV is defined later)
    if l then return l, true end
    return file_stream_url(entry.href), false
end
play_entry = function(entry, append, playlist)
    if not append and MS.fb.active then MS.fb_stop(true) end
    local stream_url, is_local = MS.play_url(entry)
    local dirpath = U.dirname(entry.href)

    if append then
        -- Manual "queue" action ('a' key) - just append, no auto-chaining needed.
        pending_meta[stream_url] = { href = entry.href, name = entry.name, dirpath = dirpath }
        queue_load(stream_url, "append-play", entry.name)
        status_line = "Queued: " .. entry.name
        return
    end

    -- Compute (once) what the NEXT episode would be, but don't queue it yet -
    -- it only gets queued once playback crosses prefetch_threshold_pct.
    -- Queue the files that follow (a real mpv playlist: next/previous keys work, the playlist shows it).
    local followers = {}
    if o.queue_folder then followers = playlist or folder_followers(entry.href) end
    local qmax = math.max(0, tonumber(o.queue_max) or 200)
    while #followers > qmax do followers[#followers] = nil end
    local queued = #followers > 0

    local next_entry = (o.autoplay_next and not queued) and find_next_media_href(entry.href) or nil
    local meta = {
        href = entry.href, name = entry.name, dirpath = dirpath,
        next_queued = false,
        next_item = next_entry and { href = next_entry.href, name = next_entry.name } or nil,
    }
    pending_meta[stream_url] = meta
    loading_meta = meta

    local batch = { { url = stream_url, title = entry.name } }
    for _, f in ipairs(followers) do
        local u = MS.play_url(f)
        pending_meta[u] = { href = f.href, name = f.name, dirpath = U.dirname(f.href) }
        batch[#batch + 1] = { url = u, title = f.name }
    end
    queue_many(batch, "replace")
    if queued then pcall(mp.set_property, "prefetch-playlist", "yes") end
    status_line = "Playing: " .. entry.name .. (is_local and "  (from your computer)" or "") .. (queued and string.format("  (+%d queued)", #followers) or "")
    if o.auto_close_on_play then close_pending_for = stream_url; MS.close_t = mp.get_time() end
end

-- ============================================================
-- DOWNLOAD-WHILE-PLAYING FALLBACK
-- ============================================================
-- Some Real-Debrid links answer mpv's range requests (seeking to the end of an MKV to read its index)
-- with HTTP 503. A plain sequential download is not affected, so when streaming fails this downloads
-- the file with curl and plays the growing local file (ffmpeg's file "follow" mode) while it downloads.
MS.fb = { active = false }
MS.fb_dirty_files = {}

function MS.fb_dir()
    local d = tostring(o.fallback_dir or "")
    if d == "" then
        d = os.getenv("TEMP") or os.getenv("TMP") or os.getenv("TMPDIR") or "/tmp"
        d = d .. "/webdav-browser-cache"
    end
    d = d:gsub("\\", "/")
    return (d:gsub("/+$", ""))
end

function MS.fb_name(href, name)
    local h = 5381
    for i = 1, #href do h = (h * 33 + href:byte(i)) % 4294967296 end
    local safe = tostring(name or "video.mkv"):gsub("[^%w%._%-]", "_")
    return string.format("%08x_%s", h, safe)
end

function MS.fb_total(href)
    local c = find_cached_dir(U.dirname(href))
    if c and type(c.entries) == "table" then
        for _, e in ipairs(c.entries) do
            if e.href == href then return e.size end
        end
    end
    return nil
end

function MS.fb_remove(path)
    if not path then return end
    if not pcall(os.remove, path) then MS.fb_dirty_files[path] = true end
    local ok = io.open(path, "rb")
    if ok then ok:close(); MS.fb_dirty_files[path] = true else MS.fb_dirty_files[path] = nil end
end

-- Leftovers from earlier sessions (and files Windows would not let us delete while mpv had them open).
function MS.fb_purge()
    pcall(function()
        local dir = MS.fb_dir()
        local files = utils.readdir(dir, "files")
        if type(files) ~= "table" then return end
        local max_age = (tonumber(o.fallback_cleanup_hours) or 24) * 3600
        for _, f in ipairs(files) do
            local pth = dir .. "/" .. f
            local info = utils.file_info(pth)
            if info and info.mtime and (os.time() - info.mtime) > max_age then pcall(os.remove, pth) end
        end
    end)
end

function MS.fb_stop(delete_file)
    local fb = MS.fb
    if MS.sc and not (MS.sc.spec and MS.sc.spec.err) then MS.sc.done("fb") end
    if fb.timer then fb.timer:kill() end
    if fb.cmd then
        fb.killed = true
        pcall(mp.abort_async_command, fb.cmd)
    end
    local path = fb.path
    MS.fb = { active = false }
    if delete_file and path and not o.fallback_keep then MS.fb_remove(path) end
end

function MS.fb_say(text, spec)
    status_line = text
    -- the glass status card when this edition has one (else mpv's plain on-screen message)
    if MS.sc and spec then MS.sc.show(spec) elseif not MS.sc then mp.osd_message(text, 1.6) end
    if browser_active then render() end
end
-- "Show  ·  S01E03" (and the episode name) for the card, else the file name made readable
function MS.fb_title(meta)
    local em = MS.ep_meta and MS.ep_meta[meta.href]
    if em and em.show then return em.show .. (em.label and ("  ·  " .. em.label) or ""), em.name end
    local cp = MS.ct_parse and MS.ct_parse(tostring(meta.name or ""))
    local sn, en
    if MS.ct_sxe then sn, en = MS.ct_sxe(meta.name) end
    local tag = (tonumber(sn) and tonumber(en)) and string.format("S%02dE%02d", tonumber(sn), tonumber(en)) or (cp and (cp.se or cp.season))
    if cp and cp.title then return cp.title .. (tag and ("  ·  " .. tag) or "") end
    return (tostring(meta.name or ""):gsub("%.%w+$", ""):gsub("[%._]+", " "))
end
function MS.fb_spec(fb, over)
    local title = MS.fb_title(fb.meta or {})
    local sp = { owner = "fb", eyebrow = "DOWNLOAD & PLAY", title = title }
    for k, v in pairs(over or {}) do sp[k] = v end
    return sp
end

function MS.fb_play()
    local fb = MS.fb
    fb.playing = true
    fb.restarts = (fb.restarts or 0) + 1
    fb.local_url = "ffmpeg://file:" .. fb.path
    pending_meta[fb.local_url] = fb.meta
    loading_meta = fb.meta
    ensure_http_options()
    -- local growing file: plain loadfile. Played again after it ran dry: the same playlist entry. After a failed
    -- stream: in that stream's place, so the rest of the queue stays as it was. Else (the P key) it replaces the list.
    local pl = mp.get_property_native("playlist") or {}
    for i, e in ipairs(pl) do
        if e.filename == fb.local_url then mp.commandv("playlist-play-index", tostring(i - 1)); return end
    end
    if fb.pl_id then
        for i, e in ipairs(pl) do
            if e.id == fb.pl_id then
                mp.commandv("loadfile", fb.local_url, "append")
                local n = mp.get_property_number("playlist-count") or 0
                mp.commandv("playlist-move", tostring(n - 1), tostring(i - 1))
                mp.commandv("playlist-play-index", tostring(i - 1))
                mp.commandv("playlist-remove", tostring(i))
                return
            end
        end
    end
    mp.commandv("loadfile", fb.local_url, "replace")
    if o.auto_close_on_play then close_pending_for = fb.local_url; MS.close_t = mp.get_time() end
end

function MS.fb_tick()
    local fb = MS.fb
    if not fb.active then return end
    local info = utils.file_info(fb.path)
    local size = info and info.size or 0
    local now = U.now_s()
    local speed = 0
    if fb.last_t and now > fb.last_t then speed = math.max(0, (size - (fb.last_size or 0)) / (now - fb.last_t)) end
    fb.last_size, fb.last_t = size, now
    fb.size, fb.speed = size, speed

    local total = tonumber(fb.total) or 0
    local pct = (total > 0) and math.floor(size / total * 100) or nil
    local label = string.format("%s%s of %s%s", U.fmt_bytes(size), pct and (" (" .. pct .. "%)") or "",
        total > 0 and U.fmt_bytes(total) or "?", speed > 0 and ("  " .. U.fmt_bytes(speed) .. "/s") or "")
    local spd = speed > 0 and (U.fmt_bytes(speed) .. "/s") or "waiting for data"

    if fb.failed and not fb.playing then
        local why = tostring(fb.err or "unknown error"):gsub("%s+$", "")
        local spec = MS.fb_spec(fb, { err = true, line = "Download failed: " .. why:gsub("%s+", " "):sub(1, 120), frac = 0, secs = 8 })
        MS.fb_stop(true)
        MS.fb_say("Download failed: " .. why:sub(1, 120), spec)
        return
    end

    if not fb.playing then
        local need = math.floor((tonumber(o.fallback_start_mb) or 200) * 1048576)
        if total > 0 then need = math.min(need, total) end
        if size > 0 and (size >= need or fb.done) then
            MS.fb_say("Download-play: starting (" .. label .. ")", MS.fb_spec(fb, { line = "Starting playback…", frac = 1 }))
            MS.fb_play()
            if MS.sc then MS.sc.done("fb") end
        else
            local eta = (speed > 0) and string.format("  ·  ~%d s", math.ceil((need - size) / speed)) or ""
            MS.fb_say(string.format("Download-play: buffering %s  -  starts at %d MB", label, math.floor(need / 1048576)),
                MS.fb_spec(fb, { line = string.format("%s of %s  ·  %s%s", U.fmt_bytes(size), U.fmt_bytes(need), spd, eta),
                    frac = (size > 0) and (size / math.max(1, need)) or nil,
                    sub = string.format("Plays at %s%s  ·  keeps downloading while you watch", U.fmt_bytes(need),
                        (fb.reason and fb.reason ~= "manual") and "  ·  streaming failed, so it downloads first" or "") }))
        end
        return
    end

    -- playing the growing file
    if fb.done and mp.get_property("path") ~= fb.local_url then
        MS.fb_stop(true)       -- finished and mpv has moved on / gone idle: clean up
        return
    end
    if fb.done then
        -- ffmpeg's "follow" keeps waiting at the end of the file; once the download is complete, move on.
        local pos, dur = mp.get_property_number("time-pos"), mp.get_property_number("duration")
        if pos and dur and dur > 0 and pos >= dur - 1.5 and mp.get_property("path") == fb.local_url then
            local pl_pos, pl_cnt = mp.get_property_number("playlist-pos"), mp.get_property_number("playlist-count")
            if pl_pos and pl_cnt and pl_pos + 1 < pl_cnt then mp.commandv("playlist-next", "force") else mp.commandv("stop") end
        end
    elseif fb.failed then
        if not fb.fail_told then
            fb.fail_told = true
            MS.fb_say("Download stopped (" .. tostring(fb.err or "error"):sub(1, 80) .. ") - playback may stall",
                MS.fb_spec(fb, { err = true, line = "The download stopped: " .. tostring(fb.err or "error"):gsub("%s+", " "):sub(1, 90),
                    sub = "Playback may stall once it reaches the end of what arrived", frac = pct and pct / 100 or 0, secs = 8 }))
        end
    elseif mp.get_property_bool("core-idle") and not mp.get_property_bool("pause") then
        -- the video caught up with the download: the card says how far along it is
        if MS.sc then
            MS.sc.show(MS.fb_spec(fb, { eyebrow = "WAITING FOR THE DOWNLOAD", line = string.format("%s of %s  ·  %s", U.fmt_bytes(size),
                total > 0 and U.fmt_bytes(total) or "?", spd), frac = (total > 0) and (size / total) or nil }))
        else mp.osd_message("Waiting for download: " .. label, 1.2) end
    elseif MS.sc then
        MS.sc.done("fb")
    end
end

-- meta: { href, name, dirpath, next_item... }
function MS.fb_start(meta, reason)
    if not o.fallback_download or not meta or not meta.href then return false end
    if MS.fb.active then
        if MS.fb.href == meta.href then return true end
        MS.fb_stop(true)       -- a different file now needs the fallback (e.g. the next episode): the old download is done with
    end
    local path = MS.fb_dir() .. "/" .. MS.fb_name(meta.href, meta.name)
    MS.fb = {
        active = true, meta = meta, href = meta.href, path = path, total = meta.size or MS.fb_total(meta.href),
        playing = false, done = false, failed = false, reason = reason,
    }
    local fb = MS.fb
    local args = { o.curl_path, "-s", "-S", "-L", "--create-dirs", "-C", "-", "--retry", "30", "--retry-delay", "3",
        "--connect-timeout", "15", "-o", path }
    if o.user_agent ~= "" then args[#args + 1] = "-A"; args[#args + 1] = o.user_agent end
    local stdin_data = nil
    if not meta.direct_url then stdin_data = U.curl_auth(args) end       -- a Real-Debrid link needs no WebDAV login
    args[#args + 1] = meta.direct_url or (o.url .. meta.href)
    fb.cmd = mp.command_native_async({
        name = "subprocess", args = args, stdin_data = stdin_data,
        capture_stdout = false, capture_stderr = true, playback_only = false,
    }, function(success, result)
        if MS.fb ~= fb or fb.killed then return end
        fb.cmd = nil
        if success and result and result.status == 0 then
            fb.done = true
        else
            fb.failed = true
            fb.err = (result and result.stderr and result.stderr ~= "" and result.stderr)
                or ("curl exited with status " .. tostring(result and result.status))
        end
    end)
    fb.timer = mp.add_periodic_timer(1, MS.fb_tick)
    MS.fb_say("Download-play: starting download...", MS.fb_spec(fb, { line = "Starting the download…" }))
    return true
end

-- Manual 'p' key: skip streaming and use the download route for the selected file.
function MS.fb_manual(entry)
    if not entry or entry.is_dir or not U.is_media(entry.name) then return end
    if MS.fb.active then MS.fb_stop(true) end
    local next_entry = o.autoplay_next and find_next_media_href(entry.href) or nil
    local meta = {
        href = entry.href, name = entry.name, dirpath = U.dirname(entry.href), next_queued = false,
        next_item = next_entry and { href = next_entry.href, name = next_entry.name } or nil,
    }
    if not MS.fb_start_forced(meta) then status_line = "Download-play is disabled (fallback_download=no)" ; render() end
end
function MS.fb_start_forced(meta)
    local saved = o.fallback_download
    o.fallback_download = true
    local ok = MS.fb_start(meta, "manual")
    o.fallback_download = saved
    return ok
end

-- script-message webdav-browser-play <href> [download]
-- e.g. in input.conf:  F5 script-message webdav-browser-play /torrents/Show/ep1.mkv download
mp.register_script_message("webdav-browser-play", function(href, mode)
    if not MS.active then return end
    if not href or href == "" then return end
    local entry = { href = href, name = U.percent_decode(U.basename(href)), is_dir = false }
    if mode == "download" then MS.fb_manual(entry) else play_entry(entry, false) end
end)

-- Applies ffmpeg's "follow" mode to the local growing file (file-local, so nothing else is affected).
mp.add_hook("on_load", 40, function()
    local fb = MS.fb
    if not (fb.active and fb.local_url) then return end
    if (mp.get_property("stream-open-filename") or "") ~= fb.local_url then return end
    local rw = tostring(math.floor((tonumber(o.fallback_stall_secs) or 45) * 1000000))
    if not pcall(mp.set_property_native, "file-local-options/stream-lavf-o", { follow = "1", rw_timeout = rw }) then
        pcall(mp.set_property, "file-local-options/stream-lavf-o", "follow=1,rw_timeout=" .. rw)
    end
end)

-- ============================================================
-- NAVIGATION
-- ============================================================
move_selection = function(delta)
    local items = get_panel_items(focus_panel)
    if #items == 0 then return end
    free_scroll[focus_panel == "sidebar" and "sidebar" or "episodes"] = false
    if focus_panel == "sidebar" then
        sidebar_selected_index = math.max(1, math.min(#items, sidebar_selected_index + delta))
    else
        selected_episode = math.max(1, math.min(#items, selected_episode + delta))
    end
    render()
end

local function want_sidebar_frac()
    local f = tonumber(o.focused_width_pct) or 70
    f = math.max(55, math.min(80, f)) / 100
    if focus_panel == "sidebar" then return f end
    return 1 - f
end

local function stop_anim()
    if anim_timer then anim_timer:kill(); anim_timer = nil end
end

local function start_anim()
    if anim_timer then return end
    anim_timer = mp.add_periodic_timer(0.033, function()
        local target = want_sidebar_frac()
        local d = target - sidebar_frac
        if math.abs(d) < 0.003 then
            sidebar_frac = target
            stop_anim()
            render()
            return
        end
        sidebar_frac = sidebar_frac + d * 0.45
        render()
    end)
end

set_focus = function(panel)
    if focus_panel == panel then
        if math.abs(sidebar_frac - want_sidebar_frac()) > 0.01 then start_anim() end
        return
    end
    focus_panel = panel
    start_anim()
    render()
end

switch_panel = function()
    set_focus((focus_panel == "sidebar") and "episodes" or "sidebar")
end

-- Makes `href` (a folder) visible in the Folders panel by materialising its ancestors from the
-- cached listings and expanding them, then opens it. With `select_href`, that file is highlighted
-- in the Files panel once the listing is shown. Used by global-search results.
reveal_path = function(href, select_href)
    local chain, cur, guard = {}, href, 0
    while guard < 64 do
        guard = guard + 1
        local parent = U.dirname(cur)
        if parent == cur or #parent >= #cur then break end
        table.insert(chain, 1, parent)
        cur = parent
        if U.with_slash(parent) == U.with_slash(root_href) or parent == "/" then break end
    end
    if chain[1] ~= root_href and U.with_slash(chain[1] or "") ~= U.with_slash(root_href) then
        table.insert(chain, 1, root_href)
    end
    for _, a in ipairs(chain) do
        local c = find_cached_dir(a)
        if c and type(c.entries) == "table" then
            apply_dir_result(a, c.entries)
            if tree[a] then tree[a].expanded = true end
        end
    end

    search_query, search_scope, search_results = "", nil, {}
    pending_select_href = select_href
    local node = tree[href]
    if href == root_href or U.with_slash(href) == U.with_slash(root_href) then
        current_path = root_href
        selected_episode, scroll_offset_episodes = 1, 0
        show_dir(root_href, "Opening")
        node = nil
    elseif node then
        open_folder_node(node)
    else
        status_line = "That folder isn't in the cache yet - press R to refresh"
        render()
        return
    end
    if node then
        for i, n in ipairs(flatten_visible()) do
            if n.href == node.href then
                sidebar_selected_index = i
                free_scroll.sidebar = false
                break
            end
        end
    end
    set_focus(select_href and "episodes" or "sidebar")
    render()
end

-- reveal = true (Right arrow / l): jump to the folder that contains a search result instead of
-- playing it. Enter always plays files.
open_selected = function(reveal)
    if focus_panel == "sidebar" then
        local node = get_panel_items("sidebar")[sidebar_selected_index]
        if node then open_folder_node(node) end
        return
    end
    local item = get_panel_items("episodes")[selected_episode]
    if not item then return end
    if item.is_dir then
        reveal_path(item.href)
    elseif reveal and search_scope == "global" then
        reveal_path(U.dirname(item.href), item.href)
    else
        play_entry(item, false)
        render()
    end
end

-- Expand / collapse a folder WITHOUT opening it in the Files panel (the little arrow in the row).
local function toggle_expand(node)
    if not node or node.virtual then return end
    if node.expanded then
        node.expanded = false
        render()
        return
    end
    node.expanded = true
    if not node.loaded then
        local cached = dir_cache[node.href]
        if cached then
            apply_dir_result(node.href, cached.entries)
            if not cache_is_fresh(cached) then fetch_listing(node.href, { silent = true }) end
        else
            fetch_listing(node.href, { status = "Loading: " .. node.name })
        end
    end
    render()
end

collapse_or_parent = function()
    if focus_panel == "episodes" then
        set_focus("sidebar")
        return
    end
    local items = get_panel_items("sidebar")
    local node = items[sidebar_selected_index]
    if not node or node.virtual then return end

    if node.expanded and #node.children > 0 then
        node.expanded = false
        render()
        return
    end

    if node.parent_href then
        for i, n in ipairs(items) do
            if n.href == node.parent_href then
                sidebar_selected_index = i
                break
            end
        end
    end
    render()
end

queue_add_current = function()
    if focus_panel ~= "episodes" then return end
    local item = get_panel_items("episodes")[selected_episode]
    if item and not item.is_dir then play_entry(item, true); render() end
end

-- Sort order is remembered PER FOLDER (and saved). `s` toggles the folder shown in the Files panel;
-- with the Folders panel focused it toggles the highlighted folder's own listing (its sub-folders
-- and files). `target` lets the header button always address the open folder.
toggle_sort = function(target)
    if not target then
        if focus_panel == "sidebar" then
            local node = get_panel_items("sidebar")[sidebar_selected_index]
            target = (node and not node.virtual) and node.href or current_path
        else
            target = current_path
        end
    end
    if target == CW_HREF then return end
    local new_mode = (sort_mode_for(target) == "recent") and "name" or "recent"
    sort_by_dir[target] = new_mode

    local cached = find_cached_dir(target)
    if cached and type(cached.entries) == "table" then
        local files = apply_dir_result(target, cached.entries)
        if current_path == target then
            file_entries = files
            selected_episode, scroll_offset_episodes = 1, 0
            free_scroll.episodes = false
        end
    end
    local nm = U.basename(target)
    status_line = string.format("Sort (%s): %s", nm ~= "" and nm or "root", new_mode == "recent" and "Recent first" or "Name")
    debounced_save_persistence()
    render()
end

-- ============================================================
-- LIBRARY INDEX  (background crawl feeding the global search, key 'f')
-- ============================================================
-- The "index" is simply the directory cache: the crawler walks the library breadth-first, ONE
-- request at a time with a pause in between (gentle on the server), and stores every listing in
-- dir_cache, which is saved to disk. Global search then scans those cached listings, so it is
-- instant and works across restarts. Folders whose cached listing is younger than
-- index_refresh_hours are not re-fetched; 'R' forces a complete re-crawl.
local IDX = {
    running = false, force = false, queue = {}, head = 1, scanned = 0, fetched = 0,
    errors = 0, consecutive_errors = 0, started = nil, last_stop = nil, autostart_armed = false,
}

function IDX.count_items()
    local dirs, items = 0, 0
    for _, c in pairs(dir_cache) do
        if type(c.entries) == "table" then dirs = dirs + 1; items = items + #c.entries end
    end
    return dirs, items
end

function IDX.finish(complete, reason)
    IDX.running = false
    MS.idx_running = false
    MS.cache_version = MS.cache_version + 1      -- make sure the final index state is searchable
    IDX.last_stop = os.time()
    if complete then
        index_meta.last_full = os.time()
        IDX.last_reason = "complete"
    else
        IDX.last_reason = reason or "stopped"
    end
    save_persistence()
    save_dircache()
    if browser_active then
        if search_scope == "global" then run_global_search_hook() end
        render()
    end
end

function IDX.step()
    if not IDX.running then return end
    if IDX.head > #IDX.queue then IDX.finish(true); return end
    if IDX.scanned >= o.index_max_dirs then IDX.finish(false, "folder limit reached"); return end
    if IDX.consecutive_errors >= 5 then IDX.finish(false, "stopped after repeated errors"); return end

    local href = IDX.queue[IDX.head]
    IDX.head = IDX.head + 1
    IDX.scanned = IDX.scanned + 1

    local function enqueue_children(entries)
        for _, e in ipairs(entries) do
            if e.is_dir then IDX.queue[#IDX.queue + 1] = e.href end
        end
    end
    local gen = IDX.gen
    local function next_step(delay) mp.add_timeout(delay, function() if IDX.gen == gen then IDX.step() end end) end

    local cached = dir_cache[href]
    local max_age = o.index_refresh_hours * 3600
    local fresh_enough = cached and not cached.stale and type(cached.entries) == "table"
        and (os.time() - (cached.ts or 0)) < max_age
    if fresh_enough and not IDX.force then
        enqueue_children(cached.entries)
        next_step(0.002)          -- no network involved: keep going right away
        return
    end

    fetch_listing(href, { silent = true }, function(ok)
        if not IDX.running or IDX.gen ~= gen then return end
        if ok then
            IDX.fetched = IDX.fetched + 1
            IDX.consecutive_errors = 0
            local c = dir_cache[href]
            if c then enqueue_children(c.entries) end
        else
            IDX.errors = IDX.errors + 1
            IDX.consecutive_errors = IDX.consecutive_errors + 1
        end
        if browser_active and search_scope == "global" then
            run_global_search_hook()
            render()
        end
        next_step(math.max(0.05, o.index_delay_secs))
    end)
end

index_start = function(force)
    if not o.index_enabled or o.url == "" then return end
    if IDX.running then
        if force then IDX.force = true end
        return
    end
    IDX.running, IDX.force = true, force and true or false
    IDX.gen = (IDX.gen or 0) + 1
    MS.idx_running = true
    IDX.queue, IDX.head = { root_href }, 1
    IDX.scanned, IDX.fetched, IDX.errors, IDX.consecutive_errors = 0, 0, 0, 0
    IDX.started, IDX.last_reason = os.time(), nil
    if browser_active then status_line = force and "Re-indexing the library..." or "Indexing the library in the background..." end
    mp.add_timeout(0.05, IDX.step)
    if browser_active then render() end
end

index_stop = function()
    if IDX.running then IDX.finish(false, "stopped") end
end

-- One-line description for the footer / debug panel.
function IDX.summary()
    local dirs, items = IDX.count_items()
    if IDX.running then
        return string.format("Indexing: %d folder%s visited, %d item%s", IDX.scanned, IDX.scanned == 1 and "" or "s",
            items, items == 1 and "" or "s")
    end
    if o.index_mode ~= "full" then
        return string.format("Search covers %d folder%s you've opened (%d items)", dirs, dirs == 1 and "" or "s", items)
    end
    if index_meta.last_full then
        return string.format("Index: %d items in %d folders - updated %s", items, dirs, U.fmt_age(index_meta.last_full))
    end
    return string.format("Index: %d items cached so far (full crawl not finished yet)", items)
end

-- Starts a crawl automatically (once per browser session) when the index is stale/missing.
function IDX.maybe_autostart()
    if not (o.index_enabled and o.index_auto_update and o.index_mode == "full") or IDX.autostart_armed or IDX.running then return end
    local age_ok = index_meta.last_full and (os.time() - index_meta.last_full) < o.index_refresh_hours * 3600
    if age_ok then return end
    IDX.autostart_armed = true
    mp.add_timeout(o.index_start_delay_secs, function()
        IDX.autostart_armed = false
        if o.index_enabled and not IDX.running then index_start(false) end
    end)
end

-- ============================================================
-- SEARCH
-- ============================================================
MS.global_total = 0           -- total matches before the index_max_results cut-off
MS.flat, MS.flat_built_at, MS.flat_version, MS.cache_version = nil, 0, -1, 0
MS.grow, MS.seen = {}, {}         -- folders whose listing is still growing / how often each was listed this session

-- "ep2" sorts before "ep10": zero-pad digit runs so plain string comparison gives natural order
local function pad_digits(s)
    return (s:gsub("%d+", function(d) return (#d < 8) and (string.rep("0", 8 - #d) .. d) or d end))
end

-- Flat, pre-sorted copy of every cached entry (normalised name + sort key). Built once per cache
-- change, so a keystroke is just a linear scan with no sorting.
local function build_flat()
    local flat, n = {}, 0
    for dirhref, c in pairs(dir_cache) do
        if type(c.entries) == "table" then
            for _, e in ipairs(c.entries) do
                local hay = U.norm_text(e.name)
                n = n + 1
                flat[n] = { hay = hay, key = pad_digits(hay), e = e, dir = dirhref }
            end
        end
    end
    table.sort(flat, function(a, b) return a.key < b.key end)
    MS.flat, MS.flat_version, MS.flat_built_at = flat, MS.cache_version, U.now_s()
end

local function run_global_search()
    search_results, MS.global_total = {}, 0
    local toks = U.query_tokens(search_query)
    if #toks == 0 then return end
    -- rebuild when the cache changed (while a crawl is running: at most every 4 s, so typing stays smooth)
    if not MS.flat or (MS.flat_version ~= MS.cache_version and (not MS.idx_running or U.now_s() - MS.flat_built_at > 4)) then
        build_flat()
    end
    local maxr = o.index_max_results
    local buckets, maxscore, total = {}, 0, 0
    for _, it in ipairs(MS.flat) do
        local hay, score, hit = it.hay, 0, true
        for _, tok in ipairs(toks) do
            local pos = hay:find(tok, 1, true)
            if not pos then hit = false; break end
            score = score + ((hay:sub(pos - 1, pos - 1) == " ") and 3 or 1)
        end
        if hit then
            total = total + 1
            local bucket = buckets[score]
            if not bucket then
                bucket = {}
                buckets[score] = bucket
                if score > maxscore then maxscore = score end
            end
            if #bucket < maxr then bucket[#bucket + 1] = it end   -- already in name order; never need more than maxr
        end
    end
    MS.global_total = total
    local out = {}
    for score = maxscore, 0, -1 do
        local bucket = buckets[score]
        if bucket then
            for _, it in ipairs(bucket) do
                if #out >= maxr then break end
                out[#out + 1] = {
                    name = it.e.name, href = it.e.href, is_dir = it.e.is_dir,
                    size = it.e.size, mtime = it.e.mtime, dirpath = it.dir,
                }
            end
        end
        if #out >= maxr then break end
    end
    search_results = out
end
run_global_search_hook = run_global_search

local function search_reset_selection()
    if search_scope == "sidebar" then
        sidebar_selected_index, scroll_offset_folders = 1, 0
    else
        selected_episode, scroll_offset_episodes = 1, 0
    end
    free_scroll.sidebar, free_scroll.episodes = false, false
end

local function search_hint()
    if search_scope == "global" then return "Type to search the folders you have opened" end
    return "Type to filter " .. (search_scope == "sidebar" and "folders" or "files")
end

-- scope: "sidebar" | "episodes" | "global" (nil = the focused panel)
start_search = function(scope)
    if not browser_active or search_active then return end
    scope = scope or focus_panel
    if search_scope ~= scope then search_query = "" end
    MS.scur = #search_query
    search_scope = scope
    search_active = true
    if scope == "global" then
        set_focus("episodes")
        run_global_search()
        IDX.maybe_autostart()
    end
    search_reset_selection()
    unbind_all()
    bind_search()
    status_line = search_hint() .. " - Enter to confirm, Esc to cancel"
    render()
end

confirm_search = function()
    search_active = false
    unbind_search()
    bind_all()
    search_reset_selection()
    if search_scope == "global" then
        status_line = string.format('Search "%s": %d result%s', search_query, MS.global_total, MS.global_total == 1 and "" or "s")
        set_focus("episodes")
    else
        status_line = (search_query ~= "") and string.format('Filter: "%s"', search_query) or "Ready"
    end
    render()
end

cancel_search = function()
    search_active = false
    search_query = ""
    search_scope = nil
    search_results, MS.global_total = {}, 0
    unbind_search()
    bind_all()
    selected_episode, scroll_offset_episodes = 1, 0
    sidebar_selected_index, scroll_offset_folders = 1, 0
    status_line = "Ready"
    render()
end

-- Text cursor in the search box: MS.scur = bytes before it. Left / Right / Home / End / Ctrl+arrows / Del edit in place.
function MS.s_cont(s, i) local b = s:byte(i); return b and b >= 128 and b < 192 end
function MS.scur_get() MS.scur = math.max(0, math.min(#search_query, MS.scur or #search_query)); return MS.scur end
function MS.scur_prev(q, c) c = c - 1; while c > 0 and MS.s_cont(q, c + 1) do c = c - 1 end; return math.max(0, c) end
function MS.scur_next(q, c) c = c + 1; while c < #q and MS.s_cont(q, c + 1) do c = c + 1 end; return math.min(#q, c) end
function MS.search_changed()
    if search_scope == "global" then run_global_search() end
    search_reset_selection()
    render()
end

search_append = function(ch)
    local c = MS.scur_get()
    search_query = search_query:sub(1, c) .. ch .. search_query:sub(c + 1)
    MS.scur = c + #ch
    MS.XT.typed(true)
    MS.search_changed()
end

search_backspace = function()
    local c = MS.scur_get()
    if c == 0 then return end
    local p = MS.scur_prev(search_query, c)
    search_query, MS.scur = search_query:sub(1, p) .. search_query:sub(c + 1), p
    MS.XT.typed(false)
    MS.search_changed()
end

function MS.search_delete()
    local c = MS.scur_get()
    if c >= #search_query then return end
    search_query = search_query:sub(1, c) .. search_query:sub(MS.scur_next(search_query, c) + 1)
    MS.XT.typed(false)
    MS.search_changed()
end

-- dir = -1 / 1 one character, -2 / 2 one word, "home" / "end"
function MS.scur_move(dir)
    local q, c = search_query, MS.scur_get()
    if dir == "home" then c = 0
    elseif dir == "end" then c = #q
    elseif dir == -1 then c = MS.scur_prev(q, c)
    elseif dir == 1 then c = MS.scur_next(q, c)
    elseif dir == -2 then
        while c > 0 and q:sub(c, c) == " " do c = c - 1 end
        while c > 0 and q:sub(c, c) ~= " " do c = c - 1 end
    elseif dir == 2 then
        while c < #q and q:sub(c + 1, c + 1) == " " do c = c + 1 end
        while c < #q and q:sub(c + 1, c + 1) ~= " " do c = c + 1 end
    end
    MS.scur = c
    if MS.XT then MS.XT.typed(false) end
    render()
end

-- ============================================================
-- DRAWING PRIMITIVES  (PlayRes pixels; \fs18 => 1 draw unit = 1 px)
-- ============================================================
function D.style_text(fs)
    return string.format("\\bord0\\shad0\\q2\\fn%s\\fs%d", o.font_name, fs or o.font_size)
end

function D.ev_text(x, y, an, extra, str)
    return string.format("{\\an%d\\pos(%d,%d)%s%s}%s",
        an, math.floor(x), math.floor(y), D.style_text(o.font_size), extra or "", str)
end

function D.rd(v) return math.floor(v + 0.5) end

function D.rect_path(x1, y1, x2, y2)
    x1, y1, x2, y2 = D.rd(x1), D.rd(y1), D.rd(x2), D.rd(y2)
    return string.format("m %d %d l %d %d l %d %d l %d %d", x1, y1, x2, y1, x2, y2, x1, y2)
end

-- fine = coordinates to a hundredth of a pixel (libass draws sub-pixel edges): for shapes that MOVE, so a glide does
-- not step a whole pixel at a time. Still shapes keep whole pixels (sharper edges).
function D.fp(v) return (string.format("%.2f", v):gsub("%.?0+$", "")) end
-- the same rectangles come up frame after frame (every card's shadow, outline and tint): their paths are kept
D.RPC, D.RPn = {}, 0
function D.rounded_path(x1, y1, x2, y2, r, fine)
    local key = x1 .. "," .. y1 .. "," .. x2 .. "," .. y2 .. "," .. r .. (fine and "f" or "")
    local hit = D.RPC[key]
    if hit then return hit end
    local s = D.rounded_path0(x1, y1, x2, y2, r, fine)
    if D.RPn > 6000 then D.RPC, D.RPn = {}, 0 end
    D.RPC[key], D.RPn = s, D.RPn + 1
    return s
end
function D.rounded_path0(x1, y1, x2, y2, r, fine)
    r = math.max(0, math.min(r, (x2 - x1) / 2, (y2 - y1) / 2))
    local n = fine and D.fp or D.rd
    if r < 1 then
        if not fine then return D.rect_path(x1, y1, x2, y2) end
        return string.format("m %s %s l %s %s l %s %s l %s %s", n(x1), n(y1), n(x2), n(y1), n(x2), n(y2), n(x1), n(y2))
    end
    local k = r * 0.5522847
    return table.concat({
        string.format("m %s %s",   n(x1 + r), n(y1)),
        string.format("l %s %s",   n(x2 - r), n(y1)),
        string.format("b %s %s %s %s %s %s", n(x2 - r + k), n(y1), n(x2), n(y1 + r - k), n(x2), n(y1 + r)),
        string.format("l %s %s",   n(x2), n(y2 - r)),
        string.format("b %s %s %s %s %s %s", n(x2), n(y2 - r + k), n(x2 - r + k), n(y2), n(x2 - r), n(y2)),
        string.format("l %s %s",   n(x1 + r), n(y2)),
        string.format("b %s %s %s %s %s %s", n(x1 + r - k), n(y2), n(x1), n(y2 - r + k), n(x1), n(y2 - r)),
        string.format("l %s %s",   n(x1), n(y1 + r)),
        string.format("b %s %s %s %s %s %s", n(x1), n(y1 + r - k), n(x1 + r - k), n(y1), n(x1 + r), n(y1)),
    }, " ")
end

function D.ev_shape(path, fill_rgb, fill_a, border_rgb, border_a, border_w)
    local tags = string.format("\\fs18\\bord%d\\shad0\\1c%s\\1a%s",
        border_w or 0, U.ass_color(fill_rgb), U.ass_alpha(fill_a or 100))
    if border_rgb and border_w and border_w > 0 then
        tags = tags .. "\\3c" .. U.ass_color(border_rgb) .. "\\3a" .. U.ass_alpha(border_a or 100)
    else
        tags = tags .. "\\3a&HFF&"
    end
    return string.format("{\\an7\\pos(0,0)%s\\p1}%s{\\p0}", tags, path)
end

function D.ev_rect(x1, y1, x2, y2, fill_rgb, fill_a, border_rgb, border_a, border_w, radius, fine)
    if x2 <= x1 or y2 <= y1 then return "" end
    local path = (fine or (radius and radius > 0)) and D.rounded_path(x1, y1, x2, y2, radius or 0, fine) or D.rect_path(x1, y1, x2, y2)
    return D.ev_shape(path, fill_rgb, fill_a, border_rgb, border_a, border_w)
end

-- an "x" as a shape, centred exactly on cx, cy (a font's "×" sits a little off-centre): arm length a, stroke t
function D.cross_path(cx, cy, a, t)
    local pts = { { t, a }, { t, t }, { a, t }, { a, -t }, { t, -t }, { t, -a }, { -t, -a }, { -t, -t }, { -a, -t }, { -a, t }, { -t, t }, { -t, a } }
    local c = math.sqrt(0.5)
    local out = {}
    for i, q in ipairs(pts) do
        out[#out + 1] = (i == 1 and "m " or (i == 2 and "l " or "")) .. string.format("%d %d", D.rd(cx + (q[1] - q[2]) * c), D.rd(cy + (q[1] + q[2]) * c))
    end
    return table.concat(out, " ")
end
-- the toast look for small controls in the header: a faint glass fill and a hairline edge
function D.ev_pill(x1, y1, x2, y2, r, S, fill_rgb, fill_a, edge_a)
    return D.ev_rect(x1, y1, x2, y2, fill_rgb or "FFFFFF", fill_a or 6, "FFFFFF", edge_a or 17, math.max(1, math.floor((S or 1) + 0.5)), r)
end

function D.clip_tag(x1, y1, x2, y2)
    return string.format("\\clip(%d,%d,%d,%d)", math.floor(x1), math.floor(y1), math.floor(x2), math.floor(y2))
end

-- ===== LiquidGlass-style gradient border + top glass highlight =====
-- libass can't stroke a shape with a true gradient, so we fake a vertical
-- light->dark->light border (same idea as LiquidGlass's LinearGradientBrush)
-- by drawing the SAME border-only outline three times, each clipped to a
-- horizontal band of the panel with its own flat color.
function D.ev_border_pass(path, border_rgb, border_a, border_w, clip)
    local tags = string.format("\\fs18\\bord%d\\shad0\\1a&HFF&\\3c%s\\3a%s%s",
        border_w or 1, U.ass_color(border_rgb), U.ass_alpha(border_a or 100), clip or "")
    return string.format("{\\an7\\pos(0,0)%s\\p1}%s{\\p0}", tags, path)
end

function D.draw_gradient_border(chunks, x1, y1, x2, y2, radius, border_w, colors, alpha)
    if not border_w or border_w <= 0 then return end
    local path = D.rounded_path(x1, y1, x2, y2, radius)
    local h = y2 - y1
    local pad = border_w + 2
    local bands = {
        { y1 - pad,          y1 + h * 0.32, colors[1] },
        { y1 + h * 0.32,     y1 + h * 0.68, colors[2] },
        { y1 + h * 0.68,     y2 + pad,      colors[3] },
    }
    for _, band in ipairs(bands) do
        local clip = D.clip_tag(x1 - pad, band[1], x2 + pad, band[2])
        table.insert(chunks, D.ev_border_pass(path, band[3], alpha, border_w, clip))
    end
end

-- Thin bright line just inside the top edge, simulating light catching the
-- top of a glass panel. Inset horizontally so it doesn't poke out of the
-- rounded corners. border_w should match whatever border width THIS panel is
-- currently using (focused vs unfocused), so the highlight sits flush against
-- its own border instead of a hardcoded one.
function D.draw_glass_highlight(chunks, x1, y1, x2, y2, radius, border_w)
    local inset = math.max(6, radius)
    local hy1 = y1 + math.max(1, border_w or 1)
    table.insert(chunks, D.ev_rect(x1 + inset, hy1, x2 - inset, hy1 + 1.6,
        "FFFFFF", U.pick(o.glass_highlight_opacity, 14), nil, 0, 0, 1))
end

local function build_breadcrumb(path, max_px)
    local parts = {}
    for seg in path:gmatch("[^/]+") do table.insert(parts, U.percent_decode(seg)) end
    local s = "root" .. (#parts > 0 and (" / " .. table.concat(parts, " / ")) or "")
    return U.fit_text(s, max_px, o.font_size - 6)
end

-- 26.10 experimental_caret in the list view: the cursor blinks (solid while you type) and the letter just typed fades
-- in. Its own small timers (the list has no animation layer); nothing runs while the box is not being typed in.
MS.XT = { FADE = 0.15 }
function MS.XT.on() return o.experimental_caret == true end
function MS.XT.still()                 -- a fade only when nothing plays behind the browser
    return o.animations ~= false and not (mp.get_property("path") and mp.get_property_bool("pause", true) == false)
end
function MS.XT.typed(ins)
    MS.XT.t, MS.XT.ins = mp.get_time(), ins and true or nil
    if not MS.XT.on() then return end
    MS.XT.arm()
    if ins and MS.XT.still() then
        if MS.XT.ft then MS.XT.ft:kill() end
        MS.XT.ft = mp.add_periodic_timer(1 / 60, function()
            if not browser_active or mp.get_time() - MS.XT.t > MS.XT.FADE + 0.02 then MS.XT.ft:kill(); MS.XT.ft = nil end
            render()
        end)
    end
end
function MS.XT.vis()
    if not MS.XT.on() or not MS.XT.still() then return true end      -- (animations=no, or over a playing video: solid)
    local dt = mp.get_time() - (MS.XT.t or 0)
    if dt < 0.55 then return true end
    return math.floor((dt - 0.55) / 0.53) % 2 == 1
end
function MS.XT.arm()
    if MS.XT.bt or not MS.XT.on() then return end
    MS.XT.bt = mp.add_periodic_timer(0.1, function()
        if not (browser_active and search_active) then MS.XT.bt:kill(); MS.XT.bt, MS.XT.cv = nil, nil; return end
        local v = MS.XT.vis()
        if v ~= MS.XT.cv then MS.XT.cv = v; render() end
    end)
end
-- "before▏after", escaped, with the caret (see-through while it blinks off) and the fading last letter
function MS.XT.field(before, after)
    if not MS.XT.on() then return U.ass_escape(before) .. "▏" .. U.ass_escape(after) end
    MS.XT.arm()
    local vis = MS.XT.vis()
    MS.XT.cv = vis
    local head, last = before, ""
    local dt = mp.get_time() - (MS.XT.t or 0)
    if MS.XT.ins and dt < MS.XT.FADE and before ~= "" and MS.XT.still() then
        local i = #before
        while i > 1 and before:byte(i) >= 128 and before:byte(i) < 192 do i = i - 1 end
        head, last = before:sub(1, i - 1), before:sub(i)
    end
    local out = U.ass_escape(head)
    if last ~= "" then
        local k = 1 - (1 - dt / MS.XT.FADE) ^ 3
        out = out .. "{\\1a" .. U.ass_alpha(100 * k) .. "}" .. U.ass_escape(last) .. "{\\1a&H00&}"
    end
    return out .. (vis and "▏" or "{\\1a&HFF&}▏{\\1a&H00&}") .. U.ass_escape(after)
end

-- Renders the search UI for one panel's second header line.
-- big=true  -> actively typing: large font + accent pill, unmistakable.
-- big=false -> confirmed filter: small warn-colored chip, unobtrusive.
--
-- NOTE: the icon is deliberately kept at NORMAL weight (\b0) even inside the
-- otherwise-bold "big" box. Forcing \b1 on an emoji glyph makes libass hunt
-- for a bold variant of the UI font, which usually doesn't have that emoji,
-- so it silently falls back to some other glyph/font (this was the "wrong
-- search icon" bug).
local function draw_search_indicator(chunks, rect, y, match_count, big)
    local clip = D.clip_tag(rect.x1, rect.y1, rect.x2, rect.y1 + layout.panel_header_h)
    if big then
        local fs_big = layout.fs_big
        local pad = 8
        table.insert(chunks, D.ev_rect(rect.x1 + pad, y - fs_big * 0.72, rect.x2 - pad, y + fs_big * 0.5,
            THEME.accent, 16, THEME.accent, 55, 1, o.corner_radius_small))
        local c = MS.scur_get and MS.scur_get() or #search_query
        local text = string.format("{\\b0}%s{\\b1} %s", ICONS.search, MS.XT.field(search_query:sub(1, c), search_query:sub(c + 1)))
        table.insert(chunks, D.ev_text(rect.x1 + pad + 10, y, 4,
            string.format("%s\\b1\\fs%d\\c%s", clip, fs_big, U.ass_color(THEME.accent)), text))
        table.insert(chunks, D.ev_text(rect.x2 - pad - 10, y, 6,
            string.format("%s\\fs%d\\c%s", clip, layout.fs - 4, U.ass_color(THEME.text_muted)),
            string.format("%d match%s", match_count, (match_count == 1) and "" or "es")))
    else
        table.insert(chunks, D.ev_text(rect.x1 + 12, y, 4,
            string.format("%s\\fs%d\\c%s", clip, layout.fs - 6, U.ass_color(THEME.warn)),
            string.format('%s "%s" - %d match%s (Esc to clear)', ICONS.search, U.ass_escape(search_query),
                match_count, (match_count == 1) and "" or "es")))
    end
end

-- ============================================================
-- LAYOUT
-- ============================================================
local function visible_rows_for(rect, panel_header_h, row_h)
    local body = rect.y2 - rect.y1 - panel_header_h - 8
    return math.max(1, math.floor(body / row_h))
end

local function compute_layout()
    local w, h = U.canvas_size()
    overlay.res_x = w
    overlay.res_y = h

    local pad, gap = 12, 10
    local header_h = 52
    local footer_h = 58
    local inner_x1, inner_x2 = pad, w - pad
    local inner_w = inner_x2 - inner_x1
    local inner_y1 = header_h + 8
    local inner_y2 = h - footer_h - 8

    local usable = inner_w - gap
    local list_x2, poster = inner_x2, nil
    if o.poster_column and w >= 900 then
        local pwid = math.max(170, math.min(300, math.floor(w * (tonumber(o.poster_column_pct) or 17) / 100)))
        list_x2 = inner_x2 - pwid - gap
        poster = { x1 = list_x2 + gap, y1 = inner_y1, x2 = inner_x2, y2 = inner_y2 }
        usable = usable - pwid - gap
    end
    local min_w = math.max(170, math.floor(usable * 0.18))
    local sb_w = math.floor(usable * sidebar_frac)
    sb_w = math.max(min_w, math.min(usable - min_w, sb_w))

    local fs = o.font_size
    local fs_big = fs + (tonumber(o.search_font_boost) or 8)

    -- Baseline (non-search) header height: unchanged from previous versions.
    local base_header_h = math.max(50, math.floor(fs * 2.6))

    -- Default sub-line (breadcrumb / file-count / confirmed-chip) position.
    local sub_line_y = 36
    local panel_header_h = base_header_h

    -- While ACTIVELY TYPING, the search pill uses fs_big (bigger font) and
    -- must be pushed below the title text with enough clearance, otherwise it
    -- visually overlaps the title above it and the row list below it (this
    -- was the "search mixing with names" bug). Only grows the header for the
    -- duration of active typing - confirmed/quiet chip mode is unaffected.
    if search_active then
        local title_bottom = 16 + fs * 0.55
        local sub_h = fs_big * 1.35
        local sub_gap = 10
        sub_line_y = title_bottom + sub_gap + sub_h / 2
        panel_header_h = math.max(base_header_h, math.floor(sub_line_y + sub_h / 2 + 10))
    end

    return {
        w = w, h = h,
        header_h = header_h, footer_h = footer_h,
        poster = poster,
        sidebar = { x1 = inner_x1, y1 = inner_y1, x2 = inner_x1 + sb_w, y2 = inner_y2 },
        list    = { x1 = inner_x1 + sb_w + gap, y1 = inner_y1, x2 = list_x2, y2 = inner_y2 },
        row_h = math.max(28, math.floor(fs * 1.95)),
        panel_header_h = panel_header_h,
        sub_line_y = math.floor(sub_line_y),
        fs_big = fs_big,
        fs = fs,
        scroll_info = {},   -- panel -> { n, vis, max_scroll }     (filled by keep_selection_in_view)
        scrollbars = {},    -- panel -> track / thumb / hit rectangles (filled by draw_scrollbar)
    }
end

local function keep_selection_in_view()
    if not layout then return end
    for _, panel in ipairs({ "sidebar", "episodes" }) do
        local items = get_panel_items(panel)
        local rect = (panel == "sidebar") and layout.sidebar or layout.list
        local vis = visible_rows_for(rect, layout.panel_header_h, layout.row_h)
        local sel = (panel == "sidebar") and sidebar_selected_index or selected_episode
        local scroll = (panel == "sidebar") and scroll_offset_folders or scroll_offset_episodes
        local n = #items
        if n < 1 then
            sel, scroll = 1, 0
            layout.scroll_info[panel] = { n = 0, vis = vis, max_scroll = 0 }
        else
            sel = math.max(1, math.min(n, sel))
            local max_scroll = math.max(0, n - vis)
            -- After wheel / scrollbar use the view is "free": it stays where the user put it and
            -- only snaps back to the selection once the selection moves (see move_selection).
            if not free_scroll[panel] then
                local margin = (n > vis) and 1 or 0
                if sel < scroll + 1 + margin then scroll = sel - 1 - margin end
                if sel > scroll + vis - margin then scroll = sel - vis + margin end
            end
            scroll = math.max(0, math.min(max_scroll, scroll))
            layout.scroll_info[panel] = { n = n, vis = vis, max_scroll = max_scroll }
        end
        if panel == "sidebar" then
            sidebar_selected_index, scroll_offset_folders = sel, scroll
        else
            selected_episode, scroll_offset_episodes = sel, scroll
        end
    end
end

-- ============================================================
-- ROW DRAWING
-- ============================================================
local function draw_scrollbar(chunks, rect, header_h, scroll, n_items, n_vis, panel)
    if n_items <= n_vis then return end
    local x2 = rect.x2 - 5
    local x1 = x2 - 4
    local y1 = rect.y1 + header_h + 4
    local y2 = rect.y2 - 6
    local track_h = y2 - y1
    if track_h < 10 then return end
    local thumb_h = math.max(16, track_h * n_vis / n_items)
    local max_scroll = n_items - n_vis
    local thumb_y = y1 + (track_h - thumb_h) * (scroll / math.max(1, max_scroll))
    local dragging = MS.drag and MS.drag.panel == panel
    local hot = dragging or (MS.hover_sb == panel)
    local bx1 = hot and (x1 - 2) or x1
    table.insert(chunks, D.ev_rect(bx1, y1, x2, y2, THEME.track, 100, nil, 0, 0, o.corner_radius_small))
    table.insert(chunks, D.ev_rect(bx1, thumb_y, x2, thumb_y + thumb_h, THEME.accent, hot and 100 or 80, nil, 0, 0, o.corner_radius_small))
    layout.scrollbars[panel] = {
        hx1 = x2 - o.scrollbar_hit_px, hx2 = rect.x2, y1 = y1, y2 = y2,
        ty1 = thumb_y, ty2 = thumb_y + thumb_h, track_h = track_h, thumb_h = thumb_h,
        max_scroll = max_scroll, n = n_items, vis = n_vis,
    }
end

-- ============================================================
-- CLEAN TITLES (clean_titles)
-- ============================================================
-- "The.Gentlemen.S02E03.2160p.NF.WEB-DL.DV.HDR.Atmos.H.265-GRP.mkv"  ->  "S02E03" + [4K] [HDR] [DV] [ATMOS]
-- Everything is wrapped in pcall; if a name can't be parsed the raw name is shown unchanged.
local CT = { cache = {}, count = 0 }

CT.TOKENS = {
    "2160p", "1080p", "1080i", "720p", "480p", "4k", "uhd", "bluray", "blu%-ray", "bdrip", "brrip",
    "web%-dl", "webdl", "webrip", "hdtv", "dvdrip", "remux", "x264", "x265", "h264", "h265", "hevc",
    "av1", "hdr", "dovi", "atmos", "dts", "ddp", "dd%+",
}

-- Characters some upload tools substitute for ones Windows forbids in file names ("Time?!" saved as U+F025),
-- plus the double-encoded form of the same ("ï€¥"). Turned back into the real character for display.
CT.SFM = { [0xF020] = '"', [0xF021] = "*", [0xF022] = ":", [0xF023] = "<", [0xF024] = ">", [0xF025] = "?",
    [0xF026] = "\\", [0xF027] = "|", [0xF028] = " ", [0xF029] = "." }
function CT.fix_chars(s)
    if not s or not s:find("[\195\239\234]") then return s end
    local function map(cp)
        local m = CT.SFM[cp]
        if m then return m end
        if cp >= 0xF030 and cp <= 0xF07F then return string.char(cp - 0xF000) end
        return nil
    end
    s = s:gsub("\239([\128\129])([\128-\191])", function(b2, b3)
        local cp = 0xF000 + (b2:byte() - 0x80) * 64 + (b3:byte() - 0x80)
        return map(cp) or ("\239" .. b2 .. b3)
    end)
    -- the same bytes read as Windows-1252 and saved again as UTF-8: "ï" "€" + (C2 xx)
    s = s:gsub("\195\175\226\130\172\194([\160-\191])", function(b3)
        return map(0xF000 + (b3:byte() - 0x80)) or ("\195\175\226\130\172\194" .. b3)
    end)
    s = s:gsub("\234\158\137", ":")                            -- U+A789 colon look-alike
    return s
end

-- words that end an episode title taken from a file name ("S02E01.You.Arent.E.Rank.Are.You.1080p.WEB")
CT.EP_STOP = {}
for w in ([[1080p 2160p 720p 480p 1080i 4k uhd web webdl web-dl webrip bluray blu-ray bdrip brrip bd hdtv dvdrip remux
    x264 x265 h264 h265 hevc avc av1 hdr hdr10 dv dovi atmos dts ddp dd aac flac opus multi dual dubbed subbed
    proper repack internal real vostfr nf amzn dsnp atvp hmax max hulu pcok cr crunchyroll hidive ita eng fre ger spa
    jpn kor 10bit 8bit hi10p complete]]):gmatch("%S+") do CT.EP_STOP[w] = true end

-- Episode title from the part of a file name that follows the episode token.
function CT.ep_title(rest)
    if not rest or rest == "" then return nil end
    rest = rest:gsub("^[%s%._%-:]+", "")
    if rest:find("^[eE]%d") or rest:find("^%-") then return nil end    -- "S01E01-E13" ranges
    if rest:find("^[%[%(]") then return nil end
    local words = {}
    for w in rest:gsub("[%._]", " "):gmatch("%S+") do
        local lw = w:lower():gsub("[%[%]%(%)]", "")
        if CT.EP_STOP[lw] or lw:find("^%d%d%d%d?p$") or w:find("^[%[%(]") then break end
        if lw:find("^%d%d%d%d$") and tonumber(lw) >= 1900 and tonumber(lw) <= 2099 then break end
        words[#words + 1] = w
        if #words >= 16 then break end
    end
    local t = table.concat(words, " "):gsub("%s*%-%s*$", "")
    t = t:gsub("^%-%s*", ""):gsub("%s+", " "):gsub("^%s+", ""):gsub("%s+$", "")
    if not t:find("%a%a") then return nil end
    return t
end

function CT.parse_raw(name)
    local base = CT.fix_chars(name)
    local ext = U.ext_of(base)
    if ext and (U.video_exts[ext:lower()] or U.audio_exts[ext:lower()]) then
        base = base:sub(1, #base - #ext - 1)
    end
    local lower = base:lower()

    -- season/episode token: must start a "word" (so "class01e02" doesn't match)
    local cut, se_label, ep_from = nil, nil, nil
    local init = 1
    while true do
        local a, b, s, e = lower:find("s(%d%d?)[%._%s]?e(%d%d%d?%d?)", init)
        if not a then break end
        if a == 1 or not lower:sub(a - 1, a - 1):match("%w") then
            se_label = string.format("S%02dE%02d", tonumber(s), tonumber(e))
            cut, ep_from = a - 1, b + 1
            break
        end
        init = a + 1
    end
    if not se_label then   -- "1x05"
        local a, b, s, e = lower:find("%f[%w](%d%d?)x(%d%d%d?)%f[%W]")
        if a and tonumber(s) < 60 then
            se_label = string.format("S%02dE%02d", tonumber(s), tonumber(e)); cut, ep_from = a - 1, b + 1
        end
    end
    if not se_label then   -- "Episode 001 Title", "Ep 10 - Title", "Episode.10"
        local a, b, e = lower:find("%f[%w]episode[%s%._%-]*(%d%d?%d?%d?)%f[%D]")
        if not a then a, b, e = lower:find("%f[%w]ep[%s%._%-]*(%d%d?%d?%d?)%f[%D]") end
        if a then se_label = string.format("E%02d", tonumber(e)); cut, ep_from = a - 1, b + 1 end
    end
    if not se_label then   -- anime style: "Show Name - 03 [1080p]" / "Show Name - 03 - Title"
        local a, b, e = lower:find("%s%-%s(%d%d%d?%d?)[%s%[%(%.]")
        if not a then a, b, e = lower:find("%s%-%s(%d%d%d?%d?)$") end
        if a then
            local v = tonumber(e)
            if not (v >= 1900 and v <= 2099 and #e == 4) and v ~= 1080 and v ~= 720 and v ~= 2160 then
                se_label = string.format("E%02d", v); cut, ep_from = a - 1, b
            end
        end
    end

    local year
    if not se_label then
        -- absolute numbering: "Show.2009.004.1080p.BD" / "Show - 004 [1080p]" -> E04. A bare 3-4 digit number counts only when
        -- a year came before it or a quality tag follows it, so "The.300.Spartans.1962" is left alone.
        local skipv = { [480] = true, [576] = true, [720] = true, [1080] = true, [1440] = true, [2160] = true, [4320] = true }
        local init3, year_seen, year_pos = 1, nil, nil
        while true do
            local a, _, n = lower:find("[%._%s%-%[%(](%d%d%d%d?)[%._%s%-%]%)]", init3)
            if not a then break end
            local v = tonumber(n)
            local sep, pc = lower:sub(a, a), lower:sub(a - 1, a - 1)
            if not (sep == "." and (pc == "h" or pc == "x")) and not skipv[v] then
                if #n == 4 and v >= 1900 and v <= 2099 then
                    if not year_seen then year_seen, year_pos = n, a end
                else
                    local nxt = lower:sub(a + #n + 1, a + #n + 14)
                    local qual = nxt:find("^[%[%(]?%d%d%d%d?p") or nxt:find("^[%[%(]?bd") or nxt:find("^[%[%(]?web")
                        or nxt:find("^[%[%(]?x26") or nxt:find("^[%[%(]?hevc") or nxt:find("^[%[%(]?blu") or nxt:find("^[%[%(]?dvd")
                    if year_seen or qual then
                        se_label = string.format("E%02d", v)
                        cut = (year_pos or a) - 1
                        year = year_seen
                        break
                    end
                end
            end
            init3 = a + 1
        end
    end
    if not cut then
        local init2 = 1
        while true do
            local a, _, y = lower:find("[%._%s%(%[](%d%d%d%d)[%._%s%)%]]", init2)
            if not a then break end
            if y:sub(1, 2) == "19" or y:sub(1, 2) == "20" then year = y; cut = a - 1; break end
            init2 = a + 1
        end
    end
    if not cut then
        local best
        for _, tok in ipairs(CT.TOKENS) do
            local a = lower:find("[%._%s%-%[%(]" .. tok)
            if a and (not best or a < best) then best = a end
        end
        if best then cut = best - 1 end
    end
    if not cut and not se_label then return false end

    local title = base:sub(1, cut or #base)
    title = title:gsub("^%b[]%s*", "")
    title = title:gsub("[%._]+", " "):gsub("%s+", " "):gsub("^[%s%-]+", ""):gsub("[%s%-%(%[]+$", "")
    if title == "" and not se_label then return false end
    local ep = ep_from and CT.ep_title(base:sub(ep_from)) or nil

    return {
        title = title, se = se_label, year = year, chips = CT.chips_for(lower), ep = ep, group = CT.file_group(base),
        label = se_label or (title .. (year and (" (" .. year .. ")") or "")),
    }
end

-- Release group of a FILE name: "...x265-VARYG" or "[SubsPlease] ..."
function CT.file_group(base)
    local g = base:match("%-([%w_]+)$")
    if g and #g >= 2 and #g <= 20 and not (CT.GROUP_BLOCK or {})[g:lower()] and not g:match("^%d+$") and not g:lower():match("^%d+p$")
       and not g:lower():match("^[ex]%d+$") and not g:lower():match("^s%d") then return g end
    local lead = base:match("^%[([^%]]+)%]")
    if lead and #lead >= 2 and #lead <= 24 and not lead:lower():match("^v%d+$") then return lead end
    return nil
end

-- Season and episode numbers in a name ("S01E02", "s1.e2", "1x02"): s, e - or nil. The token has to start a word
-- ("class01e02" is not an episode). The one parser for it; CT.parse keeps its own richer pass for the label.
function CT.sxe(name)
    local l = tostring(name or ""):lower()
    local init = 1
    while true do
        local a, _, s_, e_ = l:find("s(%d%d?)[%._%s]?e(%d%d%d?%d?)", init)
        if not a then break end
        if a == 1 or not l:sub(a - 1, a - 1):match("%w") then return tonumber(s_), tonumber(e_) end
        init = a + 1
    end
    local s_, e_ = l:match("%f[%w](%d%d?)x(%d%d%d?)%f[%W]")
    if s_ and tonumber(s_) < 60 then return tonumber(s_), tonumber(e_) end
    return nil
end
function CT.parse(name)
    local hit = CT.cache[name]
    if hit ~= nil then return hit end
    local ok, res = pcall(CT.parse_raw, name)
    if not ok then res = false end
    CT.count = CT.count + 1
    if CT.count > 30000 then CT.cache, CT.count = {}, 1 end      -- a few long shows' episode names fit
    CT.cache[name] = res
    return res
end
MS.ct_parse = CT.parse          -- for the download card (MS is older than CT)
MS.ct_sxe = CT.sxe

-- true when every parsed media file in the list shares one show title (then the title is redundant
-- on each row and only "S01E03" is shown)
function CT.uniform_title(items)
    local first, seen = nil, 0
    for _, it in ipairs(items) do
        if not it.is_dir and U.is_media(it.name) then
            local cp = CT.parse(it.name)
            if cp then
                local tl = cp.title:lower()
                if first == nil then first = tl elseif first ~= tl then return false end
                seen = seen + 1
                if seen >= 60 then break end
            end
        end
    end
    return true
end

-- ---- folder names: "MASHLE.MAGIC.AND.MUSCLES.S01.1080p.BluRay.REMUX.AVC.FLAC.2.0-NAN0" ----
--   -> title "Mashle Magic and Muscles", season "S01", chips {1080p, REMUX}, group "NAN0"
CT.GROUP_BLOCK = { dl = true, hd = true, rip = true, ma = true, hdr = true, dv = true, webdl = true, hevc = true,
    x264 = true, x265 = true, h264 = true, h265 = true, avc = true, aac = true, dts = true, ac3 = true, flac = true }
CT.SMALL_WORDS = { a = true, an = true, ["and"] = true, as = true, at = true, but = true, by = true, ["for"] = true,
    ["in"] = true, of = true, on = true, ["or"] = true, the = true, to = true, vs = true }

-- Only names that are ALL upper or ALL lower case get re-cased; mixed case is how the release was named.
function CT.titlecase(str)
    if str:find("%l") and str:find("%u") then return str end
    local out, first = {}, true
    for w in str:gmatch("%S+") do
        local lw = w:lower()
        if not first and CT.SMALL_WORDS[lw] then out[#out + 1] = lw
        else out[#out + 1] = lw:sub(1, 1):upper() .. lw:sub(2) end
        first = false
    end
    return table.concat(out, " ")
end

function CT.chips_for(lower)
    local chips = {}
    local function has(pat) return lower:find(pat) ~= nil end
    if has("2160p") or has("%f[%w]4k%f[%W]") or has("%f[%a]uhd%f[%A]") then chips[#chips + 1] = "4K"
    elseif has("1080[pi]") then chips[#chips + 1] = "1080p"
    elseif has("720p") then chips[#chips + 1] = "720p"
    elseif has("480p") then chips[#chips + 1] = "480p" end
    if has("hdr10%+") or has("hdr10plus") then chips[#chips + 1] = "HDR10+"
    elseif has("%f[%a]hdr%f[%A]") then chips[#chips + 1] = "HDR" end
    if has("%f[%a]dv%f[%A]") or has("dovi") or has("dolby[%._%s%-]?vision") then chips[#chips + 1] = "DV" end
    if has("atmos") then chips[#chips + 1] = "ATMOS" end
    if has("remux") then chips[#chips + 1] = "REMUX" end
    if has("dual[%._%s%-]?audio") then chips[#chips + 1] = "DUAL" end
    return chips
end

function CT.parse_folder_raw(name)
    local base = CT.fix_chars(name)
    local group
    local body = base
    for _ = 1, 4 do                                          -- leading tags: "[SubsPlease] Show", "[v2] Show"
        local lead = body:match("^%[([^%]]+)%]")
        if not lead then break end
        local ll = lead:lower()
        if not group and #lead >= 2 and #lead <= 24 and not ll:find("^v%d+$") and not ll:find("^%d+p$")
           and not ll:find("^%d+$") then group = lead end
        body = body:gsub("^%b[]%s*", "")
    end
    local alt                                                 -- "(Demon Slayer) Kimetsu no Yaiba ..."
    local pin, prest = body:match("^%((.-)%)%s*(.+)$")
    if pin and pin:find("%a%a") and not pin:find("^%d+$") then alt, body = pin, prest end
    body = body:gsub("^[Bb][Oo][Nn][Dd][%s%._]*50[%s%._%-]+", "")   -- "Bond 50 The Spy Who Loved Me"
    body = body:gsub("%s*%b[]%s*$", "")                       -- trailing [site]/[hash] tags
    body = body:gsub("\234\158\137", ":")                      -- U+A789 (a colon look-alike used in file names) -> ":"
    local g = body:match("%-([%w_]+)$")                       -- scene style: "...-GROUP"
    if g and not group and #g >= 2 and #g <= 20 and not CT.GROUP_BLOCK[g:lower()] and not g:match("^%d+$") then
        group = g
        body = body:sub(1, #body - #g - 1)
    end

    local lower = body:lower()
    local ls = lower .. "."
    local cut, season, year
    local function mark(a) if a and (not cut or a < cut) then cut = a end end

    local a, _, s1, s2 = ls:find("[%._%s%(%[%-]s(%d%d?)%-s?(%d%d?)[%._%s%)%]%-]")
    if a then season = string.format("S%02d-S%02d", tonumber(s1), tonumber(s2)); mark(a) end
    if not season then
        local b, _, sn, ep = ls:find("[%._%s%(%[%-]s(%d%d?)e(%d%d%d?)[%._%s%)%]%-]")
        if b then season = string.format("S%02dE%02d", tonumber(sn), tonumber(ep)); mark(b) end
    end
    if not season then
        local b, _, sn = ls:find("[%._%s%(%[%-]s(%d%d?)[%._%s%)%]%-]")
        if b then season = string.format("S%02d", tonumber(sn)); mark(b) end
    end
    if not season then
        local b, _, sn = ls:find("[%._%s%(%[%-]season[%._%s]*(%d%d?)[%._%s%)%]%-]")
        if b then season = string.format("S%02d", tonumber(sn)); mark(b) end
    end
    local ca = ls:find("[%._%s%(%[%-]complete[%._%s%)%]%-]")
    if ca then
        mark(ca)
        if not season then season = "Complete" end
    end
    local init = 1
    while true do
        local b, _, y = ls:find("[%._%s%(%[](%d%d%d%d)[%._%s%)%]]", init)
        if not b then break end
        if y:sub(1, 2) == "19" or y:sub(1, 2) == "20" then year = y; mark(b); break end
        init = b + 1
    end
    for _, tok in ipairs(CT.TOKENS) do
        mark(ls:find("[%._%s%-%[%(]" .. tok))
    end

    local br = ls:find("%s[%[%(]")                            -- "Show [001-135] (ANIMAX ...)": the first bracket ends the title
    if br then mark(br) end
    if not cut and not group then return false end
    local title = body:sub(1, (cut or (#body + 1)) - 1)
    title = title:gsub("[%._]+", " "):gsub("%s+", " ")
    title = title:gsub("^[%s%-]+", ""):gsub("[%s%-%(%[]+$", "")
    local anime_ep = title:match("%s%-%s(%d%d?%d?)$")         -- anime "Show - 12"
    if anime_ep then
        title = title:gsub("%s%-%s%d%d?%d?$", "")
        if not season then season = string.format("E%02d", tonumber(anime_ep)) end
    end
    title = CT.strip_tail(title)
    if title == "" then return false end

    return {
        title = CT.titlecase(title), season = season, year = year, group = group, alt = alt,
        chips = CT.chips_for(lower),
    }
end

-- Removes release-ish words from the END of a title: "Silo Season 1", "Bleach - Box 01", "Bleach USBD", "Naruto HD"...
function CT.strip_tail(t)
    for _ = 1, 8 do
        local old = t
        t = t:gsub("[%s%-:]+$", "")
        local l = t:lower()
        local function cut(pat)
            local a = l:find(pat)
            if not a then return end
            -- never down to nothing or a bare article: "The Collection" (2012) is a film's whole name
            local rest = t:sub(1, a - 1):lower():gsub("^[%s%p]+", ""):gsub("[%s%p]+$", "")
            if rest == "" or rest == "the" or rest == "a" or rest == "an" then return end
            t = t:sub(1, a - 1); l = t:lower()
        end
        cut("%s+seasons?%s*%d+.*$")
        cut("%s+box%s*%d+.*$")
        cut("%s+usbd$"); cut("%s+hd$"); cut("%s+tl$"); cut("%s+bd$"); cut("%s+remux$"); cut("%s+complete$"); cut("%s+collection$")
        -- "Pokemon Horizons Eng Dub", "Show English Subbed", "Show Dual Audio": the language of the release, not the title
        cut("%s+eng?l?i?s?h?%s+dub%a*$"); cut("%s+eng?l?i?s?h?%s+sub%a*$"); cut("%s+dual[%s%-]*audio$"); cut("%s+multi[%s%-]*subs?$")
        cut("%s+dubbed$"); cut("%s+subbed$")
        if t == old then break end
    end
    return t
end

CT.fcache, CT.fcount = {}, 0
-- "Pokemon Horizons Episode 1 to 6 [720p]" / "Show Ep 7-16": the episode range is not part of the title.
CT.EP_RANGE = { "^(.-)[%s%._%-]+[Ee]pisodes?[%s%._]*%d+[%s%._]*[Tt][Oo][%s%._]*%d+",
                "^(.-)[%s%._%-]+[Ee]pisodes?[%s%._]*%d+[%s%._]*[%-~]+[%s%._]*%d+",
                "^(.-)[%s%._%-]+[Ee][Pp][%s%._]*%d+[%s%._]*[%-~]+[%s%._]*%d+" }
function CT.strip_ep_range(name)
    for _, pat in ipairs(CT.EP_RANGE) do
        local s, e, b = name:find(pat)
        if s and #b >= 2 then return b .. name:sub(e + 1) end
    end
    return name
end

function CT.parse_folder(name)
    local hit = CT.fcache[name]
    if hit ~= nil then return hit end
    local ok, res = pcall(CT.parse_folder_raw, CT.strip_ep_range(name))
    if not ok then res = false end
    CT.fcount = CT.fcount + 1
    if CT.fcount > 10000 then CT.fcache, CT.fcount = {}, 1 end
    CT.fcache[name] = res
    return res
end

CT.COLORS = {
    ["4K"] = "accent", ["1080p"] = "muted", ["720p"] = "muted", ["480p"] = "muted",
    ["HDR"] = "warn", ["HDR10+"] = "warn", ["DV"] = "audio", ["ATMOS"] = "video",
    ["REMUX"] = "good", ["DUAL"] = "folder", ["NEXT"] = "accent",
}
function CT.chip_color(label)
    local k = CT.COLORS[label]
    if k == "accent" then return THEME.accent elseif k == "muted" then return THEME.text_muted
    elseif k == "warn" then return THEME.warn elseif k == "audio" then return THEME.audio
    elseif k == "video" then return THEME.video elseif k == "good" then return THEME.good
    elseif k == "folder" then return THEME.folder end
    return THEME.warn   -- resume-time chips
end

-- ============================================================
-- ROW DRAWING (continued)
-- ============================================================
local function draw_sidebar_rows(chunks, hitboxes, rect)
    local header_h = layout.panel_header_h
    local row_h = layout.row_h
    local fs = layout.fs
    local items = get_panel_items("sidebar")
    local selected_idx = sidebar_selected_index
    local scroll_off = scroll_offset_folders
    local vis = visible_rows_for(rect, header_h, row_h)
    local focused = (focus_panel == "sidebar")
    local tree_mode = not (search_scope == "sidebar" and search_query ~= "")

    local body_x1, body_y1 = rect.x1 + 1, rect.y1 + header_h
    local body_x2, body_y2 = rect.x2 - 1, rect.y2 - 1
    local clip = D.clip_tag(body_x1, body_y1, body_x2, body_y2)

    local last_idx = math.min(#items, scroll_off + vis)
    for i = scroll_off + 1, last_idx do
        local node = items[i]
        local row_y1 = body_y1 + (i - scroll_off - 1) * row_h
        local row_y2 = math.min(row_y1 + row_h, body_y2)
        local is_sel = focused and (i == selected_idx)
        local is_hov = (hover_panel == "sidebar" and hover_index == i and not is_sel)

        if is_sel then
            table.insert(chunks, D.ev_rect(rect.x1 + 2, row_y1 + 1, rect.x2 - 2, row_y2 - 1, THEME.accent, 18, nil, 0, 0, o.corner_radius_row))
            table.insert(chunks, D.ev_rect(rect.x1 + 2, row_y1 + 1, rect.x1 + 5, row_y2 - 1, THEME.accent, 100, nil, 0, 0, o.corner_radius_small))
        elseif is_hov then
            table.insert(chunks, D.ev_rect(rect.x1 + 2, row_y1 + 1, rect.x2 - 2, row_y2 - 1, "FFFFFF", 7, nil, 0, 0, o.corner_radius_row))
        end

        local icon, icon_col
        if node.virtual then
            icon, icon_col = "★", THEME.warn
        elseif node.loading then
            icon, icon_col = spinner_frames[spinner_idx], THEME.text_muted
        elseif node.loaded and #node.children == 0 then
            icon, icon_col = ICONS.folder_empty, THEME.text_dim
        elseif node.expanded then
            icon, icon_col = ICONS.folder_open, THEME.folder
        else
            icon, icon_col = ICONS.folder_closed, THEME.folder
        end

        local indent = tree_mode and (math.min(node.depth, o.max_indent_levels) * o.indent_px) or 0
        local arrow_x = rect.x1 + 14 + indent
        local name_x = arrow_x + (tree_mode and 18 or 0)
        local name_y = row_y1 + row_h / 2

        -- expand/collapse arrow: its own click target (toggles WITHOUT opening the folder)
        if tree_mode and not node.virtual and not (node.loaded and #node.children == 0) then
            table.insert(chunks, D.ev_text(arrow_x + 6, name_y, 5,
                string.format("%s\\fs%d\\c%s", clip, fs - 4, U.ass_color(is_sel and THEME.accent or THEME.text_muted)),
                node.expanded and "▾" or "▸"))
            table.insert(hitboxes, {
                panel = "sidebar", index = i, arrow = true,
                x1 = arrow_x - 6, y1 = row_y1, x2 = arrow_x + 20, y2 = row_y2,
            })
        end

        local name_col
        if is_sel then
            name_col = THEME.accent
        elseif node.virtual then
            name_col = THEME.warn
        elseif focused then
            name_col = THEME.text_primary
        else
            name_col = THEME.text_muted
        end

        local active_marker = ""
        if node.href == current_path then
            active_marker = string.format("{\\c%s}%s ", U.ass_color(THEME.accent), ICONS.active_marker)
        end

        local max_name_px = math.max(20, rect.x2 - name_x - 40)
        local display_name = U.fit_text(node.name, max_name_px, fs)
        local suffix = node.virtual and "" or "/"
        local count_txt = ""
        if node.virtual then
            count_txt = string.format("  {\\c%s}%d", U.ass_color(THEME.text_dim), #get_continue_list())
        end

        -- cleaned folder name: Title  S01  1080p REMUX  GROUP   (extras are dropped, last first, if the row is narrow)
        local fp = (o.clean_titles and o.clean_folder_titles and not node.virtual) and CT.parse_folder(node.name) or nil
        if fp then
            local budget = max_name_px - 30 - (node.href == current_path and 16 or 0)
            local title_min = math.min(U.utf8_len(fp.title) * fs * 0.62, fs * 0.62 * 14)
            local used, extras = 0, {}
            local function add_extra(text, size, col)
                local w = (U.utf8_len(text) + 2) * size * 0.58
                if budget - used - w >= title_min then
                    used = used + w
                    extras[#extras + 1] = string.format("  {\\fs%d\\c%s}%s", size, U.ass_color(col), U.ass_escape(text))
                end
            end
            if fp.season then add_extra(fp.season, fs - 4, THEME.text_muted) end
            if fp.group then add_extra(fp.group, fs - 6, THEME.audio) end
            if o.clean_titles_chips then
                local chip_txt = {}
                for _, c in ipairs(fp.chips) do chip_txt[#chip_txt + 1] = c end
                for k = 1, math.min(#chip_txt, 3) do add_extra(chip_txt[k], fs - 8, CT.chip_color(chip_txt[k])) end
            end
            display_name = U.fit_text(fp.title, budget - used, fs)
            suffix = table.concat(extras)
        end

        local line = string.format("%s{\\c%s}%s  {\\c%s}%s%s%s",
            active_marker, U.ass_color(icon_col), icon, U.ass_color(name_col), U.ass_escape(display_name), suffix, count_txt)

        table.insert(chunks, D.ev_text(name_x, name_y, 4, string.format("%s\\fs%d", clip, fs), line))

        table.insert(hitboxes, {
            panel = "sidebar", index = i,
            x1 = rect.x1, y1 = row_y1, x2 = rect.x2, y2 = row_y2,
        })
    end

    if #items == 0 then
        local msg2 = (search_scope == "sidebar" and search_query ~= "") and "(no matches)" or "(no subfolders)"
        table.insert(chunks, D.ev_text(rect.x1 + 14, rect.y1 + header_h + 22, 4,
            string.format("\\i1\\fs%d\\c%s", fs - 4, U.ass_color(THEME.text_dim)), msg2))
    end

    draw_scrollbar(chunks, rect, header_h, scroll_off, #items, vis, "sidebar")
    if last_idx < #items then
        table.insert(chunks, D.ev_text((rect.x1 + rect.x2) / 2, rect.y2 - 10, 5,
            string.format("\\fs%d\\c%s", fs - 8, U.ass_color(THEME.accent)), "▼"))
    end
end

local function draw_episode_rows(chunks, hitboxes, rect)
    local header_h = layout.panel_header_h
    local row_h = layout.row_h
    local fs = layout.fs
    local items = get_panel_items("episodes")
    local selected_idx = selected_episode
    local scroll_off = scroll_offset_episodes
    local vis = visible_rows_for(rect, header_h, row_h)
    local focused = (focus_panel == "episodes")
    local is_global = (search_scope == "global")

    local body_x1, body_y1 = rect.x1 + 1, rect.y1 + header_h
    local body_x2, body_y2 = rect.x2 - 1, rect.y2 - 1
    local clip = D.clip_tag(body_x1, body_y1, body_x2, body_y2)

    local clean = o.clean_titles and not is_global
    local uniform = clean and CT.uniform_title(items)
    local cfs = math.max(10, fs - 8)

    -- draws one chip with its LEFT edge at x_left; returns the next chip's left edge
    local function draw_chip(x_left, cy, label, color)
        local w = U.utf8_len(label) * cfs * 0.62 + 12
        local x2 = x_left + w
        table.insert(chunks, D.ev_rect(x_left, cy - cfs * 0.78, x2, cy + cfs * 0.78, color, 16, color, 45, 1, o.corner_radius_small))
        table.insert(chunks, D.ev_text((x_left + x2) / 2, cy, 5,
            string.format("%s\\b1\\fs%d\\c%s", clip, cfs, U.ass_color(color)), U.ass_escape(label)))
        return x2 + 5
    end

    local last_idx = math.min(#items, scroll_off + vis)
    -- Column widths shared by every visible row, so labels, chips, sizes and episode names line up
    -- (they used to follow each name's estimated text width and drift from row to row).
    local COL = { label = 0, chips = 0, size = 0 }
    for i = scroll_off + 1, last_idx do
        local it = items[i]
        local cp = (clean and it and not it.is_dir and U.is_media(it.name)) and CT.parse(it.name) or nil
        if cp and cp.se then
            COL.label = math.max(COL.label, U.utf8_len(cp.se) * fs * 0.62)
            local cw = 0
            if o.clean_titles_chips then
                for _, c in ipairs(cp.chips) do cw = cw + U.utf8_len(c) * cfs * 0.62 + 12 + 5 end
            end
            if it.cw == "next" then cw = cw + 4 * cfs * 0.62 + 17 end
            COL.chips = math.max(COL.chips, cw)
            if it.size and it.size > 0 then COL.size = math.max(COL.size, U.utf8_len(U.fmt_bytes(it.size)) * (fs - 6) * 0.58 + 12) end
            COL.any = true
        end
    end
    for i = scroll_off + 1, last_idx do
        local item = items[i]
        local row_y1 = body_y1 + (i - scroll_off - 1) * row_h
        local row_y2 = math.min(row_y1 + row_h, body_y2)
        local is_sel = focused and (i == selected_idx)
        local is_hov = (hover_panel == "episodes" and hover_index == i and not is_sel)

        if is_sel then
            table.insert(chunks, D.ev_rect(rect.x1 + 2, row_y1 + 1, rect.x2 - 2, row_y2 - 1, THEME.accent, 18, nil, 0, 0, o.corner_radius_row))
            table.insert(chunks, D.ev_rect(rect.x1 + 2, row_y1 + 1, rect.x1 + 5, row_y2 - 1, THEME.accent, 100, nil, 0, 0, o.corner_radius_small))
        elseif is_hov then
            table.insert(chunks, D.ev_rect(rect.x1 + 2, row_y1 + 1, rect.x2 - 2, row_y2 - 1, "FFFFFF", 7, nil, 0, 0, o.corner_radius_row))
        end

        local icon, icon_col
        if item.is_dir then
            icon, icon_col = ICONS.folder_closed, THEME.folder
        elseif U.is_video(item.name) then
            icon, icon_col = ICONS.video, THEME.video
        elseif U.is_audio(item.name) then
            icon, icon_col = ICONS.audio, THEME.audio
        else
            icon, icon_col = ICONS.file, THEME.file
        end

        local name_x = rect.x1 + 14
        local name_y = row_y1 + row_h / 2
        local name_col = is_sel and THEME.accent or (focused and THEME.text_primary or THEME.text_muted)
        local scroll_pad = (#items > vis) and 10 or 0

        -- right-hand text: path (search results / continue list) or size
        local right_text, right_col = nil, THEME.text_muted
        local hist = watch_history[item.href]
        local use_right_status = o.show_status_text and not is_global and not item.cw and not item.is_dir
        if use_right_status then
            if watched_set[item.href] then
                right_text, right_col = ICONS.watched .. " " .. tostring(o.watched_label or "Watched"), THEME.good
            elseif hist and hist.pos and hist.duration and hist.duration > 0 then
                local pct = math.floor(math.min(1, hist.pos / hist.duration) * 100)
                right_text, right_col = string.format("%s %d%% - %s left", ICONS.watching, pct,
                    U.fmt_time(math.max(0, hist.duration - hist.pos))), THEME.warn
            end
        end
        if is_global then
            right_text = U.fit_text(U.percent_decode(item.dirpath or ""):gsub("^/", ""), (rect.x2 - rect.x1) * 0.34, fs - 6)
            if right_text == "" then right_text = "/" end
        elseif item.cw then
            right_text = U.fit_text(U.basename(item.dirpath or ""), (rect.x2 - rect.x1) * 0.30, fs - 6)
        end
        local right_w = right_text and (U.utf8_len(right_text) * (fs - 6) * 0.55 + 22) or 18
        right_w = right_w + scroll_pad

        -- clean title + chips
        local cp = (clean and not item.is_dir and U.is_media(item.name)) and CT.parse(item.name) or nil
        local shown_name, name_suffix = CT.fix_chars(item.name), ""
        local chip_labels = {}
        if cp then
            if cp.se then
                shown_name = cp.se
                if not uniform and cp.title ~= "" then
                    name_suffix = string.format("  {\\fs%d\\c%s}%s", fs - 4, U.ass_color(THEME.text_muted), U.ass_escape(cp.title))
                end
            else
                shown_name = cp.label
            end
            if o.clean_titles_chips then
                for _, c in ipairs(cp.chips) do chip_labels[#chip_labels + 1] = c end
            end
        end
        if item.cw == "next" then table.insert(chip_labels, 1, "NEXT") end
        if item.cw == "resume" and hist and hist.pos then table.insert(chip_labels, 1, U.fmt_time(hist.pos)) end

        local columns = cp and cp.se and COL.any
        if columns then
            -- E01 | chips | size | episode name (title first when the folder mixes shows)
            local tail = {}
            if not uniform and cp.title ~= "" then tail[#tail + 1] = cp.title end
            if cp.ep then tail[#tail + 1] = cp.ep end
            local tail_txt = table.concat(tail, "  ·  ")
            local x_label = name_x + 30
            local x_chips = x_label + COL.label + 14
            local x_size = x_chips + COL.chips
            local x_ep = x_size + COL.size + (COL.size > 0 and 10 or 0)
            local x_end = rect.x2 - right_w - 8
            local status_txt = ""
            if o.show_watched_status and not use_right_status then
                if watched_set[item.href] then status_txt = ICONS.watched
                elseif hist then status_txt = ICONS.watching end
            end
            table.insert(chunks, D.ev_text(name_x, name_y, 4, string.format("%s\\fs%d\\c%s", clip, fs, U.ass_color(icon_col)), icon))
            table.insert(chunks, D.ev_text(x_label, name_y, 4, string.format("%s\\fs%d\\c%s", clip, fs, U.ass_color(name_col)),
                U.ass_escape(shown_name)))
            local cx = x_chips
            if x_size <= x_end then
                for k = 1, #chip_labels do cx = draw_chip(cx, name_y, chip_labels[k], CT.chip_color(chip_labels[k])) end
            end
            if item.size and item.size > 0 and x_ep <= x_end + 10 then
                table.insert(chunks, D.ev_text(x_size, name_y, 4,
                    string.format("%s\\fs%d\\c%s", clip, fs - 6, U.ass_color(THEME.text_dim)), U.ass_escape(U.fmt_bytes(item.size))))
            end
            if x_end - x_ep > 30 and (tail_txt ~= "" or status_txt ~= "") then
                local rowclip = D.clip_tag(x_ep, body_y1, math.min(body_x2, x_end), body_y2)
                local fit = U.fit_text(tail_txt, x_end - x_ep - (status_txt ~= "" and 26 or 0), fs - 4)
                local st = (status_txt ~= "") and string.format("{\\c%s}  %s", U.ass_color(watched_set[item.href] and THEME.good or THEME.warn), status_txt) or ""
                table.insert(chunks, D.ev_text(x_ep, name_y, 4, string.format("%s\\fs%d\\c%s", rowclip, fs - 4,
                    U.ass_color(is_sel and THEME.accent or THEME.text_muted)), U.ass_escape(fit) .. st))
            end
            if right_text then
                table.insert(chunks, D.ev_text(rect.x2 - 16 - scroll_pad, name_y, 6,
                    string.format("%s\\fs%d\\c%s", clip, fs - 6, U.ass_color(right_col)), U.ass_escape(right_text)))
            end
        end

        local chips_w = 0
        for _, c in ipairs(chip_labels) do chips_w = chips_w + U.utf8_len(c) * cfs * 0.62 + 12 + 5 end
        local size_text = (not item.is_dir and item.size and item.size > 0) and U.fmt_bytes(item.size) or nil
        local size_w = size_text and (U.utf8_len(size_text) * (fs - 6) * 0.55 + 14) or 0

        local status = ""
        if o.show_watched_status and not use_right_status then
            if watched_set[item.href] then
                status = string.format("{\\c%s} %s", U.ass_color(THEME.good), ICONS.watched)
            elseif hist then
                status = string.format("{\\c%s} %s", U.ass_color(THEME.warn), ICONS.watching)
            end
        end

        local icon_w_est = 30
        local status_w_est = (status ~= "") and 26 or 0
        local suffix_w_est = (name_suffix ~= "") and (U.utf8_len(cp and cp.title or "") * (fs - 4) * 0.55 + 14) or 0
        -- Narrow panel? Give up the extras in priority order (size, then chips, then the status words)
        -- so the name always keeps a readable minimum.
        do
            local keep_px = math.min(U.utf8_len(shown_name) * fs * 0.62, fs * 0.62 * 12)
            local avail = rect.x2 - name_x - icon_w_est - status_w_est - suffix_w_est - 14
            if avail - right_w - chips_w - size_w < keep_px then size_text, size_w = nil, 0 end
            if avail - right_w - chips_w < keep_px then chip_labels, chips_w = {}, 0 end
            if avail - right_w < keep_px and use_right_status and right_text then
                right_text = right_text:match("^%S+")        -- just the tick / progress icon
                right_w = U.utf8_len(right_text) * (fs - 6) * 0.55 + 22 + scroll_pad
            end
        end
        local max_name_px = math.max(20, rect.x2 - name_x - right_w - chips_w - size_w - icon_w_est - status_w_est - suffix_w_est)
        local display_name = U.fit_text(shown_name, max_name_px, fs)
        if item.is_dir then display_name = display_name .. "/" end

        if not columns then
        local line = string.format("{\\c%s}%s  {\\c%s}%s%s%s",
            U.ass_color(icon_col), icon, U.ass_color(name_col), U.ass_escape(display_name), name_suffix, status)
        table.insert(chunks, D.ev_text(name_x, name_y, 4, string.format("%s\\fs%d", clip, fs), line))

        if right_text then
            table.insert(chunks, D.ev_text(rect.x2 - 16 - scroll_pad, name_y, 6,
                string.format("%s\\fs%d\\c%s", clip, fs - 6, U.ass_color(right_col)),
                U.ass_escape(right_text)))
        end

        -- chips and size sit right after the name (estimated end of the text), not at the row's edge
        local cx = name_x + icon_w_est + U.utf8_len(display_name) * fs * 0.58 + suffix_w_est + status_w_est + 8
        local limit = rect.x2 - right_w - 4
        for k = 1, #chip_labels do
            if cx > limit then break end
            cx = draw_chip(cx, name_y, chip_labels[k], CT.chip_color(chip_labels[k]))
        end
        if size_text and cx + size_w <= limit + 8 then
            table.insert(chunks, D.ev_text(cx + 2, name_y, 4,
                string.format("%s\\fs%d\\c%s", clip, fs - 6, U.ass_color(THEME.text_dim)), U.ass_escape(size_text)))
        end
        end

        if hist and hist.pos and hist.duration and hist.duration > 0 and not item.is_dir then
            local pct = math.min(1, hist.pos / hist.duration)
            local bx1, bx2 = name_x, rect.x2 - 14
            local by1, by2 = row_y2 - 4, row_y2 - 2
            table.insert(chunks, D.ev_rect(bx1, by1, bx2, by2, THEME.track, 100, nil, 0, 0, o.corner_radius_small))
            table.insert(chunks, D.ev_rect(bx1, by1, bx1 + (bx2 - bx1) * pct, by2, THEME.accent, 100, nil, 0, 0, o.corner_radius_small))
        end

        table.insert(hitboxes, {
            panel = "episodes", index = i,
            x1 = rect.x1, y1 = row_y1, x2 = rect.x2, y2 = row_y2,
        })
    end

    if #items == 0 then
        local msg2 = "(no files)"
        if is_global then
            msg2 = (search_query == "") and "Type to search the folders you have opened" or "(no matches in the folders you have opened)"
        elseif search_scope == "episodes" and search_query ~= "" then
            msg2 = "(no matches)"
        elseif current_path == CW_HREF then
            msg2 = "Nothing to continue yet - watch something and it will show up here"
        elseif hide_watched and #file_entries > 0 then
            msg2 = "(everything here is watched - press H to show watched files)"
        end
        table.insert(chunks, D.ev_text(rect.x1 + 14, rect.y1 + header_h + 22, 4,
            string.format("\\i1\\fs%d\\c%s", fs - 4, U.ass_color(THEME.text_dim)), U.ass_escape(msg2)))
    end

    draw_scrollbar(chunks, rect, header_h, scroll_off, #items, vis, "episodes")
    if last_idx < #items then
        table.insert(chunks, D.ev_text((rect.x1 + rect.x2) / 2, rect.y2 - 10, 5,
            string.format("\\fs%d\\c%s", fs - 8, U.ass_color(THEME.accent)), "▼"))
    end
end

-- ============================================================
-- MAIN RENDER
-- ============================================================
-- ---------- debug overlay ('d') ----------
function U.table_count(tbl) local n = 0 for _ in pairs(tbl) do n = n + 1 end return n end

local function build_debug_lines()
    local L = {}
    local dirs, items = IDX.count_items()
    local cached = find_cached_dir(current_path)
    local rs = req_stats.last
    L[#L + 1] = "DEBUG  -  webdav-browser " .. SCRIPT_VERSION
    L[#L + 1] = "folder: " .. current_path
    L[#L + 1] = "listing: " .. (cached and (string.format("cached %s (%s)", U.fmt_age(cached.ts),
        cache_is_fresh(cached) and "fresh" or "stale")) or "not cached")
    L[#L + 1] = string.format("cache: %d folders, %d items, ttl %ds", dirs, items, o.cache_ttl)
    if rs then
        L[#L + 1] = "last request: " .. rs.path
        L[#L + 1] = string.format("   %d ms   HTTP %s   attempts %d   %s", rs.ms or 0, tostring(rs.code or "-"),
            rs.attempts or 1, U.fmt_age(rs.ts))
        if rs.err then L[#L + 1] = "   error: " .. rs.err end
    else
        L[#L + 1] = "last request: none yet"
    end
    L[#L + 1] = string.format("requests: %d total, %d failed, %d in flight", req_stats.total, req_stats.failures, req_stats.pending)
    L[#L + 1] = IDX.summary()
    L[#L + 1] = string.format("persistence: %s%s", persist_status.ok and "ok" or ("FAILED - " .. tostring(persist_status.err)),
        persist_status.last_save and (", saved " .. U.fmt_age(persist_status.last_save)) or ", not saved yet")
    L[#L + 1] = "data file: " .. tostring(persist_status.path)
    L[#L + 1] = string.format("auth: %s    blur: %s", o.scoped_auth and "scoped (file-local)" or "session-wide", MS.blur_state or "off")
    do
        local ok, chain = pcall(mp.get_property_native, "vf")
        local names = {}
        if ok and type(chain) == "table" then
            for _, f in ipairs(chain) do names[#names + 1] = (f.label and ("@" .. f.label) or tostring(f.name)) end
        end
        L[#L + 1] = "video filters: " .. (#names > 0 and table.concat(names, ", ") or "none")
    end
    do
        local fb = MS.fb
        if fb.active then
            L[#L + 1] = string.format("download-play: %s %s / %s%s", fb.playing and "playing" or "buffering",
                U.fmt_bytes(fb.size or 0), fb.total and U.fmt_bytes(fb.total) or "?", fb.done and "  (complete)" or "")
        end
    end
    L[#L + 1] = string.format("posters: %s, tmdb_key %s, status %s%s", o.poster_column and "on" or "OFF (poster_column=no)",
        o.tmdb_key ~= "" and (#o.tmdb_key .. " chars") or "MISSING", tostring(PS and PS.status or "?"), PS and PS.err and (" - " .. PS.err) or "")
    if MS.debug_extra then for _, ln in ipairs(MS.debug_extra()) do L[#L + 1] = ln end end
    L[#L + 1] = string.format("credentials: user '%s', password %d chars, curl via a config file (%s if it can't be written)", o.user, #o.pass, U.auth_mode())
    for _, n in ipairs(U.conf_notes or {}) do L[#L + 1] = "config: " .. n end
    L[#L + 1] = string.format("watch tracking: %d in progress, %d watched", U.table_count(watch_history), U.table_count(watched_set))
    local errs = U.table_count(listing_error)
    if errs > 0 then L[#L + 1] = string.format("folders with errors: %d", errs) end
    return L
end

-- ============================================================
-- POSTERS (poster edition only)
-- Looks the open folder's title up on TMDB, downloads the poster, converts it to raw BGRA and shows it
-- in a reserved column on the right with mpv's overlay-add. The bitmap is drawn ABOVE all text, so the
-- column is kept free of other UI and the picture is removed whenever something could cover it.
-- This product uses the TMDB API but is not endorsed or certified by TMDB.
-- ============================================================
PS = { ID = 63, gen = 0, status = "idle", info = nil, want = nil, shown = nil, timer = nil, idx = nil, dir_ok = false }

PS.PS1 = [[
param([string]$In, [string]$Out, [int]$W, [int]$H)
Add-Type -AssemblyName System.Drawing
$src = [System.Drawing.Image]::FromFile($In)
$fmt = [System.Drawing.Imaging.PixelFormat]::Format32bppPArgb
$bmp = New-Object System.Drawing.Bitmap($W, $H, $fmt)
$g = [System.Drawing.Graphics]::FromImage($bmp)
$g.InterpolationMode = [System.Drawing.Drawing2D.InterpolationMode]::HighQualityBicubic
$k = [Math]::Max($W / $src.Width, $H / $src.Height)
$cw = $W / $k; $ch = $H / $k
$from = New-Object System.Drawing.RectangleF((($src.Width - $cw) / 2), (($src.Height - $ch) / 2), $cw, $ch)
$g.DrawImage($src, (New-Object System.Drawing.RectangleF(0, 0, $W, $H)), $from, [System.Drawing.GraphicsUnit]::Pixel)
$g.Dispose(); $src.Dispose()
$rect = New-Object System.Drawing.Rectangle(0, 0, $W, $H)
$data = $bmp.LockBits($rect, [System.Drawing.Imaging.ImageLockMode]::ReadOnly, $fmt)
$bytes = New-Object byte[] ($data.Stride * $H)
[System.Runtime.InteropServices.Marshal]::Copy($data.Scan0, $bytes, 0, $bytes.Length)
$bmp.UnlockBits($data); $bmp.Dispose()
[System.IO.File]::WriteAllBytes($Out, $bytes)
]]

PS.GENERIC = { season = true, seasons = true, specials = true, special = true, extras = true, extra = true, subs = true, sample = true }

function PS.enabled()
    return o.poster_column and o.tmdb_key ~= ""
end

function PS.dir()
    if PS._dir then return PS._dir end
    local d = o.poster_cache_dir
    if d == "" then
        local base = data_dir()
        d = base and utils.join_path(base, "webdav_posters")
            or ((os.getenv("TEMP") or os.getenv("TMP") or os.getenv("TMPDIR") or "/tmp"):gsub("\\", "/") .. "/webdav_posters")
    end
    PS._dir = (d:gsub("\\", "/"):gsub("/+$", ""))
    return PS._dir
end

-- Creates the cache folder (mpv has no mkdir of its own).
function PS.mkdir()
    local d = PS.dir()
    if PS._made then return end
    -- already there: no process (a synchronous one stalls the page for a frame or several, on Windows longer)
    local fi = utils.file_info(d)
    if fi and fi.is_dir then PS._made = true; return end
    local is_win = package.config:sub(1, 1) == "\\"
    local args = is_win and { "cmd", "/c", "mkdir", (d:gsub("/", "\\")) } or { "mkdir", "-p", d }
    pcall(mp.command_native, { name = "subprocess", args = args, capture_stdout = true, capture_stderr = true, playback_only = false })
    PS._made = true
end

function PS.run(args, cb)
    mp.command_native_async({
        name = "subprocess", args = args, capture_stdout = true, capture_stderr = true, playback_only = false,
    }, function(success, res, err)
        if not success or not res then cb(nil, err or "could not start the program") return end
        cb(res, nil)
    end)
end

-- ---------- batched HTTP: many requests per curl process ----------
-- Starting a process is the slow part of a request on Windows. Independent requests (TMDB searches and details,
-- season data, images, Real-Debrid calls) are collected for a moment and handed to ONE curl as a config file; curl
-- reuses its connections and, when it is new enough (7.66+), runs them in parallel. Secrets (TMDB key, Real-Debrid
-- token) go into that config file (deleted afterwards) instead of the command line.
PS.H = { q = {}, flying = 0, n = 0, timer = nil, par = nil }
function PS.http_probe()
    if PS.H.par ~= nil or PS.H.probing then return end
    PS.H.probing = true
    PS.run({ o.curl_path, "--version" }, function(res)
        local v = res and res.status == 0 and tostring(res.stdout):match("^curl (%d+%.%d+)")
        local a, b = tostring(v or "0.0"):match("(%d+)%.(%d+)")
        PS.H.par = (tonumber(a) or 0) > 7 or ((tonumber(a) or 0) == 7 and (tonumber(b) or 0) >= 66)
        PS.H.cv = (tonumber(a) or 0) * 100 + (tonumber(b) or 0)
        if not res or res.status ~= 0 then
            PS.notice("curl", "curl could not be started - check curl_path in the conf")
        end
    end)
end

-- req = { url, headers = { "Name: value" | "@file" }, form = { k = v } (POST, url-encoded), out = file (download) }
-- cb(code, body) - code 0 = no answer; body is nil for downloads
function PS.http(req, cb)
    PS.http_probe()
    local urgent = req.urgent
    if urgent == nil then urgent = PS.U_ctx end
    if urgent == nil and PS.pri_fn then urgent = PS.pri_fn() end
    local it = { req = req, cb = cb, urgent = urgent and true or false, img = req.out ~= nil }
    local q = PS.H.q
    if it.urgent then
        -- in front of everything that can wait (after the other urgent ones)
        local at = #q + 1
        for i, x in ipairs(q) do if not x.urgent then at = i; break end end
        table.insert(q, at, it)
    else q[#q + 1] = it end
    if not PS.H.timer then PS.H.timer = mp.add_timeout(0.03, function() PS.H.timer = nil; PS.http_flush() end) end
end

function PS.cfg_q(s) return '"' .. tostring(s):gsub("\\", "/"):gsub('"', '\\"') .. '"' end

function PS.http_flush()
    local H = PS.H
    -- up to 3 curl processes; one more for what is on screen. A batch holds one kind (on-screen or not, pictures or
    -- data): its answers only come back when its slowest transfer is done
    while #H.q > 0 and (H.flying < 3 or (H.flying < 4 and H.q[1].urgent)) do
        local head = H.q[1]
        local cap = head.urgent and 4 or 12
        local batch = {}
        local i = 1
        while i <= #H.q and #batch < cap do
            local x = H.q[i]
            if x.urgent == head.urgent and x.img == head.img then batch[#batch + 1] = table.remove(H.q, i) else i = i + 1 end
        end
        H.n = H.n + 1
        local dir = PS.dir() .. "/http"
        local cfg = string.format("%s/batch_%d.cfg", dir, H.n % 64)
        local lines = {}
        for i, it in ipairs(batch) do
            local r = it.req
            -- downloads arrive under a temporary name and get their real one only when complete, so nothing ever
            -- reads (or converts) a half-written file
            it.out = r.out and string.format("%s.part%d_%d", r.out, H.n % 64, i) or string.format("%s/r_%d_%d.txt", dir, H.n % 64, i)
            if i > 1 then lines[#lines + 1] = "next" end
            lines[#lines + 1] = "url = " .. PS.cfg_q(r.url)
            lines[#lines + 1] = "output = " .. PS.cfg_q(it.out)
            lines[#lines + 1] = "create-dirs"
            lines[#lines + 1] = "silent"
            lines[#lines + 1] = "show-error"
            lines[#lines + 1] = "max-time = " .. tostring(r.timeout or 20)
            if r.retry then lines[#lines + 1] = "retry = " .. tostring(r.retry) end
            if r.stall then lines[#lines + 1] = "speed-limit = 1024"; lines[#lines + 1] = "speed-time = " .. tostring(r.stall) end
            lines[#lines + 1] = "globoff"
            if r.follow then lines[#lines + 1] = "location" end
            lines[#lines + 1] = 'write-out = "%{http_code} %{filename_effective}\\n"'
            for _, h in ipairs(r.headers or {}) do lines[#lines + 1] = "header = " .. PS.cfg_q(h) end
            for k, v in pairs(r.form or {}) do lines[#lines + 1] = "data-urlencode = " .. PS.cfg_q(k .. "=" .. v) end
            if r.data_file then lines[#lines + 1] = "data-binary = " .. PS.cfg_q("@" .. r.data_file)       -- a file as the body
            elseif r.data then lines[#lines + 1] = "data-binary = " .. PS.cfg_q(r.data) end              -- a short text body
            if r.method then lines[#lines + 1] = "request = " .. PS.cfg_q(r.method) end
        end
        -- the folder for the config files is created when it is missing (a synchronous process per batch stalled the UI)
        local f = io.open(cfg, "wb")
        if not f then
            PS.mkdir()
            pcall(mp.command_native, { name = "subprocess", playback_only = false, capture_stdout = true,
                args = (package.config:sub(1, 1) == "\\") and { "cmd", "/c", "mkdir", (dir:gsub("/", "\\")) } or { "mkdir", "-p", dir } })
            f = io.open(cfg, "wb")
        end
        if not f then
            for _, it in ipairs(batch) do it.cb(0, nil) end
        else
            f:write(table.concat(lines, "\n") .. "\n"); f:close()
            H.flying = H.flying + 1
            local args = { o.curl_path, "--config", cfg }
            if H.par then table.insert(args, 2, "--parallel"); table.insert(args, 3, "--parallel-max"); table.insert(args, 4, "6") end
            PS.run(args, function(res)
                H.flying = H.flying - 1
                pcall(os.remove, cfg)
                local codes = {}
                for code, fname in tostring(res and res.stdout or ""):gmatch("(%d%d%d) ([^\r\n]*)") do codes[fname:gsub("\\", "/")] = tonumber(code) end
                if not res then PS.notice("curl", "curl could not be started - check curl_path in the conf") end
                for _, it in ipairs(batch) do
                    local code = codes[it.out:gsub("\\", "/")] or 0
                    local body = nil
                    if it.req.out then
                        local fin = it.req.out
                        local whole = code >= 200 and code < 300 and utils.file_info(it.out) ~= nil
                        if whole and fin:match("%.jpg$") and not PS.img_valid(it.out) then whole = false; code = 0 end
                        if whole then
                            pcall(os.remove, fin)            -- Windows: rename does not replace
                            if not os.rename(it.out, fin) then code = 0 end
                        end
                        pcall(os.remove, it.out)
                        PS.img_ok[it.out] = nil
                    else
                        local rf = io.open(it.out, "rb")
                        if rf then body = rf:read("*a"); rf:close() end
                        pcall(os.remove, it.out)
                    end
                    local ok, err = pcall(it.cb, code, body)
                    if not ok then msg.error("http callback: " .. tostring(err)) end
                end
                PS.http_flush()
            end)
        end
    end
end

-- On-screen notices for services that fail (shown in the top bar for a few seconds, once per problem).
PS.NT = { cur = nil, seen = {} }
function PS.notice(key, text)
    local NT = PS.NT
    if NT.seen[key] == text then return end
    NT.seen[key] = text
    NT.cur = { text = text, t = mp.get_time() }
    msg.warn(text)
    PS.kick()
    mp.add_timeout(10.1, function() PS.kick() end)
end
-- the service works again: a later failure is announced again
function PS.notice_ok(key)
    if PS.NT.seen[key] then PS.NT.seen[key] = nil end
end
function PS.notice_text()
    local c = PS.NT.cur
    if c and mp.get_time() - c.t < 10 then return c.text end
    return nil
end

-- TMDB auth as request headers / query
function PS.tmdb_req(path)
    local url = o.tmdb_api_base .. path
    local headers = {}
    if #o.tmdb_key > 40 then headers[1] = "Authorization: Bearer " .. o.tmdb_key
    else url = url .. (url:find("?", 1, true) and "&" or "?") .. "api_key=" .. o.tmdb_key end
    return { url = url, headers = headers, timeout = 15 }
end
function PS.tmdb_status(code)
    if code == 200 then PS.notice_ok("tmdb"); return nil end
    local why = (code == 401) and "TMDB rejected the key - check tmdb_key" or (code == 429) and "TMDB is rate-limiting - slowing down"
        or (code == 0) and "TMDB unreachable - check your connection" or ("TMDB HTTP " .. code)
    if code ~= 404 then PS.notice("tmdb", why) end
    return why
end

function PS.norm(s)
    local f = U.fold(s):lower()
    local a = f:gsub("[^%w]+", "")
    if #a >= 4 or not f:find("[\128-\255]") then return a end
    return (f:gsub("[%c%s%p]+", ""))         -- ASCII spaces and punctuation go, the other script's letters stay
end

-- Title (and year) of a folder NAME; nil for generic names ("Season 1", "Specials"...) so callers can look further up.
function PS.title_of_name(name)
    local fp = o.clean_titles and CT.parse_folder(name) or nil
    local title, year
    if fp and fp.title then
        title, year = fp.title, fp.year
    else
        title = CT.strip_ep_range(name):gsub("\234\158\137", ":"):gsub("[%._]+", " "):gsub("%[[^%]]*%]", " "):gsub("%s+", " "):gsub("^%s+", ""):gsub("%s+$", "")
        year = title:match("%((%d%d%d%d)%)")
        title = title:gsub("%(%d%d%d%d%)", ""):gsub("%s+$", "")
        title = CT.strip_tail(title)
    end
    local first = title:lower():match("^(%a+)")
    local generic = (first and PS.GENERIC[first] and #title < 14) or title:match("^[Ss]%d+$")
    if title == "" or #title < 2 or generic then return nil end
    return title, year and tostring(year) or ""
end

-- Title of a folder path: the folder itself, or the nearest parent with a real title. Never the library root.
function PS.title_of_path(p)
    for _ = 1, 4 do
        local pn = p:gsub("/+$", "")
        if pn == "" or pn == root_href:gsub("/+$", "") then return nil end
        local t, y = PS.title_of_name(U.basename(p))
        if t then return t, y end
        p = U.dirname(p)
    end
    return nil
end

-- Title (and year) to look up for the folder open in the files panel.
function PS.target()
    if search_scope == "global" or current_path == CW_HREF then return nil end
    return PS.title_of_path(current_path)
end

PS.IDX_VERSION = 11    -- bump when the matching rules change: older "not found" answers are dropped once
-- (from 9 on, what was found is kept: a new rule only has to look again at the titles that had no match)
-- 11 (26.10): box sets are TMDB collections, a weak match must carry the title's own words - so matches from before
-- that were a "closest result", or a box set matched as one film, are looked up again too
function PS.keep_match(k, v, ver)
    if (ver or 0) >= 11 then return true end
    -- a weak old match is looked up again, but kept until the new rules find something (it may have been right)
    if v.q == "(closest result)" then v.recheck = true end
    return true
end
-- index.json and episodes.json are journaled (see U.jl_sync): a lookup appends one line instead of rewriting the file.
function PS.load_index()
    if PS.idx then return end
    local path = PS.dir() .. "/index.json"
    PS.idx = { __v = PS.IDX_VERSION }
    PS.idxj = { sig = {}, lines = 0 }
    local data = try_load_json(path)
    if type(data) == "table" and data.__v == PS.IDX_VERSION then
        PS.idx = U.plain(data)
        PS.idxj.lines = U.jl_apply(path, PS.idx)
    elseif type(data) == "table" and (tonumber(data.__v) or 0) >= 9 then
        local old = U.plain(data)
        U.jl_apply(path, old)
        for k, v in pairs(old) do
            if k ~= "__v" and type(v) == "table" and not v.none and PS.keep_match(k, v, tonumber(data.__v)) then PS.idx[k] = v end
        end
        pcall(os.remove, path .. ".log")
    else
        pcall(os.remove, path .. ".log")          -- an older matching version: its log is void too
    end
    for k, v in pairs(PS.idx) do PS.idxj.sig[k] = U.jl_sig(v) end
    if type(data) ~= "table" or data.__v ~= PS.IDX_VERSION then PS.idxj.lines = 1e9 end     -- an older file: rewritten once
end
-- entry: an index entry that was changed in place (details added) - marks it for the journal
function PS.save_index(entry)
    if type(entry) == "table" then entry._t = (entry._t or 0) + 1 end
    if PS.idx_timer then return end
    PS.idx_timer = mp.add_timeout(0.5, function() PS.idx_timer = nil; PS.flush_index() end)
end
function PS.flush_index()
    if not PS.idx then return end
    local path = PS.dir() .. "/index.json"
    local ok
    if PS.idxj.lines < U.JL_MAX and utils.file_info(path) then ok = U.jl_sync(PS.idxj, path, PS.idx) end
    if not ok then PS.mkdir(); U.jl_compact(PS.idxj, path, PS.idx, PS.idx) end
end

-- Romaji / alternative names TMDB does not find on its own -> what to search for instead (s = season the folder holds).
PS.ALIASES = {
    { "bokunoheroacademia", "My Hero Academia" }, { "bokunohero", "My Hero Academia" },
    { "shingekinokyojin", "Attack on Titan" }, { "kimetsunoyaiba", "Demon Slayer: Kimetsu no Yaiba" },
    { "sousounofrieren", "Frieren: Beyond Journey's End" }, { "kaguyasamawakokurasetai", "Kaguya-sama: Love Is War" },
    { "yakusokunoneverland", "The Promised Neverland" }, { "tenseishitaraslimedattaken", "That Time I Got Reincarnated as a Slime" },
    { "oredakelevelupnaken", "Solo Leveling" }, { "kusuriyanohitorigoto", "The Apothecary Diaries" },
    { "bokunokokoronoyabaiyatsu", "The Dangers in My Heart" }, { "shigatsuwakiminouso", "Your Lie in April" },
    { "kiminonawa", "Your Name." }, { "sentochihironokamikakushi", "Spirited Away" },
    { "dungeonmeshi", "Delicious in Dungeon" }, { "kaijuu8gou", "Kaiju No. 8" }, { "kaiju8gou", "Kaiju No. 8" },
    { "ookamitokoushinryou", "Spice and Wolf" }, { "honzukinogekokujou", "Ascendance of a Bookworm" },
    { "tatenoyuushanonariagari", "The Rising of the Shield Hero" }, { "konosubarashiisekainishukufukuwo", "KonoSuba: God's Blessing on This Wonderful World!" },
    { "rezerokarahajimeruisekaiseikatsu", "Re:ZERO -Starting Life in Another World-" }, { "haganenorenkinjutsushi", "Fullmetal Alchemist: Brotherhood" },
    { "mahoushoujomadokamagica", "Puella Magi Madoka Magica" }, { "seishunbutayarou", "Rascal Does Not Dream of Bunny Girl Senpai" },
    { "kanojookarishimasu", "Rent-a-Girlfriend" }, { "bocchitherock", "Bocchi the Rock!" },
    { "bleachsennenkessenhen", "Bleach", 17 }, { "bleachthousandyearbloodwar", "Bleach", 17 },
}
-- poster_overrides = "boku no hero=tv:65930; sennen kessen=tv:30984:17; some film=movie:603"
function PS.overrides()
    local src = tostring(o.poster_overrides or "")
    if PS.ov_src == src then return PS.ov end
    PS.ov_src, PS.ov = src, {}
    for part in src:gmatch("[^;|]+") do
        local text, kind, id, s = part:match("^%s*(.-)%s*=%s*(%a+)%s*:%s*(%d+)%s*:?%s*[Ss]?(%d*)%s*$")
        if text and text ~= "" and (kind == "tv" or kind == "movie") then
            PS.ov[#PS.ov + 1] = { n = PS.norm(text), kind = kind, id = id, s = tonumber(s) }
        end
    end
    return PS.ov
end
function PS.override_for(raw, title)
    local a, b = PS.norm(raw or ""), PS.norm(title or "")
    for _, ov in ipairs(PS.overrides()) do
        if ov.n ~= "" and (a:find(ov.n, 1, true) or b:find(ov.n, 1, true)) then return ov end
    end
    return nil
end
function PS.alias_for(raw, title)
    local cands = { PS.norm(title or "") }
    local fp = raw and CT.parse_folder(raw)
    if fp and fp.title then cands[#cands + 1] = PS.norm(fp.title) end
    for _, n in ipairs(cands) do
        for _, al in ipairs(PS.ALIASES) do
            if n:sub(1, #al[1]) == al[1] then return al end
        end
    end
    return nil
end
-- Looks like anime? (fansub tags, absolute numbers, dual audio...) - then TMDB's Animation results win ties.
function PS.animeish(raw)
    local l = tostring(raw or ""):lower()
    return l:find("^%[") or l:find("dual[%s%._%-]?audio") or l:find("%[dual%]") or l:find("raws") or l:find("subs")
        or l:find("%(%d%d%d?%d?%-%d%d%d?%d?%)") or l:find("%[%d%d%d?%-%d%d%d?%]") or l:find("opus") or l:find("hi10")
end
-- A name for comparing: "&" reads as "and" ("Mr. & Mrs. Smith" is the folder "Mr and Mrs Smith").
function PS.pnorm(s)
    return PS.norm((tostring(s or ""):gsub("&", " and ")))
end
-- Share of words two names have in common, the smaller of the two directions, 0..1.
function PS.overlap2(a, b)
    local wa, wb, na, nb, hit = {}, {}, 0, 0, 0
    for w in U.fold(a):lower():gsub("&", " and "):gsub("[^%w%s]", " "):gmatch("%S+") do if not wa[w] then wa[w] = true; na = na + 1 end end
    for w in U.fold(b):lower():gsub("&", " and "):gsub("[^%w%s]", " "):gmatch("%S+") do if not wb[w] then wb[w] = true; nb = nb + 1 end end
    if na == 0 or nb == 0 then return 0 end
    for w in pairs(wa) do if wb[w] then hit = hit + 1 end end
    return math.min(hit / na, hit / nb)
end
-- Share of words two names have in common (either direction), 0..1.
function PS.overlap(a, b)
    local function words(s)
        local t, n = {}, 0
        for w in U.fold(s):lower():gsub("&", " and "):gsub("[^%w%s]", " "):gmatch("%S+") do if not t[w] then t[w] = true; n = n + 1 end end
        return t, n
    end
    local wa, na = words(a)
    local wb, nb = words(b)
    if na == 0 or nb == 0 then return 0 end
    local hit = 0
    for w in pairs(wa) do if wb[w] then hit = hit + 1 end end
    return math.max(hit / na, hit / nb)
end

-- A weak match (the closest result, a shortened query) must carry the folder title's own words: "Mr and Mrs Smith"
-- shares "Mr", "and", "Mrs" with "Mr & Mrs Bachelor", but not "Smith". One word may be missing from a long title.
PS.STOPW = { the = true, a = true, an = true, ["and"] = true, of = true, ["in"] = true, on = true, at = true, to = true,
    ["for"] = true, with = true, from = true, by = true, mr = true, mrs = true, ms = true, dr = true, vs = true, de = true,
    la = true, le = true, el = true, les = true, der = true, die = true, das = true, no = true, part = true, movie = true, film = true }
PS.ROMAN = { ii = "2", iii = "3", iv = "4", v = "5", vi = "6", vii = "7", viii = "8", ix = "9", x = "10" }
function PS.key_words_ok(r, full)
    if not full or full == "" then return true end
    local have, joined = {}, {}
    for _, nm in ipairs({ r.name or r.title or "", r.original_name or r.original_title or "" }) do
        for w in U.fold(nm):lower():gsub("&", " and "):gsub("[^%w%s]", " "):gmatch("%S+") do have[PS.ROMAN[w] or w] = true end
        joined[#joined + 1] = PS.pnorm(nm)
    end
    local jn = table.concat(joined, "|")
    local n, miss = 0, 0
    for w in U.fold(full):lower():gsub("&", " and "):gsub("[^%w%s]", " "):gmatch("%S+") do
        w = PS.ROMAN[w] or w
        if not PS.STOPW[w] and (#w >= 2 or w:match("^%d$")) then
            n = n + 1
            -- a word written together in the result ("spiderman", "oceans") counts too
            if not have[w] and not (#w >= 3 and jn:find(w, 1, true)) then miss = miss + 1 end
        end
    end
    return miss <= math.floor(n / 4)
end

-- ---------- anime lookup: AniList + the anime-lists id map (no keys needed) ----------
-- Romaji folder names ("Vanitas no Carte", "Sousou no Frieren") often find nothing - or the wrong thing - on TMDB.
-- 1. AniList (GraphQL, no key) is searched with the folder title; it knows romaji, English, native names and synonyms.
-- 2. The AniList id is mapped to the exact TMDB entry (and TMDB / TVDB season + episode offset) with Fribb's
--    anime-lists file, downloaded once and refreshed weekly (stored compact as anime_map.txt).
-- 3. Not in the map: TMDB is searched with AniList's English, then native title; the result must match the year
--    (+-1) and the type (film / series).
-- Only anime-looking folders and weak / failed TMDB matches get here; every answer is cached.
PS.AM = { map = nil, state = nil, waiters = {} }
PS.AL = { q = {}, busy = false, last = -10, cache = nil }
PS.logo_wait = {}               -- titles whose details request (which brings the logo) is on its way
PS.AL_FIELDS = "id format episodes seasonYear startDate{year} title{romaji english native} synonyms"
PS.AL_GQL = "query($s:String){Page(perPage:8){media(search:$s,type:ANIME,sort:SEARCH_MATCH){" .. PS.AL_FIELDS .. "}}}"

function PS.am_path() return PS.dir() .. "/anime_map.txt" end

function PS.am_load()
    if PS.AM.map then return end
    local f = io.open(PS.am_path(), "rb")
    if not f then return end
    local map = {}
    local v2 = false
    for line in f:lines() do
        if line == "#v2" then v2 = true
        else
            local aid, kind, id, s, tvs, off, kit, imdb = line:match("^(%d+)|(%a+)|(%d+)|(%d*)|(%d*)|(%d*)|?(%d*)|?([%w,]*)")
            if aid then map[aid] = { kind = kind, id = id, s = tonumber(s), tvs = tonumber(tvs), off = tonumber(off), kitsu = tonumber(kit), imdb = imdb ~= "" and imdb or nil } end
        end
    end
    f:close()
    PS.AM.map = map
    PS.AM.v2 = v2
    -- by TMDB id: the tracked-shows check and the anime parts used to scan the whole map for one title
    local by = {}
    for aid, e in pairs(map) do
        local k = (e.kind or "tv") .. ":" .. tostring(e.id)
        local l = by[k]
        if not l then l = {}; by[k] = l end
        e.aid = aid
        l[#l + 1] = e
    end
    PS.AM.by_tmdb = by
end
function PS.am_entries(kind, id)
    if not (PS.AM and PS.AM.map) then pcall(PS.am_load) end
    return (PS.AM.by_tmdb or {})[(kind or "tv") .. ":" .. tostring(tonumber(id) or id)] or {}
end

-- The big JSON (~6 MB) is boiled down to "anilist|tv|tmdb|tmdb season|tvdb season|episode offset" lines.
function PS.am_compact(src)
    local f = io.open(src, "rb")
    if not f then return false end
    local txt = f:read("*a"); f:close()
    local ok, data = pcall(utils.parse_json, txt)
    txt = nil
    if not ok or type(data) ~= "table" then return false end
    local function n(x) x = tonumber(x); return x and string.format("%d", x) or "" end
    local out = {}
    for _, e in ipairs(data) do
        local tm = type(e.themoviedb_id) == "table" and e.themoviedb_id or nil
        if tonumber(e.anilist_id) and tm then
            local kind, id = "tv", tm.tv
            if id == nil then kind, id = "movie", tm.movie end
            if type(id) == "table" then id = id[1] end
            if tonumber(id) then
                local se = type(e.season) == "table" and e.season or {}
                local eo = type(e.episode_offset) == "table" and e.episode_offset or {}
                local im = e.imdb_id
                if type(im) == "table" then im = table.concat(im, ",") end
                out[#out + 1] = table.concat({ n(e.anilist_id), kind, n(id), n(se.tmdb), n(se.tvdb), n(eo.tmdb), n(e.kitsu_id),
                    (tostring(im or ""):gsub("[^%w,]", "")) }, "|")
            end
        end
    end
    data = nil
    collectgarbage("step", 0)                 -- a full collection here froze the page for a moment
    if #out < 500 then return false end
    return atomic_write(PS.am_path(), "#v2\n" .. table.concat(out, "\n") .. "\n") and true or false
end

function PS.am_fetch()
    local AM = PS.AM
    if AM.state == "fetching" or (AM.state == "failed" and os.time() - (AM.fail_t or 0) < 3600) then return end
    AM.state = "fetching"
    PS.mkdir()
    local tmp = PS.dir() .. "/anime_map.download"
    PS.run({ o.curl_path, "-s", "-S", "-L", "-m", "180", "--create-dirs", "-o", tmp, o.anime_map_url }, function(res)
        local ok = res and res.status == 0 and PS.am_compact(tmp)
        pcall(os.remove, tmp)
        if ok then AM.state, AM.map = "done", nil; PS.am_load()
        else AM.state, AM.fail_t = "failed", os.time(); PS.notice("animemap", "The anime-lists map could not be downloaded - anime season mapping is off for now") end
        local ws = AM.waiters
        AM.waiters = {}
        for _, cb in ipairs(ws) do cb() end
    end)
end

-- cb() once the map is loaded, or known to be unavailable (then only the title fallback is used).
function PS.am_ready(cb, need_v2)
    local info = utils.file_info(PS.am_path())
    if info and need_v2 then
        PS.am_load()
        if not PS.AM.v2 and not (PS.AM.state == "failed" and os.time() - (PS.AM.fail_t or 0) < 3600) then
            table.insert(PS.AM.waiters, cb)          -- the add screen needs the newer format: wait for it once
            PS.am_fetch()
            return
        end
    end
    if info then
        PS.am_load()
        -- weekly refresh, in the background; an older file without the kitsu / IMDb ids is refreshed once too
        if os.time() - (info.mtime or 0) > 7 * 86400 or not PS.AM.v2 then PS.am_fetch() end
        cb(); return
    end
    if PS.AM.state == "failed" and os.time() - (PS.AM.fail_t or 0) < 3600 then cb(); return end
    table.insert(PS.AM.waiters, cb)
    PS.am_fetch()
end

function PS.al_cache()
    local AL = PS.AL
    if AL.cache then return AL.cache end
    AL.cache = {}
    local f = io.open(PS.dir() .. "/anilist.json", "rb")
    if f then
        local ok, d = pcall(utils.parse_json, f:read("*a")); f:close()
        if ok and type(d) == "table" then AL.cache = d end
    end
    return AL.cache
end

-- the AniList answers file: one write for a run of answers; answers too old to be used again are dropped
function PS.al_save()
    if PS.AL.save_t then return end
    PS.AL.save_t = mp.add_timeout(2, function() PS.AL.save_t = nil; PS.al_save_now() end)
end
function PS.al_save_now()
        local c, now = PS.al_cache(), os.time()
        for k, v in pairs(c) do
            local found = type(v) == "table" and type(v.r) == "table" and #v.r > 0
            if type(v) ~= "table" or now - (tonumber(v.t) or 0) > (found and 30 or 3) * 86400 then c[k] = nil end
        end
        PS.mkdir()
        pcall(atomic_write, PS.dir() .. "/anilist.json", safe_json(c) or "{}")
end
-- AniList search, at most one request every 2 s (AniList allows 30 a minute right now). cb(list | nil, err)
function PS.al_search(query, cb)
    local key = PS.norm(query)
    local hit = PS.al_cache()[key]
    local ttl = (type(hit) == "table" and type(hit.r) == "table" and #hit.r > 0) and 30 or 3     -- days; "nothing found" is re-asked sooner
    if type(hit) == "table" and os.time() - (tonumber(hit.t) or 0) < ttl * 86400 then cb(hit.r or {}) return end
    table.insert(PS.AL.q, { q = query, key = key, cb = cb })
    PS.al_pump()
end
-- Any other AniList GraphQL query, through the same paced queue: cb(decoded reply | nil, err)
function PS.al_gql(query, cb)
    table.insert(PS.AL.q, { gql = query, raw = cb })
    PS.al_pump()
end

function PS.al_pump()
    local AL = PS.AL
    if AL.busy or #AL.q == 0 then return end
    local wait = AL.last + 2.05 - mp.get_time()
    if wait > 0 then
        if not AL.timer then AL.timer = mp.add_timeout(wait, function() AL.timer = nil; PS.al_pump() end) end
        return
    end
    -- the searches waiting now go together (one request with an alias per search, up to 8 - AniList counts it as
    -- one); any other query goes on its own
    local batch = {}
    if AL.q[1].gql or AL.q[1].single then batch[1] = table.remove(AL.q, 1)
    else
        local i = 1
        while i <= #AL.q and #batch < 8 do
            if AL.q[i].gql or AL.q[i].single then i = i + 1 else batch[#batch + 1] = table.remove(AL.q, i) end
        end
    end
    local function fail(it, why)
        if it.raw then it.raw(nil, why) else it.cb(nil, why) end
    end
    AL.busy, AL.last = true, mp.get_time()
    local bf = PS.dir() .. "/anilist_query.json"
    PS.mkdir()
    local q1 = batch[1]
    local query
    if q1.gql then query = { query = q1.gql }
    elseif #batch == 1 then query = { query = PS.AL_GQL, variables = { s = q1.q } }
    else
        local parts = {}
        for k, it in ipairs(batch) do
            parts[k] = string.format("a%d:Page(perPage:8){media(search:%s,type:ANIME,sort:SEARCH_MATCH){%s}}", k,
                safe_json((tostring(it.q):gsub("%c", " "))) or '""', PS.AL_FIELDS)
        end
        query = { query = "query{" .. table.concat(parts, " ") .. "}" }
    end
    local body = safe_json(query)
    local f = body and io.open(bf, "wb")
    if not f then
        AL.busy = false
        for _, it in ipairs(batch) do fail(it, body and "cannot write the query file" or "bad query") end
        PS.al_pump(); return
    end
    f:write(body); f:close()
    PS.run({ o.curl_path, "-s", "-S", "-m", "15", "-w", "\n%{http_code}", "-X", "POST", "-H", "Content-Type: application/json",
             "-H", "Accept: application/json", "--data-binary", "@" .. bf, o.anilist_api }, function(res)
        AL.busy = false
        local reply, code = tostring(res and res.stdout or ""):match("^(.*)\n(%d%d%d)$")
        if code == "429" then              -- rate limited: wait a minute, then try again
            for k = #batch, 1, -1 do table.insert(AL.q, 1, batch[k]) end
            AL.last = mp.get_time() + 58
        elseif code ~= "200" and #batch > 1 and code then
            for k = #batch, 1, -1 do batch[k].single = true; table.insert(AL.q, 1, batch[k]) end     -- one by one
        elseif code ~= "200" then
            local why = "AniList " .. (code and ("HTTP " .. code) or ("unreachable: " .. tostring(res and res.stderr or ""):sub(1, 120)))
            PS.notice("anilist", why .. (q1.raw and "" or " - anime titles use the TMDB search for now"))
            for _, it in ipairs(batch) do fail(it, why) end
        elseif q1.raw then
            PS.notice_ok("anilist")
            local ok, d = pcall(utils.parse_json, reply)
            q1.raw((ok and type(d) == "table") and d or nil, (ok and type(d) == "table") and nil or "AniList sent something unreadable")
        else
            PS.notice_ok("anilist")
            local ok, d = pcall(utils.parse_json, reply)
            local data = ok and type(d) == "table" and type(d.data) == "table" and d.data or nil
            local c = PS.al_cache()
            for k, it in ipairs(batch) do
                local pg = data and ((#batch == 1) and data.Page or data["a" .. k])
                if type(pg) ~= "table" then
                    fail(it, "AniList sent no answer for this search")       -- not remembered: asked again next time
                else
                    local media = pg.media
                    local list = {}
                    for _, m in ipairs(type(media) == "table" and media or {}) do
                        local t = type(m.title) == "table" and m.title or {}
                        list[#list + 1] = { id = tonumber(m.id), format = m.format, eps = tonumber(m.episodes),
                            year = tonumber(type(m.startDate) == "table" and m.startDate.year or nil) or tonumber(m.seasonYear),
                            romaji = t.romaji, english = t.english, native = t.native,
                            syn = type(m.synonyms) == "table" and m.synonyms or {} }
                    end
                    c[it.key] = { t = os.time(), r = list }
                    it.cb(list)
                end
            end
            PS.al_save()
        end
        PS.al_pump()
    end)
end

-- Season number written in an AniList title ("2nd Season", "Season 3", "Part 2" does not count).
local function al_season_of(name)
    local l = tostring(name or ""):lower()
    local n = l:match("(%d+)%a%a season") or l:match("season (%d+)") or l:match("%s(%d)$")
    if n then return tonumber(n) end
    if l:match("%sii$") then return 2 end
    if l:match("%siii$") then return 3 end
    return nil
end

-- "Part 2", "Part II", "2nd Cour", "Cour 2" -> 2
function PS.al_part_of(name)
    local l = " " .. tostring(name or ""):lower() .. " "
    local n = l:match("part%s*(%d+)") or l:match("(%d+)%a%a cour") or l:match("cour%s*(%d+)")
    if n then return tonumber(n) end
    local r = l:match("part%s+([ivx]+)[%s%p]")
    return ({ i = 1, ii = 2, iii = 3, iv = 4, v = 5 })[r or ""]
end

-- Best AniList entry for a folder: names must really match (exact, or 60 % of the words), year and type help.
function PS.al_pick(list, title, year, kindpref, season)
    local want = PS.norm(title)
    local part = PS.al_part_of(title)
    local best, best_score
    for i, m in ipairs(list or {}) do
        local names = { m.romaji, m.english, m.native }
        for _, sy in ipairs(m.syn or {}) do names[#names + 1] = sy end
        local exact, ov, sn, pn = false, 0, nil, nil
        for _, nm in ipairs(names) do
            if nm and nm ~= "" then
                if PS.norm(nm) == want then exact = true end
                ov = math.max(ov, PS.overlap(nm, title))
                sn = sn or al_season_of(nm)
                pn = pn or PS.al_part_of(nm)
            end
        end
        if exact or ov >= 0.6 then
            local score = exact and 3 or ov * 2
            local wy, my = tonumber(year) or 0, tonumber(m.year) or 0
            if wy > 0 and my > 0 then
                if wy == my then score = score + 2 elseif math.abs(wy - my) == 1 then score = score + 1 else score = score - 1 end
            end
            local film = (m.format == "MOVIE")
            if kindpref == "movie" then score = score + (film and 1 or -0.5)
            elseif kindpref == "tv" then score = score + (film and -1 or 0.5) end
            if season and season > 1 then score = score + ((sn == season) and 1.5 or -0.5)
            elseif sn and sn > 1 then score = score - 0.7 end
            -- "Part 2" folder -> the "Part 2" entry; "Part 1" (or no part) -> the entry without a later part
            if part and part > 1 then score = score + ((pn == part) and 1.5 or -1)
            elseif pn and pn > 1 then score = score - 1 end
            score = score - (i - 1) * 0.05                -- AniList's own order breaks ties
            if not best_score or score > best_score then best, best_score = m, score end
        end
    end
    return best
end

-- cb(r | nil): r = { d = TMDB details (media_type set), q = how it was found, s = local season, ms / mo / me = TMDB
-- season, episode offset and episode count of this part }
-- AniList's search is literal: "Vanitas no Carte Part 1" finds nothing ("Vanitas no Karte" is the AniList name), so the
-- title is also tried without "Part 1" / "Season 2" / "2nd Cour". (Dropping more words picks the wrong show:
-- "Dragon Ball Kai" -> "Dragon Ball".)
function PS.al_queries(title)
    local out, seen = {}, {}
    local function add(q)
        q = tostring(q or ""):gsub("%s+", " "):gsub("^%s+", ""):gsub("%s+$", "")
        if #q >= 3 and not seen[q:lower()] then seen[q:lower()] = true; out[#out + 1] = q end
    end
    add(title)
    for _, v in ipairs(PS.spell_variants(title)) do add(v) end
    local t = tostring(title)
    local core = t:gsub("%s+[Pp]art%s*%d+$", ""):gsub("%s+[Pp]art%s+[IVX]+$", ""):gsub("%s+%d+%a%a%s+[Cc]our$", "")
        :gsub("%s+[Cc]our%s*%d+$", ""):gsub("%s+[Ss]eason%s*%d+$", ""):gsub("%s+%d+%a%a%s+[Ss]eason$", ""):gsub("%s+[Ss]%d+$", "")
    add(core)
    return out
end

function PS.anime_lookup(w, tried, cb)
    local fp = w.raw and CT.parse_folder(w.raw) or nil
    local season = fp and fp.season and tonumber(fp.season:match("^S(%d+)")) or nil
    local title = w.title
    local qs = PS.al_queries(title)
    local qi, net_err = 0, nil
    local function search_next()
        qi = qi + 1
        local q = qs[qi]
        if not q then cb(nil, net_err) return end
        tried[#tried + 1] = "AniList: " .. q
        PS.al_search(q, function(list, err)
            if not list then
                net_err = err
                tried[#tried + 1] = "AniList failed: " .. tostring(err)
                cb(nil, err)                    -- the service is down: no point trying the shorter forms now
                return
            end
            local m = PS.al_pick(list, title, w.year, w.kindpref, season)
            if m then PS.anime_map(w, m, season, tried, cb) else search_next() end
        end)
    end
    search_next()
end

function PS.anime_map(w, m, season, tried, cb)
    PS.am_ready(function()
        local mp_ = PS.AM.map and PS.AM.map[tostring(m.id)]
        local function done(kind, id, how, extra)
            PS.api(string.format("/%s/%s?language=en-US", kind, id), function(d, e2)
                if not d then cb(nil, e2) return end
                d.media_type = kind
                local r = { d = d, q = how }
                for k, v in pairs(extra or {}) do r[k] = v end
                cb(r)
            end)
        end
        if mp_ then
            tried[#tried + 1] = string.format("anime-lists: AniList %d -> %s:%s", m.id, mp_.kind, mp_.id)
            local extra = {}
            -- the folder has no season tag, or the same one as the map: use the map's season / offset
            if mp_.kind == "tv" and (not season or season == (mp_.tvs or mp_.s)) then
                extra.s = (not season) and mp_.tvs or nil
                extra.ms, extra.mo, extra.me = mp_.s, mp_.off, m.eps
            end
            done(mp_.kind, mp_.id, "AniList " .. m.id, extra)
            return
        end
        -- not in the map: TMDB search with the English / native title, checked against AniList's year and type
        local qs = {}
        if m.english and m.english ~= "" then qs[#qs + 1] = m.english end
        if m.native and m.native ~= "" then qs[#qs + 1] = m.native end
        local kp = (m.format == "MOVIE") and "movie" or "tv"
        local i = 0
        local function step()
            i = i + 1
            if not qs[i] then cb(nil) return end
            tried[#tried + 1] = "TMDB (AniList title): " .. qs[i]
            PS.search(qs[i], m.year and tostring(m.year) or "", nil, function(r)
                local ry = r and tonumber(((r.first_air_date or r.release_date or "")):sub(1, 4)) or nil
                if r and r.media_type == kp and (not m.year or (ry and math.abs(ry - m.year) <= 1)) then
                    done(kp, r.id, "AniList " .. m.id .. " title")
                else step() end
            end, kp, true, { anime = true })
        end
        step()
    end)
end

-- Romaji-looking title ("... no ...", "-hen", "-kun", "shita")? Then the AniList lookup is worth it even without fansub tags.
function PS.romaji(title)
    local l = " " .. tostring(title or ""):lower():gsub("[%._]", " ") .. " "
    for _, pat in ipairs({ "%a no %a", "%a wa %a", "%a ga %a", "%a wo %a", "%a ni %a", "[%s%-]kun ", "[%s%-]chan ", "[%s%-]sama ",
                           "shita ", "%-hen ", "%a hen ", "[%s%-]sensei ", "monogatari", "gakuen", "isekai", "tensei" }) do
        if l:find(pat) then return true end
    end
    return false
end

-- ---------- Real-Debrid API (optional: rd_api_token) ----------
-- Only used to explain episodes that WebDAV does not list ("hoster unavailable", "torrent dead"...).
-- The token is sent to rd_api_base only, through a header file (never on the command line, so it
-- cannot show up in the process list or the mpv log).
function PS.kick() if PS.on_kick then PS.on_kick() end end
PS.RD = { list = nil, list_t = 0, info = {}, checks = nil, inflight = {}, running = 0, ver = 0, err = nil }
PS.RD_REASONS = { [16] = "Hoster unsupported", [17] = "Hoster in maintenance", [18] = "Hoster limit reached",
    [19] = "Hoster unavailable", [20] = "Hoster not available for free users", [23] = "Traffic exhausted",
    [24] = "File unavailable", [35] = "Removed for copyright (\"infringing file\")", [36] = "Fair usage limit" }
PS.RD_STATUS = { magnet_error = "Magnet error", magnet_conversion = "Still converting on Real-Debrid",
    waiting_files_selection = "Waiting for file selection", queued = "Queued on Real-Debrid",
    downloading = "Still downloading on Real-Debrid", error = "Torrent error on Real-Debrid", virus = "Virus detected",
    compressing = "Compressing on Real-Debrid", uploading = "Uploading on Real-Debrid", dead = "Torrent dead on Real-Debrid" }
function PS.rd_on() return tostring(o.rd_api_token or "") ~= "" end
function PS.rd_hfile()
    local RD = PS.RD
    if RD.hfile and RD.hfile_tok == o.rd_api_token and utils.file_info(RD.hfile) then return RD.hfile end
    PS.mkdir()
    local path = PS.dir() .. "/rd_header.txt"
    local f = io.open(path, "wb")
    if not f then return nil end
    f:write("Authorization: Bearer " .. tostring(o.rd_api_token):gsub("%s", "") .. "\n"); f:close()
    RD.hfile, RD.hfile_tok = path, o.rd_api_token
    return path
end
function PS.rd_req(path, post, cb, method)
    local hf = PS.rd_hfile()
    if not hf then cb(nil, "cannot write the header file", 0) return end
    PS.http({ url = tostring(o.rd_api_base or ""):gsub("/+$", "") .. path, headers = { "@" .. hf }, form = post, timeout = 20, method = method },
        function(code, body)
            if code == 0 then PS.notice("rd", "Real-Debrid unreachable - missing-episode reasons are paused")
            elseif code == 401 or code == 403 then PS.notice("rd", "Real-Debrid rejected rd_api_token")
            elseif code < 500 then PS.notice_ok("rd") end
            local ok, data = pcall(utils.parse_json, body or "")
            cb(ok and data or nil, (code == 0) and "request failed" or nil, code)
        end)
end
function PS.rd_load_checks()
    local t = {}
    local f = io.open(PS.dir() .. "/rd_checks.json", "rb")
    if f then
        local ok, d = pcall(utils.parse_json, f:read("*a")); f:close()
        if ok and type(d) == "table" then t = U.plain(d) end
    end
    return t
end
function PS.rd_save_checks()
    if PS.RD.save_t then return end
    PS.RD.save_t = mp.add_timeout(2, function() PS.RD.save_t = nil; PS.rd_save_now() end)    -- one write for a run of answers
end
function PS.rd_save_now()
    local c, now = PS.RD.checks or {}, os.time()
    for k, v in pairs(c) do if type(v) ~= "table" or now - (tonumber(v.t) or 0) > 6 * 3600 then c[k] = nil end end     -- expired (6 h)
    local txt = safe_json(c)
    if txt then PS.mkdir(); pcall(atomic_write, PS.dir() .. "/rd_checks.json", txt) end
end
-- The torrent behind one WebDAV folder: { state = "loading" | "unknown" | "ready" | "error", data = torrent info }
function PS.rd_folder(name)
    local RD = PS.RD
    local now = os.time()
    if not RD.list or now - RD.list_t > 600 then
        if not RD.busy_list then
            RD.busy_list = true
            PS.rd_req("/torrents?limit=2500", nil, function(data, err, code)
                RD.busy_list = false
                if type(data) == "table" and code == 200 then
                    RD.list, RD.list_t, RD.err = {}, os.time(), nil
                    for _, t in ipairs(data) do
                        if type(t) == "table" and t.filename then RD.list[tostring(t.filename):lower()] = { id = t.id, status = t.status } end
                    end
                else
                    RD.err = (code == 401 or code == 403) and "Real-Debrid rejected rd_api_token"
                        or ("Real-Debrid: " .. tostring(err or ("HTTP " .. code)))
                    RD.list, RD.list_t = RD.list or {}, os.time() - 480      -- try again in 2 minutes
                end
                RD.ver = RD.ver + 1
                PS.kick()
            end)
        end
        if not RD.list then return { state = "loading" } end
    end
    if RD.err and not next(RD.list) then return { state = "error" } end
    local t = RD.list[tostring(name):gsub("/+$", ""):lower()]
    if not t then return { state = "unknown" } end
    local inf = RD.info[t.id]
    if not inf or (not inf.busy and now - inf.t > 600) then
        RD.info[t.id] = { busy = true, t = inf and inf.t or 0, data = inf and inf.data }
        PS.rd_req("/torrents/info/" .. t.id, nil, function(data, err, code)
            RD.info[t.id] = { t = os.time(), data = (type(data) == "table" and code == 200) and data or (inf and inf.data) }
            RD.ver = RD.ver + 1
            PS.kick()
        end)
        inf = RD.info[t.id]
    end
    if not inf.data then return { state = "loading" } end
    return { state = "ready", data = inf.data }
end
-- Why Real-Debrid cannot serve one link (cached for 6 hours). nil while the answer is pending.
function PS.rd_check(link)
    local RD = PS.RD
    RD.checks = RD.checks or PS.rd_load_checks()
    local c = RD.checks[link]
    if c and c.r and os.time() - (c.t or 0) < 6 * 3600 then return c end
    if c and c.fail and os.time() - (c.t or 0) < 90 then return { r = "Could not reach Real-Debrid" } end
    if RD.inflight[link] or RD.running >= 4 then return nil end
    RD.inflight[link] = true
    RD.running = RD.running + 1
    PS.rd_req("/unrestrict/check", { link = link }, function(data, err, code)
        RD.running = RD.running - 1
        RD.inflight[link] = nil
        local r
        if type(data) == "table" and data.error_code then
            r = PS.RD_REASONS[tonumber(data.error_code)] or (tostring(data.error or "error"):gsub("_", " "))
        elseif code == 503 then r = "File unavailable"
        elseif code == 200 and type(data) == "table" and tonumber(data.supported) == 0 then r = "Hoster unavailable"
        elseif code == 200 then r = "Available on Real-Debrid, not listed by WebDAV yet"
        elseif code == 0 then RD.checks[link] = { fail = true, t = os.time() }
        else r = "Real-Debrid HTTP " .. code end
        if r then RD.checks[link] = { r = r, t = os.time() }; PS.rd_save_checks() end
        RD.ver = RD.ver + 1
        PS.kick()
    end)
    return nil
end

-- Common misspellings in release names, as extra queries: "Your Being Summoned, Azazel" is "You're Being ...".
function PS.spell_variants(q)
    local out = {}
    q = tostring(q or "")
    local v = q:gsub("^([Yy])ou?re?%s+(%a+ing)%f[%A]", "%1ou're %2")
    if v ~= q then out[#out + 1] = v end
    v = q:gsub("%f[%a]([Yy])oure%f[%A]", "%1ou're")
    if v ~= q and v ~= out[1] then out[#out + 1] = v end
    return out
end

-- ---- the lookup / download / convert chain -------------------------------------------------
-- Search strings to try, best first, for one folder name.
function PS.queries(raw, title, year)
    local out, seen = {}, {}
    local function add(q)
        if not q then return end
        q = q:gsub("\234\158\137", ":"):gsub("%s+", " "):gsub("^%s+", ""):gsub("%s+$", "")
        if #q >= 2 and not seen[q:lower()] then seen[q:lower()] = true; out[#out + 1] = q end
    end
    add(title)
    for _, v in ipairs(PS.spell_variants(title)) do add(v) end
    local r = tostring(raw or ""):gsub("\234\158\137", ":"):gsub("%b[]", " "):gsub("%b()", " "):gsub("[%._]+", " ")
    r = r:gsub("%s+", " "):gsub("^%s+", ""):gsub("%s+$", "")
    r = CT.strip_tail(r)
    add(r)
    for _, base in ipairs({ title or "", r }) do
        add(base:match("^(.-)%s+%-%s+"))
        add(base:match("^(.-):"))
    end
    local words = {}
    for w in tostring(title or r):gmatch("%S+") do words[#words + 1] = w end
    for n = #words - 1, 2, -1 do add(table.concat(words, " ", 1, n)) end
    if #words >= 2 and #words[1] >= 4 then add(words[1]) end
    return out
end

-- Best result. kindpref = "tv" | "movie" | "" (a season tag in the folder name means TV; a bare year means a film).
-- strict: only results whose name relates to the query count; the best unrelated one is handed back as `any`.
function PS.pick(results, title, year, kindpref, strict, opts)
    local best, best_score, any
    local want = PS.pnorm(title)
    opts = opts or {}
    for _, r in ipairs(results or {}) do
        if (r.media_type == "tv" or r.media_type == "movie") and r.poster_path and r.poster_path ~= "" then
            local date = r.first_air_date or r.release_date or ""
            local nm, on = PS.pnorm(r.name or r.title or ""), PS.pnorm(r.original_name or r.original_title or "")
            local exact = (nm == want or on == want)
            local related = exact or (#want >= 4 and ((nm ~= "" and (nm:find(want, 1, true) or want:find(nm, 1, true)))
                or (on ~= "" and (on:find(want, 1, true) or want:find(on, 1, true)))))
            -- a shortened query ("Boku no") must still resemble the full title, or "Boku no Nee-chan" wins
            if related and opts.full and not exact then
                related = (PS.overlap(r.name or r.title or "", opts.full) >= 0.6 or PS.overlap(r.original_name or r.original_title or "", opts.full) >= 0.6)
                    and PS.key_words_ok(r, opts.full)
            end
            local score = exact and 3 or (related and 1 or 0)
            if opts.anime then
                local anim = false
                for _, g in ipairs(type(r.genre_ids) == "table" and r.genre_ids or {}) do if tonumber(g) == 16 then anim = true end end
                if anim then score = score + 2 end
                if r.original_language == "ja" then score = score + 0.5 end
            end
            local ry = tonumber(date:sub(1, 4)) or 0
            local wy = tonumber(year) or 0
            if wy > 0 and ry > 0 then
                if ry == wy then score = score + 2 elseif math.abs(ry - wy) == 1 then score = score + 1 end
            end
            if kindpref and kindpref ~= "" and r.media_type == kindpref then score = score + 1.5 end
            score = score + math.min(0.9, (tonumber(r.popularity) or 0) / 1000)
            if not any and (not opts.full or PS.overlap(r.name or r.title or "", opts.full) >= 0.6) and PS.key_words_ok(r, opts.full or title) then any = r end
            if (not strict or related) and (not best_score or score > best_score) then best, best_score = r, score end
        end
    end
    return best, any
end

-- Picture names of an entry: a box set's are its collection's ("c9485"), never those of its first film.
function PS.aid(e)
    return e.coll and ("c" .. e.coll) or e.id
end
-- A box set folder ("Fast and Furious COLLECTION 2001-2021", "The Matrix Trilogy"): the name before the word, else nil.
-- The word has to end the title (only years, "complete", "movies"... may follow): "The Twilight Saga Breaking Dawn" is a film.
PS.COLLW = { collection = true, trilogy = true, quadrilogy = true, pentalogy = true, hexalogy = true, duology = true, saga = true, anthology = true }
PS.REL_TAG = { yify = true, yts = true, rarbg = true, amzn = true, nf = true, dsnp = true, hmax = true, atvp = true,
    bdrip = true, dvdrip = true, brrip = true, hdrip = true, webrip = true, bluray = true, remux = true, truehd = true,
    imax = true, hevc = true, avc = true, dts = true, aac = true, ac3 = true, ddp = true, atmos = true, hdr = true, dv = true,
    proper = true, repack = true, multi = true, dual = true, extended = true, unrated = true, remastered = true, uhd = true }
PS.COLL_TAIL = { complete = true, movies = true, movie = true, films = true, film = true, box = true, set = true, boxset = true, pack = true,
    extended = true, remastered = true, theatrical = true, edition = true, cut = true, uhd = true, ["4k"] = true, hdr = true, remux = true,
    bluray = true, web = true, webrip = true, hevc = true, avc = true, dts = true, aac = true, atmos = true, dv = true, proper = true,
    repack = true, multi = true, dual = true, audio = true, eng = true, english = true }
function PS.coll_query(title)
    local t = tostring(title or ""):gsub("%b[]", " "):gsub("%b()", " "):gsub("[%._]+", " ")
    local words = {}
    for wd in t:gmatch("%S+") do words[#words + 1] = wd end
    local at
    for i = 2, #words do if PS.COLLW[words[i]:lower()] then at = i break end end
    if not at then return nil end
    -- right after it: nothing, a year or range, "Complete", or a release tag ("1080p", "x264-GRP", "YIFY", "BluRay");
    -- anything else is a title going on ("The Twilight Saga Breaking Dawn" is a film)
    local nx = words[at + 1]
    if nx then
        local wl = nx:lower()
        if not (PS.COLL_TAIL[wl] or PS.REL_TAG[wl] or wl:find("%d") or wl:find("-", 1, true) or wl:find("–", 1, true)
            or (nx:match("^%u%u+$") ~= nil)) then return nil end
    end
    local n = at - 1
    while n > 0 and (PS.COLL_TAIL[words[n]:lower()] or words[n]:match("^%d+[%-–]*%d*$") or words[n] == "-") do n = n - 1 end
    local real = false                  -- "The Collection" (a film) has nothing before the word but "The"
    for i = 1, n do if not PS.STOPW[U.fold(words[i]):lower():gsub("[^%w]", "")] then real = true end end
    local q = table.concat(words, " ", 1, n)
    return (real and #q >= 2) and q or nil
end

function PS.search(title, year, gen, cb, kindpref, strict, opts)
    PS.http(PS.tmdb_req("/search/multi?include_adult=false&query=" .. U.url_encode_segment(title)), function(code, body)
        if gen and gen ~= PS.gen then return end
        local why = PS.tmdb_status(code)
        if code ~= 200 then cb(nil, why) return end
        local ok, data = pcall(utils.parse_json, body or "")
        if not ok or type(data) ~= "table" then cb(nil, "bad reply") return end
        local best, any = PS.pick(data.results, title, year, kindpref, strict, opts)
        cb(best or false, nil, any)
    end)
end

-- Generic TMDB GET. cb(data|nil, err, http_code)
function PS.api(path, cb)
    PS.http(PS.tmdb_req(path), function(code, body)
        local why = PS.tmdb_status(code)
        if code == 401 then cb(nil, why, 401) return end
        if code ~= 200 then cb(nil, why or ("TMDB HTTP " .. code), code) return end
        local ok, data = pcall(utils.parse_json, body or "")
        if not ok or type(data) ~= "table" then cb(nil, "bad reply", code) return end
        cb(data, nil, 200)
    end)
end

-- Persistent episode data (episodes.json): one record per show+season, fetched ONCE and kept forever.
PS.eps, PS.eps_ver, PS.idx_ver = nil, 0, 0
function PS.load_eps()
    if PS.eps then return end
    local path = PS.dir() .. "/episodes.json"
    PS.eps, PS.epsj = {}, { sig = {}, lines = 0 }
    local data = try_load_json(path)
    if type(data) == "table" then PS.eps = U.plain(data) end
    PS.epsj.lines = U.jl_apply(path, PS.eps)
    for k, v in pairs(PS.eps) do PS.epsj.sig[k] = U.jl_sig(v) end
end
function PS.save_eps()
    if PS.eps_timer then return end
    PS.eps_timer = mp.add_timeout(0.5, function()
        PS.eps_timer = nil
        local path = PS.dir() .. "/episodes.json"
        local ok
        if PS.epsj.lines < U.JL_MAX and utils.file_info(path) then ok = U.jl_sync(PS.epsj, path, PS.eps) end
        if not ok then PS.mkdir(); U.jl_compact(PS.epsj, path, PS.eps, PS.eps) end
    end)
end
function PS.ep_info(show, s, e)
    if not (show and show.id and s and e) then return nil end
    PS.load_eps()
    local rec = PS.eps[show.id .. ":" .. s]
    if type(rec) ~= "table" or rec.none or type(rec.eps) ~= "table" then return nil end
    return rec.eps[tostring(e)]
end
-- Fetch (once) season s of a TV show; calls cb() when stored (also for a season TMDB does not know).
-- Season data used to be fetched once and kept forever, so episodes that had no ratings yet when they were first
-- fetched never got them. A season record is asked for again (once per session, the old data stays on screen until
-- the answer is in): after 7 days while any of its episodes has no rating, after 60 days otherwise, and a
-- "no such season" answer after 7 days. T on a title still clears it at once.
function PS.eps_stale(rec)
    if type(rec) ~= "table" then return true end
    local age = os.time() - (tonumber(rec.ts) or 0)
    if rec.none then return age > 7 * 86400 end
    for _, ep in pairs(rec.eps or {}) do
        if (tonumber(ep.v) or 0) <= 0 then return age > 7 * 86400 end
    end
    return age > 60 * 86400
end

function PS.season(show, s, cb, force)
    PS.load_eps()
    local key = show.id .. ":" .. s
    if PS.eps[key] ~= nil and not force then cb() return end
    PS.api(string.format("/tv/%s/season/%d?language=en-US", show.id, s), function(data, err, code)
        if data and type(data.episodes) == "table" then
            local rec = { ts = os.time(), eps = {} }
            for _, ep in ipairs(data.episodes) do
                local n = tonumber(ep.episode_number)
                if n then
                    rec.eps[tostring(n)] = {
                        n = ep.name or "", o = tostring(ep.overview or ""):sub(1, 400), st = ep.still_path or "",
                        d = ep.air_date or "", r = tonumber(ep.runtime) or 0, v = tonumber(ep.vote_average) or 0,
                    }
                end
            end
            PS.eps[key] = rec
            PS.save_eps()
        elseif code == 404 then
            PS.eps[key] = { none = true, ts = os.time() }      -- TMDB has no such season: remember, do not ask again
            PS.save_eps()
        else
            PS.season_err = err
            cb(err) return
        end
        PS.eps_ver = PS.eps_ver + 1
        cb()
    end)
end
-- Overview / backdrop / season count for a show that was cached without them (older cache entries).
-- the logo to use from TMDB's list: an English PNG, else one without text language, else none ("")
function PS.best_logo(list)
    local best = ""
    for _, lg in ipairs(type(list) == "table" and list or {}) do
        local fp = tostring(lg.file_path or "")
        if fp:match("%.png$") and lg.iso_639_1 == "en" then return fp end
        if fp:match("%.png$") and best == "" then best = fp end
    end
    return best
end
function PS.details(entry, cb)
    if entry.coll then                                 -- a box set: what TMDB's collection gave is all there is
        entry.detail, entry.dv = true, 26
        if cb then mp.add_timeout(0, cb) end
        return
    end
    local mv = entry.kind == "movie"
    -- also the other names it goes by (search finds "Shingeki no Kyojin" as Attack on Titan), and - search_cast /
    -- search_keywords - its cast and keywords
    local extra = "alternative_titles"
    if o.search_cast then extra = extra .. ",credits" end
    if o.search_keywords then extra = extra .. ",keywords" end
    if o.title_logo then extra = extra .. ",images"; PS.logo_wait[tostring(entry.kind) .. ":" .. tostring(entry.id)] = true end
    PS.api(string.format("/%s/%s?language=en-US&append_to_response=%s,%s%s", mv and "movie" or "tv", entry.id,
        mv and "release_dates" or "content_ratings", extra, o.title_logo and "&include_image_language=en,null" or ""), function(d)
        PS.logo_wait[tostring(entry.kind) .. ":" .. tostring(entry.id)] = nil
        if d then
            if type(d.images) == "table" and entry.logo == nil then entry.logo = PS.best_logo(d.images.logos); entry.logo_asked = true end
            -- rich details: genres, runtime, status, age rating, tagline, years, creators
            local gen = {}
            for _, g in ipairs(type(d.genres) == "table" and d.genres or {}) do if g.name then gen[#gen + 1] = g.name end end
            entry.gen = gen
            entry.lang = d.original_language or entry.lang
            local rt = tonumber(d.runtime)
            if not rt and type(d.episode_run_time) == "table" then rt = tonumber(d.episode_run_time[1]) end
            entry.rt = rt or 0
            entry.status = d.status or ""
            entry.tag = d.tagline or ""
            entry.neps = tonumber(d.number_of_episodes) or entry.neps
            entry.yr2 = tostring(d.last_air_date or ""):sub(1, 4)
            local by = {}
            for _, c in ipairs(type(d.created_by) == "table" and d.created_by or {}) do if c.name and #by < 2 then by[#by + 1] = c.name end end
            entry.by = table.concat(by, ", ")
            local cert = ""
            local function pick_cert(list, field)
                for _, r in ipairs(list or {}) do
                    if r.iso_3166_1 == "US" then
                        if field then
                            for _, rd in ipairs(r.release_dates or {}) do if rd.certification and rd.certification ~= "" then return rd.certification end end
                        elseif r.rating and r.rating ~= "" then return r.rating end
                    end
                end
                return ""
            end
            if mv and type(d.release_dates) == "table" then cert = pick_cert(d.release_dates.results, true)
            elseif type(d.content_ratings) == "table" then cert = pick_cert(d.content_ratings.results, false) end
            entry.cert = cert
            entry.overview = tostring(d.overview or "")
            entry.backdrop_path = d.backdrop_path or entry.backdrop_path or ""
            entry.seasons = tonumber(d.number_of_seasons) or entry.seasons
            entry.vote = tonumber(d.vote_average) or entry.vote
            local sc, sp, snm = {}, {}, {}
            local n = 0
            if type(d.seasons) == "table" then
                for _, se in ipairs(d.seasons) do
                    local sn, cnt = tonumber(se.season_number), tonumber(se.episode_count)
                    if sn and sn >= 1 and cnt then sc[tostring(sn)] = cnt; n = n + 1 end
                    if sn then
                        if se.poster_path and se.poster_path ~= "" then sp[tostring(sn)] = se.poster_path end
                        if se.name and se.name ~= "" then snm[tostring(sn)] = se.name end
                    end
                end
            end
            entry.sc = (n > 0) and sc or false
            entry.sp, entry.sn = sp, snm
            if (entry.poster_path or "") == "" then entry.poster_path = d.poster_path end
            if not entry.name or entry.name == "?" then entry.name = d.name or d.title end
            -- names for the library search: original title, other titles (a few), the film series it belongs to
            local al, seen = {}, {}
            local function addn(nm) nm = tostring(nm or ""); if nm ~= "" and not seen[nm:lower()] and #al < 10 then seen[nm:lower()] = true; al[#al + 1] = nm end end
            addn(d.original_name or d.original_title)
            local at = type(d.alternative_titles) == "table" and (d.alternative_titles.results or d.alternative_titles.titles) or {}
            for _, a in ipairs(type(at) == "table" and at or {}) do if type(a) == "table" then addn(a.title) end end
            if type(d.belongs_to_collection) == "table" then addn(d.belongs_to_collection.name) end
            entry.alt = al
            if o.search_cast and type(d.credits) == "table" then
                local c = {}
                for i, p in ipairs(type(d.credits.cast) == "table" and d.credits.cast or {}) do if i <= 6 and p.name then c[#c + 1] = p.name end end
                entry.cast = c
            end
            if o.search_keywords and type(d.keywords) == "table" then
                local k = {}
                for _, kw in ipairs(d.keywords.keywords or d.keywords.results or {}) do if #k < 12 and kw.name then k[#k + 1] = kw.name end end
                entry.kw = k
            end
            entry.detail = true
            entry.dv = 26               -- details with the search names
            PS.save_index(entry)
            PS.eps_ver = PS.eps_ver + 1
        end
        cb()
    end)
end
-- Download an image to the cache (never expires). cb(ok)
-- TMDB's picture sizes, small to large. A picture already on disk at the wanted size OR LARGER is used as it is
-- (it is scaled down when converted), so a different card size, window or screen never downloads it again.
PS.SIZES = { "w92", "w185", "w300", "w342", "w500", "w780", "w1280", "original" }
function PS.jpg_for(base, size)
    local dir = PS.dir()
    local want = string.format("%s/%s_%s.jpg", dir, base, size)
    local ji = utils.file_info(want)
    if ji and ji.size > 500 then return want end
    local from = nil
    for i, sz in ipairs(PS.SIZES) do if sz == size then from = i end end
    if from then
        for i = from + 1, #PS.SIZES do
            local p = string.format("%s/%s_%s.jpg", dir, base, PS.SIZES[i])
            local fi = utils.file_info(p)
            if fi and fi.size > 500 then return p end
        end
    end
    return want
end

-- A picture on disk is whole: a JPEG ends with its end marker, a PNG with its IEND chunk. A cut-off download (the
-- network dropped, or - before v26 - a second card reading a picture that was still arriving) decodes WITHOUT an
-- error in ffmpeg, the missing part filled with green, and that green card was then kept in the cache for good.
PS.img_ok = {}
function PS.img_valid(path)
    if PS.img_ok[path] then return true end
    local f = io.open(path, "rb")
    if not f then return false end
    local head = f:read(8) or ""
    local size = f:seek("end") or 0
    local tail = ""
    if size > 64 then f:seek("set", size - 64); tail = f:read(64) or "" end
    f:close()
    local ok
    if head:sub(1, 2) == "\255\216" then ok = tail:find("\255\217", 1, true) ~= nil
    elseif head:sub(1, 8) == "\137PNG\r\n\26\n" then ok = tail:find("IEND", 1, true) ~= nil
    else ok = size > 500 end            -- WebP / GIF covers: not checked further
    if ok then PS.img_ok[path] = true end
    return ok
end
-- A broken picture is deleted with everything made from it (converted sizes, blurred placeholder), so it is fetched again.
function PS.drop_image(jpg)
    PS.img_ok[jpg] = nil
    pcall(os.remove, jpg)
    local dir, file = jpg:match("^(.*)/([^/]+)$")
    local base = file and file:match("^(.-)_[^_]+%.%a+$")
    if not base then return end
    local list = utils.readdir(dir, "files")
    for _, f in ipairs(type(list) == "table" and list or {}) do
        if f:sub(1, #base + 1) == base .. "_" and (f:match("%.bgra$") or f:match("%.tiny$")) then pcall(os.remove, dir .. "/" .. f) end
    end
    PS.st_dirty = true
end
-- Once per cache: pictures cut off by older versions (and the green cards made from them) are removed.
function PS.sweep_broken()
    local dir = PS.dir()
    local flag = dir .. "/checked_v26"
    if utils.file_info(flag) then return end
    local list = utils.readdir(dir, "files")
    if type(list) ~= "table" then return end
    local n = 0
    for _, f in ipairs(list) do
        if f:match("%.jpg$") and not PS.img_valid(dir .. "/" .. f) then PS.drop_image(dir .. "/" .. f); n = n + 1 end
    end
    local fh = io.open(flag, "wb")
    if fh then fh:write(tostring(n)); fh:close() end
    if n > 0 then msg.info(string.format("artwork: removed %d broken picture%s - they are fetched again", n, n == 1 and "" or "s")) end
end

function PS.fetch_image(size, path, jpg, cb)
    local ji = utils.file_info(jpg)
    if ji and ji.size > 500 then cb(true) return end
    -- the same picture asked for twice at once (a backdrop and a file card, say): one download, both are told
    PS.img_wait = PS.img_wait or {}
    if PS.img_wait[jpg] then table.insert(PS.img_wait[jpg], cb) return end
    PS.img_wait[jpg] = { cb }
    local function done(ok)
        local list = PS.img_wait[jpg] or {}
        PS.img_wait[jpg] = nil
        for _, f in ipairs(list) do f(ok) end
    end
    local full = tostring(path):match("^https?://")
    local url = full and path or (o.tmdb_image_base .. size .. path)     -- AniList covers: full URLs
    -- a picture whose download stalls (under 1 KB/s for 8 s) is tried again, twice; a slow but moving one may take its time
    PS.http({ url = url, out = jpg, timeout = 40, retry = 2, stall = 8 }, function(code)
        local info = utils.file_info(jpg)
        local ok = code == 200 and info and info.size > 500
        if not ok then pcall(os.remove, jpg) end
        -- a size TMDB does not serve for this picture (episode stills officially come as w300 or original): original
        if not ok and not full and size ~= "original" and (code == 400 or code == 404) then
            PS.http({ url = o.tmdb_image_base .. "original" .. path, out = jpg, timeout = 40, retry = 2, stall = 8 }, function(c2)
                local i2 = utils.file_info(jpg)
                local ok2 = c2 == 200 and i2 and i2.size > 500
                -- an episode still ("s<id>_...") refused at the bigger size: stills are asked for as original from now on
                if not ok2 then pcall(os.remove, jpg)
                elseif (size == "w780" or size == "w1280") and tostring(jpg):match("/s%d+_[^/]*$") then PS.still_big_bad = true end
                done(ok2 and true or false)
            end)
            return
        end
        done(ok and true or false)
    end)
end

-- Cache size (everything in the cache folder; history lives elsewhere and is never counted or touched).
-- The page only reads the last count; it is counted again away from drawing, at most every 10 s while artwork is being
-- added (60 s otherwise), in one pass over the names: a converted picture's size follows from its name (w x h x 4), any
-- other file is looked at once and remembered.
PS.fsz = {}
function PS.stats(force)
    local now = os.time()
    local due = not PS.st or force or now - PS.st.t >= (PS.st_dirty and 10 or 60)
    if due and not PS.st_timer and not PS.counting then
        PS.st_timer = mp.add_timeout(force and 0 or 0.4, function()
            PS.st_timer = nil
            local old = PS.st
            PS.recount(function()
                if not old or old.bytes ~= PS.st.bytes or old.imgs ~= PS.st.imgs then PS.kick() end
            end)
        end)
    end
    return PS.st or { t = 0, bytes = 0, files = 0, imgs = 0 }
end
-- the count itself: the names in one pass, the few files looked at for their size a couple of hundred per step
function PS.recount(done, now)
    if PS.counting and not now then return end
    PS.counting, PS.st_dirty = true, false
    PS.st_gen = (PS.st_gen or 0) + 1
    local gen = PS.st_gen
    local dir = PS.dir()
    local list = utils.readdir(dir, "all")
    if type(list) ~= "table" then list = {} end
    local bytes, files, imgs, seen, i = 0, 0, 0, {}, 0
    local function step()
        local looked = 0
        while true do
            i = i + 1
            local f = list[i]
            if not f then break end
            if f ~= "." and f ~= ".." and f ~= "http" then
                local sz = PS.fsz[f]
                if sz == nil then
                    local w, h = f:match("_t?(%d+)x(%d+)[%w%.]*%.bgra$")
                    if not w then w, h = f:match("_t(%d+)x(%d+)%.tiny$") end
                    if w then sz = tonumber(w) * tonumber(h) * 4
                    else
                        local info = utils.file_info(dir .. "/" .. f)
                        sz = (info and info.is_file) and info.size or false
                        looked = looked + 1
                    end
                    -- a file that keeps changing (a log, a list) is looked at again next time
                    if not f:match("%.log$") and not f:match("%.json$") and not f:match("%.txt$") then PS.fsz[f] = sz end
                end
                if sz then
                    seen[f] = true
                    bytes = bytes + sz; files = files + 1
                    if f:match("%.jpg$") then imgs = imgs + 1 end
                end
            end
            if looked >= 200 and not now then mp.add_timeout(0.02, step); return end
        end
        if gen ~= PS.st_gen then return end          -- the cache was cleared (or counted again) meanwhile
        for f in pairs(PS.fsz) do if not seen[f] then PS.fsz[f] = nil end end      -- deleted since
        PS.st = { t = os.time(), bytes = bytes, files = files, imgs = imgs }
        PS.counting = nil
        if done then done() end
    end
    step()
end
function PS.clear_cache()
    local dir = PS.dir()
    local list = utils.readdir(dir, "all")
    local n = 0
    if type(list) == "table" then
        for _, f in ipairs(list) do
            if f ~= "." and f ~= ".." and f ~= "http" and f ~= "crop_v2610" and os.remove(dir .. "/" .. f) then n = n + 1 end    -- the http folder stays
        end
    end
    PS.fsz, PS.st, PS.counting = {}, nil, nil     -- counted again (the footer says "Cache …" for a moment)
    PS.st_gen = (PS.st_gen or 0) + 1
    PS.idx, PS.eps = { __v = PS.IDX_VERSION }, {}
    PS.eps_ver = PS.eps_ver + 1
    dir_cache = {}
    MS.cache_version = MS.cache_version + 1
    PS.st_dirty = true
    return n
end

function PS.convert(jpg, bgra, w, h, cb, tries)
    if PS.conv_mode and o.poster_converter == "auto" and PS.conv_mode() == nil and (tries or 0) < 30 then
        mp.add_timeout(0.1, function() PS.convert(jpg, bgra, w, h, cb, (tries or 0) + 1) end)      -- still checking for ffmpeg
        return
    end
    local mode = PS.conv_mode and PS.conv_mode() or o.poster_converter
    if mode == "auto" or not mode then mode = (package.config:sub(1, 1) == "\\") and "powershell" or "ffmpeg" end
    local function done(res, err, tag)
        if not res or res.status ~= 0 then cb(false, tag .. " failed") else cb(true) end
    end
    if mode == "powershell" then
        local ps = PS.dir() .. "/convert.ps1"
        local f = io.open(ps, "wb")
        if not f then cb(false, "cannot write convert script") return end
        f:write(PS.PS1); f:close()
        PS.run({ "powershell", "-NoProfile", "-NonInteractive", "-ExecutionPolicy", "Bypass", "-File", ps,
                 jpg, bgra, tostring(w), tostring(h) }, function(r, e) done(r, e, "powershell") end)
    elseif mode == "ffmpeg" then
        PS.run({ o.ffmpeg_path, "-v", "error", "-y", "-i", jpg, "-vf", string.format("scale=%d:%d:force_original_aspect_ratio=increase,crop=%d:%d", w, h, w, h),
                 "-pix_fmt", "bgra", "-f", "rawvideo", bgra }, function(r, e) done(r, e, "ffmpeg") end)
    else
        PS.run({ o.magick_path, jpg, "-resize", string.format("%dx%d^", w, h), "-gravity", "center", "-extent", string.format("%dx%d", w, h), "-depth", "8", "bgra:" .. bgra },
            function(r, e) done(r, e, "magick") end)
    end
end

-- Show (or re-show) the converted picture for the current request.
function PS.draw()
    local want = PS.want
    if not (want and want.ready and browser_active and PS.status == "ok") then return end
    local ok = mp.commandv("overlay-add", tostring(PS.ID), tostring(want.x), tostring(want.y), want.bgra, "0", "bgra",
        tostring(want.w), tostring(want.h), tostring(want.w * 4))
    PS.shown = ok and want.key or nil
end

function PS.hide()
    PS.gen = PS.gen + 1
    if PS.timer then PS.timer:kill(); PS.timer = nil end
    if PS.shown then pcall(mp.commandv, "overlay-remove", tostring(PS.ID)) end
    PS.shown = nil
    PS.want = nil
    PS.status = "idle"
    PS.info = nil
end

-- Download (if needed) and convert for the size in `want`, then draw.
function PS.finish_convert(want, gen)
    local bgra = string.format("%s/p%s_%dx%d.bgra", PS.dir(), want.id, want.w, want.h)
    local bi = utils.file_info(bgra)
    if bi and bi.size == want.w * want.h * 4 then
        want.bgra, want.ready = bgra, true
        PS.status = "ok"; PS.draw(); render(); return
    end
    PS.convert(want.jpg, bgra, want.w, want.h, function(ok, why)
        if gen ~= PS.gen then return end
        local bi2 = utils.file_info(bgra)
        if not ok or not bi2 or bi2.size ~= want.w * want.h * 4 then
            PS.status, PS.err = "error", why or "bad converted size"
            render(); return
        end
        want.bgra, want.ready = bgra, true
        PS.status = "ok"; PS.draw(); render()
    end)
end

function PS.have_poster(want, entry, gen)
    PS.info = { name = entry.name, year = entry.year, kind = entry.kind }
    local jpg = PS.jpg_for("p" .. PS.aid(entry), want.size)
    want.id, want.jpg = PS.aid(entry), jpg
    local ji = utils.file_info(jpg)
    if ji and ji.size > 1000 then PS.finish_convert(want, gen); return end
    PS.http({ url = o.tmdb_image_base .. want.size .. entry.poster_path, out = jpg, timeout = 30 }, function(code)
        if gen ~= PS.gen then return end
        local info = utils.file_info(jpg)
        if code ~= 200 or not info or info.size < 1000 then
            PS.status, PS.err = "error", "poster download failed"
            render(); return
        end
        PS.save_index()   -- the cache folder exists now (curl --create-dirs), so this write can succeed
        PS.finish_convert(want, gen)
    end)
end

function PS.start(want)
    PS.gen = PS.gen + 1
    local gen = PS.gen
    PS.want = want
    PS.status = "loading"
    PS.info, PS.err = nil, nil
    PS.load_index()
    local ik = PS.norm(want.title) .. "|" .. want.year
    local hit = PS.idx[ik]
    if hit ~= nil then
        if hit == false or hit.none then PS.status = "none"; render(); return end
        PS.have_poster(want, hit, gen); return
    end
    PS.search(want.title, want.year, gen, function(r, err)
        if gen ~= PS.gen then return end
        if r == nil then PS.status, PS.err = "error", err; render(); return end
        if r == false then
            PS.idx[ik] = { none = true }
            PS.save_index()
            PS.status = "none"; render(); return
        end
        local entry = {
            id = tostring(r.id or "0"), name = r.name or r.title or "?", kind = r.media_type,
            year = (r.first_air_date or r.release_date or ""):sub(1, 4), poster_path = r.poster_path,
        }
        PS.idx[ik] = entry
        PS.save_index()
        PS.have_poster(want, entry, gen)
    end)
end

-- Called at the end of every render(). Cheap when nothing changed.
function PS.update()
    local rect = layout and layout.poster
    local title, year
    if rect and PS.enabled() and not MS.debug then title, year = PS.target() end
    if not title then
        if PS.want or PS.shown or PS.status ~= "idle" then PS.hide() end
        return
    end
    -- picture box inside the column: 2:3, leaving room for the caption underneath
    local pw = rect.x2 - rect.x1 - 16
    local avail_h = rect.y2 - rect.y1 - 16 - PS.caption_h(rect)
    local ph = math.floor(pw * 1.5)
    if ph > avail_h then ph = avail_h; pw = math.floor(ph / 1.5) end
    if pw < 80 then
        if PS.want or PS.shown or PS.status ~= "idle" then PS.hide() end
        return
    end
    pw = math.min(pw, 340)
    ph = math.floor(pw * 1.5)
    local x = math.floor(rect.x1 + ((rect.x2 - rect.x1) - pw) / 2)
    local y = math.floor(rect.y1 + 12)
    local key = PS.norm(title) .. "|" .. year
    local w_ = PS.want
    if w_ and w_.key == key and w_.w == pw and w_.h == ph and w_.x == x and w_.y == y then
        -- same request: make sure the bitmap is still on screen (e.g. after a hide)
        if w_.ready and PS.shown ~= key and PS.status == "ok" then PS.draw() end
        return
    end
    -- different request: remove the old bitmap right away, debounce the lookup while scrolling
    if PS.shown then pcall(mp.commandv, "overlay-remove", tostring(PS.ID)); PS.shown = nil end
    PS.gen = PS.gen + 1
    local gen = PS.gen
    local keep_info = (w_ and w_.key == key) and PS.info or nil
    local want = { key = key, title = title, year = year, w = pw, h = ph, x = x, y = y,
                   size = (pw > 300) and "w500" or "w342" }
    PS.want, PS.status, PS.info = want, "loading", keep_info
    if PS.timer then PS.timer:kill() end
    PS.timer = mp.add_timeout(0.35, function()
        PS.timer = nil
        if gen ~= PS.gen then return end
        PS.start(want)
    end)
end

function PS.caption_h(rect)
    return 92
end

-- Draw the column background, caption and the required TMDB attribution (ASS layer, under the bitmap).
function PS.draw_panel(chunks, rect, paint_panel)
    paint_panel(rect, false)
    local fs = layout.fs
    local cx = (rect.x1 + rect.x2) / 2
    local pw = rect.x2 - rect.x1 - 12
    local ty = rect.y2 - PS.caption_h(rect) + 4
    local want = PS.want
    local status_text
    if PS.status == "loading" then status_text = "Loading poster..."
    elseif PS.status == "none" then status_text = "No poster found"
    elseif PS.status == "error" then status_text = PS.err or "Poster error" end
    if status_text then
        table.insert(chunks, D.ev_text(cx, rect.y1 + (rect.y2 - rect.y1 - PS.caption_h(rect)) / 2, 5,
            string.format("\\fs%d\\c%s", fs - 6, U.ass_color(THEME.text_muted)), U.ass_escape(U.fit_text(status_text, pw, fs - 6))))
    elseif not want then
        table.insert(chunks, D.ev_text(cx, rect.y1 + (rect.y2 - rect.y1 - PS.caption_h(rect)) / 2, 5,
            string.format("\\fs%d\\c%s", fs - 6, U.ass_color(THEME.text_muted)), "No title to look up"))
    end
    if PS.info then
        local line = PS.info.name .. ((PS.info.year and PS.info.year ~= "") and ("  (" .. PS.info.year .. ")") or "")
        table.insert(chunks, D.ev_text(cx, ty + 8, 5,
            string.format("\\b1\\fs%d\\c%s", fs - 6, U.ass_color(THEME.text_primary)), U.ass_escape(U.fit_text(line, pw, fs - 6))))
    end
    local afs = math.max(10, fs - 14)
    local lines = { "This product uses the TMDB API", "but is not endorsed or certified", "by TMDB." }
    for i, ln in ipairs(lines) do
        table.insert(chunks, D.ev_text(cx, ty + 32 + (i - 1) * (afs + 4), 5,
            string.format("\\fs%d\\c%s", afs, U.ass_color(THEME.text_muted)), U.ass_escape(U.fit_text(ln, pw, afs))))
    end
end

-- ============================================================
-- HOME: Netflix-style poster grid (poster edition only)
-- Rows of poster cards with the clean title underneath: Continue Watching and All Titles. Enter opens a
-- title page (episodes with TMDB stills) or resumes a Continue Watching card. Artwork is fetched from TMDB
-- lazily (what is on screen first, the next rows while idle), cached on disk, converted to BGRA with rounded
-- corners and shown with overlay-add. This product uses the TMDB API but is not endorsed or certified by TMDB.
-- ============================================================
local HV = {
    r = 1, c = 1, want_vc = 1, top = 1, rows = {}, sig = nil,
    items = {}, sn = 0, dn = 0, convq = {}, converting = false, batch_n = 0,
    shown = {}, hover = nil, vis = {}, hit = {}, vis_cards = {}, wanted = {},
    last_data = nil, last_click_t = 0, last_click = nil, m = nil, mode = "home",
}
local TV = { req = {}, sn = 0, card = nil }     -- title page of one show (episodes with TMDB stills)
HV.tv = TV

HV.PS1 = [==[
param([string]$Manifest)
Add-Type -AssemblyName System.Drawing
$fmt = [System.Drawing.Imaging.PixelFormat]::Format32bppPArgb
foreach ($line in [System.IO.File]::ReadAllLines($Manifest)) {
    $p = $line.Split('|')
    if ($p.Length -lt 4) { continue }
    try {
        $W = [int]$p[2]; $H = [int]$p[3]
        $src = [System.Drawing.Image]::FromFile($p[0])
        $bmp = New-Object System.Drawing.Bitmap($W, $H, $fmt)
        $g = [System.Drawing.Graphics]::FromImage($bmp)
        $g.InterpolationMode = [System.Drawing.Drawing2D.InterpolationMode]::HighQualityBicubic
        if ($p.Length -ge 5 -and $p[4] -eq 'lg') { $g.DrawImage($src, 0, 0, $W, $H) }
        else {
            # filled and cropped in the middle, never stretched (a 4:3 still, a poster in a 16:9 card)
            $k = [Math]::Max($W / $src.Width, $H / $src.Height)
            $cw = $W / $k; $ch = $H / $k
            $from = New-Object System.Drawing.RectangleF((($src.Width - $cw) / 2), (($src.Height - $ch) / 2), $cw, $ch)
            $g.DrawImage($src, (New-Object System.Drawing.RectangleF(0, 0, $W, $H)), $from, [System.Drawing.GraphicsUnit]::Pixel)
        }
        $g.Dispose(); $src.Dispose()
        $rect = New-Object System.Drawing.Rectangle(0, 0, $W, $H)
        $data = $bmp.LockBits($rect, [System.Drawing.Imaging.ImageLockMode]::ReadOnly, $fmt)
        $bytes = New-Object byte[] ($data.Stride * $H)
        [System.Runtime.InteropServices.Marshal]::Copy($data.Scan0, $bytes, 0, $bytes.Length)
        $bmp.UnlockBits($data); $bmp.Dispose()
        if ($p.Length -ge 5 -and $p[4] -ne '' -and $p[4] -ne 'lg') {
            # backdrop: the left 45 %, the bottom 30 % and the top 12 % fade out to transparent (premultiplied)
            if (-not ('WbFade' -as [type])) {
                Add-Type -TypeDefinition @"
public static class WbFade {
    static double S(double t) { t = t < 0 ? 0 : (t > 1 ? 1 : t); return t * t * (3 - 2 * t); }
    public static void Apply(byte[] b, int w, int h) {
        for (int y = 0; y < h; y++) {
            double ky = S((h - 1 - y) / (h * 0.30)) * S(y / (h * 0.12));
            for (int x = 0; x < w; x++) {
                double k = S(x / (w * 0.45)) * ky;
                int i = (y * w + x) * 4;
                b[i] = (byte)(b[i] * k + 0.5); b[i + 1] = (byte)(b[i + 1] * k + 0.5);
                b[i + 2] = (byte)(b[i + 2] * k + 0.5); b[i + 3] = (byte)(b[i + 3] * k + 0.5);
            }
        }
    }
}
"@
            }
            [WbFade]::Apply($bytes, $W, $H)
        }
        [System.IO.File]::WriteAllBytes($p[1], $bytes)
    } catch { }
}
]==]

local function hv_clamp(v, lo, hi) return math.max(lo, math.min(hi, v)) end

function HV.active() return browser_active and MS.view == "home" end
-- Title pages keep the hero band (poster, details, the selected episode's synopsis) fixed at the top; only the rows
-- under it scroll, so the synopsis of the episode you are on never scrolls away.
function HV.chips_open() return MS.hints and MS.hints.chips_open == true end
-- how far the chips row is open (0-1, eased): it slides in under the top row and the rows below move down with it
function HV.chip_k(m)
    if m.title then return 0 end
    local want = 0
    if HV.q ~= nil then want = 1
    elseif o.home_filter_chips and HV.chips ~= nil then want = ((not m.glass) or HV.chips_open()) and 1 or 0 end
    return HV.anim_val("chips", want, 0.24)
end
function HV.chips_on(m) return HV.chip_k(m) > 0.001 end
function HV.rows_y(m) return (m.title and m.ry1 or m.ry0) + math.floor(m.chip_h * HV.chip_k(m) + 0.5) end
-- "something arrived, draw again": one redraw a frame later, however many arrive meanwhile. It used to draw at once -
-- and a picture already on disk answers at once, from inside the page being drawn, so one page drew itself again
-- for every cached picture on it (a whole second for the add screen's home page: the stutter while posters load)
function HV.kick()
    if HV.kick_t then return end
    HV.kick_t = mp.add_timeout(0.016, function()
        HV.kick_t = nil
        if HV.active() then render() end
    end)
end
PS.on_kick = function() HV.kick() end
PS.pri_fn = function() return HV.cur_pri ~= nil and HV.cur_pri <= 0 end     -- requests made for what is on screen
-- a background change for whichever view is open: the poster page with its next frame, the list at once
MS.redraw_soon = function() if HV.active() then HV.kick() elseif browser_active then render() end end
PS.conv_mode = function() return HV.conv_mode() end

-- ---------- geometry ----------
-- Sizes come in steps, the way responsive websites do it: the window's height is rounded to the nearest step below,
-- every card, picture and text size is worked out from that step, and the actual width only decides how many cards
-- fit in a row and how wide the margins are. Inside a step a resize just reflows the grid (the same pictures move);
-- maximised and full screen on one monitor are a step apart at most, usually the same one. Pictures are converted
-- once per step and kept for the last few steps used.
HV.STEPS = { 480, 600, 720, 900, 1080, 1260, 1440, 1620, 1800, 2160, 2520, 2880, 3240, 4320 }
function HV.step_h(h)
    if not o.ui_size_steps then return h end
    local best, bd = h, math.huge
    for _, st in ipairs(HV.STEPS) do
        local d = math.abs(math.log(h / st))
        if d < bd then best, bd = st, d end
    end
    return best
end
-- widths only matter for caps on very narrow windows: in steps of 96 px
function HV.step_w(w)
    if not o.ui_size_steps then return w end
    return math.max(96, math.floor(w / 96 + 0.5) * 96)
end
-- w0, h0: the layout for another window size (what the cache cleanup keeps for the last few steps)
function HV.metrics(w0, h0)
    local w, h = U.canvas_size()
    if w0 and h0 then w, h = w0, h0 end
    local hs, ws = HV.step_h(h), HV.step_w(w)
    local pct = tonumber(o.home_card_pct) or 16
    local title = (HV.mode == "title")
    -- ONE scale for every screen, from the window height's step (1080 px = 1.0) times ui_scale. Cards and text used to have
    -- separate pixel caps per screen, so on a 4K window the home / season screens and the episode screen looked like
    -- two different zoom levels.
    local S = hs / 1080 * (tonumber(o.ui_scale) or 1)
    local lfs = math.max(12, math.floor(20 * S + 0.5))
    HV.R = ((tonumber(o.card_radius) or 0) > 0) and math.max(1, math.floor(o.card_radius * S + 0.5)) or 0
    HV.couch = HV.couch_on()
    if HV.couch then lfs = math.floor(lfs * 1.12 + 0.5) end
    local cw = hv_clamp(math.floor(hs * pct / 100 * (tonumber(o.ui_scale) or 1) + 0.5), 90, math.floor(hs * 0.45))
    local grid = title and TV.grid()
    if grid and (tonumber(o.season_card_pct) or 0) > 0 then          -- the season posters of a long show
        cw = hv_clamp(math.floor(hs * tonumber(o.season_card_pct) / 100 * (tonumber(o.ui_scale) or 1) + 0.5), 90, math.floor(hs * 0.45))
    end
    if title and not grid then
        cw = hv_clamp(math.floor(hs * (tonumber(o.episode_card_pct) or 26) / 100 * (tonumber(o.ui_scale) or 1)), 150, math.floor(ws * 0.45))   -- 16:9 episode stills
    end
    local gap = math.max(6, math.floor(cw * math.max(2, math.min(40, tonumber(o.card_gap_pct) or 9)) / 100))
    local side = math.max(24, math.floor(w * 0.025)) * 2            -- side margins grow with the window
    local per = math.max(2, math.floor((w - side + gap) / (cw + gap)))
    -- card_spread: the cards share the row's whole width (wider gaps) instead of leaving the rest on the right
    if o.card_spread and per > 1 then gap = math.min(math.floor(cw * 0.4), math.floor((w - side - per * cw) / (per - 1))) end
    local used = per * cw + (per - 1) * gap
    local m = { w = w, h = h, hs = hs, ws = ws, cw = cw, ch = (title and not grid) and math.floor(cw * 9 / 16) or math.floor(cw * 1.5), gap = gap, per = per, lfs = lfs }
    m.title = title
    m.mx = math.floor((w - used) / 2)
    -- the top bar: top_bar_scale (0.3 - 1.4) of its full height (3.2 lines of text); its text shrinks with it
    local tbs = math.max(0.3, math.min(1.4, tonumber(o.top_bar_scale) or 0.8))
    m.top_h = math.max(40, math.floor(lfs * 3.2 * tbs))
    -- the title page's band: poster, text and the buttons (More: taller, the whole synopsis)
    m.hero_h = title and math.floor(hs * (TV.more and 0.48 or (o.hero_poster == false and 0.25 or 0.31)) * math.max(0.8, math.min(1.3, (tonumber(o.hero_poster_pct) or 100) / 100))) or 0
    m.foot_h = math.max(44, math.floor(lfs * 3.5))
    -- EXPERIMENTAL glass bars: a row of pills floating at the top and at the bottom, nothing full-width
    if o.experimental_glass_bars then
        m.glass = true
        m.gm = math.max(8, math.floor(14 * S + 0.5))                 -- the air around the pills
        m.gph = math.max(24, math.floor(lfs * 1.85 + 0.5))           -- pill height
        m.gattr = math.max(10, math.floor((lfs - 6) * 1.4))          -- the TMDB line under the bottom pills
        m.top_h = m.gm + m.gph + m.gm
        m.foot_h = m.gm + m.gph + math.floor(m.gm * 0.4) + m.gattr + math.floor(m.gm * 0.5)
    end
    m.sec_h = math.floor(lfs * 2.9)                       -- a section heading and the air under it
    -- under the picture: the progress bar, kept clear of the focus ring (ring_pad out, then its stroke), then the label
    local rp = HV.couch and math.max(6, math.floor(6 * S + 0.5)) or 4
    m.bar_t = math.max(3, math.floor(4 * S + 0.5))
    m.bar_gap = rp + (HV.couch and math.max(4, math.floor(3.5 * S + 0.5)) or 2) + math.max(3, math.floor(3 * S + 0.5))
    m.bar_h = m.bar_gap + m.bar_t
    m.chip_h = math.floor(lfs * 2.4)
    m.S = S
    m.line_h = math.floor(lfs * 1.3)
    m.cfs, m.cdfs, m.label_h = HV.card_fonts(lfs)
    m.block_h = m.ch + m.bar_h + m.label_h + math.floor(lfs * 1.1)
    -- first row's y without / with the hero band (the hero leaves air under it, so its poster and the first card
    -- never touch - the selected card grows and has a focus ring)
    m.ry0, m.ry1 = m.top_h + 6, m.top_h + m.hero_h + math.max(18, math.floor(lfs * 1.2))
    m.sk = HV.skey(m.cw, m.ch)
    HV.grown(m)
    -- landscape rows (Continue Watching): 16:9 cards of their own size
    do
        local lw = hv_clamp(math.floor(hs * (tonumber(o.landscape_card_pct) or 25) / 100 * (tonumber(o.ui_scale) or 1)), 150, math.floor(ws * 0.45))
        local L = { cw = lw, ch = math.floor(lw * 9 / 16), gap = gap }
        L.per = math.max(1, math.floor((w - 2 * m.mx + gap) / (lw + gap)))
        L.block_h = L.ch + m.bar_h + m.label_h + math.floor(lfs * 1.1)
        L.sk = HV.skey(L.cw, L.ch)
        HV.grown(L)
        m.L = L
    end
    return m
end

-- The two lines under a card: the title and the rating · year · type line, card_label_pct of the normal text size.
-- returns title size, detail size, the height both take (with the air above them)
function HV.card_fonts(lfs)
    local p = math.max(40, math.min(130, tonumber(o.card_label_pct) or 60)) / 100
    local cfs = math.max(10, math.floor(lfs * p + 0.5))
    local cdfs = math.max(9, math.floor((lfs - 2) * p + 0.5))
    return cfs, cdfs, math.floor(cfs * 1.3) + math.floor(cdfs * 1.4) + math.floor(lfs * 0.45)
end
-- Font size of the outlined quality / rating chips on the title pages (1080p, REMUX, TV-14):
-- 40% under the old size, so they read as tags beside the meta line, not as buttons.
function HV.chip_fs(lfs)
    return math.max(9, math.floor((lfs - 5) * 0.6 + 0.5))
end
-- Size of the selected (slightly bigger) card: an even number of pixels more on each axis, so it stays centred.
function HV.grown(d)
    local g = math.max(1, math.min(1.15, tonumber(o.selected_grow) or 1))
    local ex = 2 * math.floor(d.cw * (g - 1) / 2 + 0.5)
    local ey = 2 * math.floor(d.ch * (g - 1) / 2 + 0.5)
    if ex < 2 or ey < 2 then d.gw = nil; return end
    d.gw, d.gh = d.cw + ex, d.ch + ey
    d.gsk = HV.skey(d.gw, d.gh)
end

-- Card size / cards per row / row height for one row (landscape rows have their own).
function HV.rowdim(row, m)
    if row and row.land and m.L then return m.L end
    return m
end

-- ---------- data ----------
-- Name of the folder whose title should be looked up: the folder itself or the nearest parent with a real title.
function PS.titled_name(p)
    for _ = 1, 4 do
        local pn = p:gsub("/+$", "")
        if pn == "" or pn == root_href:gsub("/+$", "") then return nil end
        local t = PS.title_of_name(U.basename(p))
        if t then return U.basename(p) end
        p = U.dirname(p)
    end
    return nil
end

-- Everything the poster lookup and the grouping need to know about a folder name.
function HV.ident(name)
    local title, year = PS.title_of_name(name)
    local fp = o.clean_titles and CT.parse_folder(name) or nil
    title = title or name
    year = year or ""
    local kp = (fp and fp.season) and "tv" or (year ~= "" and "movie" or "")
    return { title = title, year = year, fp = fp, kindpref = kp, raw = name,
             key = PS.norm(title) .. "|" .. year .. "|" .. kp }
end

-- Grouping key: every season of a show shares it ("Show.S01", "Show.S02", "Show Season 1" -> one card); films keep their year.
-- "Bleach USBD Remux TL" / "Bleach - Box 01" (no season tag, no year) used to get a key of their own and ended up as
-- a separate "Bleach (Box 01)" card next to "Bleach" (S17); now everything without a year joins the show's card.
function HV.gkey(name)
    local id = HV.ident(name)
    if o.merge_seasons and ((id.fp and id.fp.season) or id.year == "") then return PS.norm(id.title) end
    return PS.norm(id.title) .. "|" .. id.year
end

-- One detail part: text, colour, priority (the lowest priority is dropped first when the line is too long).
local function dp(t, col, prio) return { t = t, c = col, p = prio } end

function HV.chip_parts(chips, prio_base)
    local out = {}
    for _, ch in ipairs(chips or {}) do
        local pr = (ch == "4K" or ch == "1080p" or ch == "720p" or ch == "480p") and 8 or ((ch == "HDR" or ch == "HDR10+" or ch == "DV") and 6 or 5)
        out[#out + 1] = dp(ch, CT.chip_color(ch), pr)
    end
    return out
end

function HV.card_for_folder(e)
    local id = HV.ident(e.name)
    local fp = id.fp
    local parts = {}
    if fp then
        if fp.season then parts[#parts + 1] = dp(fp.season, THEME.text_muted, 6) end
        for _, p in ipairs(HV.chip_parts(fp.chips)) do parts[#parts + 1] = p end
        if fp.group then parts[#parts + 1] = dp(fp.group, THEME.text_dim, 7) end
    end
    return { kind = "folder", href = e.href, name = e.name, title = id.title, year = id.year, raw = e.name, kindpref = id.kindpref,
             parts = parts, key = id.key, gkey = HV.gkey(e.name), folders = { e }, mtime = e.mtime or 0 }
end

-- One card per show: folders with the same grouping key are merged (merge_seasons).
function HV.group_cards(dirs)
    local groups, order = {}, {}
    for _, e in ipairs(dirs) do
        local c = HV.card_for_folder(e)
        local g = o.merge_seasons and groups[c.gkey] or nil
        if g then
            g.folders[#g.folders + 1] = e
            if (e.mtime or 0) > g.mtime then g.mtime = e.mtime or 0 end
        else
            groups[c.gkey] = c
            order[#order + 1] = c
        end
    end
    for _, c in ipairs(order) do
        if #c.folders > 1 then
            table.sort(c.folders, function(a, b) return U.natural_less(a.name, b.name) end)
            local first, last = c.folders[1], c.folders[#c.folders]
            local f1 = HV.card_for_folder(first)
            local fl = HV.card_for_folder(last)
            c.href, c.name, c.raw = first.href, first.name, first.name
            c.title, c.year, c.key, c.kindpref = f1.title, f1.year, f1.key, f1.kindpref
            -- same title in several qualities/groups: say so, the title page lists each one
            local seasons = {}
            for _, f in ipairs(c.folders) do
                local fp = o.clean_titles and CT.parse_folder(f.name) or nil
                if fp and fp.season then seasons[fp.season] = true end
            end
            local nseasons = 0
            for _ in pairs(seasons) do nseasons = nseasons + 1 end
            c.parts = {}
            if nseasons > 1 then c.parts[1] = dp(string.format("%d seasons", nseasons), THEME.text_muted, 6)
            elseif c.kindpref ~= "movie" then
                local tagged = 0
                for _, f in ipairs(c.folders) do local fp_ = CT.parse_folder(f.name); if fp_ and fp_.season then tagged = tagged + 1 end end
                local one = (tagged == #c.folders) and next(seasons) or nil
                c.parts[1] = dp((one and (one .. " · ") or "") .. string.format("%d folders", #c.folders), THEME.text_muted, 6)
            else c.parts[1] = dp(string.format("%d versions", #c.folders), THEME.text_muted, 6) end
            for _, p in ipairs(HV.chip_parts(HV.best_chips(c.folders))) do c.parts[#c.parts + 1] = p end
        end
    end
    if o.merge_by_tmdb and PS.enabled() then order = HV.merge_by_tmdb(order) end
    -- two different titles that read the same (a 2019 film and a 2024 series): add the year / type to the label
    local count = {}
    for _, c in ipairs(order) do local k = PS.norm(c.title); count[k] = (count[k] or 0) + 1 end
    for _, c in ipairs(order) do
        if count[PS.norm(c.title)] > 1 then
            local tag
            if c.kindpref == "tv" then tag = (c.year ~= "") and (c.year .. " series") or "series"
            elseif c.kindpref == "movie" or c.year ~= "" then tag = (c.year ~= "") and c.year or "movie"
            else
                -- no season, no year: tell them apart by the folder name's own extra words ("Box 01", "USBD")
                local extra = tostring(c.raw or ""):gsub("%b[]", ""):gsub("%b()", ""):gsub("[%._]+", " ")
                extra = extra:gsub("^%s*" .. c.title:gsub("%p", "%%%0") .. "%s*", "", 1):gsub("^[%s%-:]+", ""):gsub("%s+$", "")
                tag = (extra ~= "" and #extra <= 18) and extra or nil
            end
            if tag then c.shown = c.title .. " (" .. tag .. ")" end
        end
    end
    return order
end

-- The quality tags of several folders as one set: the best resolution and every extra (HDR, DV, Remux...).
HV.RES_RANK = { ["4K"] = 4, ["1080p"] = 3, ["720p"] = 2, ["480p"] = 1 }
function HV.best_chips(folders)
    local best, extra, order = nil, {}, {}
    for _, f in ipairs(folders or {}) do
        local fp = o.clean_titles and CT.parse_folder(f.name) or nil
        for _, ch in ipairs(fp and fp.chips or {}) do
            local r = HV.RES_RANK[ch]
            if r then if not best or r > HV.RES_RANK[best] then best = ch end
            elseif not extra[ch] then extra[ch] = true; order[#order + 1] = ch end
        end
    end
    local out = { best }
    for _, ch in ipairs(order) do out[#out + 1] = ch end
    return out
end

-- merge_by_tmdb: cards whose lookups found the same TMDB title become one card.
function HV.merge_by_tmdb(order)
    PS.load_index()
    local by, out = {}, {}
    for _, c in ipairs(order) do
        local e = PS.idx[c.key]
        local tk = (type(e) == "table" and not e.none and e.id) and (tostring(e.kind) .. ":" .. PS.aid(e)) or nil
        local g = tk and by[tk]
        if g then
            for _, f in ipairs(c.folders) do g.folders[#g.folders + 1] = f end
            if c.mtime > g.mtime then g.mtime = c.mtime end
            g.merged = (g.merged or 1) + 1
        else
            if tk then by[tk] = c; c.tmdb = e end
            out[#out + 1] = c
        end
    end
    for _, c in ipairs(out) do
        if c.merged and c.tmdb then
            c.title, c.shown = c.tmdb.name or c.title, nil
            c.kindpref = c.tmdb.kind or c.kindpref
            local seasons = {}
            for _, f in ipairs(c.folders) do
                local s_ = TV.folder_season(f.name)
                if s_ then seasons[s_] = true end
            end
            local n = 0
            for _ in pairs(seasons) do n = n + 1 end
            c.parts = { dp(string.format("%d folders", #c.folders), THEME.text_muted, 6) }
            if n > 1 then c.parts[1] = dp(string.format("%d seasons · %d folders", n, #c.folders), THEME.text_muted, 9) end
            for _, p in ipairs(HV.chip_parts(HV.best_chips(c.folders))) do c.parts[#c.parts + 1] = p end
            c.parts[#c.parts + 1] = dp("merged", THEME.accent, 3)
        end
    end
    return out
end

-- TMDB image size for a card px wide on screen (4K screens get sharper downloads instead of upscaled w300/w342 ones).
function HV.img_size(kind, px)
    px = px or 0
    if kind == "poster" then return (px <= 342 and "w342") or (px <= 500 and "w500") or "w780" end
    if kind == "backdrop" then return (px <= 300 and "w300") or (px <= 780 and "w780") or "w1280" end
    -- episode stills: TMDB lists w300 and original, but serves the backdrop sizes too - 4 to 8 times less to download
    -- than original at 4K (should that size ever be refused, the picture comes as original and stills stay so)
    if px <= 300 then return "w300" end
    if PS.still_big_bad then return "original" end
    return (px <= 780) and "w780" or "w1280"
end

-- Continue Watching in landscape: the still of the episode you are in (TMDB), else the show's backdrop.
function HV.cw_still(c, e)
    local lw = HV.m and HV.m.L and HV.m.L.cw or 300
    if not PS.enabled() then return end
    PS.load_index()
    local show = PS.idx[c.key]
    -- not matched yet: the card waits (blank) for the match, then the row is built again with the right picture - it
    -- used to take the portrait poster and squeeze it into the 16:9 card until something else rebuilt the page
    if show == nil then c.land_wait = true; return end
    if type(show) ~= "table" or show.none or not show.id then return end
    local hint = TV.season_of(U.basename(e.dirpath or U.dirname(e.href)))
    local s_, e_ = TV.se_of(e.name, hint)
    if show.kind ~= "movie" and s_ and e_ then
        local info = PS.ep_info(show, s_, e_)
        if info and info.st and info.st ~= "" then
            c.key = string.format("still:%s:%d:%d", show.id, s_, e_)
            c.still = { size = HV.img_size("still", lw), path = info.st, base = string.format("s%s_%d_%d", show.id, s_, e_) }
            c.ep_name = info.n
            return
        end
        PS.load_eps()
        if PS.eps[show.id .. ":" .. s_] == nil then c.need = { entry = show, s = s_ } end
    end
    if show.backdrop_path and show.backdrop_path ~= "" then
        c.key = "bd:" .. PS.aid(show)
        c.still = { size = HV.img_size("backdrop", lw), path = show.backdrop_path, base = "b" .. PS.aid(show) }
    end
end

function HV.card_for_resume(e)
    local dir = e.dirpath or U.dirname(e.href)
    local tn = PS.titled_name(dir)
    local id = HV.ident(tn or U.basename(dir))
    local p = CT.parse(e.name)
    local hist = watch_history[e.href]
    local frac, parts = nil, {}
    if p and p.se then parts[#parts + 1] = dp(p.se, THEME.text_muted, 9) end
    if e.cw == "next" then
        parts[#parts + 1] = dp("Next up", THEME.accent, 9)
    elseif hist and hist.pos and hist.duration and hist.duration > 0 then
        frac = math.min(1, hist.pos / hist.duration)
        parts[#parts + 1] = dp(U.fmt_time(math.max(0, hist.duration - hist.pos)) .. " left", THEME.warn, 9)
    end
    return { kind = "play", entry = e, href = dir, name = e.name, title = id.title, year = id.year, raw = id.raw, kindpref = id.kindpref,
             parts = parts, frac = frac, key = id.key, gkey = tn and HV.gkey(tn) or dir }
end

HV.HOME_SORT = "webdav-browser://home"
function HV.sort_id()
    if HV.mode == "title" and TV.card then return "webdav-browser://title/" .. TV.card.key end
    return HV.HOME_SORT
end
function HV.sort_mode()
    local v = sort_by_dir[HV.sort_id()]
    if v == "recent" or v == "name" then return v end
    return (HV.mode == "home" and o.default_sort == "recent") and "recent" or "name"
end
function HV.toggle_sort()
    local nm = (HV.sort_mode() == "recent") and "name" or "recent"
    sort_by_dir[HV.sort_id()] = nm
    -- the cursor stays where it is on screen (it used to follow the selected card, which could be anywhere after re-sorting)
    HV.sig = nil
    status_line = "Sort: " .. (nm == "recent" and "Recent first" or (HV.mode == "title" and "Episode order" or "Name"))
    save_persistence()
    render()
end

-- ---------- search: typo-tolerant title matching + filters ----------
-- Filters typed into the search box (or toggled with the chips under it):
--   genre:anime  genre:"sci-fi"  year:2004  year:2000-2010  year:2010s  year:>2015  type:tv|movie  rating:8  unwatched  watched
HV.GENRES = { [28] = "Action", [12] = "Adventure", [16] = "Animation", [35] = "Comedy", [80] = "Crime", [99] = "Documentary",
    [18] = "Drama", [10751] = "Family", [14] = "Fantasy", [36] = "History", [27] = "Horror", [10402] = "Music", [9648] = "Mystery",
    [10749] = "Romance", [878] = "Science Fiction", [10770] = "TV Movie", [53] = "Thriller", [10752] = "War", [37] = "Western",
    [10759] = "Action & Adventure", [10762] = "Kids", [10763] = "News", [10764] = "Reality", [10765] = "Sci-Fi & Fantasy",
    [10766] = "Soap", [10767] = "Talk", [10768] = "War & Politics" }

HV.FILTER_KEYS = { genre = true, g = true, type = true, kind = true, rating = true, r = true, year = true, y = true }
function HV.parse_query(q)
    local f = { text = {}, genre = {}, tokens = {} }
    q = tostring(q or "")
    local rest = q:gsub('(%a+):"([^"]*)"', function(k, v) f.tokens[#f.tokens + 1] = { k:lower(), v } return " " end)
    for w in rest:gmatch("%S+") do
        local k, v = w:match("^(%a+):(.+)$")
        local lw = w:lower()
        if k and not HV.FILTER_KEYS[k:lower()] then k = nil end          -- "re:zero" is a title, not a filter
        if k then f.tokens[#f.tokens + 1] = { k:lower(), v }
        elseif lw == "unwatched" or lw == "is:unwatched" then f.unwatched = true
        elseif lw == "watched" or lw == "is:watched" then f.watched = true
        else f.text[#f.text + 1] = w end
    end
    f.years = {}
    for _, t in ipairs(f.tokens) do
        local k, v = t[1], t[2]:lower()
        if k == "genre" or k == "g" then f.genre[#f.genre + 1] = v
        elseif k == "type" or k == "kind" then f.kind = (v:match("^mov") or v:match("^film")) and "movie" or "tv"
        elseif k == "rating" or k == "r" then f.rmin = tonumber((v:gsub("[^%d%.]", "")))
        elseif k == "year" or k == "y" then
            -- every year token is a range; a title passes when it is in ANY of them (2000s + 1990s = both decades)
            local a, b = v:match("^(%d%d%d%d)%-(%d%d%d%d)$")
            local dec = v:match("^(%d%d%d)0s$")
            local y1, y2
            if a then y1, y2 = tonumber(a), tonumber(b)
            elseif dec then y1, y2 = tonumber(dec) * 10, tonumber(dec) * 10 + 9
            elseif v:match("^>=") then y1 = tonumber(v:match("%d+"))
            elseif v:match("^<=") then y2 = tonumber(v:match("%d+"))
            elseif v:match("^>") then y1 = (tonumber(v:match("%d+")) or 0) + 1
            elseif v:match("^<") then y2 = (tonumber(v:match("%d+")) or 10000) - 1
            elseif v:match("^%d%d%d%d$") then y1, y2 = tonumber(v), tonumber(v) end
            if y1 or y2 then f.years[#f.years + 1] = { y1, y2 } end
        end
    end
    f.y1, f.y2 = f.years[1] and f.years[1][1] or nil, f.years[1] and f.years[1][2] or nil      -- as before, for the first range
    f.query = table.concat(f.text, " ")
    f.any = (#f.genre > 0 or f.kind or f.rmin or #f.years > 0 or f.unwatched or f.watched) and true or false
    return f
end
function HV.text_of(q) return HV.parse_query(q).query end

-- Damerau-Levenshtein distance (small strings only).
-- edit distance with swapped neighbours (Damerau): three reused rows instead of a new table per cell row
HV.DR0, HV.DR1, HV.DR2 = {}, {}, {}
function HV.dist(a, b)
    local la, lb = #a, #b
    if math.abs(la - lb) > 2 then return 99 end
    local p2, p1, cur = HV.DR0, HV.DR1, HV.DR2
    for j = 0, lb do p1[j] = j end
    local byte = string.byte
    for i = 1, la do
        cur[0] = i
        local ai, ap = byte(a, i), (i > 1) and byte(a, i - 1) or nil
        for j = 1, lb do
            local bj = byte(b, j)
            local cost = (ai == bj) and 0 or 1
            local v = math.min(p1[j] + 1, cur[j - 1] + 1, p1[j - 1] + cost)
            if ap and j > 1 and ai == byte(b, j - 1) and ap == bj then
                v = math.min(v, p2[j - 2] + 1)
            end
            cur[j] = v
        end
        p2, p1, cur = p1, cur, p2
    end
    HV.DR0, HV.DR1, HV.DR2 = p2, p1, cur
    return p1[lb]
end
-- 0 = no match, up to 1 = exact. Every word you type has to match a word of the name: exactly, as its start, inside it,
-- or with a typo or two ("bleahc", "shipuden").
-- remembered per query: the page is rebuilt with every TMDB answer during a filter search, and the names repeat
function HV.fuzzy(query, name)
    local C = HV.FZ
    if not C or C.q ~= query then C = { q = query, m = {}, n = 0 }; HV.FZ = C end
    local hit = C.m[name]
    if hit then return hit end
    local sc = HV.fuzzy0(query, name)
    if C.n < 50000 then C.m[name], C.n = sc, C.n + 1 end
    return sc
end
function HV.fuzzy0(query, name)
    local qw, nw = {}, {}
    for w in query:lower():gmatch("[%w]+") do qw[#qw + 1] = w end
    for w in tostring(name):lower():gsub("['’]", ""):gmatch("[%w]+") do nw[#nw + 1] = w end
    if #qw == 0 or #nw == 0 then return 0 end
    local joined = table.concat(nw)
    local total = 0
    for _, q in ipairs(qw) do
        local best = 0
        for _, n in ipairs(nw) do
            local sc = 0
            if n == q then sc = 1
            elseif n:sub(1, #q) == q then sc = 0.9
            elseif #q >= 3 and n:find(q, 1, true) then sc = 0.75
            elseif #q >= 4 then
                local lim = (#q >= 8) and 2 or 1
                local d1 = HV.dist(q, n)
                local d2 = (#n > #q) and HV.dist(q, n:sub(1, #q)) or 99
                if math.min(d1, d2) <= lim then sc = 0.6 end
            end
            if sc > best then best = sc end
        end
        if best == 0 and #q >= 4 and joined:find(q, 1, true) then best = 0.7 end
        if best == 0 then return 0 end
        total = total + best
    end
    return total / #qw
end

-- Every name the library search matches a title by: the folder's, TMDB's, its original and other titles, the film
-- series - and with search_cast / search_keywords its cast and keywords.
function HV.card_names(c, e)
    local out = { c.title, c.shown }
    if e then
        out[#out + 1] = e.name
        for _, n in ipairs(type(e.alt) == "table" and e.alt or {}) do out[#out + 1] = n end
        if o.search_cast then for _, n in ipairs(type(e.cast) == "table" and e.cast or {}) do out[#out + 1] = n end end
        if o.search_keywords then for _, n in ipairs(type(e.kw) == "table" and e.kw or {}) do out[#out + 1] = n end end
    end
    return out
end
-- In the background, one title at a time while nothing else loads: TMDB details (and with them the names above) for
-- titles that were matched before v26. Kept for good, like every match.
function HV.details_bg()
    if (HV.dbg_n or 0) > 0 or not PS.enabled() or not PS.idx then return end
    if (HV.sn or 0) > 0 or (HV.dn or 0) > 0 then return end
    HV.dbg_tried = HV.dbg_tried or {}
    -- eight at a time: they go out together in one curl process (one at a time was a process per title)
    HV.dbg_n = 0
    for k, e in pairs(PS.idx) do
        if HV.dbg_n >= 8 then break end
        if type(e) == "table" and e.id and not e.none and e.dv ~= 26 and k ~= "__v" and not HV.dbg_tried[k] then
            HV.dbg_tried[k] = true
            HV.dbg_n = HV.dbg_n + 1
            PS.details(e, function()
                HV.dbg_n = HV.dbg_n - 1
                if HV.dbg_n == 0 then mp.add_timeout(0.4, function() if browser_active then HV.details_bg() end end) end
            end)
        end
    end
end

-- Facts a filter needs about one title card.
function HV.card_facts(c)
    PS.load_index()
    local e = PS.idx[c.key]
    e = (type(e) == "table" and not e.none) and e or nil
    local gen = {}
    if e and type(e.gen) == "table" and #e.gen > 0 then for _, g in ipairs(e.gen) do gen[#gen + 1] = tostring(g):lower() end
    elseif e and type(e.g) == "table" then for _, id in ipairs(e.g) do if HV.GENRES[tonumber(id)] then gen[#gen + 1] = HV.GENRES[tonumber(id)]:lower() end end end
    local year = tonumber((e and e.year ~= "" and e.year) or c.year)
    -- not matched (yet): the folder names still tell anime apart (fansub tags, romaji titles)
    local hint = nil
    if not e then
        hint = PS.romaji(c.title) and true or false
        for _, fo in ipairs(c.folders or {}) do if PS.animeish(fo.name) then hint = true end end
    end
    -- the type: TMDB's, else the folder name's (a season tag = series, a bare year = film), else the season folders
    local kind = (e and e.kind) or (c.kindpref ~= "" and c.kindpref or nil)
    if not kind then
        for _, fo in ipairs(c.folders or {}) do if TV.folder_season(fo.name) then kind = "tv" end end
        if not kind and year and not c.merged then kind = "movie" end
    end
    return { gen = gen, year = year, kind = kind, known = e ~= nil,
             anime_hint = hint, vote = e and tonumber(e.vote) or nil, lang = e and e.lang or nil, names = HV.card_names(c, e) }
end

-- top-level folders you have watched something in / finished something in
function HV.watch_sets()
    local rootn = root_href:gsub("/+$", "")
    local any = {}
    local function top(h)
        local t = tostring(h):match("^(" .. rootn:gsub("%p", "%%%0") .. "/[^/]+)")
        return t
    end
    for h in pairs(watched_set) do local t = top(h); if t then any[t] = true end end
    for h, rec in pairs(watch_history) do if rec.pos then local t = top(h); if t then any[t] = true end end end
    return any
end

function HV.passes(c, f, facts, watched_any)
    if f.kind and facts.kind ~= f.kind then return false end
    if f.rmin and not (facts.vote and facts.vote >= f.rmin) then return false end
    if #(f.years or {}) > 0 then
        local y = facts.year
        local hit = false
        for _, r in ipairs(f.years) do
            if y and (not r[1] or y >= r[1]) and (not r[2] or y <= r[2]) then hit = true end
        end
        if not hit then return false end
    end
    -- genres: any of them (Sci-Fi + Action = either), as the chips read
    if #f.genre > 0 then
        local any = false
        for _, g in ipairs(f.genre) do
            local ok = false
            if g == "anime" then
                for _, x in ipairs(facts.gen) do if x == "animation" then ok = (facts.lang == "ja") or facts.lang == nil end end
                if not facts.known and facts.anime_hint then ok = true end
            else
                local gn = g:gsub("[^%w]", "")
                for _, x in ipairs(facts.gen) do if x:gsub("[^%w]", ""):find(gn, 1, true) then ok = true end end
            end
            if ok then any = true end
        end
        if not any then return false end
    end
    if f.unwatched or f.watched then
        local seen = false
        for _, fo in ipairs(c.folders or {}) do if watched_any[fo.href:gsub("/+$", "")] then seen = true end end
        if f.unwatched and seen then return false end
        if f.watched and not seen then return false end
    end
    return true
end

-- Show cards for the library search: fuzzy title matches first, then titles whose files/folders matched, then filters.
function HV.search_cards(groups)
    local f = HV.parse_query(HV.qa or HV.q)
    local scored, seen = {}, {}
    local function add(c, sc)
        if seen[c] then if sc > seen[c].sc then seen[c].sc = sc end return end
        local item = { c = c, sc = sc }
        seen[c] = item
        scored[#scored + 1] = item
    end
    if f.query == "" then
        if f.any then for _, c in ipairs(groups) do add(c, 1) end end
    else
        for _, c in ipairs(groups) do
            local facts = HV.card_facts(c)
            local best = 0
            for _, nm in ipairs(facts.names) do if nm then best = math.max(best, HV.fuzzy(f.query, nm)) end end
            for _, fo in ipairs(c.folders or {}) do
                local fp = CT.parse_folder(fo.name)
                if fp and fp.alt then best = math.max(best, HV.fuzzy(f.query, fp.alt)) end
            end
            if best > 0 then add(c, 1 + best) end
        end
        -- files / folders inside titles (library index)
        local byhref = {}
        for _, c in ipairs(groups) do for _, fo in ipairs(c.folders) do byhref[fo.href:gsub("/+$", "")] = c end end
        for _, r in ipairs(search_results or {}) do
            local h = (r.is_dir and r.href or r.dirpath or r.href):gsub("/+$", "")
            local guard = 0
            while guard < 12 and h ~= "" and not byhref[h] do
                local up = U.dirname(h .. "/"):gsub("/+$", "")
                if up == h then break end
                h = up
                guard = guard + 1
            end
            if byhref[h] then add(byhref[h], 0.5) end
        end
    end
    local out = {}
    local wa = (f.unwatched or f.watched) and HV.watch_sets() or {}
    -- filters need TMDB data, which is normally only fetched for what is on screen: look the rest up in the background
    HV.filter_pending = nil
    if f.any and PS.enabled() then
        PS.load_index()
        local pend = {}
        for _, it in ipairs(scored) do if PS.idx[it.c.key] == nil then pend[#pend + 1] = it.c end end
        HV.filter_pending = (#pend > 0) and pend or nil
    end
    for _, it in ipairs(scored) do
        if not f.any or HV.passes(it.c, f, HV.card_facts(it.c), wa) then out[#out + 1] = it end
    end
    table.sort(out, function(a, b)
        if a.sc ~= b.sc then return a.sc > b.sc end
        return U.natural_less(a.c.title, b.c.title)
    end)
    local cards = {}
    for i, it in ipairs(out) do cards[i] = it.c end
    return cards
end

-- Filter chips under the search box (click to toggle; they just edit the text in the box).
function HV.chip_defs(groups)
    local defs = {
        { label = "TV", tok = "type:tv" }, { label = "Movies", tok = "type:movie" }, { label = "Unwatched", tok = "unwatched" },
        { label = "★ 8+", tok = "rating:8" }, { label = "Anime", tok = "genre:anime" },
    }
    -- the library's most common genres and decades
    local gc, dc = {}, {}
    for _, c in ipairs(groups or {}) do
        local fa = HV.card_facts(c)
        for _, g in ipairs(fa.gen) do gc[g] = (gc[g] or 0) + 1 end
        if fa.year then local d = math.floor(fa.year / 10) * 10; dc[d] = (dc[d] or 0) + 1 end
    end
    local gl, dl = {}, {}
    for g in pairs(gc) do if g ~= "animation" then gl[#gl + 1] = g end end
    table.sort(gl, function(a, b) return gc[a] > gc[b] end)
    for i = 1, math.min(5, #gl) do
        local name = gl[i]:gsub("(%a)([%w']*)", function(a, b) return a:upper() .. b end)
        defs[#defs + 1] = { label = name, tok = 'genre:"' .. gl[i] .. '"' }
    end
    for d in pairs(dc) do dl[#dl + 1] = d end
    table.sort(dl, function(a, b) return a > b end)
    for i = 1, math.min(4, #dl) do defs[#defs + 1] = { label = dl[i] .. "s", tok = "year:" .. dl[i] .. "s" } end
    return defs
end
-- Words of the query; a quoted value (genre:"science fiction") stays one word.
function HV.q_words(q)
    local out, i = {}, 1
    q = tostring(q or "")
    while i <= #q do
        local a, b = q:find("^%S-\"[^\"]*\"", i)
        if not a then a, b = q:find("^%S+", i) end
        if a then out[#out + 1] = q:sub(a, b); i = b + 1 else i = i + 1 end
    end
    return out
end

-- the home page's filter (home_filter_chips): the same tokens as a search, kept in the data file
function HV.hf_get() return tostring(MS.hints and MS.hints.home_filter or "") end
function HV.hf_toggle(tok)
    local words, kept, had = HV.q_words(HV.hf_get()), {}, false
    local key = tok:match("^(%a+):")
    for _, w in ipairs(words) do
        if w:lower() == tok:lower() then had = true
        elseif key == "type" and w:lower():match("^type:") then
        else kept[#kept + 1] = w end
    end
    if not had then kept[#kept + 1] = tok end
    MS.hints = MS.hints or {}
    MS.hints.home_filter = table.concat(kept, " ")
    if save_persistence then save_persistence() end
    HV.r, HV.c, HV.top, HV.want_vc = 1, 1, 1, 1
    HV.sig = nil
    render()
end
function HV.hf_apply(groups)
    local q = HV.hf_get()
    if q == "" then return groups end
    local f = HV.parse_query(q)
    if not f.any then return groups end
    local wa = (f.unwatched or f.watched) and HV.watch_sets() or {}
    local out = {}
    for _, c in ipairs(groups) do if HV.passes(c, f, HV.card_facts(c), wa) then out[#out + 1] = c end end
    return out
end
function HV.toggle_token(tok)
    local words, kept, had = HV.q_words(HV.q), {}, false
    local key = tok:match("^(%a+):")
    for _, w in ipairs(words) do
        if w:lower() == tok:lower() then had = true
        elseif key == "type" and w:lower():match("^type:") then -- "type:tv" and "type:movie" exclude each other
        else kept[#kept + 1] = w end
    end
    if not had then kept[#kept + 1] = tok end
    local q = table.concat(kept, " ")
    HV.q = (q:gsub("^%s+", ""):gsub("%s+$", ""))
    HV.qa = HV.q
    HV.cur = #HV.q
    search_query = HV.text_of(HV.q)
    run_global_search_hook()
    HV.r, HV.c, HV.top, HV.want_vc = 1, 1, 1, 1
    HV.sig = nil
    render()
end


-- the Continue Watching cards (shows of the library get their card's name and key)
function HV.cw_cards(groups)
    local bygk = {}
    for _, c in ipairs(groups) do bygk[c.gkey] = c end
    local cards, seen = {}, {}
    for _, e in ipairs(get_continue_list() or {}) do
        local c = HV.card_for_resume(e)
        local gc = bygk[c.gkey]
        if gc then c.key, c.title, c.year, c.raw, c.kindpref, c.shown = gc.key, gc.title, gc.year, gc.raw, gc.kindpref, gc.shown end
        if o.continue_landscape then HV.cw_still(c, e) end
        local d = o.merge_seasons and c.gkey or (e.dirpath or "")
        if not seen[d] then seen[d] = true; cards[#cards + 1] = c end
    end
    return cards
end

function HV.build(m)
    if HV.mode == "title" then return TV.build(m) end
    local rows = {}
    local root = find_cached_dir(root_href)
    local dirs = {}
    if root and type(root.entries) == "table" then
        for _, e in ipairs(root.entries) do if e.is_dir then dirs[#dirs + 1] = e end end
    end
    local groups = (#dirs > 0) and HV.group_cards(dirs) or {}

    -- library search, on the home page itself: nothing typed yet = the home page as it is; then Continue Watching
    -- narrows to what matches and the results take All Titles' place (no separate, blank page)
    HV.search_empty = false
    if HV.q and (HV.qa or HV.q) ~= "" then
        HV.chips = HV.chip_defs(groups)
        local cards = HV.search_cards(groups)
        local q = HV.qa or HV.q
        -- titles are always complete (they come from the library listing); only the file-name index can still be crawling
        local note = MS.idx_running and "  ·  file index still building" or ""
        if HV.filter_pending then note = string.format("  ·  looking up %d more title%s for the filter…", #HV.filter_pending, #HV.filter_pending == 1 and "" or "s") .. note end
        rows[1] = { title = string.format("Search \"%s\"  ·  %d title%s%s", q, #cards, #cards == 1 and "" or "s", note), cards = {}, off = 0 }
        local i = 1
        while i <= #cards do
            local part = {}
            for j = i, math.min(#cards, i + m.per - 1) do part[#part + 1] = cards[j] end
            rows[#rows + 1] = { title = (i == 1) and rows[1].title or nil, cards = part, off = 0 }
            i = i + m.per
        end
        if #cards == 0 then rows = {} else table.remove(rows, 1) end
        for _, r in ipairs(rows) do r.res = true end
        if o.continue_row then
            local hit = {}
            for _, c in ipairs(cards) do if c.gkey then hit[c.gkey] = true end end
            local cw = {}
            for _, c in ipairs(HV.cw_cards(groups)) do if hit[c.gkey] then cw[#cw + 1] = c end end
            if #cw > 0 then table.insert(rows, 1, { title = "Continue Watching", cards = cw, shelf = true, off = 0, land = o.continue_landscape or nil }) end
        end
        HV.search_empty = #rows == 0
        return rows
    end

    if o.continue_row then
        local cards = HV.cw_cards(groups)
        local cflt = o.home_filter_chips and HV.hf_get() or ""
        if cflt ~= "" and #cards > 0 then
            local f = HV.parse_query(cflt)
            if f.any then
                local wa = (f.unwatched or f.watched) and HV.watch_sets() or {}
                local kept = {}
                for _, c in ipairs(cards) do if HV.passes(c, f, HV.card_facts(c), wa) then kept[#kept + 1] = c end end
                cards = kept
            end
        end
        if #cards > 0 then table.insert(rows, 1, { title = "Continue Watching", cards = cards, shelf = true, off = 0, land = o.continue_landscape or nil }) end
    end
    if o.home_filter_chips then HV.chips = HV.chip_defs(groups) end
    local flt = o.home_filter_chips and HV.hf_get() or ""
    if #groups > 0 then
        local all = {}
        for i, c in ipairs(flt ~= "" and HV.hf_apply(groups) or groups) do all[i] = c end
        local recent = (HV.sort_mode() == "recent")
        table.sort(all, function(a, b)
            if recent and a.mtime ~= b.mtime then return a.mtime > b.mtime end
            return U.natural_less(a.title, b.title)
        end)
        local first = true
        local i = 1
        while i <= #all do
            local cards = {}
            for j = i, math.min(#all, i + m.per - 1) do cards[#cards + 1] = all[j] end
            rows[#rows + 1] = { title = first and string.format("%s  ·  %d  ·  Sort: %s  ⇅", flt ~= "" and "Titles" or "All Titles", #all, recent and "Recently added" or "Name") or nil,
                sort_hdr = first or nil, cards = cards, off = 0 }
            first = false
            i = i + m.per
        end
    end
    return rows
end

-- ---------- selection ----------
function HV.clamp()
    local n = #HV.rows
    if n == 0 then HV.r, HV.c = 1, 1; return end
    HV.r = hv_clamp(HV.r, 1, n)
    HV.c = hv_clamp(HV.c, 1, #HV.rows[HV.r].cards)
end

function HV.fix_off(m)
    local row = HV.rows[HV.r]
    if not row or not row.shelf then return end
    local per = HV.rowdim(row, m).per
    if HV.c <= row.off then row.off = HV.c - 1
    elseif HV.c > row.off + per then row.off = HV.c - per end
    row.off = hv_clamp(row.off, 0, math.max(0, #row.cards - per))
end

function HV.vcol()
    local row = HV.rows[HV.r]
    return HV.c - ((row and row.off) or 0)
end

function HV.move(dr, dc)
    if HV.CM.open then if dr ~= 0 then HV.CM.move(dr) end return end
    if HV.TK.is_open() then if dr ~= 0 then HV.TK.move(dr) end return end
    if HV.dlc() then if dr ~= 0 then TV.dl_move(dr) end return end
    local m = HV.metrics()
    HV.m = m
    HV.clamp()
    -- the title page's buttons: ↑ from the first row of cards, ← → between them, ↓ back to the cards
    if HV.mode == "title" and TV.btns and #TV.btns > 0 then
        if HV.bfocus then
            if dc ~= 0 then HV.bfocus = hv_clamp(HV.bfocus + dc, 1, #TV.btns)
            elseif dr > 0 and #HV.rows > 0 then HV.bfocus = nil end
            HV.sig, HV.last_data = nil, nil
            return render()
        elseif dr < 0 and (HV.r <= 1 or #HV.rows == 0) then
            HV.bfocus = 1
            HV.sig, HV.last_data = nil, nil
            return render()
        end
    end
    if #HV.rows == 0 then return end
    -- a held key (steps under 0.11 s apart): the bigger picture of the selected card waits until it is let go
    local now = U.now_s()
    HV.krep = now - (HV.move_t or 0) < 0.11
    HV.move_t = now
    if HV.krep then
        mp.add_timeout(0.12, function() if HV.move_t == now and browser_active then HV.last_data = nil; render() end end)
    end
    if dc ~= 0 then
        local row = HV.rows[HV.r]
        local nc = HV.c + dc
        local r0, c0 = HV.r, HV.c
        if nc < 1 then
            local prev = HV.rows[HV.r - 1]
            if not row.shelf and prev and not prev.shelf then HV.r = HV.r - 1; nc = #prev.cards else nc = 1 end
        elseif nc > #row.cards then
            local nxt = HV.rows[HV.r + 1]
            if not row.shelf and nxt and not nxt.shelf then HV.r = HV.r + 1; nc = 1 else nc = #row.cards end
        end
        if HV.r == r0 and nc == c0 then HV.XA.bump("h", r0, dc) end          -- the end of the row: it bounces
        HV.c = nc
        HV.fix_off(m)
        HV.want_vc = HV.vcol()
    end
    if dr ~= 0 then
        local nr = hv_clamp(HV.r + dr, 1, #HV.rows)
        if nr == HV.r then HV.XA.bump("v", nil, dr) end                      -- the end of the page: it bounces
        HV.r = nr
        local row = HV.rows[nr]
        HV.c = hv_clamp((row.off or 0) + HV.want_vc, 1, #row.cards)
        HV.fix_off(m)
    end
    render()
end

function HV.edge(first)
    HV.clamp()
    if #HV.rows == 0 then return end
    if first then HV.r, HV.c = 1, 1 else HV.r = #HV.rows; HV.c = #HV.rows[HV.r].cards end
    HV.fix_off(HV.metrics())
    HV.want_vc = HV.vcol()
    render()
end

function HV.selected()
    HV.clamp()
    local row = HV.rows[HV.r]
    return row and row.cards[HV.c] or nil
end

-- ---------- poster pipeline ----------
function HV.lookup(w, st)
    PS.load_index()
    local ik = w.key
    local hit = PS.idx[ik]
    -- 26.10: an old weak match (recheck), or a match from before 26.10 of a folder that is a box set, is looked up again;
    -- the old one stays should the new rules find nothing
    local old = nil
    if type(hit) == "table" and not hit.none and not hit.coll and not hit.cqc and not (PS.recheck_done or {})[ik]
        and (hit.recheck or (not (tostring(w.raw or ""):lower():find("%f[%w]s%d+")) and (PS.coll_query(w.title or "") or PS.coll_query(w.raw)))) then
        PS.recheck_done = PS.recheck_done or {}
        PS.recheck_done[ik] = true
        old, hit = hit, nil
    end
    -- matched while AniList was unreachable: ask again once per session (the old answer stays until a better one comes)
    if type(hit) == "table" and hit.ale and o.anime_lookup and not (PS.ale_retry or {})[ik] then
        PS.ale_retry = PS.ale_retry or {}
        PS.ale_retry[ik] = true
        hit = nil
    end
    if hit ~= nil then
        if hit == false or hit.none then st.state = "none" else st.entry, st.state = hit, "entry" end
        st.tried = type(hit) == "table" and hit.tried or nil
        return
    end
    st.state = "searching"
    st.tried = {}
    local ale = nil         -- set when AniList could not be reached
    HV.sn = HV.sn + 1
    local function store(r, q, extra)
        local entry = {
            id = tostring(r.id or "0"), name = r.name or r.title or "?", kind = r.media_type,
            year = (r.first_air_date or r.release_date or ""):sub(1, 4), poster_path = r.poster_path,
            overview = tostring(r.overview or ""):sub(1, 600), backdrop_path = r.backdrop_path or "",
            vote = tonumber(r.vote_average) or 0, q = q,
            g = type(r.genre_ids) == "table" and r.genre_ids or nil, lang = r.original_language, tried = st.tried,
        }
        if type(r.genres) == "table" and not entry.g then          -- details replies list genres as objects
            entry.g = {}
            for _, gg in ipairs(r.genres) do entry.g[#entry.g + 1] = gg.id end
        end
        for k, v in pairs(extra or {}) do entry[k] = v end   -- s (season the folder holds), ms / mo / me (anime map)
        entry.cqc = true                                     -- matched by the 26.10 rules (box sets checked)
        PS.idx[ik] = entry
        PS.idx_ver = PS.idx_ver + 1
        st.entry, st.state = entry, "entry"
    end
    local function finish(r, q, extra)            -- r: TMDB result | false (nothing) ; nil = network error (st set)
        HV.sn = HV.sn - 1
        if r == false and old then
            old.recheck, old.cqc = nil, true           -- nothing better: the old match stays, and is not asked about again
            PS.idx[ik] = old
            PS.idx_ver = PS.idx_ver + 1
            st.entry, st.state = old, "entry"
            PS.save_index(old)
            HV.kick()
            return
        end
        if r == false then
            PS.idx[ik] = { none = true, tried = st.tried, ale = ale }
            st.state = "none"
        elseif r then
            extra = extra or {}
            extra.ale = ale
            store(r, q, extra)
        end
        if r ~= nil then PS.save_index() end
        HV.kick()
    end
    local function net_error(err)
        HV.sn = HV.sn - 1
        st.state, st.err, st.t = "error", err, mp.get_time()
        HV.kick()
    end
    -- 1. poster_overrides from the conf always win
    local ov = PS.override_for(w.raw, w.title)
    if ov then
        st.tried[#st.tried + 1] = "poster_overrides: " .. ov.kind .. ":" .. ov.id
        PS.api(string.format("/%s/%s?language=en-US", ov.kind, ov.id), function(d, err, code)
            if d then d.media_type = ov.kind; finish(d, "poster_overrides", { s = ov.s })
            elseif code == 404 then st.tried[#st.tried + 1] = "(not on TMDB)"; finish(false)
            else net_error(err) end
        end)
        return
    end
    local anime = (PS.animeish(w.raw or "") or PS.romaji(w.title)) and true or false
    local al_tried = false
    local urg = PS.pri_fn and PS.pri_fn() or false
    -- a box set: TMDB's collection (its poster, backdrop and overview). The entry is the collection's first film, marked
    -- `coll` so its pictures are kept apart from that film's own and no film details overwrite it.
    local rl = tostring(w.raw or w.title or ""):lower()
    local cq = nil
    if not (rl:find("%f[%w]s%d+") or rl:find("season", 1, true)) then        -- (a series' "Complete Collection" is no box set)
        -- the clean title, else the folder name itself ("Harry Potter Complete Collection": the title lost the word)
        cq = PS.coll_query(w.title or "") or PS.coll_query(w.raw)
    end
    local function via_collection(fallback)
        st.tried[#st.tried + 1] = "collection: " .. cq
        local u0 = PS.U_ctx
        PS.U_ctx = urg
        PS.api("/search/collection?language=en-US&query=" .. U.url_encode_segment(cq), function(d, err, code)
            if not d then if code == 0 or (code or 0) >= 500 or code == 401 then return net_error(err) end return fallback() end
            -- the collection named exactly so, else one whose name and the folder's share nearly all words both ways
            -- ("The Fast and the Furious" / "Fast and Furious"; not "Sherlock Holmes" for "Sherlock"). A folder that
            -- looks like a series ("Complete Collection") only takes an exact name.
            local best, near
            for _, r in ipairs(type(d.results) == "table" and d.results or {}) do
                local nm = tostring(r.name or ""):gsub("%s+[Cc]ollection$", "")
                if r.id and r.poster_path and r.poster_path ~= "" then
                    if PS.pnorm(nm) == PS.pnorm(cq) then best = r break end
                    if not near and w.kindpref ~= "tv" and PS.overlap2(nm, cq) >= 0.75 then near = r end
                end
            end
            best = best or near
            if not best then st.tried[#st.tried + 1] = "(no collection)"; return fallback() end
            local u1 = PS.U_ctx
            PS.U_ctx = urg
            PS.api("/collection/" .. tostring(best.id) .. "?language=en-US", function(cd, err2, code2)
                if not cd then if code2 == 0 or (code2 or 0) >= 500 then return net_error(err2) end return fallback() end
                local parts = {}
                for _, pt in ipairs(type(cd.parts) == "table" and cd.parts or {}) do
                    if type(pt) == "table" and pt.id and (pt.release_date or "") ~= "" then parts[#parts + 1] = pt end
                end
                table.sort(parts, function(a, b) return tostring(a.release_date) < tostring(b.release_date) end)
                local first = parts[1]
                if not first then return fallback() end
                local gen, g = {}, type(first.genre_ids) == "table" and first.genre_ids or {}
                for _, gi in ipairs(g) do if HV.GENRES[tonumber(gi)] then gen[#gen + 1] = HV.GENRES[tonumber(gi)] end end
                local last = parts[#parts]
                finish({ id = first.id, media_type = "movie", title = cd.name or best.name, release_date = first.release_date,
                         poster_path = best.poster_path, backdrop_path = (best.backdrop_path ~= nil and best.backdrop_path ~= "") and best.backdrop_path or first.backdrop_path,
                         overview = (cd.overview ~= nil and cd.overview ~= "") and cd.overview or best.overview, vote_average = first.vote_average,
                         genre_ids = g, original_language = first.original_language },
                       "collection: " .. cq, { coll = tostring(best.id), detail = true, dv = 26, gen = gen, logo = "", logo_asked = true, rt = 0,
                         yr2 = last and tostring(last.release_date):sub(1, 4) or "", nparts = #parts, alt = { tostring(best.name or "") } })
            end)
            PS.U_ctx = u1
        end)
        PS.U_ctx = u0
    end
    -- 2. anime: AniList + the anime-lists map (exact TMDB id, season, episode offset)
    local function via_anilist(fallback)
        al_tried = true
        PS.anime_lookup(w, st.tried, function(r, err)
            if r then
                local extra = { s = r.s, ms = r.ms, mo = r.mo, me = r.me, mseason = r.ms and (TV.season_of(w.raw or "") or 0) or nil }
                finish(r.d, r.q, extra)
            else
                if err and tostring(err):find("AniList", 1, true) then ale = true end
                fallback()
            end
        end)
    end
    -- 3. TMDB search ladder: alias / alternative title first, then the folder title, then shorter forms
    local function ladder()
        local qs, seen = {}, {}
        local function addq(q, trust, season)
            if not q or q == "" or seen[q:lower()] then return end
            seen[q:lower()] = true
            qs[#qs + 1] = { q = q, trust = trust, s = season }
        end
        local al = PS.alias_for(w.raw, w.title)
        if al then addq(al[2], true, al[3]) end
        local fp = w.raw and CT.parse_folder(w.raw) or nil
        if fp and fp.alt then addq(fp.alt, true) end
        for i, q in ipairs(PS.queries(w.raw or w.title, w.title, w.year)) do addq(q, i <= 2) end
        -- no season tag and no year: release names of films nearly always carry a year, so lean towards TV
        local kp = w.kindpref
        if (kp or "") == "" and (anime or (w.year or "") == "") then kp = "tv" end
        local i, any = 0, nil
        local function accept(r, q, season, weak)
            -- a weak answer (closest result, shortened query, nothing) gets a second opinion from AniList first
            if weak and o.anime_lookup and not al_tried then
                via_anilist(function() if r then finish(r, q, { s = season }) else finish(false) end end)
            elseif r then finish(r, q, { s = season })
            else finish(false) end
        end
        local function step()
            i = i + 1
            if i > #qs then accept(any, "(closest result)", nil, true) return end
            local item = qs[i]
            st.tried[#st.tried + 1] = item.q
            local u0 = PS.U_ctx
            PS.U_ctx = urg                     -- the next search of an on-screen lookup is on-screen too
            PS.search(item.q, w.year or "", nil, function(r, err, a)
                if r == nil then net_error(err) return end
                if r then accept(r, item.q, item.s, not item.trust) return end
                any = any or a
                step()
            end, kp, true, { full = (not item.trust) and w.title or nil, anime = anime })
            PS.U_ctx = u0
        end
        step()
    end
    local function main() if o.anime_lookup and anime then via_anilist(ladder) else ladder() end end
    if cq then via_collection(main) else main() end
end

function HV.download(st)
    local e = st.entry
    if type(e.poster_path) ~= "string" or e.poster_path == "" then st.state = "none"; return end
    local size = HV.img_size("poster", HV.m and (HV.m.gw or HV.m.cw) or 300)
    local jpg = PS.jpg_for("p" .. PS.aid(e), size)
    st.jpg, st.base, st.re = jpg, "p" .. PS.aid(e), "entry"
    local ji = utils.file_info(jpg)
    if ji and ji.size > 1000 then st.state = "jpg"; return end
    st.state = "downloading"
    HV.dn = HV.dn + 1
    PS.http({ url = o.tmdb_image_base .. size .. e.poster_path, out = jpg, timeout = 30 },
        function(code)
            HV.dn = HV.dn - 1
            local info = utils.file_info(jpg)
            if code ~= 200 or not info or info.size < 1000 then
                st.state, st.err, st.t = "error", "poster download failed", mp.get_time()
            else
                st.state = "jpg"
                PS.st_dirty = true
                PS.save_index()     -- the cache folder exists now
            end
            HV.kick()
        end)
end

-- ---------- artwork conversion (jpg -> raw BGRA for overlay-add) ----------
-- auto: ffmpeg when it runs (a single fast process per image), else PowerShell + GDI+ on Windows, else ImageMagick.
-- ffmpeg is probed once per session.
function HV.conv_mode()
    local mode = o.poster_converter
    if mode ~= "auto" then return mode end
    if HV.ff_ok ~= nil then
        if HV.ff_ok then return "ffmpeg" end
        return (package.config:sub(1, 1) == "\\") and "powershell" or "magick"
    end
    if not HV.ff_probe then
        HV.ff_probe = true
        PS.run({ o.ffmpeg_path, "-hide_banner", "-version" }, function(res)
            HV.ff_ok = (res and res.status == 0) and true or false
            msg.info("artwork converter: " .. HV.conv_mode())
            HV.convert_pump()
        end)
    end
    return nil       -- still probing
end

-- Size key of one converted image: "300x450" + style (".r6" rounded corners, ".f08050F" faded into that colour).
function HV.skey(w, h, fade)
    local r = fade and 0 or (HV.R or 0)          -- fade: "0a" the backdrop's transparent fade, "lg" a logo (its own alpha)
    return w .. "x" .. h .. (fade and (".f" .. fade) or "") .. (r > 0 and (".r" .. r) or "")
end

-- Coverage (0..1) of the pixels in an r x r corner, 4x4 supersampled: cov[y][x], (0,0) = the outermost pixel.
function HV.corner_cov(r)
    HV.cov_cache = HV.cov_cache or {}
    if HV.cov_cache[r] then return HV.cov_cache[r] end
    local cov = {}
    for y = 0, r - 1 do
        cov[y] = {}
        for x = 0, r - 1 do
            local n = 0
            for j = 0, 3 do
                for i = 0, 3 do
                    local dx, dy = r - (x + (i + 0.5) / 4), r - (y + (j + 0.5) / 4)
                    if dx * dx + dy * dy <= r * r then n = n + 1 end
                end
            end
            cov[y][x] = n / 16
        end
    end
    HV.cov_cache[r] = cov
    return cov
end

-- Cuts rounded corners into a converted (premultiplied) BGRA file in place: only the 4 corner squares are touched,
-- so this is the same for every converter and costs next to nothing.
function HV.round_corners(path, w, h, r)
    if not r or r < 1 or w < 2 * r or h < 2 * r then return true end
    local f = io.open(path, "r+b")
    if not f then return false end
    local cov = HV.corner_cov(r)
    local unpack_ = table.unpack or unpack
    local function seg(s, row, mirrored)
        local b = { s:byte(1, -1) }
        for x = 0, r - 1 do
            local c = row[mirrored and (r - 1 - x) or x]
            if c < 1 then
                for k = 1, 4 do b[x * 4 + k] = math.floor(b[x * 4 + k] * c + 0.5) end
            end
        end
        return string.char(unpack_(b))
    end
    local rowb = w * 4
    local function band(y0)
        f:seek("set", y0 * rowb)
        local s = f:read(r * rowb)
        if not s or #s < r * rowb then return end
        local out = {}
        for yy = 0, r - 1 do
            local y = y0 + yy
            local cy = (y < r) and y or (h - 1 - y)              -- rows from the nearest edge
            local o0 = yy * rowb
            out[#out + 1] = seg(s:sub(o0 + 1, o0 + r * 4), cov[cy], false)
            out[#out + 1] = s:sub(o0 + r * 4 + 1, o0 + (w - r) * 4)
            out[#out + 1] = seg(s:sub(o0 + (w - r) * 4 + 1, o0 + rowb), cov[cy], true)
        end
        f:seek("set", y0 * rowb)
        f:write(table.concat(out))
    end
    band(0)
    band(h - r)
    f:close()
    return true
end

-- ffmpeg filter for the backdrop: the left 45 %, the bottom 30 % and the top 12 % fade out to TRANSPARENT (premultiplied
-- alpha, as overlay-add wants it). It used to fade into a solid copy of the background colour, which showed as a box
-- with a visible edge wherever the page behind was a slightly different shade (another theme, the glass bars, an old
-- cache) - now it melts into whatever is behind it.
HV.FADE_KEY = "0a"            -- the size-key mark of the transparent fade (the old colour fades had 6 hex digits)
-- the same fade as a filter_complex chain for input i: the mask is drawn at a quarter size and scaled up (about 7x faster
-- than geq over every pixel, the result within a step or two of it)
function HV.fade_chain(i, w, h)
    local k = "st(0,clip(X/(W*0.45),0,1));st(0,ld(0)*ld(0)*(3-2*ld(0)));st(1,clip((H-1-Y)/(H*0.30),0,1));"
        .. "st(1,ld(1)*ld(1)*(3-2*ld(1)));st(2,clip(Y/(H*0.12),0,1));st(2,ld(2)*ld(2)*(3-2*ld(2)));ld(0)*ld(1)*ld(2)"
    local mw, mh = math.max(16, math.ceil(w / 4)), math.max(16, math.ceil(h / 4))
    return string.format("[%d:v]scale=%d:%d:force_original_aspect_ratio=increase,crop=%d:%d,format=rgba[i%d];color=c=black:s=%dx%d:d=1,format=gray,geq=lum='255*(%s)',scale=%d:%d:flags=bilinear[m%d];"
        .. "[i%d][m%d]alphamerge,premultiply=inplace=1,format=bgra[o%d]", i, w, h, w, h, i, mw, mh, k, w, h, i, i, i, i)
end

HV.CONV = { run = 0, bg = 0, max = 3, seq = 0, n = 0, ms = 0 }
HV.conv_out = {}
function HV.want_bgra(st, dw, dh, fade, pri)
    pri = pri or HV.cur_pri or 0
    local sk = HV.skey(dw, dh, fade)
    if st.bgra[sk] then return end
    if st.cq[sk] then
        -- already waiting: it moves up when something more urgent wants it now
        local q = st.cqi and st.cqi[sk]
        if st.cq[sk] == "queued" and q and pri < (q.pri or 0) then q.pri = pri end
        return
    end
    if not st.jpg then return end
    -- the window is being resized and mpv scales what it has: sizes of steps passed on the way are not converted
    if HV.dw_ok() and HV.size_moving(0.4) then return end
    local bgra = string.format("%s/%s_%s.bgra", PS.dir(), st.base or ("p" .. st.entry.id), sk)
    if HV.conv_out[bgra] then return end            -- another card's conversion is writing this very file
    local bi = utils.file_info(bgra)
    if bi and bi.size == dw * dh * 4 then st.bgra[sk] = bgra; return end
    HV.conv_out[bgra] = true
    st.cq[sk] = "queued"
    HV.CONV.seq = HV.CONV.seq + 1
    local qi = { st = st, jpg = st.jpg, bgra = bgra, w = dw, h = dh, sk = sk, fade = fade,
                 r = (not fade) and (HV.R or 0) or 0, pri = pri, seq = HV.CONV.seq }
    st.cqi = st.cqi or {}
    st.cqi[sk] = qi
    HV.convq[#HV.convq + 1] = qi
    if not fade then HV.want_tiny(st, dw, dh) end
end

-- ---- blurred placeholders: a tiny (12x18 / 21x12) version of each picture, stretched by mpv (dw/dh) into a soft blur
-- that shows at once - all of one screen's tinies come from ONE converter run - until the sharp picture is ready.
-- They are kept for good (a few hundred bytes each). Without dw/dh (mpv < 0.38) the tile takes the average colour.
HV.tinyq = {}
function HV.tiny_dims(w, h)
    if w <= h then return 12, math.max(6, math.floor(12 * h / w + 0.5)) end
    return math.max(6, math.floor(12 * w / h + 0.5)), 12
end
function HV.tiny_path(st, tw, th)
    return string.format("%s/%s_t%dx%d.tiny", PS.dir(), st.base or ("p" .. tostring(st.entry and st.entry.id)), tw, th)
end
-- the tiny for a w x h card: path, tw, th (nil when there is none yet)
function HV.tiny_of(st, w, h)
    if not (st and st.jpg) then return nil end
    local tw, th = HV.tiny_dims(w, h)
    local k = tw .. "x" .. th
    st.tiny = st.tiny or {}
    local t = st.tiny[k]
    if t and HV.bad_file[t] then HV.bad_file[t] = nil; t = nil end        -- deleted meanwhile (cache cleared)
    if t == nil then
        local p = HV.tiny_path(st, tw, th)
        local fi = utils.file_info(p)
        t = (fi and fi.size == tw * th * 4) and p or false
        st.tiny[k] = t
    end
    if t then return t, tw, th end
    return nil
end
function HV.want_tiny(st, w, h)
    if HV.tiny_of(st, w, h) or HV.conv_mode() == "powershell" then return end
    local tw, th = HV.tiny_dims(w, h)
    local k = tw .. "x" .. th
    st.tiny_q = st.tiny_q or {}
    if st.tiny_q[k] then return end
    st.tiny_q[k] = true
    HV.tinyq[#HV.tinyq + 1] = { st = st, jpg = st.jpg, out = HV.tiny_path(st, tw, th), w = tw, h = th, k = k }
end
-- its average colour ("RRGGBB"), for the tile on mpv without dw/dh
function HV.tiny_avg(st, w, h)
    local p, tw, th = HV.tiny_of(st, w, h)
    if not p then return nil end
    st.avg = st.avg or {}
    local k = tw .. "x" .. th
    if st.avg[k] then return st.avg[k] end
    local f = io.open(p, "rb")
    local d = f and f:read("*a")
    if f then f:close() end
    if not d or #d < tw * th * 4 then return nil end
    local r, g, b, n = 0, 0, 0, tw * th
    for i = 0, n - 1 do
        local b0, g0, r0 = d:byte(i * 4 + 1, i * 4 + 3)
        r, g, b = r + r0, g + g0, b + b0
    end
    st.avg[k] = string.format("%02X%02X%02X", math.floor(r / n), math.floor(g / n), math.floor(b / n))
    return st.avg[k]
end
-- one converter run for up to 24 tinies (ffmpeg: one process, many inputs and outputs)
function HV.tiny_pump(mode, done)
    local batch = {}
    while #HV.tinyq > 0 and #batch < 24 do
        local it = table.remove(HV.tinyq, 1)
        if it.jpg and utils.file_info(it.jpg) and PS.img_valid(it.jpg) then batch[#batch + 1] = it end
    end
    if #batch == 0 then return false end
    local function fin()
        for _, it in ipairs(batch) do
            local fi = utils.file_info(it.out)
            it.st.tiny = it.st.tiny or {}
            it.st.tiny[it.k] = (fi and fi.size == it.w * it.h * 4) and it.out or false
            if it.st.tiny_q then it.st.tiny_q[it.k] = nil end
        end
        done()
    end
    if mode == "ffmpeg" then
        local args = { o.ffmpeg_path, "-v", "error", "-y" }
        for _, it in ipairs(batch) do args[#args + 1] = "-i"; args[#args + 1] = it.jpg end
        local fc = {}
        for i, it in ipairs(batch) do
            -- blurred at 3x the size first, so the stretched result is smooth rather than blocky
            fc[#fc + 1] = string.format("[%d:v]scale=%d:%d:flags=area:force_original_aspect_ratio=increase,crop=%d:%d,gblur=sigma=2.2,scale=%d:%d:flags=area,format=bgra[t%d]",
                i - 1, it.w * 3, it.h * 3, it.w * 3, it.h * 3, it.w, it.h, i - 1)
        end
        args[#args + 1] = "-filter_complex"; args[#args + 1] = table.concat(fc, ";")
        for i, it in ipairs(batch) do
            for _, a in ipairs({ "-map", "[t" .. (i - 1) .. "]", "-frames:v", "1", "-f", "rawvideo", it.out }) do args[#args + 1] = a end
        end
        PS.run(args, function() fin() end)
    else           -- magick: one at a time (it is quick for 8x12)
        local i = 0
        local function nxt()
            i = i + 1
            local it = batch[i]
            if not it then return fin() end
            PS.run({ o.magick_path, it.jpg, "-resize", string.format("%dx%d^", it.w, it.h), "-gravity", "center", "-extent", string.format("%dx%d", it.w, it.h), "-depth", "8", "bgra:" .. it.out }, nxt)
        end
        nxt()
    end
    return true
end

-- the F1 check's test: one cached jpg converted to 160x90 the way the cards are (crop to fill); cb(ok, why, ms),
-- ok = nil when there is no picture to try
function HV.conv_try(mode, cb)
    local dir = PS.dir()
    local jpg
    for _, f in ipairs(utils.readdir(dir, "files") or {}) do
        if f:match("%.jpg$") and not f:match("^f1test") then
            local pth = dir .. "/" .. f
            if PS.img_valid(pth) then jpg = pth; break end
        end
    end
    if not jpg then return cb(nil) end
    local w, h = 160, 90
    HV.conv_try_n = (HV.conv_try_n or 0) + 1         -- each run its own files: "Check again" during a slow run is fine
    local tag = "f1test_" .. HV.conv_try_n
    local out = dir .. "/" .. tag .. "_160x90.bgra"
    pcall(os.remove, out)
    local t0 = mp.get_time()
    local function reason(res, err, opt)
        if res and res.error_string == "init" then return "the program was not found (check " .. opt .. ")" end
        if res and res.status ~= 0 then return (res.stderr ~= "" and res.stderr) or ("exit " .. tostring(res.status)) end
        return err
    end
    local function check(why)
        local fi = utils.file_info(out)
        local good = fi and fi.size == w * h * 4
        pcall(os.remove, out)
        cb(good and true or false, (not good) and (why or (fi and string.format("%d bytes, %d expected", fi.size, w * h * 4)) or "no output") or nil,
            math.floor((mp.get_time() - t0) * 1000 + 0.5))
    end
    if mode == "ffmpeg" then
        local it = { jpg = jpg, bgra = out, w = w, h = h }
        return HV.conv_run({ it }, function() check(it.err) end)
    elseif mode == "powershell" then
        local manifest, ps = dir .. "/" .. tag .. ".txt", dir .. "/f1test.ps1"     -- (not the batches' own script)
        local f, f2 = io.open(manifest, "wb"), io.open(ps, "wb")
        if not f or not f2 then
            if f then f:close() end
            if f2 then f2:close() end
            return cb(false, "cannot write in " .. dir, 0)
        end
        f:write(string.format("%s|%s|%d|%d|\n", jpg, out, w, h)); f:close()
        f2:write(HV.PS1); f2:close()
        return PS.run({ "powershell", "-NoProfile", "-NonInteractive", "-ExecutionPolicy", "Bypass", "-File", ps, manifest }, function(res, err)
            pcall(os.remove, manifest)
            check(reason(res, err, "that PowerShell runs"))
        end)
    end
    PS.run({ o.magick_path, jpg, "-resize", string.format("%dx%d^", w, h), "-gravity", "center", "-extent", string.format("%dx%d", w, h), "-depth", "8", "bgra:" .. out },
        function(res, err) check(reason(res, err, "magick_path")) end)
end
function HV.convert_done(batch)
    local good = 0
    for _, it in ipairs(batch) do
        local bi0 = utils.file_info(it.bgra)
        if bi0 and bi0.size == it.w * it.h * 4 then good = good + 1 end
    end
    -- Warn only about real failures: not for a batch whose images were deleted meanwhile (cache cleared, window
    -- resized), and say what the converter said instead of guessing that it isn't installed.
    local real, why = 0, nil
    if (batch.gen or 0) == (HV.conv_gen or 0) then
        for _, it in ipairs(batch) do
            if utils.file_info(it.jpg) then real = real + 1; why = why or it.err end
        end
    end
    if good == 0 and real > 0 then
        local mode = tostring(HV.conv_mode())
        local txt
        if mode == "ffmpeg" then txt = "Artwork could not be converted by ffmpeg" .. (why and (": " .. tostring(why):gsub("%s+", " "):sub(1, 120)) or "")
        else txt = "Artwork could not be converted (" .. mode .. ") - install ffmpeg (faster) or check poster_converter" end
        PS.notice("convert", txt)
    elseif good > 0 then PS.notice_ok("convert") end
    for _, it in ipairs(batch) do
        HV.conv_out[it.bgra] = nil
        local bi = utils.file_info(it.bgra)
        if bi and bi.size == it.w * it.h * 4 and HV.round_corners(it.bgra, it.w, it.h, it.r) then
            it.st.bgra[it.sk] = it.bgra
            it.st.cq[it.sk] = "done"
        else
            if bi then pcall(os.remove, it.bgra) end
            it.st.cq[it.sk] = "fail"
        end
    end
    if not batch.pool then HV.converting = false end
    PS.st_dirty = true
    HV.kick()
    HV.convert_pump()
end

-- ffmpeg: a few small batches at once (one process each: many inputs, one output per picture), the most urgent first.
-- Each batch lands as soon as it is done, so the hero and the posters on screen never wait behind background work.
function HV.conv_run(batch, cb)
    local args = { o.ffmpeg_path, "-v", "error", "-y" }
    for _, it in ipairs(batch) do args[#args + 1] = "-i"; args[#args + 1] = it.jpg end
    local fc = {}
    for i, it in ipairs(batch) do
        local n = i - 1
        if it.fade == "lg" then
            fc[#fc + 1] = string.format("[%d:v]scale=%d:%d:flags=lanczos,format=rgba,premultiply=inplace=1,format=bgra[o%d]", n, it.w, it.h, n)
        elseif it.fade then
            fc[#fc + 1] = HV.fade_chain(n, it.w, it.h)
        else
            -- filled and cropped in the middle, never stretched (a 4:3 still, a poster in a 16:9 card)
            fc[#fc + 1] = string.format("[%d:v]scale=%d:%d:flags=bicubic:force_original_aspect_ratio=increase,crop=%d:%d,format=bgra[o%d]", n, it.w, it.h, it.w, it.h, n)
        end
    end
    args[#args + 1] = "-filter_complex"; args[#args + 1] = table.concat(fc, ";")
    for i, it in ipairs(batch) do
        for _, a in ipairs({ "-map", "[o" .. (i - 1) .. "]", "-frames:v", "1", "-f", "rawvideo", it.bgra }) do args[#args + 1] = a end
    end
    PS.run(args, function(res, err)
        if res and res.status == 0 then return cb() end
        -- one bad picture stops the whole process: the rest are done one by one, so only that one fails
        if #batch > 1 then
            local left = #batch
            for _, it in ipairs(batch) do
                HV.conv_run({ it }, function() left = left - 1; if left == 0 then cb() end end)
            end
            return
        end
        batch[1].err = (res and res.stderr ~= "" and res.stderr) or err or ("exit " .. tostring(res and res.status))
        cb()
    end)
end
function HV.conv_sort()
    table.sort(HV.convq, function(a, b)
        if (a.pri or 0) ~= (b.pri or 0) then return (a.pri or 0) < (b.pri or 0) end
        return (a.seq or 0) < (b.seq or 0)
    end)
end
function HV.conv_pool(mode)
    local C = HV.CONV
    -- the blurred placeholders first (one quick run for a screenful), alongside
    if #HV.tinyq > 0 and not HV.tiny_busy then
        HV.tiny_busy = true
        if not HV.tiny_pump(mode, function()
            HV.tiny_busy = false
            HV.converting = C.run > 0
            HV.kick(); if HV.mode == "add" then render() end
            HV.convert_pump()
        end) then HV.tiny_busy = false end
    end
    while C.run < C.max and #HV.convq > 0 do
        HV.conv_sort()
        local p0 = HV.convq[1].pri or 0
        if p0 >= 2 and C.bg >= 2 then break end            -- background work leaves one process free for what you open
        local cap = (p0 <= 0) and 4 or 8
        local batch = { gen = HV.conv_gen or 0, pool = true }
        while #HV.convq > 0 and #batch < cap and (HV.convq[1].pri or 0) == p0 do
            local it = table.remove(HV.convq, 1)
            if it.jpg and utils.file_info(it.jpg) and not PS.img_valid(it.jpg) then
                HV.conv_out[it.bgra] = nil
                PS.drop_image(it.jpg)
                it.st.cq[it.sk] = nil
                it.st.bgra, it.st.tiny = {}, {}
                it.st.state = it.st.re or "new"
                HV.kick()
            else
                batch[#batch + 1] = it
            end
        end
        if #batch > 0 then
            C.run = C.run + 1
            if p0 >= 2 then C.bg = C.bg + 1 end
            HV.converting = true
            local t0 = mp.get_time()
            HV.conv_run(batch, function()
                C.run = C.run - 1
                if p0 >= 2 then C.bg = C.bg - 1 end
                HV.converting = C.run > 0 or HV.tiny_busy == true
                local ms = (mp.get_time() - t0) * 1000
                C.n, C.ms = C.n + #batch, C.ms + ms
                msg.verbose(string.format("pictures: %d converted in %d ms (priority %d, %d waiting, %d running)", #batch, ms, p0, #HV.convq, C.run))
                HV.convert_done(batch)
            end)
        end
    end
end

function HV.convert_pump()
    local mode = HV.conv_mode()
    if not mode then return end
    if mode == "ffmpeg" then return HV.conv_pool(mode) end
    if HV.converting then return end
    -- the blurred placeholders of what is waiting go first: one quick run shows the whole screen blurred
    if #HV.tinyq > 0 and mode ~= "powershell" then
        HV.converting = true
        if HV.tiny_pump(mode, function() HV.converting = false; HV.kick(); if HV.mode == "add" then render() end; HV.convert_pump() end) then return end
        HV.converting = false
    end
    if #HV.convq == 0 then return end
    HV.conv_sort()
    local batch = { gen = HV.conv_gen or 0 }
    while #HV.convq > 0 and #batch < 12 do
        local it = table.remove(HV.convq, 1)
        -- a picture cut off on the way is never converted: it is deleted and fetched again
        if it.jpg and utils.file_info(it.jpg) and not PS.img_valid(it.jpg) then
            HV.conv_out[it.bgra] = nil
            PS.drop_image(it.jpg)
            it.st.cq[it.sk] = nil
            it.st.bgra, it.st.tiny = {}, {}
            it.st.state = it.st.re or "new"
            HV.kick()
        else
            batch[#batch + 1] = it
        end
    end
    if #batch == 0 then HV.converting = false; return HV.convert_pump() end
    HV.converting = true
    if mode == "powershell" then
        HV.batch_n = HV.batch_n + 1
        local manifest = string.format("%s/batch_%d.txt", PS.dir(), HV.batch_n % 4)
        local lines = {}
        for _, it in ipairs(batch) do lines[#lines + 1] = string.format("%s|%s|%d|%d|%s", it.jpg, it.bgra, it.w, it.h, it.fade or "") end
        local f = io.open(manifest, "wb")
        local ps = PS.dir() .. "/convert_batch.ps1"
        local f2 = io.open(ps, "wb")
        if not f or not f2 then
            if f then f:close() end
            if f2 then f2:close() end
            HV.convert_done(batch); return
        end
        f:write(table.concat(lines, "\n") .. "\n"); f:close()
        f2:write(HV.PS1); f2:close()
        PS.run({ "powershell", "-NoProfile", "-NonInteractive", "-ExecutionPolicy", "Bypass", "-File", ps, manifest },
            function() HV.convert_done(batch) end)
        return
    end
    -- magick: one process per image, three at a time
    local next_i, left = 0, #batch
    local function worker()
        next_i = next_i + 1
        local it = batch[next_i]
        if not it then return end
        local function fin() left = left - 1; if left == 0 then HV.convert_done(batch) else worker() end end
        if it.fade then
            fin()       -- the faded backdrop needs ffmpeg or PowerShell
        else
            PS.run({ o.magick_path, it.jpg, "-resize", string.format("%dx%d^", it.w, it.h), "-gravity", "center", "-extent", string.format("%dx%d", it.w, it.h), "-depth", "8", "bgra:" .. it.bgra }, fin)
        end
    end
    for _ = 1, math.min(3, #batch) do worker() end
end

-- Idle prefetch: when everything on screen is done, the cards of the next rows (and the next page of each visible
-- shelf) are looked up, downloaded and converted too, so scrolling finds them ready.
function HV.prefetch_list(m)
    local n = math.max(0, math.floor(tonumber(o.idle_prefetch_rows) or 0))
    if n == 0 or not HV.vis or #HV.vis == 0 then return nil end
    local list = {}
    local function add_row(row, from)
        if not row then return end
        local d = HV.rowdim(row, m)
        for i = from + 1, from + d.per do
            local cd = row.cards[i]
            if not cd then break end
            if row.land then cd.dw, cd.dh = d.cw, d.ch end
            list[#list + 1] = cd
        end
    end
    for _, v in ipairs(HV.vis) do
        local row = HV.rows[v.ri]
        if row.shelf then add_row(row, (row.off or 0) + HV.rowdim(row, m).per) end
    end
    local last = HV.vis[#HV.vis].ri
    for ri = last + 1, last + n do add_row(HV.rows[ri], HV.rows[ri] and HV.rows[ri].off or 0) end
    if HV.vis[1].ri > 1 then local pr = HV.rows[HV.vis[1].ri - 1]; add_row(pr, pr.off or 0) end
    return list
end

-- Pre-converting the whole library (precache_artwork): while nothing else is loading, every title card's poster is
-- looked up, downloaded and converted at the card size, so later every row is instant. ~0.9 MB per poster on a 4K
-- window (raw pixels). The bigger "selected" version is still made on demand.
function HV.precache_next(m)
    HV.pc_total, HV.pc_done = nil, nil
    if not o.precache_artwork or HV.mode ~= "home" or HV.q or not HV.rows then return {} end
    local list, seen = {}, {}
    for _, row in ipairs(HV.rows) do
        if not row.land then
            for _, c in ipairs(row.cards) do if c.kind == "folder" and not seen[c.key] then seen[c.key] = true; list[#list + 1] = c end end
        end
    end
    local out, done = {}, 0
    for _, c in ipairs(list) do
        local st = HV.items[c.key]
        local fin = st and (st.state == "none" or st.state == "error" or st.bgra[m.sk] or (st.cq and st.cq[m.sk] == "fail"))
        if fin then done = done + 1 elseif #out < 6 then out[#out + 1] = c end
    end
    HV.pc_total, HV.pc_done = #list, done
    return out
end

function HV.idle()
    return #HV.convq == 0 and not HV.converting and HV.sn == 0 and HV.dn == 0 and TV.sn == 0
end

function HV.pump()
    if not PS.enabled() then return end
    local m = HV.m
    local now = mp.get_time()
    local gw = HV.grow_want
    HV.cur_pri = 0
    if gw then
        local st = HV.items[gw.card.key]
        if st and st.jpg then HV.want_bgra(st, gw.w, gw.h) end
    end
    local wanted = HV.wanted
    local nscreen = #HV.wanted
    -- the title you rest on (home): its page's hero and backdrop, at their final sizes
    local pf = HV.PF.extra
    if pf and HV.mode == "home" and HV.PF.key == pf.key then
        wanted = {}
        for _, w in ipairs(HV.wanted) do wanted[#wanted + 1] = w end
        for _, w in ipairs(pf.list) do wanted[#wanted + 1] = w end
        nscreen = #wanted
    end
    HV.cur_pri = 1
    if HV.idle() then
        -- the bigger "selected" picture of the cards around the selection, so moving there does not pop in a beat later
        for _, vc in ipairs(HV.vis_cards or {}) do
            if vc.gw and math.abs((vc.ri or 0) - HV.r) <= 1 and not vc.cut then
                local st = HV.items[vc.card.key]
                if st and st.jpg and st.bgra[vc.sk] then HV.want_bgra(st, vc.gw, vc.gh) end
            end
        end
        local extra = HV.prefetch_list(m) or {}
        -- once the screen and the next rows are done: the rest of the library, a few at a time
        if #extra == 0 then extra = HV.precache_next(m) end
        if #extra == 0 then HV.details_bg() end
        if #extra > 0 then
            local base = wanted
            wanted = {}
            for _, w in ipairs(base) do wanted[#wanted + 1] = w end
            for _, w in ipairs(extra) do wanted[#wanted + 1] = w end
        end
    end
    for wi, w in ipairs(wanted) do
        HV.cur_pri = (wi <= nscreen) and (w.pri or 0) or 2
        local st = HV.items[w.key]
        if not st then
            st = { state = "new", bgra = {}, cq = {} }
            HV.items[w.key] = st
        end
        if st.state == "error" and st.t and now - st.t > 20 then st.state = "new" end
        if w.still then
            TV.pump_still(w, st, m)
        elseif w.kind == "ep" or w.kind == "missing" or w.kind == "season" then
            -- no artwork source for this card (yet): nothing to look up
        elseif w.land_wait then
            -- a Continue Watching card whose title is not matched yet: only the match is wanted here; once it is in,
            -- the rows are built again and the card gets its still or backdrop
            if st.state == "new" and HV.sn < 24 then HV.lookup(w, st) end
            if not w.rebuilt and PS.idx and PS.idx[w.key] ~= nil then w.rebuilt = true; HV.sig = nil; HV.kick() end     -- (not on a network error)
        else
            if st.state == "new" then
                if HV.sn < 24 then HV.lookup(w, st) end        -- they share curl processes (12 requests each)
            end
            if st.state == "entry" and HV.dn < 12 then HV.download(st) end
            if st.state == "jpg" then HV.want_bgra(st, w.dw or m.cw, w.dh or m.ch) end
        end
        if w.need then TV.ensure_season(w.need.entry, w.need.s)
        elseif w.kind == "ep" and w.ts and HV.mode == "title" then
            local se = TV.show_entry()
            if se then TV.ensure_season(se, tonumber(w.ts)) end      -- refreshes old season data (new ratings)
        end
    end
    HV.cur_pri = nil
    if TV.card and HV.mode == "title" then TV.ensure_details() end
    if HV.q and HV.filter_pending and HV.mode ~= "title" then
        for _, c in ipairs(HV.filter_pending) do
            if HV.sn >= 24 then break end
            local st = HV.items[c.key]
            if not st then st = { state = "new", bgra = {}, cq = {} }; HV.items[c.key] = st end
            if st.state == "new" then HV.lookup(c, st) end
        end
    end
    HV.convert_pump()
end

-- ---------- bitmaps on screen ----------
function HV.clear_anim()
    HV.A.ring_cur, HV.A.ring_dst = nil, nil
    HV.A.enter_t = U.now_s()
    if HV.anim_on() then HV.anim_kick(0.25) end
end

-- Removing has to travel the same asynchronous road as the adds: mpv may still be working through a burst of
-- overlay-add commands, and a direct (synchronous) remove used to overtake them - the posters then reappeared on top
-- of the video after the browser closed. Every id that may be on screen is removed, after whatever is in flight.
HV.ever = HV.ever or {}
function HV.clear()
    HV.clear_anim()
    HV.ids = {}
    HV.cmdq, HV.cmdk = {}, {}         -- queued (unsent) poster commands must not bring posters back
    for id in pairs(HV.shown) do HV.ever[id] = true end
    for id in pairs(HV.ever) do mp.command_native_async({ "overlay-remove", tostring(id) }, function() end) end
    HV.ever = {}
    HV.shown = {}
end
-- the text layer likewise
function HV.clear_text()
    mp.command_native_async({ name = "osd-overlay", id = overlay.id, format = "none", data = "" }, function() end)
    if HV.fx_clear then HV.fx_clear() end
end

-- ---------- one batch per frame ----------
-- mpv draws a frame between two synchronous commands, so updating the text and 30 posters one command at a time showed
-- a scroll in pieces (old posters under new labels for several frames). Everything is queued and sent asynchronously in
-- one burst instead: mpv's core runs the whole queue before it draws again.
HV.cmdq, HV.cmdk, HV.inflight = {}, {}, 0
-- key: one entry per overlay ("ass", "ov12"...); a newer command for the same key replaces the queued one
function HV.cmd(args, on_fail, key)
    key = key or ("ov" .. tostring(args[2] or args.id))
    local i = HV.cmdk[key]
    if i then HV.cmdq[i] = { args, on_fail } else HV.cmdq[#HV.cmdq + 1] = { args, on_fail }; HV.cmdk[key] = #HV.cmdq end
end
-- a frame sent straight to mpv makes the queued (older) one for the same layer void, so it cannot land after it
function HV.cmd_drop(key)
    local i = HV.cmdk[key]
    if i then HV.cmdq[i] = { { "ignore" } }; HV.cmdk[key] = nil end
end
-- While mpv is still working through the previous burst (holding an arrow key), new changes wait and are merged, so
-- only the latest state is drawn instead of a backlog of every intermediate one.
function HV.flush()
    if HV.inflight > 0 or #HV.cmdq == 0 or (HV.DR and HV.DR.open) then return end
    local q = HV.cmdq
    HV.cmdq, HV.cmdk = {}, {}
    HV.inflight = #q
    for _, it in ipairs(q) do
        local fail = it[2]
        mp.command_native_async(it[1], function(ok)
            if not ok and fail then fail() end
            HV.inflight = HV.inflight - 1
            if HV.inflight == 0 and #HV.cmdq > 0 then HV.flush() end
        end)
    end
end
-- A failed overlay-add leaves mpv showing whatever that id showed before (a picture from another size or place):
-- that id is taken down, and the file is marked bad so its owner converts it again.
HV.bad_file = {}
-- dw, dh: show the w x h picture at that size instead (mpv 0.38+, see HV.dw_ok)
-- mpv maps the file as it is told: a picture smaller than w x h makes it read past the end and crash (SIGBUS), so the
-- size is checked once per file before it is handed over
HV.fsz = {}
function HV.overlay_add(id, x, y, f, w, h, sig, dw, dh, offset, stride)
    offset = offset or 0
    stride = stride or w * 4
    -- mpv maps offset + h * stride bytes of the file. A picture cut on its left side (a source offset into the row)
    -- would reach past the end: its last line is left out (Windows refuses to map past the end of a file)
    local need = offset + h * stride
    if (HV.fsz[f] or 0) < need then
        local fi = utils.file_info(f)
        HV.fsz[f] = fi and fi.size or nil
    end
    local size = HV.fsz[f] or 0
    if size < need and h > 1 and offset % stride ~= 0 and size >= offset + (h - 1) * stride then
        h = h - 1
        need = offset + h * stride
        if not (dw and dh) then dw, dh = w, h + 1 end           -- (shown at its full height, scaled, on mpv 0.38+)
    end
    if size < need then
        msg.warn(string.format("picture %s is %s bytes, %d needed - not shown", tostring(f), tostring(size), need))
        return
    end
    HV.shown[id] = sig
    HV.ever[id] = true
    local args
    if dw and dh and (dw ~= w or dh ~= h) and HV.dw_ok() then
        args = { name = "overlay-add", id = id, x = math.floor(x), y = math.floor(y), file = f, offset = offset, fmt = "bgra",
                 w = w, h = h, stride = stride, dw = math.floor(dw), dh = math.floor(dh) }
    else
        args = { "overlay-add", tostring(id), tostring(math.floor(x)), tostring(math.floor(y)), f, tostring(offset), "bgra",
                 tostring(w), tostring(h), tostring(stride) }
    end
    HV.cmd(args, function()
        if HV.shown[id] == sig then HV.shown[id] = nil end
        HV.bad_file[f] = true
        mp.command_native_async({ "overlay-remove", tostring(id) }, function() end)
        mp.add_timeout(0.05, function() if browser_active then HV.sig = nil; render() end end)
    end)
end
-- the converted picture of st for size key sk, or nil (and forgotten) when its file went missing
function HV.bgra_of(st, sk)
    local f = st and st.bgra[sk]
    if f and HV.bad_file[f] then
        HV.bad_file[f] = nil
        for k, v in pairs(st.bgra) do if v == f then st.bgra[k] = nil; if st.cq then st.cq[k] = nil end end end
        return nil
    end
    return f
end

-- ---------- Download: files of your library to your computer, one after another ----------
-- The title page's Download button opens the download card: every file of the title with a tick box (what you don't
-- have yet ticked, the ones already downloaded marked), where it all goes, and the live progress. Enter adds the ticked
-- ones to the queue and closes the card (↓ next to the cache pill, or D, brings it back); files are fetched one at a time to download_dir/<Title>/ under their own names. One that is already there
-- at its full size is skipped, a half-finished one is continued (curl -C -). Downloads go on while you browse or watch.
HV.DL = { q = {}, cur = nil, done = 0, total = 0, failed = 0, state = {}, hist = {}, paused = false }
function HV.DL.dir()
    local d = tostring(o.download_dir or "")
    if d == "" then
        local home = os.getenv("USERPROFILE") or os.getenv("HOME") or "."
        d = home .. "/Downloads/webdav-browser"
    end
    return (d:gsub("\\", "/"):gsub("/+$", ""))
end
HV.DL.safe_c, HV.DL.safe_n = {}, 0
function HV.DL.safe(s)
    s = tostring(s or "file")
    local r = HV.DL.safe_c[s]
    if r then return r end
    r = (s:gsub('[<>:"/\\|%?%*%c]', " "):gsub("%s+", " "):gsub("^%s+", ""):gsub("[%s%.]+$", ""))
    if HV.DL.safe_n > 20000 then HV.DL.safe_c, HV.DL.safe_n = {}, 0 end
    HV.DL.safe_c[s], HV.DL.safe_n = r, HV.DL.safe_n + 1
    return r
end
function HV.DL.folder(title) return HV.DL.dir() .. "/" .. HV.DL.safe(title) end
-- the path as the system writes it (backslashes on Windows)
function HV.DL.native(p) return (package.config:sub(1, 1) == "\\") and (p:gsub("/", "\\")) or p end
function HV.DL.dest(title, name) return HV.DL.folder(title) .. "/" .. HV.DL.safe(name) end
-- is anything of this title (card key) still queued or downloading
function HV.DL.busy(key)
    local DL = HV.DL
    if not DL.cur then return false end
    if key == nil or DL.cur.key == key then return true end
    for _, it in ipairs(DL.q) do if it.key == key then return true end end
    return false
end
-- what one file is: "done" (on your computer), "now", "queued", "failed", nil
function HV.DL.status(title, e)
    local DL = HV.DL
    if DL.cur and DL.cur.href == e.href then return "now" end
    for _, it in ipairs(DL.q) do if it.href == e.href then return "queued" end end
    if DL.state[e.href] == "failed" then return "failed" end
    local fi = utils.file_info(HV.DL.dest(title, e.name))
    if fi and fi.size > 0 and (not e.size or e.size <= 0 or fi.size >= e.size) then return "done" end
    return nil
end
-- entries: { href, name, size } in the order to fetch them; added after what is already queued
function HV.DL.add(title, key, entries)
    local DL = HV.DL
    local n = 0
    local idle = not DL.cur and #DL.q == 0
    local first = #DL.q + 1
    for _, e in ipairs(entries) do
        local st = DL.status(title, e)
        if st ~= "now" and st ~= "queued" then
            DL.q[#DL.q + 1] = { href = e.href, name = e.name, size = tonumber(e.size), key = key, title = title, dest = DL.dest(title, e.name) }
            DL.state[e.href] = nil
            n = n + 1
        end
    end
    if n == 0 then
        HV.DLP.fire("queued", "Already queued")
        return 0
    end
    if idle then DL.done, DL.failed, DL.total = 0, 0, 0 end
    DL.total = DL.total + n
    -- the pill says it: started now, or where in the line it is
    if idle and not DL.paused then HV.DLP.fire("start", n == 1 and "Download started" or string.format("Download started  ·  %d files", n))
    else HV.DLP.fire("queued", string.format("Queued  ·  #%d%s", first + (DL.cur and 1 or 0), n > 1 and string.format(" - #%d", first + n - 1 + (DL.cur and 1 or 0)) or "")) end
    local win = package.config:sub(1, 1) == "\\"
    local folder = DL.folder(title)
    mp.command_native_async({ name = "subprocess", playback_only = false, capture_stdout = true, capture_stderr = true,
        args = win and { "cmd", "/c", "mkdir", DL.native(folder) } or { "mkdir", "-p", folder } }, function() end)
    if not DL.cur and not DL.paused then DL.next() end
    HV.kick()
    return n
end
-- ---- what is already on your computer (play_local_first): every file under download_dir, by its name ----
function HV.DL.scan()
    local DL = HV.DL
    local idx = {}
    local dir = DL.dir()
    local folders = utils.readdir(dir, "dirs") or {}
    for _, fo in ipairs(folders) do
        for _, fn in ipairs(utils.readdir(dir .. "/" .. fo, "all") or {}) do
            if fn ~= "." and fn ~= ".." and not fn:match("%.part$") then
                local fi = utils.file_info(dir .. "/" .. fo .. "/" .. fn)
                if fi and fi.is_file and fi.size > 0 then idx[fn:lower()] = { path = dir .. "/" .. fo .. "/" .. fn, size = fi.size } end
            end
        end
    end
    DL.lidx, DL.lidx_t = idx, mp.get_time()
    DL.lver = (DL.lver or 0) + 1
    return idx
end
-- the local copy of a library file (whole), or nil
function HV.DL.local_for(e)
    if not (o.play_local_first and e and e.name) then return nil end
    local DL = HV.DL
    if not DL.lidx or mp.get_time() - (DL.lidx_t or 0) > 300 then DL.scan() end
    local hit = DL.lidx[DL.safe(e.name):lower()]
    if not hit then return nil end
    local want = tonumber(e.size)
    if want and want > 0 and hit.size < want then return nil end
    return hit.path
end
MS.local_for = function(e) return HV.DL.local_for(e) end
-- a finished file for the queue window's "Finished" list (newest first, the last 30)
function HV.DL.log(it, ok)
    if ok and HV.DL.lidx then
        HV.DL.lidx[HV.DL.safe(it.name):lower()] = { path = it.dest, size = (utils.file_info(it.dest) or { size = 0 }).size }
        HV.DL.lver = (HV.DL.lver or 0) + 1
    end
    local DL = HV.DL
    DL.last_t = U.now_s()
    mp.add_timeout(121, function() if browser_active then HV.last_data = nil; HV.kick() end end)     -- the pill leaves on time
    table.insert(DL.hist, 1, { title = it.title, key = it.key, href = it.href, name = it.name, size = it.size, ok = ok, dest = it.dest })
    while #DL.hist > 30 do table.remove(DL.hist) end
end
-- pause: the file arriving now stops and goes back to the front of the line (curl continues it later)
-- anything of this title (card key) in the line, running or paused
function HV.DL.has(key)
    local DL = HV.DL
    if DL.cur and DL.cur.key == key then return true end
    for _, it in ipairs(DL.q) do if it.key == key then return true end end
    return false
end
function HV.DL.pause()
    local DL = HV.DL
    DL.paused = true
    local c = DL.cur
    if c then
        DL.cur = nil
        if DL.cmd then pcall(mp.abort_async_command, DL.cmd); DL.cmd = nil end
        table.insert(DL.q, 1, c)
    end
    if DL.timer then DL.timer:kill(); DL.timer = nil end
    HV.kick()
end
function HV.DL.resume()
    local DL = HV.DL
    DL.paused = false
    if not DL.cur then DL.next() end
end
-- take queued file i out of the line
function HV.DL.remove(i)
    local DL = HV.DL
    if not DL.q[i] then return end
    table.remove(DL.q, i)
    DL.total = math.max(0, DL.total - 1)
    HV.kick()
end
-- the file arriving now: stop it and go on with the next (what arrived is kept)
function HV.DL.skip()
    local DL = HV.DL
    local c = DL.cur
    if not c then return end
    DL.cur = nil
    if DL.cmd then pcall(mp.abort_async_command, DL.cmd); DL.cmd = nil end
    DL.total = math.max(0, DL.total - 1)
    DL.last = c
    if DL.paused then HV.kick() else DL.next() end
end
-- queued file i to place j: true when it moved
function HV.DL.move(i, j)
    local DL = HV.DL
    if not (DL.q[i] and DL.q[j]) then return false end
    DL.q[i], DL.q[j] = DL.q[j], DL.q[i]
    return true
end
function HV.DL.next()
    local DL = HV.DL
    if DL.cur then DL.last = DL.cur end
    local it = table.remove(DL.q, 1)
    if not it then
        DL.cur = nil
        if DL.timer then DL.timer:kill(); DL.timer = nil end
        if DL.total > 0 and not DL.paused then
            if DL.failed > 0 then HV.DLP.fire("fail", string.format("%d failed  ·  %d done", DL.failed, DL.done))
            else HV.DLP.fire("done", DL.done == 1 and "Download done" or string.format("%d downloads done", DL.done)) end
        end
        HV.kick()
        return
    end
    local fi = utils.file_info(it.dest)
    if fi and fi.size > 0 and (not it.size or it.size <= 0 or fi.size >= it.size) then
        DL.done = DL.done + 1
        DL.log(it, true)
        return DL.next()
    end
    DL.cur, DL.t0, DL.speed = it, mp.get_time(), 0
    DL.tok = (DL.tok or 0) + 1
    local tok = DL.tok
    local part = it.dest .. ".part"
    local pf = utils.file_info(part)
    DL.got, DL.start_got = pf and pf.size or 0, pf and pf.size or 0
    local args = { o.curl_path, "-s", "-S", "-L", "-C", "-", "--retry", "5", "--retry-delay", "3", "--connect-timeout", "15", "--create-dirs", "-o", part }
    if o.user_agent ~= "" then args[#args + 1] = "-A"; args[#args + 1] = o.user_agent end
    local stdin_data = U.curl_auth(args)
    args[#args + 1] = o.url .. it.href
    msg.info("download: " .. it.name .. " -> " .. it.dest)
    DL.cmd = mp.command_native_async({ name = "subprocess", args = args, stdin_data = stdin_data, playback_only = false,
        capture_stdout = false, capture_stderr = true }, function(success, res)
        if DL.cur ~= it or DL.tok ~= tok then return end
        DL.cmd = nil
        if success and res and res.status == 0 then
            pcall(os.remove, it.dest)
            if os.rename(part, it.dest) then DL.done = DL.done + 1; DL.state[it.href] = nil; DL.log(it, true)
            else DL.failed = DL.failed + 1; DL.state[it.href] = "failed"; DL.log(it, false) end
        else
            DL.failed = DL.failed + 1
            DL.state[it.href] = "failed"
            DL.log(it, false)
            msg.warn("download failed: " .. it.name .. "  " .. tostring(res and res.stderr or ""):gsub("%s+", " "):sub(1, 200))
        end
        DL.next()
    end)
    if not DL.timer then
        DL.timer = mp.add_periodic_timer(1, function()
            local c = DL.cur
            if not c then return end
            local f2 = utils.file_info(c.dest .. ".part")
            local got = f2 and f2.size or 0
            local sp = math.max(0, got - (DL.got or 0))
            DL.speed = (DL.speed and DL.speed > 0) and (DL.speed * 0.6 + sp * 0.4) or sp       -- a little smoothing
            DL.got = got
            if browser_active and HV.mode ~= "add" then HV.kick() end      -- the footer and the card show it
        end)
    end
    HV.kick()
end
-- stops everything (what arrived stays and is continued next time)
function HV.DL.stop()
    local DL = HV.DL
    DL.q = {}
    local c = DL.cur
    DL.cur, DL.last, DL.last_t = nil, c or DL.last, U.now_s()
    if DL.cmd then pcall(mp.abort_async_command, DL.cmd); DL.cmd = nil end
    if DL.timer then DL.timer:kill(); DL.timer = nil end
    DL.paused = false
    if c then HV.DLP.fire("stop", "Stopped  ·  what arrived is kept") end
    HV.kick()
end
-- "3 of 12  ·  34 %" for the button and the footer
function HV.DL.progress()
    local DL = HV.DL
    local c = DL.cur
    if not c then return nil end
    local pct = (c.size and c.size > 0) and math.floor((DL.got or 0) / c.size * 100) or nil
    return string.format("%d of %d%s", DL.done + DL.failed + 1, DL.total, pct and string.format("  ·  %d %%", pct) or "")
end
-- the folder in Explorer / Finder / the file manager
-- the folder of a title, or the download folder itself when there is no title (an empty queue window)
function HV.DL.folder_of(title, win)
    if not title or title == "" or (win and title == "Downloads") then return HV.DL.dir() end
    return HV.DL.folder(title)
end
function HV.DL.open_folder(path)
    local win = package.config:sub(1, 1) == "\\"
    local mac = not win and (os.getenv("HOME") or ""):match("^/Users/")
    local args = win and { "explorer", HV.DL.native(path) } or (mac and { "open", path } or { "xdg-open", path })
    local function open() mp.command_native_async({ name = "subprocess", playback_only = false, args = args }, function() end) end
    if win then
        mp.command_native_async({ name = "subprocess", playback_only = false, capture_stderr = true,
            args = { "cmd", "/c", "mkdir", HV.DL.native(path) } }, function() open() end)
    else open() end
end

-- ---------- image layers ABOVE the posters ----------
-- mpv draws every overlay-add picture over all text and shapes, so nothing drawn as text can cover a poster. These
-- small pictures are made here, pixel by pixel, and placed over the posters as images of their own: the soft fade at
-- the bottom of the page, the dimming around the selected card (focus_style=dim), the arrows on the add screen's rows
-- and the TOP 10 badges. Each is written once per size into the artwork cache (a few KB).
HV.LY = { ID_FADE = 48, ID_DIM = 49, ID_CHEV = 53, files = {} }
HV.CARD_IDS = 47            -- posters use ids 0-46, 47 the title logo, the layers 48-59; 60-63 are the cards and the transitions
function HV.LY.rgb(hex)
    hex = tostring(hex or "000000")
    return tonumber(hex:sub(1, 2), 16) or 0, tonumber(hex:sub(3, 4), 16) or 0, tonumber(hex:sub(5, 6), 16) or 0
end
-- a premultiplied BGRA pixel
function HV.LY.px(r, g, b, a)
    a = math.max(0, math.min(1, a))
    return string.char(math.floor(b * a + 0.5), math.floor(g * a + 0.5), math.floor(r * a + 0.5), math.floor(255 * a + 0.5))
end
-- writes a picture once: rows(y) returns row y as a string of w pixels
-- painting a picture in Lua takes a while: at most ~6 ms of it per frame, the rest next frame (no stutter)
HV.LY.spent = 0
function HV.LY.frame() HV.LY.spent = 0; HV.AX.tw_spent = 0 end
function HV.LY.busy()
    if HV.LY.spent > 0.006 then
        if not HV.LY.later then HV.LY.later = true; mp.add_timeout(0.02, function() HV.LY.later = nil; HV.LY.frame(); HV.kick() end) end
        return true
    end
    return false
end
function HV.LY.make(name, w, h, rows)
    local path = PS.dir() .. "/" .. name .. ".bgra"
    if HV.LY.files[path] then return path end
    local fi = utils.file_info(path)
    if not (fi and fi.size == w * h * 4) and HV.LY.busy() then return nil end
    if not (fi and fi.size == w * h * 4) then
        local t0 = mp.get_time()
        PS.mkdir()
        local f = io.open(path, "wb")
        if not f then return nil end
        for y = 0, h - 1 do f:write(rows(y)) end
        f:close()
        HV.LY.spent = HV.LY.spent + (mp.get_time() - t0)
    end
    HV.LY.files[path] = true
    return path
end
-- one colour at one opacity, 4 x 4 (stretched by mpv)
function HV.LY.solid(hex, op)
    local r, g, b = HV.LY.rgb(hex)
    local p = HV.LY.px(r, g, b, op / 100)
    return HV.LY.make(string.format("ly_s_%s_%d", hex, op), 4, 4, function() return p:rep(4) end), 4, 4
end
-- the bottom fade: clear at the top, the page colour at the bottom (eased), 4 px wide, stretched across the page
function HV.LY.vfade(hex, h, maxa)
    local r, g, b = HV.LY.rgb(hex)
    maxa = maxa or 1
    return HV.LY.make(string.format("ly_v_%s_%d%s", hex, h, maxa < 1 and ("_" .. math.floor(maxa * 100)) or ""), 4, h, function(y)
        local k = (y + 0.5) / h
        return HV.LY.px(r, g, b, k * k * (3 - 2 * k) * maxa):rep(4)
    end), 4, h
end
-- distance from (x, y) to the segment a-b
function HV.LY.seg(x, y, ax, ay, bx, by)
    local dx, dy = bx - ax, by - ay
    local t = ((x - ax) * dx + (y - ay) * dy) / math.max(1e-6, dx * dx + dy * dy)
    t = math.max(0, math.min(1, t))
    local ex, ey = x - (ax + t * dx), y - (ay + t * dy)
    return math.sqrt(ex * ex + ey * ey)
end
-- an arrow over the edge of a row: the page colour fading in towards the edge, a white chevron on it.
-- dir = 1: right (›), -1: left (‹)
-- (posters are bitmaps and cover any text, so this button sits in the page margin, beside the row, not over it)
-- the arrow button's size (its picture is d + 2 * shadow wide)
function HV.chev_d(m) return math.max(24, math.floor(m.lfs * 2.3)) end
function HV.chev_sh(d) return math.max(3, math.floor(d * 0.2)) end
-- where the button goes for a row edge at x (the first poster's left edge / the last one's right edge): x, y, size
function HV.chev_box(m, edge_x, mid_y)
    local d = HV.chev_d(m)
    local sh = HV.chev_sh(d)
    local t = d + 2 * sh
    local cx = math.max(t / 2 + 2, math.min(m.w - t / 2 - 2, edge_x))
    return math.floor(cx - t / 2), math.floor(mid_y - t / 2), t
end
-- the button itself (premultiplied BGRA, t x t): a soft shadow, a dark glass disc with a hairline edge, the chevron
function HV.LY.chevron(_, w, _h, dir, hot)
    local t = w
    local sh = math.floor(t / 7)        -- t = d + 2 * sh with sh = d / 5: sh = t / 7
    local d = t - 2 * sh
    local c, r = t / 2, d / 2
    local s_ = d * 0.17
    local th = math.max(1.6, d * 0.075)
    local ax_, bx_ = c - dir * s_ * 0.45, c + dir * s_ * 0.55
    local fill_a = hot and 0.86 or 0.66
    local edge_a = hot and 0.42 or 0.22
    local glyph_a = hot and 1 or 0.9
    local function clamp(v) return v < 0 and 0 or (v > 1 and 1 or v) end
    return HV.LY.make(string.format("ly_cd_%d_%d%s", t, dir, hot and "h" or ""), t, t, function(y)
        local out = {}
        local py = y + 0.5
        for x = 0, t - 1 do
            local px = x + 0.5
            local dx, dy = px - c, py - c
            local dist = math.sqrt(dx * dx + dy * dy)
            -- the shadow, a little below
            local dys = py - (c + d * 0.06)
            local ds = math.sqrt(dx * dx + dys * dys)
            local sa = 0.38 * clamp((r + sh - ds) / (sh * 1.2))
            sa = sa * sa
            local R_, G_, B_, A_ = 0, 0, 0, sa
            -- the disc (a faint light from the top)
            local cd = clamp(r - dist + 0.5)
            if cd > 0 then
                local lift = 26 * clamp(1 - py / t)
                local fr, fg, fb = 22 + lift, 22 + lift, 26 + lift
                local a = fill_a * cd
                R_, G_, B_, A_ = fr * a + R_ * (1 - a), fg * a + G_ * (1 - a), fb * a + B_ * (1 - a), a + A_ * (1 - a)
                -- the hairline edge
                local ce = clamp(1 - math.abs(dist - (r - 0.9)) / 0.9) * cd
                if ce > 0 then
                    local ea = edge_a * ce
                    R_, G_, B_, A_ = 255 * ea + R_ * (1 - ea), 255 * ea + G_ * (1 - ea), 255 * ea + B_ * (1 - ea), ea + A_ * (1 - ea)
                end
                -- the chevron
                local dg = math.min(HV.LY.seg(px, py, ax_, c - s_, bx_, c), HV.LY.seg(px, py, bx_, c, ax_, c + s_))
                local cg = clamp(th / 2 + 0.5 - dg) * glyph_a
                if cg > 0 then
                    R_, G_, B_, A_ = 255 * cg + R_ * (1 - cg), 255 * cg + G_ * (1 - cg), 255 * cg + B_ * (1 - cg), cg + A_ * (1 - cg)
                end
            end
            out[#out + 1] = string.char(math.floor(B_ + 0.5), math.floor(G_ + 0.5), math.floor(R_ + 0.5), math.floor(255 * A_ + 0.5))
        end
        return table.concat(out)
    end), t, t
end
-- ---- TOP 10 badges, painted into a copy of the poster ----
-- glyphs as strokes on a 0-1 box (no font files needed): digits and T, O, P
HV.LY.GLYPH = {
    ["0"] = { { 0.5, 0, 0.9, 0.12, 1, 0.5, 0.9, 0.88, 0.5, 1, 0.1, 0.88, 0, 0.5, 0.1, 0.12, 0.5, 0 } },
    ["1"] = { { 0.25, 0.2, 0.6, 0, 0.6, 1 }, { 0.25, 1, 0.95, 1 } },
    ["2"] = { { 0.05, 0.2, 0.3, 0.02, 0.7, 0.02, 0.95, 0.22, 0.9, 0.45, 0.05, 1, 0.98, 1 } },
    ["3"] = { { 0.05, 0.1, 0.4, 0, 0.85, 0.08, 0.9, 0.35, 0.45, 0.5, 0.95, 0.65, 0.88, 0.92, 0.45, 1, 0.05, 0.9 } },
    ["4"] = { { 0.75, 1, 0.75, 0, 0.02, 0.68, 1, 0.68 } },
    ["5"] = { { 0.92, 0, 0.12, 0, 0.06, 0.45, 0.55, 0.38, 0.95, 0.62, 0.85, 0.92, 0.45, 1, 0.05, 0.9 } },
    ["6"] = { { 0.85, 0.05, 0.45, 0, 0.1, 0.3, 0.02, 0.7, 0.3, 1, 0.75, 0.98, 0.98, 0.7, 0.75, 0.45, 0.3, 0.45, 0.04, 0.62 } },
    ["7"] = { { 0.02, 0, 0.98, 0, 0.38, 1 } },
    ["8"] = { { 0.5, 0.48, 0.12, 0.3, 0.2, 0.05, 0.5, 0, 0.8, 0.05, 0.88, 0.3, 0.5, 0.48, 0.05, 0.72, 0.18, 0.96, 0.5, 1, 0.82, 0.96, 0.95, 0.72, 0.5, 0.48 } },
    ["9"] = { { 0.96, 0.38, 0.7, 0.55, 0.25, 0.55, 0.02, 0.3, 0.25, 0.02, 0.7, 0, 0.96, 0.3, 0.9, 0.7, 0.55, 1, 0.15, 0.95 } },
    T = { { 0, 0, 1, 0 }, { 0.5, 0, 0.5, 1 } },
    O = { { 0.5, 0, 0.92, 0.15, 1, 0.5, 0.92, 0.85, 0.5, 1, 0.08, 0.85, 0, 0.5, 0.08, 0.15, 0.5, 0 } },
    P = { { 0, 1, 0, 0, 0.7, 0, 0.98, 0.15, 0.98, 0.42, 0.7, 0.55, 0, 0.55 } },
}
-- coverage (0-1) of a text at (x, y) in the box: str's glyphs side by side, gw wide each, gap apart
function HV.LY.ink(str, x, y, ox, oy, gw, gh, gap, th)
    local best = 1e9
    for i = 1, #str do
        local gx = ox + (i - 1) * (gw + gap)
        if x >= gx - th and x <= gx + gw + th then
            for _, pl in ipairs(HV.LY.GLYPH[str:sub(i, i)] or {}) do
                for k = 1, #pl - 3, 2 do
                    local d = HV.LY.seg(x, y, gx + pl[k] * gw, oy + pl[k + 1] * gh, gx + pl[k + 2] * gw, oy + pl[k + 3] * gh)
                    if d < best then best = d end
                end
            end
        end
    end
    return math.max(0, math.min(1, th / 2 + 0.5 - best))
end
-- f (w x h poster) with a TOP badge for rank n in its top-left corner; the copy is kept next to the poster
function HV.LY.badged(f, w, h, n, hex)
    local out = f:gsub("%.bgra$", "") .. string.format(".top%d_%s.bgra", n, hex)
    if HV.LY.files[out] then return out end
    local fi = utils.file_info(out)
    if fi and fi.size == w * h * 4 then HV.LY.files[out] = true; return out end
    if HV.LY.busy() then return f end             -- the plain poster this frame, its badge in a moment
    local bt0 = mp.get_time()
    local src = io.open(f, "rb")
    local data = src and src:read("*a")
    if src then src:close() end
    if not data or #data ~= w * h * 4 then return f end
    local r, g, b = HV.LY.rgb(hex)
    local bw = math.max(18, math.floor(w * 0.17 + 0.5))
    local bh = math.floor(bw * 1.32)
    local bx = math.max(2, math.floor(w * 0.045 + (HV.R or 0) * 0.35))
    local num = tostring(n)
    local th1 = math.max(1.1, bw * 0.055)             -- "TOP": thin
    local th2 = math.max(1.6, bw * 0.12)              -- the number: bold
    local tw, tgh = bw * 0.17, bw * 0.17
    local tgap = bw * 0.05
    local tox = (bw - (3 * tw + 2 * tgap)) / 2
    local ng = (#num == 1) and bw * 0.42 or bw * 0.33
    local ngap = bw * 0.06
    local nox = (bw - (#num * ng + (#num - 1) * ngap)) / 2
    local noy, ngh = bh * 0.38, bh * 0.5
    -- the tab itself (ink and corners) is the same for every poster of this rank and size: worked out once
    HV.LY.tabs = HV.LY.tabs or {}
    local tkey = num .. "|" .. bw .. "|" .. bh .. "|" .. hex
    local tab = HV.LY.tabs[tkey]
    if not tab then
        tab = {}
        local cr = bw * 0.12
        for y = 0, bh - 1 do
            for x = 0, bw - 1 do
                local px_, py_ = x + 0.5, y + 0.5
                local c = math.max(HV.LY.ink("TOP", px_, py_, tox, bh * 0.1, tw, tgh, tgap, th1), HV.LY.ink(num, px_, py_, nox, noy, ng, ngh, ngap, th2))
                -- red tab under white ink; its bottom corners rounded a little
                local inside = 1
                if y > bh - cr then
                    local dx = (x < cr) and (cr - px_) or ((x > bw - cr) and (px_ - (bw - cr)) or 0)
                    local dy = py_ - (bh - cr)
                    if dx > 0 then inside = math.max(0, math.min(1, cr - math.sqrt(dx * dx + dy * dy) + 0.5)) end
                end
                tab[#tab + 1] = { r + (255 - r) * c, g + (255 - g) * c, b + (255 - b) * c, inside }
            end
        end
        HV.LY.tabs[tkey] = tab
    end
    local parts, pos = {}, 1
    local ti = 0
    for y = 0, bh - 1 do
        local off = (y * w + bx) * 4
        parts[#parts + 1] = data:sub(pos, off)
        local row = {}
        for x = 0, bw - 1 do
            ti = ti + 1
            local tp = tab[ti]
            local cr_, cg_, cb_, a = tp[1], tp[2], tp[3], tp[4]
            local i0 = off + x * 4
            local ob, og, orr, oa = data:byte(i0 + 1, i0 + 4)
            -- the tab over the poster pixel (both premultiplied)
            row[#row + 1] = string.char(math.floor(cb_ * a + ob * (1 - a) + 0.5), math.floor(cg_ * a + og * (1 - a) + 0.5),
                math.floor(cr_ * a + orr * (1 - a) + 0.5), math.floor(255 * a + oa * (1 - a) + 0.5))
        end
        parts[#parts + 1] = table.concat(row)
        pos = off + bw * 4 + 1
    end
    parts[#parts + 1] = data:sub(pos)
    local o_ = io.open(out, "wb")
    if not o_ then return f end
    o_:write(table.concat(parts)); o_:close()
    HV.LY.files[out] = true
    HV.LY.spent = HV.LY.spent + (mp.get_time() - bt0)
    return out
end
-- focus_style=dim: the four bands around the selected card's hole, over everything in the rows' area
function HV.LY.dim_on()
    local fs = tostring(o.focus_style or "dim"):lower()
    return fs == "dim" and HV.dw_ok() and not MS.debug
end
function HV.LY.place_dim(used, area, hole, op)
    if not (area and hole) then return end
    local f = HV.LY.solid(THEME.bg_dim, op or math.max(0, math.min(90, tonumber(o.dim_others_pct) or 45)))
    if not f then return end
    local L, T, R, B = math.floor(area[1]), math.floor(area[2]), math.floor(area[3]), math.floor(area[4])
    local x1, y1 = math.floor(math.min(R, math.max(L, hole[1]))), math.floor(math.min(B, math.max(T, hole[2])))
    local x2, y2 = math.floor(math.max(x1, math.min(R, hole[3]))), math.floor(math.max(y1, math.min(B, hole[4])))
    local bands = { { L, T, R, y1 }, { L, y2, R, B }, { L, y1, x1, y2 }, { x2, y1, R, y2 } }
    for i, bd in ipairs(bands) do
        local id = HV.LY.ID_DIM + i - 1
        local bw, bh = bd[3] - bd[1], bd[4] - bd[2]
        if bw > 0 and bh > 0 then
            local sig = f .. "@" .. bd[1] .. "," .. bd[2] .. "~" .. bw .. "x" .. bh
            if HV.shown[id] ~= sig then HV.overlay_add(id, bd[1], bd[2], f, 4, 4, sig, bw, bh) end
            used[id] = true
        end
    end
end
-- the bottom fade over a row cut off at y = cut
function HV.LY.place_fade(used, m, cut)
    if not (cut and HV.dw_ok()) or MS.debug then return end
    local fh = math.max(8, math.floor(m.lfs * 3.2))
    local f = HV.LY.vfade(THEME.bg_dim, fh, HV.bg_alpha() / 100)
    if not f then return end
    local y = math.floor(cut) - fh
    local sig = f .. "@0," .. y .. "~" .. m.w
    if HV.shown[HV.LY.ID_FADE] ~= sig then HV.overlay_add(HV.LY.ID_FADE, 0, y, f, 4, fh, sig, m.w, fh) end
    used[HV.LY.ID_FADE] = true
end

-- the zoom transition's reveal: row n of cards shows at REV_ROW0 + n * REV_ROW s after the poster arrived
HV.REV_DUR, HV.REV_ROW0, HV.REV_ROW, HV.REV_LINE = 0.75, 0.10, 0.08, 0.035
function HV.rev_k()
    local R = HV.REV
    if not R then return nil end
    local t = U.now_s() - R.t0
    if t >= HV.REV_DUR then HV.REV = nil; return nil end
    return t
end
-- the order of each visible row (0 = the first one on screen)
function HV.rev_order()
    local ord, n = {}, 0
    for _, v in ipairs(HV.vis or {}) do if ord[v.ri] == nil then ord[v.ri] = n; n = n + 1 end end
    return ord
end
-- true while the open transition (zoom) holds the page back: lines and rows are still hidden
function HV.rev_hold() return HV.zoom() and HV.TR.st ~= nil and HV.TR.st.kind == "open" end

HV.OV = {}
function HV.OV.which()
    if HV.TK.is_open() then return "tk" end
    local P = HV.dlc()
    if P and P.kind == "win" then return "dl" end
    return nil
end
function HV.OV.key(key, e)
    if HV.mode ~= "add" then return false end
    local which = HV.OV.which()
    if not which then return false end
    if key == "?" or key == "Shift+/" then return false end
    for _, k in ipairs(U.kb("doctor")) do if k == key then return false end end
    if type(e) == "table" and e.event == "up" then return true end
    local KEYS = HV.KEYS or {}
    local function is(list) for _, x in ipairs(list or {}) do if x == key then return true end end return false end
    local up = is(KEYS.up) or key == "GAMEPAD_DPAD_UP"
    local down = is(KEYS.down) or key == "GAMEPAD_DPAD_DOWN"
    local enter = is(KEYS.enter) or key == "GAMEPAD_ACTION_DOWN"
    local back = key == "ESC" or is(KEYS.bs) or is(U.kb("back")) or key == "GAMEPAD_ACTION_RIGHT"
    if which == "tk" then
        if up then HV.TK.move(-1) elseif down then HV.TK.move(1)
        elseif enter then HV.TK.enter()
        elseif key == "SPACE" then local r = HV.TK.sorted()[HV.TK.sel]; if r then HV.TK.cycle_bell(r.k) end
        elseif key == "DEL" or key == "KP_DEL" then HV.TK.remove_sel()
        elseif back or is(U.kb("tracked")) then HV.TK.close() end
    else
        if up then TV.dl_move(-1) elseif down then TV.dl_move(1)
        elseif enter then TV.dl_go()
        elseif key == "SPACE" then TV.dl_toggle()
        elseif key == "DEL" or key == "KP_DEL" then HV.dl_remove()
        elseif back or is(U.kb("downloads")) then HV.dl_close() end
    end
    return true             -- anything else waits until it is closed (no typing into the search box behind it)
end
-- the home page's pop-ups take the keys they use; every other key waits until they close (B2: S, V, M... used to act
-- on the card hidden behind the Tracked flyout, a menu or the help sheet)
function HV.ov_block(key)
    if not browser_active or HV.mode == "add" or MS.view ~= "home" then return false end
    local hp = HV.HP and HV.HP.open
    if not (hp or HV.TK.is_open() or HV.CM.open or HV.dlc()) then return false end
    local function is(list) for _, x in ipairs(list or {}) do if x == key then return true end end return false end
    local K = HV.KEYS or {}
    local k = tostring(key)
    local back = key == "ESC" or is(K.bs) or is(U.kb("doctor")) or is(U.kb("close")) or is(U.kb("back"))
        or k == "GAMEPAD_ACTION_RIGHT" or k == "GO_BACK" or k == "BACK" or k == "CANCEL"
    if back or key == "?" or key == "Shift+/" then return false end
    for ok_ in tostring(o.open_key or ""):gmatch("[^%s,]+") do if ok_ == key then return false end end
    if hp and (key == "MBTN_LEFT" or key == "MBTN_LEFT_DBL") then return false end     -- (HV.HP.click: outside or ✕ closes it)
    if hp then return true end
    local pad_nav = k:match("^GAMEPAD_DPAD") or k:match("^GAMEPAD_LEFT_STICK") or k == "GAMEPAD_ACTION_DOWN"
        or k == "GAMEPAD_LEFT_SHOULDER" or k == "GAMEPAD_RIGHT_SHOULDER"
    if is(K.up) or is(K.down) or is(K.left) or is(K.right) or is(K.enter) or key == "SPACE" or key == "DEL" or key == "KP_DEL"
        or pad_nav or is(U.kb("tracked")) or is(U.kb("downloads")) or is(U.kb("up")) or is(U.kb("down")) then return false end
    if HV.dlc() then
        if key == "Shift+UP" or key == "Shift+DOWN" or is(U.kb("switch_view")) or is(U.kb("queue")) then return false end
        if is(U.kb("sort")) and HV.DLC and HV.DLC.kind == "win" then return false end
    end
    return true
end
-- ---- the key hints are buttons: a click on "S Sort" presses S ----
U.HRAW = {}
function HV.MU_on() return o.experimental_mouse_ui == true end
-- the key an item of a hint stands for (what mpv calls it), nil for "←↑↓→ Move" and the like
function HV.hint_key(item)
    if U.HRAW[item] then return U.HRAW[item] end
    local k = tostring(item):match("^(%S+)")
    if not k then return nil end
    local named = { Enter = "ENTER", Esc = "ESC", Tab = "TAB", Space = "SPACE", Del = "DEL", Backspace = "BS", PgUp = "PGUP", PgDn = "PGDWN",
                    Home = "HOME", End = "END", F1 = "F1", ["/"] = "/", ["?"] = "?" }
    if named[k] then return named[k] end
    if k:match("^%a$") then return k:lower() end
    local mod, key = k:match("^(%a+)%+(%w+)$")
    if mod and key then return mod:lower() .. "+" .. ((#key == 1) and key:lower() or key:upper()) end
    return nil
end
-- the hint as separate items, each clickable (link(x1, y1, x2, y2, id, act), hot(id))
function HV.hint_items(add, m, x, y1, y2, txt, fs, link, hot)
    local cy = (y1 + y2) / 2
    local sep = HV.AX.tw("   ", fs)
    local muted, white = U.ass_color(THEME.text_muted), U.ass_color("FFFFFF")
    local i = 0
    for item in (txt .. "   "):gmatch("(.-)   +") do
        if item ~= "" then
            i = i + 1
            local k, rest = item:match("^(%S+)%s*(.*)$")
            local iw = HV.AX.tw(k or item, fs, true) + ((rest and rest ~= "") and HV.AX.tw(" " .. rest, fs) or 0)
            local key = HV.hint_key(item)
            local id = "hint" .. i
            local h = key and hot(id)
            if h then add(D.ev_rect(x - fs * 0.45, y1 + 3, x + iw + fs * 0.45, y2 - 3, "FFFFFF", 14, nil, 0, 0, (y2 - y1) / 2)) end
            add(D.ev_text(x, cy, 4, string.format("\\fs%d", fs), string.format("{\\b1\\c%s}%s{\\b0\\c%s}%s", white, U.ass_escape(k or item),
                h and white or muted, (rest and rest ~= "") and (" " .. U.ass_escape(rest)) or "")))
            if key then link(x - fs * 0.45, y1, x + iw + fs * 0.45, y2, id, function() mp.commandv("keypress", key) end) end
            x = x + iw + sep
        end
    end
end

-- ---- hover buttons on a card: play, queue, watched, download (a picture above the poster) ----
HV.LY.ID_ACT = 59
function HV.card_actions(card)
    if not card then return {} end
    local function sel_and(f) return function()
        for ri, row in ipairs(HV.rows or {}) do for ci, c in ipairs(row.cards or {}) do if c == card then HV.r, HV.c = ri, ci end end end
        f()
    end end
    if card.kind == "ep" then
        return { { g = "play", act = sel_and(HV.activate) }, { g = "queue", act = sel_and(HV.queue_selected) },
                 { g = card.watched and "watched_on" or "watched", act = sel_and(HV.toggle_watched) },
                 { g = "dl", act = function() if TV.card then HV.DL.add(TV.card.shown or TV.card.title, TV.card.key, { { href = card.entry.href, name = card.entry.name, size = card.entry.size } }) end end } }
    elseif card.kind == "play" and card.entry then
        return { { g = "play", act = sel_and(HV.activate) }, { g = "queue", act = function() play_entry(card.entry, true) end },
                 { g = "dl", act = function() HV.DL.add(card.shown or card.title, card.key, { { href = card.entry.href, name = card.entry.name, size = card.entry.size } }) end } }
    elseif card.kind == "folder" then
        return { { g = "play", act = function() TV.open(card); TV.auto = "play" end },
                 { g = "dl", act = function() TV.open(card); TV.auto = "dl" end },
                 { g = "find", act = function() HV.find_more_card(card) end } }
    end
    return {}
end
function HV.find_more_card(card)
    HV.AX.open()
    if HV.mode ~= "add" then return end
    local AX = HV.AX
    local q = card.shown or card.title or ""
    AX.q, AX.qc, AX.fedit = q, #q, false
    AX.search()
end
-- the picture: n round glass buttons in a row (hot = the one under the pointer)
function HV.LY.actbar(glyphs, d, gap, hot)
    local n = #glyphs
    local sh = math.max(2, math.floor(d * 0.18))
    local W, H = n * d + (n - 1) * gap + 2 * sh, d + 2 * sh
    local key = string.format("ly_ab_%d_%d_%s_%d", d, gap, table.concat(glyphs, "-"), hot or 0)
    local seg = HV.LY.seg
    local th = math.max(1.5, d * 0.08)
    local function clamp(v) return v < 0 and 0 or (v > 1 and 1 or v) end
    local function stroke(dist) return clamp(th / 2 + 0.5 - dist) end
    local shapes = {
        play = function(u, v)
            -- a filled triangle (soft edges)
            local x1, y1, x2, y2, x3, y3 = -0.13 * d, -0.19 * d, 0.2 * d, 0, -0.13 * d, 0.19 * d
            local function e(ax, ay, bx, by) local nx, ny = by - ay, ax - bx; local l = math.sqrt(nx * nx + ny * ny); return ((u - ax) * nx + (v - ay) * ny) / l end
            return clamp(0.5 - math.max(e(x1, y1, x2, y2), e(x2, y2, x3, y3), e(x3, y3, x1, y1)))
        end,
        queue = function(u, v) return stroke(math.min(seg(u, v, -0.18 * d, 0, 0.18 * d, 0), seg(u, v, 0, -0.18 * d, 0, 0.18 * d))) end,
        watched = function(u, v) return stroke(math.min(seg(u, v, -0.17 * d, 0.01 * d, -0.05 * d, 0.13 * d), seg(u, v, -0.05 * d, 0.13 * d, 0.19 * d, -0.13 * d))) end,
        dl = function(u, v) return stroke(math.min(seg(u, v, 0, -0.2 * d, 0, 0.08 * d), seg(u, v, -0.12 * d, -0.03 * d, 0, 0.09 * d), seg(u, v, 0, 0.09 * d, 0.12 * d, -0.03 * d), seg(u, v, -0.17 * d, 0.19 * d, 0.17 * d, 0.19 * d))) end,
        find = function(u, v)
            local cx, cy, r = -0.04 * d, -0.04 * d, 0.12 * d
            local ring = math.abs(math.sqrt((u - cx) ^ 2 + (v - cy) ^ 2) - r)
            return stroke(math.min(ring, seg(u, v, 0.05 * d, 0.05 * d, 0.18 * d, 0.18 * d)))
        end,
    }
    shapes.watched_on = shapes.watched
    return HV.LY.make(key, W, H, function(y)
        local out = {}
        local py = y + 0.5
        for x = 0, W - 1 do
            local px = x + 0.5
            local i = math.max(1, math.min(n, math.floor((px - sh + gap / 2) / (d + gap)) + 1))
            local cx, cy = sh + (i - 1) * (d + gap) + d / 2, sh + d / 2
            local dx, dy = px - cx, py - cy
            local dist = math.sqrt(dx * dx + dy * dy)
            local r = d / 2
            local dys = py - (cy + d * 0.06)
            local sa = 0.35 * clamp((r + sh - math.sqrt(dx * dx + dys * dys)) / (sh * 1.2))
            sa = sa * sa
            local R_, G_, B_, A_ = 0, 0, 0, sa
            local cd = clamp(r - dist + 0.5)
            if cd > 0 then
                local isHot = (i == hot)
                local on = glyphs[i] == "watched_on"
                local fr, fg, fb = 22, 22, 26
                if on then local ar, ag, ab = HV.LY.rgb(THEME.accent); fr, fg, fb = ar, ag, ab end
                local a = (isHot and 0.9 or 0.72) * cd
                R_, G_, B_, A_ = fr * a + R_ * (1 - a), fg * a + G_ * (1 - a), fb * a + B_ * (1 - a), a + A_ * (1 - a)
                local ce = clamp(1 - math.abs(dist - (r - 0.9)) / 0.9) * cd * (isHot and 0.45 or 0.25)
                if ce > 0 then R_, G_, B_, A_ = 255 * ce + R_ * (1 - ce), 255 * ce + G_ * (1 - ce), 255 * ce + B_ * (1 - ce), ce + A_ * (1 - ce) end
                local f = shapes[glyphs[i]]
                local cg = f and f(dx, dy) or 0
                if cg > 0 then R_, G_, B_, A_ = 255 * cg + R_ * (1 - cg), 255 * cg + G_ * (1 - cg), 255 * cg + B_ * (1 - cg), cg + A_ * (1 - cg) end
            end
            out[#out + 1] = string.char(math.floor(B_ + 0.5), math.floor(G_ + 0.5), math.floor(R_ + 0.5), math.floor(255 * A_ + 0.5))
        end
        return table.concat(out)
    end), W, H, sh
end

-- ---- right-click: a menu for the title under the pointer ----
HV.CM = { open = false }
function HV.CM.items(card)
    local L = {}
    local function sel_and(f) return function()
        for ri, row in ipairs(HV.rows or {}) do for ci, c in ipairs(row.cards or {}) do if c == card then HV.r, HV.c = ri, ci end end end
        f()
    end end
    if card.kind == "folder" then
        L[#L + 1] = { "Open", sel_and(HV.activate) }
        L[#L + 1] = { "Play", function() TV.open(card); TV.auto = "play" end }
        L[#L + 1] = { "Download…", function() TV.open(card); TV.auto = "dl" end }
        if HV.AX.enabled() then L[#L + 1] = { "Find more on the add-ons", function() HV.find_more_card(card) end } end
        L[#L + 1] = { "Re-fetch artwork", sel_and(HV.refetch) }
        L[#L + 1] = { "Show in the list view", sel_and(HV.open_list) }
    elseif card.kind == "ep" then
        L[#L + 1] = { "Play", sel_and(HV.activate) }
        L[#L + 1] = { "Add to the queue", sel_and(HV.queue_selected) }
        L[#L + 1] = { card.watched and "Mark unwatched" or "Mark watched", sel_and(HV.toggle_watched) }
        L[#L + 1] = { "Download this file", function() if TV.card then HV.DL.add(TV.card.shown or TV.card.title, TV.card.key, { { href = card.entry.href, name = card.entry.name, size = card.entry.size } }) end end }
    elseif card.kind == "play" and card.entry then
        L[#L + 1] = { "Resume", sel_and(HV.activate) }
        L[#L + 1] = { "Add to the queue", function() play_entry(card.entry, true) end }
        L[#L + 1] = { "Download this file", function() HV.DL.add(card.shown or card.title, card.key, { { href = card.entry.href, name = card.entry.name, size = card.entry.size } }) end }
    end
    return L
end
function HV.CM.show(card, x, y)
    local L = HV.CM.items(card)
    if #L == 0 then return end
    HV.TK.open, HV.TK.closing = false, nil
    HV.CM.open, HV.CM.card, HV.CM.list, HV.CM.x, HV.CM.y, HV.CM.sel, HV.CM.t0 = true, card, L, x, y, nil, U.now_s()
    HV.last_data = nil
    HV.anim_kick(0.25)
    render()
end
function HV.CM.close()
    if not HV.CM.open then return end
    HV.CM.open, HV.CM.hole, HV.CM.links = false, nil, nil
    HV.btn_hover = nil
    HV.last_data = nil
    render()
end
function HV.CM.run(i)
    HV.last_act = U.now_s()
    local it = HV.CM.list and HV.CM.list[i]
    HV.CM.close()
    if it then it[2]() end
end
function HV.CM.move(d)
    local n = #(HV.CM.list or {})
    if n == 0 then return end
    HV.CM.sel = math.max(1, math.min(n, (HV.CM.sel or 0) + d))
    HV.last_data = nil
    render()
end
function HV.CM.draw(add, m)
    local C = HV.CM
    C.links = {}
    local P = { links = C.links, fade = HV.anim_on() and HV.ease((U.now_s() - (C.t0 or 0)) / 0.14) or 1 }
    local K = HV.dl_kit(add, m, P)
    local fs = K.fs3
    local rh = math.floor(fs * 2.2)
    local wmax = 0
    for _, it in ipairs(C.list) do wmax = math.max(wmax, HV.AX.tw(it[1], fs, true)) end
    local cw = math.floor(wmax + K.pad * 2.4)
    local ch = #C.list * rh + K.pad
    local x1 = math.min(C.x + 4, m.w - m.mx - cw)
    local y1 = math.min(C.y + 4, m.h - m.foot_h - ch)
    K.body(x1, y1, x1 + cw, y1 + ch, P.fade)
    C.hole = P.hole
    for i, it in ipairs(C.list) do
        local ry = y1 + K.pad / 2 + (i - 1) * rh
        local id = "cm" .. i
        local hot = HV.btn_hover == id or C.sel == i
        if hot then add(D.ev_rect(x1 + K.pad * 0.4, ry + 2, x1 + cw - K.pad * 0.4, ry + rh - 2, TOAST.text, 12 * P.fade, nil, 0, 0, math.floor(rh * 0.3))) end
        K.txt(x1 + K.pad * 1.2, ry + rh / 2, 4, fs, hot and 100 or 85, hot, it[1])
        local ii = i
        K.link(x1, ry, x1 + cw, ry + rh, id, function() HV.CM.run(ii) end)
    end
end
HV.input = "keys"
function HV.mouse_mode() return HV.input == "mouse" and o.hover_lift and HV.dw_ok() end
function HV.key_input()
    if HV.reveal_t then HV.reveal_t:kill(); HV.reveal_t = nil end
    if HV.input == "keys" then return end
    HV.input = "keys"
    local hv = HV.hover
    if HV.mode ~= "add" and hv and HV.rows and HV.rows[hv.r] and HV.rows[hv.r].cards[hv.c] then
        HV.r, HV.c, HV.bfocus = hv.r, hv.c, nil
        HV.fix_off(HV.m)
        HV.want_vc = HV.vcol()
    end
    HV.last_data = nil
end
function HV.mouse_input()
    if HV.input == "mouse" then return end
    HV.input = "mouse"
    HV.last_data = nil
end
HV.PF = { key = nil, t = nil, done = {} }
function HV.prefetch_card(card)
    if not card or card.kind ~= "folder" then return end
    local P = HV.PF
    if P.key == card.key then return end
    P.key = card.key
    if P.t then P.t:kill() end
    P.t = mp.add_timeout(0.35, function()
        P.t = nil
        if P.key ~= card.key or P.done[card.key] or not browser_active or HV.mode ~= "home" then return end
        P.done[card.key] = true
        for i, fo in ipairs(card.folders or {}) do
            if i > 4 then break end
            if fo.href and not find_cached_dir(fo.href) then fetch_listing(fo.href, { silent = true }) end
        end
        if PS.enabled() then
            PS.load_index()
            local e = PS.idx[card.key]
            if type(e) == "table" and e.id and not e.none then
                if e.dv ~= 26 then PS.details(e, function() end) end
                local m = HV.m
                if m and o.title_logo and HV.XV.logo_path(e) then HV.XV.logo(e, 440 * m.S, (m.lfs + 14) * 2.3) end
                if m then
                    -- the title page's band, as HV.metrics works it out for that page
                    local w0, h0 = U.canvas_size()
                    local hs, ws = HV.step_h(h0), HV.step_w(w0)
                    local hero_h = math.floor(hs * (o.hero_poster == false and 0.25 or 0.31) * math.max(0.8, math.min(1.3, (tonumber(o.hero_poster_pct) or 100) / 100)))
                    local list = {}
                    if o.hero_poster ~= false then list[#list + 1] = { key = card.key, title = card.title, year = card.year, dw = math.floor((hero_h - 20) * 2 / 3), dh = hero_h - 20, pri = 1 } end
                    if o.experimental_backdrop and (e.backdrop_path or "") ~= "" and HV.conv_mode() ~= "magick" then
                        local bw = math.min(math.floor(hero_h * 16 / 9), math.floor(ws * 0.5))
                        list[#list + 1] = { key = "bdhero:" .. PS.aid(e), dw = bw, dh = hero_h, fade = HV.FADE_KEY, pri = 1,
                            still = { size = HV.img_size("backdrop", bw), path = e.backdrop_path, base = "b" .. PS.aid(e) } }
                    end
                    if #list > 0 then P.extra = { key = card.key, list = list }; HV.kick() end
                end
            end
        end
    end)
end
function HV.modal() return (HV.HP and HV.HP.open) or (HV.DR and HV.DR.open) or false end
function HV.place()
    local used = {}
    if HV.modal() then
        for id in pairs(HV.shown) do HV.cmd({ "overlay-remove", tostring(id) }); HV.shown[id] = nil end
        return
    end
    -- the download card is open: no picture inside its hole, everything else dimmed
    local mask = (HV.DLC and browser_active and HV.mode ~= "add" and HV.DLC.hole) or (HV.TK.drawn() and HV.TK.hole) or (HV.CM.open and HV.CM.hole) or nil
    local cap = HV.TK.drawn() and 40 or HV.CARD_IDS
    local ncards = cap > 42 and cap - 1 or cap
    local function masked(x, y, w_, h_) return mask and x < mask[3] and x + w_ > mask[1] and y < mask[4] and y + h_ > mask[2] end
    local rev_t = HV.rev_k()
    local rev_ord = rev_t and HV.rev_order() or nil
    if HV.TR.busy() then
        for id in pairs(HV.shown) do HV.cmd({ "overlay-remove", tostring(id) }); HV.shown[id] = nil end
        return
    end
    if not MS.debug then
        local sk = HV.m.sk
        -- Every card keeps its overlay id while it stays on screen (ids used to follow the screen position, so during a
        -- scroll each id was handed a different picture and mpv briefly showed posters in the wrong places).
        HV.ids = HV.ids or {}
        local live = {}
        for i, cd in ipairs(HV.vis_cards) do if i <= ncards then live[cd.uid] = true end end
        local taken = {}
        for uid, id in pairs(HV.ids) do
            if live[uid] and id < cap then taken[id] = true else HV.ids[uid] = nil end
        end
        local nextfree = 0
        taken[42] = true                 -- thumbfast's overlay id: left to it
        local function alloc()
            while taken[nextfree] do nextfree = nextfree + 1 end
            taken[nextfree] = true
            return nextfree
        end
        local cut_at, sel_vc = nil, nil
        for i, cd in ipairs(HV.vis_cards) do
            if cd.cut then cut_at = cd.cut end
            if cd.foc and not cd.cut then sel_vc = cd end
        end
        -- the layers above the posters: the soft fade where a row is cut off, the dimming around the selection, the
        -- arrows of rows that scroll sideways
        -- (leaving, experimental_exit_to_video: these layers go first, the posters shrink away under the fading page)
        local lyr = not HV.XA.exit
        if not mask and lyr then HV.LY.place_fade(used, HV.m, cut_at) end
        for i, c in ipairs(HV.lyc or {}) do
            if i > 6 or HV.REV or mask or not lyr then break end
            local cf = HV.LY.chevron(THEME.bg_dim, c.w, c.h, c.dir, c.hot)
            if cf then
                local id = HV.LY.ID_CHEV + i - 1
                local sig = cf .. "@" .. c.x .. "," .. c.y
                if HV.shown[id] ~= sig then HV.overlay_add(id, c.x, c.y, cf, c.w, c.h, sig) end
                used[id] = true
            end
        end
        -- the hover buttons on the card under the pointer (experimental_mouse_ui)
        local hb_ = HV.hab
        if hb_ and not mask and not HV.REV and lyr then
            local af = HV.LY.actbar(hb_.glyphs, hb_.d, hb_.gap, hb_.hot)
            if af then
                local sh_ = math.max(2, math.floor(hb_.d * 0.18))
                local W = #hb_.glyphs * hb_.d + (#hb_.glyphs - 1) * hb_.gap + 2 * sh_
                local H = hb_.d + 2 * sh_
                local sig = af .. "@" .. hb_.x .. "," .. hb_.y
                if HV.shown[HV.LY.ID_ACT] ~= sig then HV.overlay_add(HV.LY.ID_ACT, hb_.x, hb_.y, af, W, H, sig) end
                used[HV.LY.ID_ACT] = true
            end
        end
        if mask then
            if HV.dw_ok() and HV.dlc() and HV.DLC.dim then HV.LY.place_dim(used, { 0, 0, HV.m.w, HV.m.h }, mask, 62) end
        elseif sel_vc and lyr and HV.LY.dim_on() and #HV.vis_cards > 1 and not HV.typing and not HV.bfocus then
            local m = HV.m
            local rp = HV.ring_pad(m) + math.max(3, math.floor(3 * m.S + 0.5))
            local top = HV.rows_y(m)
            local hole = { sel_vc.x - rp, sel_vc.y - rp, sel_vc.x + sel_vc.w + rp, sel_vc.y + sel_vc.h + rp + m.bar_h + m.label_h }
            HV.LY.place_dim(used, { 0, top, m.w, cut_at or (m.h - m.foot_h) }, hole)
        end
        local blur_mo = o.scroll_blur ~= false and HV.scrolling() and HV.dw_ok()
        local blur_xa = o.scroll_blur ~= false and HV.dw_ok()
        for i, cd in ipairs(HV.vis_cards) do
            if i > ncards then break end
            local st = HV.items[cd.card.key]
            local cw_, ch_ = cd.w or HV.m.cw, cd.h or HV.m.ch
            local f = HV.bgra_of(st, cd.sk or sk)
            local fw, fh = cw_, ch_
            if not f then f, fw, fh = HV.alt_bgra(st, cd.sk or sk) end      -- another size, scaled, until this one is ready
            local sf, sfw, sfh = f, fw, fh
            if f and (blur_mo or (blur_xa and HV.XA.moving(cd.ri))) then
                local tf, ttw, tth = HV.tiny_of(st, cw_, ch_)
                if tf then f, fw, fh = tf, ttw, tth end
            end
            if f and rev_t and HV.mode == "title" and rev_t < HV.REV_ROW0 + (rev_ord[cd.ri] or 0) * HV.REV_ROW then f = nil end
            -- under a pop-up: the lines above it are still shown (the pop-up's dimming covers the rest on 0.38+)
            local mcut = nil
            if f and masked(cd.x, cd.y, cw_, ch_) then
                if cd.y < mask[2] - 2 then mcut = mask[2] else f = nil end
            end
            if f then
                local id = HV.ids[cd.uid]
                if not id then id = alloc(); HV.ids[cd.uid] = id end
                local px, py = math.floor(cd.x + 0.5), math.floor(cd.y + 0.5)        -- overlay-add needs whole pixels
                -- a peeking row is cut at the footer: only the top lines of the bitmap are handed to mpv
                local cutv = cd.cut
                if mcut then cutv = math.min(cutv or 1e9, mcut) end
                local vh = cutv and math.min(ch_, math.floor(cutv) - py) or ch_
                -- a row gliding past the top edge: the lines above it are skipped (overlay-add's offset)
                local top_skip, src_skip = 0, 0
                if cd.clip and py < cd.clip then
                    top_skip = math.floor(cd.clip) - py
                    src_skip = math.min(fh - 1, math.floor(top_skip * fh / ch_ + 0.5))
                    vh = vh - top_skip
                end
                if cd.par and top_skip == 0 and not cutv and HV.XA.par_on() then
                    local ox, oy = HV.XA.par(cd.x, cd.y, cw_, ch_)
                    px, py = px + ox, py + oy
                end
                local ddw, ddh = cw_, vh
                if HV.XA.exit then
                    if top_skip > 0 then vh = 0 else
                        px, py, ddw, ddh = HV.XA.exit_box(px, py, cw_, vh)
                        if ddw < 2 or ddh < 2 then vh = 0 end
                    end
                end
                if vh > 0 then
                    local function rows(h_, skip) return (vh == ch_) and h_ or math.max(1, math.min(h_ - skip, math.floor((vh + top_skip) * h_ / ch_ + 0.5) - skip)) end
                    local svh = rows(fh, src_skip)
                    -- a card passing the screen's side (a row gliding / dragged): only its part on the screen
                    local hx, hoff, hsw, hdw = HV.XS.hclip(px, ddw, fw, HV.m.w)
                    if not hx then vh = 0 else
                        local sig = f .. "@" .. hx .. "," .. (py + top_skip) .. "/" .. vh .. "~" .. cw_ .. "^" .. hdw .. "x" .. ddh .. ":" .. hoff
                        if HV.shown[id] ~= sig then HV.overlay_add(id, hx, py + top_skip, f, hsw, svh, sig, hdw, ddh, src_skip * fw * 4 + hoff, fw * 4) end
                    end
                    if sf and sf ~= f then
                        HV.TR.disp[cd.uid] = { f = sf, fw = sfw, fh = rows(sfh, math.min(sfh - 1, math.floor(top_skip * sfh / ch_ + 0.5))), x = px, y = py, w = cw_, h = ch_, vh = vh }
                    else
                        HV.TR.disp[cd.uid] = { f = f, fw = fw, fh = svh, x = px, y = py, w = cw_, h = ch_, vh = vh }
                    end
                    if vh > 0 then used[id] = true end
                end
            end
        end
    end
    -- hero poster (title page)
    local hero = HV.hero
    if hero and not MS.debug and HV.mode == "title" then
        local st = HV.items[hero.key]
        local f = st and st.bgra[HV.skey(hero.dw, hero.dh)]
        local fw, fh = hero.dw, hero.dh
        if not f then f, fw, fh = HV.alt_bgra(st, HV.skey(hero.dw, hero.dh)) end
        if f and not masked(hero.x, hero.y, hero.dw, hero.dh) then
            local hx, hy = math.floor(hero.x + 0.5), math.floor(hero.y + 0.5)
            local hdw, hdh = hero.dw, hero.dh
            if HV.XA.exit then hx, hy, hdw, hdh = HV.XA.exit_box(hx, hy, hdw, hdh) end
            local sig = f .. "@" .. hx .. "," .. hy .. "~" .. hdw .. "x" .. hdh
            if hdw >= 2 and HV.shown[61] ~= sig then HV.overlay_add(61, hx, hy, f, fw, fh, sig, hdw, hdh) end
            if hdw >= 2 then used[61] = true end
        end
    end
    -- the Tracked flyout's posters
    if HV.TK.drawn() and not MS.debug and not HV.XA.exit then
        for i, pc in ipairs(HV.TK.pics or {}) do
            if i > 6 then break end
            local id = (39 + i >= 42) and (40 + i) or (39 + i)     -- 40, 41, 43, 44, 45, 46 (42 is thumbfast's)
            local sig = pc.f .. "@" .. pc.x .. "," .. pc.y .. "~" .. pc.w
            if HV.shown[id] ~= sig then HV.overlay_add(id, pc.x, pc.y, pc.f, pc.sw or pc.w, pc.sh or pc.h, sig, pc.w, pc.h) end
            used[id] = true
        end
    end
    -- the title logo (experimental_title_logo)
    local lg = HV.logo
    if lg and not MS.debug and HV.mode == "title" and not (rev_t and rev_t < HV.REV_LINE) then
        local lx, ly, lw, lh = lg.x, lg.y, lg.w, lg.h
        if HV.XA.exit then lx, ly, lw, lh = HV.XA.exit_box(lx, ly, lw, lh) end
        local sig = lg.f .. "@" .. lx .. "," .. ly .. "~" .. lw
        if lw >= 2 and HV.shown[HV.XV.LOGO_ID] ~= sig then HV.overlay_add(HV.XV.LOGO_ID, lx, ly, lg.f, lg.w, lg.h, sig, lw, lh) end
        if lw >= 2 then used[HV.XV.LOGO_ID] = true end
    end
    -- experimental backdrop (title page, beside the text)
    local bd = HV.backdrop
    if bd and not MS.debug and HV.mode == "title" then
        local st = HV.items[bd.key]
        local f = st and st.bgra[bd.sk]
        local fw, fh = bd.dw, bd.dh
        if not f then f, fw, fh = HV.alt_bgra(st, bd.sk) end
        if f and not masked(bd.x, bd.y, bd.dw, bd.dh) then
            -- zoom: the backdrop arrives a little larger and settles (anchored top right, so it never covers the text)
            local bx, bdw, bdh = bd.x, bd.dw, bd.dh
            if rev_t and HV.dw_ok() then
                local g = 1 + 0.06 * (1 - HV.ease(rev_t / HV.REV_DUR))
                bdw, bdh = math.floor(bd.dw * g + 0.5), math.floor(bd.dh * g + 0.5)
                bx = bd.x + bd.dw - bdw
            end
            local by_ = bd.y
            if HV.XA.exit then bx, by_, bdw, bdh = HV.XA.exit_box(bx, by_, bdw, bdh) end
            local sig = f .. "@" .. bx .. "," .. by_ .. "~" .. bdw .. "x" .. bdh
            if bdw >= 2 and HV.shown[62] ~= sig then HV.overlay_add(62, bx, by_, f, fw, fh, sig, bdw, bdh) end
            if bdw >= 2 then used[62] = true end
        end
    end
    for id in pairs(HV.shown) do
        if not used[id] then
            HV.cmd({ "overlay-remove", tostring(id) })
            HV.shown[id] = nil
        end
    end
end

-- ---------- EXPERIMENTAL glass bars ----------
-- One pill: faint glass with a hairline edge and a soft shadow (the look of the toasts). hot = hovered.
function HV.gpill(add, x1, y1, x2, y2, m, tint, tint_a, hot)
    local r = (y2 - y1) / 2
    local b = math.max(4, math.floor(8 * m.S + 0.5))
    add(string.format("{\\an7\\pos(0,0)\\bord0\\shad0\\blur%d\\1c&H000000&\\1a%s\\3a&HFF&\\p1}%s{\\p0}",
        b, U.ass_alpha(30), D.rounded_path(x1, y1 + b * 0.3, x2, y2 + b * 0.5, r)))
    add(D.ev_rect(x1, y1, x2, y2, tint or "FFFFFF", tint_a or (hot and 12 or 6), "FFFFFF", hot and 30 or 17, math.max(1, math.floor(m.S + 0.5)), r))
end
function HV.gpill_a(add, x1, y1, x2, y2, m, tint, tint_a, hot, a)
    local r = (y2 - y1) / 2
    local b = math.max(4, math.floor(8 * m.S + 0.5))
    add(string.format("{\\an7\\pos(0,0)\\bord0\\shad0\\blur%d\\1c&H000000&\\1a%s\\3a&HFF&\\p1}%s{\\p0}",
        b, U.ass_alpha(30 * a), D.rounded_path(x1, y1 + b * 0.3, x2, y2 + b * 0.5, r)))
    add(D.ev_rect(x1, y1, x2, y2, tint or "FFFFFF", (tint_a or (hot and 12 or 6)) * a, "FFFFFF", (hot and 30 or 17) * a, math.max(1, math.floor(m.S + 0.5)), r))
end
-- a magnifier and a funnel, drawn (centred on cx, cy, size s)
function HV.glyph_search(cx, cy, s, rgb, op)
    local r = s * 0.3
    local ox, oy = cx - s * 0.08, cy - s * 0.08
    local th = math.max(1.2, s * 0.11)
    local ring = D.ev_rect(ox - r, oy - r, ox + r, oy + r, rgb, 0, rgb, op, th, r)
    local a = r * 0.72
    local function P(x, y) return D.fp(x) .. " " .. D.fp(y) end
    local hx, hy = ox + a, oy + a
    local d = th * 0.6
    local handle = D.ev_shape(string.format("m %s l %s %s %s", P(hx - d, hy + d), P(hx + d, hy - d), P(cx + s * 0.42 + d, cy + s * 0.42 - d), P(cx + s * 0.42 - d, cy + s * 0.42 + d)), rgb, op)
    return ring .. "\n" .. handle
end
function HV.glyph_funnel(cx, cy, s, rgb, op)
    local function P(x, y) return D.fp(cx + x * s) .. " " .. D.fp(cy + y * s) end
    return D.ev_shape(string.format("m %s l %s %s %s %s %s", P(-0.42, -0.36), P(0.42, -0.36), P(0.1, 0.04), P(0.1, 0.4), P(-0.1, 0.3), P(-0.1, 0.04)), rgb, op)
end
-- The search pill beside Home: "Search  F" until you search, then it opens up into the search field itself
-- (the width eases out); the Filters pill after it shows / hides the chips row ("Filters · 2" while two are on).
function HV.search_pills(add, m, x, y1, ph, fs, pad, limit)
    local y2, cy = y1 + ph, y1 + ph / 2
    local S = m.S
    local searching = HV.q ~= nil
    local nf = 0
    for _ in HV.hf_get():gmatch("%S+") do nf = nf + 1 end
    local fw = 0
    if o.home_filter_chips and not searching and HV.chips ~= nil then
        fw = math.floor(pad + ph * 0.5 + fs * 0.45 + HV.AX.tw("Filters", fs, true) + ((nf > 0) and (fs * 0.5 + HV.AX.tw(tostring(nf), fs - 2, true) + fs) or 0) + pad)
    end
    local key = U.kname("search")
    local w0 = math.floor(pad + ph * 0.5 + fs * 0.45 + HV.AX.tw("Search", fs) + ((key ~= "") and (fs * 0.9 + HV.AX.tw(key, fs - 3)) or 0) + pad)
    local w1 = math.max(w0, math.min(math.floor(m.w * 0.42), math.floor(limit - x - ((fw > 0) and (fw + 8 * S) or 0))))
    local k = HV.anim_val("search", searching and 1 or 0, 0.26)
    local hot = HV.link_hover == 97
    -- experimental_search_collapse: at rest only the magnifier, in a round pill; the pointer opens it to "Search  F"
    local kh = 1
    if HV.XA.on("search_collapse") then kh = HV.anim_val("xa_shov", (hot or searching) and 1 or 0, 0.2) end
    local wr = math.floor(ph + (w0 - ph) * kh)
    local sw = math.floor(wr + (w1 - wr) * k)
    HV.gpill(add, x, y1, x + sw, y2, m, searching and "FFFFFF" or nil, searching and 9 or nil, hot)
    if HV.typing then add(D.ev_rect(x, y1, x + sw, y2, "FFFFFF", 0, THEME.accent, 75 * k, math.max(1, math.floor(S + 0.5)), ph / 2)) end
    local gcol = (hot or searching) and "FFFFFF" or THEME.text_muted
    local gx = x + ph / 2 + (pad + ph * 0.25 - ph / 2) * math.max(kh, k)
    add(HV.glyph_search(gx, cy, ph * 0.5, gcol, 100))
    local tx = x + pad + ph * 0.5 + fs * 0.45
    if not searching then
        local la = (1 - k) * kh * kh
        add(D.ev_text(tx, cy, 4, string.format("\\fs%d\\c%s\\1a%s", fs, U.ass_color(hot and "FFFFFF" or THEME.text_muted), U.ass_alpha(100 * la)), "Search"))
        if key ~= "" then
            add(D.ev_text(x + sw - pad, cy, 6, string.format("\\fs%d\\c%s\\1a%s", fs - 3, U.ass_color(THEME.text_muted), U.ass_alpha(70 * la)), U.ass_escape(key)))
        end
    else
        -- the field: the text with its cursor, cut at the pill's end
        local fs2 = fs
        local cw = fs2 * 0.52
        local q, c = HV.q or "", HV.cur_get()
        local maxc = math.max(4, math.floor((x + sw - pad - tx) / cw))
        local first = 0
        while U.utf8_len(q:sub(first + 1, c)) > maxc - 1 do first = HV.cur_next(q, first) end
        local shown = q:sub(first + 1)
        local before, after = q:sub(first + 1, c), q:sub(c + 1)
        if U.utf8_len(shown) > maxc then after = U.utf8_sub(after, math.max(0, maxc - U.utf8_len(before))) end
        HV.box = { x0 = tx - U.utf8_len(q:sub(1, first)) * cw, cw = cw }
        local tcol = U.ass_color(THEME.text_primary)
        local ta = U.ass_alpha(100 * math.min(1, k * 1.5))
        local clip = string.format("\\clip(%d,%d,%d,%d)", math.floor(tx), math.floor(y1), math.floor(x + sw - pad * 0.6), math.floor(y2))
        if q == "" and not HV.typing then
            add(D.ev_text(tx, cy, 4, string.format("\\fs%d\\c%s\\1a%s%s", fs2, U.ass_color(THEME.text_muted), ta, clip), "Search the library"))
        else
            local caret = ""
            if HV.typing then
                caret = HV.XA.on("caret") and HV.XA.caret(THEME.accent, THEME.text_primary, true, ta)
                    or string.format("{\\c%s\\fscx35}▏{\\fscx100\\c%s}", U.ass_color(THEME.accent), tcol)
            end
            local ph_txt = (q == "" and HV.typing) and string.format("{\\c%s}  title, genre:anime, year:2010s, type:tv…", U.ass_color(THEME.text_dim)) or ""
            add(D.ev_text(tx, cy, 4, string.format("\\fs%d\\c%s\\1a%s%s", fs2, tcol, ta, clip),
                (first > 0 and "…" or "") .. HV.XA.before(before, 100 * math.min(1, k * 1.5)) .. caret .. U.ass_escape(after) .. ph_txt))
        end
    end
    HV.links[#HV.links + 1] = { x1 = x, x2 = x + sw, y1 = y1, y2 = y2, crumb = 97,
        act = function(mx) if not HV.typing then HV.start_search() end; if HV.q and HV.q ~= "" then HV.cur_click(mx) end end }
    x = x + sw + math.floor(8 * S)
    if fw > 0 then
        local open = HV.chips_open()
        local fhot = HV.link_hover == 96
        local on = nf > 0
        HV.gpill(add, x, y1, x + fw, y2, m, open and "FFFFFF" or (on and THEME.accent or nil), open and 13 or (on and 22 or nil), fhot)
        local fc = (open or fhot or on) and "FFFFFF" or THEME.text_muted
        add(HV.glyph_funnel(x + pad + ph * 0.25, cy, ph * 0.46, fc, 100))
        add(D.ev_text(x + pad + ph * 0.5 + fs * 0.45, cy, 4, string.format("\\b1\\fs%d\\c%s", fs, U.ass_color(fc)), "Filters"))
        if on then
            local bx2 = x + fw - pad * 0.7
            local bw = HV.AX.tw(tostring(nf), fs - 2, true) + fs * 0.9
            add(D.ev_rect(bx2 - bw, cy - fs * 0.6, bx2, cy + fs * 0.6, THEME.accent, 100, nil, 0, 0, fs * 0.6))
            add(D.ev_text(bx2 - bw / 2, cy, 5, string.format("\\b1\\fs%d\\c%s", fs - 2, "FFFFFF"), tostring(nf)))
        end
        HV.links[#HV.links + 1] = { x1 = x, x2 = x + fw, y1 = y1, y2 = y2, crumb = 96, act = function()
            MS.hints = MS.hints or {}
            MS.hints.chips_open = not HV.chips_open()
            if save_persistence then save_persistence() end
            HV.sig, HV.last_data = nil, nil
            render()
        end }
        x = x + fw + math.floor(8 * S)
    end
    return x
end
-- a small house, drawn (font glyphs for it differ between systems), centred on cx, cy, size s
function HV.house(cx, cy, s, rgb, op)
    local w2, top, eave, base = s * 0.5, cy - s * 0.52, cy - s * 0.08, cy + s * 0.46
    local bw = s * 0.36
    local path = string.format("m %s %s l %s %s l %s %s l %s %s l %s %s l %s %s l %s %s",
        D.fp(cx), D.fp(top), D.fp(cx + w2), D.fp(eave), D.fp(cx + bw), D.fp(eave), D.fp(cx + bw), D.fp(base),
        D.fp(cx - bw), D.fp(base), D.fp(cx - bw), D.fp(eave), D.fp(cx - w2), D.fp(eave))
    return D.ev_shape(path, rgb, op or 100)
end
-- The top row: Home and the breadcrumbs as pills (each clickable), notices in the middle, and on the right the status
-- pill - it opens the setup check (F1) - and the close button.
function HV.glass_top(add, m, any_fail)
    local w, lfs = m.w, m.lfs
    local y1, ph = m.gm, m.gph
    local y2, cy = y1 + ph, y1 + ph / 2
    local fs = math.max(12, lfs - 1)
    local pad = math.floor(ph * 0.55)
    -- right side first (the crumbs get what is left)
    local bcx = w - m.mx - ph / 2
    HV.close_rect = { x1 = bcx - ph / 2 - 4, x2 = bcx + ph / 2 + 4, y1 = y1 - 4, y2 = y2 + 4 }
    HV.gpill(add, bcx - ph / 2, y1, bcx + ph / 2, y2, m, HV.close_hover and THEME.bad or nil, HV.close_hover and 80 or nil, false)
    add(D.ev_shape(D.cross_path(bcx, cy, ph * 0.19, math.max(1, ph * 0.045)), HV.close_hover and "FFFFFF" or THEME.text_muted, 100))
    local st, stc
    if any_fail then st, stc = "Offline  ·  " .. U.kname("refresh"), THEME.bad
    elseif is_loading then st, stc = "Loading…", THEME.warn
    else st, stc = "Online", THEME.good end
    local dk = U.kname("doctor")
    local key_txt = (dk ~= "" and not any_fail) and dk or nil
    local dot = math.max(3, math.floor(fs * 0.2 + 0.5))
    local tw = HV.AX.tw(st, fs)
    local kw = key_txt and (HV.AX.tw(key_txt, fs - 3) + fs * 0.9) or 0
    local sx2 = bcx - ph / 2 - math.floor(10 * m.S)
    local sx1 = sx2 - (pad + dot * 2 + fs * 0.5 + tw + kw + pad * 0.8)
    local shot = HV.link_hover == 99
    HV.gpill(add, sx1, y1, sx2, y2, m, any_fail and THEME.bad or nil, any_fail and 16 or nil, shot)
    local dcx = sx1 + pad * 0.85
    add(D.ev_rect(dcx - dot, cy - dot, dcx + dot, cy + dot, stc, 100, nil, 0, 0, dot))
    if not any_fail then HV.FX.pulse = { dcx, cy, dot, stc, is_loading and 1.1 or 2.4 } end      -- it breathes (HV.fx_draw)
    add(D.ev_text(dcx + dot + fs * 0.5, cy, 4, string.format("\\fs%d\\c%s", fs, U.ass_color(any_fail and THEME.bad or THEME.text_primary)), U.ass_escape(is_loading and st or HV.XA.decode("online", st, 0.45))))
    if key_txt then
        add(D.ev_text(sx2 - pad * 0.8, cy, 6, string.format("\\fs%d\\c%s\\1a%s", fs - 3, U.ass_color(THEME.text_muted), U.ass_alpha(80)), U.ass_escape(key_txt)))
    end
    HV.links[#HV.links + 1] = { x1 = sx1, x2 = sx2, y1 = y1, y2 = y2, crumb = 99,
        act = function() if any_fail then HV.refresh() else HV.DR.show() end end }
    sx1 = HV.TK.pill(add, m, sx1 - math.floor(10 * m.S), y1, y2, fs, pad)          -- Tracked, beside Online
    -- left: Home + crumbs
    local crumbs = {}
    if HV.q and m.title then crumbs[#crumbs + 1] = { t = "Search “" .. HV.q .. "”", act = TV.back } end
    if m.title and TV.card then
        crumbs[#crumbs + 1] = { t = TV.card.shown or TV.card.title, act = (TV.season and TV.multi) and TV.leave_season or nil }
        if TV.season and TV.multi then crumbs[#crumbs + 1] = { t = (TV.season > 0) and ("Season " .. TV.season) or "Other files" } end
    end
    local x = m.mx
    local home_on = not m.title and not HV.q
    local hw = pad + ph * 0.5 + fs * 0.45 + HV.AX.tw("Home", fs, true) + pad
    local hhot = HV.link_hover == 1
    HV.gpill(add, x, y1, x + hw, y2, m, home_on and "FFFFFF" or nil, home_on and 13 or nil, hhot)     -- the toast look: no accent
    add(HV.house(x + pad + ph * 0.25, cy, ph * 0.46, home_on and "FFFFFF" or (hhot and "FFFFFF" or THEME.text_muted), 100))
    add(D.ev_text(x + pad + ph * 0.5 + fs * 0.45, cy, 4, string.format("\\b1\\fs%d\\c%s", fs, U.ass_color((home_on or hhot) and "FFFFFF" or THEME.text_muted)), "Home"))
    HV.links[#HV.links + 1] = { x1 = x, x2 = x + hw, y1 = y1, y2 = y2, act = HV.go_home, crumb = 1 }
    x = x + hw + math.floor(8 * m.S)
    if not m.title then x = HV.search_pills(add, m, x, y1, ph, fs, pad, sx1 - math.floor(16 * m.S)) end
    local limit = sx1 - math.floor(16 * m.S)
    for i, cr in ipairs(crumbs) do
        local last = (i == #crumbs)
        local room = limit - x - 2 * pad
        if room < fs * 3 then break end
        local txt = HV.fitw(cr.t, room, fs, true)
        local cw = HV.AX.tw(txt, fs, true) + 2 * pad
        local hot = HV.link_hover == i + 1 and cr.act
        HV.gpill(add, x, y1, x + cw, y2, m, last and "FFFFFF" or nil, last and 13 or nil, hot)
        add(D.ev_text(x + pad, cy, 4, string.format("\\b1\\fs%d\\c%s", fs, U.ass_color((last or hot) and "FFFFFF" or THEME.text_muted)), U.ass_escape(txt)))
        if cr.act then HV.links[#HV.links + 1] = { x1 = x, x2 = x + cw, y1 = y1, y2 = y2, act = cr.act, crumb = i + 1 } end
        x = x + cw + math.floor(8 * m.S)
    end
    HV.top_free = { x, sx1 - math.floor(16 * m.S) }        -- what is left of the row: the toasts go there
    -- a notice in the middle (links still loading, a service problem, a status line), when there is room for it
    local note, ncol
    if m.title and TV.loading_links and (TV.count or 0) > 0 then         -- (an empty page's card says it already)
        if PS.rd_on() and (TV.rd_want or 0) > 0 then note = string.format("Loading links  ·  %d / %d", TV.rd_have or 0, TV.rd_want)
        else note = "Real-Debrid is still adding files  ·  " .. tostring(TV.count or 0) .. " so far" end
        ncol = THEME.warn
    elseif PS.notice_text() then note, ncol = "⚠  " .. PS.notice_text(), THEME.warn
    elseif HV.status_visible() then
        note = status_line
        ncol = (status_line:match("^Failed") or status_line:match("^Couldn't")) and THEME.bad or THEME.text_muted
    end
    if note then
        local room = (sx1 - math.floor(16 * m.S)) - (x + math.floor(8 * m.S)) - 2 * pad
        if room > fs * 6 then
            local txt = HV.fitw(note, room, fs - 1)
            local nw = HV.AX.tw(txt, fs - 1) + 2 * pad
            local nx = math.max(x + math.floor(8 * m.S), math.floor((w - nw) / 2))
            if nx + nw > sx1 - 16 * m.S then nx = sx1 - 16 * m.S - nw end
            HV.gpill(add, nx, y1, nx + nw, y2, m, ncol ~= THEME.text_muted and ncol or nil, ncol ~= THEME.text_muted and 12 or nil, false)
            add(D.ev_text(nx + pad, cy, 4, string.format("\\fs%d\\c%s", fs - 1, U.ass_color(ncol)), U.ass_escape(HV.XA.decode("note", txt, 0.5))))
        end
    end
end
-- As many whole "Key Action" items as fit in room (never one cut in half), and their measured width (keys bold)
function HV.keys_fit(hint, room, fs)
    local items = {}
    for item in (tostring(hint or "") .. "   "):gmatch("(.-)   +") do if item ~= "" then items[#items + 1] = item end end
    local sep = HV.AX.tw("   ", fs)
    local out, wsum = {}, 0
    for i, item in ipairs(items) do
        local k, rest = item:match("^(%S+)%s*(.*)$")
        local iw = HV.AX.tw(k or item, fs, true) + ((rest and rest ~= "") and HV.AX.tw(" " .. rest, fs) or 0)
        local add_w = iw + (i > 1 and sep or 0)
        if wsum + add_w > room then break end
        out[#out + 1] = item
        wsum = wsum + add_w
    end
    if #out == 0 and items[1] then out[1] = HV.fitw(items[1], room, fs); wsum = HV.AX.tw(out[1], fs, true) end
    return table.concat(out, "   "), wsum
end
-- the keys alone, in the thin bottom pill (the add screen)
function HV.glass_keys(add, m, hint, link, hot)
    local w, h, lfs = m.w, m.h, m.lfs
    local ph = m.gph
    local y1 = h - math.floor(m.gm * 0.9) - ph
    local fs = math.max(11, lfs - 3)
    local pad = math.floor(ph * 0.55)
    local txt, tw = HV.keys_fit(hint, w - 2 * m.mx - 2 * pad, fs)
    local kw = tw + 2 * pad
    HV.gpill(add, m.mx, y1, m.mx + kw, y1 + ph, m)
    if HV.MU_on() and link then HV.hint_items(add, m, m.mx + pad, y1, y1 + ph, txt, fs, link, hot)
    else add(D.ev_text(m.mx + pad, y1 + ph / 2, 4, string.format("\\fs%d", fs), HV.keycaps(txt))) end
end
-- a floating glass card (dark tint, hairline edge, soft shadow) - the details panel of the add screen
function HV.gcard(add, x1, y1, x2, y2, m)
    local r = math.max(8, math.floor(14 * m.S + 0.5))
    local b = math.max(6, math.floor(12 * m.S + 0.5))
    add(string.format("{\\an7\\pos(0,0)\\bord0\\shad0\\blur%d\\1c&H000000&\\1a%s\\3a&HFF&\\p1}%s{\\p0}",
        b, U.ass_alpha(40), D.rounded_path(x1, y1 + b * 0.35, x2, y2 + b * 0.6, r)))
    add(D.ev_rect(x1, y1, x2, y2, THEME.bg_header, 84, "FFFFFF", 14, math.max(1, math.floor(m.S + 0.5)), r))
end
-- "Enter Play   S Sort" -> the key bright and bold, what it does muted (items are three spaces apart)
function HV.keycaps(txt)
    local out = {}
    local muted, white = U.ass_color(THEME.text_muted), U.ass_color("FFFFFF")
    for item in (txt .. "   "):gmatch("(.-)   +") do
        if item ~= "" then
            local k, rest = item:match("^(%S+)%s*(.*)$")
            out[#out + 1] = string.format("{\\b1\\c%s}%s{\\b0\\c%s}%s", white, U.ass_escape(k or item), muted,
                (rest and rest ~= "") and (" " .. U.ass_escape(rest)) or "")
        end
    end
    return table.concat(out, "   ")
end
-- The bottom row: the keys in a thin pill on the left, the cache on the right, the TMDB line underneath.
function HV.glass_bottom(add, m, hint, ctext, attr, warn_cache)
    local w, h, lfs = m.w, m.h, m.lfs
    local ph = m.gph
    local y1 = h - math.floor(m.gm * 0.5) - m.gattr - math.floor(m.gm * 0.4) - ph
    local y2, cy = y1 + ph, y1 + ph / 2
    local fs = math.max(11, lfs - 3)
    local pad = math.floor(ph * 0.55)
    local cwid = HV.AX.tw((ctext:gsub("%d", "0")), fs) + 2 * pad
    local cx2 = w - m.mx
    HV.gpill(add, cx2 - cwid, y1, cx2, y2, m, warn_cache and THEME.warn or nil, warn_cache and 14 or nil, false)
    add(D.ev_text(cx2 - pad, cy, 6, string.format("\\fs%d\\c%s", fs, U.ass_color(warn_cache and THEME.warn or THEME.text_muted)), U.ass_escape(ctext)))
    local left = cx2 - cwid
    -- ↓ beside the cache pill: the downloads (drawn on the animation layer, HV.DLP)
    if HV.DLP.visible() then left = HV.DLP.place(m, left - math.floor(8 * m.S), y1, y2, fs, pad) end
    local room = (left - math.floor(12 * m.S)) - m.mx - 2 * pad
    local txt, tw = HV.keys_fit(hint, room, fs)
    local kw = tw + 2 * pad
    HV.gpill(add, m.mx, y1, m.mx + kw, y2, m)
    if HV.MU_on() then
        HV.hint_items(add, m, m.mx + pad, y1, y2, txt, fs,
            function(a, b, c, d, id, act) HV.links[#HV.links + 1] = { x1 = a, y1 = b, x2 = c, y2 = d, hov = id, act = act } end,
            function(id) return HV.btn_hover == id end)
    else
        add(D.ev_text(m.mx + pad, cy, 4, string.format("\\fs%d", fs), HV.keycaps(txt)))
    end
    local afs = math.max(9, lfs - 6)
    add(D.ev_text(m.mx + pad, y2 + math.floor(m.gm * 0.4) + m.gattr / 2, 4, string.format("\\fs%d\\c%s", afs, U.ass_color(THEME.text_dim)),
        U.ass_escape(HV.fitw(attr, w - 2 * m.mx - 2 * pad, afs))))
end

-- ---------- drawing ----------
-- The rating is added when the card is DRAWN, not when the rows are built: the rows are built before most TMDB
-- lookups have finished, so a baked-in rating was missing on every card that was matched afterwards. It also outranks
-- the quality chips, which used to push it off narrow cards ("S01 · 1080p" left no room for "★ 7.9").
function HV.with_rating(card)
    local p = card.parts or {}
    if card.kind ~= "folder" then return p end
    local e = PS.enabled() and PS.idx and PS.idx[card.key] or nil
    e = (type(e) == "table" and not e.none) and e or nil
    local sig = tostring(e and e.vote) .. "|" .. tostring(e and e.kind) .. "|" .. tostring(e and e.gen and #e.gen) .. "|" .. tostring(e and e.year)
    if card._rs == sig and card._rp == p then return card._rq end
    local out = {}
    local v = e and tonumber(e.vote) or 0
    if v > 0 then out[#out + 1] = dp(string.format("★ %.1f", v), THEME.star, 10) end           -- kept the longest
    local yr = tostring((e and e.year ~= "" and e.year) or card.year or "")
    if yr ~= "" then out[#out + 1] = dp(yr, THEME.text_muted, 8) end
    local kind = HV.kind_label(card, e)
    if kind then out[#out + 1] = dp(kind, THEME.text_muted, 9) end
    if o.new_badges and e and HV.TK.on() then
        local tke = HV.TK.all()[HV.TK.key(e.kind, e.id)]
        local nx = tke and HV.TK.next_short(tke)
        if nx then out[#out + 1] = dp((nx:gsub("^Next ", ""):gsub(" · ", " ")), THEME.good, 9.5) end
    end
    for _, x in ipairs(p) do out[#out + 1] = x end          -- seasons / versions, quality, group
    card._rs, card._rp, card._rq = sig, p, out
    return out
end
-- "Series", "Movie" or "Anime" (Japanese animation) - from TMDB when matched, else from the folder names
function HV.kind_label(card, e)
    local f = HV.card_facts(card)
    local anime = false
    for _, g in ipairs(f.gen) do if g == "animation" and (f.lang == "ja" or f.lang == nil) then anime = true end end
    if not f.known and f.anime_hint then anime = true end
    if anime then return "Anime" end
    if f.kind == "tv" then return "Series" elseif f.kind == "movie" then return "Movie" end
    return nil
end
-- Soft shadow under a card (libass blur; drawn first, the card's bitmap covers the middle).
function HV.shadow(x1, y1, x2, y2, b, opacity)
    return string.format("{\\an7\\pos(0,0)\\bord0\\shad0\\blur%d\\1c&H000000&\\1a%s\\3a&HFF&\\p1}%s{\\p0}",
        b, U.ass_alpha(opacity), D.rounded_path(x1, y1, x2, y2, (HV.R or 0) + b / 2))
end

-- Couch mode: on with couch_mode=yes, or (auto) after a gamepad / remote key until the mouse moves again.
function HV.couch_on()
    local c = tostring(o.couch_mode or "auto"):lower()
    if c == "yes" or c == "true" then return true end
    if c == "no" or c == "false" then return false end
    return HV.pad_used == true
end
function HV.ring_pad(m) return HV.couch and math.max(6, math.floor(6 * m.S + 0.5)) or 4 end
-- Focus ring around a card; in couch mode thicker and with a glow, readable from across the room.
-- the accent outline: focus_ring=yes, or always when nothing else shows the selection (focus_style=ring, mpv < 0.38
-- without the dimming) and in couch mode (read from across the room)
function HV.ring_on()
    return o.focus_ring or HV.couch or not HV.LY.dim_on()
end
function HV.ring(x1, y1, x2, y2, sel, m, fine)
    local r = (HV.R or 0) + HV.ring_pad(m)
    local col = sel and THEME.accent or THEME.text_dim
    if HV.couch and sel then
        local bw = math.max(4, math.floor(3.5 * m.S + 0.5))
        local glow = string.format("{\\an7\\pos(0,0)\\bord%d\\shad0\\blur%d\\1a&HFF&\\3c%s\\3a%s\\p1}%s{\\p0}",
            bw * 2, bw * 2, U.ass_color(col), U.ass_alpha(45), D.rounded_path(x1, y1, x2, y2, r, fine))
        return glow .. "\n" .. D.ev_rect(x1, y1, x2, y2, "FFFFFF", 0, "FFFFFF", 100, bw, r, fine)
    end
    return D.ev_rect(x1, y1, x2, y2, "FFFFFF", 0, col, 100, sel and 3 or 2, r, fine)
end

function HV.wrap2(text, maxw, fs)
    local words = {}
    for wd in tostring(text):gmatch("%S+") do words[#words + 1] = wd end
    local function width(s) return U.utf8_len(s) * fs * 0.62 end
    local l1, i = "", 1
    while i <= #words do
        local try = (l1 == "") and words[i] or (l1 .. " " .. words[i])
        if l1 == "" or width(try) <= maxw then l1 = try; i = i + 1 else break end
    end
    local l2 = (i <= #words) and table.concat(words, " ", i) or ""
    return U.fit_text(l1, maxw, fs), (l2 ~= "" and U.fit_text(l2, maxw, fs) or "")
end

-- Coloured detail line from {t, c, p} parts; the lowest-priority parts are dropped until it fits.
function HV.detail_ass(parts, maxw, fs, default_col)
    local list = {}
    for i, p in ipairs(parts or {}) do list[i] = p end
    local function width()            -- measured like the rest of the UI (a per-letter guess dropped parts that fit)
        local t = {}
        for i, p in ipairs(list) do t[i] = p.t end
        return HV.AX.tw(table.concat(t, " · "), fs)
    end
    while #list > 1 and width() > maxw do
        local lo, idx = 99, #list
        for i = #list, 1, -1 do if list[i].p < lo then lo, idx = list[i].p, i end end
        table.remove(list, idx)
    end
    local out = {}
    for i, p in ipairs(list) do
        if i > 1 then out[#out + 1] = string.format("{\\c%s} · ", U.ass_color(THEME.text_dim)) end
        out[#out + 1] = string.format("{\\c%s}%s", U.ass_color(p.c or default_col or THEME.text_muted), U.ass_escape(p.t))
    end
    return table.concat(out)
end


function HV.sec_of(row, m)
    if not row.title then return 0 end
    return m.sec_h + (row.note and math.floor(m.lfs * 1.5) or 0)
end

-- Title pages: when the first row on screen is not the first of its section, that section's heading stays pinned
-- above the rows (so "Season 4  ·  8 episodes" never scrolls out of sight).
function HV.pin_row(m)
    if not m.title then return nil end
    local top = HV.rows[HV.top]
    if not top or top.title then return nil end
    for ri = HV.top - 1, 1, -1 do
        if HV.rows[ri].title then return HV.rows[ri] end
    end
    return nil
end
function HV.pin_h(m) return HV.pin_row(m) and m.sec_h or 0 end

function HV.row_air(m) return math.floor(m.lfs * 1.1) end

function HV.ensure_visible(m)
    HV.clamp()
    local guard = 0
    while guard < 500 do
        guard = guard + 1
        HV.top = hv_clamp(HV.top, 1, math.max(1, #HV.rows))
        if HV.r < HV.top then HV.top = HV.r
        else
            local last = HV.top
            local y = HV.rows_y(m) + HV.pin_h(m)
            for ri = HV.top, #HV.rows do
                local need = HV.rowdim(HV.rows[ri], m).block_h + HV.sec_of(HV.rows[ri], m)
                -- a row is on screen when its picture, bar and labels are; the air under it may go under the footer
                if y + need - HV.row_air(m) > m.h - m.foot_h and ri > HV.top then break end
                last = ri
                y = y + need
            end
            if last < HV.r and HV.top < HV.r then HV.top = HV.top + 1 else break end
        end
    end
end

-- the rows' glide (smooth_scroll): pixels the page is still away from where it now belongs, easing to 0
HV.SCROLL_DUR = 0.24
function HV.scroll_offset(m)
    local A = HV.A
    local now = U.now_s()
    local key = HV.mode .. "|" .. tostring(TV.card) .. "|" .. tostring(TV.season) .. "|" .. tostring(HV.q) .. "|" .. tostring(m.w) .. "x" .. tostring(m.h)
    if not o.smooth_scroll or not HV.motion_ok() or MS.debug or A.top_key ~= key or not A.top_prev then
        A.top_prev, A.top_key, A.sc, HV.cur_scroll = HV.top, key, nil, 0
        return 0
    end
    if A.top_prev ~= HV.top then
        local a, b = math.min(A.top_prev, HV.top), math.max(A.top_prev, HV.top)
        local dist = 0
        for ri = a, b - 1 do
            local r = HV.rows[ri]
            if r then dist = dist + HV.rowdim(r, m).block_h + HV.sec_of(r, m) end
        end
        -- a long jump (Home / End, several pages) does not glide the whole way: at most about one screen
        dist = math.min(dist, m.h * 0.8)
        A.sc = { from = (HV.cur_scroll or 0) + ((HV.top > A.top_prev) and dist or -dist), t0 = now }
        A.top_prev = HV.top
        HV.anim_kick(HV.SCROLL_DUR + 0.05)
    end
    local sc = A.sc
    if not sc then HV.cur_scroll = 0; return 0 end
    local k = (now - sc.t0) / HV.SCROLL_DUR
    if k >= 1 then A.sc, HV.cur_scroll = nil, 0; return 0 end
    HV.cur_scroll = sc.from * (1 - HV.ease(k))
    return math.floor(HV.cur_scroll + 0.5)
end
function HV.scrolling() return HV.A.sc ~= nil end

HV.render = function()
    if HV.XA.exit and HV.XA.exit_k() <= 0 then return HV.XA.exit_end() end
    HV.LY.frame()
    HV.hab = nil
    HV.FX.shim, HV.FX.ring, HV.FX.enter, HV.FX.pulse = {}, nil, nil, nil
    HV.lyc = {}
    if HV.mode == "add" then
        if HV.DLC and HV.DLC.kind == "pop" then HV.DLC = nil end         -- the file picker belongs to a library title page
        -- a bug on the add screen must not leave a half-drawn page behind (it used to need an mpv restart)
        local ok, err = pcall(HV.AX.render)
        HV.fx_draw()                    -- after the page: its loading posters are in HV.FX.shim now
        if not ok and not HV.AX.failing then
            HV.AX.failing = true
            msg.error("add screen: " .. tostring(err))
            HV.AX.close()
            HV.TS.show({ eyebrow = "ADD SCREEN", title = "That page hit a bug - back to the library", extra = tostring(err):gsub("^.-:%d+: ", ""):sub(1, 100) }, 8)
            HV.AX.failing = nil
        end
        return
    end
    HV.SC.hide("ax")
    local m = HV.metrics()
    HV.m = m
    local root = find_cached_dir(root_href)
    local sig = table.concat({ HV.mode, tostring(root and root.entries), tostring(get_continue_list()), m.per, tostring(o.continue_row),
        tostring(o.merge_seasons), HV.sort_mode(), PS.eps_ver, MS.cache_version, TV.card and TV.card.key or "", m.cw, HV.hf_get(),
        (o.merge_by_tmdb or HV.q) and PS.idx_ver or 0, PS.RD.ver, tostring(TV.season), HV.qa or HV.q or "" }, "|")
    if sig ~= HV.sig then
        local offs = {}
        for _, r in ipairs(HV.rows or {}) do if r.shelf and r.title then offs[r.title] = r.off end end
        HV.sig = sig; HV.rows = HV.build(m)
        if HV.jump_res then
            HV.jump_res = nil
            for ri, r in ipairs(HV.rows) do if r.res then HV.r, HV.c = ri, 1; break end end
        end
        HV.clamp()
        -- a shelf you scrolled sideways (Continue Watching) stays where it was when the rows are built again
        for _, r in ipairs(HV.rows) do
            if r.shelf and r.title and offs[r.title] then r.off = hv_clamp(offs[r.title], 0, math.max(0, #r.cards - HV.rowdim(r, m).per)) end
        end
        if TV.relayout then          -- the title page switched between season folders and episodes: new card shape
            TV.relayout = nil
            HV.sig = nil
            return HV.render()
        end
        if HV.reselect then
            for ri, row in ipairs(HV.rows) do
                for ci, cd in ipairs(row.cards) do
                    if cd.key == HV.reselect then HV.r, HV.c = ri, ci; HV.top = math.max(1, ri - 1) end
                end
            end
            HV.reselect = nil
            HV.fix_off(m); HV.want_vc = HV.vcol()
        end
    end
    overlay.res_x, overlay.res_y = m.w, m.h
    if not HV.pruned and not HV.prune_t then
        -- old window sizes' pictures are cleared out a moment after the page is up, not inside its first frame
        HV.prune_t = mp.add_timeout(2.5, function() HV.prune_t = nil; if browser_active then HV.prune_bgra() end end)
    end
    HV.fix_off(m)
    if HV.click_sel then
        HV.click_sel = nil              -- clicked a card you can see: it is selected where it is, nothing scrolls
    else
        HV.ensure_visible(m)
        HV.ensure_visible(m)       -- once more: the hero band appears / disappears as the top row changes
    end

    local w, h, lfs = m.w, m.h, m.lfs
    local chunks = {}
    local function add(c) chunks[#chunks + 1] = c end
    add(D.ev_rect(0, 0, w, h, THEME.bg_dim, HV.bg_alpha(), nil, 0, 0))
    HV.XV.glass_bg(m)

    HV.links = {}
    local any_fail = listing_error[root_href]
    if m.glass then
        HV.glass_top(add, m, any_fail)
    else
        -- top bar
        add(D.ev_rect(0, 0, w, m.top_h, THEME.bg_header, 100, nil, 0, 0))
        add(D.ev_rect(0, m.top_h - 2, w, m.top_h, THEME.grad_top, 30, nil, 0, 0))
        -- breadcrumbs: WebDAV Library › Title › Season N   (each part is clickable; the mouse back button goes up one)
        do
            local crumbs = { { t = "WebDAV Library", act = HV.go_home } }
            if HV.q and m.title then crumbs[#crumbs + 1] = { t = "Search “" .. HV.q .. "”", act = TV.back } end
            if m.title and TV.card then
                crumbs[#crumbs + 1] = { t = TV.card.shown or TV.card.title, act = (TV.season and TV.multi) and TV.leave_season or nil }
                if TV.season and TV.multi then crumbs[#crumbs + 1] = { t = (TV.season > 0) and ("Season " .. TV.season) or "Other files" } end
            end
            local cfs = math.floor((lfs + 8) * (0.5 + 0.5 * math.max(0.3, math.min(1.4, tonumber(o.top_bar_scale) or 0.8))))
            cfs = math.max(10, math.min(cfs, math.floor(m.top_h * 0.62)))
            local x = m.mx
            -- the right-hand pills (Tracked, Connected, close) are drawn after the crumbs: their width, estimated here
            local sfs_ = math.max(9, math.min(lfs - 2, math.floor(m.top_h * 0.4)))
            local rightw = HV.AX.tw("Connected", sfs_) + sfs_ * 4 + math.floor(28 * m.S) + math.floor(m.top_h * 0.86) * 1.5
            if HV.TK.on() then rightw = rightw + HV.AX.tw("Tracked 99", sfs_, true) + sfs_ * 3 end
            local limit = (HV.q and not m.title) and (w * 0.26 - 12) or math.min(w * 0.62, w - rightw - lfs)
            HV.top_free = { m.mx, w - rightw }
            for i, cr in ipairs(crumbs) do
                local last = (i == #crumbs)
                local txt = U.fit_text(cr.t, math.max(60, limit - x), cfs)
                local tw = HV.AX.tw(txt, cfs, true)            -- measured by libass, so the click area matches the text
                local hot = HV.link_hover and HV.link_hover == i and cr.act
                local col = last and THEME.accent or (hot and "FFFFFF" or THEME.text_muted)
                add(D.ev_text(x, m.top_h / 2, 4, string.format("\\b1\\fs%d\\c%s", cfs, U.ass_color(col)), U.ass_escape(txt)))
                if cr.act then HV.links[#HV.links + 1] = { x1 = x - 4, x2 = x + tw + 4, y1 = 0, y2 = m.top_h, act = cr.act, crumb = i } end
                x = x + tw + cfs * 0.45
                if not last then
                    add(D.ev_text(x, m.top_h / 2, 4, string.format("\\fs%d\\c%s", cfs, U.ass_color(THEME.text_dim)), "›"))
                    x = x + cfs * 0.9
                end
                if x > limit then break end
                HV.top_free[1] = x
            end
        end
        -- right: the connection as a small pill, then the close button as a round button of its own
        -- both in the toast look: faint glass, a hairline edge; the pill and the button share one height
        local sfs = math.max(9, math.min(lfs - 2, math.floor(m.top_h * 0.4)))
        local ph = math.min(math.floor(sfs * 1.9 + 0.5), math.floor(m.top_h * 0.86))
        local bcx, bcy = w - math.floor(28 * m.S) - ph / 2, math.floor(m.top_h / 2)
        HV.close_rect = { x1 = bcx - ph / 2 - 4, x2 = bcx + ph / 2 + 4, y1 = 0, y2 = m.top_h }
        add(D.ev_pill(bcx - ph / 2, bcy - ph / 2, bcx + ph / 2, bcy + ph / 2, ph / 2, m.S,
            HV.close_hover and THEME.bad or "FFFFFF", HV.close_hover and 80 or 6, HV.close_hover and 0 or 17))
        add(D.ev_shape(D.cross_path(bcx, bcy, ph * 0.2, math.max(1, ph * 0.045)), HV.close_hover and "FFFFFF" or THEME.text_muted, 100))
        local st_txt = (any_fail and ("Offline  ·  " .. U.kname("refresh") .. " to retry")) or (is_loading and "Loading…") or "Connected"
        local sx2 = bcx - ph / 2 - math.floor(12 * m.S)
        local dot = math.max(3, math.floor(sfs * 0.2 + 0.5))
        local sx1 = sx2 - HV.AX.tw(st_txt, sfs) - ph * 0.5 - dot * 2 - sfs * 0.5 - ph * 0.45
        add(D.ev_pill(sx1, bcy - ph / 2, sx2, bcy + ph / 2, ph / 2, m.S, any_fail and THEME.bad or "FFFFFF", any_fail and 14 or 6))
        local dcx = sx1 + ph * 0.5
        add(D.ev_rect(dcx - dot, bcy - dot, dcx + dot, bcy + dot, any_fail and THEME.bad or (is_loading and THEME.warn or THEME.good), 100, nil, 0, 0, dot))
        if not any_fail then HV.FX.pulse = { dcx, bcy, dot, is_loading and THEME.warn or THEME.good, is_loading and 1.1 or 2.4 } end
        add(D.ev_text(dcx + dot + sfs * 0.5, bcy, 4, string.format("\\fs%d\\c%s", sfs, U.ass_color(any_fail and THEME.bad or THEME.text_primary)), U.ass_escape(st_txt)))
        if any_fail then HV.links[#HV.links + 1] = { x1 = sx1, x2 = sx2, y1 = 0, y2 = m.top_h, act = function() HV.refresh() end } end
        HV.TK.pill(add, m, sx1 - math.floor(10 * m.S), bcy - ph / 2, bcy + ph / 2, sfs, math.floor(ph * 0.5))
        if HV.q and not m.title then
            local bx1, bx2 = math.floor(w * 0.26), math.floor(w * 0.70)
            HV.links[#HV.links + 1] = { x1 = bx1, x2 = bx2, y1 = 0, y2 = m.top_h,
                act = function(mx) if not HV.typing then HV.start_search() end; HV.cur_click(mx) end }
            add(D.ev_rect(bx1, m.top_h * 0.16, bx2, m.top_h * 0.84, THEME.bg_panel, 100, THEME.accent, HV.typing and 100 or 35, 1, 8))
            -- the text with a cursor where you are editing; a long query scrolls so the cursor stays in view
            local fs2 = math.max(10, math.min(lfs + 2, math.floor(m.top_h * 0.5)))
            local cw = fs2 * 0.52
            local label = "Search:  "
            local q, c = HV.q or "", HV.cur_get()
            local maxc = math.max(4, math.floor((bx2 - bx1 - 40) / cw) - U.utf8_len(label))
            local first = 0                                     -- bytes hidden on the left
            while U.utf8_len(q:sub(first + 1, c)) > maxc - 1 do first = HV.cur_next(q, first) end
            local shown = q:sub(first + 1)
            local before, after = q:sub(first + 1, c), q:sub(c + 1)
            if U.utf8_len(shown) > maxc then after = U.utf8_sub(after, math.max(0, maxc - U.utf8_len(before))) end
            HV.box = { x0 = bx1 + 14 + U.utf8_len(label) * cw - U.utf8_len(q:sub(1, first)) * cw, cw = cw }
            local tcol = U.ass_color(THEME.text_primary)
            local caret = ""
            if HV.typing then
                caret = HV.XA.on("caret") and HV.XA.caret(THEME.accent, THEME.text_primary, true)
                    or string.format("{\\c%s\\fscx35}▏{\\fscx100\\c%s}", U.ass_color(THEME.accent), tcol)
            end
            add(D.ev_text(bx1 + 14, m.top_h / 2, 4, string.format("\\fs%d\\c%s", fs2, tcol),
                U.ass_escape(label .. (first > 0 and "…" or "")) .. HV.XA.before(before) .. caret .. U.ass_escape(after)))
        elseif m.title and TV.loading_links and (TV.count or 0) > 0 then
            local txt
            if PS.rd_on() and (TV.rd_want or 0) > 0 then
                txt = string.format("Loading links from Real-Debrid  ·  %d / %d", TV.rd_have or 0, TV.rd_want)
                local frac = math.min(1, (TV.rd_have or 0) / math.max(1, TV.rd_want))
                add(D.ev_rect(0, m.top_h - 3, w, m.top_h, THEME.track, 100, nil, 0, 0))
                add(D.ev_rect(0, m.top_h - 3, w * frac, m.top_h, THEME.accent, 100, nil, 0, 0))
            else
                txt = "Real-Debrid is still adding files to this title…  (" .. tostring(TV.count or 0) .. " so far)"
            end
            add(D.ev_text(w / 2, m.top_h / 2, 5, string.format("\\fs%d\\c%s", lfs, U.ass_color(THEME.warn)), U.ass_escape(U.fit_text(txt, w * 0.4, lfs))))
        elseif PS.notice_text() then
            add(D.ev_text(w / 2, m.top_h / 2, 5, string.format("\\fs%d\\c%s", lfs, U.ass_color(THEME.warn)),
                U.ass_escape(U.fit_text("⚠  " .. PS.notice_text(), w * 0.45, lfs))))
        elseif HV.status_visible() then
            add(D.ev_text(w / 2, m.top_h / 2, 5, string.format("\\fs%d\\c%s", lfs, U.ass_color((status_line:match("^Failed") or status_line:match("^Couldn't")) and THEME.bad or THEME.text_muted)),
                U.ass_escape(U.fit_text(status_line, w * 0.4, lfs))))
        end
    end

    -- filter chips under the search box (and on the home page with home_filter_chips: they filter All Titles)
    if HV.chips_on(m) and HV.chips then
        local ck = HV.chip_k(m)
        local tw_ = HV.TW.chips
        local opening = tw_ and tw_.to == 1
        local x, cy0 = m.mx, m.top_h + 6 + m.chip_h / 2
        local cfs = lfs - 2
        local home_chips = HV.q == nil
        local cur = home_chips and HV.hf_get() or HV.q
        -- experimental_chip_stagger: each chip pops in on its own beat (a little rise, a little overshoot)
        local stag = HV.XA.on("chip_stagger") and opening and HV.anim_on() and tw_ and (tw_.t0 or 0) > 0 and tw_.t0
        if stag and HV.XA.chip_t0 ~= tw_.t0 then
            HV.XA.chip_t0 = tw_.t0
            HV.XA.frames("xa_chips", 0.22 + 0.04 * #HV.chips)
        end
        local function chip_a(i)
            if stag then return HV.XA.clamp((U.now_s() - tw_.t0 - (i - 1) * 0.04) / 0.22, 0, 1) end
            if not opening then return ck end
            return HV.ease(math.max(0, math.min(1, ck * 1.7 - (i - 1) * 0.07)))
        end
        for ci_, ch in ipairs(HV.chips) do
            local tw = HV.AX.tw(ch.label, cfs) + cfs * 1.4
            if x + tw > w - m.mx then break end
            local a = chip_a(ci_)
            local cy = cy0 - (1 - a) * 8 * m.S
            if stag then
                local b_ = 1 + 2.4 * (a - 1) ^ 3 + 1.4 * (a - 1) ^ 2          -- back-out: past the mark, then onto it
                cy = cy0 + (1 - b_) * 14 * m.S
                a = math.min(1, a * 1.8)
            end
            local on = (" " .. cur .. " "):find(" " .. ch.tok .. " ", 1, true) ~= nil
            if m.glass or HV.bg_alpha() < 100 then
                -- the toast look: faint glass with a hairline edge (the accent fills a chip that is on)
                HV.gpill_a(add, x, cy - cfs * 0.95, x + tw, cy + cfs * 0.95, m, on and THEME.accent or nil, on and 85 or nil, false, a)
            else
                add(D.ev_rect(x, cy - cfs * 0.95, x + tw, cy + cfs * 0.95, on and THEME.accent or THEME.bg_panel, (on and 85 or 100) * a,
                    on and THEME.accent or THEME.text_dim, (on and 100 or 45) * a, 1, cfs))
            end
            add(D.ev_text(x + tw / 2, cy, 5, string.format("\\fs%d\\c%s\\1a%s%s", cfs, U.ass_color(on and "FFFFFF" or THEME.text_muted), U.ass_alpha(100 * a), on and "\\b1" or ""), U.ass_escape(ch.label)))
            local tok = ch.tok
            HV.links[#HV.links + 1] = { x1 = x, x2 = x + tw, y1 = cy - cfs, y2 = cy + cfs, act = function() if home_chips then HV.hf_toggle(tok) else HV.toggle_token(tok) end end }
            x = x + tw + cfs * 0.6
        end
        if home_chips and cur ~= "" then
            local lab = "✕ Clear"
            local tw = HV.AX.tw(lab, cfs) + cfs * 1.4
            local cy = cy0
            if x + tw <= w - m.mx then
                add(D.ev_text(x + tw / 2, cy, 5, string.format("\\fs%d\\c%s\\1a%s", cfs, U.ass_color(THEME.text_muted), U.ass_alpha(100 * ck)), lab))
                HV.links[#HV.links + 1] = { x1 = x, x2 = x + tw, y1 = cy - cfs, y2 = cy + cfs, act = function() MS.hints.home_filter = ""; HV.sig = nil; if save_persistence then save_persistence() end; render() end }
            end
        end
    end

    HV.hit, HV.vis_cards, HV.wanted, HV.grow_want = {}, {}, {}, nil
    if m.title and TV.card then
        local hw, hh = TV.hero_size(m)
        HV.wanted[1] = { key = TV.card.key, title = TV.card.title, year = TV.card.year, dw = hw, dh = hh, pri = -1 }
    end
    local vis = {}
    local anim = HV.anim_on()
    local A = HV.A
    local now = U.now_s()
    -- smooth_scroll: when the first row on screen changes, the rows glide there (the page's commands go to mpv as one
    -- burst per frame, so the posters move together); rows passing the top edge are cut there, pictures included
    local scroll = HV.scroll_offset(m) + HV.XA.rb_off("v", nil, m)
    A.top, A.mode, A.card = HV.top, HV.mode, TV.card
    local pin = HV.pin_row(m)
    local top_y = HV.rows_y(m) + (pin and m.sec_h or 0)
    local y = top_y + scroll
    local bottom = h - m.foot_h
    local first = HV.top
    while scroll > 0 and first > 1 and y > top_y do          -- the rows still on their way out at the top
        local pr = HV.rows[first - 1]
        y = y - (HV.rowdim(pr, m).block_h + HV.sec_of(pr, m))
        first = first - 1
    end
    for ri = first, #HV.rows do
        local row = HV.rows[ri]
        local d_ = HV.rowdim(row, m)
        local need = d_.block_h + HV.sec_of(row, m)
        if y + need - HV.row_air(m) > bottom and #vis > 0 then
            -- the next row peeks in at the bottom (its posters cut off at the footer), so scrolling never jumps
            -- into a blank area and you can see what comes next
            local cy = y + HV.sec_of(row, m)
            if cy + math.max(24, d_.ch * 0.08) < bottom and cy >= top_y then
                vis[#vis + 1] = { ri = ri, ty = y, y = cy, cut = bottom }
            end
            break
        end
        local cy = y + HV.sec_of(row, m)
        if cy + d_.ch > top_y + 2 then
            vis[#vis + 1] = { ri = ri, ty = y, y = cy, clip = (y < top_y - 1) and top_y or nil }
        end
        y = y + need
    end
    HV.vis = vis
    -- the title you rest on: its page is prepared in the background
    if not m.title then
        local fr, fc = HV.r, HV.c
        if HV.mouse_mode() then fr, fc = HV.hover and HV.hover.r, HV.hover and HV.hover.c end
        local frow = fr and HV.rows[fr]
        if frow and frow.cards[fc] then HV.prefetch_card(frow.cards[fc]) end
    end

    HV.hero, HV.backdrop, HV.logo = nil, nil, nil
    if m.title and TV.card then TV.draw_hero(add, m) end

    if #HV.rows == 0 and m.title and TV.card then          -- (also a title opened from a search: it said "No titles match")
        TV.draw_empty(add, m)
    elseif #HV.rows == 0 then
        local msg_ = any_fail and ("⚠  " .. tostring(any_fail) .. "     (press R to retry)") or (is_loading and "Loading library…" or "No folders found")
        if HV.q then msg_ = (HV.q == "") and "Type to search the library" or ("No titles match \"" .. HV.q .. "\"" .. (MS.idx_running and "   (the file index is still building)" or "")) end
        if o.empty_states and not any_fail and not is_loading then
            HV.XV.empty(add, m, w / 2, h / 2, "library", msg_, HV.q and "Try another name, or a filter like genre:anime" or "Your WebDAV folders show up here once they have files in them")
        else
            add(D.ev_text(w / 2, h / 2, 5, string.format("\\fs%d\\c%s", lfs + 6, U.ass_color(any_fail and THEME.bad or THEME.text_muted)), U.ass_escape(msg_)))
        end
    end

    if pin then
        add(D.ev_text(m.mx, HV.rows_y(m) + m.sec_h * 0.4, 4, string.format("\\b1\\fs%d\\c%s", lfs + 6, U.ass_color(THEME.text_primary)), U.ass_escape(pin.title)))
    end
    local add_page = add
    for _, v in ipairs(vis) do
        local row = HV.rows[v.ri]
        local d = HV.rowdim(row, m)
        -- a row passing the top edge (smooth scroll): its text and shapes are cut there too
        local add = add_page
        do
            local ctag = string.format("\\clip(0,%d,%d,%d)", math.floor(v.clip or (top_y - 1)), math.floor(w), math.floor(h))
            add = function(e) add_page((tostring(e):gsub("{", "{" .. ctag, 1))) end
        end
        if row.title and not (v.clip and v.ty < v.clip) then
            local hdr_hot = row.sort_hdr and HV.hdr_hover
            add(D.ev_text(m.mx, v.ty + m.sec_h * 0.4, 4, string.format("\\b1\\fs%d\\c%s", lfs + 6, U.ass_color(hdr_hot and THEME.accent or THEME.text_primary)), U.ass_escape(row.title)))
            if row.sort_hdr then
                HV.links[#HV.links + 1] = { x1 = m.mx, x2 = m.mx + HV.AX.tw(row.title, lfs + 6, true), y1 = v.ty, y2 = v.ty + m.sec_h,
                    act = function() HV.toggle_sort() end, hdr = true }
            end
            if row.note then
                add(D.ev_text(m.mx, v.ty + m.sec_h * 0.4 + lfs * 1.45, 4, string.format("\\fs%d\\c%s", lfs, U.ass_color(THEME.warn)),
                    U.ass_escape(U.fit_text(row.note, w - 2 * m.mx, lfs))))
            end
        end
        local off = row.off or 0
        local rbx = HV.XA.rb_off("h", v.ri, m)
        local step = d.cw + m.gap
        local xst = row.shelf and HV.XS.state(HV.mode .. ":" .. tostring(row.title or v.ri)) or nil
        local sx = xst and HV.XS.pos(xst, off * step) or off * step
        local xmov = xst ~= nil and HV.XS.moving(xst)
        if row.shelf then row.xs_geo = { st = xst, step = step, per = d.per, maxs = math.max(0, (#row.cards - d.per) * step), sx = sx } end
        local c1, c2 = off + 1, off + d.per
        if xmov then c1, c2 = math.max(1, math.floor(sx / step)), math.floor(sx / step) + d.per + 2 end
        for ci = c1, c2 do
            local card = row.cards[ci]
            if not card then break end
            local x = m.mx + (ci - 1) * step - sx + rbx
            repeat                                 -- (break = the next card: one off the screen while the row moves)
            if xmov and (x + d.cw < -2 or x > w + 2) then break end
            local py = v.y
            local hov = HV.hover and HV.hover.r == v.ri and HV.hover.c == ci
            local sel
            if HV.mouse_mode() then sel = hov and true or false
            else sel = (v.ri == HV.r and ci == HV.c) and not (HV.bfocus and m.title) end
            local st = HV.items[card.key]
            local ready = st and (st.bgra[d.sk] or HV.alt_bgra(st, d.sk)) and not MS.debug
            if row.land then card.dw, card.dh = d.cw, d.ch end
            -- clip: nothing pictured goes above the content's top line (a grown or scrolled poster over the chips)
            local vc = { card = card, x = x, y = py, w = d.cw, h = d.ch, sk = d.sk, cut = v.cut, clip = v.clip or top_y,
                         uid = card.key .. "|" .. v.ri .. "|" .. ci, ri = v.ri, gw = d.gw, gh = d.gh, foc = sel,
                         par = ((row.land or (HV.mode == "title" and d.cw > d.ch)) and hov and not v.cut and not v.clip) or nil }   -- (CW, the episode stills)
            HV.vis_cards[#HV.vis_cards + 1] = vc
            HV.wanted[#HV.wanted + 1] = card
            HV.hit[#HV.hit + 1] = { x1 = x, y1 = math.max(py, v.clip or py), x2 = x + d.cw, y2 = math.min(v.cut or 1e9, py + d.ch + m.bar_h + m.label_h), r = v.ri, c = ci }
            -- the selected card grows a little (its own, bigger bitmap - only for this one card)
            local gx1, gy1, gx2, gy2 = x, py, x + d.cw, py + d.ch
            local lift = sel and HV.settled() and not xmov
            if hov and HV.MU_on() and o.hover_buttons ~= false and HV.mouse_mode() and not v.cut and py >= top_y
                and not HV.scrolling() and not xmov and U.now_s() - (HV.hover_t or 0) >= 0.28 then vc.acts = true end
            if lift and d.gw and ready and not v.cut then
                if sel then HV.grow_want = { card = card, w = d.gw, h = d.gh } end
                if st.bgra[d.gsk] or HV.dw_ok() then        -- mpv 0.38+: the normal picture, scaled, until the big one is there
                    local ex, ey = (d.gw - d.cw) / 2, (d.gh - d.ch) / 2
                    vc.x, vc.y, vc.w, vc.h, vc.sk = x - ex, py - ey, d.gw, d.gh, d.gsk
                    gx1, gy1, gx2, gy2 = x - ex, py - ey, x + d.cw + ex, py + d.ch + ey
                end
            end
            if o.card_shadows and not MS.debug then
                local b = math.max(4, math.floor(7 * m.S + 0.5))
                add(HV.shadow(gx1 + 2, gy1 + b * 0.6, gx2 - 2, gy2 + b * 0.9, b, sel and 62 or 48))
            end

            if not ready then
                -- mpv < 0.38 (no blurred placeholder): the tile at least takes the picture's colour, darkened
                local avg = st and HV.tiny_avg(st, d.cw, d.ch)
                if avg then
                    local function dk(p) return math.floor(tonumber(avg:sub(p, p + 1), 16) * 0.5 + 0.5) end
                    avg = string.format("%02X%02X%02X", dk(1), dk(3), dk(5))
                end
                add(D.ev_rect(x, py, x + d.cw, py + d.ch, avg or THEME.bg_panel, 100, nil, 0, 0, HV.R))
                local loading_art = st and (st.state == "new" or st.state == "searching" or st.state == "entry" or st.state == "downloading"
                    or st.state == "jpg") and not (st.cq and st.cq[d.sk] == "fail")
                if anim and PS.enabled() and card.kind ~= "missing" and loading_art and not MS.debug then
                    -- the sweep lives on the animation layer (HV.FX): it moves without the page being rebuilt
                    HV.FX.shim[#HV.FX.shim + 1] = { x, py, d.cw, d.ch }
                    A.shimmer_seen = true
                end
                local ptxt = card.ph or card.shown or card.title
                local t1, t2 = HV.wrap2(ptxt, d.cw - 16, lfs + 3)
                add(D.ev_text(x + d.cw / 2, py + d.ch / 2 - (t2 ~= "" and lfs or 0), 5, string.format("\\b1\\fs%d\\c%s", lfs + 3, U.ass_color(THEME.text_muted)), U.ass_escape(t1)))
                if t2 ~= "" then
                    add(D.ev_text(x + d.cw / 2, py + d.ch / 2 + lfs * 0.9, 5, string.format("\\b1\\fs%d\\c%s", lfs + 3, U.ass_color(THEME.text_muted)), U.ass_escape(t2)))
                end
                if PS.enabled() and st and (st.state == "new" or st.state == "searching" or st.state == "entry" or st.state == "downloading" or st.state == "jpg") and not (st.cq and st.cq[d.sk] == "fail") then
                    add(D.ev_text(x + d.cw / 2, py + d.ch - lfs * 1.6, 5, string.format("\\fs%d\\c%s", lfs, U.ass_color(THEME.text_dim)), "…"))
                end
            end
            -- ring (outside the picture so the bitmap does not cover it; thicker in couch mode)
            local rp = HV.ring_pad(m)
            if not HV.ring_on() then
                -- no outline (focus_ring=no): the dimming and the grow show the selection, the Netflix way
            elseif sel and anim then
                A.ring_to = { gx1 - rp, gy1 - rp - scroll, gx2 + rp, gy2 + rp - scroll }
            elseif sel or hov then
                add(HV.ring(gx1 - rp, gy1 - rp, gx2 + rp, gy2 + rp, sel, m))
            end
            if vc.acts then
                local acts = HV.card_actions(card)
                if #acts > 0 then
                    local cwid = gx2 - gx1
                    local dd = math.max(22, math.min(math.floor(lfs * 1.9), math.floor((cwid - 12) / (#acts + 0.6))))
                    local gap_ = math.floor(dd * 0.25)
                    local sh_ = math.max(2, math.floor(dd * 0.18))
                    local bw_ = #acts * dd + (#acts - 1) * gap_ + 2 * sh_
                    local bx = math.floor((gx1 + gx2) / 2 - bw_ / 2)
                    local by = math.floor(gy2 - dd - sh_ - math.max(4, dd * 0.25))
                    local hot = nil
                    for ai, a in ipairs(acts) do
                        local cx1 = bx + sh_ + (ai - 1) * (dd + gap_)
                        local id = "ha" .. ai
                        if HV.btn_hover == id then hot = ai end
                        HV.links[#HV.links + 1] = { x1 = cx1, x2 = cx1 + dd, y1 = by + sh_, y2 = by + sh_ + dd, hov = id, act = a.act }
                    end
                    local gl = {}
                    for ai, a in ipairs(acts) do gl[ai] = a.g end
                    HV.hab = { x = bx, y = by, d = dd, gap = gap_, glyphs = gl, hot = hot }
                end
            end
            local below = gy2 - (py + d.ch)          -- the grown card reaches this far below the normal one
            -- progress bar (Continue Watching)
            if card.frac then
                local by, bt = py + d.ch + below + m.bar_gap, m.bar_t
                add(D.ev_rect(x, by, x + d.cw, by + bt, THEME.track, 100, nil, 0, 0, bt / 2))
                add(D.ev_rect(x, by, x + math.max(bt * 2, d.cw * card.frac), by + bt, THEME.accent, 100, nil, 0, 0, bt / 2))
            end
            -- label: clean title (up to 2 lines) + muted detail line
            local ly = py + d.ch + m.bar_h + 4 + below
            -- one clean title line (… when too long), then rating · year · type · what you have, Netflix style
            local tcol = (sel or hov) and "FFFFFF" or THEME.text_primary      -- bright titles; the ring shows the selection
            local tfull = card.kind == "folder" and card.title or (card.shown or card.title)
            local t1 = HV.ell(tfull, d.cw, m.cfs, true)
            add(D.ev_text(x, ly, 7, string.format("\\b1\\fs%d\\c%s", m.cfs, U.ass_color(tcol)), U.ass_escape(t1)))
            if hov and t1 ~= tostring(tfull or "") then HV.tip_lbl = HV.tip_want(x, ly, tfull, m.cfs) end
            local parts = HV.with_rating(card)
            if #parts > 0 then
                add(D.ev_text(x, ly + math.floor(m.cfs * 1.3) + 1, 7, string.format("\\fs%d\\c%s", m.cdfs, U.ass_color(THEME.text_muted)),
                    HV.detail_ass(parts, d.cw, m.cdfs)))
            end
            until true
        end
        -- shelf arrows (Continue Watching): mpv 0.38+ an arrow over the row's edge (a picture layer, clickable), else
        -- the small marks in the margin
        if row.shelf then
            local mid = v.y + d.ch / 2
            local nvis = math.min(d.per, #row.cards - off)
            local re = math.floor(m.mx + nvis * (d.cw + m.gap) - m.gap)
            local cwid = math.floor(math.max(lfs * 2.2, w * 0.026))
            local ri_ = v.ri
            local function chev(dir)
                local id = "chev" .. ri_ .. dir
                local x1, y1, t = HV.chev_box(m, (dir > 0) and re or m.mx, v.y + d.ch / 2)
                HV.lyc[#HV.lyc + 1] = { x = x1, y = y1, w = t, h = t, dir = dir, hot = HV.btn_hover == id }
                HV.links[#HV.links + 1] = { x1 = x1, x2 = x1 + t, y1 = y1, y2 = y1 + t, hov = id, act = function()
                    HV.r = ri_
                    HV.c = math.max(1, math.min(#row.cards, (dir > 0) and (off + d.per + 1) or (off - d.per + 1)))
                    row.off = math.max(0, math.min(#row.cards - d.per, off + dir * d.per))
                    HV.want_vc = HV.vcol()
                    render()
                end }
            end
            local pic = not v.cut and not xmov
            if off > 0 and not xmov then
                if pic then chev(-1) else add(D.ev_text(m.mx / 2, mid, 5, string.format("\\b1\\fs%d\\c%s", lfs + 14, U.ass_color(THEME.text_muted)), "‹")) end
            end
            if off + d.per < #row.cards and not xmov then
                if pic then chev(1) else add(D.ev_text(w - m.mx / 2, mid, 5, string.format("\\b1\\fs%d\\c%s", lfs + 14, U.ass_color(THEME.text_muted)), "›")) end
            end
        end
    end
    if HV.tip_lbl then HV.tip_draw(add, HV.tip_lbl, w, m); HV.tip_lbl = nil end
    HV.vsb_draw(add, m, vis, top_y, bottom)
    -- a row cut off at the footer: its pictures stop at the cut, so its placeholders, shadows and titles stop there too
    -- (the glass bars leave the page visible under the footer; the posters' own fade is a picture layer, HV.LY)
    local lastv = vis[#vis]
    if lastv and lastv.cut then add(D.ev_rect(0, lastv.cut, w, h, THEME.bg_dim, HV.bg_alpha(), nil, 0, 0)) end
    -- extend the wanted list with the next row so it is ready before you scroll to it
    do
        local lastv = vis[#vis]
        local nrow = lastv and HV.rows[lastv.ri + 1]
        if nrow then
            for i = 1, HV.rowdim(nrow, m).per do
                local cd = nrow.cards[(nrow.off or 0) + i]
                if cd then HV.wanted[#HV.wanted + 1] = cd end
            end
        end
    end

    if anim and A.ring_to then
        local to = A.ring_to
        local dst = A.ring_dst
        if not A.ring_cur then A.ring_cur, A.ring_from, A.ring_t0 = to, to, now end
        if not dst or dst[1] ~= to[1] or dst[2] ~= to[2] or dst[3] ~= to[3] then
            A.ring_from, A.ring_dst, A.ring_t0 = A.ring_cur, to, now
            HV.anim_kick(0.2)
        end
        HV.FX.ring = { scroll = scroll, m = m }        -- drawn (and glided) on the animation layer
    end
    A.ring_to = nil
    A.shimmer, A.shimmer_seen = A.shimmer_seen, nil
    if anim and A.shimmer then HV.anim_kick(0.05) end
    if HV.FX.pulse and HV.pulse_on() then HV.anim_kick(0.05) end
    if (anim or HV.TR.busy()) and A.enter_t and now - A.enter_t < (A.enter_dur or 0.22) then
        HV.FX.enter = { 0, m.top_h, w, h - m.foot_h }
    end

    -- footer
    if not m.glass then
        add(D.ev_rect(0, h - m.foot_h, w, h, THEME.bg_header, 100, nil, 0, 0))
        add(D.ev_rect(0, h - m.foot_h, w, h - m.foot_h + 2, THEME.grad_top, 30, nil, 0, 0))
    end
    local ckey = tostring(o.cache_clear_key or ""):match("[^%s,]+") or ""
    local hint
    if HV.q and not m.title then
        hint = HV.typing and "Type to search (typos are fine)   genre:anime  year:2010-2020  type:tv  rating:8  unwatched   ←→ Home End Edit   ↓ Results   Enter Open   Esc Clear"
            or "←↑↓→ Move   Enter Open   F or click the box: edit search   Esc / Mouse-back Clear search"
    elseif m.title and TV.grid() then
        hint = U.hint({ "←↑↓→ Move", { "open", "Open season" }, { "refresh", "Refresh" }, { "switch_view", "List" }, { "refetch_art", "Re-fetch art" },
            { "report", "Report" }, U.knice(ckey) .. " Clear cache", U.kname("close") .. " / " .. U.kname("back") .. " Back" })
    elseif m.title then
        hint = U.hint({ "←↑↓→ Move", { "open", "Play" }, { "queue", "Queue" }, { "watched", "Watched" },
            { "sort", "Sort: " .. (HV.sort_mode() == "recent" and "Recent" or "Order") }, { "refresh", "Refresh" }, { "switch_view", "List" },
            { "refetch_art", "Re-fetch art" }, { "report", "Report" }, U.knice(ckey) .. " Clear cache", U.kname("close") .. " / " .. U.kname("back") .. " Back" })
    else
        hint = U.hint({ "←↑↓→ Move", { "open", "Open / Play" }, { "sort", "Sort: " .. (HV.sort_mode() == "recent" and "Recent" or "Name") },
            { "refresh", "Refresh" }, { "switch_view", "List" }, { "search", "Search all" },
            (HV.AX.enabled() and tostring(o.add_key):match("%S+")) and (tostring(o.add_key):match("%S+"):upper() .. " Add") or "",
            { "refetch_art", "Re-fetch art" }, U.knice(ckey) .. " Clear cache", { "close", "Close" } })
    end
    if HV.couch then
        hint = "(A) " .. ((m.title and not TV.grid()) and "Play" or "Open") .. "    (B) Back    (X) Watched    (Y) Queue    LB / RB Page    Start: Sort    View: Close"
    end
    local attr = "This product uses the TMDB API but is not endorsed or certified by TMDB."
    if o.tmdb_key == "" then attr = "Set tmdb_key in webdav-browser.conf to show posters.  " .. attr end
    local cs = PS.stats()
    local ctext = (cs.t == 0) and "Cache …" or string.format("Cache %s  ·  %d images", U.fmt_bytes(cs.bytes), cs.imgs)
    if HV.DL.cur then ctext = "↓ " .. tostring(HV.DL.progress()) .. "  ·  " .. ctext end
    if HV.pc_total and HV.pc_done and HV.pc_done < HV.pc_total then
        ctext = string.format("Preparing artwork %d / %d  ·  ", HV.pc_done, HV.pc_total) .. ctext
    end
    if m.glass then
        if not HV.DLP.visible() then HV.DLP.geo = nil end
        HV.glass_bottom(add, m, hint, ctext, attr, HV.clear_armed)
    else
    add(D.ev_text(m.mx, h - m.foot_h * 0.68, 4, string.format("\\fs%d\\c%s", lfs - 1, U.ass_color(THEME.text_muted)),
        U.ass_escape(HV.fitw(hint, w - 2 * m.mx, lfs - 1))))
    local cw_px = HV.AX.tw((ctext:gsub("%d", "0")), lfs - 3)
    local ly = h - m.foot_h * 0.28
    local left = w - m.mx - cw_px
    if HV.DLP.visible() then
        local ph_ = math.floor((lfs - 3) * 1.9)
        left = HV.DLP.place(m, left - lfs, ly - ph_ / 2, ly + ph_ / 2, lfs - 3, math.floor(ph_ * 0.55))
    else HV.DLP.geo = nil end
    add(D.ev_text(m.mx, ly, 4, string.format("\\fs%d\\c%s", lfs - 3, U.ass_color(THEME.text_dim)),
        U.ass_escape(U.fit_text(attr, left - m.mx - 30, lfs - 3))))
    add(D.ev_text(w - m.mx, ly, 6, string.format("\\fs%d\\c%s", lfs - 3, U.ass_color(HV.clear_armed and THEME.warn or THEME.text_muted)),
        U.ass_escape(ctext)))
    end

    -- the download card, over everything on the page (also while it fades out)
    if HV.dlc() or (HV.DLC and HV.DLC.closing and browser_active and HV.mode ~= "add") then HV.dl_card(add, m) end
    if HV.TK.drawn() then HV.TK.draw(add, m) end
    if HV.CM.open then HV.CM.draw(add, m) end

    -- debug panel (posters are hidden while it is open, because bitmaps draw above all text)
    if MS.debug then
        local lines = build_debug_lines()
        local dfs = math.max(11, lfs - 1)
        local lh = math.floor(dfs * 1.55)
        local dw = math.min(math.floor(w * 0.5), 760)
        local dx2, dy1 = w - 16, m.top_h + 12
        local dx1, dy2 = dx2 - dw, dy1 + #lines * lh + 16
        add(D.ev_rect(dx1, dy1, dx2, dy2, THEME.bg_header, 92, THEME.accent, 60, 1, 6))
        for i, line in ipairs(lines) do
            add(D.ev_text(dx1 + 12, dy1 + 8 + (i - 0.5) * lh, 4, string.format("\\fs%d\\c%s%s", dfs, U.ass_color(i == 1 and THEME.accent or THEME.text_primary), i == 1 and "\\b1" or ""),
                U.ass_escape(U.fit_text(line, dw - 24, dfs))))
        end
    end

    local data = table.concat(chunks, "\n")
    if HV.XA.exit then data = HV.XA.fade_ass(data, HV.XA.exit_k()) end
    if data ~= HV.last_data then
        HV.last_data = data
        overlay.data = data
        HV.cmd({ name = "osd-overlay", id = overlay.id, format = "ass-events", data = data,
                 res_x = math.floor(overlay.res_x), res_y = math.floor(overlay.res_y), z = overlay.z or 0, hidden = false }, nil, "ass")
    end
    HV.fx_draw()
    HV.place()
    HV.TR.frame()
    HV.flush()                 -- text and posters change in the same frame
    HV.pump()
    if TV.auto and HV.mode == "title" and #(TV.ordered or {}) > 0 then
        local a = TV.auto
        TV.auto = nil
        mp.add_timeout(0.05, function()
            if HV.mode ~= "title" then return end
            if a == "play" then TV.play_next() elseif a == "dl" then TV.dl_open() end
        end)
    end
end

-- ============================================================
-- TITLE PAGE  (one show: hero + episode stills grouped by season)
-- ============================================================
function TV.season_of(name)
    local fp = o.clean_titles and CT.parse_folder(name) or nil
    if fp and fp.season then
        local n = fp.season:match("^S(%d+)$") or fp.season:match("^S(%d+)E")
        if n then return tonumber(n) end
    end
    local n = name:match("[Ss]eason[%s%._%-]*(%d+)") or name:match("^[Ss](%d%d?)$")
    return n and tonumber(n) or nil
end

function TV.se_of(name, hint)
    local cp = CT.parse(name)
    local s, e
    if cp and cp.se then
        s, e = cp.se:match("^S(%d+)E(%d+)$")
        if not s then e = cp.se:match("^E(%d+)$") end
    end
    if not e then
        local a, b = name:match("(%d%d?)x(%d%d%d?)")
        if a then s, e = a, b end
    end
    s, e = tonumber(s), tonumber(e)
    local abs = (e ~= nil and s == nil and hint == nil)      -- a running number with no season anywhere
    if e and not s then s = hint or 1 end
    return s or hint, e, abs
end

function TV.clean_name(name)
    local cp = CT.parse(name)
    if cp and cp.title and cp.title ~= "" then return cp.title .. (cp.year and (" (" .. cp.year .. ")") or "") end
    return (CT.fix_chars(name):gsub("%.[%w]+$", ""):gsub("[%._]+", " "))
end

-- Listing of one folder of the open title. A failed listing is retried after 8, 16, 32... seconds (it used to wait
-- 45 s and fail silently, so episodes simply looked missing).
TV.fail = {}
function TV.ensure(href)
    local now = mp.get_time()
    local f = TV.fail[href]
    local wait = f and math.min(120, 8 * 2 ^ math.min(4, f.n - 1)) or 45
    if TV.req[href] and now - TV.req[href] < wait then return end
    TV.req[href] = now
    fetch_listing(href, { silent = true, urgent = true })
end
MS.on_listing = function(href, err)
    if not TV.card then return end
    if err and err ~= "superseded" then
        local f = TV.fail[href] or { n = 0 }
        f.n, f.err = f.n + 1, err
        TV.fail[href] = f
        TV.req[href] = mp.get_time()
        HV.sig = nil
        mp.add_timeout(0.05, HV.kick)          -- show the failure (after this callback has finished)
    else
        TV.fail[href] = nil
    end
end

function TV.show_entry()
    local card = TV.card
    if not card or not PS.enabled() then return nil end
    PS.load_index()
    local e = PS.idx[card.key]
    if type(e) == "table" and not e.none and e.id then return e end
    return nil
end

-- TMDB lookup result of one folder (with the anime map's season / offset, if any).
function TV.folder_entry(name)
    if not PS.enabled() then return nil end
    PS.load_index()
    local e = PS.idx[HV.ident(name).key]
    return (type(e) == "table" and not e.none) and e or nil
end

-- Season a whole folder holds when its name does not say (poster_overrides "...:17" or a built-in alias).
function TV.folder_season(name)
    local s = TV.season_of(name)
    if s then return s end
    if not PS.enabled() then return nil end
    PS.load_index()
    local e = PS.idx[HV.ident(name).key]
    return type(e) == "table" and tonumber(e.s) or nil
end

-- All media files of the show: its folders and up to three levels of sub-folders ("Season 05/Disc 1/...").
function TV.collect()
    local card = TV.card
    local list, loading = {}, 0
    local names = {}
    TV.failed, TV.waiting, TV.dirs, TV.dirs_of = {}, {}, {}, {}
    local function visit(folder, depth, hint, top)
        top = top or folder
        TV.dirs[#TV.dirs + 1] = folder.href
        TV.dirs_of[top.href] = TV.dirs_of[top.href] or {}
        table.insert(TV.dirs_of[top.href], folder.href)
        local c = find_cached_dir(folder.href)
        if not c or type(c.entries) ~= "table" then
            TV.ensure(folder.href); loading = loading + 1
            if TV.fail[folder.href] then TV.failed[#TV.failed + 1] = { name = folder.name, href = folder.href, err = TV.fail[folder.href].err }
            else TV.waiting[#TV.waiting + 1] = folder.name end
            return
        end
        if not cache_is_fresh(c) then TV.ensure(folder.href) end     -- show what we have, refresh quietly
        for _, e in ipairs(c.entries) do
            if e.is_dir then
                if depth < 3 then visit(e, depth + 1, TV.season_of(e.name) or hint, top) end
            elseif U.is_media(e.name) then
                local s, n, abs = TV.se_of(e.name, hint)
                -- "Part 2" folders numbered from 1 again: the map's episode offset makes E01 the season's E14
                local fe = TV.cur_fe
                if fe and tonumber(fe.mo) and n and not abs and (not tonumber(fe.me) or n <= tonumber(fe.me)) then n = n + tonumber(fe.mo) end
                list[#list + 1] = { entry = e, s = s, e = n, abs = abs, folder = folder, top = top }
                names[e.name:lower()] = true
            end
        end
    end
    TV.explicit = {}
    for _, f in ipairs(card.folders or {}) do
        local fe = TV.folder_entry(f.name)
        -- The match is stored once per show, but its anime-lists season / offset belong to ONE season: the folder
        -- that was looked up (mseason). Other seasons' folders of the same show must not inherit them.
        local tag = TV.season_of(f.name)
        if fe and fe.ms then
            local ok_
            if fe.mseason ~= nil then ok_ = (tag == tonumber(fe.mseason)) or (fe.mseason == 0 and tag == nil)
            else ok_ = (tag == nil) or (tag == tonumber(fe.ms)) end          -- older entries: be conservative
            if not ok_ then fe = nil end
        end
        local k = tag or (fe and tonumber(fe.s))
        if fe and fe.ms and k then TV.explicit[k] = tonumber(fe.ms) end
        TV.cur_fe = fe
        visit(f, 0, TV.folder_season(f.name))
    end
    TV.cur_fe = nil
    TV.names = names
    return list, loading
end

local function tv_natural(a, b)
    local as, bs = a.s or 0, b.s or 0
    if as ~= bs then return as < bs end
    if a.e and b.e and a.e ~= b.e then return a.e < b.e end
    if (a.e ~= nil) ~= (b.e ~= nil) then return a.e ~= nil end
    return U.natural_less(a.entry.name, b.entry.name)
end

-- Spreads running numbers (absolute-numbered anime, "Episode 137") over TMDB's seasons.
function TV.spread(list, sc)
    if type(sc) ~= "table" then return end
    local keys = {}
    for k in pairs(sc) do local n = tonumber(k); if n and n > 0 then keys[#keys + 1] = n end end
    table.sort(keys)
    if #keys < 2 then return end
    for _, ep in ipairs(list) do
        if ep.abs and ep.e then
            local n = ep.e
            for _, k in ipairs(keys) do
                local c = tonumber(sc[tostring(k)]) or 0
                if n <= c then ep.s, ep.e, ep.absn = k, n, ep.e; break end
                n = n - c
            end
            if not ep.absn then ep.unmapped = true end      -- past TMDB's last episode (movies, specials...)
        end
    end
end

-- "2, 11–12, 15–16"
function TV.ranges(nums)
    table.sort(nums)
    local out, i = {}, 1
    while i <= #nums do
        local j = i
        while j < #nums and nums[j + 1] == nums[j] + 1 do j = j + 1 end
        out[#out + 1] = (j > i) and (nums[i] .. "–" .. nums[j]) or tostring(nums[i])
        i = j + 1
    end
    return table.concat(out, ", ")
end

-- Files Real-Debrid has for this title that WebDAV does not list, each with Real-Debrid's reason.
-- returns list|nil (no token), state ("ready" | "loading" | "checking" | "error" | "off")
function TV.rd_missing(show)
    if not PS.rd_on() then return nil, "off" end
    local out, state = {}, "ready"
    TV.rd_want, TV.rd_have, TV.rd_short, TV.rd_pend = 0, 0, {}, 0
    for _, f in ipairs(TV.card.folders or {}) do
        local rec = PS.rd_folder(f.name)
        local want, miss = 0, 0
        if rec.state == "loading" then state = "loading"
        elseif rec.state == "error" then state = "error"
        elseif rec.state == "ready" then
            local d = rec.data
            local bad = d.status and d.status ~= "downloaded" and (PS.RD_STATUS[d.status] or tostring(d.status))
            local links, li = type(d.links) == "table" and d.links or {}, 0
            for _, fl in ipairs(type(d.files) == "table" and d.files or {}) do
                if tonumber(fl.selected) == 1 then
                    li = li + 1
                    local path = tostring(fl.path or "")
                    local base = path:match("([^/]+)$") or path
                    if U.is_media(base) then want = want + 1 end
                    if U.is_media(base) and not (TV.names or {})[base:lower()] then
                        miss = miss + 1
                        local reason = bad
                        if not reason then
                            local link = links[li]
                            if link then
                                local c = PS.rd_check(link)
                                if c then reason = c.r else reason = "Checking Real-Debrid…"; if state == "ready" then state = "checking" end end
                            else
                                reason = "No link on Real-Debrid"
                            end
                        end
                        local hint = TV.folder_season(f.name)
                        for seg in path:gmatch("[^/]+") do if seg ~= base then hint = TV.season_of(seg) or hint end end
                        local s, e, abs = TV.se_of(base, hint)
                        -- final = Real-Debrid has said this file will not come (dead torrent, hoster down...); anything
                        -- else (still checking, torrent downloading, link fine but not on WebDAV yet) may still appear
                        local st_ = tostring(d.status or "")
                        local final = reason and reason ~= "Checking Real-Debrid…" and not reason:find("not listed by WebDAV yet", 1, true)
                            and not (bad and (st_ == "downloading" or st_ == "queued" or st_ == "compressing" or st_ == "uploading"
                                or st_ == "magnet_conversion" or st_ == "waiting_files_selection"))
                        if not final then TV.rd_pend = TV.rd_pend + 1 end
                        out[#out + 1] = { s = s or 0, e = e, abs = abs, name = base, reason = reason, final = final and true or nil }
                    end
                end
            end
            if not bad then
                TV.rd_want, TV.rd_have = TV.rd_want + want, TV.rd_have + (want - miss)
                if miss > 0 then TV.rd_short[f.href] = true end
            end
        end
    end
    return out, state
end

-- Is Real-Debrid still adding files to this title? With a token: WebDAV lists fewer files than Real-Debrid says the
-- torrents hold AND that number still moved within the last 20 s. Without one: one of its folders is still growing.
function TV.links_loading()
    local now = os.time()
    for _, h in ipairs(TV.dirs or {}) do if MS.grow[h] and not MS.grow[h].forced then TV.grow_t = now; break end end
    if PS.rd_on() and (TV.rd_want or 0) > 0 then
        local p = TV.rd_prog
        if not p or p.card ~= TV.card or p.have ~= TV.rd_have then TV.rd_prog = { card = TV.card, have = TV.rd_have, t = now } end
        -- only files that may still come count; ones Real-Debrid already called dead do not keep the page waiting
        if TV.rd_have < TV.rd_want and (TV.rd_pend or 0) > 0 and now - TV.rd_prog.t < 10 then return true end
    end
    return TV.grow_t ~= nil and now - TV.grow_t < 5
end

-- Missing episodes per season: Real-Debrid's list when a token is set, plus gaps in the numbering.
function TV.find_missing(seasons, order, show)
    local out = {}
    TV.rd_state = "off"
    if not o.show_missing_episodes then return out end
    local rdm, rst = TV.rd_missing(show)
    TV.rd_state, TV.last_rdm = rst, rdm
    TV.loading_links = TV.links_loading()
    if TV.loading_links then
        -- while files are still arriving, show only what Real-Debrid has already confirmed as gone
        if rdm then TV.spread(rdm, show and show.sc) end
        for _, x in ipairs(rdm or {}) do
            if x.final and x.e then
                local k = x.s or 0
                local have = false
                for _, ep in ipairs(seasons[k] or {}) do if ep.e == x.e then have = true break end end
                if not have and k > 0 then out[k] = out[k] or {}; table.insert(out[k], x) end
            end
        end
        return out
    end
    if rdm then
        TV.spread(rdm, show and show.sc)
        for _, x in ipairs(rdm) do
            local k = x.s or 0
            local have = (k == 0 or not x.e)                 -- extras / unnumbered files: no place in a season
            for _, ep in ipairs(seasons[k] or {}) do if x.e and ep.e == x.e then have = true break end end
            if not have then
                out[k] = out[k] or {}
                table.insert(out[k], x)
            end
        end
    end
    -- gaps are looked for inside each folder's own range (a "1-13" pack next to a "27-40" pack is not a gap)
    for _, k in ipairs(order) do
        if k > 0 then
            local have, ranges, rorder = {}, {}, {}
            for _, ep in ipairs(seasons[k]) do
                if ep.e then have[ep.e] = true end
                if ep.e and not ep.unmapped then
                    local fk = (ep.top or ep.folder or {}).href or "?"
                    local r = ranges[fk]
                    if not r then r = { lo = ep.e, hi = ep.e }; ranges[fk] = r; rorder[#rorder + 1] = fk end
                    r.lo, r.hi = math.min(r.lo, ep.e), math.max(r.hi, ep.e)
                end
            end
            out[k] = out[k] or {}
            local known = {}
            for _, x in ipairs(out[k]) do if x.e then known[x.e] = true end end
            for _, fk in ipairs(rorder) do
                local r = ranges[fk]
                if r.hi - r.lo < 500 then
                    for n = (r.lo <= 3) and 1 or r.lo, r.hi do
                        if not have[n] and not known[n] then known[n] = true; table.insert(out[k], { s = k, e = n, gap = true }) end
                    end
                end
            end
        end
    end
    for k, v in pairs(out) do
        if #v == 0 then out[k] = nil
        else table.sort(v, function(a, b) return (a.e or 99999) < (b.e or 99999) end) end
    end
    return out
end

-- Season folders view: the title page of a show with several seasons first lists the seasons.
function TV.grid()
    return HV.mode == "title" and TV.multi and not TV.season
end
function TV.enter_season(k)
    TV.grid_pos = { r = HV.r, c = HV.c, top = HV.top, want_vc = HV.want_vc }
    TV.season = k
    HV.r, HV.c, HV.top, HV.want_vc, HV.hover = 1, 1, 1, 1, nil
    HV.sig, HV.last_data = nil, nil
    HV.clear()
    log_view("title-season")
    render()
end
function TV.leave_season()
    TV.season = nil
    local s = TV.grid_pos or {}
    HV.r, HV.c, HV.top, HV.want_vc, HV.hover = s.r or 1, s.c or 1, s.top or 1, s.want_vc or 1, nil
    HV.sig, HV.last_data = nil, nil
    HV.clear()
    log_view("title-page")
    render()
end

MS.inview = function()
    if MS.view == "home" and HV.mode == "title" and TV.card and TV.dirs then
        local list = {}
        for _, h in ipairs(TV.dirs) do list[#list + 1] = h end
        -- built again when what it shows changed (watched / progress, a local copy, the day, Real-Debrid's state),
        -- and every 15 s regardless; a long show takes a moment to build
        local fp = TV.fingerprint()
        if fp ~= TV.fp or os.time() - (TV.fp_t or 0) >= 15 then TV.fp, TV.fp_t = fp, os.time(); HV.sig = nil end
        if TV.loading_links and TV.rd_short then
            for fh in pairs(TV.rd_short) do
                for _, h in ipairs(TV.dirs_of and TV.dirs_of[fh] or {}) do MS.grow[h] = MS.grow[h] or { n = 0, stable = 0, t = os.time(), forced = true } end
            end
        end
        return list
    end
    return { current_path }
end

function TV.fingerprint()
    local w, pos = 0, 0
    for _, ep in ipairs(TV.ordered or {}) do
        local h = ep.entry and ep.entry.href
        if h then
            if watched_set[h] then w = w + 1 end
            local r = watch_history[h]
            if r and r.pos then pos = pos + math.floor(r.pos / 30) end
        end
    end
    return table.concat({ TV.card and TV.card.key or "", os.date("%Y%m%d"), w, pos, HV.DL.lver or 0, tostring(TV.loading),
        tostring(TV.loading_links), tostring(TV.rd_state), PS.idx_ver, (PS.RD and PS.RD.ver) or 0 }, "|")
end
function TV.reason_text(x)
    if x.reason then return x.reason end
    if TV.rd_state == "off" then return "Missing · set rd_api_token to see why" end
    if TV.rd_state == "loading" or TV.rd_state == "checking" then return "Checking Real-Debrid…" end
    if TV.rd_state == "error" then return "Missing · " .. tostring(PS.RD.err or "Real-Debrid unreachable") end
    return "Not in this torrent"
end

-- Episode info for file (s, e): TMDB's own season first; when TMDB has no such season (or it is shorter), the file's running
-- number is mapped onto TMDB's seasons instead (shows TMDB numbers continuously, absolute-numbered anime...).
-- returns info|nil, season used, episode used, needs-a-season-fetch
TV.sckeys = setmetatable({}, { __mode = "k" })
function TV.info_for(show, ep, offs)
    if not (show and show.kind ~= "movie" and ep.e) then return nil end
    PS.load_eps()
    local s = ep.s or 1
    local sc = type(show.sc) == "table" and show.sc or nil
    local direct = true
    if sc then
        local cnt = tonumber(sc[tostring(s)])
        if not cnt or ep.e > cnt then direct = false end
    end
    if direct then
        local rec = PS.eps[show.id .. ":" .. s]
        if rec == nil then return nil, s, ep.e, true end
        local info = PS.ep_info(show, s, ep.e)
        if info then return info, s, ep.e end
        if not sc then return nil, s, ep.e end
    end
    if sc then
        local keys = TV.sckeys[sc]           -- TMDB's season numbers in order, once per show (not once per episode)
        if not keys then
            keys = {}
            for k in pairs(sc) do if tonumber(k) and tonumber(k) > 0 then keys[#keys + 1] = tonumber(k) end end
            table.sort(keys)
            TV.sckeys[sc] = keys
        end
        local n = (offs[ep.s or 0] or 0) + ep.e
        for _, k in ipairs(keys) do
            local c = tonumber(sc[tostring(k)]) or 0
            if n <= c then
                local rec = PS.eps[show.id .. ":" .. k]
                if rec == nil then return nil, k, n, true end
                return PS.ep_info(show, k, n), k, n
            end
            n = n - c
        end
    end
    return nil, s, ep.e
end

function TV.build(m)
    local card = TV.card
    if not card then return {} end
    local eps, loading = TV.collect()
    TV.loading = loading
    local show = TV.show_entry()
    TV.spread(eps, show and show.sc)
    table.sort(eps, tv_natural)
    TV.ordered = eps
    local recent = (HV.sort_mode() == "recent")

    local seasons, order = {}, {}
    for _, ep in ipairs(eps) do
        local k = ep.s or 0
        if not seasons[k] then seasons[k] = {}; order[#order + 1] = k end
        table.insert(seasons[k], ep)
    end
    table.sort(order)

    -- how many episodes each local season holds, to map running numbers onto TMDB's seasons
    local counts, offs, run = {}, {}, 0
    for _, ep in ipairs(eps) do local k = ep.s or 0; counts[k] = math.max(counts[k] or 0, ep.e or 0, 1) end
    for _, k in ipairs(order) do offs[k] = run; run = run + counts[k] end
    local allmovie = true
    for _, ep in ipairs(eps) do if ep.e then allmovie = false break end end

    -- Release season numbers that are not TMDB's (Bleach: releases count 17 seasons, TMDB has 2 - season 2 is the
    -- Thousand-Year Blood War). When the files go past TMDB's last season, TMDB data is looked up by running episode
    -- number over the local seasons; a lone far season (only S17 here) maps onto TMDB's last season.
    local plan, keysT, maxT, offsR = nil, {}, 0, {}
    local scT = show and type(show.sc) == "table" and show.sc or nil
    if scT then
        for k in pairs(scT) do local n = tonumber(k); if n and n > 0 then keysT[#keysT + 1] = n; maxT = math.max(maxT, n) end end
        table.sort(keysT)
        local maxL = 0
        for _, k in ipairs(order) do maxL = math.max(maxL, k) end
        if maxT >= 1 and maxL > maxT then
            plan = {}
            local sum_prev = 0               -- episodes in TMDB's seasons before its last one
            for _, k in ipairs(keysT) do if k < maxT then sum_prev = sum_prev + (tonumber(scT[tostring(k)]) or 0) end end
            local run_ = 0
            for _, k in ipairs(order) do
                if k > 0 then
                    local contiguous = true
                    for j = 1, k - 1 do if not seasons[j] then contiguous = false break end end
                    offsR[k] = run_
                    if k <= maxT then plan[k] = "run"
                    elseif not contiguous then
                        -- holes before it: "last" only for a far-off season with nothing between (S01, S02 ... S17)
                        local between = false
                        for j = maxT + 1, k - 1 do if seasons[j] then between = true break end end
                        plan[k] = between and "run" or "last"
                    -- "last" only when this season starts right where TMDB's earlier seasons end (Bleach: 366 local
                    -- episodes before S17 = TMDB S1's 366). Solo Leveling (TMDB: ONE season of 25, local S01 + S02):
                    -- S02 starts at 13, far from 0, so it runs on (S02E01 = TMDB S01E13) instead of restarting at S01E01.
                    elseif math.abs(run_ - sum_prev) <= 3 then plan[k] = "last"
                    else plan[k] = "run" end
                    run_ = run_ + (counts[k] or 0)
                end
            end
        end
    end
    -- the anime-lists map said exactly which TMDB season a folder is (Bleach TYBW folder "S17" = TMDB season 2)
    if scT and TV.explicit and next(TV.explicit) then
        plan = plan or {}
        for k, ms in pairs(TV.explicit) do if scT[tostring(ms)] then plan[k] = "map:" .. ms end end
    end
    TV.plan = plan
    local function tmdb_coords(ep)
        if not plan or not ep.e or not plan[ep.s or 0] then return ep end
        if plan[ep.s] == "last" then return { s = maxT, e = ep.e } end
        local mt = tostring(plan[ep.s]):match("^map:(%d+)$")
        if mt then return { s = tonumber(mt), e = ep.e } end
        local n = (offsR[ep.s] or 0) + ep.e
        for _, k in ipairs(keysT) do
            local c = tonumber(scT[tostring(k)]) or 0
            if n <= c then return { s = k, e = n } end
            n = n - c
        end
        return { s = ep.s, e = ep.e, beyond = true }
    end

    TV.coords_impl = tmdb_coords
    TV.offs = offs
    local function add_info_parts(parts, info)
        if info and info.v and info.v > 0 then parts[#parts + 1] = dp(string.format("★ %.1f", info.v), THEME.star, 8.5) end
    end

    local function make_card(ep)
        local e = ep.entry
        local tc = tmdb_coords(ep)
        local info, ts, te, need
        if tc.beyond then info, ts, te = nil, tc.s, tc.e
        else info, ts, te, need = TV.info_for(show, tc, offs) end
        local nm = info and info.n ~= "" and info.n or nil
        local cp = CT.parse(e.name)
        local c = { kind = "ep", ep = ep, entry = e, name = e.name, year = "", info = info, ts = ts, te = te }
        if ep.e then
            c.title = ep.e .. ". " .. (nm or (cp and cp.ep) or ("Episode " .. ep.e))
            c.ph = "Episode " .. ep.e
        else
            c.title = (#eps == 1 or allmovie) and (card.shown or card.title) or TV.clean_name(e.name)
        end
        local parts = {}
        local hist = watch_history[e.href]
        if watched_set[e.href] then
            c.watched = true
            parts[#parts + 1] = dp("✓ Watched", THEME.good, 10)
        elseif hist and hist.pos and hist.duration and hist.duration > 0 then
            c.frac = math.min(1, hist.pos / hist.duration)
            parts[#parts + 1] = dp(U.fmt_time(math.max(0, hist.duration - hist.pos)) .. " left", THEME.warn, 10)
        end
        local ffp = o.clean_titles and CT.parse_folder((ep.top or ep.folder).name) or nil
        local chips = (cp and cp.chips and #cp.chips > 0) and cp.chips or (ffp and ffp.chips) or {}
        for _, p in ipairs(HV.chip_parts(chips)) do parts[#parts + 1] = p end
        local grp = (cp and cp.group) or (ffp and ffp.group)
        if grp then parts[#parts + 1] = dp(grp, THEME.text_dim, 7) end
        add_info_parts(parts, info)
        if e.size and e.size > 0 then parts[#parts + 1] = dp(U.fmt_bytes(e.size), THEME.text_muted, 3) end
        if info and info.r and info.r > 0 then parts[#parts + 1] = dp(info.r .. " min", THEME.text_muted, 2) end
        if info and info.d and info.d ~= "" and HV.XV.is_recent(info.d, 7) and not c.watched then table.insert(parts, 1, dp("NEW", THEME.accent, 12)) end
        if HV.DL.local_for(e) then parts[#parts + 1] = dp("⤓ on your PC", THEME.good, 9.6) end
        c.parts = parts
        if info and info.st and info.st ~= "" then
            c.key = string.format("still:%s:%d:%d", show.id, ts, te)
            c.still = { size = HV.img_size("still", m.cw), path = info.st, base = string.format("s%s_%d_%d", show.id, ts, te) }
        elseif show and not ep.e and show.backdrop_path and show.backdrop_path ~= "" then
            c.key = "bd:" .. PS.aid(show)
            c.still = { size = HV.img_size("backdrop", m.cw), path = show.backdrop_path, base = "b" .. PS.aid(show) }
        else
            c.key = "file:" .. e.href
            if need then c.need = { entry = show, s = ts } end
        end
        if ep.e and show then
            c.dbg = string.format("S%sE%s -> TMDB S%sE%s%s", tostring(ep.s), tostring(ep.e), tostring(ts), tostring(te),
                info and (info.st ~= "" and " (still)" or " (no still on TMDB)") or (need and " (fetching)" or " (no data)"))
            if plan then c.dbg = c.dbg .. "  [numbering " .. tostring(plan[ep.s] or "direct") .. "]" end
        end
        ep.dbg = c.dbg
        c.href = card.href
        -- what the "Next episode in 10..." card shows for this file
        MS.ep_meta[e.href] = { label = ep.e and string.format("S%02dE%02d", tonumber(ts or ep.s) or 0, tonumber(te or ep.e) or 0) or nil,
            name = nm, show = card.shown or card.title, key = c.still and c.key or nil, still = c.still }
        return c
    end

    -- a greyed card for an episode that is not on WebDAV
    local function missing_card(k, x)
        local info, _, _, need
        if show and x.e then
            local tc = tmdb_coords({ s = k, e = x.e })
            if not tc.beyond then info, _, _, need = TV.info_for(show, tc, offs) end
        end
        local nm = info and info.n ~= "" and info.n or nil
        local c = { kind = "missing", miss = x, year = "", href = card.href,
            key = "miss:" .. card.key .. ":" .. k .. ":" .. tostring(x.e or x.name), ph = "Unavailable" }
        c.title = x.e and (x.e .. ". " .. (nm or ("Episode " .. x.e))) or TV.clean_name(x.name or "?")
        c.reason = TV.reason_text(x)
        c.parts = { dp("⚠ " .. c.reason, THEME.warn, 10) }
        if need then c.need = { entry = show, s = k } end
        return c
    end

    local missing = TV.find_missing(seasons, order, show)
    TV.last_missing = missing
    local function note_for(k)
        local mlist = missing[k]
        if not mlist or #mlist == 0 then return nil, 0 end
        local nums, why = {}, {}
        for _, x in ipairs(mlist) do
            if x.e then nums[#nums + 1] = x.e end
            local r = TV.reason_text(x)
            why[r] = (why[r] or 0) + 1
        end
        local txt = string.format("⚠  %d episode%s missing", #mlist, #mlist == 1 and "" or "s")
        if #nums > 0 then txt = txt .. " (" .. U.fit_text(TV.ranges(nums), m.w * 0.4, m.lfs) .. ")" end
        if TV.rd_state == "off" then
            txt = txt .. ".  Possibly hoster unavailable on Real-Debrid."
        else
            local parts = {}
            for r, n in pairs(why) do parts[#parts + 1] = (n > 1) and (r .. " (" .. n .. ")") or r end
            table.sort(parts)
            txt = txt .. ".  " .. table.concat(parts, ", ")
        end
        return txt, #mlist
    end

    local real = 0
    for _, k in ipairs(order) do if k > 0 then real = real + 1 end end
    local multi = (#order > 1)
    if TV.multi ~= multi then TV.multi = multi; TV.relayout = true end
    if TV.season and not seasons[TV.season] then TV.season = nil end
    -- count EPISODES, not files: two releases of the same season must not read "48 of 25"
    local uniq, nuniq = {}, 0
    for _, ep in ipairs(eps) do
        local key
        if ep.e then local tc = tmdb_coords(ep); key = (tc.s or 0) .. ":" .. (tc.e or 0)
        else key = "f:" .. ep.entry.name:lower() end
        if not uniq[key] then uniq[key] = true; nuniq = nuniq + 1 end
    end
    TV.count, TV.seasons, TV.allmovie, TV.real_seasons = nuniq, #order, allmovie, real

    local rows = {}
    local function add_cards(list, title, note)
        local first, i = true, 1
        if #list == 0 and title then rows[#rows + 1] = { title = title, note = note, cards = {}, off = 0 } end
        while i <= #list do
            local cards = {}
            for j = i, math.min(#list, i + m.per - 1) do cards[#cards + 1] = list[j] end
            rows[#rows + 1] = { title = first and title or nil, note = first and note or nil, cards = cards, off = 0 }
            first = false
            i = i + m.per
        end
    end

    if multi and not TV.season then
        -- season folders
        local cards = {}
        for _, k in ipairs(order) do
            local list = seasons[k]
            local c = { kind = "season", season = k, year = "", href = card.href }
            local fe = list[1] and list[1].e or 1
            local tk = (k > 0) and tmdb_coords({ s = k, e = fe }).s or k          -- TMDB's season for this one
            local sname = show and type(show.sn) == "table" and show.sn[tostring(tk)] or nil
            if tk ~= k and sname and sname:lower():match("^season%s*%d+$") then sname = nil end
            if sname and show and PS.norm(sname) == PS.norm(show.name or "") then sname = nil end   -- TMDB calls it "Bleach"
            c.title = (k > 0) and ("Season " .. k) or "Other files"
            if sname and sname ~= "" and not sname:lower():match("^season%s*%d+$") and k > 0 then c.title = c.title .. " · " .. sname end
            c.ph = (k > 0) and ("Season " .. k) or "Other files"
            local parts = { dp(#list .. (allmovie and " files" or (#list == 1 and " episode" or " episodes")), THEME.text_muted, 9) }
            local _, nmiss = note_for(k)
            if nmiss > 0 then parts[#parts + 1] = dp("⚠ " .. nmiss .. " missing", THEME.warn, 10) end
            local w_ = 0
            for _, ep in ipairs(list) do if watched_set[ep.entry.href] then w_ = w_ + 1 end end
            if w_ > 0 then parts[#parts + 1] = dp(string.format("✓ %d/%d", w_, #list), THEME.good, 6) end
            c.parts = parts
            local sp = show and type(show.sp) == "table" and show.sp[tostring(tk)] or nil
            if sp and sp ~= "" then
                c.key = string.format("spost:%s:%d", show.id, tk)
                c.still = { size = HV.img_size("poster", m.gw or m.cw), path = sp, base = string.format("sp%s_%d", show.id, tk) }
            elseif show and show.poster_path and show.poster_path ~= "" then
                c.key = "spost:" .. PS.aid(show) .. ":show"
                c.still = { size = HV.img_size("poster", m.gw or m.cw), path = show.poster_path, base = "p" .. PS.aid(show) }
            else
                c.key = "season:" .. card.key .. ":" .. k
            end
            cards[#cards + 1] = c
        end
        local has0 = seasons[0] ~= nil
        add_cards(cards, string.format("%d season%s%s  ·  Enter to open", real, real == 1 and "" or "s", has0 and " + other files" or ""))
    else
        for _, k in ipairs(order) do
            if not TV.season or TV.season == k then
                local list = seasons[k]
                if recent then
                    table.sort(list, function(a, b)
                        local am, bm = a.entry.mtime or 0, b.entry.mtime or 0
                        if am ~= bm then return am > bm end
                        return tv_natural(a, b)
                    end)
                end
                local title
                if k > 0 then title = string.format("Season %d  ·  %d episode%s", k, #list, #list == 1 and "" or "s")
                else title = string.format("Files  ·  %d", #list) end   -- also for one film file: a heading keeps it apart from the poster
                local cards = {}
                for _, ep in ipairs(list) do cards[#cards + 1] = make_card(ep) end
                local note = note_for(k)
                if note and o.show_missing_episodes then
                    -- placeholders in episode order (not when sorted by date)
                    local ms = {}
                    for _, x in ipairs(missing[k]) do ms[#ms + 1] = missing_card(k, x) end
                    if recent then
                        for _, c in ipairs(ms) do cards[#cards + 1] = c end
                    else
                        local merged, mi = {}, 1
                        for _, c in ipairs(cards) do
                            local e_ = c.ep and c.ep.e
                            while ms[mi] and e_ and ms[mi].miss.e and ms[mi].miss.e < e_ do merged[#merged + 1] = ms[mi]; mi = mi + 1 end
                            merged[#merged + 1] = c
                        end
                        while ms[mi] do merged[#merged + 1] = ms[mi]; mi = mi + 1 end
                        cards = merged
                    end
                    if not title then title = "Files" end
                end
                add_cards(cards, title, note)
            end
        end
    end
    return rows
end

-- Ctrl+D (poster screens) / script-message webdav-browser-diagnose: writes a plain-text report of what this screen is
-- built from - every matching library folder, how it was grouped and matched, every folder of the open title with its
-- listing state, every file with the season/episode read from it. No user name, password, server address or token.
function TV.diagnose()
    local L = {}
    local function add(fmt, ...) L[#L + 1] = (select("#", ...) > 0) and string.format(fmt, ...) or fmt end
    local function q(v) return tostring(v == nil and "-" or v) end
    PS.load_index()
    add("webdav-browser diagnostics   %s   %s   mpv %s", SCRIPT_VERSION, os.date("%Y-%m-%d %H:%M"), q(mp.get_property("mpv-version")))
    add("options: merge_seasons=%s  merge_by_tmdb=%s  clean_titles=%s  show_missing_episodes=%s  rd_api_token=%s  tmdb_key=%s",
        q(o.merge_seasons), q(o.merge_by_tmdb), q(o.clean_titles), q(o.show_missing_episodes),
        PS.rd_on() and "set" or "empty", (o.tmdb_key ~= "") and "set" or "empty")
    add("folder listings: %d in flight, %d waiting", MS.dav_running or 0, #(MS.dav_q or {}))
    local sel = HV.selected()
    local needle = (HV.mode == "title" and TV.card and TV.card.title) or (HV.q ~= "" and HV.q) or (sel and sel.title) or ""
    local word = PS.norm((tostring(needle):match("^[%[%(]?[^%s%]%)]*") or needle):gsub("^%W+", ""))
    if #word < 3 then word = PS.norm(needle) end
    add("")
    add("== library folders containing '%s' ==", word)
    local root = find_cached_dir(root_href)
    local n = 0
    for _, e in ipairs(root and type(root.entries) == "table" and root.entries or {}) do
        if e.is_dir and PS.norm(e.name):find(word, 1, true) then
            n = n + 1
            local id = HV.ident(e.name)
            local fp = id.fp or {}
            local ix = PS.idx[id.key]
            local tm = (type(ix) == "table" and ix.id) and string.format("%s %s '%s' via '%s'%s", q(ix.kind), q(ix.id), q(ix.name), q(ix.q), ix.s and (" season " .. ix.s) or "")
                or ((type(ix) == "table" and ix.none) and ("not found after: " .. table.concat(ix.tried or {}, " | ")) or "not looked up yet")
            local c = find_cached_dir(e.href)
            add("%s", e.name)
            add("    title '%s'  year '%s'  season-tag %s  group %s  kind-hint %s  card-key %s", q(id.title), q(id.year), q(fp.season), q(fp.group), q(id.kindpref), HV.gkey(e.name))
            add("    TMDB: %s", tm)
            add("    listing: %s", c and type(c.entries) == "table" and string.format("%d entries, %ds old", #c.entries, os.time() - (c.ts or os.time()))
                or (listing_error[e.href] and ("ERROR " .. tostring(listing_error[e.href])) or "not loaded"))
        end
    end
    if n == 0 then add("(none - the library root may not be loaded yet)") end
    local card = (HV.mode == "title" and TV.card) or nil
    if card then
        local show = TV.show_entry()
        add("")
        add("== title page '%s'  (card key %s, %d folder%s) ==", q(card.title), q(card.key), #(card.folders or {}), #(card.folders or {}) == 1 and "" or "s")
        if show then
            local sc = {}
            if type(show.sc) == "table" then
                local ks = {}
                for k in pairs(show.sc) do ks[#ks + 1] = tonumber(k) end
                table.sort(ks)
                for _, k in ipairs(ks) do sc[#sc + 1] = string.format("S%d=%s%s", k, q(show.sc[tostring(k)]),
                    (type(show.sn) == "table" and show.sn[tostring(k)]) and (" '" .. show.sn[tostring(k)] .. "'") or "") end
            end
            add("TMDB: %s %s '%s'  seasons: %s", q(show.kind), q(show.id), q(show.name), (#sc > 0) and table.concat(sc, ", ") or "(details not loaded)")
        else
            add("TMDB: no match")
        end
        if TV.plan then
            local ps = {}
            for k, v in pairs(TV.plan) do ps[#ps + 1] = "S" .. k .. "=" .. v end
            table.sort(ps)
            add("season numbering differs from TMDB: %s", table.concat(ps, " "))
        end
        local byhref = {}
        for _, ep in ipairs(TV.ordered or {}) do byhref[ep.entry.href] = ep end
        local function walk(folder, depth, indent)
            local c = find_cached_dir(folder.href)
            local st
            if c and type(c.entries) == "table" then st = string.format("%d entries", #c.entries)
            elseif TV.fail[folder.href] then st = "FAILED: " .. tostring(TV.fail[folder.href].err) .. " (" .. TV.fail[folder.href].n .. "x)"
            elseif listing_error[folder.href] then st = "ERROR: " .. tostring(listing_error[folder.href])
            else st = "not loaded yet" end
            add("%s[%s]  season hint %s  - %s", indent, folder.name, q(depth == 0 and TV.folder_season(folder.name) or TV.season_of(folder.name)), st)
            if not (c and type(c.entries) == "table") then return end
            for _, e in ipairs(c.entries) do
                if e.is_dir then
                    if depth < 3 then walk(e, depth + 1, indent .. "    ")
                    else add("%s    [%s]  (deeper than 3 levels - not read)", indent, e.name) end
                elseif U.is_media(e.name) then
                    local ep = byhref[e.href]
                    local cp = CT.parse(e.name)
                    if ep and not ep.dbg and ep.e and show and TV.coords_impl then
                        local tc = TV.coords_impl(ep)
                        local info = (not tc.beyond) and TV.info_for(show, tc, TV.offs or {}) or nil
                        ep.dbg = string.format("S%sE%s -> TMDB S%sE%s%s", q(ep.s), q(ep.e), q(tc.s), q(tc.e),
                            info and (" '" .. tostring(info.n) .. "'") or (tc.beyond and " (past TMDB's episodes)" or " (TMDB data not loaded yet)"))
                    end
                    add("%s    %s", indent, e.name)
                    add("%s        parsed %s  ->  shown in Season %s as episode %s%s%s", indent, q(cp and cp.se),
                        q(ep and ep.s), q(ep and ep.e), (ep and ep.absn) and (" (running number " .. ep.absn .. ")") or "",
                        (ep and ep.dbg) and ("   " .. ep.dbg) or "")
                else
                    add("%s    %s  (not a media file - skipped)", indent, e.name)
                end
            end
        end
        add("")
        for _, f in ipairs(card.folders or {}) do walk(f, 0, "") end
        if TV.last_missing then
            add("")
            add("missing episodes (Real-Debrid: %s%s):", q(TV.rd_state), PS.RD.err and (", " .. PS.RD.err) or "")
            local ks = {}
            for k in pairs(TV.last_missing) do ks[#ks + 1] = k end
            table.sort(ks)
            for _, k in ipairs(ks) do
                for _, x in ipairs(TV.last_missing[k]) do
                    add("    S%s E%s  %s  %s", q(k), q(x.e), x.name and ("'" .. x.name .. "'") or "(gap in numbering)", TV.reason_text(x))
                end
            end
        end
    end
    local path = mp.command_native({ "expand-path", "~~/webdav-diagnostics.txt" })
    local f = io.open(path, "wb")
    if f then
        f:write(table.concat(L, "\n"), "\n"); f:close()
        status_line = "Report saved: " .. path
        HV.say({ eyebrow = "DIAGNOSTICS", title = "Saved", extra = path }, 5)
    else
        status_line = "Could not write " .. path
    end
    render()
end
mp.register_script_message("webdav-browser-diagnose", function() TV.diagnose() end)

-- Converted bitmaps (.bgra) are re-creatable and one set exists per window size; keep only the sizes in use now
-- so resizing the window over months cannot pile up hundreds of MB. Downloaded images and TMDB data are never pruned.
-- ---------- animations (animations=yes) ----------
-- Gliding selection outline, a quick fade-in when a screen opens, shimmering placeholders while art loads and a short
-- smooth scroll. Posters are images mpv cannot fade, so they appear at once; everything runs only while no video plays.
HV.A = {}
function HV.ease(k) k = math.max(0, math.min(1, k)); return 1 - (1 - k) ^ 3 end
mp.observe_property("path", "string", function(_, v) HV.has_file = v ~= nil end)
mp.observe_property("pause", "bool", function(_, v) HV.paused = v end)
-- nothing moves over a playing video (the browser is then a menu over the film)
function HV.motion_ok() return not (HV.has_file and HV.paused == false) end
function HV.anim_on()
    if not o.animations then return false end
    return HV.motion_ok()
end
-- frames per second for the animations: the display's refresh rate, at most 90 (animation_fps sets it yourself).
-- The motion follows the clock, not the frame count, so it looks the same at any rate.
-- the breathing status dot (pulse=yes): only while nothing plays behind the browser
function HV.pulse_on() return o.pulse ~= false and HV.motion_ok() end
function HV.anim_fps()
    local f = tonumber(o.animation_fps) or 0
    if f <= 0 then
        -- the display's rate, asked for at most every 30 s (asking waits on mpv; watching it fires all the time)
        local now = mp.get_time()
        if not HV.dfps or now - (HV.dfps_t or 0) > 30 then HV.dfps, HV.dfps_t = mp.get_property_number("display-fps") or 60, now end
        f = HV.dfps
    end
    if f ~= f or f <= 0 or f == math.huge then f = 60 end           -- unknown refresh rate (NaN): 60
    return math.max(30, math.min(90, f))
end
-- the Tracked flyout and the downloads card fade in and out (their alpha follows t0 / closing): those frames need the
-- page itself drawn again, as a scroll does - without this the flyout stayed at its first, invisible frame until
-- the next mouse move (it seemed to need several clicks, and to shake)
HV.TW = {}
function HV.anim_val(name, target, dur)
    local t = HV.TW[name]
    if not HV.anim_on() then HV.TW[name] = { from = target, to = target, t0 = 0, dur = dur, v = target }; return target end
    local now = U.now_s()
    if not t then t = { from = target, to = target, t0 = 0, dur = dur, v = target }; HV.TW[name] = t end
    if t.to ~= target then
        t.from, t.to, t.t0, t.dur = t.v, target, now, dur
        HV.anim_kick(dur + 0.05)
    end
    local k = math.min(1, (now - t.t0) / math.max(0.01, t.dur))
    t.v = t.from + (t.to - t.from) * HV.ease(k)
    if k >= 1 then t.v = t.to end
    return t.v
end
function HV.tw_live()
    local now = U.now_s()
    -- by its time only (a few frames past the end, so the last one is drawn at rest): a value left half-way because its
    -- element is no longer drawn (a page that changed meanwhile) used to keep the page redrawing every frame
    for _, t in pairs(HV.TW) do if now - t.t0 < t.dur + 0.06 then return true end end
    return false
end
function HV.fading()
    if HV.XA and HV.XA.exit then return true end
    if not HV.anim_on() then return false end
    if HV.tw_live() then return true end
    local now = U.now_s()
    if HV.TK.open and not HV.TK.closing and HV.TK.t0 and now - HV.TK.t0 < 0.24 then return true end
    if HV.CM and HV.CM.open and HV.CM.t0 and now - HV.CM.t0 < 0.2 then return true end
    if HV.TK.closing then return true end
    local P = HV.DLC
    if P and P.closing then return true end
    if P and P.t0 and now - P.t0 < 0.24 then return true end
    return false
end
-- mpv in the background (another window has the focus, or it is minimised): nothing needs to breathe
function HV.backgrounded() return MS.P.focused == false or MS.P["window-minimized"] == true end
function HV.anim_kick(dur)
    local A = HV.A
    A.till = math.max(A.till or 0, U.now_s() + (dur or 0.2))
    if A.timer and A.slow then A.timer:kill(); A.timer = nil end          -- something moves now: full frame rate again
    if A.timer then return end
    A.slow = nil
    A.timer = mp.add_periodic_timer(1 / HV.anim_fps(), HV.anim_tick)
end
function HV.anim_tick()
        local A = HV.A
        local pulsing = HV.pulse_on() and HV.FX.pulse ~= nil
        local rev = HV.REV ~= nil
        local gliding = HV.scrolling() or HV.fading()
        local pill = ((HV.DLP.live() or (HV.DLC and HV.DLC.closing) or HV.TK.closing) and HV.mode ~= "add") or HV.TK.ringing()
        local live = browser_active and MS.view == "home" and (HV.anim_on() or HV.TR.busy() or pulsing or rev or gliding or pill)
        local quiet = U.now_s() > (A.till or 0) and not A.shimmer and not HV.TR.busy() and not rev and not gliding and not pill
        if not live or (quiet and not pulsing) or (quiet and HV.backgrounded()) then
            A.timer:kill(); A.timer, A.slow = nil, nil
            if browser_active then HV.fx_draw(); HV.flush() end
            return
        end
        -- only the dot's halo moves: 15 frames a second are plenty for it (the page was redrawn at the display's rate)
        if quiet and not A.slow then
            A.timer:kill()
            A.slow = true
            A.timer = mp.add_periodic_timer(1 / 15, HV.anim_tick)
        elseif A.slow and not quiet then
            A.timer:kill(); A.timer, A.slow = nil, nil
            HV.anim_kick(0)                 -- something else moves again: back to the display's rate
            return
        end
        -- one frame: the small animation layer only (ring, shimmer, fade-in) - the page itself is not rebuilt. Sent
        -- straight to mpv, not through the page's queue: that queue waits while mpv works through a burst of posters,
        -- and a frame that waits is a stutter
        if gliding then
            -- one whole frame of the page; skipped while mpv still works through the previous one (it would only queue)
            if HV.inflight == 0 then HV.last_data = nil; render() end       -- drawn again, not rebuilt (nothing in the rows moves)
            return
        end
        HV.TR.frame(true)
        if rev then HV.place() end            -- the next row's cards, the backdrop's next size
        HV.fx_draw(true)
        HV.flush()
end
-- back in front: the dot breathes again
for _, n in ipairs({ "focused", "window-minimized" }) do
    mp.observe_property(n, "native", function()
        if browser_active and MS.view == "home" and not HV.backgrounded() then HV.anim_kick(0.05) end
    end)
end

-- ---- the animation layer: one small overlay above the page for what moves every frame ----
HV.FX = { shim = {}, ring = nil, enter = nil, ov = mp.create_osd_overlay("ass-events"), last = nil }
-- a placeholder still loading gets the sweep (top: it is in the flyout / a window itself, drawn over the page)
function HV.shim_add(x, y, w, h, top, rad)
    if not (HV.anim_on() and PS.enabled()) or MS.debug then return end
    HV.FX.shim[#HV.FX.shim + 1] = { x, y, w, h, top = top or nil, rad = rad }
    HV.A.shimmer_seen = true
    if not HV.A.shimmer then HV.A.shimmer = true; HV.anim_kick(0.05) end
end
-- is a picture of the add screen / the flyout still on its way (not failed, not missing)
function HV.img_loading(path)
    if not path then return false end
    local st = HV.AX.imgs[path]
    return st ~= nil and st.state ~= "error"
end
function HV.fx_draw(direct)
    if HV.XA.exit then return HV.fx_clear() end            -- leaving: the ring, the glow and the shimmer go first
    local F, A = HV.FX, HV.A
    local ev = {}
    local now = U.now_s()
    if browser_active and MS.view == "home" and F.pulse and HV.pulse_on() and not (HV.DR and HV.DR.open) then
        -- a soft halo grows out of the dot and fades, once every couple of seconds (faster while loading)
        local x, y, r, col, per = F.pulse[1], F.pulse[2], F.pulse[3], F.pulse[4], F.pulse[5]
        local k = ((math.floor(now * 30) / 30) % per) / per      -- 30 steps a second is smooth for a soft glow, and cheap
        local e = 1 - (1 - k) ^ 2
        local hr = r * (1.2 + 1.9 * e)
        ev[#ev + 1] = string.format("{\\an7\\pos(0,0)\\bord0\\shad0\\blur%s\\1c%s\\1a%s\\3a&HFF&\\p1}%s{\\p0}", D.fp(r * 0.6),
            U.ass_color(col), U.ass_alpha(55 * (1 - k)), D.rounded_path(x - hr, y - hr, x + hr, y + hr, hr, true))
    end
    -- zoom: the title page's lines and rows of cards are held back by masks in the page colour, then come in turn
    if browser_active and MS.view == "home" and HV.mode == "title" and (HV.REV or HV.rev_hold()) and HV.bg_alpha() >= 100 then
        local t = HV.rev_hold() and -1 or (now - HV.REV.t0)
        for i, r in ipairs(TV.hero_lines or {}) do
            local k = HV.ease((t - (i - 1) * HV.REV_LINE) / 0.22)
            if k < 1 then ev[#ev + 1] = D.ev_rect(r[1], r[2], r[3], r[4], THEME.bg_dim, math.floor((1 - k) * 100), nil, 0, 0) end
        end
        local ord = HV.rev_order()
        local m = HV.m
        for _, v in ipairs(HV.vis or {}) do
            local d = HV.rowdim(HV.rows[v.ri], m)
            local k = HV.ease((t - HV.REV_ROW0 - (ord[v.ri] or 0) * HV.REV_ROW) / 0.18)
            if k < 1 and m then
                ev[#ev + 1] = D.ev_rect(0, v.ty - 4, m.w, math.min(v.cut or 1e9, v.y + d.block_h), THEME.bg_dim, math.floor((1 - k) * 100), nil, 0, 0)
            end
        end
    end
    if browser_active and MS.view == "home" and HV.mode ~= "add" and not (HV.DR and HV.DR.open) then
        local edur = A.enter_dur or 0.22
        if F.enter and A.enter_t and now - A.enter_t < edur and HV.bg_alpha() >= 100 then
            local k = HV.ease((now - A.enter_t) / edur)
            local e = F.enter
            ev[#ev + 1] = D.ev_rect(e[1], e[2], e[3], e[4], THEME.bg_dim, math.floor((1 - k) * 100), nil, 0, 0)
        end
        if F.ring and A.ring_dst and A.ring_from and A.ring_t0 and not (HV.TR.st and HV.TR.st.kind == "play")
            and not (HV.mode == "title" and (HV.REV or HV.rev_hold())) then           -- the ring comes with its row
            local k = HV.ease((now - A.ring_t0) / 0.16)
            local to, cur = A.ring_dst, {}
            for i = 1, 4 do cur[i] = A.ring_from[i] + (to[i] - A.ring_from[i]) * k end
            A.ring_cur = cur
            local sc = F.ring.scroll or 0
            ev[#ev + 1] = HV.ring(cur[1], cur[2] + sc, cur[3], cur[4] + sc, true, F.ring.m, k < 1)
        end
        HV.TR.fx(ev, now)
        HV.DLP.draw(ev, now)
    end
    -- the loading sweep over placeholders (library cards, the add screen's posters, the Tracked flyout's): never over
    -- the flyout or the queue window from a card under it
    if browser_active and MS.view == "home" and not (HV.DR and HV.DR.open) then
        local ph = (now * 0.9) % 1.6 - 0.3
        local hole = (HV.TK.drawn() and HV.TK.hole) or (HV.dlc() and HV.DLC and HV.DLC.hole) or nil
        for _, r in ipairs(F.shim) do
            local x, y, cw, ch = r[1], r[2], r[3], r[4]
            local under = hole and not r.top and x < hole[3] and x + cw > hole[1] and y < hole[4] and y + ch > hole[2]
            local bx1 = math.max(x, x + ph * cw)
            local bx2 = math.min(x + cw, x + (ph + 0.25) * cw)
            if bx2 > bx1 and not under then ev[#ev + 1] = D.ev_rect(bx1, y, bx2, y + ch, "FFFFFF", r.op or 5, nil, 0, 0, r.rad or 0) end
        end
    end
    HV.TK.ring_fx(ev, now)
    local data = table.concat(ev, "\n")
    if data == F.last then return end
    F.last = data
    local ww, wh = U.canvas_size()
    local args = { name = "osd-overlay", id = F.ov.id, format = "ass-events", data = data, res_x = ww, res_y = wh,
             z = (overlay.z or 0) + 1, hidden = false }
    if direct then HV.cmd_drop("fx"); mp.command_native_async(args, function() end) else HV.cmd(args, nil, "fx") end
end
function HV.fx_clear()
    local F = HV.FX
    F.shim, F.ring, F.enter = {}, nil, nil
    if F.last ~= "" then
        F.last = ""
        mp.command_native_async({ name = "osd-overlay", id = F.ov.id, format = "none", data = "" }, function() end)
    end
end

-- ============================================================
-- EXPERIMENTAL motion (26.10). Each effect has its own experimental_* option (off unless set) and, like the other
-- animations, runs only with animations=yes and nothing playing behind the browser (the Now playing card and the
-- toasts excepted: they belong to playback). Nothing here moves while the page rests.
-- ============================================================
HV.XA = { dec = {}, rb = nil, exit = nil, title_n = 0 }
function HV.XA.on(name) return o["experimental_" .. name] == true end
function HV.XA.live(name) return o["experimental_" .. name] == true and HV.anim_on() end
-- keeps the page's own frames coming for dur seconds (HV.fading -> HV.tw_live), under a name of its own
function HV.XA.frames(name, dur)
    local now = U.now_s()
    HV.TW[name] = { from = 1, to = 1, t0 = now, dur = dur, v = 1 }
    HV.anim_kick(dur + 0.05)
end
-- one ASS event with more override tags in front ("{\\an7..." -> "{<tags>\\an7...")
function HV.XA.inj(ev, tags)
    if tags == "" then return ev end
    if ev:sub(1, 1) == "{" then return "{" .. tags .. ev:sub(2) end
    return "{" .. tags .. "}" .. ev
end
function HV.XA.clamp(v, a, b) return math.max(a, math.min(b, v)) end

-- ---- rubberband: pushing past the end gives a short springy bounce (a row sideways, or the page) ----
-- out quickly, back with a little overshoot, at rest at k = 1
function HV.XA.spring(k)
    if k <= 0 or k >= 1 then return 0 end
    return (1 - k) ^ 2 * math.sin(k * math.pi * 1.6) / 0.535
end
HV.XA.RB_DUR = 0.38
-- kind: "h" a row of the library (ri), "ax" a row of the add screen (ri), "v" the library page; dir: the push (+1 / -1)
function HV.XA.bump(kind, ri, dir)
    if not HV.XA.live("rubberband") then return end
    local b = HV.XA.rb
    local now = U.now_s()
    -- a held key: one bounce, not one per repeat (a new one only once the last has nearly settled)
    if b and b.kind == kind and b.ri == ri and b.dir == dir and now - b.t0 < HV.XA.RB_DUR * 0.8 then return end
    HV.XA.rb = { kind = kind, ri = ri, dir = dir, t0 = now }
    HV.XA.frames("xa_rb", HV.XA.RB_DUR)
end
-- is the picture of a card in row ri moving this frame (the exit, the page bouncing, its own row bouncing)
function HV.XA.moving(ri)
    if HV.XA.exit then return true end
    local r = HV.rows and HV.rows[ri]                  -- a row gliding sideways (not one held by a drag: you look at it)
    if r and r.xs_geo and r.xs_geo.st and r.xs_geo.st.g then return true end
    local b = HV.XA.rb
    return b ~= nil and (b.kind == "v" or (b.kind == "h" and b.ri == ri))
end
-- the offset (px) of that row / the page right now: the content moves against the push
function HV.XA.rb_off(kind, ri, m)
    local b = HV.XA.rb
    if not b or b.kind ~= kind or (ri and b.ri ~= ri) then return 0 end
    local k = (U.now_s() - b.t0) / HV.XA.RB_DUR
    if k >= 1 then HV.XA.rb = nil; return 0 end
    local S = (m and m.S) or 1
    return math.floor(-b.dir * (kind == "v" and 34 or 30) * S * HV.XA.spring(k) + 0.5)
end

-- ---- parallax: the Continue Watching picture under the pointer floats against it (a few pixels) ----
function HV.XA.par_on() return HV.XA.live("parallax") and HV.mouse_mode() and HV.dw_ok() end
-- offset of a card's picture (x, y, w, h on screen), from where the pointer is
function HV.XA.par(x, y, w, h)
    local mx, my = U.mouse_xy()
    if not mx then return 0, 0 end
    local nx = HV.XA.clamp((mx - (x + w / 2)) / (w / 2), -1, 1)
    local ny = HV.XA.clamp((my - (y + h / 2)) / (h / 2), -1, 1)
    local p = math.max(3, w * 0.022)
    return math.floor(-nx * p + 0.5), math.floor(-ny * p * 0.6 + 0.5)
end

-- ---- the text cursor: it blinks (solid while you type), and the letter you just typed fades in ----
HV.XA.FADE = 0.15
function HV.XA.typed(ins)
    HV.XA.type_t, HV.XA.type_ins = U.now_s(), ins and true or nil
    if not HV.XA.on("caret") then return end
    if ins and HV.anim_on() then HV.XA.frames("xa_type", HV.XA.FADE) end
    HV.XA.blink_arm()
end
-- a text field has the keys: the search box, the add screen's query or its filter
function HV.XA.field_on()
    if not browser_active then return false end
    if HV.typing then return true end
    local AX = HV.AX
    return HV.mode == "add" and AX ~= nil and (AX.stage == "query" or AX.fedit == true)
end
function HV.XA.caret_vis()
    if not HV.XA.on("caret") or not HV.anim_on() then return true end      -- (over a playing video: solid, no redraws)
    local dt = U.now_s() - (HV.XA.type_t or 0)
    if dt < 0.55 then return true end
    return math.floor((dt - 0.55) / 0.53) % 2 == 1          -- off, on, off... (half a second each)
end
-- two redraws a second while a field is focused (only when the caret turns on or off)
function HV.XA.blink_arm()
    if HV.XA.blink or not HV.XA.on("caret") then return end
    HV.XA.blink = mp.add_periodic_timer(0.1, function()
        if not HV.XA.field_on() then HV.XA.blink:kill(); HV.XA.blink, HV.XA.cv = nil, nil; return end
        local v = HV.XA.caret_vis()
        if v ~= HV.XA.cv then HV.XA.cv = v; HV.last_data = nil; render() end
    end)
end
-- the caret glyph: hidden it stays in the line (see-through), so the letters after it do not jump
function HV.XA.caret(rgb, after_rgb, narrow, base_a)
    HV.XA.blink_arm()
    local vis = HV.XA.caret_vis()
    HV.XA.cv = vis
    return string.format("{\\c%s%s%s}▏{%s\\c%s%s}", U.ass_color(rgb), narrow and "\\fscx35" or "", vis and "" or "\\1a&HFF&",
        narrow and "\\fscx100" or "", U.ass_color(after_rgb), vis and "" or ("\\1a" .. (base_a or "&H00&")))
end
-- the text before the cursor, escaped, with its last letter fading in when it was just typed. base: the line's own
-- opacity (0-100), for a field that is itself fading
function HV.XA.before(txt, base)
    txt = tostring(txt or "")
    local dt = U.now_s() - (HV.XA.type_t or 0)
    if not (HV.XA.on("caret") and HV.XA.type_ins and dt < HV.XA.FADE and HV.anim_on() and txt ~= "") then return U.ass_escape(txt) end
    local i = #txt                                   -- the last letter starts here (UTF-8: skip its continuation bytes)
    while i > 1 and txt:byte(i) >= 128 and txt:byte(i) < 192 do i = i - 1 end
    local head, last = txt:sub(1, i - 1), txt:sub(i)
    local k = HV.ease(dt / HV.XA.FADE)
    base = base or 100
    return U.ass_escape(head) .. "{\\1a" .. U.ass_alpha(base * k) .. "}" .. U.ass_escape(last) .. "{\\1a" .. U.ass_alpha(base) .. "}"
end

-- ---- leaving the browser: the page fades into the video while its pictures shrink away (mpv 0.38+) ----
HV.XA.EXIT = 0.24
function HV.XA.dismiss()
    if HV.XA.exit then return HV.XA.exit_end() end            -- asked again: at once
    if not (HV.XA.live("exit_to_video") and HV.dw_ok() and MS.view == "home" and HV.mode ~= "add" and not HV.modal()
        and not HV.TR.busy() and not MS.debug) then return close_browser() end
    local x = { t0 = U.now_s() }
    HV.XA.exit = x
    unbind_all()                       -- the browser's keys go; the open key ends it at once
    -- and mpv's own mouse / wheel / Esc bindings stay out of it (a double-click would go fullscreen, the wheel seek)
    for _, k in ipairs(HV.XA.EXIT_KEYS) do
        local end_now = (k == "ESC" or k:match("^MBTN_LEFT") ~= nil)
        mp.add_forced_key_binding(k, "wb_xa_exit_" .. k, function() if end_now then HV.XA.exit_end() end end)
    end
    HV.fx_clear()
    HV.XA.frames("xa_exit", HV.XA.EXIT)
    mp.add_timeout(HV.XA.EXIT + 0.2, function() if HV.XA.exit == x then HV.XA.exit_end() end end)     -- never left half-way
    HV.last_data = nil
    render()
end
HV.XA.EXIT_KEYS = { "ESC", "MBTN_LEFT", "MBTN_LEFT_DBL", "MBTN_RIGHT", "MBTN_RIGHT_DBL", "MBTN_MID", "MBTN_BACK", "MBTN_FORWARD",
    "WHEEL_UP", "WHEEL_DOWN", "WHEEL_LEFT", "WHEEL_RIGHT", "ENTER", "SPACE", "BS" }
function HV.XA.exit_keys_off()
    for _, k in ipairs(HV.XA.EXIT_KEYS) do mp.remove_key_binding("wb_xa_exit_" .. k) end
end
function HV.XA.exit_end()
    HV.XA.exit = nil
    HV.XA.exit_keys_off()
    if browser_active then close_browser() end
end
-- 1 -> 0: how much of the page is left
function HV.XA.exit_k()
    local x = HV.XA.exit
    if not x then return 1 end
    return 1 - HV.XA.clamp((U.now_s() - x.t0) / HV.XA.EXIT, 0, 1)
end
-- the page's ASS with every alpha scaled to a (1 = as it is, 0 = gone): each event gets its own alpha first, so the
-- ones that set none fade too
function HV.XA.fade_ass(data, a)
    if a >= 0.999 then return data end
    local function sc(hex) return string.format("%02X", math.floor(255 - (255 - (tonumber(hex, 16) or 0)) * a + 0.5)) end
    local base = string.format("\\alpha&H%02X&", math.floor(255 * (1 - a) + 0.5))
    local out = {}
    for line in (data .. "\n"):gmatch("([^\n]*)\n") do
        if line ~= "" then
            line = line:gsub("\\([1-4]a)&H(%x%x)&", function(t, hx) return "\\" .. t .. "&H" .. sc(hx) .. "&" end)
            line = line:gsub("\\alpha&H(%x%x)&", function(hx) return "\\alpha&H" .. sc(hx) .. "&" end)
            out[#out + 1] = HV.XA.inj(line, base)
        end
    end
    return table.concat(out, "\n")
end
-- a picture at x, y, w x h, shrunk around its middle for the exit: x, y, w, h (w / h 0 = gone)
function HV.XA.exit_box(x, y, w, h)
    local k = 1 - HV.XA.exit_k()
    local g = 1 - k * k
    local dw, dh = math.floor(w * g), math.floor(h * g)
    return math.floor(x + (w - dw) / 2), math.floor(y + (h - dh) / 2), dw, dh
end

-- ---- the title page's Play button tilts towards the pointer (libass' 3D rotation, eased) ----
function HV.XA.tilt(id, x, y, w, h)
    if not HV.XA.on("play_tilt") then return "" end
    local hot = HV.btn_hover == id and HV.mouse_mode() and HV.anim_on()
    local tx, ty = 0, 0
    if hot then
        local mx, my = U.mouse_xy()
        if mx then
            tx = HV.XA.clamp((mx - (x + w / 2)) / (w / 2), -1, 1)
            ty = HV.XA.clamp((my - (y + h / 2)) / (h / 2), -1, 1)
        end
    end
    -- the side under the pointer is pressed in: about 16 degrees across, 22 up and down (a wide, low button)
    local ay = HV.anim_val("xa_tilt_y", math.floor(tx * 16 + 0.5), 0.14)
    local ax = HV.anim_val("xa_tilt_x", math.floor(-ty * 22 + 0.5), 0.14)
    if math.abs(ax) < 0.05 and math.abs(ay) < 0.05 then return "" end
    return string.format("\\org(%d,%d)\\frx%.2f\\fry%.2f", math.floor(x + w / 2), math.floor(y + h / 2), ax, ay)
end

-- ---- decode: text that types itself in, scrambled letters settling left to right ----
HV.XA.DEC_CH = "ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz0123456789#%&*+=?@"
-- the text as it shows now. A new text (or a new gen) under key starts a decode. page: frames for the browser page (a
-- toast has its own). One slot per key ("hero", "online", "note", "ts"), so nothing piles up.
function HV.XA.decode(key, text, dur, page, gen)
    text = tostring(text or "")
    if not HV.XA.on("decode") or text == "" or not o.animations then return text end
    local now = U.now_s()
    local d = HV.XA.dec[key]
    -- only the numbers changed ("Loading links · 3 / 9"), or a new text came within 1.5 s of the last decode: no new
    -- one (a counter would keep it scrambled, a status flickering between two words would never rest)
    if d and d.gen == gen and d.text ~= text and ((d.text:gsub("%d+", "#")) == (text:gsub("%d+", "#")) or now - d.t0 < 1.5) then
        d.text = text
    end
    if not d or d.text ~= text or d.gen ~= gen then
        if page ~= false and not HV.anim_on() then HV.XA.dec[key] = { text = text, t0 = -1e9, dur = 0, gen = gen }; return text end
        d = { text = text, t0 = now, dur = dur or 0.6, gen = gen }
        HV.XA.dec[key] = d
        if page ~= false then HV.XA.frames("xa_dec_" .. key, d.dur) end
    end
    local k = (now - d.t0) / math.max(0.01, d.dur)
    if k >= 1 then return text end
    local n = U.utf8_len(text)
    local out, i = {}, 0
    local frame = math.floor(now * 24)                 -- the scrambled letters change 24 times a second
    local ch_n = #HV.XA.DEC_CH
    for ch in text:gmatch("[%z\1-\127\194-\244][\128-\191]*") do
        i = i + 1
        local settle = 0.2 + 0.8 * (i / math.max(1, n))
        if k >= settle or not ch:match("^%w$") then out[#out + 1] = ch
        else
            local r = ((i * 7919 + frame * 104729) % ch_n) + 1
            out[#out + 1] = HV.XA.DEC_CH:sub(r, r)
        end
    end
    return table.concat(out)
end


-- ---- rows that scroll sideways (Continue Watching, the title page's rows, the add screen's rows):
-- experimental_row_drag - they glide when they page (keys, arrows, the sideways wheel) and can be dragged with the
-- mouse; dragged past either end they stretch and spring back, a flick carries on, a release settles on a card.
HV.XS = { DUR = 0.3, st = {} }
function HV.XS.on() return o.experimental_row_drag == true end
-- the state of one row, kept across rebuilds of the page (key: the page and the row)
function HV.XS.state(key)
    local s = HV.XS.st[key]
    if not s then s = {}; HV.XS.st[key] = s end
    return s
end
-- where the row is drawn now (px from its first card): at rest its target; gliding towards a new one; held by a drag
function HV.XS.pos(st, target)
    if st.drag then st.last = st.drag.sx; return st.last end
    if not (HV.XS.on() and HV.anim_on()) then st.last, st.g = target, nil; return target end
    local now = U.now_s()
    if st.last == nil then st.last = target end
    if (st.g and st.g.to ~= target) or (not st.g and math.abs(st.last - target) > 0.5) then
        st.g = { from = st.last, to = target, t0 = now }
        HV.XA.frames("xs_glide", HV.XS.DUR)
        -- the frame at rest is drawn for certain (a busy mpv can skip the glide's last frames; nothing else would draw it)
        local g0 = st.g
        mp.add_timeout(HV.XS.DUR + 0.08, function()
            if st.g == g0 and browser_active then HV.last_data = nil; render() end
        end)
    end
    local g = st.g
    if g then
        local k = (now - g.t0) / HV.XS.DUR
        if k >= 1 then st.g = nil; st.last = target; return target end
        st.last = g.from + (target - g.from) * HV.ease(k)
        return st.last
    end
    st.last = target
    return target
end
function HV.XS.moving(st) return st ~= nil and (st.drag ~= nil or st.g ~= nil) end
-- past an end: the further you pull, the less it follows (never more than half a card)
function HV.XS.rubber(d, step) return d * 0.5 / (1 + d / step) end
-- a press on a row that can scroll: a drag starts once the pointer has moved 8 px sideways, else it is a click.
-- p = { st, sx0, maxs, step, click = fn, settle = fn(n) }
function HV.XS.press(p, mx, my)
    local old = HV.XS.p
    if old then                        -- a press whose release never came (let go outside the window): it ends, no click
        old.click = nil
        HV.XS.release()
    end
    p.x0, p.y0 = mx, my
    p.samples = { { U.now_s(), p.sx0 } }
    p.st.g = nil                       -- a row still gliding stops where it is drawn: it is in your hand now
    p.st.last = p.sx0
    HV.XS.p = p
end
-- a pointer move while pressed: true when the row is being dragged (the page is drawn again by the caller)
function HV.XS.move(mx, my)
    local p = HV.XS.p
    if not p then return false end
    local dx, dy = mx - p.x0, my - p.y0
    if not p.dragging then
        if math.abs(dx) < math.max(8, 8 * ((HV.m and HV.m.S) or 1)) then return false end
        if math.abs(dy) > math.abs(dx) * 1.5 then return false end      -- mostly up or down: still a click
        p.dragging = true
        p.x0 = mx                                      -- no jump: it follows from here
        dx = 0
    end
    local sx = p.sx0 - dx
    if sx < 0 then sx = -HV.XS.rubber(-sx, p.step)
    elseif sx > p.maxs then sx = p.maxs + HV.XS.rubber(sx - p.maxs, p.step) end
    p.st.drag = { sx = sx }
    local t = U.now_s()
    p.samples[#p.samples + 1] = { t, sx }
    if #p.samples > 8 then table.remove(p.samples, 1) end
    return true
end
-- the button is let go: a click when it never moved; else the row is flung (its speed over the last 0.1 s) and settles
function HV.XS.release()
    local p = HV.XS.p
    HV.XS.p = nil
    if not p then return false end
    if p.valid and not p.valid() then p.st.drag = nil; return true end      -- the page changed under the press
    if not p.dragging then if p.click then p.click() end return true end
    local sx = p.st.drag and p.st.drag.sx or p.sx0
    p.st.drag, p.st.g = nil, nil
    p.st.last = sx
    local now, v = U.now_s(), 0
    for i = #p.samples, 1, -1 do
        local s = p.samples[i]
        if now - s[1] > 0.1 or i == 1 then
            if now - s[1] > 0.005 then v = (sx - s[2]) / (now - s[1]) end
            break
        end
    end
    local target = math.max(0, math.min(p.maxs, sx + v * 0.18))
    p.settle(math.floor(target / p.step + 0.5))
    HV.XS.drag_t = now
    return true
end
-- a picture partly off the screen's sides: what of it mpv is handed (x, source offset add, source width, width) or nil
function HV.XS.hclip(x, w, fw, W)
    local lc, rc = (x < 0) and -x or 0, (x + w > W) and (x + w - W) or 0
    if lc == 0 and rc == 0 then return x, 0, fw, w end
    local vw = w - lc - rc
    if vw < 2 then return nil end
    local s0 = math.floor(lc * fw / w)
    local sw = math.max(1, math.min(fw - s0, math.floor(vw * fw / w + 0.5)))
    return x + lc, s0 * 4, sw, vw
end

-- ---- page transitions, the way Netflix does them: the picture you chose moves, the page fades ----
-- Opening a title: its poster grows out of the card you pressed into its place on the title page while the page
-- fades in behind it. Play: the card swells a little as the screen fades to black, then "Starting ..." until the video
-- is there (a failed start brings the page back). Pictures cannot fade in mpv, so they move and scale (overlay-add's
-- dw / dh, mpv 0.38+) and everything else waits until they have arrived. Off with transitions=no.
HV.TR = { id = 63, st = nil, disp = {} }
HV.TR.OPEN, HV.TR.PLAY, HV.TR.BACK = 0.30, 0.26, 0.24
-- transition_style=zoom (the default): after the poster has arrived the backdrop settles in (a slow Ken Burns), the
-- title page's lines fade in one after another and the rows of cards follow, top to bottom; Back flies the poster
-- home into its card. fade = only the poster flight and the fade (v25).
function HV.zoom() return tostring(o.transition_style or "zoom"):lower() ~= "fade" end
function HV.TR.on() return o.transitions and HV.motion_ok() and HV.dw_ok() and not MS.debug end
-- true while the transition owns the screen: the page's own pictures stay down
function HV.TR.busy() return HV.TR.st ~= nil end
-- the picture the selected card shows right now: { f, fw, fh, x, y, w, h } or nil
function HV.TR.from_selected()
    local sel = HV.selected()
    if not sel then return nil end
    for _, vc in ipairs(HV.vis_cards or {}) do
        if vc.card == sel and vc.ri == HV.r then
            local d = HV.TR.disp[vc.uid]
            if d and d.f and d.vh == d.h then return d end
        end
    end
    return nil
end
function HV.TR.start(kind, from, extra)
    local T = HV.TR
    T.st = { kind = kind, from = from, t0 = U.now_s(), dur = (kind == "open" and T.OPEN) or (kind == "back" and T.BACK) or T.PLAY, mode = HV.mode }
    for k, v in pairs(extra or {}) do T.st[k] = v end
    if kind == "open" then HV.A.enter_dur = T.OPEN end
    if kind == "back" then HV.A.enter_dur = T.BACK end
    HV.anim_kick(T.st.dur + 0.05)
end
function HV.TR.stop(quiet)
    local T = HV.TR
    if not T.st then return end
    local was = T.st.kind
    T.st = nil
    if was == "open" and not quiet and HV.zoom() and HV.mode == "title" then HV.REV = { t0 = U.now_s() }; HV.anim_kick(HV.REV_DUR) end
    HV.A.enter_dur = nil
    HV.cmd_drop("tr")
    if not quiet and browser_active and MS.view == "home" then
        -- the page's own pictures first, then the moving one goes - in that order, so no frame shows neither
        HV.sig, HV.last_data = nil, nil
        render()
        HV.cmd({ "overlay-remove", tostring(T.id) }, nil, "tr")
        HV.flush()
    else
        mp.command_native_async({ "overlay-remove", tostring(T.id) }, function() end)
    end
end
-- one frame of the moving picture (called from every render and every animation frame)
function HV.TR.frame(direct)
    local T = HV.TR
    local st = T.st
    if not st then return end
    if not browser_active then T.stop(true); return end
    local now = U.now_s()
    local k = math.min(1, (now - st.t0) / st.dur)
    local e = HV.ease(k)
    local f = st.from
    local x, y, w, h
    if st.kind == "open" then
        local to = HV.hero
        if HV.mode ~= "title" or not to then T.stop(); return end
        x, y = f.x + (to.x - f.x) * e, f.y + (to.y - f.y) * e
        w, h = f.w + (to.dw - f.w) * e, f.h + (to.dh - f.h) * e
        if k >= 1 then T.stop(); return end
    elseif st.kind == "back" then
        -- the title page's poster flies home into its card (found once the home page has been laid out)
        if HV.mode == "title" or HV.mode == "add" then T.stop(); return end
        local to = nil
        for _, vc in ipairs(HV.vis_cards or {}) do
            if vc.card and vc.card.key == f.key and vc.ri == HV.r then to = vc; break end
        end
        if not to then if k >= 1 then T.stop() end return end
        x, y = f.x + (to.x - f.x) * e, f.y + (to.y - f.y) * e
        w, h = f.w + (to.w - f.w) * e, f.h + (to.h - f.h) * e
        if k >= 1 then T.stop(); return end
    else
        if HV.mode ~= st.mode then T.stop(); return end      -- Esc / Back while it starts: the page is shown again
        if k >= 1 then
            if not st.gone then st.gone = true; mp.command_native_async({ "overlay-remove", tostring(T.id) }, function() end) end
            -- a start that never comes (no answer, an error the page does not hear of) gives the page back
            if now - st.t0 > 25 then T.stop() end
            return
        end
        local g = 1 + 0.08 * e
        w, h = f.w * g, f.h * g
        x, y = f.x - (w - f.w) / 2, f.y - (h - f.h) / 2
    end
    local args = { name = "overlay-add", id = T.id, x = math.floor(x + 0.5), y = math.floor(y + 0.5), file = f.f, offset = 0,
             fmt = "bgra", w = f.fw, h = f.fh, stride = f.fw * 4, dw = math.max(2, math.floor(w + 0.5)), dh = math.max(2, math.floor(h + 0.5)) }
    if direct then HV.cmd_drop("tr"); mp.command_native_async(args, function() end) else HV.cmd(args, nil, "tr") end
end
-- what the black screen says while the video starts
function HV.TR.fx(ev, now)
    local st = HV.TR.st
    if not st or st.kind ~= "play" then return end
    local ww, wh = U.canvas_size()
    local k = HV.ease((now - st.t0) / st.dur)
    ev[#ev + 1] = D.ev_rect(0, 0, ww, wh, "000000", math.floor(k * 100), nil, 0, 0)
    if now - st.t0 > st.dur then
        local S = wh / 1080
        local fs = math.max(14, math.floor(20 * S))
        local dots = {}
        for i = 1, 3 do
            local a = 0.35 + 0.65 * (0.5 + 0.5 * math.sin(now * 5 - i * 0.9))
            dots[#dots + 1] = string.format("{\\1a%s}●", U.ass_alpha(a * 90))
        end
        ev[#ev + 1] = D.ev_text(ww / 2, wh / 2 - fs, 5, string.format("\\fs%d\\c&HFFFFFF&\\fsp%d", math.floor(fs * 0.7), math.floor(fs * 0.4)), table.concat(dots))
        ev[#ev + 1] = D.ev_text(ww / 2, wh / 2 + fs * 0.6, 5, string.format("\\fs%d\\c&HFFFFFF&\\1a%s", fs, U.ass_alpha(70)),
            U.ass_escape(U.fit_text(st.title and ("Starting " .. st.title) or "Starting", ww * 0.8, fs)))
    end
end
mp.register_event("end-file", function(ev)
    if ev.reason == "error" and HV.TR.st and HV.TR.st.kind == "play" then HV.TR.stop() end
end)

-- the last few window sizes (one per size step), remembered across restarts: their pictures are kept
function HV.note_layout(w, h)
    local path = PS.dir() .. "/layouts.json"
    if not HV.recent then
        local d = try_load_json(path)
        HV.recent = type(d) == "table" and d or {}
    end
    local sig = HV.step_sig(w, h)
    if HV.recent[1] and HV.recent[1].sig == sig then return end
    local out = { { w = w, h = h, sig = sig } }
    for _, l in ipairs(HV.recent) do
        if type(l) == "table" and l.sig ~= sig and tonumber(l.w) and tonumber(l.h) and #out < 3 then out[#out + 1] = l end
    end
    HV.recent = out
    pcall(atomic_write, path, safe_json(out) or "[]")
end
-- true while the window size changed in the last `secs` (and a render is due when that has passed)
function HV.size_moving(secs)
    if not HV.resize_t or mp.get_time() - HV.resize_t >= secs then return false end
    if not HV.settle_timer then
        HV.settle_timer = mp.add_timeout(secs - (mp.get_time() - HV.resize_t) + 0.05, function()
            HV.settle_timer = nil
            if browser_active then HV.sig, HV.last_data = nil, nil; render() end
        end)
    end
    return true
end
function HV.prune_bgra()
    if HV.pruned or not PS.enabled() then return end
    if HV.size_moving(2) then return end         -- only a size kept for a while counts (a drag passes many steps)
    HV.pruned = true
    local keep = {}
    local saved = HV.mode
    local saved_multi = TV.multi
    local cw0, ch0 = U.canvas_size()
    HV.note_layout(cw0, ch0)
    for _, lay in ipairs(HV.recent) do
    for _, md in ipairs({ "home", "title" }) do
        HV.mode = md
        TV.multi = false
        local m = HV.metrics(tonumber(lay.w), tonumber(lay.h))
        for _, d in ipairs({ m, m.L }) do
            keep[d.sk] = true
            if d.gsk then keep[d.gsk] = true end
        end
        if md == "title" then
            local hw, hh = TV.hero_size(m); keep[HV.skey(hw, hh)] = true
            local bw, bh = TV.backdrop_size(m); keep[HV.skey(bw, bh, HV.FADE_KEY)] = true
        end
        local nw, nh = HV.next_card_size(m.h); keep[HV.skey(nw, nh)] = true
        local aw, ah = HV.AX.poster_size(m); keep[HV.skey(aw, ah)] = true      -- the add screen's result posters
        local cw_, ch_ = HV.AX.home_card_size(m); keep[HV.skey(cw_, ch_)] = true  -- and its home rows
    end
    end
    HV.mode, TV.multi = saved, saved_multi
    HV.metrics()                      -- the current window's card radius again (HV.R; it is part of the size keys)
    local dir = PS.dir()
    local list = utils.readdir(dir, "all")          -- names only: nothing is opened to find out what to delete
    if type(list) ~= "table" then return end
    local gone = {}
    for _, f in ipairs(list) do
        local dims = f:match("_(%d+x%d+[%w%.]*)%.bgra$")
        if dims and not keep[dims] then
            if pcall(os.remove, dir .. "/" .. f) then gone[dir .. "/" .. f] = true end
        end
    end
    -- the pictures in memory that pointed at deleted files are converted again when they are needed
    local function forget(st)
        if type(st) ~= "table" or type(st.bgra) ~= "table" then return end
        for k, v in pairs(st.bgra) do if gone[v] then st.bgra[k] = nil; if st.cq then st.cq[k] = nil end end end
    end
    for _, st in pairs(HV.items or {}) do forget(st) end
    for _, st in pairs(HV.AX.imgs or {}) do forget(st) end
    PS.st_dirty = true
    HV.age_out()
end
-- 26.10: pictures used to be scaled to the card's exact shape, so one of another shape was stretched (a 4:3 still, a
-- poster standing in for a 16:9 picture). Now they are cropped to fill. The wide ones converted before (stills,
-- backdrops, their blurred stand-ins) are removed once and made again from the kept downloads when next shown.
function HV.crop_migrate()
    if not PS.enabled() then return end
    local dir = PS.dir()
    local mark = dir .. "/crop_v2610"
    if utils.file_info(mark) or not utils.file_info(dir) then return end
    local n = 0
    for _, f in ipairs(utils.readdir(dir, "files") or {}) do
        if not f:match("^lg") then
            local w, h = f:match("_(%d+)x(%d+)[^_]*%.bgra$")
            if not w then w, h = f:match("_t(%d+)x(%d+)%.tiny$") end
            w, h = tonumber(w), tonumber(h)
            if w and h and w > h and os.remove(dir .. "/" .. f) then n = n + 1; PS.fsz[f] = nil end
        end
    end
    local fh = io.open(mark, "wb"); if fh then fh:write("26.10\n"); fh:close() end
    if n > 0 then PS.st_dirty = true; msg.info(string.format("artwork: %d wide pictures will be made again (cropped, not stretched)", n)) end
end
-- cache_max_age_days: episode stills, season posters and backdrops not refreshed for that many days are deleted (they come
-- back from TMDB when shown again). Once a day at most, a few files per step, so it never holds anything up.
function HV.age_out()
    local days = tonumber(o.cache_max_age_days) or 0
    if days <= 0 or HV.aging then return end
    local mark = PS.dir() .. "/aged.txt"
    local mi = utils.file_info(mark)
    if mi and os.time() - (mi.mtime or 0) < 86400 then return end
    local f = io.open(mark, "wb"); if f then f:write(tostring(os.time())); f:close() end
    local dir = PS.dir()
    -- pictures this session has loaded (the page, Continue Watching, the cards) are kept: their states point at the files
    local used = {}
    for _, tbl in ipairs({ HV.items or {}, HV.AX.imgs or {} }) do
        for _, st in pairs(tbl) do if type(st) == "table" and st.base then used[st.base] = true end end
    end
    local names = {}
    for _, n in ipairs(utils.readdir(dir, "all") or {}) do
        -- stills "s<id>_<s>_<e>", season posters "sp<id>_<s>", backdrops "b<id>" - posters and logos are kept
        local base = n:match("^(.-)_t?%d+x%d+") or n:match("^(.-)_[%w]+%.jpg$")
        if (n:match("^s%d") or n:match("^sp%d") or n:match("^b%d") or n:match("^bc%d")) and (n:match("%.jpg$") or n:match("%.bgra$") or n:match("%.tiny$"))
            and not (base and used[base]) then
            names[#names + 1] = n
        end
    end
    if #names == 0 then return end
    HV.aging = true
    local cut, i, gone = os.time() - days * 86400, 0, 0
    local function step()
        for _ = 1, 150 do
            i = i + 1
            local n = names[i]
            if not n then
                HV.aging = nil
                if gone > 0 then PS.st_dirty = true; msg.info(string.format("artwork cache: %d old files removed (cache_max_age_days=%d)", gone, days)) end
                return
            end
            local inf = utils.file_info(dir .. "/" .. n)
            if inf and (inf.mtime or os.time()) < cut and os.remove(dir .. "/" .. n) then
                gone = gone + 1
                PS.fsz[n], HV.fsz[dir .. "/" .. n] = nil, nil
            end
        end
        mp.add_timeout(0.05, step)
    end
    step()
end

-- ---- background work for the page ----
function TV.ensure_season(show, s)
    if not (show and show.id and s) then return end
    PS.load_eps()
    local key = show.id .. ":" .. s
    TV.season_checked = TV.season_checked or {}
    if TV.season_checked[key] then return end
    local refresh = PS.eps[key] ~= nil and PS.eps_stale(PS.eps[key])
    if (PS.eps[key] ~= nil and not refresh) then TV.season_checked[key] = true; return end
    if TV.season_busy and TV.season_busy[key] then return end
    if TV.sn >= 4 then return end
    if refresh then TV.season_checked[key] = true end       -- one refresh per season per session
    TV.season_busy = TV.season_busy or {}
    TV.season_busy[key] = true
    TV.sn = TV.sn + 1
    PS.season(show, s, function(err)
        TV.sn = TV.sn - 1
        if err then   -- network trouble: allow a retry after a while, nothing is stored
            mp.add_timeout(30, function() if TV.season_busy then TV.season_busy[key] = nil end end)
        elseif TV.season_busy then
            TV.season_busy[key] = nil
        end
        HV.kick()
    end, refresh)
end

function TV.ensure_details()
    local e = TV.show_entry()
    if not e or (e.detail and (e.kind == "movie" or e.sp ~= nil) and e.gen ~= nil) then return end
    if TV.det_busy == e.id then return end
    TV.det_busy = e.id
    local u0 = PS.U_ctx
    PS.U_ctx = true                -- the open title page's own details
    PS.details(e, function() HV.kick() end)
    PS.U_ctx = u0
end

function TV.pump_still(w, st, m)
    if st.state == "new" then
        if HV.dn >= 12 then return end
        local sp = w.still
        st.base = sp.base
        st.jpg = PS.jpg_for(sp.base, sp.size)
        st.state = "downloading"
        HV.dn = HV.dn + 1
        PS.fetch_image(sp.size, sp.path, st.jpg, function(ok)
            HV.dn = HV.dn - 1
            if ok then st.state = "jpg"; PS.st_dirty = true
            else st.state, st.t, st.err = "error", mp.get_time(), "still download failed" end
            HV.kick()
        end)
    elseif st.state == "jpg" then
        HV.want_bgra(st, w.dw or m.cw, w.dh or m.ch, w.fade)
    end
end

-- ---- a title page with nothing to show: one floating card that says exactly why, and what you can do ----
-- (still loading, Real-Debrid removed the files and why, WebDAV can't list the folder, or the folder is simply empty)
function TV.empty_info()
    local info = { eyebrow = "WEBDAV", keys = {} }
    local function key(k, label, act) info.keys[#info.keys + 1] = { k = k, label = label, act = act } end
    if #(TV.failed or {}) > 0 then
        local f = TV.failed[1]
        info.title, info.tone = "Couldn't load this title's folder", "bad"
        info.line = tostring(f.err or "no answer") .. ((#TV.failed > 1) and string.format("  (and %d more)", #TV.failed - 1) or "")
        key(U.kname("refresh"), "Retry", function() HV.refresh() end)
        key(U.kname("doctor"), "Setup check", function() HV.DR.show() end)
        return info
    end
    if (TV.loading or 0) > 0 then
        info.title, info.tone, info.line, info.spin = "Loading…", "muted", "Asking WebDAV what this folder holds", true
        return info
    end
    local rdm = TV.last_rdm
    -- files really on their way: the folder grew a moment ago, or Real-Debrid named one that is still downloading or
    -- is fine but not on WebDAV yet. Links still being checked are not that (they are usually gone): while Real-Debrid
    -- is asked, ONE card says so and then turns into the answer (it used to say "Nothing to play here", then "still
    -- adding the files", then "isn't available")
    local coming = TV.grow_t ~= nil and os.time() - TV.grow_t < 5
    for _, x in ipairs(rdm or {}) do if not x.final and x.reason ~= "Checking Real-Debrid…" then coming = true break end end
    if TV.loading_links and coming then
        info.eyebrow, info.tone = "REAL-DEBRID", "warn"
        info.title = "Real-Debrid is still adding the files"
        if (TV.rd_want or 0) > 0 then
            info.line = string.format("%d of %d ready on WebDAV  ·  this page fills in by itself", TV.rd_have or 0, TV.rd_want)
            info.frac = (TV.rd_have or 0) / math.max(1, TV.rd_want)
        else info.line, info.spin = "This page fills in by itself as they arrive", true end
        return info
    end
    if TV.rd_state == "loading" or TV.rd_state == "checking" or TV.loading_links then
        info.eyebrow, info.tone, info.spin = "REAL-DEBRID", "muted", true
        info.title = "Checking Real-Debrid…"
        info.line = "Asking Real-Debrid about this title's files"
        return info
    end
    if rdm and #rdm > 0 then
        info.eyebrow, info.tone = "REAL-DEBRID", "bad"
        local why, order = {}, {}
        for _, x in ipairs(rdm) do
            local r = TV.reason_text(x)
            if not why[r] then why[r] = 0; order[#order + 1] = r end
            why[r] = why[r] + 1
        end
        table.sort(order, function(a, b) return why[a] > why[b] end)
        info.title = (#rdm == 1) and "This file isn't available" or string.format("These %d files aren't available", #rdm)
        local parts = {}
        for i = 1, math.min(2, #order) do parts[#parts + 1] = order[i] .. ((#order > 1) and string.format(" (%d)", why[order[i]]) or "") end
        info.line = "Real-Debrid: " .. table.concat(parts, "  ·  ")
        -- the torrent behind it can be streamed with rqbit instead - unless nobody is sharing it
        local rel = nil
        for _, f in ipairs(TV.card.folders or {}) do
            local rec = PS.rd_folder(f.name)
            local d = rec.state == "ready" and rec.data or nil
            if d and d.hash and d.hash ~= "" then
                rel = { hash = tostring(d.hash):lower(), title = TV.card.shown or TV.card.title, folder = f.name, seeds = tonumber(d.seeders) }
                break
            end
        end
        key(U.kname("refresh"), "Retry", function() HV.refresh() end)
        key(U.knice(tostring(o.add_key or "n"):match("[^%s,]+") or "n"), "Find another release", function() HV.AX.open() end)
        if rel and HV.AX.t_on() then
            if rel.seeds == 0 then
                info.sub = "The torrent has no seeders right now, so it can't be streamed instead either"
            else
                TV.empty_rel = rel
                key(U.kname("refetch_art"), "Stream as a torrent", function() TV.stream_empty() end)
            end
        end
        key(U.kname("doctor"), "Setup check", function() HV.DR.show() end)
        return info
    end
    info.tone = "muted"
    info.title = "Nothing to play here"
    if TV.rd_state == "off" then
        info.line = "WebDAV lists no video files in this folder  ·  add rd_api_token to the conf to see Real-Debrid's reason"
    else
        info.line = "WebDAV lists no video files in this folder"
    end
    key(U.kname("refresh"), "Refresh", function() HV.refresh() end)
    key(U.knice(tostring(o.add_key or "n"):match("[^%s,]+") or "n"), "Find a release", function() HV.AX.open() end)
    return info
end
-- T on that card: the release's torrent through rqbit (the add screen's streaming)
function TV.stream_empty()
    local rel = TV.empty_rel
    if not rel then return false end
    HV.AX.open()
    if HV.mode == "add" then HV.AX.torrent(rel) end
    return true
end
function TV.draw_empty(add, m)
    TV.empty_rel = nil
    local info = TV.empty_info()
    local w, h, lfs, S = m.w, m.h, m.lfs, m.S
    local top = HV.rows_y(m)
    local bottom = h - m.foot_h
    local cw = math.floor(math.min(w - 2 * m.mx, 760 * S * (tonumber(o.ui_scale) or 1)))
    local pad = math.floor(lfs * 1.3)
    local fs_e, fs_t, fs_l = math.max(10, lfs - 7), lfs + 5, lfs - 1
    local lines = TV.wrap(info.line or "", cw - 2 * pad, fs_l, 2)
    local bh = math.floor(lfs * 1.7)
    local ch = pad + fs_e + lfs * 0.7 + fs_t + lfs * 0.6 + #lines * fs_l * 1.35 + (info.sub and fs_l * 1.5 or 0)
        + ((info.frac or info.spin) and lfs * 1.0 or 0) + (#info.keys > 0 and (lfs * 0.9 + bh) or 0) + pad
    local x1 = math.floor((w - cw) / 2)
    local y1 = math.floor(top + math.max(0, (bottom - top - ch) / 2.2))
    local x2, y2 = x1 + cw, y1 + ch
    HV.gcard(add, x1, y1, x2, y2, m)
    local tone = (info.tone == "bad" and THEME.bad) or (info.tone == "warn" and THEME.warn) or THEME.text_muted
    local fsp = math.max(1, math.floor(S + 0.5))
    local y = y1 + pad
    -- a small dot in the tone, then the source
    local dot = math.max(3, math.floor(lfs * 0.22))
    add(D.ev_rect(x1 + pad, y + fs_e / 2 - dot, x1 + pad + dot * 2, y + fs_e / 2 + dot, tone, 100, nil, 0, 0, dot))
    add(D.ev_text(x1 + pad + dot * 2 + math.floor(lfs * 0.45), y + fs_e / 2, 4, string.format("\\b1\\fs%d\\fsp%d\\c%s", fs_e, fsp, U.ass_color(THEME.text_muted)),
        U.ass_escape(info.eyebrow or "")))
    y = y + fs_e + lfs * 0.7
    add(D.ev_text(x1 + pad, y + fs_t / 2, 4, string.format("\\b1\\fs%d\\c%s", fs_t, U.ass_color(THEME.text_primary)), U.ass_escape(HV.ell(info.title or "", cw - 2 * pad, fs_t, true))))
    y = y + fs_t + lfs * 0.6
    for _, ln in ipairs(lines) do
        add(D.ev_text(x1 + pad, y + fs_l / 2, 4, string.format("\\fs%d\\c%s", fs_l, U.ass_color(info.tone == "muted" and THEME.text_muted or tone)), U.ass_escape(ln)))
        y = y + fs_l * 1.35
    end
    if info.sub then
        add(D.ev_text(x1 + pad, y + fs_l * 0.6, 4, string.format("\\fs%d\\c%s", fs_l - 1, U.ass_color(THEME.text_dim)), U.ass_escape(HV.ell(info.sub, cw - 2 * pad, fs_l - 1))))
        y = y + fs_l * 1.5
    end
    if info.frac or info.spin then
        local bt = math.max(3, math.floor(4 * S + 0.5))
        local by = y + lfs * 0.35
        add(D.ev_rect(x1 + pad, by, x2 - pad, by + bt, THEME.track, 100, nil, 0, 0, bt / 2))
        if info.frac then
            add(D.ev_rect(x1 + pad, by, x1 + pad + math.max(bt * 2, (cw - 2 * pad) * math.min(1, info.frac)), by + bt, THEME.accent, 100, nil, 0, 0, bt / 2))
        else
            HV.FX.shim[#HV.FX.shim + 1] = { x1 + pad, by, cw - 2 * pad, bt }       -- a sweep while nothing can be counted
            HV.A.shimmer_seen = true
        end
        y = y + lfs * 1.0
    end
    if #info.keys > 0 then
        y = y + lfs * 0.9
        local bx = x1 + pad
        local fsb = math.max(11, lfs - 2)
        for _, k in ipairs(info.keys) do
            local tw1 = HV.AX.tw(k.k, fsb, true)
            local tw2 = HV.AX.tw(k.label, fsb)
            local bw = math.floor(tw1 + tw2 + fsb * 2.2)
            if bx + bw > x2 - pad then break end
            local hot = HV.btn_hover == k.label
            HV.gpill(add, bx, y, bx + bw, y + bh, m, nil, nil, hot)
            add(D.ev_text(bx + fsb * 0.9, y + bh / 2, 4, string.format("\\fs%d", fsb),
                string.format("{\\b1\\c%s}%s {\\b0\\c%s}%s", U.ass_color(THEME.text_primary), U.ass_escape(k.k), U.ass_color(THEME.text_muted), U.ass_escape(k.label))))
            HV.links[#HV.links + 1] = { x1 = bx, x2 = bx + bw, y1 = y, y2 = y + bh, act = k.act, hov = k.label }
            bx = bx + bw + math.floor(lfs * 0.6)
        end
    end
end

-- ---- hero (poster + title + overview) ----
function TV.hero_size(m)
    local hh = m.hero_h - 20
    return math.floor(hh * 2 / 3), hh
end

-- Experimental backdrop: the whole hero band's height, flush with the right edge, beside (never behind) the text.
function TV.backdrop_size(m)
    local bh = m.hero_h
    return math.min(math.floor(bh * 16 / 9), math.floor((m.ws or m.w) * 0.5)), bh
end

function TV.wrap(text, maxw, fs, maxlines)
    local words = {}
    for wd in tostring(text):gmatch("%S+") do words[#words + 1] = wd end
    local lines, cur = {}, ""
    local i = 1
    while i <= #words do
        local try = (cur == "") and words[i] or (cur .. " " .. words[i])
        if cur == "" or U.utf8_len(try) * fs * 0.55 <= maxw then cur = try; i = i + 1
        else
            lines[#lines + 1] = cur; cur = ""
            if #lines >= maxlines then break end
        end
    end
    if cur ~= "" and #lines < maxlines then lines[#lines + 1] = cur
    elseif i <= #words and #lines >= maxlines then lines[#lines] = U.fit_text(lines[#lines] .. " " .. table.concat(words, " ", i), maxw, fs) end
    return lines
end

-- The next episode to play from the title page's Play button: the one you are in the middle of, else the one after the
-- last you watched, else the first. returns ep, "resume" | "next" | "start" | "again"
function TV.next_up()
    local eps = TV.ordered or {}
    if #eps == 0 then return nil end
    local best, bt = nil, -1
    local min = tonumber(o.resume_min_secs) or 15
    for _, ep in ipairs(eps) do
        local hst = watch_history[ep.entry.href]
        if hst and hst.pos and (hst.duration or 0) > 0 and hst.pos >= min and not watched_set[ep.entry.href] then
            local t = tonumber(hst.last_played) or 0
            if t > bt then best, bt = ep, t end
        end
    end
    if best then return best, "resume" end
    local last = 0
    for i, ep in ipairs(eps) do if watched_set[ep.entry.href] then last = i end end
    if eps[last + 1] then return eps[last + 1], (last > 0) and "next" or "start" end
    return eps[1], "again"
end
-- Play: the card of that episode is selected and opened (so the play transition starts from it); seasons view: directly
function TV.play_next()
    local ep = TV.next_up()
    if not ep then return end
    for ri, row in ipairs(HV.rows or {}) do
        for ci, c in ipairs(row.cards) do
            if c.kind == "ep" and c.entry and c.entry.href == ep.entry.href then
                HV.r, HV.c, HV.bfocus = ri, ci, nil
                HV.fix_off(HV.m or HV.metrics())
                return HV.activate()
            end
        end
    end
    TV.play({ entry = ep.entry, ep = ep })
end
-- + Queue: everything from the next episode on goes after what is playing
function TV.queue_all()
    local ep = TV.next_up()
    local go = false
    local n = 0
    for _, e in ipairs(TV.ordered or {}) do
        if e == ep then go = true end
        if go then play_entry(e.entry, true); n = n + 1 end
    end
    if n > 0 then HV.TS.show({ eyebrow = "QUEUE", title = TV.card.shown or TV.card.title, extra = string.format("%d file%s added", n, n == 1 and "" or "s") }, 3) end
end
-- ✓ Watched: the whole title (or back to unwatched when it already all is)
function TV.all_watched()
    local eps = TV.ordered or {}
    if #eps == 0 then return false end
    for _, ep in ipairs(eps) do if not watched_set[ep.entry.href] then return false end end
    return true
end
function TV.toggle_all_watched()
    local all = TV.all_watched()
    for _, ep in ipairs(TV.ordered or {}) do
        local h = ep.entry.href
        if all then watched_set[h] = nil else watched_set[h] = os.time(); watch_history[h] = nil end
    end
    mark_continue_dirty()
    save_persistence()
    HV.sig = nil
    render()
end
-- Find more: the add screen, searching this title
function TV.find_more()
    local q = (TV.show_entry() or {}).name or TV.card.title
    HV.AX.open()
    if HV.mode ~= "add" then return end
    local AX = HV.AX
    AX.q, AX.qc, AX.fedit = q, #q, false
    AX.search()
end
-- ↓ Download: the title's download page (pick the files, see them arrive)
function TV.download() TV.dl_open() end
-- the button row of the title page (also reached with ↑ from the first row of cards)
function TV.buttons()
    local out = {}
    local ep, how = TV.next_up()
    if ep then
        local tag = (ep.e and not TV.allmovie) and string.format("S%02dE%02d", tonumber(ep.s) or 1, ep.e) or nil
        local word = (how == "resume") and "Resume" or ((how == "again") and "Play again" or "Play")
        out[#out + 1] = { id = "play", label = "▶  " .. word .. (tag and ("  " .. tag) or ""), act = TV.play_next, primary = true }
        out[#out + 1] = { id = "queue", label = "+  Queue", act = TV.queue_all }
        out[#out + 1] = { id = "watched", label = TV.all_watched() and "✓  Watched" or "✓  Mark watched", act = TV.toggle_all_watched }
    end
    if HV.AX.enabled() then out[#out + 1] = { id = "find", label = "Find more", act = TV.find_more } end
    local tki = HV.TK.on() and HV.TK.show_info()
    if tki then
        out[#out + 1] = { id = "track", label = HV.TK.has(tki.kind, tki.id) and "✓  Tracking" or "+  Track", act = HV.TK.toggle_tv }
    end
    if ep then
        local DL = HV.DL
        local mine = HV.DL.has(TV.card.key)
        local p = HV.DL.busy(TV.card.key) and HV.DL.progress()
        local label = (mine and DL.paused) and "↓  Paused" or (p and ("↓  Downloading " .. p)) or "↓  Download"
        out[#out + 1] = { id = "dl", label = label, act = TV.download }
        if mine then
            out[#out + 1] = { id = "dlpause", label = DL.paused and "▶  Resume" or "❚❚  Pause",
                act = function() if DL.paused then DL.resume() else DL.pause() end; HV.sig, HV.last_data = nil, nil; render() end }
        end
    end
    return out
end

function TV.draw_hero(add, m)
    local card, lfs, w = TV.card, m.lfs, m.w
    local hw, hh = TV.hero_size(m)
    local with_poster = o.hero_poster ~= false
    local x0, y0 = m.mx, m.top_h + 10
    local st = HV.items[card.key]
    if with_poster then
        local ready = st and st.bgra[HV.skey(hw, hh)] and not MS.debug
        HV.hero = { key = card.key, x = x0, y = y0, dw = hw, dh = hh }
        if not ready then
            add(D.ev_rect(x0, y0, x0 + hw, y0 + hh, THEME.bg_panel, 100, nil, 0, 0, HV.R or 6))
            add(D.ev_text(x0 + hw / 2, y0 + hh / 2, 5, string.format("\\fs%d\\c%s", lfs, U.ass_color(THEME.text_dim)), PS.enabled() and "…" or ""))
        end
    end
    local show = TV.show_entry()
    local tx = with_poster and (x0 + hw + math.floor(lfs * 1.4)) or x0
    local maxw = w - tx - m.mx
    HV.backdrop = nil
    if o.experimental_backdrop and show and (show.backdrop_path or "") ~= "" and not MS.debug and HV.conv_mode() ~= "magick" then
        local bw, bh = TV.backdrop_size(m)
        local bx = w - bw
        if bx - tx > w * 0.3 then          -- only when enough room is left for the text
            local key = "bdhero:" .. PS.aid(show)
            HV.backdrop = { key = key, x = bx, y = m.top_h, dw = bw, dh = bh, sk = HV.skey(bw, bh, HV.FADE_KEY) }
            HV.wanted[#HV.wanted + 1] = { key = key, dw = bw, dh = bh, fade = HV.FADE_KEY, pri = -1,
                still = { size = HV.img_size("backdrop", bw), path = show.backdrop_path, base = "b" .. PS.aid(show) } }
            maxw = bx - tx - lfs
        end
    end
    local tfs, gfs, sfs = lfs + 14, lfs - 1, lfs - 2
    HV.XV.wash(add, m, st, tx - lfs * 2, y0, math.min(w - m.mx, tx + maxw + lfs * 2), y0 + hh)
    -- the show's logo (experimental_title_logo) stands in for the title text once it is on disk
    local logo_f, logo_w, logo_h = HV.XV.logo(show, math.min(maxw * 0.6, 440 * m.S), tfs * 2.3)
    HV.logo = nil
    -- ---- what is shown, measured first so the block sits centred beside the poster ----
    -- meta: ★ 8.5 · 2025–2026 · 24 min, then outlined chips (quality, age rating), then the status
    local meta = {}
    if show and show.vote and show.vote > 0 then meta[#meta + 1] = { t = string.format("★ %.1f", show.vote), c = THEME.star } end
    local year = (show and show.year ~= "" and show.year) or card.year
    if year and year ~= "" then
        local y2 = show and show.yr2 or ""
        meta[#meta + 1] = { t = (y2 ~= "" and y2 ~= year and (show.kind ~= "movie" or show.coll)) and (year .. "–" .. y2) or year, c = THEME.text_primary }
    end
    if show and (show.rt or 0) > 0 then
        local rt = show.rt
        meta[#meta + 1] = { t = (show.kind == "movie" and rt >= 60) and string.format("%dh %02dm", math.floor(rt / 60), rt % 60) or (rt .. " min"), c = THEME.text_muted }
    end
    local chips = {}
    local q, bytes = {}, 0
    for _, ep in ipairs(TV.ordered or {}) do
        bytes = bytes + (tonumber(ep.entry.size) or 0)
        local cp = CT.parse(ep.entry.name)
        for _, ch in ipairs(cp and cp.chips or {}) do q[ch] = (q[ch] or 0) + 1 end
    end
    local ql = {}
    for k in pairs(q) do ql[#ql + 1] = k end
    table.sort(ql, function(a, b) return (HV.RES_RANK[a] or 0) * 1000 + q[a] > (HV.RES_RANK[b] or 0) * 1000 + q[b] end)
    for i = 1, math.min(3, #ql) do chips[#chips + 1] = { t = ql[i], c = CT.chip_color(ql[i]) } end
    if show and show.cert and show.cert ~= "" then chips[#chips + 1] = { t = show.cert, c = THEME.text_primary } end
    local status = (show and show.status and show.status ~= "" and show.kind ~= "movie") and show.status or nil
    -- genres, then what YOU have
    local genres = (show and type(show.gen) == "table" and #show.gen > 0) and table.concat(show.gen, "  ·  ", 1, math.min(3, #show.gen)) or nil
    local L3 = {}
    if TV.count and TV.count > 0 then
        local real = TV.real_seasons or 0
        local tot = show and tonumber(show.neps) or nil
        if TV.allmovie then L3[#L3 + 1] = dp(TV.count .. (TV.count == 1 and " file" or " files"), THEME.text_muted, 9)
        else L3[#L3 + 1] = dp(tot and tot >= TV.count and string.format("You have %d of %d episodes", TV.count, tot) or (TV.count .. " episodes"), THEME.text_muted, 9) end
        if real > 0 then L3[#L3 + 1] = dp(real .. (real == 1 and " season" or " seasons"), THEME.text_muted, 8) end
        if bytes > 0 then L3[#L3 + 1] = dp(U.fmt_bytes(bytes), THEME.text_dim, 1) end
    end
    if TV.loading and TV.loading > 0 then L3[#L3 + 1] = dp(string.format("loading %d folder%s…", TV.loading, TV.loading == 1 and "" or "s"), THEME.text_dim, 3) end
    -- the languages remembered for this show (remember_tracks): what Play will switch to
    local first_ep = TV.ordered and TV.ordered[1] and TV.ordered[1].entry
    local trec = first_ep and o.remember_tracks and MS.tracks[MS.show_key(first_ep.href) or ""] or nil
    if type(trec) == "table" and (trec.a or trec.s) then
        local function nice(l) l = tostring(l or ""); if l:sub(1, 6) == "title:" then return l:sub(7) end; return U.lang_name(l) end
        local bits = {}
        if trec.a then bits[#bits + 1] = "audio " .. nice(trec.a) end
        if trec.s then bits[#bits + 1] = (trec.s == "no") and "no subtitles" or ("subs " .. nice(trec.s)) end
        L3[#L3 + 1] = dp("♪ " .. table.concat(bits, " · "), THEME.text_dim, 4)
    end
    -- a tracked show: its next episode, as the add screen and the Tracked flyout say it
    local tke = show and not show.coll and HV.TK.on() and HV.TK.all()[HV.TK.key(show.kind, show.id)] or nil
    if tke and tke.kind == "tv" then
        local line = HV.TK.next_short(tke)
        if line then L3[#L3 + 1] = dp(line, THEME.good, 7) end
    end
    -- the selected episode (its name, rating, air date) or the show's tagline; then the synopsis
    local sel = (not HV.bfocus) and HV.selected() or nil
    local body, head, tag
    if sel and sel.kind == "ep" and sel.info and HV.mode == "title" then
        local i = sel.info
        local hp = { dp(string.format("S%02dE%02d", tonumber(sel.ts) or 0, tonumber(sel.te) or 0), THEME.accent, 10) }
        if i.n and i.n ~= "" then hp[#hp + 1] = dp(i.n, THEME.text_primary, 9) end
        if i.v and i.v > 0 then hp[#hp + 1] = dp(string.format("★ %.1f", i.v), THEME.star, 8) end
        if i.d and i.d ~= "" then hp[#hp + 1] = dp(i.d, THEME.text_muted, 6) end
        if i.r and i.r > 0 then hp[#hp + 1] = dp(i.r .. " min", THEME.text_muted, 5) end
        head = hp
        body = (i.o and i.o ~= "") and i.o or "No synopsis on TMDB for this episode."
    else
        body = show and show.overview or ""
        if show and show.tag and show.tag ~= "" then tag = show.tag end
    end
    if body == "" and not PS.enabled() then body = "Set tmdb_key in webdav-browser.conf to see descriptions, posters and episode stills." end
    local btns = (HV.mode == "title") and TV.buttons() or {}
    TV.btns = btns
    if HV.bfocus and HV.bfocus > #btns then HV.bfocus = (#btns > 0) and #btns or nil end
    local bh = math.floor(lfs * 2.1)
    local bfs = lfs - 1
    local fail = TV.failed and #TV.failed > 0
    -- heights (in px) of each line, then as many synopsis lines as the space leaves
    local lh = math.floor(lfs * 1.42)
    local fixed = (logo_f and (logo_h + math.floor(lfs * 0.4)) or math.floor(tfs * 1.25)) + lh + (genres and lh or 0) + (#L3 > 0 and lh or 0) + (fail and lh or 0)
        + ((tag or head) and lh or 0) + ((#btns > 0) and (bh + math.floor(lfs * 0.7)) or 0) + (#L3 > 0 and math.floor(lfs * 0.25) or 0)
    local room = (with_poster and hh or m.hero_h - 20) - fixed
    local blines = math.max(1, math.floor(room / math.floor(lfs * 1.35)))
    local lines = (body ~= "") and TV.wrap(body, maxw, lfs, TV.more and 40 or blines) or {}
    local cut = (body ~= "") and #TV.wrap(body, maxw, lfs, 40) > #lines
    TV.more_avail = cut or TV.more
    local total = fixed + #lines * math.floor(lfs * 1.35)
    local y = y0 + math.max(0, math.floor(((with_poster and hh or total) - total) / 2))
    -- where each line went: the zoom transition fades them in one after another (HV.fx_draw)
    TV.hero_lines = {}
    local function mark(y1_, y2_) TV.hero_lines[#TV.hero_lines + 1] = { tx - 6, y1_ - 2, tx + maxw + 6, y2_ + 2 } end
    -- ---- drawing, top to bottom ----
    if logo_f then
        HV.logo = { f = logo_f, x = tx, y = y, w = logo_w, h = logo_h }
        mark(y, y + logo_h + math.floor(lfs * 0.4))
        y = y + logo_h + math.floor(lfs * 0.4)
    else
        local ttl = HV.ell(card.shown or card.title, maxw, tfs, true)
        if HV.mode == "title" then ttl = HV.XA.decode("hero", ttl, 0.7, true, HV.XA.title_n) end
        add(D.ev_text(tx, y + tfs * 0.62, 4, string.format("\\b1\\fs%d\\c%s", tfs, U.ass_color(THEME.text_primary)), U.ass_escape(ttl)))
        mark(y, y + math.floor(tfs * 1.25))
        y = y + math.floor(tfs * 1.25)
    end
    do      -- the meta line with its chips
        local x = tx
        local cy = y + lh / 2
        local sep = string.format("{\\c%s}  ·  ", U.ass_color(THEME.text_dim))
        local parts = {}
        for i, p in ipairs(meta) do parts[#parts + 1] = (i > 1 and sep or "") .. string.format("{\\c%s}%s", U.ass_color(p.c), U.ass_escape(p.t)) end
        local mtxt = table.concat(parts)
        if mtxt ~= "" then
            add(D.ev_text(x, cy, 4, string.format("\\fs%d", lfs), mtxt))
            local plain = {}
            for _, p in ipairs(meta) do plain[#plain + 1] = p.t end
            x = x + HV.AX.tw(table.concat(plain, "  ·  "), lfs) + lfs * 0.8
        end
        local cfs = HV.chip_fs(lfs)
        local chh = math.floor(cfs * 1.7)
        local bw_ = math.max(1, math.floor(m.S + 0.5))
        for _, c in ipairs(chips) do
            local cw = HV.AX.tw(c.t, cfs, true) + cfs * 1.1
            if x + cw > tx + maxw then break end
            add(D.ev_rect(x, cy - chh / 2, x + cw, cy + chh / 2, "FFFFFF", 0, c.c, 75, bw_, math.max(2, math.floor(cfs * 0.3))))
            add(D.ev_text(x + cw / 2, cy, 5, string.format("\\b1\\fs%d\\c%s", cfs, U.ass_color(c.c)), U.ass_escape(c.t)))
            x = x + cw + lfs * 0.35
        end
        if status and x + HV.AX.tw(status, lfs - 2) < tx + maxw then
            add(D.ev_text(x + lfs * 0.2, cy, 4, string.format("\\fs%d\\c%s", lfs - 2, U.ass_color(status == "Ended" and THEME.text_muted or THEME.good)), U.ass_escape(status)))
        end
        mark(y, y + lh)
        y = y + lh
    end
    if genres then
        add(D.ev_text(tx, y + lh / 2, 4, string.format("\\fs%d\\c%s", gfs, U.ass_color(THEME.text_muted)), U.ass_escape(HV.ell(genres, maxw, gfs))))
        mark(y, y + lh)
        y = y + lh
    end
    if fail then
        local f1 = TV.failed[1]
        local txt = string.format("⚠  %d folder%s could not be listed (%s: %s) - retrying, R to retry now, Ctrl+D for a report",
            #TV.failed, #TV.failed == 1 and "" or "s", U.basename(f1.href) ~= "" and U.basename(f1.href) or f1.name, tostring(f1.err))
        add(D.ev_text(tx, y + lh / 2, 4, string.format("\\fs%d\\c%s", lfs - 1, U.ass_color(THEME.warn)), U.ass_escape(U.fit_text(txt, maxw, lfs - 1))))
        y = y + lh
    end
    if head then
        add(D.ev_text(tx, y + lh / 2, 4, string.format("\\b1\\fs%d", lfs), HV.detail_ass(head, maxw, lfs)))
        mark(y, y + lh)
        y = y + lh
    elseif tag then
        add(D.ev_text(tx, y + lh / 2, 4, string.format("\\i1\\fs%d\\c%s", lfs - 1, U.ass_color(THEME.text_muted)), U.ass_escape(HV.ell(tag, maxw, lfs - 1))))
        mark(y, y + lh)
        y = y + lh
    end
    for i, ln in ipairs(lines) do
        local txt = U.ass_escape(ln)
        -- the last line of a cut synopsis ends in "More" (click, or I) - "Less" folds it back
        if i == #lines and TV.more_avail then
            local word = TV.more and "Less" or "More"
            local hot = HV.btn_hover == "more"
            txt = txt .. string.format("  {\\b1\\c%s}%s", U.ass_color(hot and THEME.text_primary or THEME.accent), word)
            local lw = HV.AX.tw(ln .. "  ", lfs)
            HV.links[#HV.links + 1] = { x1 = tx + lw - 4, x2 = tx + lw + HV.AX.tw(word, lfs, true) + 6, y1 = y, y2 = y + lfs * 1.35,
                act = TV.toggle_more, hov = "more" }
        end
        add(D.ev_text(tx, y + lfs * 0.67, 4, string.format("\\fs%d\\c%s", lfs, U.ass_color(THEME.text_primary)), txt))
        mark(y, y + math.floor(lfs * 1.35))
        y = y + math.floor(lfs * 1.35)
    end
    -- what YOU have, under the synopsis
    if #L3 > 0 then
        y = y + math.floor(lfs * 0.25)
        add(D.ev_text(tx, y + lh / 2, 4, string.format("\\fs%d", sfs), HV.detail_ass(L3, maxw, sfs)))
        mark(y, y + lh)
        y = y + lh
    end
    if #btns > 0 then
        y = y + math.floor(lfs * 0.7)
        mark(y - 6, y + bh + 10)
        local x = tx
        for i, b in ipairs(btns) do
            local tw_ = HV.AX.tw(b.label, bfs, true)
            local bw = math.floor(tw_ + bfs * 2.4)
            if x + bw > tx + maxw then break end
            local hot = HV.btn_hover == b.id or HV.bfocus == i
            if b.primary then
                local tl = HV.XA.tilt(b.id, x, y, bw, bh)          -- experimental_play_tilt ("" otherwise)
                add(HV.XA.inj(string.format("{\\an7\\pos(0,0)\\bord0\\shad0\\blur%d\\1c&H000000&\\1a%s\\3a&HFF&\\p1}%s{\\p0}", math.max(4, math.floor(8 * m.S)),
                    U.ass_alpha(30), D.rounded_path(x, y + bh * 0.12, x + bw, y + bh * 1.1, bh / 2)), tl))
                add(HV.XA.inj(D.ev_rect(x, y, x + bw, y + bh, "FFFFFF", hot and 100 or 90, nil, 0, 0, bh / 2), tl))
                add(HV.XA.inj(D.ev_text(x + bw / 2, y + bh / 2, 5, string.format("\\b1\\fs%d\\c%s", bfs, U.ass_color(THEME.bg_dim)), U.ass_escape(b.label)), tl))
            else
                HV.gpill(add, x, y, x + bw, y + bh, m, nil, nil, hot)
                add(D.ev_text(x + bw / 2, y + bh / 2, 5, string.format("\\b1\\fs%d\\c%s", bfs, U.ass_color(hot and "FFFFFF" or THEME.text_primary)), U.ass_escape(b.label)))
            end
            if HV.bfocus == i then
                local rp = math.max(3, math.floor(4 * m.S))
                add(D.ev_rect(x - rp, y - rp, x + bw + rp, y + bh + rp, "FFFFFF", 0, THEME.accent, 100, math.max(2, math.floor(2.5 * m.S)), bh / 2 + rp))
            end
            HV.links[#HV.links + 1] = { x1 = x, x2 = x + bw, y1 = y, y2 = y + bh, act = function() HV.bfocus = nil; b.act() end, hov = b.id }
            if b.id == "dl" then TV.dl_rect = { x, y, x + bw, y + bh } end
            x = x + bw + math.floor(lfs * 0.6)
        end
    end
end
-- ---------- ? : the keys of the page you are on, as a glass sheet ----------
HV.HP = { open = false, ov = nil }
function HV.HP.rows()
    local function K(name)
        local raw = U.kb(name)[1]
        if raw and #raw == 1 then return raw:match("%u") and ("Shift+" .. raw) or raw:upper() end
        return U.kname(name)
    end
    local out = {}
    local function sec(title) out[#out + 1] = { sec = title } end
    local function row(k, what) if k and k ~= "" then out[#out + 1] = { k = k, what = what } end end
    local dl = U.knice((tostring(o.key_downloads or "D"):match("[^%s,]+")) or "D")
    local tk = U.knice((tostring(o.key_tracked or "u"):match("[^%s,]+")) or "u")
    if HV.mode == "add" then
        local st = HV.AX.stage
        sec("Add from add-ons")
        row("Type", "search a movie or series (TMDB)")
        row("↑ ↓ ← →", "move   ·   ↑ at the top: the search box")
        row("Enter", st == "title" and "the chosen button" or (st == "pick" and "add the ticked files" or "open"))
        row("Tab", "Nyaa.si for this title (or the source switch)")
        if st == "packs" or st == "releases" then row(K("sort") ~= "" and K("sort") or "S", "sort"); row("/", "filter the list"); row("E", "single episodes"); row("T", "stream as a torrent"); row("Ctrl+S", "save the add-ons' answers") end
        if st == "pick" then row("Space", "tick a file"); row("A", "all / none") end
        row("Esc", "back   ·   on the home page: close")
    elseif HV.TK.is_open() then
        sec("Tracked shows")
        row("↑ ↓", "move"); row("Enter", "open the title"); row("Space", "its bell: every episode / seasons / off"); row("Del", "untrack"); row("Esc", "close")
    elseif HV.dlc() then
        sec(HV.DLC.kind == "pop" and "Download" or "Download queue")
        if HV.DLC.kind == "pop" then row("Space", "tick a file"); row("A", "all / none"); row("Enter", "download the ticked"); row(dl, "the queue window")
        else row("↑ ↓", "select"); row("Shift+↑ ↓", "reorder"); row("Del", "remove"); row("Space", "pause / resume"); row(K("sort"), "stop all"); row(K("switch_view"), "open the folder") end
        row("Esc", "close")
    elseif HV.mode == "title" then
        sec("Title page")
        row("↑ ↓ ← →", "move   ·   ↑ from the first row: the buttons")
        row(K("open"), "play   ·   on a button: press it")
        row(K("queue"), "queue the episode"); row(K("watched"), "watched / unwatched"); row(K("sort"), "sort: order / recent")
        row(K("more"), "the whole synopsis"); row(K("refetch_art"), "re-fetch the artwork   ·   removed files: stream the torrent")
        row(K("report"), "a report of this title"); row(dl, "the download queue"); row(tk, "tracked shows")
        row(K("switch_view"), "the list view"); row(K("back") .. " / " .. K("close"), "back")
    else
        sec(HV.q and "Library search" or "Library")
        row("↑ ↓ ← →", "move"); row(K("open"), "open the title   ·   a file: play")
        row(K("search"), "search the library  (genre:anime  year:2010-2020  type:tv  rating:8  unwatched)")
        row(K("sort"), "sort: name / recently added"); row(K("refresh"), "refresh the listing"); row(K("refresh_all"), "refresh everything")
        row(K("queue"), "queue"); row(K("watched"), "watched / unwatched")
        if HV.AX.enabled() then row(U.knice((tostring(o.add_key or "n"):match("[^%s,]+")) or "n"), "add from add-ons") end
        row(dl, "the download queue"); row(tk, "tracked shows"); row(K("switch_view"), "the list view")
        row(U.knice((tostring(o.cache_clear_key or "ctrl+x"):match("[^%s,]+")) or "ctrl+x"), "clear the cache (press twice)")
        row(K("doctor"), "setup check"); row(K("close"), "close")
    end
    sec("Everywhere")
    row("?", "this sheet"); row(K("doctor"), "setup check")
    row("Mouse", (o.single_click_open and "a click opens" or "a click selects, a double-click opens") .. ", the wheel scrolls, the back button goes back")
    return out
end
function HV.HP.toggle()
    if HV.HP.open then return HV.HP.close() end
    HV.HP.open, HV.HP.t0 = true, U.now_s()
    -- pictures are drawn above every text layer: the page's posters go while the sheet is up
    if browser_active then HV.clear(); PS.hide() end
    HV.HP.draw()
end
-- a click: on its ✕ or outside the sheet closes it; inside, nothing
function HV.HP.click()
    local H = HV.HP
    local mx, my = U.mouse_xy()
    local r, x = H.rect, H.xr
    if not mx or not r then return H.close() end
    local inside = mx >= r[1] and mx <= r[3] and my >= r[2] and my <= r[4]
    local on_x = x and mx >= x[1] - 4 and mx <= x[3] + 4 and my >= x[2] - 4 and my <= x[4] + 4
    if on_x or not inside then H.close() end
end
function HV.HP.move(val)
    local H, x = HV.HP, HV.HP.xr
    local hot = (val and x and val.x >= x[1] - 4 and val.x <= x[3] + 4 and val.y >= x[2] - 4 and val.y <= x[4] + 4) or nil
    if hot ~= H.hot then H.hot = hot; H.draw() end
end
function HV.HP.close()
    if not HV.HP.open then return end
    HV.HP.open = false
    if HV.HP.ov then HV.HP.ov.data = ""; HV.HP.ov:update() end
    HV.GL.hide("hp")
    if browser_active then HV.sig, HV.last_data, MS.last_overlay_data = nil, nil, nil; render() end
end
function HV.HP.draw()
    local H = HV.HP
    if not H.open then return end
    local ww, wh = U.canvas_size()
    if not ww or ww <= 0 then return end
    local S = wh / 1080
    local rows = H.rows()
    local fs, fsk = math.max(11, math.floor(14 * S)), math.max(11, math.floor(13 * S))
    local fst = math.max(13, math.floor(20 * S))
    local lh, sh = math.floor(fs * 1.75), math.floor(fs * 2.4)
    local pad = math.floor(24 * S)
    local n = 0
    for _, r in ipairs(rows) do n = n + (r.sec and sh or lh) end
    local pw = math.min(ww - 60 * S, 900 * S)
    local ph = pad + fst * 1.4 + n + pad
    local x1, y1 = (ww - pw) / 2, math.max(20 * S, (wh - ph) / 2)
    local x2, y2 = x1 + pw, y1 + ph
    local a = HV.anim_on() and HV.ease((U.now_s() - (H.t0 or 0)) / 0.18) or 1
    local rad = math.floor(18 * S)
    local ev = {}
    ev[#ev + 1] = D.ev_rect(0, 0, ww, wh, "000000", 45 * a, nil, 0, 0, 0)
    local glass = (not browser_active) and HV.GL.show("hp", x1, y1, x2, y2, rad, S)
    HV.GL.frame(ev, x1, y1, x2, y2, rad, S, glass)
    if not glass then ev[#ev + 1] = D.ev_rect(x1, y1, x2, y2, THEME.bg_header, 94 * a, nil, 0, 0, rad) end
    local px = x1 + pad
    ev[#ev + 1] = HV.GL.txt(px, y1 + pad + fst * 0.5, 4, fst, 100 * a, true, "Keys")
    -- a round ✕ in the corner; a click on it, or anywhere outside the sheet, closes it (HV.HP.click)
    local xd = math.floor(fst * 1.5)
    local xcx, xcy = x2 - pad - xd / 2, y1 + pad + fst * 0.5
    H.rect, H.xr = { x1, y1, x2, y2 }, { xcx - xd / 2, xcy - xd / 2, xcx + xd / 2, xcy + xd / 2 }
    ev[#ev + 1] = D.ev_rect(H.xr[1], H.xr[2], H.xr[3], H.xr[4], H.hot and THEME.bad or "FFFFFF", (H.hot and 80 or 8) * a, "FFFFFF", 20 * a, 1, xd / 2)
    ev[#ev + 1] = D.ev_shape(D.cross_path(xcx, xcy, xd * 0.2, math.max(1, xd * 0.05)), H.hot and "FFFFFF" or THEME.text_muted, 100 * a)
    ev[#ev + 1] = HV.GL.txt(H.xr[1] - fsk * 0.8, y1 + pad + fst * 0.5, 6, fsk, 55 * a, false, "? or Esc closes")
    local y = y1 + pad + fst * 1.4
    local kw = 150 * S
    for _, r in ipairs(rows) do
        if r.sec then
            ev[#ev + 1] = D.ev_text(px, y + sh * 0.62, 4, string.format("\\b1\\fs%d\\c%s\\1a%s\\fsp1", fsk - 2, U.ass_color(THEME.accent), U.ass_alpha(100 * a)), U.ass_escape(r.sec:upper()))
            y = y + sh
        else
            -- the key as a cap
            local kt = r.k
            local tw = HV.AX.tw(kt, fsk, true) + fsk * 1.1
            ev[#ev + 1] = D.ev_rect(px, y + lh * 0.12, px + tw, y + lh * 0.88, "FFFFFF", 8 * a, "FFFFFF", 25 * a, 1, lh * 0.25)
            ev[#ev + 1] = D.ev_text(px + tw / 2, y + lh / 2, 5, string.format("\\b1\\fs%d\\c%s\\1a%s", fsk, "&HFFFFFF&", U.ass_alpha(100 * a)), U.ass_escape(kt))
            ev[#ev + 1] = HV.GL.txt(px + math.max(kw, tw + fsk), y + lh / 2, 4, fs, 80 * a, false, U.ass_escape(U.fit_text(r.what, x2 - pad - (px + math.max(kw, tw + fsk)), fs)))
            y = y + lh
        end
    end
    H.ov = H.ov or mp.create_osd_overlay("ass-events")
    H.ov.res_x, H.ov.res_y, H.ov.z = ww, wh, 3011
    H.ov.data = table.concat(ev, "\n")
    H.ov:update()
    if a < 1 then mp.add_timeout(1 / 60, function() if H.open then H.draw() end end) end
end

-- ---------- EXPERIMENTAL visuals (experimental_* in webdav-browser.conf) ----------
HV.XV = {}
-- video glass: the paused frame stays visible, dimmed and blurred, behind the browser (vo=gpu-next for the blur)
function HV.bg_alpha()
    if o.experimental_video_glass and HV.has_file and browser_active then
        return math.max(40, math.min(100, tonumber(o.experimental_video_glass_pct) or 72))
    end
    return 100
end
function HV.XV.glass_bg(m)
    if HV.bg_alpha() < 100 then
        HV.GL.show("bg", 0, 0, m.w, m.h, 0, m.S)
    else HV.GL.hide("bg") end
end
-- the colour wash: the poster's average colour, lifted, as a soft glow behind the hero's text
function HV.XV.wash(add, m, st, x1, y1, x2, y2)
    if not o.hero_wash or not st then return end
    local avg = HV.tiny_avg(st, 60, 90)
    if not avg then return end
    local r, g, b = tonumber(avg:sub(1, 2), 16), tonumber(avg:sub(3, 4), 16), tonumber(avg:sub(5, 6), 16)
    -- more saturation, a little brighter: a wash, not mud
    local mx, mn = math.max(r, g, b), math.min(r, g, b)
    local l = (mx + mn) / 2
    local function lift(c) local d = c - l; return math.max(0, math.min(255, math.floor(l * 0.9 + 40 + d * 1.8))) end
    local hex = string.format("%02X%02X%02X", lift(r), lift(g), lift(b))
    local op = math.max(4, math.min(40, tonumber(o.hero_wash_pct) or 14))
    -- three soft layers, each smaller than the last: a glow that fades out radially, not a tinted box
    local H = y2 - y1
    for i = 1, 3 do
        local inset = (i - 1) * 0.18
        local ax1, ay1 = x1 + (x2 - x1) * inset * 0.5, y1 + H * (0.08 + inset)
        local ax2, ay2 = x2 - (x2 - x1) * inset * 0.5, y2 - H * (0.08 + inset)
        if ax2 - ax1 > 40 and ay2 - ay1 > 20 then
            add(string.format("{\\an7\\pos(0,0)\\bord0\\shad0\\blur%d\\1c%s\\1a%s\\3a&HFF&\\p1}%s{\\p0}", math.floor(math.max(20, H * 0.5)),
                U.ass_color(hex), U.ass_alpha(op * 0.5), D.rounded_path(ax1, ay1, ax2, ay2, (ay2 - ay1) / 2)))
        end
    end
end
-- title logos (TMDB's transparent logo of a show / film) instead of the title text on the hero
HV.XV.LOGO_ID = 47
HV.XV.best_logo = PS.best_logo
function HV.XV.logo_path(show)
    if not (o.title_logo and show and show.id and show.kind) then return nil end
    if show.logo == nil and not show.logo_asked and not PS.logo_wait[tostring(show.kind) .. ":" .. tostring(show.id)] then
        show.logo_asked = true
        PS.api(string.format("/%s/%s/images?include_image_language=en,null", show.kind, show.id), function(d)
            local best = ""
            for _, lg in ipairs(d and type(d.logos) == "table" and d.logos or {}) do
                local fp = tostring(lg.file_path or "")
                if fp:match("%.png$") and (best == "" or (lg.iso_639_1 == "en" and not best:match("en$"))) then best = fp end
                if fp:match("%.png$") and lg.iso_639_1 == "en" then best = fp; break end
            end
            show.logo = best
            if not (HV.AX.tv and HV.AX.tv.t == show) and not show.ax then
                PS.idx_ver = PS.idx_ver + 1
                if PS.save_index then PS.save_index(show) end         -- with the entry: it goes into the journal
            end
            if browser_active then HV.sig, HV.last_data = nil, nil; render() end
        end)
    end
    return (show.logo ~= nil and show.logo ~= "") and show.logo or nil
end
-- width and height of a PNG from its header
function HV.XV.png_size(path)
    local f = io.open(path, "rb")
    if not f then return nil end
    local head = f:read(24); f:close()
    if not head or #head < 24 or head:sub(1, 8) ~= "\137PNG\r\n\26\n" then return nil end
    local function u32(p) local a, b, c, d = head:byte(p, p + 3); return ((a * 256 + b) * 256 + c) * 256 + d end
    return u32(17), u32(21)
end
-- the logo picture for the hero: f, w, h (nil until it is downloaded and converted); maxw x maxh is its box
function HV.XV.logo(show, maxw, maxh)
    local path = HV.XV.logo_path(show)
    if not path then return nil end
    local key = "logo:" .. show.id
    local st = HV.items[key]
    if not st then
        st = { state = "new", bgra = {}, cq = {}, base = "lg" .. show.id, entry = { id = 0 } }
        HV.items[key] = st
    end
    if st.state == "new" and HV.dn < 12 then
        st.jpg = PS.jpg_for(st.base, "w500"):gsub("%.jpg$", ".png")
        st.state = "downloading"
        HV.dn = HV.dn + 1
        PS.fetch_image("w500", path, st.jpg, function(ok)
            HV.dn = HV.dn - 1
            st.state = ok and "jpg" or "error"
            if browser_active then HV.sig, HV.last_data = nil, nil; HV.kick() end
        end)
        return nil
    end
    if st.state ~= "jpg" then return nil end
    if not st.pw then
        local pw, ph = HV.XV.png_size(st.jpg)
        if not pw or pw < 2 or ph < 2 then st.state = "error"; return nil end
        st.pw, st.ph = pw, ph
    end
    local sc = math.min(maxw / st.pw, maxh / st.ph)
    local dw, dh = math.max(8, math.floor(st.pw * sc + 0.5)), math.max(4, math.floor(st.ph * sc + 0.5))
    HV.want_bgra(st, dw, dh, "lg", -1)
    HV.convert_pump()
    local f = HV.bgra_of(st, HV.skey(dw, dh, "lg"))
    if f then return f, dw, dh end
    return nil
end
-- "NEW" on episode cards that aired in the last week, "Next S02E07 · in 3 days" on tracked shows' cards
function HV.XV.is_recent(date, days)
    if not o.new_badges then return false end
    local t, d = HV.TK.when(date)
    return t ~= nil and d <= 0 and d >= -(days or 7)
end
-- empty states: a drawn glyph (no font needed) over a short line
function HV.XV.empty(add, m, cx, cy, kind, title, sub)
    local S, lfs = m.S, m.lfs
    local s = math.floor(64 * S)
    local col = THEME.text_dim
    local function P(x, y) return D.fp(cx + x * s) .. " " .. D.fp(cy - s * 0.55 + y * s) end
    local function rect(x1, y1, x2, y2, r) return D.rounded_path(cx + x1 * s, cy - s * 0.55 + y1 * s, cx + x2 * s, cy - s * 0.55 + y2 * s, r * s) end
    if kind == "library" then
        -- three film cards, the middle one taller
        for i, c in ipairs({ { -0.95, 0.12 }, { -0.3, 0 }, { 0.35, 0.12 } }) do
            add(D.ev_shape(rect(c[1], c[2] - 0.5, c[1] + 0.6, c[2] + 0.5, 0.08), col, i == 2 and 55 or 30))
        end
    elseif kind == "queue" then
        -- an arrow into a tray
        add(D.ev_shape(string.format("m %s l %s %s %s %s %s %s", P(-0.08, -0.55), P(0.08, -0.55), P(0.08, -0.05), P(0.3, -0.05), P(0, 0.28), P(-0.3, -0.05), P(-0.08, -0.05)), col, 55))
        add(D.ev_shape(rect(-0.55, 0.35, 0.55, 0.55, 0.06), col, 30))
    elseif kind == "tracked" then
        add(HV.TK.bell(cx, cy - s * 0.5, s * 1.1, col, 45))
    end
    add(D.ev_text(cx, cy + s * 0.25, 5, string.format("\\b1\\fs%d\\c%s", lfs + 2, U.ass_color(THEME.text_muted)), U.ass_escape(title)))
    if sub then add(D.ev_text(cx, cy + s * 0.25 + lfs * 1.6, 5, string.format("\\fs%d\\c%s", lfs - 1, U.ass_color(THEME.text_dim)), U.ass_escape(sub))) end
end

-- ---- downloads on screen: the popover over the Download button, the queue window, the ↓ pill in the footer ----
-- The popover (kind "pop") opens above the title page's Download button: this title's files with tick boxes; Enter
-- queues the ticked ones and it closes. ⧉ (or the pill, or D) opens the queue window (kind "win"): the file arriving
-- now, everything waiting - of every title - and what finished this session; pause / resume, remove, reorder, retry.
-- HV.DLC = { kind, title, key, items (pop), sel, top, hole, links, dim }
function HV.dlc()
    local P = HV.DLC
    if P and browser_active and (HV.mode ~= "add" or P.kind == "win") and not P.closing then return P end
    return nil
end
function HV.dl_close(quiet)
    if not HV.DLC then return end
    if o.exit_anim and HV.anim_on() and not quiet and not HV.DLC.closing then
        HV.DLC.closing = U.now_s()
        HV.DLC.links, HV.btn_hover = {}, nil
        mp.add_timeout(0.17, function() if HV.DLC and HV.DLC.closing then HV.DLC = nil; HV.last_data = nil; if browser_active then render() end end end)
        HV.anim_kick(0.2)
        HV.last_data = nil
        render()
        return
    end
    HV.DLC, HV.btn_hover = nil, nil
    if quiet then return end
    HV.last_data = nil
    render()
end
-- the Download button: the popover with this title's files
function TV.dl_open()
    if not TV.card or #(TV.ordered or {}) == 0 then return HV.dl_show() end
    if HV.dlc() and HV.DLC.kind == "pop" then return HV.dl_close() end
    local title = TV.card.shown or TV.card.title
    local items = {}
    local only = (TV.multi and TV.season) or nil
    for _, ep in ipairs(TV.ordered or {}) do
      if not only or (ep.s or 0) == only then
        local e = ep.entry
        local em = MS.ep_meta[e.href]
        local label = (em and em.label and not TV.allmovie) and (em.label .. ((em.name and em.name ~= "") and ("  ·  " .. em.name) or "")) or TV.clean_name(e.name)
        local stt = HV.DL.status(title, e)
        items[#items + 1] = { e = e, label = label, on = (stt == nil or stt == "failed") }   -- what you don't have yet starts ticked
      end
    end
    HV.DLC = { kind = "pop", items = items, sel = 1, top = 1, title = title, key = TV.card.key, t0 = U.now_s() }
    HV.bfocus = nil
    HV.last_data = nil
    HV.anim_kick(0.25)
    render()
end
-- the queue window (the pill, D, ⧉ in the popover); pressed again it closes
function HV.dl_show()
    if HV.dlc() and HV.DLC.kind == "win" then return HV.dl_close() end
    local DL = HV.DL
    local c = DL.cur or DL.q[1] or DL.last
    HV.DLC = { kind = "win", title = c and c.title or "Downloads", sel = 1, top = 1, t0 = U.now_s() }
    HV.bfocus = nil
    HV.last_data = nil
    HV.anim_kick(0.25)
    render()
end
-- the rows of the queue window: the one arriving now, the queue, then what finished (newest first)
function HV.dl_rows()
    local DL, out = HV.DL, {}
    if DL.cur then out[#out + 1] = { kind = "cur", it = DL.cur } end
    for i, it in ipairs(DL.q) do out[#out + 1] = { kind = "q", i = i, it = it } end
    for _, it in ipairs(DL.hist) do out[#out + 1] = { kind = "hist", it = it } end
    return out
end
function HV.dl_count(P)
    if P.kind == "pop" then return #P.items end
    return #HV.dl_rows()
end
function HV.dl_sel_row()
    local P = HV.dlc()
    if not P or P.kind ~= "win" then return nil end
    return HV.dl_rows()[P.sel]
end
function TV.dl_toggle(i)
    local P = HV.dlc()
    if not P then return end
    if P.kind == "win" then
        -- Space in the queue window: pause / resume everything
        if HV.DL.paused then HV.DL.resume() else HV.DL.pause() end
        HV.last_data = nil
        return render()
    end
    local it = P.items[i or P.sel]
    if not it then return end
    it.on = not it.on
    HV.last_data = nil
    render()
end
function TV.dl_all()
    local P = HV.dlc()
    if not (P and P.kind == "pop") then return end
    local any_on = false
    for _, it in ipairs(P.items) do if it.on then any_on = true end end
    for _, it in ipairs(P.items) do it.on = not any_on end
    HV.last_data = nil
    render()
end
-- Enter: popover - the ticked files join the queue and it closes; window - resume, or retry a failed file
function TV.dl_go()
    local P = HV.dlc()
    if not P then return end
    if P.kind == "win" then
        local r = HV.dl_sel_row()
        if r and r.kind == "hist" and not r.it.ok then
            HV.DL.add(r.it.title, r.it.key, { { href = r.it.href, name = r.it.name, size = r.it.size } })
        elseif HV.DL.paused then HV.DL.resume() end
        HV.last_data = nil
        return render()
    end
    local list = {}
    for _, it in ipairs(P.items) do
        if it.on then
            local stt = HV.DL.status(P.title, it.e)
            if stt ~= "now" and stt ~= "queued" then list[#list + 1] = { href = it.e.href, name = it.e.name, size = it.e.size } end
        end
    end
    if #list == 0 then
        HV.TS.show({ eyebrow = "DOWNLOAD", title = "Nothing to add", extra = "tick a file with Space (A ticks all)" }, 3)
        return
    end
    HV.DL.add(P.title, P.key, list)
    HV.dl_close()
end
function TV.dl_move(d)
    local P = HV.dlc()
    if not P then return end
    local n = HV.dl_count(P)
    if n == 0 then return end
    P.sel = math.max(1, math.min(n, P.sel + d))
    HV.last_data = nil
    render()
end
-- Del: take the selected file out of the queue (the one arriving now is stopped and skipped; what arrived is kept)
function HV.dl_remove()
    local r = HV.dl_sel_row()
    if not r then return end
    if r.kind == "q" then HV.DL.remove(r.i)
    elseif r.kind == "cur" then HV.DL.skip()
    elseif r.kind == "hist" then
        for i, h in ipairs(HV.DL.hist) do if h == r.it then table.remove(HV.DL.hist, i); break end end
    end
    HV.last_data = nil
    render()
end
-- Shift+↑ / Shift+↓: move the selected queued file up or down the queue
function HV.dl_reorder(d)
    local P = HV.dlc()
    local r = HV.dl_sel_row()
    if not (r and r.kind == "q") then return end
    local j = r.i + d
    if HV.DL.move(r.i, j) then P.sel = P.sel + d end
    HV.last_data = nil
    render()
end
-- the mouse over the card: its own buttons only (the page under it does not react)
function HV.dl_click(mx, my)
    HV.last_act = U.now_s()
    local P = HV.DLC
    local L = P.links or {}
    for i = #L, 1, -1 do         -- the last one drawn is on top (a row's buttons after the row)
        local ln = L[i]
        if mx >= ln.x1 and mx <= ln.x2 and my >= ln.y1 and my <= ln.y2 then ln.act(); return end
    end
    local hl = P.hole
    if not (hl and mx >= hl[1] and mx <= hl[3] and my >= hl[2] and my <= hl[4]) then HV.dl_close() end
end

-- shared drawing of both cards
function HV.dl_kit(add, m, P)
    local S = m.S
    local K = {
        S = S, fs1 = math.max(10, math.floor(12 * S)), fs2 = math.max(13, math.floor(17 * S)),
        fs3 = math.max(11, math.floor(14 * S)), fs4 = math.max(10, math.floor(12.5 * S)),
        pad = math.floor(16 * S), gap = math.floor(8 * S), fsp = math.max(1, math.floor(S + 0.5)),
        bar_h = math.max(3, math.floor(4 * S + 0.5)),
    }
    K.pill_h = math.floor(K.fs4 * 2)
    K.rh = math.floor(K.fs3 * 2.45)
    function K.txt(x, y, an, fs, op, bold, s, rgb, extra)
        add(D.ev_text(x, y, an, string.format("\\fs%d\\b%d\\c%s\\1a%s%s", fs, bold and 1 or 0, U.ass_color(rgb or TOAST.text),
            U.ass_alpha(op * (P.fade or 1)), extra or ""), U.ass_escape(s)))
    end
    function K.link(x1, y1, x2, y2, id, act) P.links[#P.links + 1] = { x1 = x1, y1 = y1, x2 = x2, y2 = y2, hov = id, act = act } end
    -- a small pill button, right edge at px2: returns its left edge
    function K.pill(px2, cy, label, id, act, tint)
        local pw = math.floor(HV.AX.tw(label, K.fs4, true) + K.fs4 * 1.8)
        local px1 = px2 - pw
        local hot = HV.btn_hover == id
        add(D.ev_rect(px1, cy - K.pill_h / 2, px2, cy + K.pill_h / 2, tint or TOAST.text, hot and 26 or 12, tint or TOAST.text, hot and 45 or 22, K.fsp, K.pill_h / 2))
        K.txt(px1 + pw / 2, cy, 5, K.fs4, 95, true, label)
        K.link(px1, cy - K.pill_h / 2, px2, cy + K.pill_h / 2, id, act)
        return px1
    end
    -- the body: shadow, fill, hairline; k = 0..1 of its entrance (scale from the anchor, fade)
    function K.body(x1, y1, x2, y2, a)
        local rad = math.floor(16 * S)
        local b = math.max(6, math.floor(16 * S))
        add(string.format("{\\an7\\pos(0,0)\\bord0\\shad0\\blur%d\\1c&H000000&\\1a%s\\3a&HFF&\\p1}%s{\\p0}",
            b, U.ass_alpha(42 * a), D.rounded_path(x1, y1 + b * 0.35, x2, y2 + b * 0.6, rad)))
        add(D.ev_rect(x1, y1, x2, y2, TOAST.fill, 100 * a, TOAST.edge, 24 * a, K.fsp, rad))
        P.hole = { x1 - b, y1 - b, x2 + b, y2 + b * 1.4 }
    end
    -- the bar of the file arriving now
    function K.bar(x1, x2, y, frac)
        add(D.ev_rect(x1, y, x2, y + K.bar_h, TOAST.text, 14, nil, 0, 0, K.bar_h / 2))
        if frac then add(D.ev_rect(x1, y, x1 + math.max(K.bar_h * 2, (x2 - x1) * frac), y + K.bar_h, TOAST.accent, 100, nil, 0, 0, K.bar_h / 2)) end
    end
    function K.keys(x, y, list)
        local out = {}
        for i, k in ipairs(list) do
            out[#out + 1] = string.format("{\\b1\\1a%s}%s {\\b0\\1a%s}%s", U.ass_alpha(92), U.ass_escape((i > 1 and "    " or "") .. k[1]), U.ass_alpha(55), U.ass_escape(k[2]))
        end
        add(D.ev_text(x, y, 4, string.format("\\fs%d\\c%s", K.fs4, U.ass_color(TOAST.text)), table.concat(out)))
    end
    return K
end
-- "12 MB of 31 MB  ·  4 MB/s  ·  ~2 min left"
function HV.dl_stats()
    local DL = HV.DL
    local c = DL.cur
    if not c then return "" end
    local bits = { U.fmt_bytes(DL.got or 0) .. (c.size and (" of " .. U.fmt_bytes(c.size)) or "") }
    if (DL.speed or 0) > 0 then
        bits[#bits + 1] = U.fmt_bytes(DL.speed) .. "/s"
        if c.size and c.size > (DL.got or 0) then
            local secs = math.ceil((c.size - DL.got) / DL.speed)
            bits[#bits + 1] = (secs >= 120) and string.format("~%d min left", math.ceil(secs / 60)) or string.format("~%d s left", secs)
        end
    else bits[#bits + 1] = "waiting for data" end
    return table.concat(bits, "  ·  ")
end
function HV.dl_card(add, m)
    local P = HV.DLC
    P.links = {}
    local k = HV.ease((U.now_s() - (P.t0 or 0)) / 0.2)
    if not HV.anim_on() then k = 1 end
    if P.closing then k = 1 - HV.ease((U.now_s() - P.closing) / 0.16) end
    if P.kind == "pop" then return HV.dl_pop(add, m, P, k) end
    return HV.dl_win(add, m, P, k)
end

-- the popover: above the Download button (below it when there is no room), an arrow pointing at the button
function HV.dl_pop(add, m, P, a)
    local K = HV.dl_kit(add, m, P)
    P.fade = a
    local S, w, h = K.S, m.w, m.h
    local items = P.items
    local cw = math.floor(math.min(w - 40 * S, 470 * S))
    local fixed = K.pad + K.fs2 + K.gap + K.fs4 + K.gap * 1.5 + K.gap + K.pill_h + K.pad
    local br = TV.dl_rect or { w / 2 - 40, h / 2, w / 2 + 40, h / 2 + 30 }
    local arrow = math.floor(9 * S)
    -- above the button, with as many rows as fit there (at least 3, else it opens below)
    local fit = math.floor((br[2] - arrow - ((m.top_h or 0) + 4 * S) - fixed) / K.rh)
    local above = fit >= math.min(3, #items)
    local nvis = math.min(#items, 6, above and fit or 6)
    local ch = fixed + nvis * K.rh
    local x1 = math.floor(math.max(m.mx, math.min(w - m.mx - cw, (br[1] + br[3]) / 2 - cw / 2)))
    local y1 = above and math.floor(br[2] - arrow - ch) or math.floor(br[4] + arrow)
    -- it grows out of the button: a few pixels of travel and a fade
    y1 = y1 + math.floor((1 - a) * 8 * S * (above and 1 or -1))
    local x2, y2 = x1 + cw, y1 + ch
    K.body(x1, y1, x2, y2, a)
    -- the arrow
    local ax = math.floor(math.max(x1 + 24 * S, math.min(x2 - 24 * S, (br[1] + br[3]) / 2)))
    local ay = above and y2 or y1
    local d = above and 1 or -1
    add(D.ev_shape(string.format("m %s %s l %s %s l %s %s", D.fp(ax - arrow), D.fp(ay - d), D.fp(ax), D.fp(ay + d * arrow), D.fp(ax + arrow), D.fp(ay - d)), TOAST.fill, 100 * a))
    P.hole = { math.min(P.hole[1], x1), math.min(P.hole[2], ay - arrow), math.max(P.hole[3], x2), math.max(P.hole[4], ay + arrow) }
    if a < 0.35 then return end
    local tx, tr, tw = x1 + K.pad, x2 - K.pad, cw - 2 * K.pad
    local y = y1 + K.pad
    local cy = y + K.fs2 / 2
    local xr = K.pill(tr, cy, "✕", "dlx", function() HV.dl_close() end)
    xr = K.pill(xr - math.floor(6 * S), cy, "⧉  Queue", "dlwin", function() HV.dl_show() end)
    K.txt(tx, cy, 4, K.fs2, 100, true, HV.scfit("Download", xr - tx - K.gap, K.fs2, true))
    y = y + K.fs2 + K.gap
    local n_on, bytes = 0, 0
    for _, it in ipairs(items) do if it.on then n_on = n_on + 1; bytes = bytes + (tonumber(it.e.size) or 0) end end
    K.txt(tx, y + K.fs4 / 2, 4, K.fs4, 62, false, string.format("%d of %d ticked  ·  %s", n_on, #items, U.fmt_bytes(bytes)))
    local aw = HV.AX.tw("All / none", K.fs4, true)
    local hot = HV.btn_hover == "dlall"
    K.txt(tr, y + K.fs4 / 2, 6, K.fs4, hot and 100 or 80, true, "All / none", hot and TOAST.text or TOAST.accent)
    K.link(tr - aw - 4, y - 2, tr + 2, y + K.fs4 + 2, "dlall", function() TV.dl_all() end)
    y = y + K.fs4 + math.floor(K.gap * 1.5)
    if P.sel < P.top then P.top = P.sel elseif P.sel >= P.top + nvis then P.top = P.sel - nvis + 1 end
    P.top = math.max(1, math.min(P.top, #items - nvis + 1))
    local DL = HV.DL
    for i = P.top, math.min(#items, P.top + nvis - 1) do
        local it = items[i]
        local ry = y + (i - P.top) * K.rh
        local sel, hov = (i == P.sel), HV.btn_hover == ("dl" .. i)
        if sel or hov then
            add(D.ev_rect(tx - K.pad * 0.45, ry + 1, tr + K.pad * 0.45, ry + K.rh - 1, TOAST.text, sel and 10 or 5, TOAST.text, sel and 20 or 0, sel and K.fsp or 0, (K.rh - 2) / 2))
        end
        local rcy = ry + K.rh / 2
        local bs = math.floor(K.fs3 * 0.95)
        add(D.ev_rect(tx, rcy - bs / 2, tx + bs, rcy + bs / 2, it.on and TOAST.accent or TOAST.text, it.on and 100 or 0,
            it.on and TOAST.accent or TOAST.text, it.on and 100 or 45, K.fsp, math.max(2, bs * 0.25)))
        if it.on then K.txt(tx + bs / 2, rcy, 5, math.floor(bs * 0.85), 100, true, "✓", "FFFFFF") end
        local stt = HV.DL.status(P.title, it.e)
        local stxt, scol = "", nil
        if stt == "done" then stxt, scol = "✓ on your computer", TOAST.good
        elseif stt == "now" then
            local pc = (it.e.size and it.e.size > 0) and math.floor((DL.got or 0) / it.e.size * 100) or nil
            stxt, scol = "↓ " .. (pc and (pc .. " %") or "now"), TOAST.accent
        elseif stt == "queued" then stxt = "queued"
        elseif stt == "failed" then stxt, scol = "failed", TOAST.bad end
        local size = (tonumber(it.e.size) or 0) > 0 and U.fmt_bytes(it.e.size) or ""
        K.txt(tr, rcy, 6, K.fs4, 55, false, size)
        local rx = tr - HV.AX.tw(size, K.fs4) - K.gap
        if stxt ~= "" then
            K.txt(rx, rcy, 6, K.fs4, scol and 95 or 55, false, stxt, scol)
            rx = rx - HV.AX.tw(stxt, K.fs4) - K.gap
        end
        local lx = tx + bs + K.gap
        K.txt(lx, rcy, 4, K.fs3, sel and 100 or 85, sel, HV.scfit(it.label, rx - lx, K.fs3, sel))
        local ii = i
        K.link(tx - K.pad * 0.45, ry, tr + K.pad * 0.45, ry + K.rh, "dl" .. i, function() P.sel = ii; TV.dl_toggle(ii) end)
    end
    y = y + nvis * K.rh
    local more = (#items > nvis) and string.format("%d of %d  ·  ", math.min(#items, P.top + nvis - 1), #items) or ""
    y = y + K.gap
    -- the buttons: ↓ Download the ticked files (Enter), and while the line runs Pause / Resume beside it
    local by = y + K.pill_h / 2
    local DLq = HV.DL
    local lbl = (n_on > 0) and string.format("↓  Download %d file%s", n_on, n_on == 1 and "" or "s") or "↓  Download"
    local bx = K.pill(tr, by, lbl, "dlgo", function() TV.dl_go() end, TOAST.accent)
    if DLq.cur or DLq.paused then
        bx = K.pill(bx - math.floor(6 * S), by, DLq.paused and "▶  Resume" or "❚❚  Pause", "dlpause2",
            function() if DLq.paused then DLq.resume() else DLq.pause() end; HV.last_data = nil; render() end)
    end
    K.txt(tx, by, 4, K.fs4, 50, false, HV.scfit(more .. "Space tick  ·  A all  ·  Enter download", bx - tx - K.gap, K.fs4, false))
end

-- the queue window: centred, the page dimmed around it
function HV.dl_win(add, m, P, a)
    local K = HV.dl_kit(add, m, P)
    P.fade = a
    local DL = HV.DL
    local S, w, h = K.S, m.w, m.h
    P.dim = true
    local rows = HV.dl_rows()
    local nvis = (#rows == 0) and (o.empty_states and 4 or 1) or math.min(#rows, 8)
    local cw = math.floor(math.min(w - 40 * S, 640 * S))
    local c = DL.cur
    local head_h = K.fs1 + K.gap + K.fs2 + math.floor(K.gap * 0.7) + K.fs4
    local cur_h = (c or DL.paused) and (K.gap * 2 + K.fs3 + math.floor(K.gap * 0.8) + K.bar_h + math.floor(K.gap * 0.8) + K.pill_h) or 0
    local ch = K.pad + head_h + cur_h + K.gap * 2 + K.fs4 + math.floor(K.gap * 0.6) + nvis * K.rh + K.gap + K.fs4 + K.pad
    local x1 = math.floor((w - cw) / 2)
    local y1 = math.floor(math.max((m.top_h or 0), (h - ch) / 2)) + math.floor((1 - a) * 10 * S)
    local x2, y2 = x1 + cw, y1 + ch
    if not HV.dw_ok() then add(D.ev_rect(0, 0, w, h, THEME.bg_dim, 55 * a, nil, 0, 0)) end
    K.body(x1, y1, x2, y2, a)
    if a < 0.35 then return end
    local tx, tr, tw = x1 + K.pad, x2 - K.pad, cw - 2 * K.pad
    local y = y1 + K.pad
    local cy = y + K.fs1 / 2
    local xr = K.pill(tr, cy, "✕", "dlx", function() HV.dl_close() end)
    local sel_row = rows[P.sel]
    local ftitle = (sel_row and sel_row.it.title) or P.title
    xr = K.pill(xr - math.floor(6 * S), cy, "Open folder", "dlfolder", function() HV.DL.open_folder(HV.DL.folder_of(ftitle, true)) end)
    K.txt(tx, cy, 4, K.fs1, 62, true, "DOWNLOADS", nil, "\\fsp" .. K.fsp)
    y = y + K.fs1 + K.gap
    local left = #DL.q + (c and 1 or 0)
    local head = DL.paused and "Paused" or (c and string.format("%d of %d", DL.done + DL.failed + 1, DL.total))
        or (#DL.hist > 0 and "All done" or "Nothing downloading")
    K.txt(tx, y + K.fs2 / 2, 4, K.fs2, 100, true, head .. (left > 1 and string.format("  ·  %d to go", left) or ""))
    y = y + K.fs2 + math.floor(K.gap * 0.7)
    K.txt(tx, y + K.fs4 / 2, 4, K.fs4, 55, false, HV.scfit("To  " .. HV.DL.native(HV.DL.dir()), tw, K.fs4, false))
    y = y + K.fs4
    if c or DL.paused then
        y = y + K.gap * 2
        local cur = c or DL.q[1]
        local pct = (cur and cur.size and cur.size > 0) and math.min(1, (c and (DL.got or 0) or (utils.file_info(cur.dest .. ".part") or { size = 0 }).size) / cur.size) or nil
        local right = pct and string.format("%d %%", math.floor(pct * 100)) or "…"
        local rw = HV.AX.tw(right, K.fs3, true)
        K.txt(tr, y + K.fs3 / 2, 6, K.fs3, 95, true, right)
        K.txt(tx, y + K.fs3 / 2, 4, K.fs3, 92, true, HV.scfit(cur and (cur.title .. "  ·  " .. cur.name) or "", tw - rw - K.gap, K.fs3, true))
        y = y + K.fs3 + math.floor(K.gap * 0.8)
        K.bar(tx, tr, y, pct)
        y = y + K.bar_h + math.floor(K.gap * 0.8)
        local pcy = y + K.pill_h / 2
        local sx = K.pill(tr, pcy, "■  Stop all", "dlstop", function() HV.DL.stop() end, TOAST.bad)
        sx = K.pill(sx - math.floor(6 * S), pcy, DL.paused and "▶  Resume" or "❚❚  Pause", "dlpause",
            function() if DL.paused then DL.resume() else DL.pause() end; HV.last_data = nil; render() end)
        K.txt(tx, pcy, 4, K.fs4, 60, false, HV.scfit(DL.paused and "paused - what arrived is kept" or HV.dl_stats(), sx - tx - K.gap, K.fs4, false))
        y = y + K.pill_h
    end
    -- the list
    y = y + K.gap * 2
    local nq = #DL.q
    K.txt(tx, y + K.fs4 / 2, 4, K.fs4, 70, true, string.format("Queue %d  ·  Finished %d", nq + (c and 1 or 0), #DL.hist))
    y = y + K.fs4 + math.floor(K.gap * 0.6)
    if #rows == 0 then
        if o.empty_states then HV.XV.empty(add, m, (tx + tr) / 2, y + K.rh * 0.6, "queue", "Nothing queued", "A title page's Download button picks the files")
        else K.txt(tx, y + K.rh / 2, 4, K.fs3, 55, false, "Nothing yet - a title page's Download button picks the files") end
    end
    P.sel = math.max(1, math.min(P.sel, math.max(1, #rows)))
    if P.sel < P.top then P.top = P.sel elseif P.sel >= P.top + nvis then P.top = P.sel - nvis + 1 end
    P.top = math.max(1, math.min(P.top, math.max(1, #rows - nvis + 1)))
    for i = P.top, math.min(#rows, P.top + nvis - 1) do
        local r = rows[i]
        local it = r.it
        local ry = y + (i - P.top) * K.rh
        local rcy = ry + K.rh / 2
        local i0 = i
        P.links[#P.links + 1] = { x1 = tx - K.pad * 0.45, x2 = tr + K.pad * 0.45, y1 = ry, y2 = ry + K.rh, hov = "dw" .. i,
            act = function() P.sel = i0; HV.last_data = nil; render() end }
        local sel, hov = (i == P.sel), (HV.btn_hover or ""):match("^dw%a?" .. i .. "$") ~= nil
        if sel or hov then
            add(D.ev_rect(tx - K.pad * 0.45, ry + 1, tr + K.pad * 0.45, ry + K.rh - 1, TOAST.text, sel and 10 or 5, TOAST.text, sel and 20 or 0, sel and K.fsp or 0, (K.rh - 2) / 2))
        end
        -- the mark: ↓ now, the place in the queue, ✓ / ✕ when finished
        local mark, mcol = "", TOAST.text
        if r.kind == "cur" then mark, mcol = "↓", TOAST.accent
        elseif r.kind == "q" then mark, mcol = tostring(r.i + (c and 1 or 0)), TOAST.text
        elseif it.ok then mark, mcol = "✓", TOAST.good else mark, mcol = "✕", TOAST.bad end
        K.txt(tx + K.fs3 * 0.5, rcy, 5, K.fs4, r.kind == "q" and 55 or 95, true, mark, mcol)
        -- right side: size, then what you can do with it (on the selected / hovered row)
        local size = (tonumber(it.size) or 0) > 0 and U.fmt_bytes(it.size) or ""
        local rx = tr
        if sel or hov then
            local ii = i
            local function sbtn(label, id, act)
                local x0 = K.pill(rx, rcy, label, id .. i, function() P.sel = ii; act() end)
                rx = x0 - math.floor(4 * S)
            end
            sbtn("✕", "dwx", HV.dl_remove)
            if r.kind == "q" then
                if r.i < nq then sbtn("↓", "dwd", function() HV.dl_reorder(1) end) end
                if r.i > 1 then sbtn("↑", "dwu", function() HV.dl_reorder(-1) end) end
            elseif r.kind == "hist" and not it.ok then
                sbtn("Retry", "dwr", TV.dl_go)
            end
            rx = rx - K.gap
        end
        local status = (r.kind == "cur") and (DL.paused and "paused" or "now") or (r.kind == "q" and "" or (it.ok and "done" or "failed"))
        local right = size .. ((status ~= "" and size ~= "") and "  ·  " or "") .. status
        K.txt(rx, rcy, 6, K.fs4, 55, false, right, (r.kind == "hist" and not it.ok) and TOAST.bad or nil)
        rx = rx - HV.AX.tw(right, K.fs4) - K.gap
        local lx = tx + K.fs3 * 1.4
        local se, ep = CT.sxe(it.name)
        local lab = it.title .. "  ·  " .. (se and string.format("S%02dE%02d", se, ep) or TV.clean_name(it.name))
        K.txt(lx, rcy, 4, K.fs3, (r.kind == "hist") and 60 or (sel and 100 or 85), sel, HV.scfit(lab, rx - lx, K.fs3, sel))
    end
    y = y + nvis * K.rh
    if #rows > nvis then K.txt(tr, y + K.gap * 0.4, 6, math.max(9, K.fs4 - 2), 45, false, string.format("%d of %d", math.min(#rows, P.top + nvis - 1), #rows)) end
    y = y + K.gap
    K.keys(tx, y + K.fs4 / 2, { { "↑↓", "Select" }, { "Shift+↑↓", "Reorder" }, { "Del", "Remove" }, { "Space", DL.paused and "Resume" or "Pause" },
        { "S", "Stop all" }, { "V", "Folder" }, { "Esc", "Close" } })
end

-- ---- the ↓ pill in the footer (the animation layer draws it, so it can move without the page being rebuilt) ----
-- Starting or queueing a download: it widens with a little overshoot to "Download started" / "Queued · #3", the
-- arrow drops in, a light sweeps along its bottom edge; after a moment it settles back to "↓ Downloads" with a count
-- badge that bumps, and a thin line along its bottom edge shows the file arriving now. Done: a green "✓ Done";
-- a failure shakes once in red. Click it (or D) for the queue window.
HV.DLP = { ev = nil, geo = nil, n = 0, bump_t = nil, DUR = 2.6 }
function HV.DLP.count() return #HV.DL.q + (HV.DL.cur and 1 or 0) end
function HV.DLP.visible()
    local DL = HV.DL
    if DL.cur ~= nil or #DL.q > 0 or DL.paused then return true end
    return #DL.hist > 0 and U.now_s() - (DL.last_t or 0) < 120      -- finished: it stays a couple of minutes (Shift+D still opens the list)
end
function HV.DLP.fire(kind, text)
    local P = HV.DLP
    P.ev = { kind = kind, text = text, t0 = U.now_s() }
    if not (browser_active and MS.view == "home" and HV.mode ~= "add") then
        -- the footer is not on screen: a toast says it
        HV.TS.show({ eyebrow = "DOWNLOAD", title = text, note_rgb = (kind == "fail") and TOAST.bad or nil }, 3)
    end
    HV.anim_kick(P.DUR + 0.1)
    HV.kick()
end
function HV.DLP.live()
    local P = HV.DLP
    local now = U.now_s()
    return (P.ev and now - P.ev.t0 < P.DUR) or (P.bump_t and now - P.bump_t < 0.35) or false
end
-- the footer reserves the pill's place and makes it clickable: x2 = its right edge
function HV.DLP.place(m, x2, y1, y2, fs, pad)
    local P = HV.DLP
    if not HV.DLP.visible() then P.geo = nil; return x2 end
    local lab = "↓  Downloads"
    local w0 = math.floor(HV.AX.tw(lab, fs, true) + 2 * pad)
    P.geo = { x2 = x2, y1 = y1, y2 = y2, fs = fs, pad = pad, w0 = w0, S = m.S, glass = m.glass }
    HV.links[#HV.links + 1] = { x1 = x2 - w0, x2 = x2, y1 = y1, y2 = y2, hov = "dlpill", act = function() HV.dl_show() end }
    return x2 - w0
end
function HV.DLP.draw(ev, now)
    local P = HV.DLP
    local g = P.geo
    if not g or not HV.DLP.visible() and not P.ev then return end
    local DL = HV.DL
    local S, fs, pad = g.S, g.fs, g.pad
    local n = HV.DLP.count()
    if n > (P.n or 0) then P.bump_t = now end
    P.n = n
    local e = P.ev
    local t = e and (now - e.t0) or nil
    if t and t >= P.DUR then P.ev, e, t = nil, nil, nil end
    -- how far open (0 = the compact pill, 1 = the event's text), with a little overshoot on the way out
    local function back(k) k = math.max(0, math.min(1, k)); local c = 1.6; return 1 + (c + 1) * (k - 1) ^ 3 + c * (k - 1) ^ 2 end
    local open = 0
    if t then
        if t < 0.38 then open = back(t / 0.38)
        elseif t > P.DUR - 0.34 then open = 1 - HV.ease((t - (P.DUR - 0.34)) / 0.34)
        else open = 1 end
    end
    local elab = e and e.text or ""
    local w1 = e and math.floor(HV.AX.tw(elab, fs, true) + 2 * pad + fs * 1.2) or g.w0
    local wnow = math.floor(g.w0 + (w1 - g.w0) * open)
    local x2 = g.x2
    if e and e.kind == "fail" and t < 0.45 then x2 = x2 + math.sin(t * 42) * 6 * S * (1 - t / 0.45) end
    local x1, y1, y2 = x2 - wnow, g.y1, g.y2
    local h = y2 - y1
    local r = h / 2
    local cy = (y1 + y2) / 2
    local hot = HV.btn_hover == "dlpill"
    -- the body: an accent tint while something arrives, green / red for done / failed
    local tint = (e and e.kind == "done") and TOAST.good or ((e and e.kind == "fail") and TOAST.bad or TOAST.accent)
    local busy = DL.cur ~= nil and not DL.paused
    local ta = (e and math.min(1, open * 1.4) * 34) or ((busy or hot) and (hot and 30 or 18) or 8)
    local b = math.max(4, math.floor(8 * S + 0.5))
    ev[#ev + 1] = string.format("{\\an7\\pos(0,0)\\bord0\\shad0\\blur%d\\1c&H000000&\\1a%s\\3a&HFF&\\p1}%s{\\p0}",
        b, U.ass_alpha(34), D.rounded_path(x1, y1 + b * 0.3, x2, y2 + b * 0.5, r))
    ev[#ev + 1] = D.ev_rect(x1, y1, x2, y2, THEME.bg_header, 86, "FFFFFF", hot and 34 or 20, math.max(1, math.floor(S + 0.5)), r)
    if ta > 0 then ev[#ev + 1] = D.ev_rect(x1, y1, x2, y2, tint, ta, nil, 0, 0, r) end
    -- the labels cross-fade: the compact one out, the event's in (rising a little)
    local la = e and math.max(0, 1 - open * 3) or 1
    local ea = e and math.max(0, math.min(1, (open - 0.25) / 0.6)) or 0
    if la > 0.01 then
        ev[#ev + 1] = D.ev_text(x1 + wnow / 2, cy, 5, string.format("\\b1\\fs%d\\c%s\\1a%s", fs, U.ass_color(THEME.text_primary), U.ass_alpha(100 * la)), "↓  Downloads")
    end
    if ea > 0.01 then
        local dy = (1 - ea) * 6 * S
        local icon, icol = "↓", "FFFFFF"
        if e.kind == "done" then icon = "✓" elseif e.kind == "fail" then icon = "✕" elseif e.kind == "stop" then icon = "■" end
        -- the arrow drops in and bounces once
        local iy = 0
        if (e.kind == "start" or e.kind == "queued") and t < 0.45 then
            local k = t / 0.45
            iy = -(1 - k) * 10 * S * math.abs(math.cos(k * math.pi * 1.5))
        end
        local ix = x1 + pad + fs * 0.4
        ev[#ev + 1] = D.ev_text(ix, cy + iy, 5, string.format("\\b1\\fs%d\\c%s\\1a%s", fs + 1, U.ass_color(icol), U.ass_alpha(100 * ea)), icon)
        ev[#ev + 1] = D.ev_text(ix + fs * 0.9, cy + dy, 4, string.format("\\b1\\fs%d\\c%s\\1a%s", fs, U.ass_color("FFFFFF"), U.ass_alpha(100 * ea)), U.ass_escape(elab))
    end
    -- inside the pill: a light sweeping across once at the start, then the file arriving now as a soft fill from the
    -- left (the pill's own rounded shape, cut where the download is) - it used to be a line on the pill's bottom edge
    local function filled(xa, xb, rgb, op)
        if xb - xa < 1 then return end
        local clip = string.format("\\clip(%d,%d,%d,%d)", math.floor(xa), math.floor(y1) - 1, math.ceil(xb), math.ceil(y2) + 1)
        ev[#ev + 1] = (D.ev_rect(x1, y1, x2, y2, rgb, op, nil, 0, 0, r):gsub("{", "{" .. clip, 1))
    end
    if e and (e.kind == "start" or e.kind == "queued") and t < 0.9 then
        local k = HV.ease(t / 0.9)
        local sx = x1 + (x2 - x1) * k
        filled(math.max(x1, sx - (x2 - x1) * 0.35), sx, "FFFFFF", 16 * (1 - k * 0.6))
    elseif DL.cur and DL.cur.size and DL.cur.size > 0 then
        local f = math.min(1, (DL.got or 0) / DL.cur.size)
        filled(x1, x1 + math.max(r, (x2 - x1) * f), DL.paused and TOAST.warn or TOAST.accent, DL.paused and 22 or 30)
    end
    -- the count badge on the corner, bumping when it grows
    if n > 0 then
        local bk = P.bump_t and math.max(0, math.min(1, (now - P.bump_t) / 0.35)) or 1
        local sc = 1 + 0.4 * (1 - HV.ease(bk))
        local bfs = math.max(9, math.floor(fs * 0.78))
        local br_ = math.floor(bfs * 0.78 * sc)
        local bx, by = x2 - br_ * 0.35, y1 + br_ * 0.25
        local bw2 = math.max(br_, HV.AX.tw(tostring(n), bfs, true) / 2 + br_ * 0.45)
        ev[#ev + 1] = D.ev_rect(bx - bw2, by - br_, bx + bw2, by + br_, DL.paused and TOAST.warn or TOAST.accent, 100, THEME.bg_dim, 100, math.max(1, math.floor(1.5 * S)), br_)
        ev[#ev + 1] = D.ev_text(bx, by, 5, string.format("\\b1\\fs%d\\c%s\\fscx%d\\fscy%d", bfs, U.ass_color("FFFFFF"), math.floor(sc * 100), math.floor(sc * 100)), tostring(n))
    end
end

-- ---------- tracked shows ----------
-- "+ Track" on a title page (library or add screen) keeps the title here for good, until you untrack it. Every few
-- hours while mpv runs (track_check_hours) TMDB is asked for the next and the last episode (a movie: its release
-- date), and AniList for the exact airing time of anime. What is new waits until nothing is playing (or the browser
-- is open) and is then said in one toast; the Tracked pill on the top bar gets a dot until you look.
-- Each title's bell: every new episode | new seasons only (movies: the release) | off.
-- MS.tracked["tv:12345"] = { kind, id, name, poster, year, anime, bell, added, last {s,e,date}, next {s,e,date},
--                            status, release, al {ep, at}, new, seen }
HV.TK = { open = false, sel = 1, top = 1, pending = {}, pics = {} }
HV.TK.BELLS = { "all", "season", "off" }
function HV.TK.all()
    if type(MS.tracked) ~= "table" then MS.tracked = {} end
    return MS.tracked
end
function HV.TK.key(kind, id) return tostring(kind) .. ":" .. tostring(tonumber(id) or id) end
-- the live entry of a tracked show (nil once untracked)
function HV.TK.cur(e) return e and HV.TK.all()[HV.TK.key(e.kind, e.id)] or nil end
function HV.TK.has(kind, id) return id ~= nil and HV.TK.all()[HV.TK.key(kind, id)] ~= nil end
function HV.TK.on() return o.track_shows ~= false and PS.enabled() end
function HV.TK.save() HV.TK.rev = (HV.TK.rev or 0) + 1; debounced_save_persistence(2) end     -- a run of checks is one write
-- start tracking: info = { kind, id, name, poster, year, anime }
function HV.TK.add(info)
    if not (info and info.id and (info.kind == "tv" or info.kind == "movie")) then return end
    local k = HV.TK.key(info.kind, info.id)
    local all = HV.TK.all()
    if all[k] then return all[k] end
    local bell = tostring(o.track_bell or "all")
    if bell ~= "season" and bell ~= "off" then bell = "all" end
    local e = { kind = info.kind, id = tonumber(info.id), name = info.name or "?", poster = info.poster, year = info.year or "",
        anime = info.anime and true or nil, bell = bell, added = os.time() }
    all[k] = e
    HV.TK.save()
    HV.TS.show({ eyebrow = "TRACKED", title = e.name, extra = "you'll hear about new " .. ((e.kind == "movie") and "dates" or "episodes") }, 3)
    -- the dates now (what aired before you tracked it is not news); an anime then asks AniList for its air time
    HV.TK.check(e, true, function()
        if e.anime and e.kind == "tv" and o.track_air_times then HV.TK.anilist({ e }, true) end
    end)
    return e
end
function HV.TK.remove(k)
    local all = HV.TK.all()
    local e = all[k]
    if not e then return end
    all[k] = nil
    for _, tk in ipairs({ k, "w" .. k }) do
        if HV.TK.timers[tk] then HV.TK.timers[tk]:kill(); HV.TK.timers[tk] = nil end
    end
    HV.TK.save()
    HV.TS.show({ eyebrow = "TRACKED", title = "Untracked", extra = e.name }, 2.5)
end
-- the add screen's title page
function HV.TK.toggle_ax(t)
    if not (t and t.id) then return end
    local k = HV.TK.key(t.kind, t.id)
    if HV.TK.all()[k] then return HV.TK.remove(k) end
    HV.TK.add({ kind = t.kind, id = t.id, name = t.name, poster = t.poster, year = t.year, anime = HV.AX.is_anime(t) })
end
-- the library's title page
function HV.TK.show_info()
    local show = TV.show_entry and TV.show_entry()
    if not (show and show.id and (show.kind == "tv" or show.kind == "movie")) or show.coll then return nil end      -- (not a box set)
    local anime = false
    for _, g in ipairs(type(show.g) == "table" and show.g or {}) do if tonumber(g) == 16 then anime = true end end
    return { kind = show.kind, id = tonumber(show.id), name = show.name, poster = show.poster_path, year = show.year,
        anime = anime and (show.lang == "ja" or show.lang == "zh" or show.lang == "ko") }
end
function HV.TK.toggle_tv()
    local info = HV.TK.show_info()
    if not info then return end
    local k = HV.TK.key(info.kind, info.id)
    if HV.TK.all()[k] then HV.TK.remove(k) else HV.TK.add(info) end
    HV.last_data = nil
    render()
end

-- ---- checks ----
function HV.TK.ep(x)
    if type(x) ~= "table" then return nil end
    return { s = tonumber(x.season_number), e = tonumber(x.episode_number), date = x.air_date }
end
function HV.TK.newer(a, b)        -- episode a after episode b
    if not a or not a.e then return false end
    if not b or not b.e then return true end
    if (a.s or 0) ~= (b.s or 0) then return (a.s or 0) > (b.s or 0) end
    return a.e > b.e
end
function HV.TK.news(e, text, probe, loud)
    e.new = true
    local item = { name = e.name, text = text, loud = loud }
    if loud then HV.TK.ding() end
    HV.TK.pending[#HV.TK.pending + 1] = item
    -- an episode: ask the add-ons whether a cached release is up already (track_cached_check), the toast says so
    if probe and o.track_cached_check and HV.AX.enabled() and e.kind == "tv" then
        item.wait = os.time() + 20
        HV.TK.probe(e, probe.s, probe.e, function(cached, total)
            item.wait = nil
            if cached and cached > 0 then item.text = item.text .. string.format("  ·  %d cached on Real-Debrid", cached); e.cached = true
            elseif total and total > 0 then item.text = item.text .. "  ·  not cached yet" end
            HV.TK.deliver()
        end)
    end
    -- said a moment later, so news of several titles from one check comes as one toast
    if not HV.TK.dt then HV.TK.dt = mp.add_timeout(3, function() HV.TK.dt = nil; HV.TK.deliver() end) end
end
-- how many releases of S<s>E<e> the first add-on has, and how many of them are cached: cb(cached, total)
function HV.TK.probe(e, s_, e_, cb)
    local AX = HV.AX
    local src = AX.sources()[1]
    if not src then return cb(nil) end
    local function ask(imdb)
        if not imdb then return cb(nil) end
        local id = string.format("%s:%d:%d", imdb, s_ or 1, e_ or 1)
        local api = src.api ~= nil
        local url = api and (src.api .. "?type=series&id=" .. U.url_encode_segment(id)) or (src.url .. "/stream/series/" .. id .. ".json")
        PS.http({ url = url, timeout = 30, headers = api and { src.auth } or nil }, function(code, body)
            local ok, d = pcall(utils.parse_json, body or "")
            if code ~= 200 or not ok or type(d) ~= "table" then return cb(nil) end
            local list = api and (type(d.data) == "table" and d.data.results) or d.streams
            local n, c = 0, 0
            for _, x in ipairs(type(list) == "table" and list or {}) do
                if type(x) == "table" then
                    local it = api and AX.from_api(x) or AX.from_stremio(x)
                    if it then n = n + 1; if it.cached then c = c + 1 end end
                end
            end
            cb(c, n)
        end)
    end
    if e.imdb then return ask(e.imdb) end
    PS.api(string.format("/tv/%d/external_ids", e.id), function(d)
        e.imdb = d and d.imdb_id or nil
        ask(e.imdb)
    end)
end
function HV.TK.check(e, quiet, done)
    PS.api(string.format("/%s/%d?language=en-US", e.kind, e.id), function(d)
        if not d then if done then done() end return end
        e = HV.TK.cur(e)
        if not e then if done then done() end return end
        e.name = d.name or d.title or e.name
        if type(d.poster_path) == "string" and d.poster_path ~= "" then e.poster = d.poster_path end
        e.status = d.status
        e.checked = os.time()
        local today = os.date("%Y-%m-%d")
        if e.kind == "tv" then
            local last, nxt = HV.TK.ep(d.last_episode_to_air), HV.TK.ep(d.next_episode_to_air)
            local _, ago = HV.TK.when(last and last.date or nil)
            if not quiet and e.bell ~= "off" and last and HV.TK.newer(last, e.last) and (e.bell == "all" or last.e == 1)
                and (ago == nil or ago >= -7) then
                HV.TK.news(e, string.format("S%02dE%02d is out", last.s or 1, last.e), { s = last.s or 1, e = last.e })
            end
            e.last, e.next = (HV.TK.newer(e.last, last) and e.last) or last, nxt
            if not e.anime and nxt and o.track_air_times then mp.add_timeout(0.2, function() HV.TK.tvmaze(e) end) end
        else
            local rel = (type(d.release_date) == "string" and d.release_date ~= "") and d.release_date or nil
            if not quiet and e.bell ~= "off" then
                if rel and not e.release then HV.TK.news(e, "release date: " .. (HV.AX.nice_date(rel) or rel))
                elseif rel and rel <= today and not e.out_seen then HV.TK.news(e, "is out") end
            end
            if rel and rel <= today then e.out_seen = true end
            e.release = rel
        end
        HV.TK.save()
        if HV.TK.open and browser_active then HV.last_data = nil; render() end
        if done then done() end
    end)
end
-- anime: AniList's airing schedule (the exact time of the next episode, which is shown in your own time zone). The
-- AniList entry comes from the anime map (by TMDB id); a show the map doesn't have yet (a new season) is looked up on
-- AniList by its name. AniList counts the episodes of each entry from 1: the map's offset (or TMDB's next episode on the
-- same day) turns that into the TMDB season and episode, so "S02E05" is the episode the library will have.
function U.al_norm(t) return tostring(t or ""):lower():gsub("&", "and"):gsub("[^%w]", "") end
function HV.TK.al_pick(e, media)
    local want = U.al_norm(e.name)
    local best, fallback = nil, nil
    for _, md in ipairs(type(media) == "table" and media or {}) do
        local live = type(md.nextAiringEpisode) == "table" or md.status == "RELEASING" or md.status == "NOT_YET_RELEASED"
        if live and md.format ~= "MOVIE" then
            local names = {}
            local t = type(md.title) == "table" and md.title or {}
            names[#names + 1] = t.english; names[#names + 1] = t.romaji
            for _, sy in ipairs(type(md.synonyms) == "table" and md.synonyms or {}) do names[#names + 1] = sy end
            for _, nm in ipairs(names) do
                local n = U.al_norm(nm)
                if n ~= "" and n == want then best = best or md end
                if #n >= 4 and #want >= 4 and (n:find(want, 1, true) or (want:find(n, 1, true) and #n >= 0.6 * #want)) then fallback = fallback or md end
            end
        end
    end
    return best or fallback
end
function HV.TK.al_apply(e, na, s_, off, quiet)
    e = HV.TK.cur(e)
    if not e then return end
    local now = os.time()
    local prev = e.al
    if na then
        local ep, at = tonumber(na.episode), tonumber(na.airingAt)
        if off == nil then
            -- no offset known: TMDB's next episode, when it airs the same day, tells how the two count
            off = 0
            local nx = e.next
            if nx and nx.e and nx.date and at and ep then
                local t, days = HV.TK.when(nx.date)
                local _, dd = HV.TK.when(os.date("%Y-%m-%d", at))
                if t and dd and math.abs((days or 0) - dd) <= 1 then off = nx.e - ep; s_ = nx.s or s_ end
            end
        end
        e.al = (ep and at) and { ep = ep + off, at = at, s = s_ or 1 } or nil
    else e.al = nil end
    HV.TK.arm(e)
    -- the episode we were waiting for has aired (AniList knows it before TMDB does)
    if not quiet and prev and prev.at and prev.at <= now and e.bell == "all" and (e.al_seen or 0) < (prev.ep or 0) then
        e.al_seen = prev.ep
        HV.TK.news(e, string.format("S%02dE%02d is out", prev.s or 1, prev.ep), { s = prev.s or 1, e = prev.ep })
    end
end
function HV.TK.al_search(list, quiet)
    local want, by = {}, {}
    for i, e in ipairs(list) do
        if i > 8 then break end
        local q = tostring(e.name or ""):gsub("\\", " "):gsub('"', " ")
        if q ~= "" and q ~= "?" then
            want[#want + 1] = string.format('s%d:Page(perPage:6){media(search:"%s",type:ANIME,sort:SEARCH_MATCH){id status format title{romaji english} synonyms nextAiringEpisode{airingAt episode}}}', i, q)
            by["s" .. i] = e
        end
    end
    if #want == 0 then return end
    PS.al_gql("query{" .. table.concat(want, " ") .. "}", function(d)
        local data = type(d) == "table" and d.data or nil
        if type(data) ~= "table" then return end
        for alias, e0 in pairs(by) do
            local pg = data[alias]
            local e = HV.TK.cur(e0)
            local md = e and HV.TK.al_pick(e, type(pg) == "table" and pg.media or nil)
            if md then
                e.al_id = tonumber(md.id)
                local na = type(md.nextAiringEpisode) == "table" and md.nextAiringEpisode or nil
                HV.TK.al_apply(e, na, (e.next and e.next.s) or (e.last and e.last.s) or 1, nil, quiet)
                msg.verbose(string.format("tracked: %s -> AniList %s (by name)", tostring(e.name), tostring(md.id)))
            end
        end
        HV.TK.save()
        if HV.TK.open and browser_active then HV.last_data = nil; render() end
    end)
end
function HV.TK.anilist(list, quiet)
    if not (PS.AM and PS.AM.map) then pcall(PS.am_load) end
    if #list == 0 then return end
    local want, by, search = {}, {}, {}
    for _, e in ipairs(list) do
        local best, bs, boff = nil, -1, 0
        for _, m_ in ipairs(PS.am_entries("tv", e.id)) do
            if (tonumber(m_.s) or 1) > bs then best, bs, boff = m_.aid, tonumber(m_.s) or 1, tonumber(m_.off) or 0 end
        end
        if best then
            want[#want + 1] = string.format("a%s:Media(id:%s){status nextAiringEpisode{airingAt episode}}", best, best)
            by["a" .. best] = { e = e, s = bs, off = boff }
        elseif e.al_id then          -- found by name before
            want[#want + 1] = string.format("n%d:Media(id:%d){status nextAiringEpisode{airingAt episode}}", e.al_id, e.al_id)
            by["n" .. e.al_id] = { e = e, s = (e.next and e.next.s) or (e.last and e.last.s) or 1 }
        else search[#search + 1] = e end
    end
    if #search > 0 then HV.TK.al_search(search, quiet) end
    if #want == 0 then return end
    PS.al_gql("query{" .. table.concat(want, " ") .. "}", function(d)
        local data = type(d) == "table" and d.data or nil
        if type(data) ~= "table" then return end
        local again = {}
        for alias, ref in pairs(by) do
            local m_ = data[alias]
            local e = ref.e
            local na = type(m_) == "table" and type(m_.nextAiringEpisode) == "table" and m_.nextAiringEpisode or nil
            -- the map's entry has finished while TMDB lists a next episode: a new season the map doesn't know yet
            local kind_ = alias:sub(1, 1)
            if not na and (kind_ == "a" or kind_ == "n") and e.next and e.next.date and e.next.date >= os.date("%Y-%m-%d", os.time() - 86400) then
                if kind_ == "n" then e.al_id = nil end
                again[#again + 1] = e
            else
                HV.TK.al_apply(e, na, ref.s, ref.off, quiet)
            end
        end
        if #again > 0 then HV.TK.al_search(again, quiet) end
        HV.TK.save()
        if HV.TK.open and browser_active then HV.last_data = nil; render() end
    end)
end
function HV.TK.check_all(quiet)
    if not HV.TK.on() then return end
    local list = {}
    for _, e in pairs(HV.TK.all()) do list[#list + 1] = e end
    local anime = {}
    for i, e in ipairs(list) do
        if e.anime and e.kind == "tv" then anime[#anime + 1] = e end
        -- eight at a time (they share one curl process), a group every 0.4 s
        mp.add_timeout(0.4 * math.floor((i - 1) / 8), function() HV.TK.check(e, quiet) end)
    end
    mp.add_timeout(0.4 * math.ceil(#list / 8) + 1, function() HV.TK.anilist(anime, quiet) end)
end
-- what is new is said when nothing plays (or the browser is open): one toast for all of it
function HV.TK.deliver()
    local P = HV.TK.pending
    if #P == 0 then return end
    local loud = false
    for _, it in ipairs(P) do if it.loud then loud = true end end
    if not (browser_active or not HV.has_file or HV.paused or loud) then return end
    for _, it in ipairs(P) do if it.wait and it.wait > os.time() then return end end     -- a cache probe still on its way
    local title = (#P == 1) and (P[1].name .. "  " .. P[1].text) or string.format("%d new", #P)
    local extra = nil
    if #P > 1 then
        local names = {}
        for i = 1, math.min(3, #P) do names[#names + 1] = P[i].name end
        extra = table.concat(names, "  ·  ") .. ((#P > 3) and "  …" or "")
    end
    HV.TK.pending = {}
    HV.TS.show({ eyebrow = "TRACKED", title = title, extra = extra, decode = true, act = "tracked", note = U.knice((tostring(o.key_tracked or "u"):match("[^%s,]+")) or "u") .. " to see" }, 7)
    if browser_active then HV.last_data = nil; render() end
end
if o.track_shows ~= false then
    mp.add_timeout(10, function() HV.TK.check_all(false) end)           -- soon after the start: the toast comes while the player is still idle
    mp.add_periodic_timer(math.max(1, tonumber(o.track_check_hours) or 3) * 3600, function() HV.TK.check_all(false) end)
    mp.add_periodic_timer(20, HV.TK.deliver)
    -- the bell rings every few seconds while something is new (track_bell_anim)
    mp.add_periodic_timer(5, function()
        if HV.TK.bellpos and browser_active and HV.motion_ok() then HV.TK.ring_t0 = U.now_s(); HV.anim_kick(HV.TK.RING + 0.1) end
    end)
end

-- ---- air times (in your own time zone) ----
function U.days_from_civil(y, m, d)
    y = (m <= 2) and (y - 1) or y
    local era = math.floor(y / 400)
    local yoe = y - era * 400
    local mp_ = (m + 9) % 12
    local doy = math.floor((153 * mp_ + 2) / 5) + d - 1
    local doe = yoe * 365 + math.floor(yoe / 4) - math.floor(yoe / 100) + doy
    return era * 146097 + doe - 719468
end
-- "2026-10-20T01:00:00+00:00" (or ...Z, or no seconds) -> epoch seconds, nil when it doesn't read
function U.iso_epoch(sv)
    sv = tostring(sv or "")
    local y, mo, d, H, M, rest = sv:match("^(%d%d%d%d)%-(%d%d)%-(%d%d)[T ](%d%d):(%d%d)(.*)$")
    if not y then return nil end
    local S_ = tonumber(rest:match("^:(%d%d)")) or 0
    local off = 0
    local sg, oh, om = rest:match("([%+%-])(%d%d):?(%d%d)%s*$")
    if sg then off = (tonumber(oh) * 3600 + tonumber(om) * 60) * (sg == "-" and -1 or 1) end
    return U.days_from_civil(tonumber(y), tonumber(mo), tonumber(d)) * 86400 + tonumber(H) * 3600 + tonumber(M) * 60 + S_ - off
end
-- 8:30 pm (or 20:30 with clock_24h)
function U.clock(t)
    local d = os.date("*t", t)
    if o.clock_24h then return string.format("%02d:%02d", d.hour, d.min) end
    local h = d.hour % 12
    if h == 0 then h = 12 end
    return string.format("%d:%02d %s", h, d.min, d.hour < 12 and "am" or "pm")
end
-- when the next episode airs, as an epoch, when the time of day is known (AniList's, or TVmaze's)
function HV.TK.air_at(e)
    local now = os.time()
    if e.al and e.al.at and e.al.at > now - 86400 then return e.al.at, e.al.s, e.al.ep end
    local tv = e.tvn
    if tv and tv.at and tv.at > now - 86400 then return tv.at, tv.s, tv.e end
    return nil
end
-- TVmaze (no key): the next and the previous episode with their air time (by the show's IMDb id)
HV.TVMAZE = "https://api.tvmaze.com"
function HV.TK.tvmaze(e, cb)
    if not o.track_air_times or e.kind ~= "tv" then if cb then cb() end return end
    local function show(id)
        PS.http({ url = string.format("%s/shows/%d?embed%%5B%%5D=nextepisode&embed%%5B%%5D=previousepisode", HV.TVMAZE, id), timeout = 20 }, function(code, body)
            local ok, d = pcall(utils.parse_json, body or "")
            if code == 200 and ok and type(d) == "table" then
                local em = type(d._embedded) == "table" and d._embedded or {}
                local nx = type(em.nextepisode) == "table" and em.nextepisode or nil
                local pv = type(em.previousepisode) == "table" and em.previousepisode or nil
                e = HV.TK.cur(e) or e
                e.tvn = nx and { at = U.iso_epoch(nx.airstamp), s = tonumber(nx.season), e = tonumber(nx.number) } or nil
                e.tvp = pv and { at = U.iso_epoch(pv.airstamp), s = tonumber(pv.season), e = tonumber(pv.number) } or nil
                HV.TK.arm(e)
            end
            if cb then cb() end
        end)
    end
    if e.tvm then return show(e.tvm) end
    local function look(imdb)
        if not imdb then if cb then cb() end return end
        PS.http({ url = HV.TVMAZE .. "/lookup/shows?imdb=" .. imdb, timeout = 20, follow = true }, function(code, body)
            local ok, d = pcall(utils.parse_json, body or "")
            if code == 200 and ok and type(d) == "table" and tonumber(d.id) then
                e.tvm = tonumber(d.id)
                return show(e.tvm)
            end
            e.tvm_none = os.time()
            if cb then cb() end
        end)
    end
    if e.tvm_none and os.time() - e.tvm_none < 7 * 86400 then if cb then cb() end return end
    if e.imdb then return look(e.imdb) end
    PS.api(string.format("/tv/%d/external_ids", e.id), function(d) e.imdb = d and d.imdb_id or nil; look(e.imdb) end)
end
-- an episode airs in this session: at its time (+1 min) it is announced - or, with add-ons, watched until a cached
-- release is up, then announced as streamable (track_watch_release); one timer per show
HV.TK.timers = {}
function HV.TK.arm(e)
    local at, s_, ep = HV.TK.air_at(e)
    local k = HV.TK.key(e.kind, e.id)
    if HV.TK.timers[k] then HV.TK.timers[k]:kill(); HV.TK.timers[k] = nil end
    if not at or not ep or e.bell == "off" then return end
    if e.bell == "season" and ep ~= 1 then return end
    local now = os.time()
    local tag = string.format("%d:%d", s_ or 1, ep)
    if e.aired_tag == tag then return end
    if at - now > 26 * 3600 then return end                       -- the next check re-arms it
    HV.TK.timers[k] = mp.add_timeout(math.max(1, at - now + 60), function()
        HV.TK.timers[k] = nil
        HV.TK.aired(e, s_ or 1, ep, at)
    end)
end
function HV.TK.aired(e, s_, ep, at)
    e = HV.TK.cur(e)
    if not e or e.bell == "off" then return end      -- untracked or muted meanwhile
    local tag = string.format("%d:%d", s_, ep)
    if e.aired_tag == tag then return end
    e.aired_tag = tag
    e.last = { s = s_, e = ep, date = os.date("%Y-%m-%d", at) }      -- TMDB's later "is out" stays quiet
    if e.al and e.al.ep == ep then e.al_seen = ep end
    HV.TK.save()
    local label = string.format("S%02dE%02d", s_, ep)
    if o.track_watch_release and o.track_cached_check and HV.AX.enabled() then
        HV.TK.watch(e, s_, ep, at, label)
    else
        HV.TK.news(e, label .. " is out", nil, true)
    end
end
-- asks the add-ons now and then until a cached release of S<s>E<ep> is up (at most a day)
function HV.TK.watch(e, s_, ep, at, label)
    local mins = math.max(5, math.min(120, tonumber(o.track_poll_mins) or 15))
    local function try()
        local c = HV.TK.cur(e)
        if not c or c.bell == "off" then return end
        e = c
        HV.TK.probe(e, s_, ep, function(cached, total)
            if cached and cached > 0 then
                e.cached = true
                HV.TK.news(e, string.format("%s can be streamed  ·  %d cached on Real-Debrid", label, cached), nil, true)
                return
            end
            if os.time() - at > 24 * 3600 then
                HV.TK.news(e, label .. " aired" .. ((total and total > 0) and "  ·  not cached yet" or "  ·  no release found yet"), nil, true)
                return
            end
            HV.TK.timers["w" .. HV.TK.key(e.kind, e.id)] = mp.add_timeout(mins * 60, try)
        end)
    end
    try()
end
-- the sound that comes with news (track_sound): the system's notification sound, or your own .wav
function HV.TK.ding()
    local v = tostring(o.track_sound or "yes")
    if v == "no" or v == "" or v == "false" then return end
    local custom = (v ~= "yes" and v ~= "true") and v or nil
    local win = package.config:sub(1, 1) == "\\"
    local args
    if win then
        local f = custom or "C:\\Windows\\Media\\Windows Notify System Generic.wav"
        args = { "powershell", "-NoProfile", "-NonInteractive", "-Command",
            string.format("$f='%s'; if (-not (Test-Path $f)) { $f='C:\\Windows\\Media\\Windows Notify.wav' }; (New-Object Media.SoundPlayer $f).PlaySync()", (f:gsub("'", "''"))) }
    elseif (mp.get_property("platform") or "") == "darwin" then
        args = { "afplay", custom or "/System/Library/Sounds/Glass.aiff" }
    else
        args = { "sh", "-c", custom and ('paplay "$1" 2>/dev/null || aplay -q "$1"') or
            "paplay /usr/share/sounds/freedesktop/stereo/message-new-instant.oga 2>/dev/null || canberra-gtk-play -i message-new-instant 2>/dev/null", "sh", custom or "" }
    end
    mp.command_native_async({ name = "subprocess", playback_only = false, capture_stdout = true, capture_stderr = true, args = args }, function() end)
end
-- ---- what one row says ----
-- a time (epoch, or a TMDB date) and how many calendar days away it is
function HV.TK.when(at_or_date)
    local t = at_or_date
    local now = os.time()
    local W = HV.TK.W
    if not W or now >= W.till then
        -- today's noon, kept until midnight (looked at again every 10 minutes: a clock or DST change)
        local b = os.date("*t", now)
        W = { noon0 = os.time({ year = b.year, month = b.month, day = b.day, hour = 12 }), s = {},
              till = math.min(now + 600, os.time({ year = b.year, month = b.month, day = b.day + 1, hour = 0 })) }
        HV.TK.W = W
    end
    if type(t) == "string" then
        local hit = W.s[t]
        if hit then return hit[1], hit[2] end
        local y, mo, da = t:match("^(%d+)-(%d+)-(%d+)")
        if not y then return nil end
        t = os.time({ year = tonumber(y), month = tonumber(mo), day = tonumber(da), hour = 12 })
        local a = os.date("*t", t)
        local d = math.floor((os.time({ year = a.year, month = a.month, day = a.day, hour = 12 }) - W.noon0) / 86400 + 0.5)
        W.s[at_or_date] = { t, d }
        return t, d
    end
    local a = os.date("*t", t)
    local noon1 = os.time({ year = a.year, month = a.month, day = a.day, hour = 12 })
    return t, math.floor((noon1 - W.noon0) / 86400 + 0.5)
end
-- line, colour, sort key
function HV.TK.line(e)
    local now = os.time()
    if e.kind == "tv" then
        local at, as, ae = HV.TK.air_at(e)
        if at and at > now - 6 * 3600 then
            local _, days = HV.TK.when(at)
            local when = os.date("%a %d %b", at) .. "  " .. U.clock(at)
            local rel = (at <= now) and "aired" or ((days <= 0) and "today" or ((days == 1) and "tomorrow" or string.format("in %d days", days)))
            local lab = string.format("S%02dE%02d", as or 1, ae or 0)
            return string.format("%s  ·  %s  ·  %s", lab, when, rel), (days <= 1) and TOAST.good or TOAST.text, at
        end
        local nx = e.next
        if nx and nx.e and nx.date then
            local t, days = HV.TK.when(nx.date)
            if t and days >= 0 then
                local rel = (days == 0) and "today" or ((days == 1) and "tomorrow" or string.format("in %d days", days))
                return string.format("S%02dE%02d  ·  %s  ·  %s", nx.s or 1, nx.e, os.date("%a %d %b", t), rel), (days <= 1) and TOAST.good or TOAST.text, t
            end
        end
        local st = tostring(e.status or "")
        if st == "Ended" or st == "Canceled" then
            return (st == "Ended" and "Ended" or "Cancelled") .. (e.last and e.last.e and string.format("  ·  last S%02dE%02d", e.last.s or 1, e.last.e) or ""), nil, 4e9
        end
        if nx and nx.e then return string.format("S%02dE%02d  ·  date TBA", nx.s or 1, nx.e), nil, 3e9 end
        if e.last and e.last.e then return string.format("Latest S%02dE%02d  ·  next date TBA", e.last.s or 1, e.last.e), nil, 3e9 end
        return (e.checked and "Date TBA") or "Checking…", nil, 3e9
    end
    if e.release then
        local t, days = HV.TK.when(e.release)
        if t and days > 0 then return string.format("Out %s  ·  in %d days", os.date("%a %d %b %Y", t), days), (days <= 7) and TOAST.good or TOAST.text, t end
        if t then return "Released " .. os.date("%d %b %Y", t), TOAST.good, 2e9 end
    end
    return (e.checked and "Release date TBA") or "Checking…", nil, 3e9
end
-- "Next S02E07 · in 3 days" (anime: AniList's airing time), nil when nothing is known
function HV.TK.next_short(e)
    if not e or e.kind ~= "tv" then return nil end
    local now = os.time()
    local at, as, ae = HV.TK.air_at(e)
    if at and at > now then
        local _, days = HV.TK.when(at)
        local lab = string.format("Next S%02dE%02d", as or 1, ae or 0)
        local when = (days <= 0) and ("today " .. U.clock(at)) or ((days == 1) and ("tomorrow " .. U.clock(at)) or ("in " .. days .. " days"))
        return lab .. " · " .. when
    end
    local nx = e.next
    if nx and nx.e and nx.date then
        local t, days = HV.TK.when(nx.date)
        if t and days >= 0 then
            return string.format("Next S%02dE%02d · %s", nx.s or 1, nx.e, (days == 0) and "today" or ((days == 1) and "tomorrow" or ("in " .. days .. " days")))
        end
    end
    if nx and nx.e then return string.format("Next S%02dE%02d · date TBA", nx.s or 1, nx.e) end
    return nil
end
function HV.TK.sorted()
    local key = tostring(HV.TK.all()) .. "|" .. (HV.TK.rev or 0) .. "|" .. math.floor(mp.get_time())
    if HV.TK.sorted_c and HV.TK.sorted_k == key then return HV.TK.sorted_c end
    local out = HV.TK.sorted0()
    HV.TK.sorted_c, HV.TK.sorted_k = out, key
    return out
end
function HV.TK.sorted0()
    local out = {}
    for k, e in pairs(HV.TK.all()) do
        local line, col, sk = HV.TK.line(e)
        out[#out + 1] = { k = k, e = e, line = line, col = col, sk = (e.new and -1 or 0) * 1e10 + sk, when = sk }
    end
    table.sort(out, function(a, b) if a.sk ~= b.sk then return a.sk < b.sk end return a.e.name < b.e.name end)
    return out
end
-- the calendar view: which day a row belongs to ("Today", "Tomorrow", "Sat 18 Oct", "Later", "Date TBA", "Ended")
function HV.TK.day_of(r)
    local sk = r.when or 3e9
    if sk >= 4e9 then return "Ended / released" end
    if sk >= 3e9 then return "Date TBA" end
    if sk >= 2e9 then return "Out now" end
    local _, days = HV.TK.when(sk)
    if days <= 0 then return "Today" elseif days == 1 then return "Tomorrow" elseif days < 7 then return os.date("%A", sk) end
    return "Later"
end
-- the next 7 days, each with how many episodes it brings (the strip at the top of the flyout)
function HV.TK.week()
    local out = {}
    local b = os.date("*t")
    local day0 = os.time({ year = b.year, month = b.month, day = b.day, hour = 12 })
    for i = 0, 6 do out[i + 1] = { t = day0 + i * 86400, n = 0, names = {} } end
    for _, r in ipairs(HV.TK.sorted()) do
        if r.when < 2e9 then
            local _, days = HV.TK.when(r.when)
            if days and days >= 0 and days < 7 then
                local d = out[days + 1]
                d.n = d.n + 1
                d.names[#d.names + 1] = r.e.name
            end
        end
    end
    return out
end
function HV.TK.any_new() for _, e in pairs(HV.TK.all()) do if e.new then return true end end return false end
-- the bell rings (track_bell_anim): true while a ring is on its way
HV.TK.RING = 0.9
function HV.TK.ringing() return HV.TK.bellpos ~= nil and HV.TK.ring_t0 ~= nil and U.now_s() - HV.TK.ring_t0 < HV.TK.RING end
function HV.TK.ring_fx(ev, now)
    local bp = HV.TK.bellpos
    if not bp or not browser_active or MS.view ~= "home" or (HV.DR and HV.DR.open) then return end
    local t = HV.TK.ring_t0 and (now - HV.TK.ring_t0) or HV.TK.RING
    local ang = 0
    if t < HV.TK.RING then
        local k = t / HV.TK.RING
        ang = 16 * math.sin(t * 2 * math.pi * 3.3) * (1 - k) ^ 1.5
        local hr = bp.s * (0.65 + 1.1 * k)
        ev[#ev + 1] = string.format("{\\an7\\pos(0,0)\\bord0\\shad0\\blur%s\\1c%s\\1a%s\\3a&HFF&\\p1}%s{\\p0}", D.fp(bp.s * 0.3),
            U.ass_color(THEME.accent), U.ass_alpha(45 * (1 - k)), D.rounded_path(bp.cx - hr, bp.cy - hr, bp.cx + hr, bp.cy + hr, hr, true))
    end
    local bell = HV.TK.bell(0, 0, bp.s, bp.rgb, 100)
    ev[#ev + 1] = (bell:gsub("\\pos%(0,0%)", string.format("\\pos(%s,%s)\\org(%s,%s)\\frz%s", D.fp(bp.cx), D.fp(bp.cy), D.fp(bp.cx), D.fp(bp.cy - bp.s * 0.5), D.fp(-ang)), 1))
end

-- ---- the Tracked pill (top bar) and its flyout ----
-- the pill: right edge x2; returns its left edge
function HV.TK.pill(add, m, x2, y1, y2, fs, pad)
    if not HV.TK.on() then HV.TK.anchor = nil; return x2 end
    local lab = "Tracked"
    local n = 0
    for _ in pairs(HV.TK.all()) do n = n + 1 end
    local bs = math.floor((y2 - y1) * 0.42)
    local w0 = math.floor(pad + bs + fs * 0.45 + HV.AX.tw(lab, fs, true) + ((n > 0) and (fs * 0.6 + HV.AX.tw(tostring(n), fs - 2)) or 0) + pad)
    local x1 = x2 - w0
    local cy = (y1 + y2) / 2
    local hot = HV.link_hover == 98 or HV.TK.open
    HV.gpill(add, x1, y1, x2, y2, m, HV.TK.open and "FFFFFF" or nil, HV.TK.open and 13 or nil, hot)
    local ringing = HV.TK.any_new() and HV.anim_on() and not HV.TK.open and o.track_bell_anim ~= false
    if ringing then HV.TK.bellpos = { cx = x1 + pad + bs / 2, cy = cy, s = bs, rgb = hot and "FFFFFF" or THEME.text_muted }
    else HV.TK.bellpos = nil; add(HV.TK.bell(x1 + pad + bs / 2, cy, bs, hot and "FFFFFF" or THEME.text_muted, 100)) end
    add(D.ev_text(x1 + pad + bs + fs * 0.45, cy, 4, string.format("\\b1\\fs%d\\c%s", fs, U.ass_color(hot and "FFFFFF" or THEME.text_muted)), lab))
    if n > 0 then
        add(D.ev_text(x2 - pad, cy, 6, string.format("\\fs%d\\c%s", fs - 2, U.ass_color(THEME.text_dim)), tostring(n)))
    end
    if HV.TK.any_new() then          -- something new: a dot on the bell
        local dr = math.max(2, math.floor(fs * 0.18))
        local dx, dy = x1 + pad + bs * 0.85, cy - bs * 0.38
        add(D.ev_rect(dx - dr, dy - dr, dx + dr, dy + dr, THEME.bad, 100, THEME.bg_dim, 100, 1, dr))
    end
    HV.TK.anchor = { x1, y1, x2, y2 }
    HV.links[#HV.links + 1] = { x1 = x1, x2 = x2, y1 = y1, y2 = y2, crumb = 98, act = function() HV.TK.toggle() end }
    return x1
end
-- a bell, drawn (font glyphs for it differ between systems); off = struck through
function HV.TK.bell(cx, cy, s, rgb, op, off)
    local function P(x, y) return D.fp(cx + x * s) .. " " .. D.fp(cy + y * s) end
    local path = "m " .. P(-0.46, 0.28) .. " l " .. P(-0.36, 0.16) .. " b " .. P(-0.36, -0.14) .. " " .. P(-0.3, -0.4) .. " " .. P(0, -0.42)
        .. " b " .. P(0.3, -0.4) .. " " .. P(0.36, -0.14) .. " " .. P(0.36, 0.16) .. " l " .. P(0.46, 0.28)
        .. " m " .. P(-0.12, 0.34) .. " b " .. P(-0.1, 0.5) .. " " .. P(0.1, 0.5) .. " " .. P(0.12, 0.34)
        .. " m " .. P(-0.05, -0.42) .. " l " .. P(-0.05, -0.5) .. " " .. P(0.05, -0.5) .. " " .. P(0.05, -0.42)
    local out = D.ev_shape(path, rgb, op)
    if off then out = out .. "\n" .. D.ev_shape(string.format("m %s l %s %s %s", P(-0.5, -0.5), P(0.5, 0.45), P(0.42, 0.53), P(-0.58, -0.42)), rgb, op) end
    return out
end
function HV.TK.toggle()
    if HV.TK.open then return HV.TK.close(true) end
    HV.dl_close(true)
    HV.TK.open, HV.TK.sel, HV.TK.top, HV.TK.t0 = true, 1, 1, U.now_s()
    HV.bfocus = nil
    HV.last_data = nil
    HV.anim_kick(0.25)
    render()
end
function HV.TK.close(now)
    if not HV.TK.open then return end
    if o.exit_anim and HV.anim_on() and not HV.TK.closing and not now then
        HV.TK.closing, HV.TK.links = U.now_s(), {}
        mp.add_timeout(0.17, function()
            if not HV.TK.closing then return end
            if HV.TK.open then HV.TK.close(true) else HV.TK.closing = nil end
        end)
        HV.anim_kick(0.2)
        HV.last_data = nil
        render()
        return
    end
    HV.TK.closing = nil
    HV.TK.open, HV.TK.hole, HV.TK.links = false, nil, nil
    -- what you have seen is no longer new
    local changed = false
    for _, e in pairs(HV.TK.all()) do if e.new then e.new = nil; changed = true end end
    if changed then HV.TK.save() end
    HV.btn_hover = nil
    HV.last_data = nil
    render()
end
-- list | calendar: what you last picked with the ▦ / ☰ pill, else track_view from the conf
function HV.TK.view()
    local v = MS.hints and MS.hints.track_view
    if v ~= "list" and v ~= "calendar" then v = tostring(o.track_view or "list") end
    return v
end
function HV.TK.is_open() return HV.TK.open and browser_active and not HV.TK.closing end
function HV.TK.drawn() return HV.TK.open and browser_active end
function HV.TK.move(d)
    local n = #HV.TK.sorted()
    if n == 0 then return end
    HV.TK.sel = math.max(1, math.min(n, HV.TK.sel + d))
    HV.last_data = nil
    render()
end
function HV.TK.cycle_bell(k)
    local e = HV.TK.all()[k]
    if not e then return end
    local i = 1
    for j, b in ipairs(HV.TK.BELLS) do if b == e.bell then i = j end end
    e.bell = HV.TK.BELLS[(i % #HV.TK.BELLS) + 1]
    if e.kind == "movie" and e.bell == "season" then e.bell = "off" end      -- a movie: its release, or nothing
    HV.TK.arm(e)
    if e.bell == "off" and HV.TK.timers["w" .. k] then HV.TK.timers["w" .. k]:kill(); HV.TK.timers["w" .. k] = nil end
    HV.TK.save()
    HV.last_data = nil
    render()
end
function HV.TK.bell_hint(e)
    if e.bell == "off" then return "Notifications off" end
    if e.kind == "movie" then return "Notify: release date and release" end
    return (e.bell == "season") and "Notify: new seasons only" or "Notify: every new episode"
end
-- Enter / a click: its title page - in your library when it is there, else the add screen's
function HV.TK.open_entry(e)
    if not e then return end
    HV.last_act = U.now_s()
    HV.TK.close(true)
    if HV.mode == "add" then
        return HV.AX.show_title({ kind = e.kind, id = e.id, name = e.name, poster = e.poster, year = e.year, anime = e.anime, text = e.name },
            HV.AX.stage == "title")
    end
    PS.load_index()
    if HV.mode == "home" and not HV.q then
        for _, row in ipairs(HV.rows or {}) do
            for _, card in ipairs(row.cards or {}) do
                local ie = PS.idx[card.key]
                if type(ie) == "table" and tonumber(ie.id) == e.id and ie.kind == e.kind and card.kind == "folder" then return TV.open(card) end
            end
        end
    end
    HV.AX.open()
    if HV.mode ~= "add" then return end
    HV.AX.show_title({ kind = e.kind, id = e.id, name = e.name, poster = e.poster, year = e.year, anime = e.anime, text = e.name })
end
function HV.TK.enter()
    local r = HV.TK.sorted()[HV.TK.sel]
    if r then HV.TK.open_entry(r.e) end
end
function HV.TK.remove_sel()
    local r = HV.TK.sorted()[HV.TK.sel]
    if r then HV.TK.remove(r.k); HV.last_data = nil; render() end
end
function HV.TK.click(mx, my)
    local L = HV.TK.links or {}
    for i = #L, 1, -1 do         -- the last one drawn is on top (a row's buttons after the row)
        local ln = L[i]
        if mx >= ln.x1 and mx <= ln.x2 and my >= ln.y1 and my <= ln.y2 then ln.act(); return end
    end
    local hl = HV.TK.hole
    if not (hl and mx >= hl[1] and mx <= hl[3] and my >= hl[2] and my <= hl[4]) then HV.TK.close() end
end
-- the flyout: under the pill, right-aligned with it; posters on the left of each row; scrolls past max height
function HV.TK.draw(add, m)
    local K = HV.dl_kit(add, m, { links = {} })
    local TK = HV.TK
    TK.links, TK.pics = {}, {}
    local function link(x1, y1, x2, y2, id, act) TK.links[#TK.links + 1] = { x1 = x1, y1 = y1, x2 = x2, y2 = y2, hov = id, act = act } end
    local S, w, h = K.S, m.w, m.h
    local a = HV.anim_on() and HV.ease((U.now_s() - (TK.t0 or 0)) / 0.2) or 1
    if TK.closing then a = 1 - HV.ease((U.now_s() - TK.closing) / 0.16) end
    local rows = TK.sorted()
    local th = math.floor(60 * S)
    local tw_ = math.floor(th * 2 / 3)
    local rh = th + math.floor(10 * S)
    local an = TK.anchor or { w - m.mx - 100, 10, w - m.mx, 40 }
    local cw = math.floor(math.min(w - 2 * m.mx, 540 * S))
    local x2 = math.floor(math.min(w - m.mx, an[3]))
    local x1 = x2 - cw
    local y1 = math.floor(an[4] + 8 * S - (1 - a) * 6 * S)
    local cal_h = (HV.TK.view() == "calendar") and (math.floor(K.fs4 * 3.4) + K.gap) or 0
    local head = K.pad + K.fs2 + K.gap + cal_h
    local maxh = math.floor(h * 0.66)
    local nvis = math.max(1, math.min(#rows, math.floor((maxh - head - K.pad - K.fs4 - K.gap) / rh), 8))
    local ch = head + ((#rows == 0) and (K.fs3 * (o.empty_states and 7 or 3)) or (nvis * rh)) + K.gap + K.fs4 + K.pad
    local y2 = y1 + ch
    local P = { links = TK.links, fade = a }
    local K2 = HV.dl_kit(add, m, P)
    K2.body(x1, y1, x2, y2, a)
    TK.hole = P.hole
    -- the little arrow up to the pill
    local ax = math.floor((an[1] + an[3]) / 2)
    local ar = math.floor(7 * S)
    add(D.ev_shape(string.format("m %s %s l %s %s l %s %s", D.fp(ax - ar), D.fp(y1 + 1), D.fp(ax), D.fp(y1 - ar), D.fp(ax + ar), D.fp(y1 + 1)), TOAST.fill, 100 * a))
    if a < 0.35 then return end
    local tx, tr = x1 + K.pad, x2 - K.pad
    local y = y1 + K.pad
    local cy = y + K.fs2 / 2
    K2.txt(tx, cy, 4, K.fs2, 100, true, "Tracked")
    K2.txt(tx + HV.AX.tw("Tracked", K.fs2, true) + K.gap, cy, 4, K.fs4, 55, false, string.format("%d title%s", #rows, #rows == 1 and "" or "s"))
    local xr = K2.pill(tr, cy, "Check now", "tkcheck", function()
        HV.TK.check_all(false)
        HV.TS.show({ eyebrow = "TRACKED", title = "Checking…" }, 2)
    end)
    local cal = HV.TK.view() == "calendar"
    xr = K2.pill(xr - math.floor(6 * S), cy, cal and "☰ List" or "▦ Calendar", "tkview", function()
        MS.hints = MS.hints or {}
        MS.hints.track_view = cal and "list" or "calendar"
        if save_persistence then save_persistence() end
        HV.last_data = nil; render()
    end)
    y = y + K.fs2 + K.gap
    if cal then
        -- the week: seven cells, a count where something airs
        local wk = HV.TK.week()
        local cw_ = math.floor((tr - tx - 6 * K.gap * 0.5) / 7)
        local ch_ = math.floor(K.fs4 * 3.4)
        for i, d in ipairs(wk) do
            local cx1 = tx + (i - 1) * (cw_ + math.floor(K.gap * 0.5))
            local hot = HV.btn_hover == ("tkd" .. i)
            add(D.ev_rect(cx1, y, cx1 + cw_, y + ch_, TOAST.text, d.n > 0 and (hot and 22 or 12) or 5, TOAST.text, d.n > 0 and 30 or 12, K.fsp, math.floor(8 * S)))
            K2.txt(cx1 + cw_ / 2, y + K.fs4 * 0.9, 5, K.fs4 - 1, i == 1 and 95 or 60, i == 1, i == 1 and "Today" or os.date("%a", d.t))
            K2.txt(cx1 + cw_ / 2, y + K.fs4 * 2.3, 5, K.fs3, d.n > 0 and 100 or 35, d.n > 0, d.n > 0 and tostring(d.n) or os.date("%d", d.t), d.n > 0 and TOAST.accent or nil)
            if d.n > 0 then
                local names = table.concat(d.names, "  ·  ", 1, math.min(3, #d.names)) .. (#d.names > 3 and "  …" or "")
                TK.links[#TK.links + 1] = { x1 = cx1, y1 = y, x2 = cx1 + cw_, y2 = y + ch_, hov = "tkd" .. i, act = function() HV.TS.show({ eyebrow = os.date("%A %d %b", d.t), title = names }, 4) end }
            end
        end
        y = y + ch_ + K.gap
    end
    if #rows == 0 then
        if o.empty_states then HV.XV.empty(add, m, (tx + tr) / 2, y + K.fs3 * 1.2, "tracked", "Nothing tracked", "“+ Track” on a title page adds it")
        else K2.txt(tx, y + K.fs3, 4, K.fs3, 60, false, "Nothing yet - “+ Track” on a title page adds it") end
    end
    TK.sel = math.max(1, math.min(TK.sel, math.max(1, #rows)))
    if TK.sel < TK.top then TK.top = TK.sel elseif TK.sel >= TK.top + nvis then TK.top = TK.sel - nvis + 1 end
    TK.top = math.max(1, math.min(TK.top, math.max(1, #rows - nvis + 1)))
    local calv = HV.TK.view() == "calendar"
    for i = TK.top, math.min(#rows, TK.top + nvis - 1) do
        local r = rows[i]
        local e = r.e
        local ry = y + (i - TK.top) * rh
        if calv then
            local day = HV.TK.day_of(r)
            local prev = rows[i - 1] and HV.TK.day_of(rows[i - 1])
            if (i == TK.top or prev ~= day) then
                K2.txt(tr, ry + 1, 9, K.fs4 - 2, 60, true, day:upper(), (day == "Today") and TOAST.accent or nil, "\\fsp1")
            end
        end
        local ii = i
        TK.links[#TK.links + 1] = { x1 = tx - K.pad * 0.45, x2 = tr + K.pad * 0.45, y1 = ry, y2 = ry + rh, hov = "tk" .. i,
            act = function() TK.sel = ii; HV.TK.open_entry(e) end }
        local sel, hov = (i == TK.sel), (HV.btn_hover or ""):match("^tk%a?" .. i .. "$") ~= nil
        if sel or hov then
            add(D.ev_rect(tx - K.pad * 0.45, ry + 1, tr + K.pad * 0.45, ry + rh - 1, TOAST.text, sel and 10 or 5, TOAST.text, sel and 20 or 0, sel and K.fsp or 0, math.floor(10 * S)))
        end
        local py = ry + math.floor((rh - th) / 2)
        local f, fw, fh = HV.AX.image(e.poster, tw_, th, "poster")
        if f and #TK.pics < 6 then TK.pics[#TK.pics + 1] = { x = tx, y = py, f = f, w = tw_, h = th, sw = fw, sh = fh }
        else
            add(D.ev_rect(tx, py, tx + tw_, py + th, THEME.bg_panel, 100, nil, 0, 0, math.floor(4 * S)))
            if HV.img_loading(e.poster) then HV.shim_add(tx, py, tw_, th, true) end
        end
        -- the bell (its hint on hover) and, on the selected / hovered row, ✕ to untrack
        local bcx = tr - math.floor(K.pill_h / 2)
        local rcy = ry + rh / 2
        local bid = "tkb" .. i
        local bhot = HV.btn_hover == bid
        add(D.ev_rect(bcx - K.pill_h / 2, rcy - K.pill_h / 2, bcx + K.pill_h / 2, rcy + K.pill_h / 2, TOAST.text, bhot and 24 or 10, TOAST.text, bhot and 40 or 18, K.fsp, K.pill_h / 2))
        add(HV.TK.bell(bcx, rcy, K.pill_h * 0.5, e.bell == "off" and TOAST.text or (e.bell == "season" and TOAST.warn or TOAST.accent), e.bell == "off" and 45 or 100, e.bell == "off"))
        if e.bell == "season" then K2.txt(bcx + K.pill_h * 0.26, rcy + K.pill_h * 0.2, 5, math.max(8, K.fs4 - 3), 100, true, "S", TOAST.warn) end
        local k_ = r.k
        link(bcx - K.pill_h / 2, rcy - K.pill_h / 2, bcx + K.pill_h / 2, rcy + K.pill_h / 2, bid, function() HV.TK.cycle_bell(k_) end)
        local rx = bcx - K.pill_h / 2 - K.gap
        if sel or hov then
            rx = K2.pill(rx, rcy, "✕", "tkx" .. i, function() HV.TK.remove(k_); HV.last_data = nil; render() end) - K.gap
            TK.links[#TK.links].hov = "tkx" .. i
        end
        local lx = tx + tw_ + K.gap * 1.5
        local name = e.name .. ((e.year or "") ~= "" and ("  (" .. e.year .. ")") or "")
        local nfs = K.fs3
        local tag = e.new and "NEW" or nil
        local tagw = tag and (HV.AX.tw(tag, K.fs4 - 2, true) + K.fs4) or 0
        K2.txt(lx, rcy - K.fs3 * 0.62, 4, nfs, sel and 100 or 90, true, HV.scfit(name, rx - lx - tagw, nfs, true))
        if tag then
            local nx = lx + math.min(HV.AX.tw(name, nfs, true), rx - lx - tagw) + K.gap * 0.8
            add(D.ev_rect(nx, rcy - K.fs3 * 0.62 - K.fs4 * 0.62, nx + tagw - K.gap * 0.4, rcy - K.fs3 * 0.62 + K.fs4 * 0.62, TOAST.accent, 100, nil, 0, 0, K.fs4 * 0.4))
            K2.txt(nx + (tagw - K.gap * 0.4) / 2, rcy - K.fs3 * 0.62, 5, K.fs4 - 2, 100, true, tag, "FFFFFF")
        end
        K2.txt(lx, rcy + K.fs4 * 0.75, 4, K.fs4, r.col and 95 or 60, false, HV.scfit(r.line, rx - lx, K.fs4, false), r.col)
        -- the bell's hint, under it
        if bhot then
            local hint = HV.TK.bell_hint(e)
            local hw = HV.AX.tw(hint, K.fs4) + K.fs4 * 1.6
            local hx2, hy1 = bcx + K.pill_h / 2, rcy + K.pill_h / 2 + 4 * S
            add(D.ev_rect(hx2 - hw, hy1, hx2, hy1 + K.fs4 * 1.9, THEME.bg_header, 96, TOAST.edge, 30, K.fsp, K.fs4 * 0.95))
            K2.txt(hx2 - hw / 2, hy1 + K.fs4 * 0.95, 5, K.fs4, 90, false, hint)
        end
    end
    y = y + ((#rows == 0) and (K.fs3 * (o.empty_states and 7 or 3)) or (nvis * rh))
    if #rows > nvis then K2.txt(tr, y + K.gap * 0.4, 6, math.max(9, K.fs4 - 2), 45, false, string.format("%d of %d", math.min(#rows, TK.top + nvis - 1), #rows)) end
    y = y + K.gap
    K2.keys(tx, y + K.fs4 / 2, { { "↑↓", "Move" }, { "Enter", "Open" }, { "Space", "Bell" }, { "Del", "Untrack" }, { "Esc", "Close" } })
    -- the links of the body are the flyout's own (K2 wrote into P.links = TK.links)
end

function TV.toggle_more()
    TV.more = not TV.more
    HV.sig, HV.last_data = nil, nil
    HV.clear()
    render()
end

-- ---- actions ----
function TV.open(card)
    if not card then return end
    TV.auto = nil
    HV.saved = { r = HV.r, c = HV.c, top = HV.top, want_vc = HV.want_vc }
    TV.card = card
    TV.req = {}
    TV.season, TV.multi, TV.grid_pos = nil, nil, nil
    HV.bfocus, TV.more, TV.btns, HV.DLC = nil, nil, nil, nil
    HV.XA.title_n = HV.XA.title_n + 1                  -- each visit decodes its name again (experimental_decode)
    HV.mode = "title"
    log_view("title-page")
    HV.r, HV.c, HV.top, HV.want_vc, HV.hover = 1, 1, 1, 1, nil
    HV.sig, HV.last_data = nil, nil
    HV.clear()
    render()
end

function TV.back()
    HV.bfocus, TV.more, TV.btns, HV.DLC = nil, nil, nil, nil
    -- zoom: the poster you see goes back into its card
    local back_from = nil
    local hero = HV.hero
    if hero and TV.card and HV.TR.on() and HV.zoom() and not HV.TR.busy() and not TV.season then
        local hst = HV.items[hero.key]
        local f = hst and hst.bgra[HV.skey(hero.dw, hero.dh)]
        if f then back_from = { f = f, fw = hero.dw, fh = hero.dh, x = hero.x, y = hero.y, w = hero.dw, h = hero.dh, key = TV.card.key } end
    end
    HV.REV = nil
    HV.mode = "home"
    log_view(HV.q and "search-results" or "home")
    TV.card = nil
    HV.hero = nil
    local s = HV.saved or {}
    HV.r, HV.c, HV.top, HV.want_vc = s.r or 1, s.c or 1, s.top or 1, s.want_vc or 1
    HV.sig, HV.last_data, HV.hover = nil, nil, nil
    HV.clear()
    if back_from then HV.TR.start("back", back_from) end
    render()
end

-- What plays after `ep`: the following episodes, one file per episode - when a title holds two versions of the same
-- episode (two releases), the one from the same folder as the episode you started wins.
function TV.playlist_from(ep)
    local after, found = {}, false
    for _, x in ipairs(TV.ordered or {}) do
        if found then after[#after + 1] = x end
        if x.entry.href == ep.entry.href then found = true end
    end
    local list, slot = {}, {}
    local mytop = (ep.top or ep.folder or {}).href
    for _, x in ipairs(after) do
        local k = x.e and ((x.s or 0) .. ":" .. x.e) or nil
        if not k then list[#list + 1] = x.entry
        elseif k ~= ((ep.s or 0) .. ":" .. tostring(ep.e)) then
            local i = slot[k]
            if not i then list[#list + 1] = x.entry; slot[k] = #list
            elseif (x.top or x.folder or {}).href == mytop then list[i] = x.entry end
        end
    end
    return list
end

function TV.play(card)
    play_entry(card.entry, false, TV.playlist_from(card.ep))
end

-- ---------- library search inside the poster UI ----------
function HV.start_search()
    if not browser_active then return end
    if HV.typing then return end
    if HV.mode == "title" then
        HV.mode, HV.tv.card = "home", nil
        local sv = HV.saved or {}             -- where you were on the home page (Esc brings it back)
        HV.r, HV.c, HV.top, HV.want_vc = sv.r or 1, sv.c or 1, sv.top or 1, sv.want_vc or 1
    end
    unbind_all()
    HV.q = HV.q or ""
    HV.qa = HV.q
    HV.cur = #HV.q
    HV.typing = true
    search_query = HV.text_of(HV.q)
    run_global_search_hook()
    IDX.maybe_autostart()
    -- the page stays as it is until something is typed; Esc brings back where you were
    if HV.q == "" and not HV.sq_saved then HV.sq_saved = { r = HV.r, c = HV.c, top = HV.top, want_vc = HV.want_vc } end
    HV.sig, HV.last_data = nil, nil
    HV.bind_search()
    log_view("search-typing")
    render()
end

-- ---- the search box: a text cursor (HV.cur = bytes before it) that arrows, Home/End, Ctrl+arrows and clicks move ----
local function u8_is_cont(s, i) local b = s:byte(i); return b and b >= 128 and b < 192 end
function HV.cur_get() local q = HV.q or ""; HV.cur = math.max(0, math.min(#q, HV.cur or #q)); return HV.cur end
function HV.cur_prev(q, c) c = c - 1; while c > 0 and u8_is_cont(q, c + 1) do c = c - 1 end; return math.max(0, c) end
function HV.cur_next(q, c) c = c + 1; while c < #q and u8_is_cont(q, c + 1) do c = c + 1 end; return math.min(#q, c) end

-- The box shows every key at once; the results (fuzzy match over the whole library + the file index) follow 0.15 s
-- after you stop typing, so a big library never makes typing lag.
function HV.search_changed()
    HV.last_data = nil
    render()
    if HV.XA.on("live_search") then
        -- experimental_live_search: at most every 60 ms, the first key at once; a burst ends on what was typed last
        if HV.search_timer then return end
        local wait = math.max(0, 0.06 - (U.now_s() - (HV.XA.qa_t or 0)))
        HV.search_timer = mp.add_timeout(wait, function()
            HV.search_timer = nil
            HV.XA.qa_t = U.now_s()
            HV.apply_query()
        end)
        return
    end
    if HV.search_timer then HV.search_timer:kill() end
    HV.search_timer = mp.add_timeout(0.15, function()
        HV.search_timer = nil
        HV.apply_query()
    end)
end
function HV.apply_query()
    if not HV.q then return end
    local was = HV.qa or ""
    HV.qa = HV.q
    search_query = HV.text_of(HV.q)
    run_global_search_hook()
    if HV.q == "" then
        local sv = HV.sq_saved                 -- all deleted: the home page, where you were
        if sv and was ~= "" then HV.r, HV.c, HV.top, HV.want_vc = sv.r, sv.c, sv.top, sv.want_vc end
    else
        HV.r, HV.c, HV.top, HV.want_vc = 1, 1, 1, 1
        HV.jump_res = true                     -- the first result, not Continue Watching above it
    end
    HV.sig = nil
    render()
end

function HV.search_append(ch)
    local q, c = HV.q or "", HV.cur_get()
    HV.q = q:sub(1, c) .. ch .. q:sub(c + 1)
    HV.cur = c + #ch
    HV.XA.typed(true)
    HV.search_changed()
end

function HV.search_backspace()
    local q, c = HV.q or "", HV.cur_get()
    if c == 0 then return end
    local p = HV.cur_prev(q, c)
    HV.q, HV.cur = q:sub(1, p) .. q:sub(c + 1), p
    HV.XA.typed(false)
    HV.search_changed()
end

function HV.search_delete()
    local q, c = HV.q or "", HV.cur_get()
    if c >= #q then return end
    HV.q = q:sub(1, c) .. q:sub(HV.cur_next(q, c) + 1)
    HV.XA.typed(false)
    HV.search_changed()
end

-- dir = -1 / 1 one character, -2 / 2 one word, "home" / "end"
function HV.cur_move(dir)
    local q, c = HV.q or "", HV.cur_get()
    if dir == "home" then c = 0
    elseif dir == "end" then c = #q
    elseif dir == -1 then c = HV.cur_prev(q, c)
    elseif dir == 1 then c = HV.cur_next(q, c)
    elseif dir == -2 then
        while c > 0 and q:sub(c, c) == " " do c = c - 1 end
        while c > 0 and q:sub(c, c) ~= " " do c = c - 1 end
    elseif dir == 2 then
        while c < #q and q:sub(c + 1, c + 1) == " " do c = c + 1 end
        while c < #q and q:sub(c + 1, c + 1) ~= " " do c = c + 1 end
    end
    HV.cur = c
    HV.XA.typed(false)
    HV.last_data = nil
    render()
end

-- A click in the box puts the cursor at the nearest character (widths estimated like the rest of the layout).
function HV.cur_click(x)
    local b = HV.box
    if not b then return end
    local q = HV.q or ""
    local best, best_d, c = #q, math.huge, 0
    while true do
        local d = math.abs(b.x0 + U.utf8_len(q:sub(1, c)) * b.cw - x)
        if d < best_d then best, best_d = c, d end
        if c >= #q then break end
        c = HV.cur_next(q, c)
    end
    HV.cur = best
    HV.last_data = nil
    render()
end

function HV.stop_typing()
    if HV.typing then
        unbind_all()          -- also removes the typing keys
        bind_all()
    end
end

function HV.search_cancel()
    if HV.search_timer then HV.search_timer:kill(); HV.search_timer = nil end
    local typed = (HV.qa or HV.q or "") ~= ""
    HV.q, HV.qa = nil, nil
    search_query, search_scope = "", nil
    search_results, MS.global_total = {}, 0
    HV.stop_typing()
    local sv = HV.sq_saved
    HV.sq_saved = nil
    if sv then HV.r, HV.c, HV.top, HV.want_vc = sv.r, sv.c, sv.top, sv.want_vc
    else HV.r, HV.c, HV.top, HV.want_vc = 1, 1, 1, 1 end
    HV.sig, HV.last_data = nil, nil
    if typed then HV.clear() end
    log_view("home")
    render()
end

-- Leave the box for the results (the query stays; F or a click on the box edits it again).
function HV.to_results()
    if (HV.q or "") == "" then return HV.search_cancel() end      -- nothing typed: just the home page again
    HV.search_now()
    HV.stop_typing()
    HV.typing = false
    HV.last_data = nil
    render()
end

function HV.search_now()                 -- Enter / Down before the 0.15 s pause: use what is typed right away
    if HV.search_timer then HV.search_timer:kill(); HV.search_timer = nil; HV.apply_query() end
end

function HV.search_enter()
    HV.search_now()
    local card = HV.selected()
    if not card then return end
    HV.stop_typing()
    HV.activate()
end

MS.debug_extra = function()
    local L = {}
    if HV.mode == "title" and HV.tv.card then
        L[#L + 1] = "title page: " .. tostring(HV.tv.card.title) .. "  key " .. tostring(HV.tv.card.key)
    end
    local card = HV.selected()
    if card then
        local st = HV.items[card.key]
        local e = PS.idx and PS.idx[card.key]
        if card.kind == "ep" then
            L[#L + 1] = "episode: " .. tostring(card.dbg or "-")
        elseif card.kind == "missing" then
            L[#L + 1] = "missing: " .. tostring(card.miss and card.miss.name or ("E" .. tostring(card.miss and card.miss.e))) .. "  -  " .. tostring(card.reason)
        elseif card.kind == "season" then
            L[#L + 1] = "season folder " .. tostring(card.season) .. "  art " .. tostring(card.still and card.still.path or "none")
        else
            L[#L + 1] = string.format("selected: '%s' (%s%s)", card.title, card.kindpref ~= "" and card.kindpref or "any kind", card.year ~= "" and (", " .. card.year) or "")
            if type(e) == "table" and e.id then
                L[#L + 1] = string.format("TMDB: %s %s '%s' via '%s'", e.kind or "?", e.id, e.name or "?", tostring(e.q))
            elseif st and st.tried then
                L[#L + 1] = "TMDB: not found after: " .. table.concat(st.tried, " | ")
            else
                L[#L + 1] = "TMDB: " .. tostring(st and st.state or "pending")
            end
        end
    end
    if HV.mode == "title" then
        L[#L + 1] = "Real-Debrid: " .. (PS.rd_on() and (tostring(TV.rd_state) .. (PS.RD.err and ("  (" .. PS.RD.err .. ")") or "")) or "off (no rd_api_token)")
    end
    return L
end


function HV.show()
    log_view("home")
    MS.view = "home"
    HV.mode, TV.card = "home", nil
    PS.hide()
    HV.last_data, HV.sig = nil, nil
    unbind_all(); bind_all()
    render()
end

-- classic list view of a folder
function HV.open_folder(href)
    if not href then return end
    log_view("classic-list")
    MS.view = "browse"
    HV.clear()
    HV.last_data = nil
    unbind_all(); bind_all()
    reveal_path(href)
    set_focus("episodes")
    render()
end


function HV.activate()
    HV.last_act = U.now_s()
    if HV.CM.open then return HV.CM.run(HV.CM.sel or 1) end
    if HV.TK.is_open() then return HV.TK.enter() end
    if HV.dlc() then return TV.dl_go() end
    if HV.mode == "title" and HV.bfocus and TV.btns and TV.btns[HV.bfocus] then
        local b = TV.btns[HV.bfocus]
        if b.id ~= "dl" and b.id ~= "watched" then HV.bfocus = nil end
        return b.act()
    end
    local card = HV.selected()
    if not card then return end
    if HV.TR.st then return end                       -- a transition is running: this press is the same action
    local from = HV.TR.on() and HV.TR.from_selected() or nil
    local plays = card.kind == "ep" or card.kind == "play"
    if from and plays and o.auto_close_on_play then
        -- "Bleach  ·  S01E02" (Continue Watching), "Bleach  ·  S01E03 Episode title 3" (title page), a film's own name
        local what = card.shown or card.title
        if card.kind == "play" and card.parts and card.parts[1] and tostring(card.parts[1].t):match("^S?%d*E%d+") then
            what = what .. "  ·  " .. card.parts[1].t
        elseif card.kind == "ep" and TV.card and card.ep and card.ep.e then
            what = (TV.card.shown or TV.card.title) .. "  ·  " .. string.format("S%02dE%02d", card.ep.s or 1, card.ep.e)
        end
        HV.TR.start("play", from, { title = what })
        HV.place(); HV.TR.frame(); HV.fx_draw(); HV.flush()
    elseif from and card.kind == "folder" then
        HV.TR.start("open", from)
    end
    if card.kind == "ep" then TV.play(card)
    elseif card.kind == "season" then TV.enter_season(card.season)
    elseif card.kind == "missing" then
        status_line = "Unavailable: " .. tostring(card.reason)
        HV.say({ eyebrow = "NOT ON WEBDAV", title = tostring(card.reason), kind = "err" }, 3)
        render()
    elseif card.kind == "play" then play_entry(card.entry, false)
    else TV.open(card) end
end

function HV.open_list()
    local card = HV.selected()
    if HV.mode == "title" and TV.card then HV.open_folder(TV.card.href)
    elseif card then HV.open_folder(card.href) end
end

function HV.queue_selected()
    local card = HV.selected()
    if card and card.kind == "ep" then play_entry(card.entry, true) end
end

function HV.toggle_watched()
    local card = HV.selected()
    if card and card.kind == "ep" then toggle_watched(card.entry); HV.sig = nil; render() end
end

-- Forget the cached TMDB match of the selected title (and its episode data) so it is looked up again.
function HV.refetch()
    local card = HV.selected()
    if HV.mode == "title" then card = TV.card end
    if not card or not card.key then return end
    PS.load_index()
    local e = PS.idx[card.key]
    if type(e) == "table" and e.id then
        PS.load_eps()
        for k in pairs(PS.eps) do if k:match("^" .. e.id .. ":") then PS.eps[k] = nil end end
        PS.save_eps()
        PS.eps_ver = PS.eps_ver + 1
    end
    PS.idx[card.key] = nil
    PS.save_index()
    HV.items[card.key] = nil
    for k in pairs(HV.items) do if k:match("^still:") or k:match("^bd:") then HV.items[k] = nil end end
    TV.det_busy, TV.season_busy, TV.season_checked = nil, {}, nil
    HV.PF.done[card.key] = nil
    status_line = "Looking up " .. tostring(card.title) .. " again"
    HV.sig = nil
    render()
end

function HV.clear_cache_key()
    local now = U.now_s()
    if not HV.clear_armed then PS.recount(nil, true) end      -- the size it is about to delete, counted now
    local st = PS.stats()
    if HV.clear_armed and now - HV.clear_armed < 6 then
        HV.clear_armed = nil
        local n = PS.clear_cache()
        HV.GL.written, HV.GL.list = nil, nil          -- the blur shader's file went too: written again when needed
        HV.clear()
        HV.items, HV.convq, HV.sig = {}, {}, nil
        HV.LY.files, HV.fsz, HV.conv_out = {}, {}, {}
        HV.conv_gen = (HV.conv_gen or 0) + 1      -- a batch still converting belongs to the old cache: no warning for it
        HV.AX.imgs = {}
        PS.hide()
        TV.req, TV.season_busy, TV.det_busy, TV.season_checked = {}, {}, nil, nil
        HV.PF.done, HV.PF.extra, HV.TR.disp, HV.bad_file = {}, nil, {}, {}
        status_line = string.format("Cache cleared (%d files). Watch history was not touched.", n)
        load_root()
        render()
    else
        HV.clear_armed = now
        status_line = string.format("Press %s again to clear the cache (%s)",
            (tostring(o.cache_clear_key):match("[^%s,]+") or "key"):upper(), U.fmt_bytes(st.bytes))
        mp.add_timeout(6, function() if HV.clear_armed == now then HV.clear_armed = nil; HV.sig = nil; if browser_active then render() end end end)
        render()
    end
end

-- Messages in the top bar disappear 6 s after they appear ("Sort: Name", "Config reloaded"...); warnings stay longer.
function HV.status_visible()
    local st = status_line
    if not st or st == "" or st == "Ready" or st:match("^Loaded") then return false end
    -- an empty title page's card already tells what Real-Debrid is doing
    if HV.mode == "title" and (TV.count or 0) == 0 and st:find("still adding files", 1, true) then return false end
    local now = U.now_s()
    if st ~= HV.st_last then
        HV.st_last, HV.st_t = st, now
        mp.add_timeout(6.1, function() if HV.st_last == st and browser_active then HV.last_data = nil; render() end end)
        mp.add_timeout(15.1, function() if HV.st_last == st and browser_active then HV.last_data = nil; render() end end)
    end
    local keep = (st:match("^Failed") or st:match("^Press") or st:find("still adding", 1, true)) and 15 or 6
    return now - HV.st_t < keep
end

-- "WebDAV Library" crumb: straight back to the home screen (out of a title, out of a search).
function HV.go_home()
    if HV.mode == "title" then TV.back() end
    if HV.q or HV.typing then HV.search_cancel() return end
    HV.r, HV.c, HV.top, HV.want_vc = 1, 1, 1, 1
    HV.sig = nil
    render()
end
-- Mouse back button / Backspace: one level up, never closes the browser.
function HV.back()
    if HV.CM.open then return HV.CM.close() end
    if HV.TK.is_open() then return HV.TK.close() end
    if HV.dlc() then return HV.dl_close() end
    if HV.typing then HV.search_cancel()
    elseif HV.mode == "title" and TV.season and TV.multi then TV.leave_season()
    elseif HV.mode == "title" then TV.back()
    elseif HV.q then HV.search_cancel() end
end

function HV.esc()
    if HV.CM.open then return HV.CM.close() end
    if HV.TK.is_open() then return HV.TK.close() end
    if HV.dlc() then return HV.dl_close() end
    if HV.mode == "title" and TV.season and TV.multi then TV.leave_season()
    elseif HV.mode == "title" then TV.back()
    elseif HV.q then HV.search_cancel()
    else HV.XA.dismiss() end
end

function HV.hit_at(x, y)
    for _, hb in ipairs(HV.hit) do
        if x >= hb.x1 and x <= hb.x2 and y >= hb.y1 and y <= hb.y2 then return hb end
    end
    return nil
end

function HV.pad_hit()
    if not HV.pad_used then HV.pad_used = true; HV.last_data = nil end
end

function HV.on_move(val)
    if not HV.active() or not val then return end
    if HV.HP.open then return HV.HP.move(val) end
    if HV.XS.p and HV.XS.move(val.x, val.y) then HV.last_data = nil; return render() end      -- a row being dragged
    if HV.vsb_drag then return HV.vsb_to(val.y) end                                          -- the scroll bar held
    local vh = HV.mode ~= "add" and HV.vsb_hit(val.x, val.y) or nil
    if vh ~= HV.vsb_hot then HV.vsb_hot = vh; HV.last_data = nil; render() end
    if HV.mode == "add" then return HV.AX.on_move(val) end
    local redraw = false                   -- several changes in one move are one redraw
    local moved = HV.last_mouse and (math.abs(val.x - HV.last_mouse.x) > 3 or math.abs(val.y - HV.last_mouse.y) > 3)
    if HV.pad_used and moved then
        HV.pad_used = false; redraw = true            -- the mouse is back: normal focus ring again
    end
    if moved and HV.input ~= "mouse" then HV.mouse_input(); redraw = true end
    HV.last_mouse = { x = val.x, y = val.y }
    local lh, hh, bh = nil, nil, nil
    local dlc = HV.dlc() or (HV.TK.is_open() and { links = HV.TK.links }) or (HV.CM.open and { links = HV.CM.links }) or nil
    for _, ln in ipairs(dlc and dlc.links or HV.links or {}) do
        if val.x >= ln.x1 and val.x <= ln.x2 and val.y >= ln.y1 and val.y <= ln.y2 then
            if ln.crumb then lh = ln.crumb end
            if ln.hdr then hh = true end
            if ln.hov then bh = ln.hov end           -- a button (title page, the empty-page card)
        end
    end
    if lh ~= HV.link_hover or hh ~= HV.hdr_hover or bh ~= HV.btn_hover then
        HV.link_hover, HV.hdr_hover, HV.btn_hover = lh, hh, bh; redraw = true
    end
    local cr = HV.close_rect
    local ch = (cr and val.x >= cr.x1 and val.x <= cr.x2 and val.y <= cr.y2) or nil
    if ch ~= HV.close_hover then HV.close_hover = ch; redraw = true end
    local on_chev = bh and tostring(bh):match("^chev") ~= nil
    local hb = (not dlc and not on_chev and val.hover ~= false) and HV.hit_at(val.x, val.y) or nil
    local nh = hb and { r = hb.r, c = hb.c } or nil
    local same = (nh == nil and HV.hover == nil) or (nh and HV.hover and nh.r == HV.hover.r and nh.c == HV.hover.c)
    -- the Play button's tilt and the Continue Watching picture's float follow every move
    if bh == "play" and HV.XA.on("play_tilt") and HV.anim_on() then redraw = true end
    local prow = nh and HV.rows[nh.r]
    local pd = prow and HV.m and HV.rowdim(prow, HV.m)
    if same and not redraw and prow and HV.XA.par_on() and (prow.land or (HV.mode == "title" and pd and pd.cw > pd.ch)) then HV.place(); HV.flush() end
    if not same then
        -- the spotlight and the bigger picture follow the pointer at once (26.9 held them back during a sweep, which
        -- left the spotlight on the card you had just left for a moment: a flicker)
        HV.hover = nh
        HV.hover_t = U.now_s()
        redraw = true
        -- the hover buttons come after a short rest on the card, not while the pointer passes over it
        if nh and HV.MU_on() and o.hover_buttons ~= false then
            mp.add_timeout(0.3, function() if HV.hover == nh and browser_active then HV.last_data = nil; render() end end)
        end
        HV.reveal_arm(nh)
    end
    if redraw then HV.last_data = nil; render() end
end
-- a held key has been let go: the selected card may grow (the pointer never waits)
function HV.settled()
    if HV.mouse_mode() then return true end
    return not (HV.krep and U.now_s() - (HV.move_t or 0) < 0.11)
end
-- Resting the pointer on a card of the cut-off bottom row (bottom_reveal_secs) moves the page up one row; moving on
-- before then does nothing. Only a pointer move arms it, so a page that moved under a still pointer never runs on, and
-- after one reveal the pointer has to leave the cut-off row first (moving along the new bottom row used to chain them).
function HV.reveal_arm(nh)
    if HV.reveal_t then HV.reveal_t:kill(); HV.reveal_t = nil end
    local secs = tonumber(o.bottom_reveal_secs) or 0
    if not nh or secs <= 0 or not HV.mouse_mode() or HV.mode == "add" then HV.reveal_block = nil; return end
    local cut = false
    for _, v in ipairs(HV.vis or {}) do if v.ri == nh.r and v.cut then cut = true end end
    if not cut then HV.reveal_block = nil; return end
    if HV.reveal_block then return end
    HV.reveal_t = mp.add_timeout(secs, function()
        HV.reveal_t = nil
        if not browser_active or HV.hover ~= nh or not HV.mouse_mode() or HV.dlc() or HV.TK.is_open() or HV.CM.open then return end
        local row = HV.rows and HV.rows[nh.r]
        if not (row and row.cards[nh.c]) then return end
        HV.r, HV.c, HV.bfocus = nh.r, nh.c, nil
        HV.reveal_block = true
        HV.fix_off(HV.m)
        HV.want_vc = HV.vcol()
        HV.last_data = nil
        render()
        mp.add_timeout(HV.SCROLL_DUR + 0.1, function()
            if not browser_active or not HV.mouse_mode() or HV.hover ~= nh then return end
            local mx, my = U.mouse_xy()
            local hb = mx and HV.hit_at(mx, my)
            HV.hover = hb and { r = hb.r, c = hb.c } or nil
            HV.hover_t = U.now_s()
            HV.last_data = nil
            render()
        end)
    end)
end

function HV.mouse_down()
    if not HV.active() then return end
    if HV.HP.open then return HV.HP.click() end
    local mx, my = U.mouse_xy()
    if not mx then return end
    HV.mouse_input()
    if HV.CM.open then
        for i = #(HV.CM.links or {}), 1, -1 do
            local ln = HV.CM.links[i]
            if mx >= ln.x1 and mx <= ln.x2 and my >= ln.y1 and my <= ln.y2 then ln.act(); return end
        end
        return HV.CM.close()
    end
    if HV.TS.click(mx, my) then return end
    if HV.TK.is_open() then return HV.TK.click(mx, my) end
    if HV.dlc() then return HV.dl_click(mx, my) end
    local cr = HV.close_rect
    if cr and mx >= cr.x1 and mx <= cr.x2 and my <= cr.y2 then HV.XA.dismiss(); return end
    local left_typing = false
    if HV.typing then
        local on_box = false
        for _, ln in ipairs(HV.links or {}) do
            if ln.crumb == 97 and mx >= ln.x1 and mx <= ln.x2 and my >= ln.y1 and my <= ln.y2 then on_box = true end
        end
        -- (leaving the field binds the keys again: this click's release goes to the old binding, so nothing below
        -- may wait for it - no held scroll bar, no row press)
        if not on_box then HV.to_results(); left_typing = true end
    end
    for _, ln in ipairs(HV.links or {}) do
        if mx >= ln.x1 and mx <= ln.x2 and my >= ln.y1 and my <= ln.y2 then ln.act(mx, my); return end
    end
    if HV.vsb_hit(mx, my) then
        if left_typing then return end
        return HV.vsb_press(mx, my)
    end
    local hb = HV.hit_at(mx, my)
    if not hb then return end
    local g = HV.XS.on() and HV.rows[hb.r] and HV.rows[hb.r].xs_geo or nil
    if g and g.st and g.maxs > 0 and not left_typing then
        local ri, row0, mode0 = hb.r, HV.rows[hb.r], HV.mode
        HV.XS.press({ st = g.st, sx0 = g.sx, maxs = g.maxs, step = g.step,
            valid = function() return HV.active() and HV.mode == mode0 and HV.rows[ri] == row0 end,
            click = function() HV.mouse_act(hb) end,
            settle = function(n)
                local rw = HV.rows[ri]
                if rw then
                    rw.off = math.max(0, math.min(#rw.cards - g.per, n))
                    if HV.r == ri then HV.c = hv_clamp(HV.c, rw.off + 1, math.min(#rw.cards, rw.off + g.per)); HV.want_vc = HV.vcol() end
                end
                HV.last_data = nil
                render()
            end }, mx, my)
        return
    end
    return HV.mouse_act(hb)
end
-- what a click on a card does (HV.mouse_down, or the release of a press on a row that did not become a drag)
function HV.mouse_act(hb)
    local now = U.now_s()
    local dbl = HV.last_click and HV.last_click.r == hb.r and HV.last_click.c == hb.c and (now - HV.last_click_t) * 1000 <= o.double_click_ms
    HV.last_click, HV.last_click_t = { r = hb.r, c = hb.c }, now
    HV.r, HV.c, HV.bfocus = hb.r, hb.c, nil
    for _, v in ipairs(HV.vis or {}) do
        if v.ri == hb.r then HV.click_sel = not v.cut end        -- the peeking row at the bottom still scrolls in
    end
    HV.fix_off(HV.m)
    HV.want_vc = HV.vcol()
    -- single_click_open: one click opens a title / plays an episode (a second click inside double_click_ms is ignored)
    if o.single_click_open then
        if dbl then return end
        HV.last_act = now
        return HV.activate()
    end
    if dbl then HV.last_click = nil; HV.activate() else render() end
end

-- the thin scroll bar at the page's right edge (mouse UI): where you are among the rows; drag its thumb, or click the
-- track to jump there. HV.vsb = what was drawn (its hit area and thumb); HV.vsb_drag while it is held
function HV.vsb_draw(add, m, vis, top_y, bottom)
    HV.vsb = nil
    if not (HV.MU_on() and HV.mouse_mode()) or not HV.rows or HV.XA.exit then return end
    local n = #HV.rows
    local full = 0
    for _, v in ipairs(vis) do if not v.cut then full = full + 1 end end
    full = math.max(1, full)
    if n <= full then return end
    local S = m.S or 1
    local maxtop = n - full + 1
    local pad = math.floor(6 * S)
    local y1, y2 = top_y + pad, bottom - pad
    local th = y2 - y1
    if th < 40 * S then return end
    local thh = math.max(math.floor(28 * S), math.floor(th * full / n))
    local dr = HV.vsb_drag
    local frac = dr and dr.frac or ((HV.top - 1) / math.max(1, maxtop - 1))
    local ty1 = math.floor(y1 + (th - thh) * math.max(0, math.min(1, frac)) + 0.5)
    local hot = dr ~= nil or HV.vsb_hot
    local bw = hot and math.max(4, math.floor(7 * S)) or math.max(3, math.floor(4 * S))
    local x2 = m.w - math.max(4, math.floor(m.mx * 0.3))
    local x1 = x2 - bw
    if hot then add(D.ev_rect(x1, y1, x2, y2, THEME.track, 55, nil, 0, 0, bw / 2)) end
    add(D.ev_rect(x1, ty1, x2, ty1 + thh, hot and THEME.text_primary or THEME.text_muted, hot and 90 or 55, nil, 0, 0, bw / 2))
    HV.vsb = { x1 = x2 - math.floor(18 * S), x2 = m.w, y1 = y1, y2 = y2, ty1 = ty1, thh = thh, th = th, maxtop = maxtop, full = full }
end
function HV.vsb_hit(mx, my)
    local b = HV.vsb
    return b and mx and mx >= b.x1 and mx <= b.x2 and my >= b.y1 - 4 and my <= b.y2 + 4
end
function HV.vsb_press(mx, my)
    local b = HV.vsb
    local on_thumb = my >= b.ty1 and my <= b.ty1 + b.thh
    HV.vsb_drag = { grab = on_thumb and (my - b.ty1) or math.floor(b.thh / 2) }
    HV.vsb_to(my)
end
function HV.vsb_to(my)
    local b, dr = HV.vsb, HV.vsb_drag
    if not (b and dr) then return end
    dr.frac = math.max(0, math.min(1, (my - dr.grab - b.y1) / math.max(1, b.th - b.thh)))
    local top = 1 + math.floor(dr.frac * (b.maxtop - 1) + 0.5)
    if top ~= HV.top then
        HV.top = top
        if HV.r < top or HV.r > top + b.full - 1 then
            HV.r = top
            local row = HV.rows[top]
            HV.c = hv_clamp(HV.c, 1, math.max(1, row and #row.cards or 1))
        end
        HV.hover = nil
    end
    HV.last_data = nil
    render()
end
function HV.mouse_up()
    if HV.vsb_drag then HV.vsb_drag = nil; HV.last_data = nil; return render() end
    if not HV.XS.p then return end
    local dragged = HV.XS.p.dragging
    HV.XS.release()
    if dragged then HV.rehit_after_glide() end
end
-- a row moved sideways under the pointer: no card is under it while it glides; then the one that is now
function HV.rehit_after_glide()
    if not HV.mouse_mode() then HV.last_data = nil; return render() end
    HV.hover = nil
    HV.last_data = nil
    render()
    local t0 = U.now_s()
    HV.rehit_t = t0
    mp.add_timeout(HV.XS.DUR + 0.04, function()
        if HV.rehit_t ~= t0 or not browser_active or not HV.mouse_mode() or HV.XS.p then return end
        HV.last_data = nil
        render()
        local mx, my = U.mouse_xy()
        local hb = mx and HV.hit_at(mx, my) or nil
        HV.hover = hb and { r = hb.r, c = hb.c } or nil
        HV.hover_t = U.now_s()
        HV.last_data = nil
        render()
    end)
end
-- the sideways wheel (a touchpad's swipe): the row under the pointer (or the selected one) one card on; past an end, the bounce
function HV.on_hwheel(dir)
    if not HV.active() or HV.HP.open or HV.CM.open or HV.TK.is_open() or HV.dlc() then return end
    local now, ri = U.now_s(), nil
    local hw = HV.hw_last
    if hw and now - hw.t < 0.5 and HV.rows and HV.rows[hw.r] == hw.row then ri = hw.r end     -- the rest of one swipe
    if not ri and HV.mouse_mode() then
        local mx, my = U.mouse_xy()
        local hb = mx and HV.hit_at(mx, my) or nil
        ri = (hb and hb.r) or (HV.hover and HV.hover.r)
    end
    ri = ri or HV.r
    local row = HV.rows and HV.rows[ri]
    if not (row and row.shelf) then return end
    HV.hw_last = { r = ri, row = row, t = now }
    local per = HV.rowdim(row, HV.m).per
    local n = (row.off or 0) + dir
    if n < 0 or n > math.max(0, #row.cards - per) then HV.XA.bump("h", ri, dir); HV.last_data = nil; return render() end
    row.off = n
    if HV.r == ri then HV.c = hv_clamp(HV.c, n + 1, math.min(#row.cards, n + per)); HV.want_vc = HV.vcol() end
    if HV.XS.on() and HV.anim_on() then return HV.rehit_after_glide() end
    HV.last_data = nil
    render()
end
function HV.mouse_dbl()
    if not HV.active() or HV.HP.open then return end
    if HV.XS.p and not HV.XS.p.dragging then HV.XS.p.click = nil end      -- the double-click acts; its release does not
    if HV.XS.drag_t and U.now_s() - HV.XS.drag_t < 0.5 then return end        -- (the end of a drag)
    if HV.CM.open then return end
    if HV.dlc() or HV.TK.is_open() then return end
    if U.now_s() - (HV.last_act or 0) < 0.4 then return end
    local mx, my = U.mouse_xy()
    local hb = mx and HV.hit_at(mx, my)
    if not hb then return end
    HV.r, HV.c, HV.bfocus = hb.r, hb.c, nil
    HV.last_click = nil
    HV.activate()
end

function HV.on_wheel(dir)
    if not HV.active() then return end
    if HV.reveal_t then HV.reveal_t:kill(); HV.reveal_t = nil end
    if HV.CM.open then return HV.CM.close() end
    if HV.TK.is_open() then return HV.TK.move(dir) end
    if HV.dlc() then return TV.dl_move(dir) end
    if HV.bfocus then HV.bfocus = nil end
    -- a notch soon after another goes on from where that one went: the card "under the pointer" is not known again
    -- until the page has stopped (taking it from where the cards WERE made every other notch do nothing)
    local now = U.now_s()
    local chained = HV.wheel_t and now - HV.wheel_t < HV.SCROLL_DUR + 0.2
    HV.wheel_t = now
    if HV.mouse_mode() and HV.vis and #HV.vis > 0 and not chained then
        if HV.hover and HV.rows[HV.hover.r] then HV.r, HV.c = HV.hover.r, HV.hover.c
        else
            local v = (dir > 0) and HV.vis[#HV.vis] or HV.vis[1]
            if v.cut and #HV.vis > 1 then v = HV.vis[#HV.vis - 1] end
            HV.r = v.ri
        end
    end
    if dir < 0 and HV.mode == "title" and HV.r <= 1 then return render() end   -- the wheel never lands on the buttons
    local top0 = HV.top
    HV.move(dir, 0)
    if HV.mouse_mode() then
        local function rehit()
            local mx, my = U.mouse_xy()
            local hb = mx and HV.hit_at(mx, my) or nil
            local h0 = HV.hover
            HV.hover = hb and { r = hb.r, c = hb.c } or nil
            if h0 and hb and h0.r == hb.r and h0.c == hb.c then return end        -- the same card: nothing to redraw
            HV.hover_t = U.now_s()
            HV.last_data = nil
            render()
        end
        if HV.top == top0 then return rehit() end          -- the page did not move: the pointer's card is where it was
        HV.hover = nil
        HV.last_data = nil
        render()
        local tries = 0
        local function after()
            if HV.wheel_t ~= now or not browser_active or not HV.mouse_mode() then return end
            tries = tries + 1
            if HV.scrolling() and tries < 12 then mp.add_timeout(0.05, after); return end
            HV.last_data = nil
            render()                    -- the glide's frames only move the pictures: the hit boxes are made again here
            rehit()
        end
        mp.add_timeout(HV.SCROLL_DUR + 0.02, after)
    end
end
function HV.right_click()
    if not HV.active() then return end
    local mx, my = U.mouse_xy()
    if not mx then return end
    if HV.CM.open then return HV.CM.close() end
    if HV.TK.is_open() then return HV.TK.close() end
    if HV.dlc() then return HV.dl_close() end
    local hb = HV.hit_at(mx, my)
    local row = hb and HV.rows[hb.r]
    local card = row and row.cards[hb.c]
    if card then return HV.CM.show(card, mx, my) end
    if o.right_click_back then HV.back() end
end

function HV.refresh()
    HV.sig = nil
    if HV.mode == "title" and TV.card then
        TV.req, TV.fail = {}, {}
        local list, seen = {}, {}
        local function walk(href, depth)
            if seen[href] or depth > 3 then return end
            seen[href] = true
            list[#list + 1] = href
            local c = find_cached_dir(href)
            if c and type(c.entries) == "table" then
                for _, e in ipairs(c.entries) do if e.is_dir then walk(e.href, depth + 1) end end
            end
        end
        for _, f in ipairs(TV.card.folders or {}) do walk(f.href, 0) end
        local left = #list
        status_line = string.format("Refreshing %d folder%s…", left, left == 1 and "" or "s")
        for _, href in ipairs(list) do
            local c = find_cached_dir(href)
            if c then c.stale = true; c._t = (c._t or 0) + 1 end
            fetch_listing(href, { silent = true, urgent = true }, function()
                left = left - 1
                if left <= 0 then status_line = "Refreshed"; HV.sig = nil; render() end
            end)
        end
        if PS.RD then PS.RD.list_t, PS.RD.info = 0, {} end
        render()
    else
        refresh_all()
    end
end


-- ============================================================
-- MAIN RENDER
-- ============================================================
render = function()
    if browser_active and HV.resizing then return end       -- the window is being resized: draw once it settles
    if browser_active and HV.DR and HV.DR.open then return end   -- the setup check is on top: the browser waits
    if not browser_active then
        overlay:remove()
        HV.clear_text()
        MS.last_overlay_data = nil
        PS.hide()
        HV.clear()
        return
    end
    if MS.view == "home" then return HV.render() end
    HV.fx_clear()                                         -- the list view has no animation layer

    layout = compute_layout()
    keep_selection_in_view()

    local w, h = layout.w, layout.h
    local sidebar, list = layout.sidebar, layout.list
    local fs = layout.fs
    local chunks, hitboxes, buttons = {}, {}, {}
    local cur_err = listing_error[current_path]
    local any_fail = cur_err or listing_error[root_href]

    table.insert(chunks, D.ev_rect(0, 0, w, h, THEME.bg_dim, o.dim_background_pct, nil, 0, 0))

    -- ---- header ----
    table.insert(chunks, D.ev_rect(0, 0, w, layout.header_h, THEME.bg_header, o.header_opacity, nil, 0, 0))
    table.insert(chunks, D.ev_rect(0, layout.header_h - 2, w, layout.header_h,
        THEME.grad_top, 35, nil, 0, 0))
    table.insert(chunks, D.ev_text(14, layout.header_h / 2 - 8, 4,
        string.format("\\b1\\fs%d\\c%s", fs + 4, U.ass_color(THEME.text_primary)), "WebDAV Browser"))
    table.insert(chunks, D.ev_text(14, layout.header_h / 2 + 12, 4,
        string.format("\\fs%d\\c%s", fs - 6, U.ass_color(THEME.text_muted)), U.ass_escape(host_label)))

    -- the connection, right-aligned and kept apart from the close button; offline says how to retry
    -- the connection pill and the close button, in the toast look (faint glass, hairline edge), one height
    -- "Connected" only once the server has answered: while the first listing is on its way it says so
    local st_txt = any_fail and ("Offline  ·  " .. U.kname("refresh") .. " to retry") or (is_loading and "Loading…") or "Connected"
    local sfs = fs - 6
    local ph = math.floor(sfs * 1.9 + 0.5)
    local bcx, bcy = w - 16 - ph / 2, math.floor(layout.header_h / 2)
    table.insert(chunks, D.ev_pill(bcx - ph / 2, bcy - ph / 2, bcx + ph / 2, bcy + ph / 2, ph / 2, 1))
    table.insert(chunks, D.ev_shape(D.cross_path(bcx, bcy, ph * 0.2, math.max(1, ph * 0.045)), THEME.text_muted, 100))
    table.insert(buttons, { x1 = bcx - ph / 2 - 6, y1 = bcy - ph / 2 - 4, x2 = bcx + ph / 2 + 6, y2 = bcy + ph / 2 + 4, action = "close" })
    local dr = math.max(3, math.floor(sfs * 0.2 + 0.5))
    local sx2 = bcx - ph / 2 - 10
    local sx1 = sx2 - HV.AX.tw(st_txt, sfs) - ph * 0.95 - dr * 2 - sfs * 0.5
    table.insert(chunks, D.ev_pill(sx1, bcy - ph / 2, sx2, bcy + ph / 2, ph / 2, 1, any_fail and THEME.bad or "FFFFFF", any_fail and 14 or 6))
    table.insert(chunks, D.ev_rect(sx1 + ph * 0.5 - dr, bcy - dr, sx1 + ph * 0.5 + dr, bcy + dr, any_fail and THEME.bad or (is_loading and THEME.warn or THEME.good), 100, nil, 0, 0, dr))
    table.insert(chunks, D.ev_text(sx1 + ph * 0.5 + dr + sfs * 0.5, bcy, 4,
        string.format("\\fs%d\\c%s", sfs, U.ass_color(any_fail and THEME.bad or THEME.text_primary)), U.ass_escape(st_txt)))
    if IDX.running then
        table.insert(chunks, D.ev_text(sx1 - 12, bcy, 6,
            string.format("\\fs%d\\c%s", sfs, U.ass_color(THEME.accent)),
            string.format("%s indexing %d", spinner_frames[spinner_idx], IDX.scanned)))
    end

    local function paint_panel(rect, focused)
        local bg = focused and THEME.bg_panel or THEME.bg_panel_dim
        local bw = focused and o.border_width_focus or o.border_width_unfocus
        local border_alpha = focused and math.min(100, o.border_alpha + 18) or o.border_alpha

        table.insert(chunks, D.ev_rect(rect.x1, rect.y1, rect.x2, rect.y2, bg, o.panel_opacity, nil, 0, 0, o.corner_radius))

        if o.border_gradient_enabled then
            D.draw_gradient_border(chunks, rect.x1, rect.y1, rect.x2, rect.y2, o.corner_radius, bw,
                { THEME.grad_top,
                  THEME.grad_mid,
                  THEME.grad_bottom },
                border_alpha)
        else
            table.insert(chunks, D.ev_rect(rect.x1, rect.y1, rect.x2, rect.y2, THEME.border_unfocus, 0, THEME.border_unfocus, border_alpha, bw, o.corner_radius))
        end

        if o.glass_highlight_enabled then
            D.draw_glass_highlight(chunks, rect.x1, rect.y1, rect.x2, rect.y2, o.corner_radius, bw)
        end
    end
    paint_panel(sidebar, focus_panel == "sidebar")
    paint_panel(list,    focus_panel == "episodes")
    if layout.poster then PS.draw_panel(chunks, layout.poster, paint_panel) end

    -- ---- Folders panel header ----
    local sb_focus = focus_panel == "sidebar"
    table.insert(chunks, D.ev_text(sidebar.x1 + 12, sidebar.y1 + 16, 4,
        string.format("\\b1\\fs%d\\c%s", fs, U.ass_color(sb_focus and THEME.accent or THEME.text_primary)),
        (sb_focus and "▸  " or "") .. "Folders"))

    if search_scope == "sidebar" and search_active then
        draw_search_indicator(chunks, sidebar, sidebar.y1 + layout.sub_line_y, #get_panel_items("sidebar"), true)
    elseif search_scope == "sidebar" and search_query ~= "" then
        draw_search_indicator(chunks, sidebar, sidebar.y1 + layout.sub_line_y, #get_panel_items("sidebar"), false)
    else
        local crumb = (current_path == CW_HREF) and "Continue Watching"
            or build_breadcrumb(current_path, sidebar.x2 - sidebar.x1 - 24)
        table.insert(chunks, D.ev_text(sidebar.x1 + 12, sidebar.y1 + layout.sub_line_y, 4,
            string.format("\\fs%d\\c%s", fs - 6, U.ass_color(THEME.text_muted)), U.ass_escape(crumb)))
    end

    table.insert(buttons, {
        x1 = sidebar.x1, y1 = sidebar.y1, x2 = sidebar.x2, y2 = sidebar.y1 + layout.panel_header_h,
        action = "focus_sidebar",
    })

    -- ---- Files panel header ----
    local ep_focus = focus_panel == "episodes"
    local title
    if search_scope == "global" then title = "Search: whole library"
    elseif current_path == CW_HREF then title = "Continue Watching"
    else
        title = U.basename(current_path)
        if title == "" then title = "Root" end
        if o.clean_titles and o.clean_folder_titles then
            local fp = CT.parse_folder(title)
            if fp then
                title = fp.title .. (fp.season and ("  " .. fp.season) or "") .. (fp.group and ("  " .. fp.group) or "")
            end
        end
    end
    table.insert(chunks, D.ev_text(list.x1 + 12, list.y1 + 16, 4,
        string.format("\\b1\\fs%d\\c%s", fs, U.ass_color(ep_focus and THEME.accent or THEME.text_primary)),
        (ep_focus and "▸  " or "") .. U.ass_escape(U.fit_text(title, (list.x2 - list.x1) * 0.55, fs))))

    local ep_items = get_panel_items("episodes")
    local vis_ep = visible_rows_for(list, layout.panel_header_h, layout.row_h)

    if search_scope == "global" and search_active then
        draw_search_indicator(chunks, list, list.y1 + layout.sub_line_y, MS.global_total, true)
    elseif search_scope == "global" and search_query ~= "" then
        draw_search_indicator(chunks, list, list.y1 + layout.sub_line_y, MS.global_total, false)
    elseif search_scope == "episodes" and search_active then
        draw_search_indicator(chunks, list, list.y1 + layout.sub_line_y, #ep_items, true)
    elseif search_scope == "episodes" and search_query ~= "" then
        draw_search_indicator(chunks, list, list.y1 + layout.sub_line_y, #ep_items, false)
    else
        local from = math.min(#ep_items, scroll_offset_episodes + 1)
        local to   = math.min(#ep_items, scroll_offset_episodes + vis_ep)
        local range = (#ep_items == 0) and "0 files" or string.format("%d–%d / %d files", from, to, #ep_items)
        if hide_watched and current_path ~= CW_HREF then range = range .. "   (watched hidden)" end
        table.insert(chunks, D.ev_text(list.x1 + 12, list.y1 + layout.sub_line_y, 4,
            string.format("\\fs%d\\c%s", fs - 6, U.ass_color(THEME.text_muted)), U.ass_escape(range)))
    end

    -- sort chip (per-folder sort memory); not shown for virtual lists
    if current_path ~= CW_HREF and search_scope ~= "global" then
        local recent = (sort_mode_for(current_path) == "recent")
        table.insert(chunks, D.ev_rect(list.x2 - 120, list.y1 + 4, list.x2 - 8, list.y1 + 32,
            "FFFFFF", 6, nil, 0, 0, o.corner_radius_small))
        table.insert(chunks, D.ev_text(list.x2 - 14, list.y1 + 16, 6,
            string.format("\\fs%d\\c%s", fs - 6, U.ass_color(THEME.accent)),
            "Sort: " .. (recent and "Recent" or "Name")))
        table.insert(buttons, { x1 = list.x2 - 120, y1 = list.y1 + 4, x2 = list.x2 - 8, y2 = list.y1 + 32, action = "sort" })
    end
    table.insert(buttons, {
        x1 = list.x1, y1 = list.y1, x2 = list.x2 - 120, y2 = list.y1 + layout.panel_header_h,
        action = "focus_episodes",
    })

    -- ---- bodies ----
    local root_first_load = is_loading and current_path == root_href and #root_children == 0

    if root_first_load then
        table.insert(chunks, D.ev_text((sidebar.x1 + sidebar.x2) / 2, (sidebar.y1 + sidebar.y2) / 2, 5,
            string.format("\\fs%d\\c%s", fs + 2, U.ass_color(THEME.text_muted)),
            spinner_frames[spinner_idx] .. "  Loading..."))
    else
        draw_sidebar_rows(chunks, hitboxes, sidebar)
    end

    local files_loading = is_loading and #file_entries == 0 and current_path ~= CW_HREF and search_scope ~= "global"
    if root_first_load or files_loading then
        table.insert(chunks, D.ev_text((list.x1 + list.x2) / 2, (list.y1 + list.y2) / 2, 5,
            string.format("\\fs%d\\c%s", fs + 2, U.ass_color(THEME.text_muted)),
            spinner_frames[spinner_idx] .. "  Loading..."))
    elseif cur_err and #file_entries == 0 and search_scope ~= "global" then
        local cx_, cy_ = (list.x1 + list.x2) / 2, (list.y1 + list.y2) / 2
        table.insert(chunks, D.ev_text(cx_, cy_ - 10, 5,
            string.format("\\fs%d\\c%s", fs, U.ass_color(THEME.bad)), "⚠  " .. U.ass_escape(cur_err)))
        table.insert(chunks, D.ev_text(cx_, cy_ + 18, 5,
            string.format("\\fs%d\\c%s", fs - 6, U.ass_color(THEME.text_muted)), "Press R to retry"))
    else
        draw_episode_rows(chunks, hitboxes, list)
    end

    -- ---- footer ----
    table.insert(chunks, D.ev_rect(0, h - layout.footer_h, w, h, THEME.bg_header, o.footer_opacity, nil, 0, 0))
    table.insert(chunks, D.ev_rect(0, h - layout.footer_h, w, h - layout.footer_h + 2,
        THEME.grad_top, 35, nil, 0, 0))
    local hint
    if search_active then
        hint = "Type to search   ↑↓ Results   Enter Confirm   Esc Cancel"
    else
        hint = U.hint({ "↑↓ Move", { "switch_panel", "Panel" }, { "open", "Play/Open" }, { "back", "Up" }, { "search_folder", "Filter" },
            { "search", "Search all" }, { "queue", "Queue" }, { "play_download", "Download+play" }, { "sort", "Sort" }, { "refresh", "Refresh" },
            { "watched", "Watched" }, { "hide_watched", "Hide" }, { "debug", "Debug" }, { "switch_view", "Home" }, { "close", MS.from_home and "Back" or "Close" } })
    end
    table.insert(chunks, D.ev_text(14, h - layout.footer_h + 16, 4,
        string.format("\\fs%d\\c%s", fs - 6, U.ass_color(THEME.text_muted)),
        U.ass_escape(U.fit_text(hint, w - 28, fs - 6))))
    local st_col = (status_line:match("^Failed") or status_line:match("^Couldn't")) and THEME.bad or THEME.good
    table.insert(chunks, D.ev_text(14, h - layout.footer_h + 38, 4,
        string.format("\\fs%d\\c%s", fs - 4, U.ass_color(st_col)), U.ass_escape(U.fit_text(status_line, w * 0.55, fs - 4))))
    if search_scope == "global" or IDX.running then
        table.insert(chunks, D.ev_text(w - 14, h - layout.footer_h + 38, 6,
            string.format("\\fs%d\\c%s", fs - 6, U.ass_color(THEME.text_muted)),
            U.ass_escape(U.fit_text(IDX.summary(), w * 0.42, fs - 6))))
    end

    -- ---- debug panel ----
    if MS.debug then
        local lines = build_debug_lines()
        local dfs = math.max(11, fs - 8)
        local lh = math.floor(dfs * 1.55)
        local dw = math.min(math.floor(w * 0.5), 760)
        local dx2, dy1 = w - 16, layout.header_h + 12
        local dx1, dy2 = dx2 - dw, dy1 + #lines * lh + 16
        table.insert(chunks, D.ev_rect(dx1, dy1, dx2, dy2, THEME.bg_header, 88, THEME.accent, 60, 1, o.corner_radius_small))
        for i, line in ipairs(lines) do
            table.insert(chunks, D.ev_text(dx1 + 12, dy1 + 8 + (i - 0.5) * lh, 4,
                string.format("\\fs%d\\c%s%s", dfs, U.ass_color(i == 1 and THEME.accent or THEME.text_primary), i == 1 and "\\b1" or ""),
                U.ass_escape(U.fit_text(line, dw - 24, dfs))))
        end
    end

    -- ---- hover tooltip: full release name for rows whose title was cleaned ----
    local tip_name
    local function hover_is_live()
        local mx, my = U.mouse_xy()
        if not mx then return false end
        for _, hb in ipairs(hitboxes) do
            if hb.panel == hover_panel and hb.index == hover_index and mx >= hb.x1 and mx <= hb.x2 and my >= hb.y1 and my <= hb.y2 then
                return true
            end
        end
        return false
    end
    if o.clean_titles and o.clean_titles_tooltip and hover_index and not MS.drag and hover_is_live() then
        if hover_panel == "episodes" and search_scope ~= "global" then
            local it = ep_items[hover_index]
            if it and not it.is_dir and U.is_media(it.name) and CT.parse(it.name) then tip_name = it.name end
        elseif hover_panel == "sidebar" and o.clean_folder_titles then
            local nd = get_panel_items("sidebar")[hover_index]
            if nd and not nd.virtual and CT.parse_folder(nd.name) then tip_name = nd.name end
        end
    end
    if tip_name then
        do
            local mx, my = U.mouse_xy()
            if mx then
                local tfs = fs - 4
                local txt = U.fit_text(tip_name, w * 0.7, tfs)
                local tw = U.utf8_len(txt) * tfs * 0.58 + 24
                local tx1 = math.min((layout.poster and (layout.poster.x1 - 6) or w - 10) - tw, math.max(10, mx + 14))
                local ty1 = math.min(h - layout.footer_h - 34, my + 22)
                table.insert(chunks, D.ev_rect(tx1, ty1, tx1 + tw, ty1 + tfs * 1.9, THEME.bg_header, 94, THEME.accent, 55, 1, o.corner_radius_small))
                table.insert(chunks, D.ev_text(tx1 + 12, ty1 + tfs * 0.95, 4,
                    string.format("\\fs%d\\c%s", tfs, U.ass_color(THEME.text_primary)), U.ass_escape(txt)))
            end
        end
    end

    row_hitboxes, button_hitboxes = hitboxes, buttons
    local data = table.concat(chunks, "\n")
    local res_key = w .. "x" .. h
    if data ~= MS.last_overlay_data or res_key ~= MS.last_res then
        MS.last_overlay_data, MS.last_res = data, res_key
        overlay.data = data
        overlay:update()
    end
    PS.update()
end

-- ============================================================
-- MOUSE
-- ============================================================
function U.mouse_xy()
    local m = mp.get_property_native("mouse-pos")
    if not m or m.hover == false then return nil end
    return m.x, m.y
end

-- Keys of one browser action from the conf (key_<name>); right_click_back adds the right mouse button to "back".
function U.kb(name)
    local out = {}
    for k in tostring(o["key_" .. name] or ""):gmatch("[^%s,]+") do out[#out + 1] = k end
    if name == "back" and o.right_click_back and not o.experimental_mouse_ui then out[#out + 1] = "MBTN_RIGHT" end
    return out
end
-- How a key is written in the footer hints: the first key of the action ("ENTER" -> "Enter", "ctrl+d" -> "Ctrl+D")
function U.knice(k)
    return (tostring(k or ""):gsub("(%a)(%w*)", function(a, b) return a:upper() .. b:lower() end))
end
function U.kname(name)
    local k = U.kb(name)[1]
    if not k then return "" end
    local nice = { ENTER = "Enter", ESC = "Esc", BS = "Backspace", MBTN_BACK = "Mouse-back", MBTN_RIGHT = "Right-click",
                   PGUP = "PgUp", PGDWN = "PgDn", HOME = "Home", END = "End", TAB = "Tab", SPACE = "Space" }
    if nice[k] then return nice[k] end
    if #k == 1 then return k:upper() end
    return (k:gsub("(%a)(%w*)", function(a, b) return a:upper() .. b:lower() end))
end

-- footer hint from { {action, label}, "literal", ... }: actions with no key set are left out
function U.hint(parts)
    local out = {}
    for _, p in ipairs(parts) do
        if type(p) == "string" then if p ~= "" then out[#out + 1] = p end
        else
            local k = U.kname(p[1])
            if k ~= "" then out[#out + 1] = k .. " " .. p[2]; U.HRAW[k .. " " .. p[2]] = U.kb(p[1])[1] end
        end
    end
    return table.concat(out, "   ")
end
function U.point_in(x, y, r)
    return x >= r.x1 and x <= r.x2 and y >= r.y1 and y <= r.y2
end

do   -- mouse handling lives in its own scope (keeps the main chunk under Lua 5.1's 200-local limit)
-- ---------- scrolling helpers ----------
local function scroll_value(panel)
    return (panel == "sidebar") and scroll_offset_folders or scroll_offset_episodes
end

-- Sets a panel's scroll offset directly (wheel / scrollbar). Marks the panel "free" so the view
-- stays where the user put it until the selection moves again.
local function set_scroll(panel, v)
    local info = layout and layout.scroll_info and layout.scroll_info[panel]
    local mx = info and info.max_scroll or 0
    v = math.max(0, math.min(mx, math.floor(v + 0.5)))
    if panel == "sidebar" then scroll_offset_folders = v else scroll_offset_episodes = v end
    free_scroll[panel] = true
end

-- scrollbar under the pointer (the grab area is wider than the drawn bar)
local function scrollbar_at(mx, my)
    if not layout or not layout.scrollbars then return nil end
    for panel, sb in pairs(layout.scrollbars) do
        if mx >= sb.hx1 and mx <= sb.hx2 and my >= sb.y1 and my <= sb.y2 then return panel, sb end
    end
    return nil
end

local function drag_to(y)
    local d = MS.drag
    if not d or not layout then return end
    local sb = layout.scrollbars[d.panel]
    if not sb then return end
    local travel = math.max(1, sb.track_h - sb.thumb_h)
    set_scroll(d.panel, ((y - d.grab - sb.y1) / travel) * sb.max_scroll)
end

-- ---------- clicks ----------
-- Folders panel: the arrow toggles expand/collapse only; the rest of the row opens the folder.
-- Files panel: a click selects, a DOUBLE-click plays (or reveals a folder result).
local function click_row(hb, is_double)
    if hb.arrow then
        local node = get_panel_items("sidebar")[hb.index]
        if node then
            sidebar_selected_index = hb.index
            free_scroll.sidebar = false
            toggle_expand(node)
        end
        return
    end
    if hb.panel == "sidebar" then
        sidebar_selected_index = hb.index
        free_scroll.sidebar = false
        if focus_panel ~= "sidebar" then set_focus("sidebar") end
        local node = get_panel_items("sidebar")[hb.index]
        if node then open_folder_node(node) end
        return
    end
    selected_episode = hb.index
    free_scroll.episodes = false
    if focus_panel ~= "episodes" then set_focus("episodes") end
    if is_double then open_selected(false) else render() end
end

local function mouse_down()
    if not browser_active then return end
    local mx, my = U.mouse_xy()
    if not mx then return end

    for _, b in ipairs(button_hitboxes) do
        if (b.action == "close" or b.action == "sort") and U.point_in(mx, my, b) then
            if b.action == "close" then close_browser() else toggle_sort(current_path) end
            return
        end
    end

    local panel, sb = scrollbar_at(mx, my)
    if panel then
        if my >= sb.ty1 and my <= sb.ty2 then
            MS.drag = { panel = panel, grab = my - sb.ty1 }          -- grab the thumb
        else
            set_scroll(panel, scroll_value(panel) + ((my < sb.ty1) and -sb.vis or sb.vis))   -- page toward the click
        end
        free_scroll[panel] = true
        render()
        return
    end

    for _, hb in ipairs(row_hitboxes) do      -- the expand arrow is listed before its row
        if U.point_in(mx, my, hb) then
            local now = U.now_s()
            local is_double = (not hb.arrow) and MS.last_panel == hb.panel and MS.last_index == hb.index
                and (now - MS.last_down_t) * 1000 <= o.double_click_ms
            MS.last_panel, MS.last_index = hb.panel, hb.index
            if is_double then MS.last_double_t, MS.last_down_t = now, 0 else MS.last_down_t = now end
            click_row(hb, is_double)
            return
        end
    end

    for _, b in ipairs(button_hitboxes) do
        if U.point_in(mx, my, b) then
            if b.action == "focus_sidebar" then set_focus("sidebar")
            elseif b.action == "focus_episodes" then set_focus("episodes") end
            return
        end
    end
end

local function mouse_up()
    if MS.drag then
        MS.drag = nil
        render()
    end
end

-- Some mpv builds report a double-click as MBTN_LEFT_DBL instead of a second MBTN_LEFT.
local function mouse_dbl()
    if not browser_active then return end
    if U.now_s() - MS.last_double_t < 0.3 then return end     -- already handled via our own timing
    local mx, my = U.mouse_xy()
    if not mx then return end
    for _, hb in ipairs(row_hitboxes) do
        if not hb.arrow and U.point_in(mx, my, hb) then
            MS.last_double_t, MS.last_down_t = U.now_s(), 0
            click_row(hb, true)
            return
        end
    end
end
on_dblclick = mouse_dbl

-- Bound as a "complex" binding, so it receives {event = "down" | "up" | ...}.
on_click = function(e)
    if type(e) == "table" then
        if e.event == "down" or e.event == "press" then mouse_down()
        elseif e.event == "up" then mouse_up() end
    else
        mouse_down()
    end
end

-- The wheel scrolls the VIEW of the panel under the pointer (the selection stays put).
on_wheel = function(dir)
    if not browser_active or not layout then return end
    local mx, my = U.mouse_xy()
    local panel
    if mx then
        if U.point_in(mx, my, layout.sidebar) then panel = "sidebar"
        elseif U.point_in(mx, my, layout.list) then panel = "episodes" end
    end
    panel = panel or ((focus_panel == "sidebar") and "sidebar" or "episodes")
    set_scroll(panel, scroll_value(panel) + dir * o.scroll_lines)
    render()
end

mp.observe_property("mouse-pos", "native", function(_, val)
    if not browser_active or not val then return end
    if MS.view == "home" then return HV.on_move(val) end
    if MS.drag then
        drag_to(val.y)
        local now = U.now_s()
        if now - MS.last_move_render > 0.014 then MS.last_move_render = now; render() end
        return
    end
    local new_panel, new_index = nil, nil
    for _, hb in ipairs(row_hitboxes) do
        if U.point_in(val.x, val.y, hb) then
            new_panel, new_index = hb.panel, hb.index
            break
        end
    end
    local sbp = scrollbar_at(val.x, val.y)
    if new_panel ~= hover_panel or new_index ~= hover_index or sbp ~= MS.hover_sb then
        hover_panel, hover_index, MS.hover_sb = new_panel, new_index, sbp
        render()
    end
end)

end

-- Resizing: dragging a window corner changes the size dozens of times a second. Sizes come in steps (HV.metrics), so
-- while the step stays the same nothing is converted: the grid reflows live with the pictures it has. When the step
-- changes, mpv 0.38+ shows the pictures of the old step scaled (overlay-add dw/dh) until the sharp ones are converted;
-- older mpv takes them down and lays everything out once, 0.35 s after the size stops changing.
HV.last_dims = nil
-- the size step's signature: the picture sizes this window needs
function HV.step_sig(w, h)
    -- the width only caps picture sizes in windows narrower than they are tall (backdrop, stills): elsewhere it
    -- just changes how many cards fit a row
    local hs, ws = HV.step_h(h), HV.step_w(w)
    return hs .. "/" .. ((ws < hs) and tostring(ws) or "wide")
end
mp.observe_property("osd-dimensions", "native", function(_, v)
    local w, h = type(v) == "table" and tonumber(v.w), type(v) == "table" and tonumber(v.h)
    local key = (w and h) and (w .. "x" .. h) or ""
    if key == HV.last_dims then return end
    local first = (HV.last_dims == nil)
    HV.last_dims = key
    if not (w and h) or w < 64 or h < 64 then return end
    if not first then HV.resize_t = mp.get_time() end
    local sig = HV.step_sig(w, h)
    local stepped = HV.cur_step ~= nil and HV.cur_step ~= sig
    HV.cur_step = sig
    if stepped then
        -- conversions queued for the old step are dropped (asked again for the new sizes)
        for _, it in ipairs(HV.convq) do
            if it.st and it.st.cq then it.st.cq[it.sk] = nil end
            HV.conv_out[it.bgra] = nil
        end
        HV.convq = {}
        HV.PF.extra, HV.PF.done = nil, {}       -- the title page's sizes changed too
        HV.pruned = false            -- the cache keeps the last few steps, the rest goes (once, when it settles)
    end
    if not browser_active or first then return end
    if stepped then
        if not HV.dw_ok() then
            if not HV.resizing then HV.resizing = true; HV.clear() end
            if HV.resize_timer then HV.resize_timer:kill() end
            HV.resize_timer = mp.add_timeout(0.35, function()
                HV.resize_timer = nil
                HV.resizing = false
                HV.sig, HV.last_data = nil, nil
                if browser_active then render() end
            end)
            return
        end
    end
    if HV.resizing then return end
    -- the same pictures, laid out for the new size: drawn now, then at most every 50 ms while it keeps changing
    HV.sig, HV.last_data = nil, nil
    if HV.reflow_timer then HV.reflow_again = true; return end
    render()
    HV.reflow_timer = mp.add_timeout(0.05, function()
        HV.reflow_timer = nil
        if HV.reflow_again then HV.reflow_again = nil; HV.sig, HV.last_data = nil, nil; if browser_active then render() end end
    end)
end)

-- mpv 0.38+: overlay-add can show a picture at another size (dw / dh): scaled on the GPU, nothing converted
function HV.dw_ok()
    if HV._dw == nil then
        HV._dw = false
        for _, c in ipairs(mp.get_property_native("command-list") or {}) do
            if c.name == "overlay-add" then
                for _, a in ipairs(c.args or {}) do if a.name == "dw" then HV._dw = true end end
            end
        end
        msg.verbose("pictures: overlay-add " .. (HV._dw and "scales (dw/dh)" or "cannot scale - mpv older than 0.38"))
    end
    return HV._dw
end
-- another size of the same picture (same shape and fade), to show scaled while the right size is converted: f, w, h
function HV.alt_bgra(st, sk)
    if not (st and st.bgra and sk and HV.dw_ok()) then return nil end
    local tw, th = sk:match("^(%d+)x(%d+)")
    tw, th = tonumber(tw), tonumber(th)
    if not (tw and th) or th == 0 then return nil end
    local fade = sk:match("%.f(%x+)")
    local best, bw, bh
    for k, f in pairs(st.bgra) do
        if k ~= sk and not HV.bad_file[f] and k:match("%.f(%x+)") == fade then
            local w, h = k:match("^(%d+)x(%d+)")
            w, h = tonumber(w), tonumber(h)
            if w and h and h > 0 and math.abs(w / h - tw / th) < 0.03 and (not best or w > bw) then best, bw, bh = f, w, h end
        end
    end
    if not best and not fade then return HV.tiny_of(st, tw, th) end    -- the blurred placeholder
    return best, bw, bh
end

-- ============================================================
-- KEY BINDINGS
-- ============================================================
-- ONE alias table feeds BOTH browse mode and search mode, so the two can never drift apart again
-- (the on-screen-keyboard bug: search mode had no LEFT/RIGHT/KP_* at all). The Windows on-screen
-- keyboard reports its arrow keys as KP_UP / KP_DOWN / KP_LEFT / KP_RIGHT (not the KP8/KP2/...
-- digit names), so every direction lists both.
local safe_bind, REP, ONCE   -- shared with the playback events further down
do   -- key bindings live in their own scope (Lua 5.1: max 200 locals per function)
local KEYS = {
    up    = { "UP", "KP_UP", "KP8" },
    down  = { "DOWN", "KP_DOWN", "KP2" },
    left  = { "LEFT", "KP_LEFT", "KP4" },
    right = { "RIGHT", "KP_RIGHT", "KP6" },
    enter = { "ENTER", "KP_ENTER", "KP5" },
    pgup  = { "PGUP" }, pgdn = { "PGDWN" }, home = { "HOME" }, end_ = { "END" },
    tab   = { "TAB" }, bs = { "BS" },
}
HV.KEYS = KEYS

local function select_edge(first)
    local items = get_panel_items(focus_panel)
    free_scroll[focus_panel == "sidebar" and "sidebar" or "episodes"] = false
    if focus_panel == "sidebar" then sidebar_selected_index = first and 1 or math.max(1, #items)
    else selected_episode = first and 1 or math.max(1, #items) end
    render()
end

local function selected_file()
    if focus_panel ~= "episodes" then return nil end
    return get_panel_items("episodes")[selected_episode]
end

local function toggle_hide_watched()
    hide_watched = not hide_watched
    status_line = hide_watched and "Hiding watched files" or "Showing watched files"
    after_files_set()
    render()
end

local function clear_search_state()
    search_query, search_scope = "", nil
    search_results, MS.global_total = {}, 0
    selected_episode, scroll_offset_episodes = 1, 0
    sidebar_selected_index, scroll_offset_folders = 1, 0
    status_line = "Ready"
    render()
end

local function esc_pressed()
    if search_query ~= "" or search_scope ~= nil then clear_search_state()
    elseif MS.from_home then HV.show()
    else close_browser() end
end

REP, ONCE = { repeatable = true }, { repeatable = false }
local CLICK = { complex = true }

local function build_browse_bindings()
    local L = {}
    local function add(key, fn, flags) L[#L + 1] = { key, fn, flags or ONCE } end
    local function many(keys, fn, flags) for _, k in ipairs(keys) do add(k, fn, flags) end end

    many(U.kb("up"),        function() move_selection(-1) end, REP)
    many(U.kb("down"),      function() move_selection(1) end, REP)
    many(U.kb("page_up"),   function() move_selection(-10) end, REP)
    many(U.kb("page_down"), function() move_selection(10) end, REP)
    many(U.kb("first"),     function() select_edge(true) end)
    many(U.kb("last"),      function() select_edge(false) end)
    many(U.kb("open"),      function() open_selected(false) end)
    many(U.kb("right"),     function() open_selected(true) end)
    many(U.kb("left"),      function() collapse_or_parent() end)
    many(U.kb("back"),      function() collapse_or_parent() end)
    many(U.kb("switch_panel"), function() switch_panel() end)
    many(U.kb("queue"),     function() queue_add_current() end)
    many(U.kb("sort"),      function() toggle_sort() end)
    many(U.kb("refresh"),   function() refresh_current() end)
    many(U.kb("refresh_all"), function() refresh_all() end)
    many(U.kb("search_folder"), function() start_search() end)
    many(U.kb("search"),    function() start_search("global") end)
    many(U.kb("watched"),   function() toggle_watched(selected_file()) end)
    many(U.kb("play_download"), function() MS.fb_manual(selected_file()) end)
    many(U.kb("hide_watched"), function() toggle_hide_watched() end)
    many(U.kb("debug"),     function() MS.debug = not MS.debug; render() end)
    many(U.kb("switch_view"), function() HV.show() end)
    many(U.kb("doctor"),    function() HV.DR.show() end)
    many(U.kb("close"), esc_pressed)
    add("MBTN_LEFT", function(e) on_click(e) end, CLICK)
    add("MBTN_LEFT_DBL", function() on_dblclick() end)
    add("WHEEL_UP",   function() on_wheel(-1) end, REP)
    add("WHEEL_DOWN", function() on_wheel(1) end, REP)
    return L
end

local function build_home_bindings()
    local L = {}
    local function add(key, fn, flags) L[#L + 1] = { key, fn, flags or ONCE } end
    local function many(keys, fn, flags) for _, k in ipairs(keys) do add(k, fn, flags) end end
    many(U.kb("up"),        function() HV.move(-1, 0) end, REP)
    many(U.kb("down"),      function() HV.move(1, 0) end, REP)
    many(U.kb("left"),      function() HV.move(0, -1) end, REP)
    many(U.kb("right"),     function() HV.move(0, 1) end, REP)
    many(U.kb("page_up"),   function() HV.move(-2, 0) end, REP)
    many(U.kb("page_down"), function() HV.move(2, 0) end, REP)
    many(U.kb("first"),     function() HV.edge(true) end)
    many(U.kb("last"),      function() HV.edge(false) end)
    many(U.kb("open"),      function() HV.activate() end)
    many(U.kb("switch_view"), function() if HV.dlc() then HV.DL.open_folder(HV.DL.folder_of(HV.DLC.title, HV.DLC.kind == "win")) else HV.open_list() end end)
    -- Space: ticks a file on the download card; anywhere else it pauses / plays as usual
    many({ "SPACE" }, function()
        if HV.TK.is_open() then local r = HV.TK.sorted()[HV.TK.sel]; if r then HV.TK.cycle_bell(r.k) end
        elseif HV.dlc() then TV.dl_toggle() else mp.commandv("cycle", "pause") end
    end)
    many(U.kb("search"),    function() HV.start_search() end)
    many(U.kb("search_folder"), function() HV.start_search() end)
    many(U.kb("sort"),      function() if HV.dlc() then HV.DL.stop() else HV.toggle_sort() end end)
    many(U.kb("queue"),     function() if HV.dlc() then TV.dl_all() else HV.queue_selected() end end)
    many(U.kb("watched"),   function() HV.toggle_watched() end)
    many(U.kb("downloads"), function() HV.dl_show() end)
    many({ "DEL", "KP_DEL" }, function() if HV.TK.is_open() then HV.TK.remove_sel() elseif HV.dlc() then HV.dl_remove() end end)
    many(U.kb("tracked"), function() if HV.TK.on() then HV.TK.toggle() end end)
    many({ "Shift+UP" }, function() if HV.dlc() then HV.dl_reorder(-1) else HV.move(-1, 0) end end, REP)
    many({ "Shift+DOWN" }, function() if HV.dlc() then HV.dl_reorder(1) else HV.move(1, 0) end end, REP)
    many(U.kb("more"),      function() if HV.mode == "title" and (TV.more_avail or TV.more) then TV.toggle_more() end end)
    many(U.kb("refetch_art"), function()
        -- on a title page whose files Real-Debrid removed, the same key streams the torrent instead
        if HV.mode == "title" and #(HV.rows or {}) == 0 and TV.stream_empty() then return end
        HV.refetch()
    end)
    for key in tostring(o.add_key or "n"):gmatch("[^%s,]+") do add(key, function() HV.AX.open() end) end
    for key in tostring(o.cache_clear_key or "ctrl+x"):gmatch("[^%s,]+") do add(key, function() HV.clear_cache_key() end) end
    many(U.kb("back"),      function() HV.back() end)
    many(U.kb("report"),    function() TV.diagnose() end)
    many(U.kb("doctor"),    function() HV.DR.show() end)
    many(U.kb("refresh"),   function() HV.refresh() end)
    many(U.kb("refresh_all"), function() HV.refresh() end)
    many(U.kb("debug"),     function() MS.debug = not MS.debug; render() end)
    many(U.kb("close"),     function() if HV.HP.open then return HV.HP.close() end; HV.esc() end)
    add("?", function() HV.HP.toggle() end)
    add("Shift+/", function() HV.HP.toggle() end)
    -- gamepads (mpv: input-gamepad=yes) and TV remotes; using one turns couch mode on (couch_mode=auto)
    local function pad(keys, fn, flags)
        for _, k in ipairs(keys) do add(k, function(...) HV.pad_hit(); fn(...) end, flags) end
    end
    pad({ "GAMEPAD_DPAD_UP", "GAMEPAD_LEFT_STICK_UP" },       function() HV.move(-1, 0) end, REP)
    pad({ "GAMEPAD_DPAD_DOWN", "GAMEPAD_LEFT_STICK_DOWN" },   function() HV.move(1, 0) end, REP)
    pad({ "GAMEPAD_DPAD_LEFT", "GAMEPAD_LEFT_STICK_LEFT" },   function() HV.move(0, -1) end, REP)
    pad({ "GAMEPAD_DPAD_RIGHT", "GAMEPAD_LEFT_STICK_RIGHT" }, function() HV.move(0, 1) end, REP)
    pad({ "GAMEPAD_LEFT_SHOULDER", "CHANNEL_UP" },    function() HV.move(-2, 0) end, REP)
    pad({ "GAMEPAD_RIGHT_SHOULDER", "CHANNEL_DOWN" }, function() HV.move(2, 0) end, REP)
    pad({ "GAMEPAD_ACTION_DOWN", "PLAY", "PLAYPAUSE", "PLAYONLY" }, function() HV.activate() end)
    pad({ "GAMEPAD_ACTION_RIGHT", "GO_BACK", "BACK", "CANCEL" }, function() HV.esc() end)
    pad({ "GAMEPAD_ACTION_LEFT" }, function() HV.toggle_watched() end)
    pad({ "GAMEPAD_ACTION_UP" }, function() HV.queue_selected() end)
    pad({ "GAMEPAD_START", "MENU" }, function() HV.toggle_sort() end)
    add("MBTN_LEFT", function(e)
        if type(e) == "table" then
            if e.event == "down" or e.event == "press" then HV.mouse_down() end
            if e.event == "up" or e.event == "press" then HV.mouse_up() end
        else HV.mouse_down() end
    end, CLICK)
    add("MBTN_LEFT_DBL", function() HV.mouse_dbl() end)
    add("WHEEL_UP",   function() HV.on_wheel(-1) end, REP)
    add("WHEEL_DOWN", function() HV.on_wheel(1) end, REP)
    add("WHEEL_LEFT",  function() HV.on_hwheel(-1) end, REP)
    add("WHEEL_RIGHT", function() HV.on_hwheel(1) end, REP)
    if o.experimental_mouse_ui then add("MBTN_RIGHT", function() HV.right_click() end) end
    return L
end

local browse_bound = {}      -- names currently registered, so unbind removes exactly what was bound

safe_bind = function(name, key, fn, flags)
    local ok, err = pcall(mp.add_forced_key_binding, key, name, fn, flags)
    if not ok then msg.warn("webdav-browser: could not bind '" .. key .. "': " .. tostring(err)) end
end

bind_all = function()
    local seen = {}
    for _, kb in ipairs((MS.view == "home") and build_home_bindings() or build_browse_bindings()) do
        if seen[kb[1]] and not MS.dup_warned then
            MS.dup_warned = true
            msg.warn("config: the key '" .. kb[1] .. "' is set for more than one action - the last one wins")
        end
        seen[kb[1]] = true
        local name = "webdav_" .. kb[1]
        local fn = kb[2]
        if not tostring(kb[1]):match("^MBTN") and not tostring(kb[1]):match("^WHEEL") then
            local f0, kname = fn, kb[1]
            fn = function(...) HV.key_input(); if HV.ov_block(kname) then return end; return f0(...) end
        end
        safe_bind(name, kb[1], fn, kb[3])
        browse_bound[#browse_bound + 1] = name
    end
end
unbind_all = function()
    for _, name in ipairs(browse_bound) do mp.remove_key_binding(name) end
    browse_bound = {}
    if HV.typing then HV.typing = false; unbind_search() end
end

-- ---------- search mode ----------
local SEARCH_CHARS_LOWER = "abcdefghijklmnopqrstuvwxyz0123456789-_.'()[]!&+,"
local SEARCH_CHARS_UPPER = "ABCDEFGHIJKLMNOPQRSTUVWXYZ"
local search_bound = {}

bind_search = function()
    local function add(name, key, fn, flags)
        safe_bind(name, key, fn, flags)
        search_bound[#search_bound + 1] = name
    end
    local function many(prefix, keys, fn, flags)
        for _, k in ipairs(keys) do add(prefix .. k, k, fn, flags) end
    end
    -- typing: named keys first (work on every mpv version)...
    for i = 1, #SEARCH_CHARS_LOWER do
        local ch = SEARCH_CHARS_LOWER:sub(i, i)
        add("search_c_" .. ch, ch, function() search_append(ch) end, REP)
    end
    for i = 1, #SEARCH_CHARS_UPPER do
        local ch = SEARCH_CHARS_UPPER:sub(i, i)
        add("search_C_" .. ch, ch, function() search_append(ch) end, REP)
    end
    add("search_space", "SPACE", function() search_append(" ") end, REP)
    -- ...and any_unicode as the fallback for EVERYTHING else (: ; @ # accents, kana, ...). A named
    -- binding always wins over any_unicode for the same key, so nothing is typed twice.
    add("search_any", "any_unicode", function(e)
        if type(e) ~= "table" then return end
        if e.event ~= "down" and e.event ~= "repeat" and e.event ~= "press" then return end
        local txt = e.key_text
        if txt and txt ~= "" and #txt <= 8 then search_append(txt) end
    end, { repeatable = true, complex = true })

    many("search_", KEYS.bs,    function() search_backspace() end, REP)
    many("search_", KEYS.enter, function() confirm_search() end)
    add("search_cancel", "ESC", function() cancel_search() end)
    many("search_", KEYS.up,    function() move_selection(-1) end, REP)
    many("search_", KEYS.down,  function() move_selection(1) end, REP)
    many("search_", KEYS.pgup,  function() move_selection(-10) end, REP)
    many("search_", KEYS.pgdn,  function() move_selection(10) end, REP)
    -- the text cursor
    many("search_", KEYS.home,  function() MS.scur_move("home") end)
    many("search_", KEYS.end_,  function() MS.scur_move("end") end)
    many("search_", KEYS.left,  function() MS.scur_move(-1) end, REP)
    many("search_", KEYS.right, function() MS.scur_move(1) end, REP)
    add("search_cl", "ctrl+LEFT",  function() MS.scur_move(-2) end, REP)
    add("search_cr", "ctrl+RIGHT", function() MS.scur_move(2) end, REP)
    add("search_del", "DEL", function() MS.search_delete() end, REP)
    add("search_kpdel", "KP_DEL", function() MS.search_delete() end, REP)
    many("search_", KEYS.tab,   function() end)
    add("search_click", "MBTN_LEFT", function(e) on_click(e) end, CLICK)
    add("search_dbl", "MBTN_LEFT_DBL", function() on_dblclick() end)
    add("search_wu", "WHEEL_UP",   function() on_wheel(-1) end, REP)
    add("search_wd", "WHEEL_DOWN", function() on_wheel(1) end, REP)
end

unbind_search = function()
    for _, name in ipairs(search_bound) do mp.remove_key_binding(name) end
    search_bound = {}
end

-- Typing keys for the poster UI's own search box (same key set as the list UI's search).
HV.bind_search = function()
    local function add(name, key, fn, flags)
        safe_bind(name, key, fn, flags)
        search_bound[#search_bound + 1] = name
    end
    local function many(prefix, keys, fn, flags)
        for _, k in ipairs(keys) do add(prefix .. k, k, fn, flags) end
    end
    for i = 1, #SEARCH_CHARS_LOWER do
        local ch = SEARCH_CHARS_LOWER:sub(i, i)
        add("hvs_c_" .. ch, ch, function() HV.search_append(ch) end, REP)
    end
    for i = 1, #SEARCH_CHARS_UPPER do
        local ch = SEARCH_CHARS_UPPER:sub(i, i)
        add("hvs_C_" .. ch, ch, function() HV.search_append(ch) end, REP)
    end
    add("hvs_space", "SPACE", function() HV.search_append(" ") end, REP)
    add("hvs_any", "any_unicode", function(e)
        if type(e) ~= "table" then return end
        if e.event ~= "down" and e.event ~= "repeat" and e.event ~= "press" then return end
        local txt = e.key_text
        if txt and txt ~= "" and #txt <= 8 then HV.search_append(txt) end
    end, { repeatable = true, complex = true })
    many("hvs_", KEYS.bs,    function() HV.search_backspace() end, REP)
    add("hvs_del", "DEL", function() HV.search_delete() end, REP)
    add("hvs_kpdel", "KP_DEL", function() HV.search_delete() end, REP)
    many("hvs_", KEYS.enter, function() HV.search_enter() end)
    add("hvs_cancel", "ESC", function() HV.search_cancel() end)
    -- Left / Right / Home / End edit the text; Down (or Tab) goes to the results, F or a click comes back to the box
    many("hvs_", KEYS.left,  function() HV.cur_move(-1) end, REP)
    many("hvs_", KEYS.right, function() HV.cur_move(1) end, REP)
    add("hvs_cl", "ctrl+LEFT",  function() HV.cur_move(-2) end, REP)
    add("hvs_cr", "ctrl+RIGHT", function() HV.cur_move(2) end, REP)
    many("hvs_", KEYS.home,  function() HV.cur_move("home") end)
    many("hvs_", KEYS.end_,  function() HV.cur_move("end") end)
    many("hvs_", KEYS.down,  function() HV.to_results() end)
    many("hvs_", KEYS.tab,   function() HV.to_results() end)
    many("hvs_", KEYS.up,    function() end)
    many("hvs_", KEYS.pgdn,  function() HV.to_results() end)
    add("hvs_click", "MBTN_LEFT", function(e)
        if type(e) == "table" then
            if e.event == "down" or e.event == "press" then HV.mouse_down() end
            if e.event == "up" or e.event == "press" then HV.mouse_up() end
        else HV.mouse_down() end
    end, CLICK)
    add("hvs_dbl", "MBTN_LEFT_DBL", function() HV.mouse_dbl() end)
    add("hvs_back", "MBTN_BACK", function() HV.back() end)
    add("hvs_wu", "WHEEL_UP",   function() HV.on_wheel(-1) end, REP)
    add("hvs_wl", "WHEEL_LEFT",  function() HV.on_hwheel(-1) end, REP)
    add("hvs_wr", "WHEEL_RIGHT", function() HV.on_hwheel(1) end, REP)
    add("hvs_wd", "WHEEL_DOWN", function() HV.on_wheel(1) end, REP)
end

-- ============================================================
-- ADD FROM ADD-ONS (EXPERIMENTAL, poster edition)
-- ============================================================
-- Find a movie or episode on TMDB, list its releases from Stremio add-ons (AIOStreams, Comet... addon_urls in the
-- conf), and add the one you pick to Real-Debrid without leaving mpv:
--   film:   search -> title -> releases -> add to Real-Debrid -> plays as soon as it is ready
--   series: search -> title -> every season / complete pack (like Debrid Media Manager) -> add the whole pack ->
--           pick the episode to start from (E on the pack list = one single episode instead)
-- Add-ons that know your Real-Debrid account mark cached releases themselves ([RD+], ⚡); otherwise a release is
-- added and watched: "downloaded" within a few seconds = cached; else you see its progress and can wait, leave it
-- downloading, delete it or try the next release. Hashes that turned out cached are remembered and marked next time.
-- Add-on URLs can contain your Real-Debrid key: they live in the conf and are never written to the log.
HV.AX = { stage = nil, bound = {}, list = {}, sel = 1, top = 1, imgs = {}, sortm = 1, filt = "", hits = {} }
-- Cinemeta (Stremio's own catalogue) numbers seasons the way the add-ons do (IMDb), which is not always TMDB's
HV.AX.CINEMETA = "https://v3-cinemeta.strem.io"

function HV.AX.urls()
    local out = {}
    for u0 in tostring(o.addon_urls or ""):gmatch("[^%s;|,]+") do
        local u = u0:gsub("^stremio://", "https://"):gsub("/manifest%.json$", ""):gsub("/+$", "")
        if u:match("^https?://") then out[#out + 1] = u end
    end
    return out
end
function HV.AX.enabled() return #HV.AX.urls() > 0 end
function HV.AX.host(u) return (tostring(u):match("^https?://([^/]+)") or "add-on") end

-- remembered "this hash was cached" answers
function HV.AX.cache_path() return PS.dir() .. "/addon_cached.json" end
function HV.AX.known()
    local AX = HV.AX
    if not AX.kc then AX.kc = try_load_json(AX.cache_path()) or {} end
    return AX.kc
end
function HV.AX.remember(hash)
    local kc = HV.AX.known()
    kc[hash:lower()] = os.time()
    pcall(atomic_write, HV.AX.cache_path(), safe_json(kc) or "{}")
end

-- ---- small helpers ----
HV.AX.B64 = U.b64_chars
HV.AX.b64enc = U.base64_encode
-- base64 / base64url -> string (nil when it is not base64)
function HV.AX.b64dec(s)
    s = tostring(s or ""):gsub("%-", "+"):gsub("_", "/"):gsub("=+$", "")
    if s == "" or s:find("[^%w%+/]") then return nil end
    local I = HV.AX.B64I
    if not I then
        I = {}
        for i = 1, 64 do I[HV.AX.B64:byte(i)] = i - 1 end
        HV.AX.B64I = I
    end
    -- 6 bits per letter, a byte out whenever 8 are in (a leftover of fewer than 8 bits is dropped, as before)
    local out, acc, nb = {}, 0, 0
    for k = 1, #s do
        acc = acc * 64 + I[s:byte(k)]
        nb = nb + 6
        if nb >= 8 then
            nb = nb - 8
            local pw = 2 ^ nb
            local b = math.floor(acc / pw)
            out[#out + 1] = string.char(b)
            acc = acc - b * pw
        end
    end
    return table.concat(out)
end

-- AIOStreams and other formatters write small capitals and sub/superscript digits ("ꜱ₀₉·ᴇ₁₆₈"): back to plain text
HV.AX.NMAP = {}
function HV.AX.build_nmap()
    local caps = { "ᴀ", "ʙ", "ᴄ", "ᴅ", "ᴇ", "ғ", "ɢ", "ʜ", "ɪ", "ᴊ", "ᴋ", "ʟ", "ᴍ", "ɴ", "ᴏ", "ᴘ", "ǫ", "ʀ", "ꜱ", "ᴛ", "ᴜ", "ᴠ", "ᴡ", "x", "ʏ", "ᴢ" }
    for i, c in ipairs(caps) do if c ~= "x" then HV.AX.NMAP[c] = string.char(64 + i) end end
    HV.AX.NMAP["ꜰ"] = "F"
    local subs = { "₀", "₁", "₂", "₃", "₄", "₅", "₆", "₇", "₈", "₉" }
    local sups = { "⁰", "¹", "²", "³", "⁴", "⁵", "⁶", "⁷", "⁸", "⁹" }
    for i = 1, 10 do HV.AX.NMAP[subs[i]] = tostring(i - 1); HV.AX.NMAP[sups[i]] = tostring(i - 1) end
    HV.AX.NMAP["\226\128\141"] = ""            -- zero-width joiner
    HV.AX.NMAP["\226\128\139"] = ""            -- zero-width space
    HV.AX.NMAP["\226\128\143"] = ""            -- right-to-left mark
end
HV.AX.build_nmap()
function HV.AX.norm(s)
    return (tostring(s or ""):gsub("[\192-\247][\128-\191]*", function(ch) return HV.AX.NMAP[ch] end))
end

function HV.AX.num(s, pat) local v = tostring(s or ""):match(pat); return v and tonumber((v:gsub(",", ""))) or nil end
function HV.AX.unit(n, u)
    n = tonumber(n)
    if not n then return nil end
    u = tostring(u or ""):upper():sub(1, 1)
    return n * ((u == "T") and 1099511627776 or (u == "G") and 1073741824 or (u == "K") and 1024 or 1048576)
end
-- every size written in the text, in order; "1.4 / 30.8 GB" (one unit for both) counts as two sizes
function HV.AX.sizes_of(text)
    local AX = HV.AX
    local out = {}
    text = tostring(text or "")
    local a, b, u = text:match("([%d%.]+)%s*/%s*([%d%.]+)%s*([KMGT]i?B)")
    if a then return { AX.unit(a, u), AX.unit(b, u) } end
    local a2, u1, b2, u2 = text:match("([%d%.]+)%s*([KMGT]i?B)[^\n%d]-/[^\n%d]-([%d%.]+)%s*([KMGT]i?B)")
    if a2 then return { AX.unit(a2, u1), AX.unit(b2, u2) } end
    for n, uu in text:gmatch("([%d%.]+)%s*([KMGT]i?B)") do out[#out + 1] = AX.unit(n, uu) end
    return out
end
function HV.AX.res_of(text)
    local l = tostring(text or ""):lower()
    if l:find("2160p") or l:find("%f[%w]4k%f[%W]") or l:find("uhd") then return "4K", 4 end
    if l:find("1440p") then return "1440p", 3.5 end
    if l:find("1080p") or l:find("fhd") then return "1080p", 3 end
    if l:find("720p") then return "720p", 2 end
    if l:find("576p") or l:find("480p") or l:find("%f[%w]sd%f[%W]") then return "480p", 1 end
    return "", 0
end

-- tags read from release names: source, codec, audio, HDR, languages, group
function HV.AX.tags_of(name)
    local l = " " .. tostring(name or ""):lower():gsub("[%._]", " ") .. " "
    local t = {}
    local function has(p) return l:find(p) ~= nil end
    if has("remux") then t.src = "Remux" elseif has("blu%-?ray") or has("%f[%w]bd%f[%W]") or has("bdrip") then t.src = "BluRay"
    elseif has("web%-?dl") then t.src = "WEB-DL" elseif has("webrip") then t.src = "WEBRip" elseif has("%f[%w]web%f[%W]") then t.src = "WEB"
    elseif has("hdtv") then t.src = "HDTV" elseif has("dvd") then t.src = "DVD" end
    if has("x265") or has("hevc") or has("h 265") or has("h265") then t.codec = "HEVC"
    elseif has("%f[%w]av1%f[%W]") then t.codec = "AV1"
    elseif has("x264") or has("avc") or has("h 264") or has("h264") then t.codec = "AVC" end
    if has("10 ?bit") or has("10%-bit") then t.bit = "10-bit" end
    if has("dolby vision") or has("%f[%w]dv%f[%W]") or has("dovi") then t.hdr = "DV" elseif has("hdr") then t.hdr = "HDR" end
    local au = {}
    if has("truehd") then au[#au + 1] = "TrueHD" end
    if has("atmos") then au[#au + 1] = "Atmos" end
    if has("dts%-?hd") or has("dts%-?x") then au[#au + 1] = "DTS-HD" elseif has("%f[%w]dts%f[%W]") then au[#au + 1] = "DTS" end
    if has("flac") then au[#au + 1] = "FLAC" end
    if has("ddp") or has("dd%+") or has("eac3") or has("e%-ac%-?3") then au[#au + 1] = "DD+" elseif has("%f[%w]dd%f[%W]") or has("%f[%w]ac3%f[%W]") then au[#au + 1] = "DD" end
    if has("%f[%w]aac") then au[#au + 1] = "AAC" end
    if has("opus") then au[#au + 1] = "Opus" end
    t.audio = au
    if has("dual[%s%-]?audio") or has("%f[%w]dual%f[%W]") then t.dual = "Dual audio"
    elseif has("multi[%s%-]?audio") or has("%f[%w]multi%f[%W]") then t.dual = "Multi audio" end
    -- release group: "[Group] Name..." or "...-GROUP.mkv" / "...-GROUP"
    local raw = tostring(name or ""):gsub("^%s+", "")
    local g = raw:match("^%[([^%]]+)%]")
    if not g then
        local base = raw:gsub("%s+$", ""):gsub("%.%w%w%w?$", "")
        g = base:match("%-([%w]+)$") or base:match("%-([%w]+)%s*%[[^%]]*%]$")
    end
    if g and #g <= 20 and not g:match("^%d+p$") and not g:lower():match("^x?26[45]$") then t.group = g end
    return t
end

-- What a release NAME says it holds. Only used for labels when the add-on gives nothing better.
function HV.AX.scope(name)
    local l = " " .. HV.AX.norm(name or ""):lower():gsub("[%._]", " ") .. " "
    local a, b = l:match("%f[%w]s(%d%d?)%s*[%-~]%s*s?(%d%d?)%f[^%d]")
    if not a then a, b = l:match("seasons?%s*(%d+)%s*[%-~]%s*(%d+)") end
    if a and tonumber(b) > tonumber(a) then return "multi", tonumber(a), tonumber(b) end
    -- episode ranges: E168-E195, (001-366), Episodes 1-24
    local e1, e2 = l:match("%f[%w]e(%d+)%s*[%-~]%s*e?(%d+)%f[^%d]")
    if not e1 then e1, e2 = l:match("[%(%[](%d%d%d?%d?)%s*[%-~]%s*(%d%d%d?%d?)[%)%]]") end
    if not e1 then e1, e2 = l:match("episodes?%s*(%d+)%s*[%-~]%s*(%d+)") end
    local s = l:match("%f[%w]s(%d%d?)%f[^%d]") or l:match("%f[%w]s(%d%d?)e%d") or l:match("season%s*(%d+)")
    if e1 and tonumber(e2) > tonumber(e1) then return "range", tonumber(e1), tonumber(e2), tonumber(s) end
    if l:match("%f[%w]s%d%d?e%d") or l:match("%f[%w]%d%d?x%d%d%f[^%d]") or l:match("episode%s*%d") or l:match("%f[%w]e%d%d%d?%f[^%d]") then return "episode", tonumber(s) end
    if s then return "season", tonumber(s) end
    if l:match("%s%-%s+%d%d%d?%d?%f[^%d]") then return "episode" end      -- "[Group] Show - 012 (1080p)"
    if l:find("complete") or l:find("collection") or l:find("all seasons") then return "complete" end
    return nil
end

-- "S02E05" / "Ep 168" for a file name
function HV.AX.ep_label(name)
    local base = tostring(name or ""):match("([^/]+)$") or ""
    local s_, e_, abs = TV.se_of(base, nil)
    if s_ and e_ and not abs then return string.format("S%02dE%02d", s_, e_), s_, e_ end
    if e_ then return "Ep " .. e_, nil, e_ end
    local n = base:lower():match("%f[%w]e(%d%d%d?%d?)%f[^%d]") or base:match("%s%-%s+(%d%d%d?%d?)%f[^%d]")
    if n then return "Ep " .. tonumber(n), nil, tonumber(n) end
    return nil
end

-- AIOStreams debrid links carry the torrent as base64url JSON (hash, title, file index) in one path segment
function HV.AX.fileinfo(url)
    local AX = HV.AX
    url = tostring(url or "")
    if not url:find("/playback/", 1, true) and not url:find("/resolve/", 1, true) then return nil end
    for seg in url:gmatch("/([%w%-_]+)") do
        -- base64 of a JSON object ("{") starts with "e": most API keys, hashes and encrypted configs are not decoded at all
        if #seg >= 40 and #seg % 4 ~= 1 and seg:sub(1, 1) == "e" then
            local js = AX.b64dec(seg)
            if js and js:sub(1, 1) == "{" then
                local ok, d = pcall(utils.parse_json, js)
                if ok and type(d) == "table" and (d.hash or d.title) then return d end
            end
        end
    end
    return nil
end

-- ---- open / close / navigation ----
function HV.AX.open()
    local AX = HV.AX
    HV.A.sc, HV.cur_scroll = nil, 0
    if not AX.enabled() then
        HV.say({ eyebrow = "ADD-ONS", title = "Set addon_urls in webdav-browser.conf", extra = "AIOStreams / Comet manifest URLs" }, 5)
        return
    end
    unbind_all()
    HV.clear()
    AX.prev_mode = HV.mode
    HV.mode = "add"
    HV.TK.open, HV.TK.closing = false, nil
    if HV.DLC and HV.DLC.kind == "pop" then HV.DLC = nil end
    AX.job, AX.fedit, AX.hover, AX.bs_armed = nil, false, nil, nil
    AX.visit = (AX.visit or 0) + 1
    AX.api_bad = nil                     -- a fixed password is tried again
    local sv = AX.saved
    if sv and os.time() - sv.t < 6 * 3600 then
        -- back where you left it: the search, its results and the list you were on
        for k, v in pairs(sv.st) do AX[k] = v end
        AX.qc = #(AX.q or "")
        AX.fc = #(AX.filt or "")
        if AX.stage == "results" then AX.libmark()
        elseif AX.m and AX.stage == AX.m.stage then AX.relist(false); if PS.rd_on() then AX.rd_load(true, function() if HV.mode == "add" then AX.relist(false) end end) end end
    else
        AX.stage, AX.q, AX.qc, AX.list, AX.sel, AX.top, AX.msg = "home", "", 0, {}, 1, 1, nil
        AX.title, AX.season, AX.ep, AX.sfilter, AX.m, AX.packs_m, AX.results, AX.last_q = nil, nil, nil, 0, nil, nil, nil, nil
        AX.filt, AX.fc, AX.note, AX.nyaa, AX.nq, AX.nyaa_m, AX.from_home = "", 0, nil, false, "", nil, nil
    end
    AX.bind()
    if AX.stage == "home" then AX.show_home() else render() end
end

-- what reopening the screen brings back (a list, never a half-finished add)
HV.AX.SAVE_KEYS = { "stage", "q", "list", "sel", "top", "msg", "title", "season", "ep", "sfilter", "m", "packs_m", "results",
                    "last_q", "filt", "episodes", "note", "nyaa", "nq", "nyaa_q", "nyaa_m", "hr", "hc", "from_home", "rsel" }
function HV.AX.save()
    local AX = HV.AX
    local st = {}
    for _, k in ipairs(AX.SAVE_KEYS) do st[k] = AX[k] end
    local j = AX.job
    if j and j.from then
        st.stage, st.list, st.sel, st.top, st.m = j.from.stage, j.from.list, j.from.sel, j.from.top, j.from.m or AX.m
    end
    if st.stage == "pick" or st.stage == "adding" or st.stage == "ready" or not st.stage then st.stage = AX.results and "results" or "home" end
    if st.stage == "query" then st.stage = st.nyaa and (st.m and "releases" or "home") or "home" end
    if st.nyaa and st.m and st.m.kind == "nyaa" then st.nyaa_m = st.m end
    AX.saved = { t = os.time(), st = st }
end

function HV.AX.close()
    local AX = HV.AX
    pcall(AX.abandon)
    AX.save()
    AX.unbind()
    if AX.poll then AX.poll:kill(); AX.poll = nil end
    AX.req = (AX.req or 0) + 1          -- answers still on their way are dropped
    AX.stage, AX.job = nil, nil
    HV.clear()
    HV.mode = (AX.prev_mode == "title") and "title" or "home"
    HV.sig, HV.last_data = nil, nil
    bind_all()
    -- something was added: re-read the library so it shows up
    if AX.added then AX.added = false; HV.mode = "home"; HV.refresh() end
    render()
end

-- the search box, keeping the results (↓ / Enter on an unchanged search goes back to them)
function HV.AX.edit_query()
    local AX = HV.AX
    AX.stage, AX.fedit, AX.hover = "query", false, nil
    AX.qc = #(AX.q or "")
    render()
end

-- one step back (Esc / Backspace / right mouse button / B)
function HV.AX.back()
    local AX = HV.AX
    local st = AX.stage
    if AX.fedit then AX.fedit = false; AX.filt = ""; AX.refilter(); return end
    if st == "home" then AX.close(); return
    elseif st == "query" then
        if AX.nyaa then
            if AX.m and AX.m.kind == "nyaa" then AX.stage = "releases"; AX.relist(false) else AX.toggle_src(false) end
        else AX.show_home() end
        return
    elseif st == "results" then AX.show_home(); return
    elseif st == "title" then
        local tv = AX.tv
        if tv and tv.prev then AX.tv = tv.prev; render(); return end      -- a title opened from "More like this"
        AX.tv = nil
        if tv and tv.from == "results" and AX.results then AX.show_results() else AX.show_home() end
        return
    elseif st == "releases" and AX.nyaa then
        local ret = AX.nyaa_ret
        if ret then                -- searched from a title page: back to it
            AX.toggle_src(false)
            AX.tv, AX.stage, AX.msg, AX.title, AX.hover = ret, "title", nil, nil, nil
            render()
            return
        end
        if AX.m and not AX.m.latest then AX.nyaa_search(""); return end
        AX.toggle_src(false); return
    elseif st == "packs" then AX.back_to_title()
    elseif st == "seasons" then AX.show_packs()
    elseif st == "episodes" then AX.show_seasons()
    elseif st == "releases" then
        if AX.title and AX.title.kind == "tv" then AX.show_episodes()
        else AX.back_to_title() end
    elseif st == "pick" then AX.cancel_pick()
    elseif st == "adding" or st == "ready" then AX.leave_job(false)
    else AX.close(); return end
    render()
end

-- from a title's release list back to its title page (or where you came from, without one)
function HV.AX.back_to_title()
    local AX = HV.AX
    AX.req = (AX.req or 0) + 1
    if AX.tv then AX.stage, AX.msg, AX.title = "title", nil, nil; return end
    if AX.results and not AX.from_home then AX.show_results() else AX.show_home() end
end
function HV.AX.set_list(stage, list, msg_)
    local AX = HV.AX
    AX.stage, AX.list, AX.sel, AX.top, AX.msg, AX.hover = stage, list or {}, 1, 1, msg_, nil
end

-- ---- TMDB side ----
function HV.AX.search()
    local AX = HV.AX
    local q = AX.q:gsub("^%s+", ""):gsub("%s+$", "")
    if AX.nyaa then return AX.nyaa_search(q) end
    if q == "" then return end
    AX.from_home = nil
    if q == AX.last_q and AX.results then return AX.show_results() end     -- same search: the results are still here
    AX.last_q = q
    AX.set_list("results", {}, "Searching TMDB…")
    render()
    PS.api("/search/multi?include_adult=false&query=" .. U.url_encode_segment(q), function(d, err)
        if HV.mode ~= "add" or AX.stage ~= "results" or q ~= AX.last_q then return end
        local good, weak = {}, {}
        for _, r in ipairs(d and d.results or {}) do
            if r.media_type == "tv" or r.media_type == "movie" then
                local yr = tostring(r.first_air_date or r.release_date or ""):sub(1, 4)
                local ov = tostring(r.overview or "")
                local votes = tonumber(r.vote_count)
                local poster = (type(r.poster_path) == "string" and r.poster_path ~= "") and r.poster_path or nil
                if poster or ov ~= "" then
                    local it = { kind = r.media_type, id = r.id, name = r.name or r.title or "?", year = yr, poster = poster,
                        overview = ov, votes = votes, vote = tonumber(r.vote_average) or 0 }
                    it.text = it.name .. (yr ~= "" and ("  (" .. yr .. ")") or "")
                    if poster and (votes == nil or votes > 0) then good[#good + 1] = it else weak[#weak + 1] = it end
                end
            end
        end
        for _, it in ipairs(weak) do good[#good + 1] = it end
        AX.results = good
        AX.set_list("results", good, (#good == 0) and (err and ("TMDB: " .. err) or "Nothing found on TMDB") or nil)
        AX.libmark()
        render()
    end)
end
function HV.AX.show_results()
    local AX = HV.AX
    AX.req = (AX.req or 0) + 1
    local keep = AX.rsel
    AX.set_list("results", AX.results or {})
    if keep and keep <= #AX.list then AX.sel = keep end
    AX.libmark()
    render()
end
-- "in your library" (matched titles) and "added" (added from this screen, before the library has caught up)
HV.AX.added_ids = {}
function HV.AX.libmark() HV.AX.libmark_list(HV.AX.results) end
function HV.AX.libmark_list(items)
    local AX = HV.AX
    PS.load_index()
    local lib = {}
    for _, e in pairs(PS.idx or {}) do
        if type(e) == "table" and e.id and not e.coll then lib[((e.kind == "movie") and "movie" or "tv") .. ":" .. tostring(e.id)] = true end
    end
    for _, it in ipairs(items or {}) do
        local key = it.kind .. ":" .. tostring(it.id)
        it.inlib = lib[key] or nil
        it.added = AX.added_ids[key] or nil
    end
end

-- IMDb id (the add-ons look releases up by it); a series goes straight to every release of every season
function HV.AX.pick_title(t)
    local AX = HV.AX
    if AX.stage == "results" then AX.rsel = AX.sel; AX.from_home = nil end
    AX.title = t
    AX.season, AX.ep, AX.m, AX.packs_m, AX.note = nil, nil, nil, nil, nil
    AX.filt, AX.fedit = "", false
    AX.set_list(t.kind == "tv" and "packs" or "releases", {}, "Looking up " .. t.name .. "…")
    render()
    if t.kind == "movie" and t.imdb and t.imdb ~= "" then return AX.find_releases({ { id = t.imdb } }, "movie", "releases") end
    local path = string.format("/%s/%d?language=en-US&append_to_response=external_ids", t.kind, t.id)
    PS.api(path, function(d)
        if HV.mode ~= "add" or AX.title ~= t then return end
        t.imdb = d and (d.imdb_id or (type(d.external_ids) == "table" and d.external_ids.imdb_id)) or nil
        if not d then AX.set_list(AX.stage, {}, "TMDB did not answer - press Esc and try again"); render(); return end
        if not t.imdb or t.imdb == "" then AX.set_list(AX.stage, {}, "TMDB has no IMDb id for this title - the add-ons cannot look it up"); render(); return end
        if t.kind == "tv" then
            local seasons = {}
            for _, se in ipairs(type(d.seasons) == "table" and d.seasons or {}) do
                local n = tonumber(se.season_number)
                if n and n > 0 then seasons[#seasons + 1] = { season = n, first = 1, count = tonumber(se.episode_count) or 0, name = se.name } end
            end
            t.tmdb_seasons = seasons
            local anime = false
            for _, g in ipairs(type(d.genres) == "table" and d.genres or {}) do if tonumber(g.id) == 16 then anime = true end end
            anime = anime and (d.original_language == "ja" or d.original_language == "zh" or d.original_language == "ko")
            AX.cinemeta(t, function()
                if AX.title ~= t or HV.mode ~= "add" then return end
                -- anime: the id map (for parts listed under another IMDb title) is fetched first if it isn't here yet
                if anime and o.anime_lookup and PS.am_ready then
                    PS.am_ready(function() if AX.title == t and HV.mode == "add" then AX.series_releases() end end, true)
                else AX.series_releases() end
            end)
        else
            AX.find_releases({ { id = t.imdb } }, "movie", "releases")
        end
    end)
end

-- seasons and episodes as the add-ons number them
function HV.AX.cinemeta(t, cb)
    if t.cm ~= nil then return cb() end
    PS.http({ url = HV.AX.CINEMETA .. "/meta/series/" .. t.imdb .. ".json", timeout = 20 }, function(code, body)
        t.cm = false
        local ok, d = pcall(utils.parse_json, body or "")
        local vids = (code == 200 and ok and type(d) == "table" and type(d.meta) == "table" and type(d.meta.videos) == "table") and d.meta.videos or nil
        if vids then
            local by, seasons = {}, {}
            for _, v in ipairs(vids) do
                local s, e = tonumber(v.season), tonumber(v.episode or v.number)
                if s and e and s > 0 then
                    if not by[s] then by[s] = {}; seasons[#seasons + 1] = s end
                    table.insert(by[s], { episode = e, name = v.name or v.title, overview = v.overview or v.description, released = v.released })
                end
            end
            table.sort(seasons)
            local out = {}
            for _, s in ipairs(seasons) do
                table.sort(by[s], function(a, b) return a.episode < b.episode end)
                out[#out + 1] = { season = s, first = by[s][1].episode, count = #by[s], eps = by[s] }
            end
            if #out > 0 then t.cm = out end
        end
        cb()
    end)
end
function HV.AX.slist(t) return (t and t.cm) or (t and t.tmdb_seasons) or {} end

-- ---- asking the add-ons, paced ----
-- AIOStreams allows (by default) 10 Stremio stream requests per 15 s and 5 search-API requests per 10 s per IP;
-- going over returns HTTP 429. Requests to one host wait their turn; a 429 is retried after the window.
HV.AX.lanes = {}
function HV.AX.lane(key, win, max)
    local l = HV.AX.lanes[key]
    if not l then l = { win = win, max = max, times = {}, q = {} }; HV.AX.lanes[key] = l end
    return l
end
function HV.AX.pump(l)
    local now = mp.get_time()
    local keep = {}
    for _, t in ipairs(l.times) do if now - t < l.win then keep[#keep + 1] = t end end
    l.times = keep
    while #l.q > 0 and #l.times < l.max do
        local job = table.remove(l.q, 1)
        l.times[#l.times + 1] = now
        job()
    end
    if #l.q > 0 and not l.timer then
        local wait = math.max(0.2, (l.times[1] or now) + l.win - now + 0.1)
        l.timer = mp.add_timeout(wait, function() l.timer = nil; HV.AX.pump(l) end)
    end
end
function HV.AX.enqueue(l, job, front)
    if front then table.insert(l.q, 1, job) else l.q[#l.q + 1] = job end
    HV.AX.pump(l)
end
function HV.AX.throttled(l)       -- a 429: treat the window as full from now on
    local now = mp.get_time()
    l.times = {}
    for _ = 1, l.max do l.times[#l.times + 1] = now end
end

-- The sources: one per add-on URL. AIOStreams with aiostreams_password set uses its search API (real fields:
-- folder, folder size, cached, already-in-library, release group, languages); everything else the Stremio answer.
function HV.AX.sources()
    local AX = HV.AX
    local out = {}
    local pw = tostring(o.aiostreams_password or "")
    for _, u in ipairs(AX.urls()) do
        local src = { url = u, host = AX.host(u) }
        local root, uuid = u:match("^(https?://.-)/stremio/([%w%-]+)/[^/]+$")
        if root and pw ~= "" and not (AX.api_bad or {})[u] then
            src.api = root .. "/api/v1/search"
            src.auth = "Authorization: Basic " .. AX.b64enc(uuid .. ":" .. pw)
        end
        out[#out + 1] = src
    end
    return out
end

function HV.AX.fetch(src, kind, id, cb0, keep)
    local AX = HV.AX
    local req = AX.req
    local api = src.api ~= nil
    local url = api and (src.api .. "?type=" .. kind .. "&id=" .. U.url_encode_segment(id))
        or (src.url .. "/stream/" .. kind .. "/" .. id .. ".json")
    AX.cache = AX.cache or {}
    local c = AX.cache[url]
    if c and os.time() - c.t < 1200 then return cb0(200, c.d, api) end
    AX.flying = AX.flying or {}
    local fl = AX.flying[url]
    if fl then fl.cbs[#fl.cbs + 1] = cb0; if not keep then fl.keep = true end; return end
    fl = { cbs = { cb0 }, keep = keep }
    AX.flying[url] = fl
    local function cb(code, d, a)
        if AX.flying[url] == fl then AX.flying[url] = nil end
        for _, f in ipairs(fl.cbs) do f(code, d, a) end
    end
    local l = api and AX.lane(src.host .. "#api", 10, 5) or AX.lane(src.host .. "#st", 15, 10)
    local tries = 0
    local function go()
        -- you moved on (another title, back, closed): a question still waiting in line is dropped, not sent
        -- (unless something still waits for it: a prefetch, or the page that asked again)
        if req ~= AX.req and not fl.keep then l.times[#l.times] = nil; if AX.flying[url] == fl then AX.flying[url] = nil end; return end
        -- the password was refused meanwhile: don't send the rest, the caller falls back to the Stremio answer
        if api and (AX.api_bad or {})[src.url] then l.times[#l.times] = nil; return cb(401, nil, true) end
        PS.http({ url = url, timeout = 45, headers = api and { src.auth } or nil }, function(code, body)
            if code == 429 and tries < 3 then
                tries = tries + 1
                AX.throttled(l)
                AX.enqueue(l, go, true)
                return
            end
            local ok, d = pcall(utils.parse_json, body or "")
            if not ok or type(d) ~= "table" then d = nil end
            if code == 200 and d then AX.cache[url] = { t = os.time(), d = d } end
            cb(code, d, api)
        end)
    end
    AX.enqueue(l, go)
end

-- ---- one release, from either kind of answer ----
function HV.AX.from_stremio(st)
    local AX = HV.AX
    local bh = type(st.behaviorHints) == "table" and st.behaviorHints or {}
    local sd = type(st.streamData) == "table" and st.streamData or {}
    local nm = AX.norm(st.name or "")
    local desc = AX.norm(st.description or st.title or "")
    local text = nm .. "\n" .. desc
    local it = { name_raw = nm, desc_raw = desc }
    it.file = bh.filename or sd.filename
    it.fsize = tonumber(bh.videoSize) or tonumber(sd.size)
    it.psize = tonumber(sd.folderSize)
    it.folder = sd.folderName
    it.hash = st.infoHash and tostring(st.infoHash):lower() or nil
    it.idx = tonumber(st.fileIdx)
    it.url = st.url
    -- "tracker:udp://..." sources: the trackers of the torrent (used when it is streamed with rqbit)
    for _, s in ipairs(type(st.sources) == "table" and st.sources or {}) do
        local tr = type(s) == "string" and s:match("^tracker:(%a+://%S+)$")
        if tr then it.trackers = it.trackers or {}; it.trackers[#it.trackers + 1] = tr end
    end
    if not it.hash and st.url then
        local fi = AX.fileinfo(st.url)
        if fi then
            it.hash = fi.hash and tostring(fi.hash):lower() or nil
            if fi.title and fi.title ~= it.file then it.folder = it.folder or fi.title end
            it.idx = it.idx or tonumber(fi.fileIndex) or tonumber(fi.index)
        else
            local h = tostring(st.url):match("%f[%x](" .. ("%x"):rep(40) .. ")%f[^%x]")
            it.hash = h and h:lower() or nil
        end
    end
    -- lines of the description: a line naming the file, the one above it (Torrentio-style) the folder
    local lines = {}
    for ln in desc:gmatch("[^\n]+") do lines[#lines + 1] = ln end
    if not it.file then
        for _, ln in ipairs(lines) do
            local clean = ln:gsub("^[^%w%[%(]+", ""):gsub("%s+$", "")
            if U.is_media(clean) and not clean:find("/", 1, true) then it.file = clean break end
        end
    end
    for i, ln in ipairs(lines) do
        local clean = ln:gsub("^[^%w%[%(]+", ""):gsub("%s+$", "")
        local f_ = clean:match("^(.-)/([^/]+%.%w%w%w)$")
        if f_ and f_ ~= "" and ln:find("📁", 1, true) then it.folder = it.folder or f_ end
        if ln:find("📁", 1, true) and not f_ and #clean > 4 then it.folder = it.folder or clean end
        if ln:find("📄", 1, true) and #clean > 4 then it.file = it.file or clean end
        if it.file and clean == it.file and i > 1 then
            local prev = lines[i - 1]:gsub("^[^%w%[%(]+", ""):gsub("%s+$", "")
            if #prev > 8 and not prev:find("💾", 1, true) and not prev:find("👤", 1, true) and prev ~= it.file and (prev:find("%.") or prev:find("%[")) then it.folder = it.folder or prev end
        end
    end
    -- sizes: the add-on's videoSize is the file; a larger size in the text is the folder / pack
    local sz = AX.sizes_of(desc)
    if #sz == 0 then sz = AX.sizes_of(nm) end
    if it.fsize then
        for _, s in ipairs(sz) do if s > it.fsize * 1.3 and not it.psize then it.psize = s end end
    elseif #sz >= 2 then
        it.fsize = math.min(sz[1], sz[2]); local big = math.max(sz[1], sz[2]); if big > it.fsize * 1.3 then it.psize = big end
    elseif #sz == 1 then it.size_only = sz[1] end
    it.seeds = AX.num(text, "👤%s*([%d,]+)") or AX.num(text, "👥%s*([%d,]+)") or AX.num(text, "🌱%s*([%d,]+)") or AX.num(text, "⇄%s*([%d,]+)")
        or AX.num(text:lower(), "seeders?:?%s*([%d,]+)")
    local lnm = nm:lower()
    if nm:find("%[%u%u%+%]") or nm:find("⚡", 1, true) or (text:find("Ready", 1, true) and not text:find("Not Ready", 1, true))
        or lnm:find("instant") then it.cached = true
    elseif nm:find("⏳", 1, true) or lnm:find("download%]") or text:find("Not Ready", 1, true) or lnm:find("uncached") then it.cached = false end
    if text:find("Your Media", 1, true) or text:find("📌 Library", 1, true) then it.inlib = true end
    it.res, it.rank = AX.res_of(text .. " " .. tostring(it.file or ""))
    -- languages written as codes ("JA · EN") or as flags
    local langs = {}
    for _, ln in ipairs(lines) do
        local c = ln:gsub("[%s·|/•,]", ""):gsub("\194\183", "")
        if #c >= 2 and #c <= 16 and c:match("^%u+$") and #c % 2 == 0 then
            for code in ln:gmatch("%u%u") do langs[#langs + 1] = code end
        end
    end
    local flags = 0
    for _ in text:gmatch("\240\159\135[\166-\191]\240\159\135[\166-\191]") do flags = flags + 1 end
    if #langs > 0 then it.langs = langs elseif flags >= 2 then it.nlang = flags end
    it.grp_hint = text:match("🏷️%s*([^%s·|]+)")
    return it
end

function HV.AX.from_api(r)
    local AX = HV.AX
    local pf = type(r.parsedFile) == "table" and r.parsedFile or {}
    local it = { api = true }
    it.hash = r.infoHash and tostring(r.infoHash):lower() or nil
    it.idx = tonumber(r.fileIdx)
    it.url = r.url
    it.file = r.filename
    it.folder = r.folderName
    it.fsize = tonumber(r.size)
    it.psize = tonumber(r.folderSize)
    if r.cached == true then it.cached = true elseif r.cached == false then it.cached = false end
    it.inlib = r.library == true or nil
    it.seeds = tonumber(r.seeders)
    it.res = tostring(pf.resolution or "")
    if it.res == "2160p" then it.res = "4K" end
    local _, rank = AX.res_of(it.res)
    it.rank = rank
    it.quality, it.encode, it.group = pf.quality, pf.encode, pf.releaseGroup
    it.audio = (type(pf.audioTags) == "table" and #pf.audioTags > 0) and pf.audioTags or nil
    it.langs = (type(pf.languages) == "table" and #pf.languages > 0) and pf.languages or nil
    it.spack = pf.seasonPack == true
    it.pseasons = type(pf.seasons) == "table" and pf.seasons or (type(pf.folderSeasons) == "table" and pf.folderSeasons or nil)
    local nb = {}
    for _, v in ipairs({ r.addon, r.indexer, r.service }) do if type(v) == "string" and v ~= "" then nb[#nb + 1] = v end end
    it.name_raw = table.concat(nb, " · ")
    local dl = {}
    for _, v in ipairs({ r.folderName, r.filename }) do if type(v) == "string" and v ~= "" then dl[#dl + 1] = v end end
    it.desc_raw = table.concat(dl, "\n")
    if not it.hash and r.url then local fi = AX.fileinfo(r.url); if fi and fi.hash then it.hash = tostring(fi.hash):lower() end end
    if not it.hash and not it.url then return nil end
    return it
end

-- fold a newly heard release into the merged list (same torrent from several add-ons / queries = one row)
function HV.AX.merge(m, it, src, q)
    local AX = HV.AX
    local key = it.hash or ("url:" .. tostring(it.url))
    local cur = m.by[key]
    if not cur then
        cur = it
        cur.srcs, cur.qids, cur.nq, cur.qs = {}, {}, 0, {}
        m.by[key] = cur
        m.order[#m.order + 1] = cur
    else
        for k, v in pairs(it) do if cur[k] == nil then cur[k] = v end end
        if it.cached == true then cur.cached = true end
        if it.api then          -- the search API knows better than parsed text
            for _, k in ipairs({ "folder", "psize", "fsize", "group", "langs", "spack", "pseasons", "quality", "encode", "audio", "inlib" }) do
                if it[k] ~= nil then cur[k] = it[k] end
            end
            cur.api = true
        end
        if (it.seeds or 0) > (cur.seeds or 0) then cur.seeds = it.seeds end
    end
    if cur.hash and AX.known()[cur.hash] and cur.cached == nil then cur.cached = true end
    cur._fin = nil                 -- worked out again at the next relist
    cur.srcs[src.host] = true
    if q.id and not cur.qids[q.id] then cur.qids[q.id] = true; cur.nq = cur.nq + 1 end
    if q.season then cur.qs[q.season] = true end
end

-- labels, pack-or-not, seasons covered, tags: computed when the list is rebuilt
function HV.AX.finish(it, all_seasons)
    local AX = HV.AX
    local fname = it.file or ""
    local folder = it.folder
    if folder and fname ~= "" and folder:gsub("%.%w%w%w?$", "") == fname:gsub("%.%w%w%w?$", "") then folder = nil; it.folder = nil end
    it.title = folder or (fname ~= "" and fname) or (it.desc_raw or ""):match("^[^%w%[%(]*([^\n]+)") or "?"
    local tg = AX.tags_of(folder or fname)
    if folder and fname ~= "" then
        local tf = AX.tags_of(fname)
        for k, v in pairs(tf) do if tg[k] == nil or (type(v) == "table" and #tg[k] == 0) then tg[k] = v end end
    end
    -- the add-on's own text fills what the names don't say (codec, source, audio)
    local td = AX.tags_of(it.desc_raw or "")
    for _, k in ipairs({ "src", "codec", "bit", "hdr" }) do if tg[k] == nil then tg[k] = td[k] end end
    if #tg.audio == 0 then tg.audio = td.audio end
    it.tg = tg
    it.group = it.group or tg.group or it.grp_hint
    -- pack?
    local sc, a, b, c = AX.scope(folder or "")
    if it.spack then it.pack = true
    elseif it.psize and it.fsize and it.psize > it.fsize * 1.5 then it.pack = true
    elseif folder and sc ~= "episode" then it.pack = true
    elseif it.nq > 1 then it.pack = true
    elseif fname ~= "" and not folder and not it.psize then it.pack = false
    elseif AX.scope(fname ~= "" and fname or it.title) == "episode" then it.pack = false
    else it.pack = nil end
    -- what it holds
    local cov = {}
    local label
    if it.pack then
        local ps = it.pseasons
        if ps and #ps > 1 and sc ~= "range" then
            local lo, hi = math.huge, 0
            for _, s in ipairs(ps) do lo = math.min(lo, s); hi = math.max(hi, s); cov[s] = true end
            label = (#all_seasons > 1 and #ps >= #all_seasons) and "Complete series" or string.format("Seasons %d–%d", lo, hi)
        elseif sc == "multi" then for s = a, b do cov[s] = true end; label = string.format("Seasons %d–%d", a, b)
        elseif sc == "range" then
            label = string.format("Episodes %d–%d", a, b)
            if c then cov[c] = true end
            if ps and #ps > 0 then
                for _, s in ipairs(ps) do cov[s] = true end
                label = label .. ((#ps > 1) and string.format(" (seasons %d–%d)", ps[1], ps[#ps]) or (" (season " .. ps[1] .. ")"))
            end
        elseif sc == "season" or (ps and #ps == 1) then local s = a or ps[1]; cov[s] = true; label = "Season " .. s .. " pack"
        elseif sc == "complete" then for _, s in ipairs(all_seasons) do cov[s] = true end; label = "Complete series"
        else label = "Pack" end
        if not next(cov) then for s in pairs(it.qs) do cov[s] = true end end
    else
        local el = AX.ep_label(fname ~= "" and fname or it.title)
        if AX.m and AX.m.kind == "movie" then label = (it.pack == false) and "Single file" or ""
        else label = (it.pack == false) and ("Single file" .. (el and (" · " .. el) or "")) or ((el and (el .. " · ") or "") .. "contents unknown") end
        for s in pairs(it.qs) do cov[s] = true end
    end
    -- found only through a part (TYBW...): say which part, the release's own "Season 1" is that part's
    local only_part, plabel = true, nil
    for s_ in pairs(it.qs) do
        if s_ >= 1000 then
            cov[s_] = true
            for _, pt in ipairs((AX.title and AX.title.parts) or {}) do if pt.key == s_ then plabel = pt.label end end
        else only_part = false end
    end
    if only_part and plabel and next(it.qs) then label = plabel .. " · " .. label end
    it.cov, it.label = cov, label
    local n = 0
    for _ in pairs(cov) do n = n + 1 end
    it.ncov = n
    it.size = it.psize or it.fsize or it.size_only
    -- text the filter searches
    local bits = { it.title, fname, it.group or "", it.res or "", it.quality or "", it.encode or "", label, it.name_raw or "", it.desc_raw or "" }
    for _, v in pairs(tg) do if type(v) == "string" then bits[#bits + 1] = v elseif type(v) == "table" then bits[#bits + 1] = table.concat(v, " ") end end
    if it.langs then bits[#bits + 1] = table.concat(it.langs, " ") end
    if it.cached == true then bits[#bits + 1] = "cached" end
    it.hay = AX.norm(table.concat(bits, " ")):lower()
end

-- ---- finding releases (progressive: the list fills in as answers arrive) ----
function HV.AX.find_releases(qs, kind, stage)
    local AX = HV.AX
    local srcs = AX.sources()
    AX.req = (AX.req or 0) + 1
    local req = AX.req
    local m = { by = {}, order = {}, total = #srcs * #qs, done = 0, failed = {}, fails = {}, kind = kind, stage = stage, raw = {} }
    AX.m = m
    AX.sfilter = 0
    AX.set_list(stage, {}, nil)
    AX.raw = m.raw
    if PS.rd_on() then AX.rd_load(false, function() if AX.m == m and AX.stage == m.stage then AX.relist(false) end end) end
    AX.relist(true)
    for _, q in ipairs(qs) do
        for _, src in ipairs(srcs) do
            local function handle(code, d, api)
                if req ~= AX.req or HV.mode ~= "add" then return end
                if api and (code == 401 or code == 403) then
                    -- wrong AIOStreams password: say so once and fall back to the Stremio answer for this add-on
                    AX.api_bad = AX.api_bad or {}
                    AX.api_bad[src.url] = true
                    PS.notice("aio", "AIOStreams did not accept aiostreams_password - showing its normal add-on answers instead")
                    src.api, src.auth = nil, nil
                    AX.fetch(src, kind, q.id, handle)
                    return
                end
                m.done = m.done + 1
                local list
                if code == 200 and d then
                    if api then
                        list = (type(d.data) == "table" and type(d.data.results) == "table") and d.data.results or nil
                        local fl = type(d.data) == "table" and tonumber(d.data.filtered) or 0
                        m.filtered = math.max(m.filtered or 0, fl)
                    else list = type(d.streams) == "table" and d.streams or nil
                    end
                    if list then m.raw[#m.raw + 1] = { host = src.host, api = api, id = q.id, d = d } end
                end
                if not list then
                    if not m.fails[src.host] then
                        m.fails[src.host] = true
                        m.failed[#m.failed + 1] = src.host .. ((code == 0) and " (no answer)" or (code == 429) and " (too many requests)" or (" (HTTP " .. code .. ")"))
                    end
                else
                    for _, x in ipairs(list) do
                        if type(x) == "table" then
                            local it = api and AX.from_api(x) or AX.from_stremio(x)
                            if it then AX.merge(m, it, src, q) end
                        end
                    end
                end
                AX.relist_soon(m)              -- answers that arrive together (remembered ones all at once) are one relist
            end
            AX.fetch(src, kind, q.id, handle)
        end
    end
end

-- rebuild the visible list from the merged releases (season tab, filter, sort), keeping the cursor on its release
function HV.AX.relist(reset)
    local AX = HV.AX
    local m = AX.m
    if not m or AX.stage ~= m.stage then return end
    local all = {}
    for _, se in ipairs(AX.slist(AX.title)) do all[#all + 1] = se.season end
    -- only the releases an answer touched (and all of them when the title's seasons or parts changed); the filter,
    -- the sort and the season tabs just pick from what is worked out
    local fsig = table.concat(all, ",") .. "|" .. tostring(AX.title) .. "|" .. #((AX.title and AX.title.parts) or {}) .. "|" .. tostring(m.kind)
    if m.fsig ~= fsig then m.fsig = fsig; for _, it in ipairs(m.order) do it._fin = nil end end
    for _, it in ipairs(m.order) do if not it._fin then AX.finish(it, all); it._fin = true end end
    local cur = AX.list[AX.sel] and AX.list[AX.sel].rel
    local f = AX.sfilter or 0
    local words = {}
    for w in AX.norm(AX.filt or ""):lower():gmatch("%S+") do words[#words + 1] = w end
    local rows, hidden = {}, 0
    for _, it in ipairs(m.order) do
        local ok = true
        if m.stage == "packs" then
            if it.pack == false then ok = false; hidden = hidden + 1 end
            if ok and f ~= 0 and not it.cov[f] then ok = false end
        end
        if ok then
            for _, w in ipairs(words) do
                local neg = w:sub(1, 1) == "-" and #w > 1
                local hit = it.hay:find(neg and w:sub(2) or w, 1, true) ~= nil
                if hit == neg then ok = false break end
            end
        end
        if ok then rows[#rows + 1] = { rel = it } end
    end
    AX.sort_rows(rows)
    AX.list = rows
    AX.hidden = hidden
    AX.all_n = #m.order - hidden            -- before the filter words (the sort line says "12 of 40")
    local sel = 1
    if not reset and cur then for i, r in ipairs(rows) do if r.rel == cur then sel = i break end end end
    if reset then AX.top = 1 end
    AX.sel = math.max(1, math.min(sel, #rows))
    -- status line
    local parts = {}
    if AX.note then parts[#parts + 1] = AX.note end
    if AX.api_bad and next(AX.api_bad) then parts[#parts + 1] = "AIOStreams refused aiostreams_password (check it in the conf) - using its normal answers" end
    if m.kind == "nyaa" and m.done >= m.total and #m.order > 0 then
        parts[#parts + 1] = m.latest and "Latest trusted uploads on Nyaa.si  ·  ↑ at the top (or click the box) to search" or string.format("%d torrents from Nyaa.si (not checked for Real-Debrid cache)", #m.order)
    end
    if m.done < m.total then
        parts[#parts + 1] = (m.kind == "nyaa") and "Asking Nyaa.si…" or ((m.total > 1) and string.format("Asking the add-ons… %d of %d answers so far", m.done, m.total) or "Asking the add-ons…")
    elseif #m.order == 0 then parts[#parts + 1] = "No releases found"
    elseif #rows == 0 then parts[#parts + 1] = (#words > 0) and "Nothing matches the filter" or (f ~= 0 and (f >= 1000 and "No pack holds this part" or ("No pack holds season " .. f)) or "No packs found") end
    if m.stage == "packs" and hidden > 0 then parts[#parts + 1] = hidden .. " single-episode release" .. (hidden == 1 and "" or "s") .. " not shown - E picks one episode" end
    if #m.failed > 0 then parts[#parts + 1] = "no answer from " .. table.concat(m.failed, ", ") end
    if (m.filtered or 0) > 0 then parts[#parts + 1] = string.format("AIOStreams held back %d+ releases by your AIOStreams settings (e.g. uncached / result limits)", m.filtered) end
    AX.nyaa_tip = nil
    local few = math.max(0, math.floor(tonumber(o.nyaa_fallback_below) or 5))
    if m.kind ~= "nyaa" and m.done >= m.total and AX.title and #m.order < few and tostring(o.nyaa_fallback or "ask") ~= "no" then
        local t = AX.title
        if tostring(o.nyaa_fallback) == "auto" and AX.is_anime(t) and not m.auto_nyaa then
            m.auto_nyaa = true
            mp.add_timeout(0.5, function() if AX.m == m and HV.mode == "add" then AX.nyaa_for(t.name) end end)
        end
        AX.nyaa_tip = { text = ((#m.order == 0) and "No releases" or string.format("Only %d release%s", #m.order, #m.order == 1 and "" or "s"))
            .. " from " .. AX.addon_word(), name = t.name }
    end
    AX.msg = (#parts > 0) and table.concat(parts, "  ·  ") or nil
    if m.done >= m.total then
        if #m.failed > 0 then PS.notice("addons", "Add-on trouble: " .. table.concat(m.failed, ", ")) else PS.notice_ok("addons") end
    end
    render()
end
function HV.AX.refilter() HV.AX.relist(false) end
function HV.AX.relist_soon(m)
    local AX = HV.AX
    if AX.rl_t then return end
    AX.rl_t = mp.add_timeout(0, function()
        AX.rl_t = nil
        if AX.m and HV.mode == "add" then AX.relist(false) end        -- relist works on the current list (AX.m)
    end)
end

HV.AX.SORTS = { { "best", "Best match" }, { "big", "Biggest first" }, { "small", "Smallest first" }, { "name", "Name" }, { "seeds", "Most seeders" },
                 { "res", "Resolution" } }
-- Nyaa lists: only what Nyaa itself knows (no cache state, no add-on ranking). Default: newest for the latest uploads,
-- most seeders for a search - until you pick one.
HV.AX.NSORTS = { { "seeds", "Most seeders" }, { "new", "Newest first" }, { "big", "Biggest first" }, { "small", "Smallest first" } }
function HV.AX.sort_cur()
    local AX = HV.AX
    local nyaa = AX.m and AX.m.kind == "nyaa"
    local list = nyaa and AX.NSORTS or AX.SORTS
    local i = nyaa and (AX.nsortm or ((AX.m.latest) and 2 or 1)) or AX.sortm or 1
    i = math.max(1, math.min(#list, i))
    return list[i], i, list, nyaa
end
function HV.AX.sort_rows(rows)
    local AX = HV.AX
    local mode = AX.sort_cur()[1]
    local function cachedv(it) return (it.cached == true) and 2 or (it.cached == nil and 1 or 0) end
    table.sort(rows, function(x, y)
        local a, b = x.rel, y.rel
        if mode == "big" or mode == "small" then
            local sa, sb = a.size or 0, b.size or 0
            if sa ~= sb then if mode == "big" then return sa > sb else return sa < sb end end
        elseif mode == "name" then
            if a.title ~= b.title then return U.natural_less(a.title:lower(), b.title:lower()) end
        elseif mode == "seeds" then
            if (a.seeds or 0) ~= (b.seeds or 0) then return (a.seeds or 0) > (b.seeds or 0) end
        elseif mode == "res" then
            if a.rank ~= b.rank then return a.rank > b.rank end
        elseif mode == "new" then
            if (a.date or 0) ~= (b.date or 0) then return (a.date or 0) > (b.date or 0) end
        end
        if cachedv(a) ~= cachedv(b) then return cachedv(a) > cachedv(b) end
        if a.rank ~= b.rank then return a.rank > b.rank end
        if (a.ncov or 0) ~= (b.ncov or 0) then return (a.ncov or 0) > (b.ncov or 0) end
        if (a.seeds or 0) ~= (b.seeds or 0) then return (a.seeds or 0) > (b.seeds or 0) end
        if (a.size or 0) ~= (b.size or 0) then return (a.size or 0) > (b.size or 0) end
        return tostring(a.title) < tostring(b.title)
    end)
end
function HV.AX.cycle_sort()
    local AX = HV.AX
    if AX.stage ~= "packs" and AX.stage ~= "releases" then return end
    local _, i, list, nyaa = AX.sort_cur()
    if nyaa then AX.nsortm = i % #list + 1 else AX.sortm = i % #list + 1 end
    AX.relist(false)
end

-- series: the first episode of every season (finds that season's packs and the complete ones)
function HV.AX.series_releases()
    local AX = HV.AX
    local t = AX.title
    local qs = {}
    for i, se in ipairs(AX.slist(t)) do
        if i > 40 then break end
        qs[#qs + 1] = { id = string.format("%s:%d:%d", t.imdb, se.season, se.first or 1), season = se.season }
    end
    if #qs == 0 then qs[1] = { id = t.imdb .. ":1:1", season = 1 } end
    for _, q in ipairs(AX.anime_parts(t)) do qs[#qs + 1] = q end
    AX.find_releases(qs, "series", "packs")
    -- opened from a home card about one season ("Season 2" on AniList, a season that just started): its tab
    local tab = AX.want_tab(t)
    if tab ~= 0 then AX.sfilter = tab; AX.relist(true) end
end

-- Anime: parts the IMDb season list (Cinemeta) doesn't have - Bleach's Thousand-Year Blood War is TMDB's season 2
-- and TVDB's season 17, but Cinemeta lists 16 seasons, so "tt...:17:1" is never asked. The anime-lists map gives each
-- cour's Kitsu id; the add-ons accept "kitsu:<id>:<episode>". Each such TMDB season gets its own tab (1000 + season).
function HV.AX.anime_parts(t)
    local qs, parts, seen = {}, {}, {}
    t.parts = parts
    if not (PS.AM and PS.AM.map) then pcall(PS.am_load) end
    local map = PS.AM and PS.AM.map
    if not map then return qs end
    local names = {}
    for _, se in ipairs(t.tmdb_seasons or {}) do names[se.season] = se.name end
    -- the parts beyond the seasons the IMDb queries already cover: their TVDB season is past Cinemeta's last one
    -- (Bleach: Cinemeta stops at 16, TYBW is TVDB season 17), or they have no TVDB season and are a later TMDB one
    local cmax = 0
    for _, se in ipairs(HV.AX.slist(t)) do cmax = math.max(cmax, se.season) end
    local list = {}
    for _, e in ipairs(PS.am_entries("tv", t.id)) do
        if e.kitsu and ((e.tvs and e.tvs > cmax) or (not e.tvs and (e.s or 1) > 1)) then list[#list + 1] = e end
    end
    table.sort(list, function(a, b) if (a.s or 0) ~= (b.s or 0) then return (a.s or 0) < (b.s or 0) end return a.kitsu < b.kitsu end)
    msg.verbose(string.format("add-ons: %d anime part(s) beyond season %d for TMDB %s", #list, cmax, tostring(t.id)))
    for i, e in ipairs(list) do
        if i > 12 then break end
        local key = 1000 + (e.s or 0)
        if not seen[key] then
            seen[key] = true
            local nm = names[e.s or -1]
            parts[#parts + 1] = { key = key, label = (nm and nm ~= "" and not nm:match("^Season %d+$")) and nm or ("Part " .. (e.s or #parts + 1)) }
        end
        qs[#qs + 1] = { id = "kitsu:" .. e.kitsu .. ":1", season = key }
    end
    return qs
end

-- back to the pack list without asking again
function HV.AX.show_packs()
    local AX = HV.AX
    -- left while it was still asking the add-ons: asked again (the answers already in are cached), else it stayed half-filled
    local pm = AX.packs_m
    if pm and (pm.done or 0) < (pm.total or 0) and AX.title and AX.title.imdb then AX.packs_m = nil; return AX.series_releases() end
    if AX.packs_m then
        AX.m = AX.packs_m
        AX.req = (AX.req or 0) + 1
        AX.stage, AX.hover = "packs", nil
        AX.relist(true)
    elseif AX.title and AX.title.imdb then AX.series_releases() end
end

function HV.AX.season_tab(d)
    local AX = HV.AX
    if AX.stage ~= "packs" or not AX.title then return end
    local opts = { 0 }
    for _, se in ipairs(AX.slist(AX.title)) do opts[#opts + 1] = se.season end
    for _, pt in ipairs(AX.title.parts or {}) do opts[#opts + 1] = pt.key end
    local cur = 1
    for i, s in ipairs(opts) do if s == (AX.sfilter or 0) then cur = i end end
    cur = ((cur - 1 + d) % #opts) + 1
    AX.sfilter = opts[cur]
    AX.relist(true)
end

-- the single-episode path (E): season -> episode -> that episode's releases
function HV.AX.show_seasons()
    local AX = HV.AX
    if AX.m and AX.m.stage == "packs" then AX.packs_m = AX.m end
    local rows = {}
    for _, se in ipairs(AX.slist(AX.title)) do
        rows[#rows + 1] = { season = se.season, text = "Season " .. se.season, chips = { { string.format("%d episodes", se.count or 0) } } }
    end
    AX.set_list("seasons", rows, (#rows == 0) and "No seasons found" or nil)
    render()
end

function HV.AX.pick_season(se)
    local AX = HV.AX
    AX.season = se.season
    local t = AX.title
    if t.cm then
        for _, s in ipairs(t.cm) do
            if s.season == se.season then
                local eps = {}
                for _, ep in ipairs(s.eps) do
                    eps[#eps + 1] = { episode = ep.episode, text = string.format("%d.  %s", ep.episode, ep.name or ("Episode " .. ep.episode)),
                        chips = { { tostring(ep.released or ""):sub(1, 10) } }, note = tostring(ep.overview or "") }
                end
                AX.episodes = eps
                return AX.show_episodes()
            end
        end
    end
    AX.set_list("episodes", {}, "Loading season " .. se.season .. "…")
    render()
    PS.api(string.format("/tv/%d/season/%d?language=en-US", t.id, se.season), function(d)
        if HV.mode ~= "add" or AX.season ~= se.season or AX.stage ~= "episodes" then return end
        local eps = {}
        for _, ep in ipairs(d and d.episodes or {}) do
            local n = tonumber(ep.episode_number)
            if n then eps[#eps + 1] = { episode = n, text = string.format("%d.  %s", n, ep.name or ("Episode " .. n)),
                chips = { { tostring(ep.air_date or "") } }, note = tostring(ep.overview or "") } end
        end
        AX.episodes = eps
        AX.show_episodes()
    end)
end
function HV.AX.show_episodes() local AX = HV.AX; AX.req = (AX.req or 0) + 1; AX.set_list("episodes", AX.episodes or {}); render() end

-- ---- the add screen's home: what is trending / popular / airing (TMDB and AniList) ----
-- kind: "tmdb" one TMDB list | "providers" the streaming services of addon_providers, mixed into one row | "anilist" an
-- AniList list, matched to TMDB through the anime-lists map | "seasons" shows whose newest season started lately
HV.AX.HOME = {
    { id = "trend", title = "Trending today", kind = "tmdb", path = "/trending/all/day", rank = true },
    { id = "stream", title = "Popular on the streaming services", kind = "providers" },
    { id = "atrend", title = "Trending anime", kind = "anilist" },
    { id = "anew", title = "Anime that just started airing", kind = "anilist", fresh = true },
    { id = "seasons", title = "New seasons", kind = "seasons" },
    { id = "movies", title = "Trending movies", kind = "tmdb", path = "/trending/movie/week", media = "movie", rank = true },
}
HV.AX.HOME_TTL = 3 * 3600
-- one TMDB answer row -> a title (same shape as a search result)
function HV.AX.item_of(r, kind)
    kind = r.media_type or kind
    if kind ~= "tv" and kind ~= "movie" then return nil end
    local poster = (type(r.poster_path) == "string" and r.poster_path ~= "") and r.poster_path or nil
    if not poster then return nil end
    local yr = tostring(r.first_air_date or r.release_date or ""):sub(1, 4)
    local it = { kind = kind, id = r.id, name = r.name or r.title or "?", year = yr, poster = poster,
        overview = tostring(r.overview or ""), votes = tonumber(r.vote_count), vote = tonumber(r.vote_average) or 0 }
    it.text = it.name .. (yr ~= "" and ("  (" .. yr .. ")") or "")
    for _, g in ipairs(type(r.genre_ids) == "table" and r.genre_ids or {}) do
        if tonumber(g) == 16 and r.original_language == "ja" then it.anime = true end
    end
    return it
end

-- the services of addon_providers: { name, ids = "9|119" }
function HV.AX.providers()
    local out = {}
    for part in tostring(o.addon_providers or ""):gmatch("[^;]+") do
        local name, ids = part:match("^%s*(.-)%s*=%s*([%d|,%s]+)%s*$")
        ids = ids and ids:gsub("[,%s]+", "|"):gsub("|+", "|"):gsub("^|", ""):gsub("|$", "")
        if name and name ~= "" and ids and ids ~= "" then out[#out + 1] = { name = name, ids = ids } end
    end
    return out
end
function HV.AX.region() return (tostring(o.addon_region or ""):upper():match("^%s*(%a%a)%s*$")) or "US" end

function HV.AX.home_tmdb(def, row, done)
    PS.api(def.path .. (def.path:find("?", 1, true) and "&" or "?") .. "language=en-US", function(d, err)
        local out = {}
        for _, r in ipairs(d and d.results or {}) do
            local it = HV.AX.item_of(r, def.media)
            if it then out[#out + 1] = it end
        end
        done(out, err)
    end)
end

-- Netflix series, Netflix film, Prime Video series... in turns, so every service is near the front; each title once
function HV.AX.home_providers(def, row, done)
    local AX = HV.AX
    local provs = AX.providers()
    if #provs == 0 then return done({}, "addon_providers is empty") end
    local names = {}
    for _, p in ipairs(provs) do names[#names + 1] = p.name end
    row.title = "Popular on " .. table.concat(names, " · ")
    local lists, left, err0 = {}, #provs * 2, nil
    for pi, p in ipairs(provs) do
        for ki, kind in ipairs({ "tv", "movie" }) do
            local slot = (pi - 1) * 2 + ki
            PS.api(string.format("/discover/%s?language=en-US&sort_by=popularity.desc&watch_region=%s&with_watch_monetization_types=flatrate&with_watch_providers=%s",
                kind, AX.region(), U.url_encode_segment(p.ids)), function(d, err)
                local l = {}
                for _, r in ipairs(d and d.results or {}) do
                    local it = AX.item_of(r, kind)
                    if it then it.via = p.name; l[#l + 1] = it end
                end
                lists[slot], err0, left = l, err0 or err, left - 1
                if left > 0 then return end
                local out, seen, i = {}, {}, 1
                while #out < 60 do
                    local any = false
                    for s = 1, #provs * 2 do
                        local it = lists[s] and lists[s][i]
                        if it then
                            any = true
                            local k = it.kind .. ":" .. tostring(it.id)
                            if not seen[k] then seen[k] = true; out[#out + 1] = it end
                        end
                    end
                    if not any then break end
                    i = i + 1
                end
                done(out, err0)
            end)
        end
    end
end

-- AniList: trending now / started airing in the last 100 days (by popularity). The anime-lists map turns AniList
-- entries into TMDB titles (and says which TMDB / TVDB season it is); unmapped ones are looked up on TMDB when opened.
HV.AX.AL_FIELDS = "id format seasonYear startDate{year} averageScore title{romaji english} coverImage{extraLarge large} description(asHtml:false)"
function HV.AX.item_of_al(m)
    if type(m) ~= "table" or not tonumber(m.id) then return nil end
    local t = type(m.title) == "table" and m.title or {}
    local cov = type(m.coverImage) == "table" and (m.coverImage.extraLarge or m.coverImage.large) or nil
    if type(cov) ~= "string" or not cov:match("^https?://") then return nil end
    local eng, rom = type(t.english) == "string" and t.english or nil, type(t.romaji) == "string" and t.romaji or nil
    local name = (eng and eng ~= "") and eng or rom or "?"
    local y = tonumber(type(m.startDate) == "table" and m.startDate.year or nil) or tonumber(m.seasonYear)
    local map = PS.AM and PS.AM.map and PS.AM.map[string.format("%d", tonumber(m.id))]
    local desc = tostring(type(m.description) == "string" and m.description or ""):gsub("<[Bb][Rr]%s*/?>", " "):gsub("<[^>]*>", "")
    local it = { kind = map and map.kind or ((m.format == "MOVIE") and "movie" or "tv"), id = map and tonumber(map.id) or nil,
        al = tonumber(m.id), name = name, romaji = rom, year = y and tostring(y) or "", poster = cov,
        overview = (HV.AX.unhtml(desc):gsub("%s+", " "):gsub("^%s+", "")), vote = (tonumber(m.averageScore) or 0) / 10,
        ms = map and map.s or nil, mtvs = map and map.tvs or nil, src = "AniList" }
    it.text = it.name .. (it.year ~= "" and ("  (" .. it.year .. ")") or "")
    return it
end
function HV.AX.home_anilist(def, row, done)
    local AX = HV.AX
    local q
    if def.fresh then
        local t = os.date("*t", os.time() - 100 * 86400)
        q = string.format("{Page(perPage:30){media(type:ANIME,isAdult:false,status:RELEASING,startDate_greater:%04d%02d%02d,format_in:[TV,TV_SHORT,ONA],sort:POPULARITY_DESC){%s}}}",
            t.year, t.month, t.day, AX.AL_FIELDS)
    else
        q = string.format("{Page(perPage:30){media(type:ANIME,isAdult:false,sort:TRENDING_DESC){%s}}}", AX.AL_FIELDS)
    end
    PS.al_gql(q, function(d, err)
        local media = d and type(d.data) == "table" and type(d.data.Page) == "table" and d.data.Page.media
        if type(media) ~= "table" then return done({}, err or "AniList sent no list") end
        local function build()
            local out = {}
            for _, m in ipairs(media) do
                local it = AX.item_of_al(m)
                if it then out[#out + 1] = it end
            end
            done(out)
        end
        -- the id map (downloaded once, ~6 MB) turns them into TMDB titles; without it they are looked up when opened
        if o.anime_lookup and PS.am_ready then PS.am_ready(build, true) else build() end
    end)
end

-- New seasons: popular shows (older than half a year) with episodes in the last 45 days, kept when their newest season
-- (2 or later) began within the last 60 days - so a long-running show that merely aired an episode does not count.
function HV.AX.home_seasons(def, row, done)
    local AX = HV.AX
    local now = os.time()
    local function day(n) return os.date("!%Y-%m-%d", now - n * 86400) end
    local base = string.format("/discover/tv?language=en-US&sort_by=popularity.desc&air_date.gte=%s&air_date.lte=%s&first_air_date.lte=%s"
        .. "&without_genres=10763%%7C10764%%7C10766%%7C10767", day(45), day(0), day(180))
    local cands, seen, pages = {}, {}, 2
    local function details()
        if #cands == 0 then return done({}, "TMDB had no candidates") end
        local keep, left = {}, #cands
        for i, it in ipairs(cands) do
            PS.api(string.format("/tv/%s?language=en-US", tostring(it.id)), function(d)
                local last = d and type(d.last_episode_to_air) == "table" and d.last_episode_to_air or nil
                local sn = last and tonumber(last.season_number)
                if sn and sn >= 2 then
                    for _, se in ipairs(type(d.seasons) == "table" and d.seasons or {}) do
                        local ad = tostring(se.air_date or "")
                        if tonumber(se.season_number) == sn and ad >= day(60) and ad <= day(0) then
                            it.season, it.sdate = sn, ad
                            keep[i] = it
                        end
                    end
                end
                left = left - 1
                if left > 0 then return end
                local out = {}
                for j = 1, #cands do if keep[j] then out[#out + 1] = keep[j] end end
                done(out, (#out == 0) and "no show started a new season lately" or nil)
            end)
        end
    end
    local got = 0
    for page = 1, pages do
        PS.api(base .. "&page=" .. page, function(d)
            for _, r in ipairs(d and d.results or {}) do
                local it = AX.item_of(r, "tv")
                if it and not seen[it.id] and #cands < 40 then seen[it.id] = true; cands[#cands + 1] = it end
            end
            got = got + 1
            if got == pages then details() end
        end)
    end
end

-- Rows are kept 3 hours, on disk too (addon_home.json), so the screen opens instantly after a restart.
function HV.AX.home_path() return PS.dir() .. "/addon_home.json" end
HV.AX.HOME_FIELDS = { "kind", "id", "al", "name", "romaji", "year", "poster", "overview", "votes", "vote", "text", "via", "season", "sdate", "ms", "mtvs", "src" }
function HV.AX.home_save()
    local AX = HV.AX
    local H = AX.home
    if not H then return end
    for _, r in ipairs(H.rows) do if r.loading or r.err then return end end     -- only complete sets are kept
    local out = { v = 2, t = H.t, region = AX.region(), providers = tostring(o.addon_providers or ""), rows = {} }
    for i, r in ipairs(H.rows) do
        local items = {}
        for _, it in ipairs(r.items) do
            local c = {}
            for _, k in ipairs(AX.HOME_FIELDS) do c[k] = it[k] end
            items[#items + 1] = c
        end
        out.rows[i] = { id = r.id, title = r.title, items = items }
    end
    PS.mkdir()
    pcall(atomic_write, AX.home_path(), safe_json(out) or "{}")
end
function HV.AX.home_disk()
    local AX = HV.AX
    local d = try_load_json(AX.home_path())
    if type(d) ~= "table" or d.v ~= 2 or type(d.rows) ~= "table" or os.time() - (tonumber(d.t) or 0) >= AX.HOME_TTL then return nil end
    if d.region ~= AX.region() or d.providers ~= tostring(o.addon_providers or "") or #d.rows ~= #AX.HOME then return nil end
    local rows = {}
    for i, r in ipairs(d.rows) do
        if type(r) ~= "table" or r.id ~= AX.HOME[i].id or type(r.items) ~= "table" then return nil end
        local items = {}
        for _, it in ipairs(r.items) do if type(it) == "table" and it.poster then items[#items + 1] = U.plain(it) end end
        rows[i] = { id = r.id, title = r.title, items = items, loading = false }
    end
    return { t = tonumber(d.t), rows = rows }
end

function HV.AX.home_load(force)
    local AX = HV.AX
    local H = AX.home
    if not H and not force then H = AX.home_disk(); AX.home = H end
    if H and not force and os.time() - H.t < AX.HOME_TTL then
        -- a row that failed (service down) is asked again after two minutes, the rest stays
        local retry = false
        for _, r in ipairs(H.rows) do if r.err and os.time() - (r.t or H.t) > 120 then retry = true end end
        if not retry then return end
    end
    H = H and not force and H or { t = os.time(), rows = {} }
    AX.home = H
    AX.home_gen = (AX.home_gen or 0) + 1
    local gen = AX.home_gen
    for i, def in ipairs(AX.HOME) do
        local row = H.rows[i]
        if not row or row.err or force then
            row = { id = def.id, title = def.title, items = {}, loading = true, rank = def.rank }
            H.rows[i] = row
            AX["home_" .. def.kind](def, row, function(items, err)
                if AX.home_gen ~= gen then return end
                row.loading = false
                row.items = items or {}
                row.err, row.t = (#row.items == 0) and (err or "nothing") or nil, os.time()
                if row.err then msg.info("add screen: row '" .. row.title .. "': " .. tostring(row.err)) end
                AX.libmark_list(row.items)
                AX.home_save()
                if HV.mode == "add" and AX.stage == "home" then render() end
            end)
        end
    end
end
function HV.AX.home_rows()
    local out = {}
    local rank = {}
    for _, d in ipairs(HV.AX.HOME) do rank[d.id] = d.rank end
    for _, r in ipairs((HV.AX.home or {}).rows or {}) do
        r.rank = rank[r.id]                      -- also on rows saved by older versions
        if r.loading or #r.items > 0 then out[#out + 1] = r end
    end
    return out
end
function HV.AX.show_home()
    local AX = HV.AX
    AX.req = (AX.req or 0) + 1
    AX.nyaa = false
    AX.stage, AX.fedit, AX.hover, AX.msg = "home", false, nil, nil
    AX.hr, AX.hc = AX.hr or 1, AX.hc or 1
    AX.hoff = AX.hoff or {}
    AX.home_load(false)
    for _, r in ipairs(AX.home_rows()) do AX.libmark_list(r.items) end
    render()
end
function HV.AX.home_cur()
    local AX = HV.AX
    local rows = AX.home_rows()
    local r = rows[AX.hr or 1]
    return r and r.items[AX.hc or 1], r, rows
end
function HV.AX.hmove(dr, dc)
    local AX = HV.AX
    local rows = AX.home_rows()
    if #rows == 0 then if dr < 0 then AX.edit_query() end return end
    local r = math.max(1, math.min(#rows, AX.hr or 1))
    if dr < 0 and r == 1 then AX.edit_query(); return end
    r = math.max(1, math.min(#rows, r + dr))
    local n = #rows[r].items
    local c = math.max(1, math.min(math.max(1, n), (AX.hc or 1) + dc))
    if dc ~= 0 and c == (AX.hc or 1) and r == (AX.hr or 1) then HV.XA.bump("ax", r, dc) end    -- the end of the row
    AX.hr, AX.hc = r, c
    render()
end
-- An AniList title the map does not know yet: found on TMDB by its English, then its romaji name (type and year must fit).
function HV.AX.resolve(it, cb)
    local AX = HV.AX
    if it.id then return cb(it) end
    local qs = {}
    for _, q in ipairs({ it.name, it.romaji }) do if q and q ~= "" and q ~= "?" then qs[#qs + 1] = q end end
    local i, y = 0, tonumber(it.year)
    local function step()
        i = i + 1
        if HV.mode ~= "add" or AX.stage ~= "home" then return end
        if not qs[i] then AX.msg = "TMDB does not list “" .. it.name .. "” yet - try typing its name"; render(); return end
        PS.search(qs[i], it.year or "", nil, function(r)
            local ry = r and tonumber(tostring(r.first_air_date or r.release_date or ""):sub(1, 4)) or nil
            if r and r.media_type == it.kind and (not y or not ry or math.abs(ry - y) <= 1) then
                it.id = r.id
                AX.msg = nil
                cb(it)
            else step() end
        end, it.kind, true, { anime = true })
    end
    AX.msg = "Looking up " .. it.name .. " on TMDB…"
    render()
    step()
end
function HV.AX.home_open()
    local AX = HV.AX
    local it = AX.home_cur()
    if not it then return end
    AX.resolve(it, function(t)
        if HV.mode ~= "add" or AX.stage ~= "home" then return end
        AX.from_home = true
        AX.show_title(t)
    end)
end
-- The season tab a home card points at: AniList's part (TVDB / TMDB season) or the season that just started.
function HV.AX.want_tab(t)
    local have = {}
    for _, se in ipairs(HV.AX.slist(t)) do have[se.season] = true end
    for _, pt in ipairs(t.parts or {}) do have[pt.key] = true end
    -- a season card on its title page: that season's tab (an anime cour has its own, 1000 + season)
    local ws = t.want_season
    if ws then
        if have[1000 + ws] then return 1000 + ws end
        if have[ws] then return ws end
    end
    if t.src == "AniList" then
        if t.ms and have[1000 + t.ms] then return 1000 + t.ms end
        if t.mtvs and have[t.mtvs] then return t.mtvs end
        if t.ms and t.ms > 1 and have[t.ms] then return t.ms end
    elseif t.season and have[t.season] then return t.season end
    return 0
end

-- card size on the home rows (also kept by the artwork clean-up)
-- the card size comes from the size step; the window's width decides how many fit (about 8 on a 16:9 screen)
-- The add screen's home rows: the library's poster size, but never so tall that fewer than two rows fit above the
-- detail strip (a big home_card_pct used to leave a single row on a 4K window).
-- How much the selected add-on poster grows (1 = not at all: mpv < 0.38 can't scale a picture)
function HV.AX.home_grow()
    local g = math.max(1, math.min(1.15, tonumber(o.selected_grow) or 1))
    return (g > 1 and HV.dw_ok()) and g or 1
end
function HV.AX.home_card_size(m)
    local lfs = m.lfs
    local gap = math.floor(lfs * 0.8)
    local cw = math.floor((m.hs or m.h) * (tonumber(o.home_card_pct) or 16) / 100 * (tonumber(o.ui_scale) or 1) + 0.5)
    local tfs = lfs + 2
    local avail = m.h - m.foot_h - lfs * 0.5 - math.floor(lfs * 4.2) - (m.top_h + lfs * 3.8)   -- as render_home has it
    local _, _, la = HV.card_fonts(lfs)
    local row_extra = tfs * 1.9 + la + lfs * 0.6
    local g = HV.AX.home_grow()
    local cw_max = math.floor((avail / 2 - row_extra) / (1.5 * g))  -- posters are 2:3, with room for the selected one to grow
    if cw_max > 40 then cw = math.min(cw, cw_max) end
    local n = math.max(2, math.floor((m.w - 2 * m.mx + gap) / (cw + gap)))
    -- card_spread: the posters share the whole width, as in the library
    if o.card_spread and n > 1 then gap = math.min(math.floor(cw * 0.4), math.floor((m.w - 2 * m.mx - n * cw) / (n - 1))) end
    return cw, math.floor(cw * 1.5), gap, n
end

-- ---- Nyaa.si (EXPERIMENTAL): its RSS search, then the same file checklist / Real-Debrid flow ----
function HV.AX.nyaa_base() return (tostring(o.nyaa_url or "https://nyaa.si"):gsub("/+$", "")) end
function HV.AX.unhtml(s)
    s = tostring(s or ""):gsub("<!%[CDATA%[(.-)%]%]>", "%1")
    s = s:gsub("&#(%d+);", function(n) n = tonumber(n); return (n and n < 128) and string.char(n) or "?" end)
    s = s:gsub("&#x(%x+);", function(n) n = tonumber(n, 16); return (n and n < 128) and string.char(n) or "?" end)
    return (s:gsub("&quot;", '"'):gsub("&apos;", "'"):gsub("&lt;", "<"):gsub("&gt;", ">"):gsub("&amp;", "&"))
end
HV.AX.MONTHS = { Jan = 1, Feb = 2, Mar = 3, Apr = 4, May = 5, Jun = 6, Jul = 7, Aug = 8, Sep = 9, Oct = 10, Nov = 11, Dec = 12 }
-- "Sun, 11 Oct 2026 22:33:56 -0000" -> seconds since 1970 (UTC)
function HV.AX.rfc822(s)
    local d, mo, y, hh, mi, ss = tostring(s or ""):match("(%d+)%s+(%a+)%s+(%d+)%s+(%d+):(%d+):(%d+)")
    mo = mo and HV.AX.MONTHS[mo]
    if not mo then return nil end
    return HV.AX.civil(tonumber(y), mo, tonumber(d)) * 86400 + tonumber(hh) * 3600 + tonumber(mi) * 60 + tonumber(ss)
end
-- days since 1970-01-01 of a calendar date (Howard Hinnant), no os.time() so the local time zone never enters
function HV.AX.civil(y, mo, d)
    if mo <= 2 then y = y - 1 end
    local era = math.floor(y / 400)
    local yoe = y - era * 400
    local mp_ = (mo + 9) % 12
    local doy = math.floor((153 * mp_ + 2) / 5) + d - 1
    local doe = yoe * 365 + math.floor(yoe / 4) - math.floor(yoe / 100) + doy
    return era * 146097 + doe - 719468
end
-- "2026-10-02" -> whole days ago (nil when it is not a date)
function HV.AX.days_ago(ymd)
    local y, mo, d = tostring(ymd or ""):match("^(%d%d%d%d)%-(%d%d)%-(%d%d)")
    if not y then return nil end
    return math.floor((HV.AX.now_utc() or 0) / 86400) - HV.AX.civil(tonumber(y), tonumber(mo), tonumber(d))
end
function HV.AX.now_utc()
    local t = os.date("!*t")
    return HV.AX.rfc822(string.format("%d %s %d %d:%d:%d", t.day, ({ "Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec" })[t.month], t.year, t.hour, t.min, t.sec))
end
function HV.AX.ago(t)
    if not t then return nil end
    local d = math.max(0, (HV.AX.now_utc() or t) - t)
    local function n_(v, one, many) return v .. " " .. ((v == 1) and one or many) .. " ago" end
    if d < 3600 then return math.max(1, math.floor(d / 60)) .. " min ago" end
    if d < 86400 then return math.floor(d / 3600) .. " h ago" end
    if d < 86400 * 60 then return n_(math.floor(d / 86400), "day", "days") end
    if d < 86400 * 730 then return n_(math.floor(d / (86400 * 30)), "month", "months") end
    return n_(math.floor(d / (86400 * 365)), "year", "years")
end

function HV.AX.nyaa_parse(xml)
    local AX = HV.AX
    local out = {}
    for item in tostring(xml or ""):gmatch("<item>(.-)</item>") do
        -- the exact element: "<nyaa:category>" must not match "<nyaa:categoryId>"
        local function tag(n)
            local v = item:match("<" .. n .. ">(.-)</" .. n .. ">") or item:match("<" .. n .. "%s[^>]*>(.-)</" .. n .. ">")
            return v and (v:gsub("[\r\n]+", " "):gsub("^%s+", ""):gsub("%s+$", "")) or nil
        end
        local hash = tag("nyaa:infoHash")
        local title = AX.unhtml(tag("title"))
        if hash and hash:match("^%x+$") and #hash == 40 and title ~= "" then
            local n, u = tostring(tag("nyaa:size") or ""):match("([%d%.]+)%s*([KMGT]i?B)")
            -- a torrent of one video is named after that file; anything else after its folder
            local one = U.is_media(title)
            out[#out + 1] = {
                hash = hash:lower(), folder = (not one) and title or nil, file = one and title or nil, size_only = AX.unit(n, u),
                seeds = tonumber(tag("nyaa:seeders")),
                leech = tonumber(tag("nyaa:leechers")), dls = tonumber(tag("nyaa:downloads")),
                date = AX.rfc822(tag("pubDate")), cat = AX.unhtml(tag("nyaa:category")),
                trusted = tag("nyaa:trusted") == "Yes", remake = tag("nyaa:remake") == "Yes",
                view = tag("guid"), nyaa = true, torrent_url = AX.unhtml(tag("link") or ""):match("^https?://%S+%.torrent$"),
                name_raw = "Nyaa.si · " .. AX.unhtml(tag("nyaa:category") or ""), desc_raw = title,
            }
            out[#out].res, out[#out].rank = AX.res_of(title)
        end
    end
    return out
end

-- Nyaa's RSS gives up to 75 hits per request: ask twice (most seeded + newest) and merge. q == "" = latest uploads.
function HV.AX.nyaa_search(q)
    local AX = HV.AX
    AX.nyaa = true
    q = tostring(q or ""):gsub("^%s+", ""):gsub("%s+$", "")
    AX.nyaa_q = q
    AX.req = (AX.req or 0) + 1
    local req = AX.req
    local cat = tostring(o.nyaa_category or "1_0")
    local base = AX.nyaa_base() .. "/?page=rss&c=" .. U.url_encode_segment(cat) .. "&f=" .. ((q == "") and "2" or "0")
        .. ((q ~= "") and ("&q=" .. U.url_encode_segment(q)) or "")
    local urls = (q == "") and { base } or { base .. "&s=seeders&o=desc", base .. "&s=id&o=desc" }
    local m = { by = {}, order = {}, total = #urls, done = 0, failed = {}, fails = {}, kind = "nyaa", stage = "releases", raw = {}, latest = (q == "") }
    AX.m = m
    AX.sfilter = 0
    AX.set_list("releases", {}, nil)
    AX.raw = m.raw
    if PS.rd_on() then AX.rd_load(false, function() if AX.m == m and AX.stage == m.stage then AX.relist(false) end end) end
    AX.relist(true)
    local src = { host = AX.host(AX.nyaa_base()) }
    for _, u in ipairs(urls) do
        PS.http({ url = u, timeout = 30 }, function(code, body)
            if req ~= AX.req or HV.mode ~= "add" then return end
            m.done = m.done + 1
            if code ~= 200 then
                if not m.fails.nyaa then
                    m.fails.nyaa = true
                    m.failed[#m.failed + 1] = src.host .. ((code == 0) and " (no answer - blocked or offline? set nyaa_url to a mirror)" or (" (HTTP " .. code .. ")"))
                end
            else
                local list = AX.nyaa_parse(body)
                m.raw[#m.raw + 1] = { host = src.host, api = false, id = q, d = { count = #list } }
                -- both requests are one search: a torrent found by both is still found once (not "a pack")
                for _, it in ipairs(list) do AX.merge(m, it, src, { id = "nyaa" }) end
            end
            AX.relist(false)
        end)
    end
end

-- Tab / the chips beside the search box: Add-ons <-> Nyaa.si
function HV.AX.toggle_src(to_nyaa)
    local AX = HV.AX
    if to_nyaa == nil then to_nyaa = not AX.nyaa end
    AX.nyaa_ret = nil
    if AX.stage == "pick" then AX.cancel_pick() elseif AX.stage == "adding" or AX.stage == "ready" then AX.leave_job(false) end
    if AX.nyaa and AX.m and AX.m.kind == "nyaa" then AX.nyaa_m = AX.m end
    if (to_nyaa and AX.nyaa) or (not to_nyaa and not AX.nyaa and AX.stage == "home") then return end
    AX.q, AX.nq = AX.nq or "", AX.q or ""          -- each side keeps its own search text
    AX.qc = #AX.q
    if to_nyaa then
        AX.title = nil
        if AX.nyaa_m then AX.nyaa = true; AX.m = AX.nyaa_m; AX.stage = "releases"; AX.relist(true)
        else AX.nyaa_search(AX.q or "") end
    else
        AX.show_home()
    end
end

-- ---- Real-Debrid ----
-- Your torrents on Real-Debrid by hash, so a release you already have is reused instead of added again.
function HV.AX.rd_load(force, cb)
    local AX = HV.AX
    local L = AX.rdl
    if L and not force and os.time() - L.t < 120 then if cb then cb(L.by) end return end
    AX.rd_waiters = AX.rd_waiters or {}
    if cb then AX.rd_waiters[#AX.rd_waiters + 1] = cb end
    if AX.rd_loading then return end
    AX.rd_loading = true
    local by, page = {}, 1
    local function done(ok)
        AX.rd_loading = false
        if ok then AX.rdl = { t = os.time(), by = by } end
        local ws = AX.rd_waiters
        AX.rd_waiters = {}
        for _, w in ipairs(ws) do w(by, ok) end
    end
    local function step()
        PS.rd_req("/torrents?limit=2500&page=" .. page, nil, function(d, _, code)
            if type(d) ~= "table" or d.error or (tonumber(code) and tonumber(code) >= 300) then return done(code == 204) end       -- 204 = no torrents at all
            for _, t in ipairs(d) do
                if type(t) == "table" and t.hash then by[tostring(t.hash):lower()] = { id = t.id, status = t.status } end
            end
            if #d >= 2500 and page < 10 then page = page + 1; step() else done(true) end
        end)
    end
    step()
end
function HV.AX.on_rd(hash)
    local L = HV.AX.rdl
    return hash and L and L.by[hash] or nil
end

-- Plays Real-Debrid / add-on links: straight from the add-on screen into playback, with mpv's youtube-dl hook
-- switched off for these URLs (it would try to "extract" the link first and can fail).
HV.AX.urls_playing = {}
function HV.AX.play(items, chain)
    local AX = HV.AX
    AX.save()
    AX.unbind()
    if AX.poll then AX.poll:kill(); AX.poll = nil end
    AX.stage, AX.job = nil, nil
    HV.mode = "home"
    close_browser()
    -- the title it belongs to, for the now-playing card (the add screen's TMDB title; Nyaa has none)
    local tt = (not AX.nyaa) and AX.title or nil
    for _, it in ipairs(items) do
        AX.urls_playing[it.url] = it.title or "?"
        AX.np_meta[it.url] = tt and { name = tt.name, year = tt.year, kind = tt.kind } or nil
    end
    AX.chain = chain
    if chain then chain.cur = items[1].url end
    msg.info("add-ons: playing " .. tostring(items[1].title))
    queue_many(items, "replace")
    HV.say({ eyebrow = "STARTING", title = tostring(items[1].title), kind = "wait", key = "start" }, 3)
end
mp.add_hook("on_load", 9, function()
    local u = mp.get_property("stream-open-filename") or ""
    local t = HV.AX.urls_playing[u]
    if not t then return end
    pcall(mp.set_property, "file-local-options/ytdl", "no")
    pcall(mp.set_property, "file-local-options/force-media-title", t)
end)
-- one episode ahead: when an episode from a pack starts, the next one is turned into a link and queued after it
mp.register_event("file-loaded", function()
    local AX = HV.AX
    local c = AX.chain
    if not c then return end
    local u = mp.get_property("stream-open-filename") or ""
    if u ~= c.cur and u ~= c.pending then return end
    if c.pending and u ~= c.pending then return end         -- the current one again: the next is already queued
    c.cur, c.pending = u, nil
    local nx = c.rows[c.next]
    if not nx then AX.chain = nil; return end
    c.next = c.next + 1
    c.pending = "?"
    PS.rd_req("/unrestrict/link", { link = nx.link }, function(r)
        if AX.chain ~= c then return end
        if not (r and r.download) then c.pending = nil; return end
        AX.urls_playing[r.download] = nx.text
        AX.rel_url[r.download] = c.rel
        AX.np_meta[r.download] = AX.np_meta[c.cur]
        c.pending = r.download
        queue_many({ { url = r.download, title = nx.text } }, "append")
    end, "POST")
end)
mp.register_event("end-file", function(ev)
    if ev.reason == "error" then
        local AX = HV.AX
        -- a file that failed to open has no stream-open-filename any more: its playlist entry says what it was
        local u = mp.get_property("stream-open-filename") or ""
        for _, e in ipairs(mp.get_property_native("playlist") or {}) do
            if e.id == ev.playlist_entry_id then u = e.filename or u end
        end
        if AX.urls_playing[u] then
            msg.warn("add-ons: playback failed: " .. tostring(ev.file_error))
            local rel = AX.rel_url[u]
            if AX.t_of(u) then
                HV.say({ eyebrow = "COULDN'T PLAY", title = "The torrent stream", extra = tostring(ev.file_error), kind = "err" }, 8)
            elseif rel and rel.hash and AX.t_on() then
                AX.offer_t(rel, ev.file_error)
            else
                HV.say({ eyebrow = "COULDN'T PLAY", title = "The Real-Debrid link", extra = tostring(ev.file_error), kind = "err" }, 8)
            end
        end
    end
end)
-- Real-Debrid made a link but it does not play (its filter can also strike at this point): T streams it as a torrent
HV.AX.rel_url = {}
HV.AX.np_meta = {}
function HV.AX.offer_off()
    local AX = HV.AX
    if not AX.t_timer then return end
    AX.t_timer:kill(); AX.t_timer = nil
    mp.remove_key_binding("wb-offer-t"); mp.remove_key_binding("wb-offer-t2")
end
function HV.AX.offer_t(rel, why)
    local AX = HV.AX
    local off = AX.offer_off
    local function go()
        off()
        if HV.TS.spec and HV.TS.spec.key == "offer" then HV.TS.hide() end
        mp.osd_message("", 0)
        if not browser_active then open_browser() end
        if HV.mode ~= "add" then AX.open() end
        if HV.mode == "add" then AX.torrent(rel) end
    end
    off()
    if AX.t_auto() then
        HV.TS.show({ eyebrow = "REAL-DEBRID", title = "Link didn't play", extra = "switching to a torrent stream", pos = "top" }, 4)
        msg.info("add-ons: the Real-Debrid link did not play (" .. tostring(why) .. ") - streaming it as a torrent")
        mp.add_timeout(0.3, go)
        return
    end
    HV.say({ eyebrow = "REAL-DEBRID", title = "The link didn't play", extra = tostring(why), note = "T  stream it as a torrent", note_rgb = TOAST.accent, kind = "err", key = "offer" }, 20)
    mp.add_forced_key_binding("t", "wb-offer-t", go)
    mp.add_forced_key_binding("T", "wb-offer-t2", go)
    AX.t_timer = mp.add_timeout(20, off)
end

-- the title counts as added (results show it) and the library listing is re-read a few times, quietly, until
-- Real-Debrid's WebDAV shows the new folder (it can take a little while)
function HV.AX.mark_added()
    local AX = HV.AX
    local t = AX.title
    if t then AX.added_ids[t.kind .. ":" .. tostring(t.id)] = true end
    AX.lib_refresh()
end
function HV.AX.lib_refresh()
    local AX = HV.AX
    AX.lr_gen = (AX.lr_gen or 0) + 1
    local gen = AX.lr_gen
    for _, d in ipairs({ 4, 15, 45, 120 }) do
        mp.add_timeout(d, function()
            if gen ~= AX.lr_gen then return end
            local c = find_cached_dir(root_href)
            if c then c.stale = true; c._t = (c._t or 0) + 1 end
            fetch_listing(root_href, { silent = true, urgent = true }, function()
                HV.sig = nil
                if browser_active and HV.mode ~= "add" then render() end
            end)
        end)
    end
end

-- Real-Debrid's refusal in words; refused = its filter / a dead torrent (then the torrent itself may still work: T)
function HV.AX.rd_why(d, err, code)
    local e = (type(d) == "table" and (d.error or d.error_code)) and d or nil
    if e and (tonumber(e.error_code) == 35 or tostring(e.error or ""):find("infring", 1, true)) then
        return "Real-Debrid won't take this release - its \"infringing file\" filter blocks it", true, true
    end
    local txt = e and (tostring(e.error or ""):gsub("_", " ")) or nil
    return "Real-Debrid did not take it (" .. ((txt and txt ~= "") and txt or tostring(err or ("HTTP " .. tostring(code)))) .. ")", e ~= nil
end

-- torrent_fallback=auto: what Real-Debrid's filter refuses is streamed as a torrent straight away (the reason shows
-- for a moment first); manual leaves it to T
function HV.AX.t_auto() return tostring(o.torrent_fallback or "auto"):lower() ~= "manual" end
function HV.AX.auto_torrent(job, infr)
    local AX = HV.AX
    if not infr or not AX.t_auto() or not job or job.kind == "torrent" then return end
    if not (AX.t_on() and job.rel and job.rel.hash) then return end
    job.auto_t = true
    render()
    mp.add_timeout(1.5, function() if AX.job == job and job.err then AX.torrent(job.rel) end end)
end

function HV.AX.busy()
    local j = HV.AX.job
    return (j and not j.err and j.state ~= "ready") and true or false
end

function HV.AX.add(row)
    local AX = HV.AX
    local rel = row.rel
    if AX.busy() then return end                         -- one at a time: a second Enter can't add it twice
    AX.note = nil
    if not rel.hash then
        if rel.url then AX.rel_url[rel.url] = rel; AX.play({ { url = rel.url, title = rel.file or rel.title } }) end   -- only the add-on can play it
        return
    end
    if not PS.rd_on() then AX.msg = "Adding needs rd_api_token in the conf"; render(); return end
    if AX.stage == "packs" then AX.packs_m = AX.m end
    local job = { rel = rel, state = "checking", t0 = mp.get_time(), title = rel.title, from_stage = AX.stage,
                  from = { stage = AX.stage, list = AX.list, sel = AX.sel, top = AX.top, m = AX.m } }
    AX.job = job
    AX.stage = "adding"
    render()
    AX.rd_load(true, function(by, ok)
        if AX.job ~= job then return end
        if not ok then job.err = "Could not read your Real-Debrid torrents (to avoid adding one twice) - try again"; render(); return end
        local have = by[rel.hash]
        if have then
            job.id, job.existing = have.id, true
            msg.info("add-ons: already on Real-Debrid, reusing it")
            return AX.poll_job(job)
        end
        job.state = "adding"
        render()
        PS.rd_req("/torrents/addMagnet", { magnet = "magnet:?xt=urn:btih:" .. rel.hash }, function(d, err, code)
            if AX.job ~= job then
                if d and d.id then PS.rd_req("/torrents/delete/" .. d.id, nil, function() end, "DELETE") end   -- you left meanwhile
                return
            end
            if not (d and d.id) then
                local why, refused, infr = AX.rd_why(d, err, code)
                job.state, job.err, job.refused = "error", why, refused
                render(); AX.auto_torrent(job, infr); return
            end
            job.id = d.id
            if AX.rdl then AX.rdl.by[rel.hash] = { id = d.id, status = "magnet_conversion" } end
            AX.poll_job(job)
        end, "POST")
    end)
end

-- the file checklist (nothing is selected on Real-Debrid until you confirm it)
function HV.AX.pick(job, info)
    local AX = HV.AX
    local rel = job.rel
    local rows = {}
    for _, f in ipairs(type(info.files) == "table" and info.files or {}) do
        local p = tostring(f.path or "")
        local base = p:match("([^/]+)$") or p
        local lp = p:lower()
        local media = U.is_media(base)
        local video = media and not lp:find("sample") and not lp:find("/extras?/") and not lp:find("trailer")
        rows[#rows + 1] = { id = tostring(f.id), path = p, text = base, bytes = tonumber(f.bytes) or 0, video = video, other = not media }
    end
    -- the videos first (in order), samples / extras / other files after them
    table.sort(rows, function(a, b)
        if a.video ~= b.video then return a.video end
        return U.natural_less(a.path, b.path)
    end)
    -- ticked: the file you were looking at when you came from one episode, every main video when you picked a pack
    local want = nil
    for _, r in ipairs(rows) do if rel.file and r.text == rel.file then want = r end end
    -- the add-on's file index counts from 0; Real-Debrid numbers files from 1, rqbit from 0
    local base = (job.kind == "torrent") and 0 or 1
    if not want and rel.idx then for _, r in ipairs(rows) do if r.id == tostring(rel.idx + base) then want = r end end end
    local whole = (job.from_stage == "packs")
    for _, r in ipairs(rows) do r.on = (whole and r.video) or (not whole and r == want) or false end
    if not whole and not want then for _, r in ipairs(rows) do r.on = r.video end end
    local cur
    for i, r in ipairs(rows) do
        if not cur and r.on then cur = i end
        local el = AX.ep_label(r.text)
        r.chips = {}
        if el then r.chips[#r.chips + 1] = { el, THEME.accent } end
        if r.bytes > 0 then r.chips[#r.chips + 1] = { U.fmt_bytes(r.bytes) } end
        if not r.video then r.chips[#r.chips + 1] = { r.other and "not a video" or "sample / extra", THEME.text_dim } end
        if r == want then cur = i end
    end
    cur = cur or 1
    job.state, job.files = "pick", rows
    AX.stage, AX.list, AX.sel, AX.top = "pick", rows, cur, math.max(1, cur - 3)
    -- one video file and it is the one you picked: nothing to choose, take it straight away
    local nvid, only = 0, nil
    for _, r in ipairs(rows) do if r.video then nvid = nvid + 1; only = r end end
    if nvid == 1 and only.on then
        for _, r in ipairs(rows) do r.on = (r == only) end
        return AX.confirm_pick()
    end
    if job.kind == "torrent" then
        AX.msg = "The torrent's files  ·  Enter streams the ticked ones with rqbit (to " .. AX.t_dir() .. (o.fallback_keep and ")" or ", removed afterwards)")
    else
        AX.msg = (job.existing and "This torrent is already on your Real-Debrid, waiting for files to be chosen" or "Real-Debrid has the torrent's file list")
            .. " - nothing is downloaded until you press Enter"
    end
    render()
end
function HV.AX.pick_totals()
    local n, bytes = 0, 0
    for _, r in ipairs(HV.AX.list or {}) do if r.on then n = n + 1; bytes = bytes + (r.bytes or 0) end end
    return n, bytes
end
function HV.AX.toggle(i, all)
    local AX = HV.AX
    if AX.stage ~= "pick" then return end
    if all then
        local any_on = false
        for _, r in ipairs(AX.list) do if r.on then any_on = true end end
        for _, r in ipairs(AX.list) do r.on = (not any_on and r.video) or false end
    elseif AX.list[i] then AX.list[i].on = not AX.list[i].on end
    render()
end
function HV.AX.confirm_pick()
    local AX = HV.AX
    local job = AX.job
    if not job or job.state ~= "pick" then return end
    local ids = {}
    for _, r in ipairs(AX.list) do if r.on then ids[#ids + 1] = r.id end end
    if #ids == 0 then AX.msg = "Tick at least one file (Space)"; render(); return end
    if job.kind == "torrent" then return AX.t_rows(job, ids) end
    job.state, job.nsel = "selecting", #ids
    AX.stage, AX.msg = "adding", nil
    render()
    PS.rd_req("/torrents/selectFiles/" .. job.id, { files = table.concat(ids, ",") }, function(_, err, code)
        if AX.job ~= job then return end
        if code ~= 204 and code ~= 202 and code ~= 200 then job.err = "Real-Debrid did not accept the selection (" .. tostring(err or ("HTTP " .. code)) .. ")"; render(); return end
        AX.added = true
        AX.mark_added()
        job.state = "downloading"
        AX.poll_job(job)
    end, "POST")
end
-- leaving the checklist: nothing was selected yet, so the torrent is removed again (unless it was already yours)
function HV.AX.cancel_pick()
    local AX = HV.AX
    local job = AX.job
    if job and job.id and not job.existing then
        PS.rd_req("/torrents/delete/" .. job.id, nil, function() end, "DELETE")
        if AX.rdl and job.rel.hash then AX.rdl.by[job.rel.hash] = nil end
    end
    AX.job = nil
    if AX.poll then AX.poll:kill(); AX.poll = nil end
    local f = job and job.from
    if f then AX.stage, AX.list, AX.sel, AX.top, AX.m = f.stage, f.list, f.sel, f.top, f.m end
    AX.note = (job and job.kind == "torrent") and "Nothing streamed"
        or (job and job.existing) and "Nothing chosen - it was already on your Real-Debrid (waiting for files to be chosen) and is left as it was"
        or "Not added - nothing was left on Real-Debrid"
    AX.relist(false)
end

-- downloaded: the selected files, to start playing from any of them
function HV.AX.ready(job, info)
    local AX = HV.AX
    local links = type(info.links) == "table" and info.links or {}
    local rows = {}
    for _, f in ipairs(type(info.files) == "table" and info.files or {}) do
        if tonumber(f.selected) == 1 then
            local i = #rows + 1
            local base = tostring(f.path or ""):match("([^/]+)$") or "?"
            rows[i] = { text = base, path = tostring(f.path or ""), link = links[i], bytes = tonumber(f.bytes) }
        end
    end
    if #rows == 0 then for i, l in ipairs(links) do rows[i] = { text = "File " .. i, path = "", link = l } end end
    if #rows == 0 then job.err = "Real-Debrid shows no link"; render(); return end
    table.sort(rows, function(a, b) return U.natural_less(a.path ~= "" and a.path or a.text, b.path ~= "" and b.path or b.text) end)
    for _, r in ipairs(rows) do
        local el = AX.ep_label(r.text)
        r.chips = {}
        if el then r.chips[#r.chips + 1] = { el, THEME.accent } end
        if r.bytes and r.bytes > 1 then r.chips[#r.chips + 1] = { U.fmt_bytes(r.bytes) } end
    end
    job.state, job.rows = "ready", rows
    AX.mark_added()
    if #rows == 1 and not job.existing then return AX.start(job, 1) end
    AX.stage, AX.list, AX.sel, AX.top = "ready", rows, 1, 1
    local nvid = 0
    for _, f in ipairs(type(info.files) == "table" and info.files or {}) do
        local pth = tostring(f.path or ""):lower()
        if U.is_media(pth) and not pth:find("sample") then nvid = nvid + 1 end
    end
    AX.msg = (job.existing and "Already on your Real-Debrid - nothing was added again" or "Added to Real-Debrid")
        .. string.format("  ·  %d file%s  ·  %s", #rows, #rows == 1 and "" or "s", job.existing and "it is in your library" or "it will appear in your library")
    -- Real-Debrid can't add files to a torrent once they were chosen: say how to get the others
    if job.existing and nvid > #rows then
        AX.msg = AX.msg .. string.format("  ·  it has %d more video files: Ctrl+D deletes it, then add it again to choose them", nvid - #rows)
    end
    render()
end

-- play the picked file; the following ones are turned into links one at a time while you watch
function HV.AX.start(job, from)
    local AX = HV.AX
    local rows = job.rows
    local r = rows and rows[from]
    if job.kind == "torrent" then return AX.t_start(job, from) end
    if not r or not r.link then return end
    job.state = "unrestricting"
    AX.stage = "adding"
    render()
    PS.rd_req("/unrestrict/link", { link = r.link }, function(u, err, code)
        if AX.job ~= job then return end
        if not (u and u.download) then
            local why, refused, infr = AX.rd_why(u, err, code)
            job.err, job.refused = "Real-Debrid could not make a link for this file - " .. why, refused
            render(); AX.auto_torrent(job, infr); return
        end
        local chain = (from < #rows) and { rows = rows, next = from + 1, rel = job.rel } or nil
        AX.rel_url[u.download] = job.rel
        AX.play({ { url = u.download, title = (#rows == 1 and not job.rel.pack and job.title) or r.text } }, chain)
    end, "POST")
end

-- P on the file list: download it to disk while playing (the library's "download + play"), for a slow Real-Debrid link
function HV.AX.dlplay(i)
    local AX = HV.AX
    local job = AX.job
    local r = job and job.rows and job.rows[i]
    if job and job.kind == "torrent" then return AX.t_start(job, i) end    -- it downloads to disk anyway
    if not r or not r.link then return end
    PS.rd_req("/unrestrict/link", { link = r.link }, function(u, err, code)
        if AX.job ~= job then return end
        if not (u and u.download) then
            local why, refused, infr = AX.rd_why(u, err, code)
            job.err, job.refused = "Real-Debrid could not make a link for this file - " .. why, refused
            AX.stage = "adding"; render(); AX.auto_torrent(job, infr); return
        end
        AX.save()
        AX.unbind()
        if AX.poll then AX.poll:kill(); AX.poll = nil end
        AX.stage, AX.job = nil, nil
        HV.mode = "home"
        close_browser()
        msg.info("add-ons: download + play " .. tostring(r.text))
        MS.fb_start_forced({ href = "rd:" .. tostring(r.link), name = r.text, dirpath = "rd:", direct_url = u.download,
            size = tonumber(u.filesize) or r.bytes, next_queued = false })
    end, "POST")
end

function HV.AX.poll_job(job)
    local AX = HV.AX
    if AX.poll then AX.poll:kill() end
    local busy = false
    local function tick()
        if AX.job ~= job or busy then return end
        busy = true
        PS.rd_req("/torrents/info/" .. job.id, nil, function(info, err, code)
            busy = false
            if AX.job ~= job then return end
            local c = tonumber(code) or 0
            if type(info) ~= "table" or info.error or c >= 400 then
                local why = (type(info) == "table" and info.error) and tostring(info.error):gsub("_", " ") or tostring(err or ("HTTP " .. c))
                job.err = "Real-Debrid: " .. why
                if c == 401 or c == 403 or c == 404 then
                    if AX.poll then AX.poll:kill(); AX.poll = nil end
                    job.err = (c == 404) and "Real-Debrid: this torrent is gone (deleted on the website?)" or "Real-Debrid refused the token (rd_api_token)"
                end
                render(); return
            end
            job.err = nil
            job.status, job.progress, job.speed, job.seeds = info.status, tonumber(info.progress) or 0, tonumber(info.speed), tonumber(info.seeders)
            if info.status == "waiting_files_selection" then
                if AX.poll then AX.poll:kill(); AX.poll = nil end
                if job.state ~= "pick" then AX.pick(job, info) end
                return
            elseif info.status == "downloaded" then
                if AX.poll then AX.poll:kill(); AX.poll = nil end
                if mp.get_time() - job.t0 < 20 and not job.existing then AX.remember(job.rel.hash) end
                AX.ready(job, info)
                return
            elseif info.status == "error" or info.status == "dead" or info.status == "virus" or info.status == "magnet_error" then
                job.err = "Real-Debrid gave up on it: " .. tostring(PS.RD_STATUS[info.status] or info.status)
                job.refused = (info.status ~= "virus")
                if AX.poll then AX.poll:kill(); AX.poll = nil end
            elseif info.status == "magnet_conversion" then job.state = "converting"
            else job.state = "downloading" end
            render()
        end)
    end
    AX.poll = mp.add_periodic_timer(2, tick)
    tick()
end

-- Esc while it downloads: keep it on Real-Debrid (it shows up in the library when done); Ctrl+D also removes it
-- Leaving an unfinished add-on job: nothing is left behind that never starts. A Real-Debrid torrent whose files were
-- never chosen would wait on your account for good (it is deleted); a torrent buffering in rqbit stops downloading.
function HV.AX.abandon()
    local AX = HV.AX
    local job = AX.job
    if not job then return end
    if AX.stage == "pick" then return AX.cancel_pick() end
    if job.kind == "torrent" then
        if job.tid and job.tid ~= AX.t_of(mp.get_property("path")) then AX.t_remove(job.tid) end
    elseif HV.AX.unstarted(job) then
        PS.rd_req("/torrents/delete/" .. job.id, nil, function() end, "DELETE")
        if AX.rdl and job.rel and job.rel.hash then AX.rdl.by[job.rel.hash] = nil end
    end
end
-- added by us, but its files were never chosen (Real-Debrid keeps it in "waiting for files" for good)
function HV.AX.unstarted(job)
    return job and job.kind ~= "torrent" and job.id and not job.existing and not job.nsel and job.state ~= "ready"
end
function HV.AX.leave_job(delete, then_next)
    local AX = HV.AX
    local job = AX.job
    if not delete and HV.AX.unstarted(job) then delete = true; job.unstarted = true end
    AX.job = nil
    if AX.poll then AX.poll:kill(); AX.poll = nil end
    if delete and job and job.id then
        PS.rd_req("/torrents/delete/" .. job.id, nil, function() end, "DELETE")
        if AX.rdl and job.rel.hash then AX.rdl.by[job.rel.hash] = nil end
    end
    local f = job and job.from or { stage = "query", list = {}, sel = 1, top = 1 }
    local note
    if job and job.kind == "torrent" then
        if job.tid then AX.t_remove(job.tid) end
        note = job.tid and "Stopped - the torrent was removed again" or "Stopped"
    elseif delete and job and job.id then note = job.unstarted and "Not added - nothing was left on Real-Debrid" or "Deleted from Real-Debrid"
    elseif job and job.id then
        note = (job.state == "ready") and "Kept on Real-Debrid" or "Left on Real-Debrid - it appears in your library when done"
    end
    AX.stage, AX.list, AX.sel, AX.top, AX.m, AX.msg = f.stage, f.list, f.sel, f.top, f.m or AX.m, note
    AX.note = note
    if AX.m and AX.m.stage == AX.stage then AX.relist(false) end
    if then_next and job then
        for i, row in ipairs(AX.list) do
            if row.rel == job.rel and AX.list[i + 1] then AX.sel = i + 1; AX.add(AX.list[i + 1]); return end
        end
    end
    render()
end

-- ---- Torrent streaming (rqbit), for what Real-Debrid refuses ----
-- Real-Debrid's filename filter turns down many WEB-DL / WEBRip releases (error 35 "infringing file"). T streams such a
-- release as a torrent instead, with rqbit (github.com/ikatson/rqbit, one program, no install): it downloads in order,
-- serves the file over local HTTP while it downloads (seeking waits for the pieces) and mpv plays that link.
-- rqbit is started here when nothing answers on torrent_port and quits with mpv; an rqbit you run yourself is used as
-- it is. Files go to <fallback_dir>/torrents/<hash> and are deleted when playback moves on (fallback_keep=yes keeps them).
HV.AX.T = { ids = {}, removing = {} }   -- rqbit torrent ids added this session -> { hash }; hashes being removed
function HV.AX.t_on() return tostring(o.torrent_client or "") ~= "" end
function HV.AX.t_base() return "http://127.0.0.1:" .. math.floor(tonumber(o.torrent_port) or 3030) end
function HV.AX.t_dir() return MS.fb_dir() .. "/torrents" end

-- cb(is_rqbit, http_code)
function HV.AX.t_probe(cb)
    PS.http({ url = HV.AX.t_base() .. "/", timeout = 3 }, function(code, body)
        cb(code == 200 and tostring(body or ""):find('"rqbit"', 1, true) ~= nil, code)
    end)
end

-- rqbit answering on the port (started here when needed): cb(ok, why)
function HV.AX.t_ensure(cb)
    local AX, T = HV.AX, HV.AX.T
    T.waiters = T.waiters or {}
    T.waiters[#T.waiters + 1] = cb
    if T.starting then return end
    T.starting = true
    local function finish(ok, why)
        T.starting = false
        local ws = T.waiters
        T.waiters = {}
        for _, w in ipairs(ws) do w(ok, why) end
    end
    AX.t_probe(function(ok, code)
        if ok then
            if not T.proc then msg.info("torrents: using the rqbit already running on " .. AX.t_base()) end
            return finish(true)
        end
        if code == 401 then
            return finish(false, string.format("The rqbit on port %d asks for a password - set torrent_port to another port", math.floor(tonumber(o.torrent_port) or 3030)))
        end
        if code ~= 0 then
            return finish(false, string.format("Something else (not rqbit) answers on port %d - set torrent_port to a free one", math.floor(tonumber(o.torrent_port) or 3030)))
        end
        local args = { o.torrent_client, "-v", "error", "--http-api-listen-addr", (AX.t_base():gsub("^http://", "")) }
        for a in tostring(o.torrent_client_args or ""):gmatch("%S+") do args[#args + 1] = a end
        -- what rqbit does (trackers, DHT, peers) goes to a log next to the downloads, new each start: the place to look
        -- when a torrent never starts
        T.log = AX.t_dir() .. "/rqbit.log"
        if not utils.file_info(AX.t_dir()) then          -- the log can't be opened in a folder that isn't there yet
            local win = package.config:sub(1, 1) == "\\"
            pcall(mp.command_native, { name = "subprocess", playback_only = false, capture_stdout = true, capture_stderr = true,
                args = win and { "cmd", "/c", "mkdir", (AX.t_dir():gsub("/", "\\")) } or { "mkdir", "-p", AX.t_dir() } })
        end
        pcall(os.remove, T.log)
        for _, a in ipairs({ "--log-file", T.log, "--log-file-rust-log", "info", "server", "start", "--disable-persistence", AX.t_dir() }) do args[#args + 1] = a end
        msg.info("torrents: nothing answers on " .. AX.t_base() .. " - starting " .. table.concat(args, " "))
        T.died = nil
        -- runs until mpv quits (async commands are ended with the script); -v error keeps its output small
        T.proc = mp.command_native_async({ name = "subprocess", args = args, playback_only = false, capture_stdout = true, capture_stderr = true },
            function(success, res, err)
                T.proc = nil
                local out = tostring(res and ((res.stderr or "") .. (res.stdout or "")) or ""):gsub("\27%[[%d;]*m", "")
                local last = out:match("([^\n]*[Ee]rror[^\n]*)") or out:match("([^\n]+)\n*$")
                if res and res.error_string == "killed" then return end          -- ended with mpv
                if not success or not res or res.error_string == "init" then
                    T.died = string.format("Could not start '%s' - install rqbit (github.com/ikatson/rqbit/releases) or set torrent_client to its full path",
                        tostring(o.torrent_client))
                else
                    T.died = "rqbit stopped" .. (last and (": " .. last:sub(1, 160)) or (" (exit " .. tostring(res.status) .. ")"))
                end
                msg.warn("torrents: " .. T.died .. (err and (" / " .. tostring(err)) or ""))
                if T.starting then finish(false, T.died) end
            end)
        local tries = 0
        local function poll()
            if not T.starting then return end
            tries = tries + 1
            AX.t_probe(function(ok2)
                if not T.starting then return end
                if ok2 then msg.info("torrents: rqbit answers on " .. AX.t_base()); return finish(true) end
                if tries >= 40 then return finish(false, "rqbit did not answer within 20 s") end
                mp.add_timeout(0.5, poll)
            end)
        end
        mp.add_timeout(0.4, poll)
    end)
end

-- the magnet: the release's own trackers, then torrent_trackers
function HV.AX.t_magnet(rel)
    local tr, seen = {}, {}
    local function add(u)
        if u and u ~= "" and not seen[u] then seen[u] = true; tr[#tr + 1] = "&tr=" .. U.url_encode_segment(u) end
    end
    for _, u in ipairs(rel.trackers or {}) do add(u) end
    for u in tostring(o.torrent_trackers or ""):gmatch("%S+") do add(u) end
    return "magnet:?xt=urn:btih:" .. rel.hash .. "&dn=" .. U.url_encode_segment(tostring(rel.folder or rel.file or rel.title or "")) .. table.concat(tr)
end

-- the .torrent file: Nyaa's download link, else the magnet resolved by rqbit (asks the peers). cb(path | nil, why)
function HV.AX.t_meta(rel, cb)
    local AX = HV.AX
    local f = string.format("%s/%s.torrent", AX.t_dir(), rel.hash)
    local fi = utils.file_info(f)
    if fi and fi.size > 60 then return cb(f, nil, "the copy saved earlier") end
    local function resolve()
        local t0 = mp.get_time()
        msg.info("torrents: asking rqbit to fetch the file list from the torrent's peers (magnet)")
        PS.http({ url = AX.t_base() .. "/torrents/resolve_magnet", data = AX.t_magnet(rel), out = f, timeout = 180 }, function(code)
            local i = utils.file_info(f)
            if code == 200 and i and i.size > 60 then return cb(f, nil, "the torrent's peers") end
            local said = ""
            local rf = io.open(f, "rb")
            if rf then said = rf:read(300) or ""; rf:close() end
            pcall(os.remove, f)
            msg.warn(string.format("torrents: resolve_magnet gave HTTP %d after %d s %s", code, math.floor(mp.get_time() - t0), said:gsub("%s+", " ")))
            if code == 0 and mp.get_time() - t0 > 150 then return cb(nil, "No peer sent the torrent's file list within 3 minutes - it may be dead") end
            cb(nil, (code == 0) and "rqbit did not answer" or ("rqbit could not get the file list (HTTP " .. code .. ") " .. said:gsub("%s+", " "):sub(1, 120)))
        end)
    end
    if not rel.torrent_url then return resolve() end
    PS.http({ url = rel.torrent_url, out = f, timeout = 30 }, function(code)
        local i = utils.file_info(f)
        if code == 200 and i and i.size > 60 then return cb(f, nil, "Nyaa's .torrent file") end
        pcall(os.remove, f)
        msg.info("torrents: the .torrent download gave HTTP " .. code .. " - trying the magnet")
        resolve()
    end)
end

-- the files inside: cb(details | nil, why)
function HV.AX.t_list(f, cb)
    PS.http({ url = HV.AX.t_base() .. "/torrents?list_only=true", data_file = f, timeout = 30 }, function(code, body)
        local ok, d = pcall(utils.parse_json, body or "")
        local det = ok and type(d) == "table" and type(d.details) == "table" and d.details or nil
        if code ~= 200 or not det or type(det.files) ~= "table" then
            return cb(nil, "rqbit could not list the files (HTTP " .. code .. ") " .. tostring(body or ""):sub(1, 120))
        end
        cb(det)
    end)
end

-- T on a release (or on a release Real-Debrid refused): the file checklist, then streaming
function HV.AX.torrent(rel)
    local AX = HV.AX
    if not rel then return end
    if not rel.hash then AX.msg = "This release has no torrent hash - only the add-on can play it"; render(); return end
    if not AX.t_on() then AX.msg = "Streaming a torrent needs torrent_client (rqbit) in webdav-browser.conf"; render(); return end
    if tonumber(rel.seeds) == 0 then
        AX.msg = "This torrent has 0 seeders right now - nobody is sharing it, so it can't be streamed. Pick another release."
        render(); return
    end
    local old = AX.job
    if old and old.kind == "torrent" and not old.err then return end
    if AX.poll then AX.poll:kill(); AX.poll = nil end
    -- a Real-Debrid attempt that failed (error / dead / virus): that torrent is of no use, it goes
    if old and old.id and not old.existing and old.err then
        PS.rd_req("/torrents/delete/" .. old.id, nil, function() end, "DELETE")
        if AX.rdl and old.rel.hash then AX.rdl.by[old.rel.hash] = nil end
    end
    local from = (old and old.from) or { stage = AX.stage, list = AX.list, sel = AX.sel, top = AX.top, m = AX.m }
    local job = { kind = "torrent", rel = rel, state = "t_start", t0 = mp.get_time(), title = rel.title, from_stage = from.stage, from = from }
    AX.job = job
    AX.stage, AX.msg = "adding", nil
    render()
    AX.t_ensure(function(ok, why)
        if AX.job ~= job then return end
        if not ok then job.err = why; render(); return end
        job.state, job.t1 = "t_meta", mp.get_time()
        msg.info("torrents: " .. tostring(rel.title) .. "  (" .. rel.hash .. ")")
        AX.t_watch(job)
        render()
        AX.t_meta(rel, function(f, why2, src)
            if AX.job ~= job then return end
            if not f then job.err = why2; render(); return end
            msg.info(string.format("torrents: file list from %s after %d s", tostring(src), math.floor(mp.get_time() - job.t1)))
            job.tfile = f
            AX.t_list(f, function(det, why3)
                if AX.job ~= job then return end
                if not det then job.err = why3; render(); return end
                local files = {}
                for i, fl in ipairs(det.files) do
                    local pad = type(fl.attributes) == "table" and fl.attributes.padding == true
                    local comps = type(fl.components) == "table" and fl.components or { tostring(fl.name or ("file " .. i)) }
                    if not pad then files[#files + 1] = { id = i - 1, path = "/" .. table.concat(comps, "/"), bytes = tonumber(fl.length) or 0 } end
                end
                job.tname = det.name
                AX.pick(job, { files = files })
            end)
        end)
    end)
end

-- the ticked files, as the list to start from (nothing is downloaded yet)
function HV.AX.t_rows(job, ids)
    local AX = HV.AX
    local byid = {}
    for _, r in ipairs(job.files or {}) do byid[r.id] = r end
    local rows = {}
    for _, fid in ipairs(ids) do
        local r = byid[fid]
        if r then rows[#rows + 1] = { text = r.text, path = r.path, bytes = r.bytes, fidx = tonumber(fid) } end
    end
    table.sort(rows, function(a, b) return U.natural_less(a.path, b.path) end)
    for _, r in ipairs(rows) do
        local el = AX.ep_label(r.text)
        r.chips = {}
        if el then r.chips[#r.chips + 1] = { el, THEME.accent } end
        if r.bytes and r.bytes > 1 then r.chips[#r.chips + 1] = { U.fmt_bytes(r.bytes) } end
    end
    job.state, job.rows = "ready", rows
    if #rows == 1 then return AX.t_start(job, 1) end
    AX.stage, AX.list, AX.sel, AX.top = "ready", rows, 1, 1
    AX.msg = "Streaming the torrent with rqbit  ·  pick where to start (the following files play after it)  ·  nothing downloads before Enter"
    render()
end

-- one timer per torrent job, while it waits: the file list (seconds, DHT nodes) or the first megabytes (progress)
function HV.AX.t_watch(job)
    local AX = HV.AX
    if job.tick then return end
    local n = 0
    job.tick = mp.add_periodic_timer(1, function()
        if AX.job ~= job or job.err or (job.state ~= "t_meta" and job.state ~= "t_buffer") then
            if job.tick then job.tick:kill(); job.tick = nil end
            return
        end
        n = n + 1
        if job.state == "t_buffer" and not job.busy then
            job.busy = true
            AX.t_stat(job)
        elseif n % 2 == 1 and not job.busy then
            -- rqbit lists a magnet only once its peers sent the file list: till then the DHT size shows it is working
            job.busy = true
            PS.http({ url = AX.t_base() .. "/dht/stats", timeout = 3 }, function(code, body)
                job.busy = false
                local ok, d = pcall(utils.parse_json, body or "")
                if code == 200 and ok and type(d) == "table" then job.dht = tonumber(d.routing_table_size) end
                if code ~= 200 then job.dht = nil end
            end)
        end
        if HV.mode == "add" and AX.stage == "adding" and AX.job == job then render() end
    end)
end

-- Enter on a file (or the only file): rqbit downloads that file from its start; playback begins once
-- torrent_start_mb of it is on disk, and only then does the screen close
function HV.AX.t_start(job, from)
    local AX = HV.AX
    local r = job.rows and job.rows[from]
    if not r then return end
    job.start, job.state, job.err = from, "t_add", nil
    job.have, job.speed, job.live, job.seen, job.t_data, job.fails, job.tstate = 0, 0, 0, 0, nil, 0, nil
    job.size = (r.bytes and r.bytes > 0) and r.bytes or nil
    AX.stage, AX.msg = "adding", nil
    render()
    local out = AX.t_dir() .. "/" .. job.rel.hash:sub(1, 16)
    local url = string.format("%s/torrents?overwrite=true&only_files=%d&output_folder=%s", AX.t_base(), r.fidx, U.url_encode_segment(out))
    -- the same torrent removed a moment ago (Esc, then T again): rqbit has to finish that first
    local waited = job.waited or 0
    if AX.T.removing[job.rel.hash] and waited < 20 then
        job.waited = waited + 1
        mp.add_timeout(0.3, function() if AX.job == job and job.state == "t_add" then AX.t_start(job, from) end end)
        return
    end
    job.waited = nil
    -- a torrent rqbit already has (your own rqbit, with your own downloads) is used but never changed or deleted from here
    PS.http({ url = AX.t_base() .. "/torrents", timeout = 10 }, function(_, lbody)
        if AX.job ~= job then return end
        local had = false
        local okl, ld = pcall(utils.parse_json, lbody or "")
        for _, t in ipairs((okl and type(ld) == "table" and type(ld.torrents) == "table") and ld.torrents or {}) do
            if type(t) == "table" and tostring(t.info_hash or ""):lower() == job.rel.hash and not AX.T.ids[tonumber(t.id) or -1] then had = true end
        end
        PS.http({ url = url, data_file = job.tfile, timeout = 60 }, function(code, body)
            local ok, d = pcall(utils.parse_json, body or "")
            local id = ok and type(d) == "table" and tonumber(d.id)
            if id and not had then AX.T.ids[id] = { hash = job.rel.hash } end
            if AX.job ~= job then                -- you left meanwhile: it goes again
                if id then AX.t_remove(id) end
                return
            end
            if code ~= 200 or not id then
                msg.warn("torrents: adding gave HTTP " .. code .. " " .. tostring(body or ""):sub(1, 300))
                job.err = "rqbit did not take it (HTTP " .. code .. ") " .. tostring(body or ""):gsub("%s+", " "):sub(1, 140)
                render(); return
            end
            job.tid, job.had = id, had
            msg.info(string.format("torrents: rqbit has it as #%d%s - downloading '%s' (file %d) to %s", id, had and " (already in your rqbit)" or "",
                tostring(r.text), r.fidx, out))
            job.state, job.t2 = "t_buffer", mp.get_time()
            AX.t_watch(job)
            render()
        end)
    end)
end

-- once a second while it buffers: how much of the file is there, how fast, from how many peers
function HV.AX.t_stat(job)
    local AX = HV.AX
    PS.http({ url = string.format("%s/torrents/%d/stats/v1", AX.t_base(), job.tid), timeout = 4 }, function(code, body)
        job.busy = false
        if AX.job ~= job or job.state ~= "t_buffer" or job.err then return end
        local ok, d = pcall(utils.parse_json, body or "")
        if code ~= 200 or not ok or type(d) ~= "table" then
            job.fails = (job.fails or 0) + 1
            if job.fails >= 8 then
                job.err = "rqbit stopped answering (HTTP " .. code .. ")" .. (AX.T.died and (" - " .. AX.T.died) or "")
                render()
            end
            return
        end
        job.fails = 0
        local r = job.rows[job.start]
        local live = type(d.live) == "table" and d.live or {}
        local ps = type(live.snapshot) == "table" and type(live.snapshot.peer_stats) == "table" and live.snapshot.peer_stats or {}
        job.tstate = tostring(d.state or "")
        job.speed = (type(live.download_speed) == "table" and tonumber(live.download_speed.mbps) or 0) * 1048576
        job.live, job.seen = tonumber(ps.live) or 0, tonumber(ps.seen) or 0
        job.have = type(d.file_progress) == "table" and tonumber(d.file_progress[r.fidx + 1]) or 0
        job.size = job.size or tonumber(d.total_bytes)
        if job.tstate == "error" then
            job.err = "rqbit: " .. tostring(d.error or "the torrent stopped with an error")
            msg.warn("torrents: " .. job.err)
            render(); return
        end
        if job.have > 0 and not job.t_data then
            job.t_data = mp.get_time()
            msg.info(string.format("torrents: first data after %d s (%d peers connected, %d found)", math.floor(job.t_data - job.t2), job.live, job.seen))
        end
        local need = AX.t_need(job)
        if job.have >= need or d.finished == true then return AX.t_launch(job) end
        if job.tstate == "paused" then
            job.err = "This torrent is paused in rqbit" .. (job.had and " - resume it there (or remove it there) and press T again" or "")
            render(); return
        end
        -- your own rqbit's torrent keeps its own file selection: the stream itself makes rqbit fetch this file
        if job.had and job.tstate == "live" then return AX.t_launch(job) end
    end)
end
-- bytes of the file wanted on disk before playback starts
function HV.AX.t_need(job)
    local need = math.max(0, tonumber(o.torrent_start_mb) or 50) * 1048576
    if job.size and job.size > 0 then need = math.min(need, job.size) end
    return need
end

-- the adding screen for a torrent: the status line, the lines under it ({ text, colour }) and the bar (0..1 or nil)
function HV.AX.t_lines(j)
    local AX = HV.AX
    local now = mp.get_time()
    local where = AX.t_base():gsub("^http://", "")
    if j.state == "t_start" then return "Starting rqbit…", { { "rqbit answers on " .. where .. " once it is up" } } end
    if j.state == "t_meta" then
        local s = math.floor(now - (j.t1 or j.t0))
        local line = string.format("Getting the torrent's file list from its peers…  %d s", s)
        local sub = { { "rqbit shows a torrent on " .. where .. " only once this list has arrived" } }
        if j.dht then sub[#sub + 1] = { string.format("DHT: %d node%s known", j.dht, (j.dht == 1) and "" or "s") } end
        if s >= 20 and (j.dht or 0) == 0 then
            sub[#sub + 1] = { "rqbit reaches no DHT nodes - a firewall or VPN may be blocking it" .. (AX.T.log and ("  (log: " .. AX.T.log .. ")") or ""), THEME.warn }
        elseif s >= 45 then
            sub[#sub + 1] = { "No peer has answered yet - this torrent may have no seeders right now (Esc to pick another)", THEME.warn }
        end
        return line, sub
    end
    if j.state == "t_add" then return "Adding the torrent to rqbit…", nil end
    if j.state == "t_play" then return "Buffered - starting playback…", nil, 1 end
    -- t_buffer
    local need = AX.t_need(j)
    local have = math.min(j.have or 0, need)
    local s = math.floor(now - (j.t2 or now))
    local peers = string.format("%d peer%s connected (%d found)", j.live or 0, (j.live == 1) and "" or "s", j.seen or 0)
    local sub = {}
    local line
    if j.tstate == "initializing" then
        line = "rqbit is checking what is already on disk…"
    elseif (j.have or 0) <= 0 then
        line = string.format("Waiting for the first data…  %d s  ·  %s", s, peers)
        if s >= 30 and (j.seen or 0) == 0 then
            sub[#sub + 1] = { "This torrent has no seeders right now - nobody is sharing it (Esc to pick another release)", THEME.warn }
        elseif s >= 30 and (j.live or 0) == 0 then
            sub[#sub + 1] = { "Peers were found but none answers - they may be offline, or a firewall blocks rqbit (Esc to pick another release)", THEME.warn }
        elseif s >= 30 then
            sub[#sub + 1] = { "Connected, but nothing has arrived yet - the peers may be busy or slow", THEME.warn }
        end
    else
        line = string.format("Downloading before playback: %s of %s (%d %%)  ·  %s/s  ·  %s", U.fmt_bytes(have), U.fmt_bytes(need),
            math.floor(have / math.max(1, need) * 100), U.fmt_bytes(j.speed or 0), peers)
    end
    local whole = (j.size and j.size > 0) and string.format("  ·  %d %% of the file (%s)", math.floor((j.have or 0) / j.size * 100), U.fmt_bytes(j.size)) or ""
    table.insert(sub, 1, { string.format("Playback starts by itself at %s%s  ·  it keeps downloading while you watch", U.fmt_bytes(need), whole) })
    if (j.speed or 0) > 0 and (j.have or 0) > 0 and have < need then
        sub[1][1] = sub[1][1] .. string.format("  ·  ~%d s left", math.ceil((need - have) / j.speed))
    end
    return line, sub, (need > 0) and (have / need) or 1
end
-- the status card for a release being added / streamed: Real-Debrid's progress or rqbit's, errors with what to do
function HV.AX.job_card(j)
    local AX = HV.AX
    local tor = j.kind == "torrent"
    local sp = { owner = "ax", eyebrow = tor and "TORRENT STREAM" or "REAL-DEBRID", title = j.title or "", keys = "Esc:Back" }
    if j.err then
        sp.err, sp.line = true, j.err
        if not tor and AX.t_on() and j.rel and j.rel.hash then
            if j.auto_t then sp.sub = "Switching to a torrent stream (rqbit) - it plays as soon as enough is downloaded…"
            else sp.keys = "T:Stream it as a torrent|Esc:Back" end
        elseif tor then
            local h = AX.t_errhint(j)
            sp.sub = h[1] and h[1][1] or nil
        end
        return sp
    end
    if tor then
        local line, sub, frac = AX.t_lines(j)
        sp.line, sp.frac = line, frac
        for _, x in ipairs(sub or {}) do
            if x[2] then sp.sub, sp.sub_rgb = x[1], TOAST.warn; break end
            sp.sub = sp.sub or x[1]
        end
        return sp
    end
    if j.state == "checking" then sp.line = "Checking your Real-Debrid torrents first…"
    elseif not j.id then sp.line = "Adding the torrent to Real-Debrid…"
    elseif j.state == "converting" then sp.line = "Real-Debrid is reading the torrent's file list…"
    elseif j.state == "selecting" then sp.line = string.format("Selecting %d file%s…", j.nsel or 0, (j.nsel == 1) and "" or "s")
    elseif j.status == "downloaded" or j.state == "unrestricting" then sp.line, sp.frac = "Ready - starting playback…", 1
    else
        local bits = { PS.RD_STATUS[j.status or ""] or tostring(j.status or "queued") }
        if j.speed and j.speed > 0 then bits[#bits + 1] = U.fmt_bytes(j.speed) .. "/s" end
        if j.seeds then bits[#bits + 1] = j.seeds .. (j.seeds == 1 and " seeder" or " seeders") end
        sp.line = table.concat(bits, "  ·  ")
        sp.frac = (j.progress or 0) / 100
        sp.sub = "Not cached - Real-Debrid downloads it first, then it plays"
        -- a torrent nobody shares: say so instead of a bar that never moves
        if j.seeds == 0 and (j.progress or 0) <= 0 then
            j.zero_t = j.zero_t or mp.get_time()
            if mp.get_time() - j.zero_t > 20 then
                sp.sub, sp.sub_rgb = "This torrent has no seeders right now - Real-Debrid can't download it (Esc to pick another release)", TOAST.warn
            end
        else j.zero_t = nil end
    end
    return sp
end

-- under a torrent error: where to look
function HV.AX.t_errhint(j)
    local AX = HV.AX
    local sub = {}
    if AX.T.log then sub[#sub + 1] = { "rqbit's log: " .. AX.T.log } end
    if j.tid then sub[#sub + 1] = { string.format("rqbit's page for it: %s/web/  (torrent #%d)", AX.t_base(), j.tid) } end
    return sub
end

-- enough is there: the files after the start one are added to the download, playback starts and the screen closes
function HV.AX.t_launch(job)
    local AX = HV.AX
    job.state = "t_play"
    if job.tick then job.tick:kill(); job.tick = nil end
    local ids, items = {}, {}
    for i = job.start, #job.rows do
        local r = job.rows[i]
        ids[#ids + 1] = r.fidx
        items[#items + 1] = { url = string.format("%s/torrents/%d/stream/%d", AX.t_base(), job.tid, r.fidx), title = r.text }
    end
    if #ids > 1 and not job.had then
        PS.http({ url = string.format("%s/torrents/%d/update_only_files", AX.t_base(), job.tid), method = "POST", timeout = 10,
            headers = { "Content-Type: application/json" }, data = '{"only_files":[' .. table.concat(ids, ",") .. "]}" }, function(code, body)
            if code ~= 200 then msg.warn("torrents: could not add the following files (HTTP " .. code .. ") " .. tostring(body or ""):sub(1, 200)) end
        end)
    end
    msg.info(string.format("torrents: %s of '%s' downloaded in %d s - playing", U.fmt_bytes(job.have or 0), tostring(items[1].title), math.floor(mp.get_time() - (job.t2 or job.t0))))
    AX.play(items)
end

-- rqbit forgets the torrent (fallback_keep=yes) or deletes it with its files (only torrents added from here)
function HV.AX.t_remove(id)
    local AX = HV.AX
    local t = id and AX.T.ids[id]
    if not t then return end
    AX.T.ids[id] = nil
    AX.T.removing[t.hash] = true
    PS.http({ url = string.format("%s/torrents/%d/%s", AX.t_base(), id, o.fallback_keep and "forget" or "delete"), method = "POST", timeout = 10 },
        function() AX.T.removing[t.hash] = nil end)
end
-- every torrent of ours except the one playing
function HV.AX.t_cleanup(keep)
    local busy = HV.AX.job and HV.AX.job.kind == "torrent" and HV.AX.job.tid
    for id in pairs(HV.AX.T.ids) do if id ~= keep and id ~= busy then HV.AX.t_remove(id) end end
end
-- the rqbit id of a stream link of ours
function HV.AX.t_of(path)
    local base = HV.AX.t_base()
    if tostring(path or ""):sub(1, #base) ~= base then return nil end
    return tonumber(tostring(path):match("/torrents/(%d+)/stream/"))
end
-- playback moved to something else / stopped: the torrents go
mp.register_event("file-loaded", function()
    if not next(HV.AX.T.ids) then return end
    HV.AX.t_cleanup(HV.AX.t_of(mp.get_property("path")))
end)
mp.observe_property("idle-active", "bool", function(_, idle)
    if idle and next(HV.AX.T.ids) then HV.AX.t_cleanup(nil) end
end)
-- while a torrent stream runs short of data (under 3 s buffered, or paused to buffer): how fast it comes
mp.add_periodic_timer(2, function()
    local AX = HV.AX
    if AX.T.busy or not next(AX.T.ids) then return end
    local id = AX.t_of(MS.prop("path"))
    if not id then return end
    local cs = mp.get_property_native("demuxer-cache-state")
    local low = type(cs) == "table" and not cs.eof and (tonumber(cs["cache-duration"]) or 0) < 3
    if not (low or mp.get_property_bool("paused-for-cache")) then return end
    AX.T.busy = true
    PS.http({ url = string.format("%s/torrents/%d/stats/v1", AX.t_base(), id), timeout = 3 }, function(code, body)
        AX.T.busy = false
        local ok, d = pcall(utils.parse_json, body or "")
        if code ~= 200 or not ok or type(d) ~= "table" then return end
        local live = type(d.live) == "table" and d.live or {}
        local sp = type(live.download_speed) == "table" and tonumber(live.download_speed.mbps) or 0
        local ps = type(live.snapshot) == "table" and type(live.snapshot.peer_stats) == "table" and live.snapshot.peer_stats or {}
        local total, have = tonumber(d.total_bytes) or 0, tonumber(d.progress_bytes) or 0
        HV.say({ eyebrow = "TORRENT", title = "Buffering", kind = "wait", key = "tbuf",
            extra = string.format("%.1f MB/s  ·  %d peer%s  ·  %d %%", sp * 1.048576, tonumber(ps.live) or 0, (tonumber(ps.live) == 1) and "" or "s",
                total > 0 and math.floor(have / total * 100) or 0) }, 3.5)
    end)
end)
-- quitting: rqbit stops with mpv, so the files are deleted first (a few quick local requests)
function HV.AX.t_shutdown()
    local AX = HV.AX
    for id in pairs(AX.T.ids) do
        pcall(mp.command_native, { name = "subprocess", playback_only = false, capture_stdout = true, capture_stderr = true,
            args = { o.curl_path, "-s", "-m", "3", "-X", "POST", string.format("%s/torrents/%d/%s", AX.t_base(), id, o.fallback_keep and "forget" or "delete") } })
    end
    AX.T.ids = {}
end
-- leftovers of a session that ended abruptly: torrent folders / files older than fallback_cleanup_hours
function HV.AX.t_purge()
    if o.fallback_keep or not HV.AX.t_on() then return end
    pcall(function()
        local dir = HV.AX.t_dir()
        local max_age = (tonumber(o.fallback_cleanup_hours) or 24) * 3600
        local win = package.config:sub(1, 1) == "\\"
        for _, f in ipairs(utils.readdir(dir, "files") or {}) do
            local i = utils.file_info(dir .. "/" .. f)
            if f:match("^%x+%.torrent$") and i and os.time() - (i.mtime or os.time()) > max_age then pcall(os.remove, dir .. "/" .. f) end
        end
        for _, d in ipairs(utils.readdir(dir, "dirs") or {}) do
            local i = utils.file_info(dir .. "/" .. d)
            if d:match("^%x%x%x%x%x%x%x%x%x%x%x%x%x%x%x%x$") and i and os.time() - (i.mtime or os.time()) > max_age then
                local p = dir .. "/" .. d
                mp.command_native_async({ name = "subprocess", playback_only = false, capture_stdout = true, capture_stderr = true,
                    args = win and { "cmd", "/c", "rmdir", "/s", "/q", (p:gsub("/", "\\")) } or { "rm", "-rf", p } }, function() end)
            end
        end
    end)
end

-- Ctrl+S: what the add-ons sent for the last search, links removed, for bug reports
function HV.AX.save_answers()
    local AX = HV.AX
    local function scrub(v, k)
        if type(v) == "table" then
            local out = {}
            for kk, vv in pairs(v) do out[kk] = scrub(vv, kk) end
            return out
        end
        if type(v) == "string" and (k == "url" or k == "externalUrl" or k == "nzbUrl" or v:match("^https?://")) then
            local fi = AX.fileinfo(v)
            local h = v:match("%f[%x](" .. ("%x"):rep(40) .. ")%f[^%x]")
            local s = "<link removed>"
            if fi then s = s .. " fileinfo=" .. (safe_json({ hash = fi.hash, title = fi.title, fileIndex = fi.fileIndex, index = fi.index }) or "") end
            if h then s = s .. " hash=" .. h end
            if v:find("/playback/", 1, true) and not fi then s = s .. " (stored fileinfo)" end
            return s
        end
        return v
    end
    local data = {}
    for _, r in ipairs(AX.raw or {}) do data[#data + 1] = { host = r.host, search_api = r.api, id = r.id, answer = scrub(r.d) } end
    if #data == 0 then HV.say({ eyebrow = "ADD-ONS", title = "Nothing to save yet", extra = "open a title's releases first" }, 3); return end
    local path = PS.dir() .. "/addon_answers.json"
    local ok = pcall(atomic_write, path, safe_json(data) or "[]")
    HV.say(ok and { eyebrow = "ADD-ONS", title = "Answers saved (links removed)", extra = path } or { eyebrow = "ADD-ONS", title = "Could not save the answers", kind = "err" }, 6)
    msg.info("add-ons: answers saved to " .. path)
end

-- ---- keys ----
function HV.AX.enter(i)
    local AX = HV.AX
    if AX.fedit then AX.fedit = false; render(); return end
    if AX.stage == "home" then return AX.home_open() end
    if AX.stage == "title" and AX.tv then
        if AX.tv.zone == "row" then return AX.tv_open_card() end
        local b = AX.title_buttons(AX.tv.t)[AX.tv.btn or 1]
        if b then b.act() end
        return
    end
    if i then AX.sel = i end
    local row = AX.list[AX.sel]
    if AX.stage == "query" then AX.search()
    elseif not row then return
    elseif AX.stage == "results" then AX.show_title(row)
    elseif AX.stage == "seasons" then AX.pick_season(row)
    elseif AX.stage == "episodes" then
        AX.ep = row.episode
        AX.find_releases({ { id = string.format("%s:%d:%d", AX.title.imdb, AX.season, AX.ep), season = AX.season } }, "series", "releases")
    elseif AX.stage == "releases" or AX.stage == "packs" then AX.add(row)
    elseif AX.stage == "pick" then AX.confirm_pick()
    elseif AX.stage == "ready" and AX.job then AX.start(AX.job, AX.sel) end
end
function HV.AX.move(d)
    local AX = HV.AX
    if AX.stage == "home" then
        if math.abs(d) >= 1e5 then local _, r = AX.home_cur(); AX.hc = (d < 0) and 1 or math.max(1, r and #r.items or 1); render(); return end
        return AX.hmove((d < 0) and -1 or 1, 0)
    end
    if AX.stage == "title" then return AX.tv_zone(d) end               -- the title page: its buttons and the row under them
    if AX.stage == "query" then return end
    if d < 0 and AX.sel == 1 and (AX.stage == "results" or (AX.stage == "releases" and AX.nyaa)) then return AX.edit_query() end
    if #AX.list == 0 then return end
    AX.sel = math.max(1, math.min(#AX.list, AX.sel + d))
    render()
end
-- ---- text boxes (the search and the filter): a real cursor ----
-- AX.q / AX.qc and AX.filt / AX.fc: the text and the cursor as a byte offset (always on a character boundary)
function HV.AX.field()
    local AX = HV.AX
    if AX.fedit then return "filt", "fc" end
    if AX.stage == "query" then return "q", "qc" end
    return nil
end
function HV.AX.changed(f)
    local AX = HV.AX
    if f == "filt" then AX.refilter() else render() end
end
function HV.AX.ins(ch)
    local AX = HV.AX
    local f, c = AX.field()
    local txt = AX[f] or ""
    local pos = math.max(0, math.min(#txt, AX[c] or #txt))
    AX[f] = txt:sub(1, pos) .. ch .. txt:sub(pos + 1)
    AX[c] = pos + #ch
    AX.bs_armed = nil
    HV.XA.typed(true)
    AX.changed(f)
end
-- byte offset of the character boundary left / right of pos
function HV.AX.prev_b(txt, pos)
    pos = pos - 1
    while pos > 0 and txt:byte(pos + 1) and txt:byte(pos + 1) >= 128 and txt:byte(pos + 1) < 192 do pos = pos - 1 end
    return math.max(0, pos)
end
function HV.AX.next_b(txt, pos)
    pos = pos + 1
    while pos < #txt and txt:byte(pos + 1) >= 128 and txt:byte(pos + 1) < 192 do pos = pos + 1 end
    return math.min(#txt, pos)
end
function HV.AX.cur(d, word)
    local AX = HV.AX
    local f, c = AX.field()
    if not f then return false end
    local txt = AX[f] or ""
    local pos = math.max(0, math.min(#txt, AX[c] or #txt))
    if d == "home" then pos = 0
    elseif d == "end" then pos = #txt
    elseif word then
        if d < 0 then
            while pos > 0 and txt:sub(pos, pos):match("%s") do pos = pos - 1 end
            while pos > 0 and not txt:sub(pos, pos):match("%s") do pos = AX.prev_b(txt, pos) end
        else
            while pos < #txt and txt:sub(pos + 1, pos + 1):match("%s") do pos = pos + 1 end
            while pos < #txt and not txt:sub(pos + 1, pos + 1):match("%s") do pos = AX.next_b(txt, pos) end
        end
    elseif d < 0 then pos = AX.prev_b(txt, pos)
    else pos = AX.next_b(txt, pos) end
    AX[c] = pos
    HV.XA.typed(false)
    render()
    return true
end
function HV.AX.del_fwd()
    local AX = HV.AX
    local f, c = AX.field()
    if not f then return end
    local txt = AX[f] or ""
    local pos = math.max(0, math.min(#txt, AX[c] or #txt))
    if pos >= #txt then return end
    AX[f] = txt:sub(1, pos) .. txt:sub(AX.next_b(txt, pos) + 1)
    HV.XA.typed(false)
    AX.changed(f)
end

function HV.AX.type(ch)
    local AX = HV.AX
    -- "?" with nothing typed yet: the key sheet (a "?" inside a title still types)
    if ch == "?" and (AX.stage ~= "query" or (AX.q or "") == "") and not AX.fedit then return HV.HP.toggle() end
    if AX.field() then return AX.ins(ch) end
    if AX.stage == "home" then                -- typing on the home page starts a new search
        if ch == " " then return end
        AX.stage, AX.q, AX.qc, AX.bs_armed = "query", ch, #ch, nil
        HV.XA.typed(true)
        render()
        return
    end
    local l = ch:lower()
    if l == "e" and AX.stage == "packs" and AX.title and AX.title.imdb then AX.show_seasons()
    elseif l == "s" then AX.cycle_sort()
    elseif (l == "/" or l == "f") and (AX.stage == "packs" or AX.stage == "releases") then AX.start_filter()
    elseif l == "p" and AX.stage == "ready" then AX.dlplay(AX.sel)
    elseif l == "t" and (AX.stage == "packs" or AX.stage == "releases") then
        local row = AX.list[AX.sel]
        AX.torrent(row and row.rel)
    elseif l == "t" and AX.stage == "adding" and AX.job and AX.job.kind ~= "torrent" and AX.job.err then AX.torrent(AX.job.rel)
    elseif l == " " and AX.stage == "pick" then AX.toggle(AX.sel)
    elseif l == "a" and AX.stage == "pick" then AX.toggle(nil, true) end
end
function HV.AX.start_filter()
    local AX = HV.AX
    AX.fedit = true
    AX.fc = #(AX.filt or "")
    render()
end

-- Backspace: deletes while there is text. Holding it never leaves the screen: once the box is empty the repeats do
-- nothing; a NEW press on an empty search box first says "press again", the next one goes back.
function HV.AX.bs(ev)
    local AX = HV.AX
    local rep = (ev == "repeat")
    local f, c = AX.field()
    if f then
        local txt = AX[f] or ""
        local pos = math.max(0, math.min(#txt, AX[c] or #txt))
        if pos > 0 then
            local p0 = AX.prev_b(txt, pos)
            AX[f] = txt:sub(1, p0) .. txt:sub(pos + 1)
            AX[c] = p0
            AX.bs_armed = nil
            HV.XA.typed(false)
            AX.changed(f)
            return
        end
        if rep then return end
        if f == "filt" then AX.fedit = false; render(); return end
        if #txt > 0 then return end                       -- cursor at the start of a non-empty search: nothing to do
        local now = mp.get_time()
        if AX.bs_armed and now - AX.bs_armed < 3 then AX.bs_armed = nil; AX.back(); return end
        AX.bs_armed = now
        render()
        mp.add_timeout(3.05, function() if AX.bs_armed and mp.get_time() - AX.bs_armed >= 3 then AX.bs_armed = nil; if HV.mode == "add" then render() end end end)
        return
    end
    if rep then return end                                -- held: one step back, not five
    if AX.stage == "home" then
        local now = mp.get_time()
        if AX.bs_armed and now - AX.bs_armed < 3 then AX.bs_armed = nil; AX.close(); return end
        AX.bs_armed = now
        render()
        mp.add_timeout(3.05, function() if AX.bs_armed and mp.get_time() - AX.bs_armed >= 3 then AX.bs_armed = nil; if HV.mode == "add" then render() end end end)
        return
    end
    AX.back()
end

-- ---- mouse ----
function HV.AX.hit_at(x, y)
    for i = #HV.AX.hits, 1, -1 do
        local h = HV.AX.hits[i]
        if x >= h.x1 and x <= h.x2 and y >= h.y1 and y <= h.y2 then return h end
    end
    return nil
end
function HV.AX.on_move(val)
    local AX = HV.AX
    -- the flyout / the queue window is open: only its own buttons light up
    local P = (HV.TK.is_open() and { links = HV.TK.links }) or HV.dlc()
    if P and val then
        local bh = nil
        for _, ln in ipairs(P.links or {}) do
            if val.x >= ln.x1 and val.x <= ln.x2 and val.y >= ln.y1 and val.y <= ln.y2 and ln.hov then bh = ln.hov end
        end
        if bh ~= HV.btn_hover then HV.btn_hover = bh; HV.last_data = nil; render() end
        return
    end
    if val and HV.XS.p and HV.XS.move(val.x, val.y) then return render() end    -- a row being dragged
    local h = val and AX.hit_at(val.x, val.y)
    local hv = h and (h.row or h.id or (h.card and ("c" .. h.card[1] .. ":" .. h.card[2]))) or nil
    local lm = AX.last_mouse
    if lm and (math.abs(val.x - lm.x) > 3 or math.abs(val.y - lm.y) > 3) and HV.input ~= "mouse" then HV.mouse_input(); AX.hover = nil end
    AX.last_mouse = { x = val.x, y = val.y }
    if hv ~= AX.hover then
        AX.hover = hv
        if h and h.card and o.hover_lift and AX.stage == "home" then AX.hr, AX.hc = h.card[1], h.card[2] end
        if h and h.id and o.hover_lift and AX.stage == "title" and AX.tv then
            local n = tostring(h.id):match("^tr(%d+)$")
            if n then AX.tv.zone, AX.tv.rc = "row", tonumber(n) end
        end
        render()
    end
end
-- typing in the search box, then the mouse goes to the list: typing ends there (what you typed stays in the box)
function HV.AX.leave_typing()
    local AX = HV.AX
    if AX.stage ~= "query" then return end
    local q = (AX.q or ""):gsub("^%s+", ""):gsub("%s+$", "")
    if AX.nyaa then
        if AX.m and AX.m.kind == "nyaa" then AX.stage = "releases"; AX.relist(false) else AX.stage = "home" end
    elseif AX.results and q == AX.last_q then AX.show_results()
    else AX.stage = "home" end
end
function HV.AX.click(dbl)
    if HV.HP.open then if not dbl then HV.HP.click() end return end
    -- the second click of a double-click whose first click already changed the page does nothing more
    if dbl and U.now_s() - (HV.last_act or 0) < 0.45 then return end
    return HV.AX.guard(function() return HV.AX.click0(dbl) end)
end
-- runs a click and notes when it changed the page (HV.last_act), so the double-click that follows does nothing more
-- (also the click a row press makes on its release)
function HV.AX.guard(fn)
    local st0, req0, t0, tv0 = HV.AX.stage, HV.AX.req, HV.AX.title, HV.AX.tv
    local r = fn()
    if HV.AX.stage ~= st0 or HV.AX.req ~= req0 or HV.AX.title ~= t0 or HV.AX.tv ~= tv0 or HV.mode ~= "add" then HV.last_act = U.now_s() end
    return r
end
function HV.AX.click0(dbl)
    local AX = HV.AX
    local mx, my = U.mouse_xy()
    if not mx then return end
    HV.mouse_input()
    if HV.TS.click(mx, my) then return end
    if HV.TK.is_open() then return HV.TK.click(mx, my) end
    if HV.dlc() then return HV.dl_click(mx, my) end
    local h = AX.hit_at(mx, my)
    if not h then
        if AX.fedit then AX.fedit = false; render() end
        return
    end
    if AX.fedit and h.id ~= "filter" then AX.fedit = false end
    if AX.stage == "query" and (h.card or h.row) then AX.leave_typing() end
    if h.xs and h.xs.st and h.act and h.xs.maxs > 0 and not dbl and HV.XS.on() then
        local g, act, tv0 = h.xs, h.act, AX.tv
        HV.XS.press({ st = g.st, sx0 = g.sx, maxs = g.maxs, step = g.step, settle = g.settle,
            valid = function() return HV.mode == "add" and AX.stage == "title" and AX.tv == tv0 end,
            click = function() HV.AX.guard(act) end }, mx, my)
        return
    end
    if h.act then return h.act() end
    local g = h.card and HV.XS.on() and AX.stage == "home" and AX.xs_geo and AX.xs_geo[h.card[1]] or nil
    if g and g.st and g.maxs > 0 and not dbl then
        local ri, card = h.card[1], h.card
        HV.XS.press({ st = g.st, sx0 = g.sx, maxs = g.maxs, step = g.step,
            valid = function() return HV.mode == "add" and AX.stage == "home" end,
            click = function() HV.AX.guard(function() return AX.card_click(card, false) end) end,
            settle = function(n)
                local nitems = g.items
                AX.hoff = AX.hoff or {}
                AX.hoff[ri] = math.max(1, math.min(math.max(1, nitems - g.per + 1), n + 1))
                if AX.hr == ri then AX.hc = math.max(AX.hoff[ri], math.min(AX.hoff[ri] + g.per - 1, AX.hc or 1)) end
                render()
            end }, mx, my)
        return
    end
    if h.card then return AX.card_click(h.card, dbl) end
    return AX.click_rest(h, dbl)
end
function HV.AX.card_click(card, dbl)
    local AX = HV.AX
    local h = { card = card }
    do
        local now = U.now_s()
        local same = (AX.hr == h.card[1] and AX.hc == h.card[2])
        local again = same and AX.last_click and (now - AX.last_click) * 1000 <= (tonumber(o.double_click_ms) or 400)
        AX.hr, AX.hc = h.card[1], h.card[2]
        if o.single_click_open then
            if again then return end              -- the second click of a double-click: nothing more to do
            AX.last_click = now
            return AX.home_open()
        end
        if dbl or again then AX.last_click = nil; return AX.home_open() end
        AX.last_click = now
        render()
        return
    end
end
function HV.AX.click_rest(h, dbl)
    local AX = HV.AX
    if h.row then
        if h.box then AX.sel = h.row; return AX.toggle(h.row) end
        local now = U.now_s()
        local again = (AX.sel == h.row) and AX.last_click and (now - AX.last_click) * 1000 <= (tonumber(o.double_click_ms) or 400)
        -- single_click_open: the search results open with one click (the release and file lists keep select-then-Enter)
        if o.single_click_open and AX.stage == "results" then
            if again then return end
            AX.last_click, AX.sel = now, h.row
            return AX.enter(h.row)
        end
        if dbl or again then AX.last_click = nil; return AX.enter(h.row) end
        AX.last_click = now
        AX.sel = h.row
        render()
    end
end

function HV.AX.bind()
    local AX = HV.AX
    AX.bound = {}
    local function add(key, fn, flags)
        local name = "webdav_ax_" .. #AX.bound
        local f = fn
        if not tostring(key):match("^MBTN") and not tostring(key):match("^WHEEL") then
            f = function(...)
                HV.key_input()
                if HV.OV.key(key, ...) then return end         -- the Tracked flyout / the queue window, over this page
                return fn(...)
            end
        end
        safe_bind(name, key, f, flags or ONCE)
        AX.bound[#AX.bound + 1] = name
    end
    for i = 1, #SEARCH_CHARS_LOWER do local ch = SEARCH_CHARS_LOWER:sub(i, i); add(ch, function() AX.type(ch) end, REP) end
    for i = 1, #SEARCH_CHARS_UPPER do local ch = SEARCH_CHARS_UPPER:sub(i, i); add(ch, function() AX.type(ch) end, REP) end
    add("/", function() AX.type("/") end)
    for _, k in ipairs(U.kb("doctor")) do add(k, function() HV.DR.show() end) end
    add("SPACE", function() AX.type(" ") end, REP)
    add("any_unicode", function(e)
        if type(e) ~= "table" or (e.event ~= "down" and e.event ~= "repeat" and e.event ~= "press") then return end
        if e.key_text and e.key_text ~= "" and #e.key_text <= 8 then AX.type(e.key_text) end
    end, { repeatable = true, complex = true })
    for _, k in ipairs(KEYS.up) do add(k, function() AX.move(-1) end, REP) end
    for _, k in ipairs(KEYS.down) do add(k, function()
        if AX.fedit then AX.fedit = false; render()
        elseif AX.stage == "query" then
            local q = (AX.q or ""):gsub("^%s+", ""):gsub("%s+$", "")
            if AX.nyaa then if AX.m and AX.m.kind == "nyaa" then AX.stage = "releases"; AX.relist(false) end
            elseif AX.results and q == AX.last_q then AX.show_results()
            else AX.show_home() end
        else AX.move(1) end
    end, REP) end
    for _, k in ipairs(KEYS.left) do add(k, function()
        if AX.stage == "home" then AX.hmove(0, -1) elseif AX.stage == "title" then AX.tv_btn(-1) elseif not AX.cur(-1) then AX.season_tab(-1) end end, REP) end
    for _, k in ipairs(KEYS.right) do add(k, function()
        if AX.stage == "home" then AX.hmove(0, 1) elseif AX.stage == "title" then AX.tv_btn(1) elseif not AX.cur(1) then AX.season_tab(1) end end, REP) end
    -- Tab: Nyaa.si - for the title you are on when there is one (its title page or its releases), else the source switch
    add("TAB", function()
        if AX.stage == "pick" or AX.stage == "adding" then return end
        local t = (AX.stage == "title" and AX.tv and AX.tv.t) or ((AX.stage == "packs" or AX.stage == "releases") and not AX.nyaa and AX.title) or nil
        if t then AX.nyaa_for(t.name) else AX.toggle_src() end
    end)
    add("ctrl+LEFT", function() AX.cur(-1, true) end, REP)
    add("ctrl+RIGHT", function() AX.cur(1, true) end, REP)
    add("DEL", function() AX.del_fwd() end, REP)
    add("KP_DEL", function() AX.del_fwd() end, REP)
    for _, k in ipairs(KEYS.pgup) do add(k, function() if AX.stage == "home" then AX.hmove(-2, 0) else AX.move(-10) end end, REP) end
    for _, k in ipairs(KEYS.pgdn) do add(k, function() if AX.stage == "home" then AX.hmove(2, 0) else AX.move(10) end end, REP) end
    for _, k in ipairs(KEYS.home) do add(k, function() if not AX.cur("home") then AX.move(-1e6) end end) end
    for _, k in ipairs(KEYS.end_) do add(k, function() if not AX.cur("end") then AX.move(1e6) end end) end
    for _, k in ipairs(KEYS.enter) do add(k, function() AX.enter() end) end
    for _, k in ipairs(KEYS.bs) do
        add(k, function(e)
            local ev = type(e) == "table" and e.event or "down"
            if ev == "up" then return end
            AX.bs(ev)
        end, { repeatable = true, complex = true })
    end
    add("ESC", function() if HV.HP.open then return HV.HP.close() end; AX.back() end)
    add("?", function() HV.HP.toggle() end)
    for _, k in ipairs(U.kb("back")) do if k ~= "BS" then add(k, function() AX.back() end) end end
    add("MBTN_LEFT", function(e)
        if type(e) == "table" then
            if e.event == "down" or e.event == "press" then AX.click(false) end
            if (e.event == "up" or e.event == "press") and HV.XS.p then HV.XS.release() end
        else AX.click(false) end
    end, CLICK)
    add("MBTN_LEFT_DBL", function()
        if HV.XS.drag_t and U.now_s() - HV.XS.drag_t < 0.5 then return end       -- (the end of a drag)
        if HV.XS.p and not HV.XS.p.dragging then HV.XS.p.click = nil end        -- the double-click acts; its release does not
        AX.click(true)
    end)
    if o.experimental_mouse_ui and o.right_click_back then add("MBTN_RIGHT", function() AX.back() end) end
    add("ctrl+d", function() if AX.stage == "adding" or AX.stage == "ready" then AX.leave_job(true) end end)
    add("ctrl+n", function() if AX.stage == "adding" then AX.leave_job(true, true) end end)
    add("ctrl+s", function() AX.save_answers() end)
    add("GAMEPAD_DPAD_UP", function() HV.pad_hit(); AX.move(-1) end, REP)
    add("GAMEPAD_DPAD_DOWN", function() HV.pad_hit(); AX.move(1) end, REP)
    add("GAMEPAD_DPAD_LEFT", function() HV.pad_hit(); if AX.stage == "home" then AX.hmove(0, -1) else AX.season_tab(-1) end end, REP)
    add("GAMEPAD_DPAD_RIGHT", function() HV.pad_hit(); if AX.stage == "home" then AX.hmove(0, 1) else AX.season_tab(1) end end, REP)
    add("GAMEPAD_ACTION_DOWN", function() HV.pad_hit(); AX.enter() end)
    add("GAMEPAD_ACTION_RIGHT", function() HV.pad_hit(); AX.back() end)
    add("GAMEPAD_ACTION_UP", function()
        HV.pad_hit()
        if AX.stage == "pick" then AX.toggle(AX.sel) elseif AX.stage == "packs" then AX.type("e") end
    end)
    add("GAMEPAD_ACTION_LEFT", function() HV.pad_hit(); if AX.stage == "pick" then AX.toggle(nil, true) else AX.cycle_sort() end end)
    -- the wheel while typing: you went for the list, so typing ends (the text stays) and the list scrolls
    local function wheel(d)
        if HV.TK.is_open() then return HV.TK.move(d) end
        if HV.dlc() then return TV.dl_move(d) end
        if AX.fedit then AX.fedit = false end
        if AX.stage == "query" then AX.leave_typing() end
        AX.move(d)
    end
    add("WHEEL_UP", function() wheel(-1) end, REP)
    add("WHEEL_DOWN", function() wheel(1) end, REP)
    -- sideways: the row under the pointer on the home page (else the selected one)
    local function hwheel(d)
        if AX.stage == "title" and AX.tv_xs and AX.tv then
            local g, tv = AX.tv_xs.geo, AX.tv
            local off = (tv.roff or 1) + d
            if off < 1 or off > math.max(1, g.items - g.per + 1) then HV.XA.bump("axt", nil, d); return render() end
            return g.settle(off - 1)
        end
        if AX.stage ~= "home" then return end
        local hr = tostring(AX.hover or ""):match("^c(%d+):")
        local ri = tonumber(hr) or AX.hr or 1
        local g = AX.xs_geo and AX.xs_geo[ri]
        if not g then return end
        local off = (AX.hoff and AX.hoff[ri] or 1) + d
        if off < 1 or off > math.max(1, g.items - g.per + 1) then HV.XA.bump("ax", ri, d); return render() end
        AX.hoff[ri] = off
        if AX.hr == ri then AX.hc = math.max(off, math.min(off + g.per - 1, AX.hc or 1)) end
        render()
    end
    add("WHEEL_LEFT", function() hwheel(-1) end, REP)
    add("WHEEL_RIGHT", function() hwheel(1) end, REP)
end
function HV.AX.unbind()
    for _, name in ipairs(HV.AX.bound or {}) do mp.remove_key_binding(name) end
    HV.AX.bound = {}
end

-- ---- drawing ----
-- result posters: TMDB jpg -> bgra like the cards, shown with overlay ids 0..59 (HV.AX.image, with the title page)
function HV.AX.poster_size(m)
    local ph = math.floor(m.lfs * 5.6) - 14
    return math.floor(ph * 2 / 3), ph
end

function HV.AX.chips_ass(chips)
    local out = {}
    for _, c in ipairs(chips or {}) do
        if c[1] and c[1] ~= "" then out[#out + 1] = string.format("{\\c%s}", U.ass_color(c[2] or THEME.text_muted)) .. U.ass_escape((tostring(c[1]):gsub("[\r\n]+", " "))) end
    end
    return table.concat(out, string.format("{\\c%s}  ·  ", U.ass_color(THEME.text_dim)))
end
-- Text width for click areas: measured by libass itself on a hidden overlay (compute_bounds), cached per text;
-- a rough estimate if this mpv can't measure.
HV.AX.wcache = {}
-- text shortened (with "…") to a width measured by libass (U.fit_text only estimates, generously)
-- the same, ending in … when it had to be shortened
-- the whole title of the card under the pointer when its label had to be shortened (mouse UI): drawn over its
-- neighbours' labels, on a dark plate the width of the title. HV.tip_want: what to draw (nil: off); HV.tip_draw: drawn
function HV.tip_want(x, y, str, fs, rgb)
    if not (HV.MU_on() and HV.mouse_mode()) or HV.XS.p and HV.XS.p.dragging then return nil end
    return { x = x, y = y, s = tostring(str or ""), fs = fs, rgb = rgb }
end
function HV.tip_draw(add, t, w, m)
    if not t or t.s == "" then return end
    local tw = HV.AX.tw(t.s, t.fs, true)
    local pad = math.max(4, math.floor(t.fs * 0.45))
    local edge = math.floor((m and m.mx or 20) * 0.5)
    local maxw = w - 2 * edge - 2 * pad
    local s = t.s
    if tw > maxw then s = HV.ell(s, maxw, t.fs, true); tw = HV.AX.tw(s, t.fs, true) end
    local x = math.max(edge + pad, math.min(t.x, w - edge - pad - tw))
    local y1, y2 = t.y - math.floor(pad * 0.5), t.y + math.floor(t.fs * 1.25) + math.floor(pad * 0.5)
    add(D.ev_rect(x - pad, y1, x + tw + pad, y2, THEME.bg_panel, 96, THEME.text_dim, 35, 1, math.floor((y2 - y1) / 2)))
    add(D.ev_text(x, t.y, 7, string.format("\\b1\\fs%d\\c%s", t.fs, U.ass_color(t.rgb or "FFFFFF")), U.ass_escape(s)))
end
function HV.ell(s, max_px, fs, bold)
    s = tostring(s or "")
    if s == "" or HV.AX.tw(s, fs, bold) <= max_px then return s end
    local cut = HV.fitw(s, max_px - HV.AX.tw("…", fs, bold), fs, bold):gsub("…$", ""):gsub("[%s%p]+$", "")
    return cut .. "…"
end
function HV.fitw(s, max_px, fs, bold)
    s = tostring(s or "")
    local full = (s ~= "") and HV.AX.tw(s, fs, bold) or 0
    if s == "" or full <= max_px then return s end
    local len = U.utf8_len(s)
    -- the longest start that fits, found by halving (the shortened probes are measured for this session only)
    local lo, hi = 1, len - 1
    local n = math.max(1, math.min(len - 1, math.floor(len * max_px / math.max(1, full))))
    if HV.AX.tw(U.utf8_sub(s, n), fs, bold, true) <= max_px then lo = n else hi = n - 1 end
    while lo < hi do
        local mid = math.ceil((lo + hi) / 2)
        if HV.AX.tw(U.utf8_sub(s, mid), fs, bold, true) <= max_px then lo = mid else hi = mid - 1 end
    end
    return U.utf8_sub(s, lo)
end
-- Text widths, measured by mpv itself (libass) and remembered - also across sessions (textw.json in the cache
-- folder), so a page opens with its exact layout. A width not known yet is asked for without waiting while mpv is busy
-- or the frame has already spent its few ms on it: the guess stands in and the page is drawn again when it comes.
function HV.AX.wload()
    local AX = HV.AX
    AX.wloaded = true
    local f = io.open(PS.dir() .. "/textw.json", "rb")
    local d = f and f:read("*a")
    if f then f:close() end
    local ok, t = pcall(utils.parse_json, d or "")
    if ok and type(t) == "table" and (t.v == 1 or t.v == 2) and t.font == tostring(o.font_name) and type(t.w) == "table" then
        -- version 1 also keyed by the window width: those entries are taken over without it
        local old = t.v == 1
        for k, v in pairs(t.w) do
            if old then
                local nk = tostring(k):match("^(.*|%d+|%a+)|[^|]*$")
                if nk then AX.wcache[nk] = tonumber(v) end
            else AX.wcache[k] = tonumber(v) end
        end
        AX.wbase = AX.wbase or {}
        for k, v in pairs(type(t.b) == "table" and t.b or {}) do
            if type(v) == "table" then
                local nk = old and tostring(k):match("^(%d+|%a+)|") or k
                if nk then AX.wbase[nk] = { x0 = tonumber(v.x0), x1 = tonumber(v.x1) } end
            end
        end
        if old then AX.wdirty = true end
    end
end
function HV.AX.wsave()
    local AX = HV.AX
    if not AX.wdirty then return end
    AX.wdirty = false
    local n = 0
    for _ in pairs(AX.wcache) do n = n + 1 end
    -- too many: the widths not used this session go (it used to forget them all, and measure everything again)
    if n > 12000 then
        local keep = {}
        for k, v in pairs(AX.wcache) do if AX.wuse[k] then keep[k] = v end end
        AX.wcache = keep
    end
    local ok, js = pcall(utils.format_json, { v = 2, font = tostring(o.font_name), w = AX.wcache, b = AX.wbase or {} })
    if not ok or not js then return end
    PS.mkdir()
    local f = io.open(PS.dir() .. "/textw.json", "wb")
    if f then f:write(js); f:close() end
end
mp.add_periodic_timer(20, function() pcall(HV.AX.wsave) end)
mp.register_event("shutdown", function() pcall(HV.AX.wsave) end)
HV.AX.wtmp, HV.AX.wtn, HV.AX.wuse = {}, 0, {}
function HV.AX.keep(key, w, tmp)
    local AX = HV.AX
    if tmp then
        if AX.wtn > 6000 then AX.wtmp, AX.wtn = {}, 0 end
        AX.wtmp[key], AX.wtn = w, AX.wtn + 1
    else
        AX.wcache[key], AX.wdirty = w, true
        AX.wuse[key] = true
    end
end
function HV.AX.tw(s, fs, bold, tmp)
    local AX = HV.AX
    s = tostring(s)
    local m = HV.m
    if not AX.wloaded then AX.wload() end
    -- a width does not depend on the window (the page is laid out in the window's own pixels), only on the text, size and
    -- weight; tmp = a probe (a shortened title, a long overview, a changing count): kept for this session only
    local key = s .. "|" .. fs .. "|" .. tostring(bold)
    local c = AX.wcache[key]
    if c then AX.wuse[key] = true; return c end
    c = AX.wtmp[key]
    if c then return c end
    local est = U.utf8_len(s) * fs * (bold and 0.53 or 0.49)
    if not m or AX.no_measure then return est end
    AX.wbase = AX.wbase or {}
    local bkey = fs .. "|" .. tostring(bold)
    local base = AX.wbase[bkey]
    local function ev(txt) return D.ev_text(0, m.h / 2, 7, string.format("\\fs%d\\b%d", fs, bold and 1 or 0), txt) end
    local now = mp.get_time()
    local busy = (HV.inflight or 0) > 0 or (AX.tw_spent or 0) > 0.004 or now < (AX.tw_async_until or 0)
    if busy or not base then
        AX.tw_wait = AX.tw_wait or {}
        AX.mo2 = AX.mo2 or mp.create_osd_overlay("ass-events")
        local function ask(txt, done)
            mp.command_native_async({ name = "osd-overlay", id = AX.mo2.id, format = "ass-events", res_x = math.floor(m.w), res_y = math.floor(m.h), z = 0,
                hidden = true, compute_bounds = true, data = ev(txt) }, function(ok, r) done(ok and type(r) == "table" and r.x1 and r or nil) end)
        end
        local function want_text(b)
            if AX.tw_wait[key] then return end
            AX.tw_wait[key] = true
            ask("|" .. U.ass_escape(s) .. "|", function(r)
                AX.tw_wait[key] = nil
                if r then
                    AX.keep(key, (r.x1 - r.x0) - (b.x1 - b.x0), tmp)
                    HV.last_data = nil         -- drawn again with it; nothing that builds the rows uses widths
                    HV.kick()
                end
            end)
        end
        if base then want_text(base)
        elseif not AX.tw_wait[bkey] then
            AX.tw_wait[bkey] = true
            ask("||", function(r)
                AX.tw_wait[bkey] = nil
                if r then AX.wbase[bkey] = { x0 = r.x0, x1 = r.x1 }; AX.wdirty = true; want_text(AX.wbase[bkey]) end
            end)
        end
        return est
    end
    local tq0 = mp.get_time()
    AX.mo = AX.mo or mp.create_osd_overlay("ass-events")
    local mo = AX.mo
    mo.res_x, mo.res_y, mo.hidden, mo.compute_bounds = math.floor(m.w), math.floor(m.h), true, true
    -- measured between two markers so leading / trailing spaces count too
    mo.data = ev("|" .. U.ass_escape(s) .. "|")
    local ok, r = pcall(mo.update, mo)
    if ok and type(r) == "table" and r.x1 then
        c = (r.x1 - r.x0) - (base.x1 - base.x0)
        AX.keep(key, c, tmp)
    else
        AX.no_measure = true
        c = est
        AX.wcache[key] = c
    end
    local dt = mp.get_time() - tq0
    AX.tw_spent = (AX.tw_spent or 0) + dt
    if dt > 0.012 then AX.tw_async_until = mp.get_time() + 2 end      -- mpv is slow to answer just now: don't wait on it
    return c
end

-- the details under a release
function HV.AX.rel_chips(it)
    local AX = HV.AX
    local c = {}
    if it.cached == true then c[#c + 1] = { "✓ cached", THEME.good }
    elseif it.cached == false then c[#c + 1] = { "not cached", THEME.text_dim } end
    if AX.on_rd(it.hash) or it.inlib then c[#c + 1] = { "already on your Real-Debrid", THEME.warn } end
    c[#c + 1] = { it.label, THEME.accent }
    if it.res and it.res ~= "" then c[#c + 1] = { it.res } end
    local tg = it.tg or {}
    local q = it.quality or tg.src
    if q then c[#c + 1] = { q } end
    local enc = it.encode or tg.codec
    if enc then c[#c + 1] = { enc .. (tg.bit and (" " .. tg.bit) or "") } end
    if tg.hdr then c[#c + 1] = { tg.hdr } end
    local au = it.audio or tg.audio
    if au and #au > 0 then c[#c + 1] = { table.concat(au, " ") } end
    if it.langs and #it.langs >= 2 then c[#c + 1] = { "Dual audio (" .. table.concat(it.langs, ", ") .. ")", THEME.good }
    elseif tg.dual then c[#c + 1] = { tg.dual, THEME.good }
    elseif it.nlang and it.nlang >= 2 then c[#c + 1] = { it.nlang .. " languages", THEME.good }
    elseif it.langs and #it.langs == 1 then c[#c + 1] = { it.langs[1] } end
    if it.group then c[#c + 1] = { it.group, THEME.text_primary } end
    if it.pack and it.fsize and it.psize then c[#c + 1] = { "episode " .. U.fmt_bytes(it.fsize) .. " · whole pack " .. U.fmt_bytes(it.psize) }
    elseif it.psize then c[#c + 1] = { "whole pack " .. U.fmt_bytes(it.psize) }
    elseif it.fsize then c[#c + 1] = { U.fmt_bytes(it.fsize) }
    elseif it.size_only then c[#c + 1] = { U.fmt_bytes(it.size_only) } end
    if it.seeds and it.seeds > 0 then c[#c + 1] = { "👤 " .. it.seeds .. ((it.leech and it.leech > 0) and (" / " .. it.leech) or "") } end
    if it.nyaa then
        if it.trusted then c[#c + 1] = { "trusted", THEME.good } end
        if it.remake then c[#c + 1] = { "remake", THEME.bad } end
        if it.date then c[#c + 1] = { AX.ago(it.date) } end
        if it.dls and it.dls > 0 then c[#c + 1] = { it.dls .. " downloads", THEME.text_dim } end
        if it.cat and it.cat ~= "" then c[#c + 1] = { (it.cat:gsub("^Anime %- ", "")), THEME.text_dim } end
    end
    local srcs = {}
    for h in pairs(it.srcs or {}) do srcs[#srcs + 1] = h end
    table.sort(srcs)
    c[#c + 1] = { table.concat(srcs, ", "), THEME.text_dim }
    if not it.hash then c[#c + 1] = { "plays through the add-on (files can't be chosen)", THEME.warn } end
    return c
end

function HV.AX.crumbs()
    local AX = HV.AX
    local t = AX.title
    local st = AX.stage
    local function leave() if AX.stage == "pick" then AX.cancel_pick() elseif AX.stage == "adding" or AX.stage == "ready" then AX.leave_job(false) end end
    -- every level above the current one can be clicked
    local c = { { "Add from add-ons", (st ~= "home" or AX.nyaa) and function() leave(); AX.toggle_src(false) end or nil } }
    if AX.nyaa then
        local m = AX.m
        local searched = m and m.kind == "nyaa" and not m.latest
        c[#c + 1] = { "Nyaa.si", (searched or st ~= "releases") and function() leave(); AX.nyaa_search("") end or nil }
        if searched then
            c[#c + 1] = { "Search “" .. (AX.nyaa_q or "") .. "”", (st ~= "releases") and function() leave(); AX.stage = "releases"; AX.relist(false) end or nil }
        end
        return c
    end
    if AX.results and st ~= "query" and st ~= "home" and not (AX.from_home and st ~= "results") then
        c[#c + 1] = { "Search “" .. (AX.last_q or AX.q or "") .. "”", (st ~= "results") and function() leave(); AX.show_results() end or nil }
    end
    if t and st ~= "query" and st ~= "results" and st ~= "home" then
        local at_top = (st == "packs") or (st == "releases" and t.kind ~= "tv")
        c[#c + 1] = { t.name, (not at_top) and function()
            leave()
            if t.kind == "tv" then AX.show_packs() elseif AX.m then AX.req = (AX.req or 0) + 1; AX.stage = "releases"; AX.relist(true) end
        end or nil }
        if st == "seasons" or st == "episodes" or (st == "releases" and t.kind == "tv") then
            c[#c + 1] = { "Single episode", (st ~= "seasons") and function() AX.req = (AX.req or 0) + 1; AX.show_seasons() end or nil }
            if AX.season and (st == "episodes" or st == "releases") then
                c[#c + 1] = { "Season " .. AX.season, (st == "releases") and function() AX.show_episodes() end or nil }
            end
            if st == "releases" and AX.ep then c[#c + 1] = { string.format("Episode %d", AX.ep) } end
        end
        -- the file list / adding / play steps add no crumb: the screen itself says where you are
    end
    return c
end

-- the home rows: a title line, then posters; the highlighted card grows a ring, its details sit at the bottom
function HV.AX.render_home(add, hit, pics, m, y, bottom, focused)
    local AX = HV.AX
    local w, lfs = m.w, m.lfs
    local rows = AX.home_rows()
    local cw, ch, gap, n = AX.home_card_size(m)
    local tfs = lfs + 2
    local cfs, cdfs, la = HV.card_fonts(lfs)
    -- the selected poster grows by gy on each side: the rows keep that much air above and below it, so a grown poster
    -- never reaches the row title above, and its two label lines move down with its bottom edge
    local g = AX.home_grow()
    local gx, gy = math.floor(cw * (g - 1) / 2 + 0.5), math.floor(ch * (g - 1) / 2 + 0.5)
    local rh = math.floor(tfs * 1.9 + ch + la + lfs * 0.6) + 2 * gy  -- the poster, its title and a rating · year · type line
    local detail_h = math.floor(lfs * 4.2)
    if #rows == 0 then
        add(D.ev_text(m.mx, y + lfs, 4, string.format("\\fs%d\\c%s", lfs, U.ass_color(THEME.text_muted)), U.ass_escape("Loading what's trending and popular…")))
        return
    end
    AX.hr = math.max(1, math.min(#rows, AX.hr or 1))
    local fit = math.max(1, math.floor((bottom - detail_h - y) / rh))
    AX.htop = AX.htop or 1
    if AX.hr < AX.htop then AX.htop = AX.hr elseif AX.hr >= AX.htop + fit then AX.htop = AX.hr - fit + 1 end
    AX.htop = math.max(1, math.min(AX.htop, math.max(1, #rows - fit + 1)))
    AX.hoff = AX.hoff or {}
    AX.ly = { chev = {} }
    AX.xs_geo = {}
    for ri = AX.htop, math.min(#rows, AX.htop + fit - 1) do
        local row = rows[ri]
        local ry = y + (ri - AX.htop) * rh
        add(D.ev_text(m.mx, ry + tfs * 0.7, 4, string.format("\\fs%d\\b1\\c%s", tfs, U.ass_color(THEME.text_primary)), U.ass_escape(row.title)
            .. (row.loading and string.format("{\\b0\\c%s}   loading…", U.ass_color(THEME.text_dim)) or "")))
        local sel_c = (ri == AX.hr) and math.max(1, math.min(#row.items, AX.hc or 1)) or nil
        if sel_c then AX.hc = sel_c end
        local off = AX.hoff[ri] or 1
        if sel_c then
            if sel_c < off then off = sel_c elseif sel_c >= off + n then off = sel_c - n + 1 end
        end
        off = math.max(1, math.min(off, math.max(1, #row.items - n + 1)))
        AX.hoff[ri] = off
        local py = math.floor(ry + tfs * 1.6) + gy
        local rbx = HV.XA.rb_off("ax", ri, m)
        -- experimental_row_drag: the row glides to its place (and can be dragged); the cards either side come in as it moves
        local step = cw + gap
        local xst = HV.XS.on() and HV.XS.state("ax:" .. tostring(row.title or ri)) or nil
        local sx = xst and HV.XS.pos(xst, (off - 1) * step) or (off - 1) * step
        local xmov = xst and HV.XS.moving(xst)
        AX.xs_geo[ri] = { st = xst, step = step, per = n, items = #row.items, maxs = math.max(0, (#row.items - n) * step), sx = sx }
        local c1, c2 = off, math.min(#row.items, off + n - 1)
        if xmov then c1, c2 = math.max(1, math.floor(sx / step) + 1 - 1), math.min(#row.items, math.floor(sx / step) + n + 1) end
        for ci = c1, c2 do
            local it = row.items[ci]
            local px = math.floor(m.mx + (ci - 1) * step - sx) + rbx
            local hov = AX.hover == ("c" .. ri .. ":" .. ci)
            local sel = focused and (ri == AX.hr and ci == AX.hc)
            if HV.mouse_mode() then sel = hov end
            local ex, ey = (sel and g > 1) and gx or 0, (sel and g > 1) and gy or 0
            if (sel or hov) and HV.ring_on() then
                local pad = sel and math.max(3, math.floor(lfs * 0.18)) or 2
                -- a ring only: the OSD is drawn over the posters, a filled shape would hide the picture
                add(D.ev_rect(px - ex - pad, py - ey - pad, px + cw + ex + pad, py + ch + ey + pad, THEME.accent, 0, sel and THEME.accent or THEME.text_muted, sel and 100 or 70, pad, 10))
            end
            local f, fw, fh = AX.poster(it, cw, ch)
            -- the trending rows: a TOP 10 badge painted into the poster (an image of its own: text can't go over pictures)
            if f and row.rank and ci <= 10 and fw == cw and fh == ch then f = HV.LY.badged(f, cw, ch, ci, THEME.accent) end
            if sel and HV.LY.dim_on() then
                local rp = math.max(3, math.floor(lfs * 0.18)) + 2
                AX.ly.dim = { { 0, y, w, bottom - detail_h }, { px - ex - rp, py - ey - rp, px + cw + ex + rp, py + ch + ey + rp + la } }
            end
            -- the selected poster grows a little, as in the library (the same picture, scaled by mpv 0.38+)
            if f and ey > 0 then
                pics[#pics + 1] = { x = px - ex, y = py - ey, f = f, w = cw + 2 * ex, h = ch + 2 * ey, sw = fw, sh = fh }
            elseif f then pics[#pics + 1] = { x = px, y = py, f = f, w = cw, h = ch, sw = fw, sh = fh }
            else
                add(D.ev_rect(px, py, px + cw, py + ch, THEME.bg_panel, 100, THEME.text_dim, 40, 1, 8))
                if HV.img_loading(it.poster) then HV.shim_add(px, py, cw, ch) end
                add(D.ev_text(px + cw / 2, py + ch / 2, 5, string.format("\\fs%d\\c%s\\q0", lfs - 2, U.ass_color(THEME.text_muted)),
                    U.ass_escape(U.fit_text(it.name, cw - 10, lfs - 2))))
            end
            -- one clean title line, then ★ rating · year · Series / Movie / Anime (and ✓ when you have it), as in the library
            local cap = HV.ell(it.name, cw, cfs, true)
            local ly = py + ch + ey + math.floor(lfs * 0.45)
            add(D.ev_text(px, ly, 7, string.format("\\b1\\fs%d\\c%s", cfs, U.ass_color((sel or hov) and "FFFFFF" or THEME.text_primary)), U.ass_escape(cap)))
            if hov and cap ~= tostring(it.name or "") then HV.tip_lbl = HV.tip_want(px, ly, it.name, cfs) end
            local dl = {}
            if (it.vote or 0) > 0 and it.votes ~= 0 then dl[#dl + 1] = dp(string.format("★ %.1f", it.vote), THEME.star, 10) end
            if it.year and it.year ~= "" then dl[#dl + 1] = dp(it.year, THEME.text_muted, 8) end
            local anime = it.src == "AniList" or it.anime
            dl[#dl + 1] = dp(anime and "Anime" or (it.kind == "tv" and "Series" or "Movie"), THEME.text_muted, 9)
            if it.season then dl[#dl + 1] = dp("S" .. it.season, THEME.accent, 7) end
            if it.inlib or it.added then dl[#dl + 1] = dp("✓", THEME.good, 11) end
            if o.new_badges then
                if it.season and it.sdate and HV.XV.is_recent(it.sdate, 7) then table.insert(dl, 1, dp("NEW", THEME.accent, 12)) end
                local tke = HV.TK.on() and it.id and it.kind and HV.TK.all()[HV.TK.key(it.kind, it.id)]
                local nx = tke and HV.TK.next_short(tke)
                if nx then dl[#dl + 1] = dp((nx:gsub("^Next ", ""):gsub(" · ", " ")), THEME.good, 9.5) end
            end
            add(D.ev_text(px, ly + math.floor(cfs * 1.3) + 1, 7, string.format("\\fs%d\\c%s", cdfs, U.ass_color(THEME.text_muted)), HV.detail_ass(dl, cw, cdfs)))
            hit(px, py, px + cw, py + ch + ey + la, { card = { ri, ci } })
        end
        -- more to either side: on the selected (or hovered) row an arrow over the row's edge, a picture layer (HV.LY) so
        -- it sits over the posters and can be clicked; the other rows (and mpv < 0.38) keep the small marks in the margin
        local hov_row = tostring(AX.hover or ""):match("^c(%d+):") or tostring(AX.hover or ""):match("^chev(%d+)")
        local big = true
        local re = math.floor(m.mx + (math.min(#row.items, off + n - 1) - off + 1) * (cw + gap) - gap)
        local function chev(dir)
            local id = "chev" .. ri .. (dir > 0 and "r" or "l")
            local x1, y1, t = HV.chev_box(m, (dir > 0) and re or m.mx, py + ch / 2)
            AX.ly.chev[#AX.ly.chev + 1] = { x = x1, y = y1, w = t, h = t, dir = dir, hot = AX.hover == id }
            hit(x1, y1, x1 + t, y1 + t, { id = id, act = function()
                AX.hr = ri
                AX.hc = math.max(1, math.min(#row.items, (dir > 0) and (off + n) or (off - n)))
                AX.hoff[ri] = math.max(1, off + dir * n)
                render()
            end })
        end
        if xmov then big = nil end                       -- the arrows wait until the row is still
        if off > 1 and not xmov then
            if big then chev(-1) else add(D.ev_text(m.mx - lfs * 0.9, py + ch / 2, 5, string.format("\\fs%d\\c%s", lfs + 6, U.ass_color(THEME.text_muted)), "‹")) end
        end
        if off + n - 1 < #row.items and not xmov then
            if big then chev(1) else add(D.ev_text(w - m.mx + lfs * 0.9, py + ch / 2, 5, string.format("\\fs%d\\c%s", lfs + 6, U.ass_color(THEME.text_muted)), "›")) end
        end
    end
    if HV.tip_lbl then HV.tip_draw(add, HV.tip_lbl, w, m); HV.tip_lbl = nil end
    -- details of the highlighted title
    local it = focused and AX.home_cur() or nil
    if it then
        local dy = bottom - detail_h + lfs * 0.2
        local wrap_w = w - 2 * m.mx
        if m.glass then
            -- a floating card as wide as what it says (title line or the wrapped overview), never wider than the page
            local ov = it.overview ~= "" and it.overview or "No overview on TMDB."
            local tl = AX.tw(it.text, lfs + 2, true) + lfs * 14
            local ovw = math.min(AX.tw(ov, lfs - 3, nil, true) / 2 + lfs * 2, w - 2 * m.mx)
            local cwid = math.min(w - 2 * m.mx + lfs * 1.2, math.max(tl, ovw, w * 0.35) + lfs * 1.2)
            HV.gcard(add, m.mx - lfs * 0.6, bottom - detail_h - lfs * 0.1, m.mx - lfs * 0.6 + cwid, bottom + lfs * 0.3, m)
            wrap_w = cwid - lfs * 1.2
        else
            add(D.ev_rect(0, bottom - detail_h, w, bottom + lfs * 0.5, THEME.bg_header, 92, nil, 0, 0))
        end
        local chips = { { (it.anime or it.src == "AniList") and "Anime" or (it.kind == "tv" and "Series" or "Movie"), THEME.accent } }
        if it.season then
            local days = AX.days_ago(it.sdate)
            chips[#chips + 1] = { string.format("Season %d", it.season) .. (days and (" · started " .. ((days <= 0) and "today" or (days == 1) and "yesterday"
                or (days .. " days ago"))) or ""), THEME.good }
        end
        if it.via then chips[#chips + 1] = { it.via, THEME.text_primary } end
        if it.vote > 0 and it.votes ~= 0 then chips[#chips + 1] = { string.format("★ %.1f", it.vote) .. ((it.src == "AniList") and " on AniList" or ""), THEME.star } end
        if it.inlib then chips[#chips + 1] = { "✓ in your library", THEME.good }
        elseif it.added then chips[#chips + 1] = { "✓ added to Real-Debrid", THEME.good } end
        add(D.ev_text(m.mx, dy + lfs * 0.6, 4, string.format("\\fs%d\\b1\\c%s", lfs + 2, "FFFFFF"), U.ass_escape(U.fit_text(it.text, math.min(w * 0.55, wrap_w * 0.6), lfs + 2)))
            .. string.format("{\\b0\\fs%d}   ", lfs - 2) .. AX.chips_ass(chips))
        local ls = TV.wrap(it.overview ~= "" and it.overview or "No overview on TMDB.", wrap_w, lfs - 3, 2)
        for k, ln in ipairs(ls) do ls[k] = U.ass_escape(ln) end
        add(D.ev_text(m.mx, dy + lfs * 1.5, 7, string.format("\\fs%d\\c%s", lfs - 3, U.ass_color(THEME.text_muted)), table.concat(ls, "\\N")))
    end
end

-- ---- the add screen's title page: poster, details and what to do with it (before any release list) ----
-- Opened from a home card or a search result. "Search movie / show / anime on AIOStreams" asks your add-ons for its
-- releases (the release lists as before); "Search Nyaa.si" looks the name up there.
function HV.AX.is_anime(t)
    if not t then return false end
    if t.anime or t.src == "AniList" then return true end
    for _, g in ipairs(type(t.genre_ids) == "table" and t.genre_ids or {}) do if tonumber(g) == 16 and t.lang == "ja" then return true end end
    if t.det and t.det.anime then return true end
    return false
end
function HV.AX.kind_word(t)
    if HV.AX.is_anime(t) then return "anime" end
    return (t and t.kind == "tv") and "show" or "movie"
end
-- the add-ons by name: AIOStreams when one of yours is, else "your add-ons"
function HV.AX.addon_word()
    if tostring(o.aiostreams_password or "") ~= "" then return "AIOStreams" end
    for u in tostring(o.addon_urls or ""):gmatch("%S+") do if u:lower():find("aiostreams", 1, true) then return "AIOStreams" end end
    return "your add-ons"
end
function HV.AX.show_title(t, from_title)
    local AX = HV.AX
    local prev = from_title and AX.tv or nil
    AX.tv = { t = t, from = AX.stage, rsel = AX.sel, btn = 1, zone = "btn", rc = 1, roff = 1, prev = prev }
    if AX.stage == "results" then AX.rsel = AX.sel end
    AX.stage, AX.msg, AX.hover = "title", nil, nil
    AX.title, AX.tv_xs = nil, nil
    for k in pairs(HV.XS.st) do if k:find("^axt:") then HV.XS.st[k] = nil end end     -- (only the title being opened)
    t.want_season = nil
    render()
    if t.det or not t.id then return end
    local extra = ((t.kind == "movie") and "release_dates,recommendations" or "content_ratings,recommendations") .. ",external_ids"
    if o.title_logo then extra = extra .. ",images" end
    PS.api(string.format("/%s/%d?language=en-US&append_to_response=%s%s", t.kind, t.id, extra, o.title_logo and "&include_image_language=en,null" or ""), function(d)
        if not d then return end
        if type(d.external_ids) == "table" and (d.external_ids.imdb_id or "") ~= "" then t.imdb = d.external_ids.imdb_id end
        if type(d.images) == "table" and t.logo == nil then t.logo = HV.XV.best_logo(d.images.logos); t.logo_asked = true end
        -- a film: its add-on answers are asked for now, so "Search … on AIOStreams" opens with them already here
        if t.kind == "movie" and t.imdb and HV.AX.enabled() then
            for _, src in ipairs(HV.AX.sources()) do HV.AX.fetch(src, "movie", t.imdb, function() end, true) end
        end
        local det = { gen = {}, seasons_list = {}, recs = {} }
        for _, g in ipairs(type(d.genres) == "table" and d.genres or {}) do
            if g.name then det.gen[#det.gen + 1] = g.name end
            if tonumber(g.id) == 16 and d.original_language == "ja" then det.anime = true end
        end
        det.rt = tonumber(d.runtime) or (type(d.episode_run_time) == "table" and tonumber(d.episode_run_time[1])) or nil
        det.seasons = tonumber(d.number_of_seasons)
        det.eps = tonumber(d.number_of_episodes)
        det.status = d.status
        det.tag = d.tagline
        det.backdrop = (type(d.backdrop_path) == "string" and d.backdrop_path ~= "") and d.backdrop_path or nil
        det.release = (type(d.release_date) == "string" and d.release_date ~= "") and d.release_date or nil
        local nx = type(d.next_episode_to_air) == "table" and d.next_episode_to_air or nil
        if nx then det.next = { s = tonumber(nx.season_number), e = tonumber(nx.episode_number), date = nx.air_date } end
        local cert = ""
        local res = (t.kind == "movie") and (type(d.release_dates) == "table" and d.release_dates.results) or (type(d.content_ratings) == "table" and d.content_ratings.results) or {}
        for _, r in ipairs(res) do
            if r.iso_3166_1 == "US" then
                if t.kind == "movie" then for _, rd in ipairs(r.release_dates or {}) do if (rd.certification or "") ~= "" then cert = rd.certification break end end
                else cert = r.rating or "" end
            end
        end
        det.cert = cert
        -- the row under the hero: its seasons (a show with more than one), else more like it
        for _, se in ipairs(type(d.seasons) == "table" and d.seasons or {}) do
            local n = tonumber(se.season_number)
            if n and n > 0 then
                det.seasons_list[#det.seasons_list + 1] = { season = n, name = se.name or ("Season " .. n), count = tonumber(se.episode_count) or 0,
                    year = tostring(se.air_date or ""):sub(1, 4), poster = (type(se.poster_path) == "string" and se.poster_path ~= "") and se.poster_path or t.poster, id = t.id }
            end
        end
        local rec = type(d.recommendations) == "table" and type(d.recommendations.results) == "table" and d.recommendations.results or {}
        for _, r in ipairs(rec) do
            local kind = r.media_type or t.kind
            if (kind == "tv" or kind == "movie") and type(r.poster_path) == "string" and r.poster_path ~= "" and #det.recs < 16 then
                local yr = tostring(r.first_air_date or r.release_date or ""):sub(1, 4)
                local it = { kind = kind, id = r.id, name = r.name or r.title or "?", year = yr, poster = r.poster_path, overview = tostring(r.overview or ""),
                    vote = tonumber(r.vote_average) or 0, votes = tonumber(r.vote_count), genre_ids = r.genre_ids, lang = r.original_language }
                it.text = it.name .. (yr ~= "" and ("  (" .. yr .. ")") or "")
                det.recs[#det.recs + 1] = it
            end
        end
        if (t.overview or "") == "" then t.overview = tostring(d.overview or "") end
        t.det = det
        if HV.mode == "add" and AX.stage == "title" and AX.tv and AX.tv.t == t then render() end
    end)
end
-- what the row under the hero shows: { kind = "seasons" | "recs", items }
function HV.AX.title_row(t)
    local det = t and t.det
    if not det then return nil end
    if t.kind == "tv" and #det.seasons_list > 1 then return { kind = "seasons", title = "Seasons", items = det.seasons_list } end
    if #det.recs > 0 then return { kind = "recs", title = "More like this", items = det.recs } end
    return nil
end
function HV.AX.title_buttons(t)
    local AX = HV.AX
    local b = {}
    b[#b + 1] = { id = "find", label = "Search " .. AX.kind_word(t) .. " on " .. AX.addon_word(), primary = true, act = function() t.want_season = nil; AX.pick_title(t) end }
    -- Nyaa.si is an anime tracker: its button is on anime only (nyaa_button=always: everywhere; Tab works on any title)
    if AX.is_anime(t) or tostring(o.nyaa_button or "anime") == "always" then
        b[#b + 1] = { id = "nyaa", label = "Search Nyaa.si", act = function() AX.nyaa_for(t.name) end }
    end
    if HV.TK and t.id then
        local on = HV.TK.has(t.kind, t.id)
        b[#b + 1] = { id = "track", label = on and "✓  Tracking" or "+  Track", act = function() HV.TK.toggle_ax(t); render() end }
    end
    return b
end
-- Nyaa.si for this name (Tab on a title, the hint when the add-ons found little)
function HV.AX.nyaa_for(name)
    local AX = HV.AX
    local ret = AX.tv
    AX.nyaa_m = nil
    AX.nq = tostring(name or "")
    AX.nyaa = false
    AX.toggle_src(true)
    AX.nyaa_ret = ret          -- Esc comes back to this title page
end
-- ← → : between the buttons, or along the row under the hero
function HV.AX.tv_btn(d)
    local AX = HV.AX
    local tv = AX.tv
    if not tv then return end
    if tv.zone == "row" then
        local row = AX.title_row(tv.t)
        local n = row and #row.items or 0
        tv.rc = math.max(1, math.min(n, (tv.rc or 1) + d))
    else
        local n = #AX.title_buttons(tv.t)
        tv.btn = math.max(1, math.min(n, (tv.btn or 1) + d))
    end
    render()
end
-- ↑ ↓ : the buttons and the row under the hero
function HV.AX.tv_zone(d)
    local AX = HV.AX
    local tv = AX.tv
    if not tv then return end
    if d > 0 and tv.zone == "btn" and AX.title_row(tv.t) then tv.zone = "row"
    elseif d < 0 and tv.zone == "row" then tv.zone = "btn" end
    render()
end
-- Enter / a click on a card of that row: a season -> its releases; another title -> its title page
function HV.AX.tv_open_card(i)
    local AX = HV.AX
    local tv = AX.tv
    local row = tv and AX.title_row(tv.t)
    local it = row and row.items[i or tv.rc]
    if not it then return end
    if row.kind == "seasons" then
        tv.t.want_season = it.season
        AX.pick_title(tv.t)
        tv.t.want_season = it.season
    else AX.show_title(it, true) end
end
-- an add-screen picture of any TMDB path: kind "poster" | "backdrop" (faded to transparent): f, w, h or nil
function HV.AX.image(path, pw, ph, kind)
    local AX = HV.AX
    if not path then return nil end
    local fade = (kind == "backdrop") and HV.FADE_KEY or nil
    local st = AX.imgs[path .. (fade and "#b" or "")]
    if not st then
        -- TMDB paths name the file themselves; AniList cover URLs are long: a hash of the URL
        local h = 5381
        if path:match("^https?://") then for i = 1, #path do h = (h * 33 + path:byte(i)) % 4294967296 end end
        local base = path:match("^https?://") and string.format("axa_%08x", h) or ((fade and "axb_" or "axp_") .. path:gsub("[^%w]", ""))
        st = { state = "new", bgra = {}, cq = {}, base = base, entry = { id = 0 } }
        AX.imgs[path .. (fade and "#b" or "")] = st
    end
    if st.state == "new" and HV.dn < 12 then
        local size = HV.img_size(fade and "backdrop" or "poster", pw)
        st.jpg = PS.jpg_for(st.base, size)
        st.state = "downloading"
        HV.dn = HV.dn + 1
        PS.fetch_image(size, path, st.jpg, function(ok)
            HV.dn = HV.dn - 1
            st.state = ok and "jpg" or "error"
            PS.st_dirty = true
            if HV.mode == "add" or HV.TK.is_open() then HV.kick() end
        end)
    elseif st.state == "jpg" then
        HV.want_bgra(st, pw, ph, fade, -1)          -- before any background work
        HV.convert_pump()
    end
    local sk = HV.skey(pw, ph, fade)
    local f = HV.bgra_of(st, sk)
    -- the artwork cache may have been trimmed since: check the file once per visit, convert again if it's gone
    if f and st.checked ~= AX.visit then
        st.checked = AX.visit
        local fi = utils.file_info(f)
        if not fi or fi.size ~= pw * ph * 4 then
            st.bgra, st.cq = {}, {}
            if not (st.jpg and utils.file_info(st.jpg)) then st.state = "new" end
            return nil
        end
    end
    if f then return f, pw, ph end
    return HV.alt_bgra(st, sk)        -- mpv 0.38+: another size of it, shown scaled, until this one is ready
end
function HV.AX.poster(it, pw, ph) return HV.AX.image(it and it.poster, pw, ph, "poster") end
-- "Sat 18 Oct" for a TMDB date (and "today" / "tomorrow")
-- joins the strings of a list, skipping nils (table.concat throws on a hole)
function U.join(list, sep)
    local out = {}
    for i = 1, table.maxn(list) do if list[i] ~= nil and list[i] ~= "" then out[#out + 1] = tostring(list[i]) end end
    return table.concat(out, sep)
end
function HV.AX.nice_date(d)
    local y, mo, da = tostring(d or ""):match("^(%d+)-(%d+)-(%d+)")
    if not y then return nil end
    local t = os.time({ year = tonumber(y), month = tonumber(mo), day = tonumber(da), hour = 12 })
    local days = math.floor((t - os.time()) / 86400 + 0.5)
    if days == 0 then return "today" elseif days == 1 then return "tomorrow" end
    return os.date("%a %d %b", t) .. ((tonumber(y) ~= tonumber(os.date("%Y"))) and (" " .. y) or "")
end

-- the add screen's title page, laid out like the library's: the poster, beside it the text block centred on it, the
-- TMDB backdrop faded in on the right (experimental_backdrop), and under it a row of its seasons / more like it
function HV.AX.render_title(add, hit, pics, m, y, bottom)
    local AX = HV.AX
    local tv = AX.tv
    local t = tv and tv.t
    if not t then return end
    local w, lfs = m.w, m.lfs
    local det = t.det or {}
    local row = AX.title_row(t)
    -- the library's hero band
    local pct = math.max(0.8, math.min(1.3, (tonumber(o.hero_poster_pct) or 100) / 100))
    local band = math.floor((m.hs or m.h) * 0.31 * pct)
    local ccw, cch = AX.home_card_size(m)
    local _, _, la = HV.card_fonts(lfs)
    local row_h = row and (lfs * 2.2 + cch * AX.home_grow() + la) or 0
    band = math.max(math.floor(lfs * 9), math.min(band, bottom - y - row_h - lfs))
    local ph = band - 20
    local pw = math.floor(ph * 2 / 3)
    local x0, y0 = m.mx, math.floor(y + lfs * 0.3)
    local f, fw, fh = AX.image(t.poster, pw, ph, "poster")
    if f then pics[#pics + 1] = { x = x0, y = y0, f = f, w = pw, h = ph, sw = fw, sh = fh }
    else add(D.ev_rect(x0, y0, x0 + pw, y0 + ph, THEME.bg_panel, 100, nil, 0, 0, HV.R or 6)) end
    local tx = x0 + pw + math.floor(lfs * 1.4)
    local maxw = w - m.mx - tx
    -- the backdrop: the band's height, flush right, beside (never behind) the text
    if o.experimental_backdrop and det.backdrop and HV.conv_mode() ~= "magick" then
        local bh = band
        local bw = math.min(math.floor(bh * 16 / 9), math.floor(w * 0.5))
        local bx = w - bw
        if bx - tx > w * 0.3 then
            local bf, bfw, bfh = AX.image(det.backdrop, bw, bh, "backdrop")
            if bf then pics[#pics + 1] = { x = bx, y = y0 - 10, f = bf, w = bw, h = bh, sw = bfw, sh = bfh } end
            maxw = bx - tx - lfs
        end
    end
    -- what is shown, measured first so the block sits centred beside the poster
    local tfs, gfs = lfs + 14, lfs - 1
    local lh = math.floor(lfs * 1.45)
    HV.XV.wash(add, m, t.poster and AX.imgs[t.poster] or nil, tx - lfs * 2, y0, math.min(w - m.mx, tx + maxw + lfs * 2), y0 + ph)
    -- the title's logo stands in for its name once it is on disk (TMDB titles only: AniList ids are not TMDB's)
    local logo_f, logo_w, logo_h
    if t.src ~= "AniList" then logo_f, logo_w, logo_h = HV.XV.logo(t, math.min(maxw * 0.6, 440 * m.S), tfs * 2.3) end
    local meta = {}
    if (t.vote or 0) > 0 and t.votes ~= 0 then meta[#meta + 1] = string.format("{\\c%s}★ %.1f", U.ass_color(THEME.star), t.vote) end
    if (t.year or "") ~= "" then meta[#meta + 1] = string.format("{\\c%s}%s", U.ass_color(THEME.text_primary), t.year) end
    if t.kind == "movie" and det.rt and det.rt > 0 then
        meta[#meta + 1] = string.format("{\\c%s}%s", U.ass_color(THEME.text_muted), det.rt >= 60 and string.format("%dh %02dm", math.floor(det.rt / 60), det.rt % 60) or (det.rt .. " min"))
    end
    local mt = table.concat(meta, string.format("{\\c%s}  ·  ", U.ass_color(THEME.text_dim)))
    local chips = { { (AX.kind_word(t):gsub("^%l", string.upper)), THEME.accent } }
    if (det.cert or "") ~= "" then chips[#chips + 1] = { det.cert, THEME.text_primary } end
    if t.inlib then chips[#chips + 1] = { "✓ In your library", THEME.good } elseif t.added then chips[#chips + 1] = { "✓ Added", THEME.good } end
    local genres = (#(det.gen or {}) > 0) and table.concat(det.gen, "  ·  ", 1, math.min(4, #det.gen)) or nil
    -- the facts line: seasons and episodes, the next episode, or the release date
    local facts = {}
    if t.kind == "tv" then
        if det.seasons then facts[#facts + 1] = string.format("%d season%s", det.seasons, det.seasons == 1 and "" or "s") end
        if det.eps and det.eps > 0 then facts[#facts + 1] = string.format("%d episodes", det.eps) end
        if det.next and det.next.e then
            local nd = AX.nice_date(det.next.date)
            facts[#facts + 1] = string.format("Next: S%02dE%02d%s", det.next.s or 1, det.next.e, nd and ("  " .. nd) or "")
        end
    elseif det.release then
        local nd = AX.nice_date(det.release)
        local future = det.release > os.date("%Y-%m-%d")
        if future then facts[#facts + 1] = "Out " .. (nd or det.release) end
    elseif t.kind == "movie" and t.det then facts[#facts + 1] = "Release date TBA" end
    local bh = math.floor(lfs * 2.1)
    local syn_max = 3
    local lines = TV.wrap((t.overview or "") ~= "" and t.overview or "No overview on TMDB.", maxw, lfs, syn_max)
    local head_h = logo_f and (logo_h + math.floor(lfs * 0.4)) or math.floor(tfs * 1.25)
    local hblock = head_h + lh + (genres and lh or 0) + (((det.tag or "") ~= "") and lh or 0)
        + #lines * math.floor(lfs * 1.35) + ((#facts > 0) and lh or 0) + math.floor(lfs * 0.7) + bh
    local yy = y0 + math.max(0, math.floor((ph - hblock) / 2))
    -- ---- drawing, top to bottom ----
    if logo_f then pics[#pics + 1] = { x = tx, y = yy, f = logo_f, w = logo_w, h = logo_h }
    else add(D.ev_text(tx, yy + tfs * 0.62, 4, string.format("\\b1\\fs%d\\c%s", tfs, U.ass_color(THEME.text_primary)), U.ass_escape(HV.ell(t.name, maxw, tfs, true)))) end
    yy = yy + head_h
    add(D.ev_text(tx, yy + lh / 2, 4, string.format("\\fs%d", lfs), mt))
    local cx = tx + ((mt ~= "") and (HV.AX.tw((mt:gsub("{[^}]*}", "")), lfs) + lfs * 0.8) or 0)
    local cfs = HV.chip_fs(lfs)
    local chh = math.floor(cfs * 1.7)
    for _, c in ipairs(chips) do
        local cw = HV.AX.tw(c[1], cfs, true) + cfs * 1.1
        if cx + cw > tx + maxw then break end
        add(D.ev_rect(cx, yy + lh / 2 - chh / 2, cx + cw, yy + lh / 2 + chh / 2, "FFFFFF", 0, c[2], 75, math.max(1, math.floor(m.S + 0.5)), math.max(2, math.floor(cfs * 0.3))))
        add(D.ev_text(cx + cw / 2, yy + lh / 2, 5, string.format("\\b1\\fs%d\\c%s", cfs, U.ass_color(c[2])), U.ass_escape(c[1])))
        cx = cx + cw + lfs * 0.35
    end
    if det.status and det.status ~= "" and t.kind == "tv" and cx + HV.AX.tw(det.status, lfs - 2) < tx + maxw then
        add(D.ev_text(cx + lfs * 0.2, yy + lh / 2, 4, string.format("\\fs%d\\c%s", lfs - 2, U.ass_color(det.status == "Ended" and THEME.text_muted or THEME.good)), U.ass_escape(det.status)))
    end
    yy = yy + lh
    if genres then
        add(D.ev_text(tx, yy + lh / 2, 4, string.format("\\fs%d\\c%s", gfs, U.ass_color(THEME.text_muted)), U.ass_escape(HV.ell(genres, maxw, gfs))))
        yy = yy + lh
    end
    if (det.tag or "") ~= "" then
        add(D.ev_text(tx, yy + lh / 2, 4, string.format("\\i1\\fs%d\\c%s", lfs - 1, U.ass_color(THEME.text_muted)), U.ass_escape(HV.ell(det.tag, maxw, lfs - 1))))
        yy = yy + lh
    end
    for _, ln in ipairs(lines) do
        add(D.ev_text(tx, yy + lfs * 0.67, 4, string.format("\\fs%d\\c%s", lfs, U.ass_color(THEME.text_primary)), U.ass_escape(ln)))
        yy = yy + math.floor(lfs * 1.35)
    end
    if #facts > 0 then
        add(D.ev_text(tx, yy + lh / 2, 4, string.format("\\fs%d\\c%s", lfs - 2, U.ass_color(THEME.text_muted)), U.ass_escape(HV.ell(table.concat(facts, "  ·  "), maxw, lfs - 2))))
        yy = yy + lh
    end
    yy = yy + math.floor(lfs * 0.7)
    -- the buttons: compact pills, the first one filled
    local bx = tx
    local bfs = lfs - 1
    for i, b in ipairs(AX.title_buttons(t)) do
        local bw = math.floor(HV.AX.tw(b.label, bfs, true) + bfs * 2.4)
        if bx + bw > tx + maxw then break end
        local focus = tv.zone == "btn" and tv.btn == i
        local hot = AX.hover == ("tb" .. i) or focus
        if b.primary then
            add(string.format("{\\an7\\pos(0,0)\\bord0\\shad0\\blur%d\\1c&H000000&\\1a%s\\3a&HFF&\\p1}%s{\\p0}", math.max(4, math.floor(8 * m.S)),
                U.ass_alpha(30), D.rounded_path(bx, yy + bh * 0.12, bx + bw, yy + bh * 1.1, bh / 2)))
            add(D.ev_rect(bx, yy, bx + bw, yy + bh, "FFFFFF", hot and 100 or 88, nil, 0, 0, bh / 2))
            add(D.ev_text(bx + bw / 2, yy + bh / 2, 5, string.format("\\b1\\fs%d\\c%s", bfs, U.ass_color(THEME.bg_dim)), U.ass_escape(b.label)))
        else
            HV.gpill(add, bx, yy, bx + bw, yy + bh, m, b.id == "track" and HV.TK and HV.TK.has(t.kind, t.id) and THEME.good or nil,
                b.id == "track" and HV.TK and HV.TK.has(t.kind, t.id) and 14 or nil, hot)
            add(D.ev_text(bx + bw / 2, yy + bh / 2, 5, string.format("\\b1\\fs%d\\c%s", bfs, U.ass_color(hot and "FFFFFF" or THEME.text_primary)), U.ass_escape(b.label)))
        end
        if focus and HV.ring_on() then
            local rp = math.max(3, math.floor(4 * m.S))
            add(D.ev_rect(bx - rp, yy - rp, bx + bw + rp, yy + bh + rp, "FFFFFF", 0, THEME.accent, 100, math.max(2, math.floor(2.5 * m.S)), bh / 2 + rp))
        end
        local act = b.act
        hit(bx, yy, bx + bw, yy + bh, { id = "tb" .. i, act = function() tv.zone, tv.btn = "btn", i; act() end })
        bx = bx + bw + math.floor(lfs * 0.6)
    end
    -- the row under the hero: seasons (Enter: that season's releases) or more like this (Enter: its title page)
    if row then
        local ry = y0 + band + math.floor(lfs * 0.6)
        local tfs2 = lfs + 2
        add(D.ev_text(m.mx, ry + tfs2 * 0.7, 4, string.format("\\fs%d\\b1\\c%s", tfs2, U.ass_color(THEME.text_primary)), U.ass_escape(row.title)))
        local cw, ch, gap = AX.home_card_size(m)
        local cfs2, cdfs2 = HV.card_fonts(lfs)
        local gy_ = math.floor(ch * (AX.home_grow() - 1) / 2 + 0.5)
        local py = math.floor(ry + tfs2 * 1.6) + gy_
        if py + ch + la + gy_ > bottom then ch = math.max(lfs * 4, bottom - la - py); cw = math.floor(ch * 2 / 3) end
        local n = math.max(1, math.floor((w - 2 * m.mx + gap) / (cw + gap)))
        local sel_c = tv.zone == "row" and math.max(1, math.min(#row.items, tv.rc or 1)) or nil
        local off = tv.roff or 1
        if sel_c then if sel_c < off then off = sel_c elseif sel_c >= off + n then off = sel_c - n + 1 end end
        off = math.max(1, math.min(off, math.max(1, #row.items - n + 1)))
        tv.roff = off
        -- experimental_row_drag: as on the home rows (glides, can be dragged)
        local step = cw + gap
        local xst = HV.XS.on() and HV.XS.state("axt:" .. tostring(row.kind) .. ":" .. tostring(tv.t and tv.t.id)) or nil
        local sx = xst and HV.XS.pos(xst, (off - 1) * step) or (off - 1) * step
        local xmov = xst and HV.XS.moving(xst)
        local rbx = HV.XA.rb_off("axt", nil, m)
        local geo = { st = xst, step = step, per = n, items = #row.items, maxs = math.max(0, (#row.items - n) * step), sx = sx,
            settle = function(k)
                tv.roff = math.max(1, math.min(math.max(1, #row.items - n + 1), k + 1))
                if tv.zone == "row" then tv.rc = math.max(tv.roff, math.min(tv.roff + n - 1, tv.rc or 1)) end
                render()
            end }
        AX.tv_xs = { geo = geo }
        local c1, c2 = off, math.min(#row.items, off + n - 1)
        if xmov then c1, c2 = math.max(1, math.floor(sx / step)), math.min(#row.items, math.floor(sx / step) + n + 1) end
        for ci = c1, c2 do
            local it = row.items[ci]
            local px = math.floor(m.mx + (ci - 1) * step - sx) + rbx
            local hov = AX.hover == ("tr" .. ci)
            local sel = sel_c == ci
            if HV.mouse_mode() then sel = hov end
            -- the selected card grows a little (as everywhere); the outline only with focus_ring
            local g = AX.home_grow()
            local ex, ey = sel and math.floor(cw * (g - 1) / 2 + 0.5) or 0, sel and math.floor(ch * (g - 1) / 2 + 0.5) or 0
            if (sel or hov) and (HV.ring_on() or g <= 1) then
                local pad = sel and math.max(3, math.floor(lfs * 0.18)) or 2
                add(D.ev_rect(px - ex - pad, py - ey - pad, px + cw + ex + pad, py + ch + ey + pad, THEME.accent, 0, sel and THEME.accent or THEME.text_muted, sel and 100 or 70, pad, 10))
            end
            local pf, pfw, pfh = AX.image(it.poster, cw, ch, "poster")
            if pf and ey > 0 then pics[#pics + 1] = { x = px - ex, y = py - ey, f = pf, w = cw + 2 * ex, h = ch + 2 * ey, sw = pfw, sh = pfh }
            elseif pf then pics[#pics + 1] = { x = px, y = py, f = pf, w = cw, h = ch, sw = pfw, sh = pfh }
            else
                add(D.ev_rect(px, py, px + cw, py + ch, THEME.bg_panel, 100, THEME.text_dim, 40, 1, 8))
                if HV.img_loading(it.poster) then HV.shim_add(px, py, cw, ch) end
            end
            local name = it.name
            local sub = (row.kind == "seasons") and U.join({ (it.year or "") ~= "" and it.year or nil, (it.count or 0) > 0 and (it.count .. " episodes") or nil }, "  ·  ")
                or U.join({ (it.vote or 0) > 0 and string.format("★ %.1f", it.vote) or nil, (it.year or "") ~= "" and it.year or nil, it.kind == "tv" and "Series" or "Movie" }, "  ·  ")
            local ly = py + ch + ey + math.floor(lfs * 0.45)
            local cap2 = HV.ell(name, cw, cfs2, true)
            add(D.ev_text(px, ly, 7, string.format("\\b1\\fs%d\\c%s", cfs2, U.ass_color(sel and THEME.accent or (hov and "FFFFFF" or THEME.text_primary))), U.ass_escape(cap2)))
            if hov and cap2 ~= tostring(name or "") then HV.tip_lbl = HV.tip_want(px, ly, name, cfs2, sel and THEME.accent) end
            add(D.ev_text(px, ly + math.floor(cfs2 * 1.3) + 1, 7, string.format("\\fs%d\\c%s", cdfs2, U.ass_color(THEME.text_muted)), U.ass_escape(HV.ell(sub, cw, cdfs2))))
            local cidx = ci
            hit(px, py, px + cw, py + ch + la, { id = "tr" .. ci, xs = geo, act = function() tv.zone, tv.rc = "row", cidx; AX.tv_open_card(cidx) end })
        end
        -- more to either side: the round arrow buttons, as on the home rows
        AX.ly = AX.ly or { chev = {} }
        AX.ly.chev = AX.ly.chev or {}
        local re = math.floor(m.mx + (math.min(#row.items, off + n - 1) - off + 1) * (cw + gap) - gap)
        local function chev(dir)
            local id = "tchev" .. (dir > 0 and "r" or "l")
            local x1, y1, t = HV.chev_box(m, (dir > 0) and re or m.mx, py + ch / 2)
            AX.ly.chev[#AX.ly.chev + 1] = { x = x1, y = y1, w = t, h = t, dir = dir, hot = AX.hover == id }
            hit(x1, y1, x1 + t, y1 + t, { id = id, act = function()
                tv.roff = math.max(1, math.min(off + dir * n, math.max(1, #row.items - n + 1)))
                if tv.zone == "row" then tv.rc = (dir > 0) and tv.roff or math.min(#row.items, tv.roff + n - 1) end
                render()
            end })
        end
        if off > 1 and not xmov then chev(-1) end
        if off + n - 1 < #row.items and not xmov then chev(1) end
        if HV.tip_lbl then HV.tip_draw(add, HV.tip_lbl, w, m); HV.tip_lbl = nil end
    end
end

function HV.AX.render()
    local AX = HV.AX
    HV.LY.frame()
    local m = HV.metrics()
    HV.m = m
    local w, h, lfs = m.w, m.h, m.lfs
    overlay.res_x, overlay.res_y = w, h
    local ev, pics, hits = {}, {}, {}
    AX.hits = hits
    AX.ly = nil
    local function add(c) ev[#ev + 1] = c end
    local function hit(x1, y1, x2, y2, t) t.x1, t.y1, t.x2, t.y2 = x1, y1, x2, y2; hits[#hits + 1] = t end
    add(D.ev_rect(0, 0, w, h, THEME.bg_dim, HV.bg_alpha(), nil, 0, 0))
    HV.XV.glass_bg(m)
    if m.glass then
        -- Home (back to the library), the add screen's levels as pills, EXPERIMENTAL on the right
        local y1, ph = m.gm, m.gph
        local cy = y1 + ph / 2
        local fs = math.max(12, lfs - 1)
        local pad = math.floor(ph * 0.55)
        local x = m.mx
        local hhot = AX.hover == "ghome"
        local hw = pad + ph * 0.5 + fs * 0.45 + AX.tw("Home", fs, true) + pad
        HV.gpill(add, x, y1, x + hw, y1 + ph, m, nil, nil, hhot)
        add(HV.house(x + pad + ph * 0.25, cy, ph * 0.46, hhot and "FFFFFF" or THEME.text_muted, 100))
        add(D.ev_text(x + pad + ph * 0.5 + fs * 0.45, cy, 4, string.format("\\b1\\fs%d\\c%s", fs, U.ass_color(hhot and "FFFFFF" or THEME.text_muted)), "Home"))
        hit(x, y1, x + hw, y1 + ph, { id = "ghome", act = function() AX.close() end })
        x = x + hw + math.floor(8 * m.S)
        local y2 = y1 + ph
        -- ✕ closes the browser, as on the library page
        local bcx = w - m.mx - ph / 2
        local chot = AX.hover == "close"
        HV.gpill(add, bcx - ph / 2, y1, bcx + ph / 2, y2, m, chot and THEME.bad or nil, chot and 80 or nil, false)
        add(D.ev_shape(D.cross_path(bcx, cy, ph * 0.19, math.max(1, ph * 0.045)), chot and "FFFFFF" or THEME.text_muted, 100))
        hit(bcx - ph / 2 - 4, y1 - 4, bcx + ph / 2 + 4, y2 + 4, { id = "close", act = function() close_browser() end })
        -- Online (F1: the setup check)
        local fail = listing_error[root_href]
        local st, stc = "Online", THEME.good
        if fail then st, stc = "Offline", THEME.bad elseif is_loading then st, stc = "Loading…", THEME.warn end
        local dk = U.kname("doctor")
        local dot = math.max(3, math.floor(fs * 0.2 + 0.5))
        local stw = AX.tw(st, fs)
        local kw = (dk ~= "") and (AX.tw(dk, fs - 3) + fs * 0.9) or 0
        local sx2 = bcx - ph / 2 - math.floor(10 * m.S)
        local sx1 = sx2 - (pad + dot * 2 + fs * 0.5 + stw + kw + pad * 0.8)
        HV.gpill(add, sx1, y1, sx2, y2, m, fail and THEME.bad or nil, fail and 16 or nil, AX.hover == "status")
        local dcx = sx1 + pad * 0.85
        add(D.ev_rect(dcx - dot, cy - dot, dcx + dot, cy + dot, stc, 100, nil, 0, 0, dot))
        add(D.ev_text(dcx + dot + fs * 0.5, cy, 4, string.format("\\fs%d\\c%s", fs, U.ass_color(fail and THEME.bad or THEME.text_primary)), U.ass_escape(st)))
        if dk ~= "" then add(D.ev_text(sx2 - pad * 0.8, cy, 6, string.format("\\fs%d\\c%s\\1a%s", fs - 3, U.ass_color(THEME.text_muted), U.ass_alpha(80)), U.ass_escape(dk))) end
        hit(sx1, y1, sx2, y2, { id = "status", act = function() HV.DR.show() end })
        local limit = sx1 - math.floor(10 * m.S)
        -- Tracked: its flyout opens over this page
        if HV.TK.on() then
            local n0 = #HV.links
            local lh0 = HV.link_hover
            HV.link_hover = (AX.hover == "tkpill") and 98 or nil
            local tx1 = HV.TK.pill(add, m, limit, y1, y2, fs, pad)
            HV.link_hover = lh0
            for i = #HV.links, n0 + 1, -1 do table.remove(HV.links, i) end          -- the pill's own link is the library's
            hit(tx1, y1, limit, y2, { id = "tkpill", act = function() HV.TK.toggle() end })
            limit = tx1
        end
        limit = limit - math.floor(16 * m.S)
        local cr = AX.crumbs()
        for i, c in ipairs(cr) do
            local room = limit - x - 2 * pad
            if room < fs * 3 then break end
            local txt = HV.fitw(c[1], room, fs, true)
            local cw = AX.tw(txt, fs, true) + 2 * pad
            local last = (i == #cr)
            local hot = c[2] and AX.hover == ("crumb" .. i)
            HV.gpill(add, x, y1, x + cw, y1 + ph, m, last and "FFFFFF" or nil, last and 13 or nil, hot)
            add(D.ev_text(x + pad, cy, 4, string.format("\\b1\\fs%d\\c%s", fs, U.ass_color((last or hot) and "FFFFFF" or THEME.text_muted)), U.ass_escape(txt)))
            if c[2] then hit(x, y1, x + cw, y1 + ph, { id = "crumb" .. i, act = c[2] }) end
            x = x + cw + math.floor(8 * m.S)
        end
        if PS.notice_text() and limit - x > fs * 8 then
            local txt = HV.fitw("⚠  " .. PS.notice_text(), limit - x - 2 * pad, fs - 1)
            local nw = AX.tw(txt, fs - 1) + 2 * pad
            HV.gpill(add, limit - nw, y1, limit, y1 + ph, m, THEME.warn, 12, false)
            add(D.ev_text(limit - nw + pad, cy, 4, string.format("\\fs%d\\c%s", fs - 1, U.ass_color(THEME.warn)), U.ass_escape(txt)))
        end
    else
    add(D.ev_rect(0, 0, w, m.top_h, THEME.bg_header, 100, nil, 0, 0))
    -- breadcrumbs (clickable)
    local cfs = math.floor((lfs + 8) * (0.5 + 0.5 * math.max(0.3, math.min(1.4, tonumber(o.top_bar_scale) or 0.8))))
    cfs = math.max(10, math.min(cfs, math.floor(m.top_h * 0.62)))
    local x = m.mx
    for i, c in ipairs(AX.crumbs()) do
        if i > 1 then
            local gap = cfs * 0.55
            add(D.ev_text(x + gap, m.top_h / 2, 4, string.format("\\fs%d\\b0\\c%s", cfs, U.ass_color(THEME.text_dim)), "›"))
            x = x + gap * 2 + AX.tw("›", cfs, false)
        end
        local tw = AX.tw(c[1], cfs, true)
        local hov = c[2] and AX.hover == ("crumb" .. i)
        local col = c[2] and (hov and "FFFFFF" or THEME.accent) or THEME.text_primary
        add(D.ev_text(x, m.top_h / 2, 4, string.format("\\fs%d\\b1\\u%d\\c%s", cfs, hov and 1 or 0, U.ass_color(col)), U.ass_escape(c[1])))
        if c[2] then hit(x - 4, 0, x + tw + 4, m.top_h, { id = "crumb" .. i, act = c[2] }) end
        x = x + tw
    end
    end
    local y = m.top_h + lfs * 1.6
    -- search box
    -- the source switch (Tab): Add-ons | Nyaa.si
    local sfs = lfs - 1
    local chips_ = { { "Add-ons", false }, { "Nyaa.si", true } }
    local cx2 = w - m.mx
    local cws = {}
    for i, ch in ipairs(chips_) do cws[i] = AX.tw(ch[1], sfs, true) + sfs * 1.6 end
    local cx1 = cx2 - cws[1] - cws[2] - sfs * 0.6
    local bx1, bx2 = m.mx, cx1 - sfs
    -- release lists: the filter is a pill in this row, between the search box and the source switch
    local listy_ = (AX.stage == "packs" or AX.stage == "releases")
    local frow = nil
    if listy_ then
        local fwid = math.floor(math.min(w * 0.28, (bx2 - bx1) * 0.45))
        frow = { x1 = bx2 - fwid, x2 = bx2 }
        bx2 = frow.x1 - sfs * 0.6
    end
    do
        local x_ = cx1
        for i, ch in ipairs(chips_) do
            local on = (AX.nyaa == ch[2])
            local hov = AX.hover == ("src" .. i)
            if m.glass then
                if on then add(D.ev_rect(x_, y - lfs, x_ + cws[i], y + lfs, THEME.accent, 85, nil, 0, 0, lfs))
                else HV.gpill(add, x_, y - lfs, x_ + cws[i], y + lfs, m, nil, nil, hov) end
            else
                add(D.ev_rect(x_, y - lfs, x_ + cws[i], y + lfs, on and THEME.accent or THEME.bg_panel, on and 85 or 100, THEME.accent, (on or hov) and 100 or 35, 1, 8))
            end
            add(D.ev_text(x_ + cws[i] / 2, y, 5, string.format("\\fs%d\\b1\\c%s", sfs, U.ass_color((on or hov) and "FFFFFF" or THEME.text_muted)), U.ass_escape(ch[1])))
            local to = ch[2]
            hit(x_, y - lfs, x_ + cws[i], y + lfs, { id = "src" .. i, act = function() AX.toggle_src(to) end })
            x_ = x_ + cws[i] + sfs * 0.6
        end
    end
    local editing = (AX.stage == "query")
    if m.glass then
        HV.gpill(add, bx1, y - lfs, bx2, y + lfs, m, nil, nil, false)
        if editing then add(D.ev_rect(bx1, y - lfs, bx2, y + lfs, "FFFFFF", 0, THEME.accent, 90, math.max(1, math.floor(m.S + 0.5)), lfs)) end
    else
        add(D.ev_rect(bx1, y - lfs, bx2, y + lfs, THEME.bg_panel, 100, THEME.accent, editing and 100 or 35, 1, 8))
    end
    do
        local q = AX.q or ""
        local label = AX.nyaa and "Search Nyaa.si:  " or "Movie or series:  "
        local txt
        if editing then
            local pos = math.max(0, math.min(#q, AX.qc or #q))
            local caret = HV.XA.on("caret") and HV.XA.caret(THEME.accent, THEME.text_primary, false)
                or string.format("{\\c%s}▏{\\c%s}", U.ass_color(THEME.accent), U.ass_color(THEME.text_primary))
            txt = U.ass_escape(label) .. HV.XA.before(q:sub(1, pos)) .. caret .. U.ass_escape(q:sub(pos + 1))
            if q == "" then
                txt = txt .. string.format("{\\c%s}", U.ass_color(AX.bs_armed and THEME.warn or THEME.text_dim))
                    .. U.ass_escape(AX.bs_armed and "Press Backspace again to go back  (Esc works too)" or (AX.nyaa and "release name, group, episode… Enter to search" or "type a title, Enter to search"))
            end
        else
            local shown = (AX.nyaa and AX.m and AX.m.kind == "nyaa" and not AX.m.latest) and (AX.nyaa_q or q) or q
            txt = U.ass_escape(label .. shown)
            if shown == "" then
                txt = txt .. string.format("{\\c%s}", U.ass_color(AX.bs_armed and THEME.warn or THEME.text_dim))
                    .. U.ass_escape(AX.bs_armed and "Press Backspace again to close  (Esc works too)" or "start typing to search")
            end
        end
        add(D.ev_text(bx1 + (m.glass and lfs or 16), y, 4, string.format("\\fs%d\\c%s", lfs + 2, U.ass_color(THEME.text_primary)), txt))
    end
    if not editing and AX.stage ~= "pick" and AX.stage ~= "adding" then
        hit(bx1, y - lfs, bx2, y + lfs, { id = "qbox", act = function() AX.edit_query() end })
    end
    if frow then
        local fx1, fx2, fs = frow.x1, frow.x2, lfs - 1
        if m.glass then
            HV.gpill(add, fx1, y - lfs, fx2, y + lfs, m, nil, nil, AX.hover == "filter")
            if AX.fedit then add(D.ev_rect(fx1, y - lfs, fx2, y + lfs, "FFFFFF", 0, THEME.accent, 90, math.max(1, math.floor(m.S + 0.5)), lfs)) end
        else
            add(D.ev_rect(fx1, y - lfs, fx2, y + lfs, THEME.bg_panel, 100, THEME.accent, AX.fedit and 100 or 35, 1, 8))
        end
        local shown = (AX.filt ~= "" or AX.fedit)
        local ftxt
        if AX.fedit then
            local fq = AX.filt or ""
            local pos = math.max(0, math.min(#fq, AX.fc or #fq))
            local caret = HV.XA.on("caret") and HV.XA.caret(THEME.accent, THEME.text_primary, false)
                or string.format("{\\c%s}▏{\\c%s}", U.ass_color(THEME.accent), U.ass_color(THEME.text_primary))
            ftxt = HV.XA.before(fq:sub(1, pos)) .. caret .. U.ass_escape(fq:sub(pos + 1))
        else ftxt = U.ass_escape(HV.ell(shown and AX.filt or "Filter (/)  e.g. dual 1080 -hevc", fx2 - fx1 - lfs * 1.6, fs)) end
        add(D.ev_text(fx1 + (m.glass and lfs or 12), y, 4, string.format("\\fs%d\\c%s", fs, U.ass_color(shown and THEME.text_primary or THEME.text_dim)), ftxt))
        hit(fx1, y - lfs, fx2, y + lfs, { id = "filter", act = function() AX.start_filter() end })
    end
    y = y + lfs * 2.2
    -- season tabs · sort · filter (release lists)
    local listy = (AX.stage == "packs" or AX.stage == "releases")
    if listy then
        local fs = lfs - 1
        local tx = m.mx
        if AX.stage == "packs" and AX.title then
            local tabs = { { 0, "All seasons" } }
            for _, se in ipairs(AX.slist(AX.title)) do tabs[#tabs + 1] = { se.season, "S" .. se.season } end
            for _, pt in ipairs(AX.title.parts or {}) do tabs[#tabs + 1] = { pt.key, U.fit_text(pt.label, w * 0.18, fs) } end
            for _, tb in ipairs(tabs) do
                local on = (tb[1] == (AX.sfilter or 0))
                local hov = AX.hover == ("tab" .. tb[1])
                add(D.ev_text(tx, y, 4, string.format("\\fs%d\\b%d\\c%s", fs, on and 1 or 0, U.ass_color(on and THEME.accent or (hov and "FFFFFF" or THEME.text_muted))), U.ass_escape(tb[2])))
                local tw = AX.tw(tb[2], fs, on)
                local s_ = tb[1]
                hit(tx - 6, y - fs * 0.7, tx + tw + 6, y + fs * 0.7, { id = "tab" .. s_, act = function() AX.sfilter = s_; AX.relist(true) end })
                tx = tx + tw + fs * 0.9
            end
            tx = tx + fs
        end
        local stext = "Sort: " .. AX.sort_cur()[2]
        add(D.ev_text(tx, y, 4, string.format("\\fs%d\\c%s", fs, U.ass_color(AX.hover == "sort" and "FFFFFF" or THEME.text_primary)), U.ass_escape(stext) .. string.format("{\\c%s}  (S)", U.ass_color(THEME.text_dim))))
        local sw = AX.tw(stext .. "  (S)", fs)
        hit(tx - 6, y - fs * 0.7, tx + sw + 6, y + fs * 0.7, { id = "sort", act = function() AX.cycle_sort() end })
        tx = tx + sw + fs * 1.5
        -- how many there are (of how many, when the filter hides some), right-aligned
        local nshow = #(AX.list or {})
        local ctxt = string.format("%d %s", nshow, (AX.stage == "packs") and ((nshow == 1) and "pack" or "packs") or ((nshow == 1) and "release" or "releases"))
        if AX.filt and AX.filt ~= "" and AX.all_n and AX.all_n > nshow then ctxt = ctxt .. string.format(" of %d", AX.all_n) end
        add(D.ev_text(w - m.mx, y, 6, string.format("\\fs%d\\c%s", fs, U.ass_color(THEME.text_muted)), U.ass_escape(ctxt)))
        y = y + lfs * 1.7
    end
    if AX.msg and o.empty_states and AX.stage == "results" and #(AX.list or {}) == 0 and not AX.msg:match("…$") then
        HV.XV.empty(add, m, w / 2, (y + h - m.foot_h) / 2, "library", AX.msg, AX.nyaa and "Try fewer words" or "Try another spelling, or the original title")
    elseif AX.msg then
        add(D.ev_text(m.mx, y, 4, string.format("\\fs%d\\c%s", lfs - 1, U.ass_color(THEME.warn)), U.ass_escape(U.fit_text(AX.msg, w - 2 * m.mx, lfs - 1))))
        y = y + lfs * 1.5
    end
    -- the add-ons found little: Nyaa.si in one click (or Tab)
    if AX.nyaa_tip and (AX.stage == "packs" or AX.stage == "releases") and not AX.nyaa then
        local tip = AX.nyaa_tip
        local fs = lfs - 2
        local lab = "Search Nyaa.si for “" .. tip.name .. "”   Tab"
        local tw_ = AX.tw(tip.text, fs)
        add(D.ev_text(m.mx, y, 4, string.format("\\fs%d\\c%s", fs, U.ass_color(THEME.text_muted)), U.ass_escape(tip.text)))
        local bx = m.mx + tw_ + lfs
        local bw = math.floor(AX.tw(lab, fs, true) + fs * 2)
        local bh = math.floor(lfs * 1.6)
        HV.gpill(add, bx, y - bh / 2, bx + bw, y + bh / 2, m, nil, nil, AX.hover == "nyaatip")
        add(D.ev_text(bx + bw / 2, y, 5, string.format("\\b1\\fs%d\\c%s", fs, U.ass_color(THEME.text_primary)), U.ass_escape(lab)))
        hit(bx, y - bh / 2, bx + bw, y + bh / 2, { id = "nyaatip", act = function() AX.nyaa_for(tip.name) end })
        y = y + lfs * 1.8
    end
    local bottom = h - m.foot_h - lfs * 0.5
    local st = AX.stage
    if st ~= "adding" then HV.SC.hide("ax") end
    if st == "adding" and AX.job then
        -- the wait itself is the floating status card (HV.SC), the same one the download-while-playing fallback uses
        HV.SC.show(AX.job_card(AX.job))
    elseif st == "title" then
        AX.render_title(add, hit, pics, m, y, bottom)
    elseif st == "home" or (st == "query" and not AX.nyaa) then
        AX.render_home(add, hit, pics, m, y, bottom, st == "home")
    elseif st == "results" then
        -- tall rows: poster, title (year), type · rating · votes · in your library, two lines of overview
        local rh = math.floor(lfs * 5.6)
        local pw, ph = AX.poster_size(m)
        local rows = math.max(1, math.floor((bottom - y) / rh))
        if AX.sel < AX.top then AX.top = AX.sel elseif AX.sel >= AX.top + rows then AX.top = AX.sel - rows + 1 end
        local tx = m.mx + pw + 24
        local tw = w - m.mx - tx - 10
        for i = AX.top, math.min(#AX.list, AX.top + rows - 1) do
            local it = AX.list[i]
            local ry = y + (i - AX.top) * rh
            local sel = (i == AX.sel)
            if sel then add(D.ev_rect(m.mx - 10, ry - 4, w - m.mx + 10, ry + rh - 6, THEME.accent, 18, THEME.accent, 70, 2, 10))
            elseif AX.hover == i then add(D.ev_rect(m.mx - 10, ry - 4, w - m.mx + 10, ry + rh - 6, THEME.accent, 7, nil, 0, 0, 10)) end
            hit(m.mx - 10, ry - 4, w - m.mx + 10, ry + rh - 6, { row = i })
            local f, fw, fh = AX.poster(it, pw, ph)
            if f then pics[#pics + 1] = { x = m.mx, y = ry + 2, f = f, w = pw, h = ph, sw = fw, sh = fh }
            else add(D.ev_rect(m.mx, ry + 2, m.mx + pw, ry + 2 + ph, THEME.bg_panel, 100, nil, 0, 0, 8)) end
            add(D.ev_text(tx, ry + lfs * 0.8, 4, string.format("\\b1\\fs%d\\c%s", lfs + 2, U.ass_color(sel and "FFFFFF" or THEME.text_primary)),
                U.ass_escape(U.fit_text(it.text or "?", tw, lfs + 2))))
            local chips = { { (it.anime or it.src == "AniList") and "Anime" or (it.kind == "tv" and "Series" or "Movie"), THEME.accent } }
            if it.vote > 0 and it.votes ~= 0 then chips[#chips + 1] = { string.format("★ %.1f", it.vote), THEME.star } end
            if it.votes then chips[#chips + 1] = { (it.votes == 1) and "1 vote" or (tostring(it.votes) .. " votes") } end
            if it.inlib then chips[#chips + 1] = { "✓ in your library", THEME.good }
            elseif it.added then chips[#chips + 1] = { "✓ added to Real-Debrid - on its way to your library", THEME.good } end
            add(D.ev_text(tx, ry + lfs * 2.0, 4, string.format("\\fs%d", lfs - 2), AX.chips_ass(chips)))
            local lines = TV.wrap(it.overview ~= "" and it.overview or "No overview on TMDB.", tw, lfs - 3, 2)
            for k, ln in ipairs(lines) do
                add(D.ev_text(tx, ry + lfs * (2.15 + 1.1 * k), 4, string.format("\\fs%d\\c%s", lfs - 3, U.ass_color(THEME.text_muted)), U.ass_escape(ln)))
            end
        end
    elseif st ~= "query" then
        -- releases / packs: three lines (name, file, details); the other lists two
        local rel = (st == "packs" or st == "releases")
        local rh = math.floor(lfs * (rel and 3.9 or 2.9))
        local cur = AX.list[AX.sel]
        local detail_h = 0
        if rel and cur then detail_h = lfs * 3.6 elseif cur and cur.note and cur.note ~= "" then detail_h = lfs * 2.6 end
        if st == "pick" then detail_h = lfs * 1.8 end
        local rows = math.max(1, math.floor((bottom - detail_h - y) / rh))
        if AX.sel < AX.top then AX.top = AX.sel elseif AX.sel >= AX.top + rows then AX.top = AX.sel - rows + 1 end
        AX.top = math.max(1, math.min(AX.top, math.max(1, #AX.list - rows + 1)))
        if AX.sel < AX.top then AX.top = AX.sel end
        local cx = m.mx + 6
        for i = AX.top, math.min(#AX.list, AX.top + rows - 1) do
            local row = AX.list[i]
            local ry = y + (i - AX.top) * rh
            local sel = (i == AX.sel)
            if sel then add(D.ev_rect(m.mx - 10, ry, w - m.mx + 10, ry + rh - 6, THEME.accent, 18, THEME.accent, 70, 2, 10))
            elseif AX.hover == i then add(D.ev_rect(m.mx - 10, ry, w - m.mx + 10, ry + rh - 6, THEME.accent, 7, nil, 0, 0, 10)) end
            hit(m.mx - 10, ry, w - m.mx + 10, ry + rh - 6, { row = i })
            local tx = cx
            if st == "pick" then
                local bs = math.floor(lfs * 0.9)
                local by = ry + (rh - 6) / 2 - bs / 2
                add(D.ev_rect(cx, by, cx + bs, by + bs, row.on and THEME.accent or THEME.bg_panel, 100, row.on and THEME.accent or THEME.text_muted, 100, 2, 4))
                if row.on then add(D.ev_text(cx + bs / 2, by + bs / 2, 5, string.format("\\b1\\fs%d\\c%s", bs, "FFFFFF"), "✓")) end
                hit(cx - 6, ry, cx + bs + 10, ry + rh - 6, { row = i, box = true })
                tx = cx + bs + lfs * 0.7
            end
            local tw = w - m.mx - tx - 14
            if rel then
                local it = row.rel
                -- measured cuts (…) so a long release name never runs under the next column
                add(D.ev_text(tx, ry + rh * 0.22, 4, string.format("\\b1\\fs%d\\c%s", lfs, U.ass_color(sel and "FFFFFF" or THEME.text_primary)), U.ass_escape(HV.ell(it.title, tw, lfs, true))))
                if it.file and it.file ~= it.title then
                    add(D.ev_text(tx, ry + rh * 0.48, 4, string.format("\\fs%d\\c%s", lfs - 3, U.ass_color(THEME.text_muted)), U.ass_escape(HV.ell("📄 " .. it.file, tw, lfs - 3))))
                end
                add(D.ev_text(tx, ry + rh * 0.74, 4, string.format("\\fs%d", lfs - 3), AX.chips_ass(AX.rel_chips(it))))
            else
                local dim = (st == "pick" and not row.video)
                add(D.ev_text(tx, ry + rh * 0.32, 4, string.format("\\b1\\fs%d\\c%s", lfs, U.ass_color(sel and "FFFFFF" or (dim and THEME.text_muted or THEME.text_primary))),
                    U.ass_escape(U.fit_text(row.text or "?", tw, lfs))))
                if row.chips and #row.chips > 0 then
                    add(D.ev_text(tx, ry + rh * 0.68, 4, string.format("\\fs%d", lfs - 3), AX.chips_ass(row.chips)))
                end
            end
        end
        if #AX.list > rows and not rel then           -- release lists: the sort line says how many
            add(D.ev_text(w - m.mx, y - lfs * 0.6, 6, string.format("\\fs%d\\c%s", lfs - 3, U.ass_color(THEME.text_dim)),
                string.format("%d–%d of %d", AX.top, math.min(#AX.list, AX.top + rows - 1), #AX.list)))
        end
        -- details of the highlighted row: the add-on's own text, so nothing is hidden
        local dy = bottom - detail_h + lfs * 0.3
        if rel and cur then
            local it = cur.rel
            if m.glass then HV.gcard(add, m.mx - lfs * 0.6, bottom - detail_h, w - m.mx + lfs * 0.6, bottom - lfs * 0.2, m)
            else add(D.ev_rect(0, bottom - detail_h, w, h - m.foot_h, THEME.bg_header, 92, nil, 0, 0)) end
            local txt = (it.name_raw or ""):gsub("\n+", "  ") .. "  ·  " .. (it.desc_raw or ""):gsub("\n+", "  ·  ")
            if it.hash then txt = txt .. "  ·  hash " .. it.hash end
            local ls = TV.wrap(txt, w - 2 * m.mx, lfs - 4, 3)
            for k, ln in ipairs(ls) do ls[k] = U.ass_escape(ln) end
            add(D.ev_text(m.mx, dy, 7, string.format("\\fs%d\\c%s", lfs - 4, U.ass_color(THEME.text_muted)), table.concat(ls, "\\N")))
        elseif st == "pick" then
            local n, bytes = AX.pick_totals()
            add(D.ev_text(m.mx, dy + lfs * 0.3, 7, string.format("\\b1\\fs%d\\c%s", lfs, U.ass_color(n > 0 and THEME.text_primary or THEME.warn)),
                U.ass_escape(string.format("%d of %d files ticked  ·  %s", n, #AX.list, U.fmt_bytes(bytes)))))
        elseif cur and cur.note and cur.note ~= "" then
            local ls = TV.wrap(cur.note, w - 2 * m.mx, lfs - 2, 2)
            for k, ln in ipairs(ls) do ls[k] = U.ass_escape(ln) end
            add(D.ev_text(m.mx, dy, 7, string.format("\\fs%d\\c%s", lfs - 2, U.ass_color(THEME.text_muted)), table.concat(ls, "\\N")))
        end
    end
    -- footer
    if not m.glass then add(D.ev_rect(0, h - m.foot_h, w, h, THEME.bg_header, 100, nil, 0, 0)) end
    local hint
    if AX.fedit then hint = "Type to filter (-word leaves out)   ← → Move the cursor   Enter / ↓ Done   Esc Clear"
    else
        hint = ({ home = "←↑↓→ Move   Enter Open   Type to search   Tab Nyaa.si   ↑ at the top: search box   Esc Close",
            query = AX.nyaa and "Type a release name   ← → Home End Move the cursor   Enter Search Nyaa.si   ↓ The list   Tab Add-ons   Esc Back"
                or ("Type a title   ← → Home End Move the cursor   Enter Search TMDB   ↓ " .. (AX.results and "Back to the results" or "Home") .. "   Tab Nyaa.si   Esc Back"),
            results = "↑↓ Move   Enter Pick   Esc Back",
            title = "← → Choose   ↑↓ Buttons / row   Enter Open   Tab Nyaa.si   Esc Back",
            packs = "↑↓ Move   ← → Season   S Sort   / Filter   Enter Choose files   T Stream torrent   E Single episode   Ctrl+S Save answers   Esc Back",
            releases = AX.nyaa and "↑↓ Move (↑ at the top: search)   S Sort   / Filter   Enter Choose files   T Stream torrent   Tab Add-ons   Esc Back"
                or "↑↓ Move   S Sort   / Filter   Enter Choose files   T Stream torrent   Ctrl+S Save answers   Esc Back",
            seasons = "↑↓ Move   Enter Pick season   Esc Back", episodes = "↑↓ Move   Enter Find releases   Esc Back",
            pick = (AX.job and AX.job.kind == "torrent") and "↑↓ Move   Space Tick   A All / none   Enter Stream the ticked files   Esc Cancel"
                or "↑↓ Move   Space Tick   A All / none   Enter Add the ticked files   Esc Cancel (removes it again)",
            ready = (AX.job and AX.job.kind == "torrent") and "↑↓ Move   Enter Play from here (the next ones follow)   Esc Back (removes the torrent)"
                or "↑↓ Move   Enter Play from here (the next ones follow)   P Download + play   Esc Back   Ctrl+D Delete from Real-Debrid",
            adding = (AX.job and AX.job.kind == "torrent") and "Esc Cancel (rqbit drops the torrent again)"
                or (AX.job and AX.job.err) and ("T Stream as a torrent   Esc Back" .. (AX.job.id and "   Ctrl+D Delete it" or "") .. "   Ctrl+N Try the next release")
                or "Esc Keep it on Real-Debrid   Ctrl+D Delete it   Ctrl+N Delete and try the next release" })[st or ""] or ""
    end
    if m.glass then
        HV.glass_keys(add, m, hint, function(a, b, c, d, id, act) hit(a, b, c, d, { id = id, act = act }) end, function(id) return AX.hover == id end)
        -- ↓ Downloads, bottom right, as on the library page (a click goes back to the library and opens the queue)
        if HV.DLP.visible() then
            local ph_ = m.gph
            local fy1 = h - math.floor(m.gm * 0.9) - ph_
            local fs_ = math.max(11, lfs - 3)
            local pad_ = math.floor(ph_ * 0.55)
            local n = HV.DLP.count()
            local lab = "↓  Downloads" .. ((n > 0) and ("  " .. n) or "")
            local pw_ = math.floor(AX.tw(lab, fs_, true) + 2 * pad_)
            local hot = AX.hover == "dlpill"
            HV.gpill(add, w - m.mx - pw_, fy1, w - m.mx, fy1 + ph_, m, nil, nil, hot)
            add(D.ev_text(w - m.mx - pw_ / 2, fy1 + ph_ / 2, 5, string.format("\\b1\\fs%d\\c%s", fs_, U.ass_color(hot and "FFFFFF" or THEME.text_muted)), U.ass_escape(lab)))
            hit(w - m.mx - pw_, fy1, w - m.mx, fy1 + ph_, { id = "dlpill", act = function() HV.dl_show() end })
        end
    else
        add(D.ev_text(m.mx, h - m.foot_h * 0.5, 4, string.format("\\fs%d\\c%s", lfs - 2, U.ass_color(THEME.text_muted)), U.ass_escape(U.fit_text(hint, w - 2 * m.mx, lfs - 2))))
    end
    if PS.notice_text() and not m.glass then
        add(D.ev_text(w - m.mx - lfs, m.top_h / 2, 6, string.format("\\fs%d\\c%s", lfs - 2, U.ass_color(THEME.warn)), U.ass_escape("⚠  " .. U.fit_text(PS.notice_text(), w * 0.35, lfs - 2))))
    end
    if HV.dlc() or (HV.DLC and HV.DLC.closing and HV.DLC.kind == "win") then HV.dl_card(add, m) end
    if HV.TK.drawn() then HV.TK.draw(add, m) end
    local data = table.concat(ev, "\n")
    if data ~= HV.last_data then
        HV.last_data = data
        overlay.data = data
        HV.cmd({ name = "osd-overlay", id = overlay.id, format = "ass-events", data = data,
                 res_x = math.floor(w), res_y = math.floor(h), z = overlay.z or 0, hidden = false }, nil, "ass")
    end
    HV.A.shimmer, HV.A.shimmer_seen = HV.A.shimmer_seen, nil          -- (a placeholder still loading: the sweep goes on)
    HV.place_list(pics)
    HV.flush()
end

-- the add screen's own pictures (result posters) on ids 0..59; everything else goes
function HV.place_list(pics)
    local used = {}
    if HV.modal() then
        for id in pairs(HV.shown) do HV.cmd({ "overlay-remove", tostring(id) }); HV.shown[id] = nil end
        return
    end
    -- the flyout / the queue window over the add screen: no picture inside it, the rest dimmed for the window
    local mask = (HV.dlc() and HV.DLC.hole) or (HV.TK.drawn() and HV.TK.hole) or nil
    if mask then
        local kept = {}
        for _, p in ipairs(pics or {}) do
            if not (p.x < mask[3] and p.x + p.w > mask[1] and p.y < mask[4] and p.y + p.h > mask[2]) then kept[#kept + 1] = p end
            if #kept >= 40 then break end            -- 40-46: the flyout's posters
        end
        pics = kept
        if HV.dw_ok() and HV.dlc() and HV.DLC.dim then HV.LY.place_dim(used, { 0, 0, HV.m.w, HV.m.h }, mask, 62) end
        for i, pc in ipairs(HV.TK.drawn() and HV.TK.pics or {}) do
            if i > 6 then break end
            local id = (39 + i >= 42) and (40 + i) or (39 + i)
            local sig = pc.f .. "@" .. pc.x .. "," .. pc.y .. "~" .. pc.w
            if HV.shown[id] ~= sig then HV.overlay_add(id, pc.x, pc.y, pc.f, pc.sw or pc.w, pc.sh or pc.h, sig, pc.w, pc.h) end
            used[id] = true
        end
    end
    -- the add screen's layers: arrows on the rows that scroll on, the dimming around the selected poster
    local ly = (not mask) and HV.AX.ly or nil
    if ly then
        for i, c in ipairs(ly.chev or {}) do
            if i > 6 then break end
            local f = HV.LY.chevron(THEME.bg_dim, c.w, c.h, c.dir, c.hot)
            if f then
                local id = HV.LY.ID_CHEV + i - 1
                local sig = f .. "@" .. c.x .. "," .. c.y
                if HV.shown[id] ~= sig then HV.overlay_add(id, c.x, c.y, f, c.w, c.h, sig) end
                used[id] = true
            end
        end
        if ly.dim and HV.LY.dim_on() then HV.LY.place_dim(used, ly.dim[1], ly.dim[2]) end
    end
    for i, p in ipairs(pics or {}) do
        if i > HV.CARD_IDS - 1 then break end
        local id = (i - 1 >= 42) and i or (i - 1)              -- 42 is thumbfast's
        local px, py = math.floor(p.x + 0.5), math.floor(p.y + 0.5)
        local fw = p.sw or p.w
        local hx, hoff, hsw, hdw = HV.XS.hclip(px, p.w, fw, HV.m.w)
        if hx then
            local sig = p.f .. "@" .. hx .. "," .. py .. "~" .. p.w .. "^" .. hdw .. ":" .. hoff
            if HV.shown[id] ~= sig then HV.overlay_add(id, hx, py, p.f, hsw, p.sh or p.h, sig, hdw, p.h, hoff, fw * 4) end
            used[id] = true
        end
    end
    for id in pairs(HV.shown) do
        if not used[id] then HV.cmd({ "overlay-remove", tostring(id) }); HV.shown[id] = nil end
    end
end

end

-- ============================================================
-- LIVE CONFIG RELOAD
-- ============================================================
-- Re-reads webdav-browser.conf (+ script-opts) into a fresh copy of the defaults and applies only
-- what changed. Triggered by the on_update callback, by a 2-second poll while the browser is open
-- (editing the .conf file does not fire on_update by itself), and by
-- `script-message webdav-browser-reload-config`.
local function apply_config_changes(changed)
    normalize_options()
    THEME = build_theme()
    TOAST = PAL.build_toast()
    ICONS = build_icons()
    auth_configured = false
    if changed.url or changed.user or changed.pass or changed.start_path then
        dir_cache, tree, root_children, file_entries = {}, {}, {}, {}
        MS.flat, MS.cache_version = nil, MS.cache_version + 1
        listing_error = {}
        index_stop()
        if browser_active then
            root_href = (o.start_path ~= "" and o.start_path or "/")
            load_root()
        end
    end
    if changed.background_blur_enabled or changed.background_blur_mode or changed.background_blur_strength
        or changed.background_blur_max_height or changed.background_blur_force then
        remove_background_blur()
        if browser_active then apply_background_blur() end
    end
    sidebar_frac = want_sidebar_frac()
    -- a key changed: the browser's keys are bound again (the hints showed the new key while the old one still worked)
    local keys = false
    for k in pairs(changed) do if tostring(k):match("^key_") then keys = true end end
    if keys and browser_active and not search_active and not HV.typing and HV.mode ~= "add" and not (HV.DR and HV.DR.open) then
        unbind_all(); bind_all()
    end
    if browser_active then render() end
end

-- the conf file's size and date: the poll only reads the file again when they change
function MS.conf_stamp()
    if not MS.conf_path and mp.get_time() - (MS.conf_look or -99) > 30 then
        MS.conf_look = mp.get_time()
        local ok, pth = pcall(mp.find_config_file, "script-opts/webdav-browser.conf")
        MS.conf_path = (ok and type(pth) == "string") and pth or false
    end
    local i = MS.conf_path and utils.file_info(MS.conf_path)
    return i and (tostring(i.size) .. "|" .. tostring(i.mtime)) or "none"
end
local function reload_config()
    MS.conf_sig = MS.conf_stamp()
    local fresh = {}
    for k, v in pairs(DEFAULTS) do fresh[k] = v end
    options.read_options(fresh, "webdav-browser")
    U.conf_notes = U.lenient_conf(fresh)
    U.normalize_all(fresh)    -- the same cleanup as at the start, or a cleaned value looks changed for ever
    local changed, any = {}, false
    for k, v in pairs(fresh) do
        if o[k] ~= v then changed[k] = true; any = true end
    end
    if not any then return end
    for k in pairs(changed) do o[k] = fresh[k] end
    apply_config_changes(changed)
    if browser_active then HV.TS.show({ eyebrow = "WEBDAV-BROWSER", title = "Config reloaded" }, 2) else HV.say({ eyebrow = "WEBDAV-BROWSER", title = "Config reloaded" }, 2) end
    status_line = "Config reloaded"
    if browser_active then render() end
end
hot_reload_hook = function() reload_config() end
mp.register_script_message("webdav-browser-reload-config", reload_config)
mp.register_script_message("webdav-browser-reindex", function() index_start(true) end)

-- ============================================================
-- OPEN / CLOSE
-- ============================================================
-- mpv's own controller draws its idle logo ("Drop files or URLs to play here") under the browser, and it shows
-- through the see-through panels: hidden while the browser is open, put back as it was when it closes
MS.logo = function(show)
    if show then
        if MS.logo_off then MS.logo_off = nil; mp.commandv("script-message", "osc-idlescreen", "yes", "no_osd") end
    else
        local on = mp.get_property_native("user-data/osc/idlescreen")
        if on == nil then
            -- the OSC only publishes this once it was changed: go by its settings (default: logo on)
            on = mp.get_property_native("osc") == true
            local so = mp.get_property_native("script-opts") or {}
            if so["osc-idlescreen"] == "no" then on = false end
            local ok, path = pcall(mp.command_native, { "expand-path", "~~/script-opts/osc.conf" })
            local f = ok and path and io.open(path, "r")
            if f then
                local t = "\n" .. f:read("*a"); f:close()
                if t:find("\n%s*idlescreen%s*=%s*no") then on = false end
            end
        end
        if on == true then
            MS.logo_off = true
            mp.commandv("script-message", "osc-idlescreen", "no", "no_osd")
        end
    end
end
-- While the browser is open over a video, the player's own controller (osc / ModernZ) must not wake up when the
-- mouse passes its seekbar zone: its thumbnails (thumbfast) used to show through the browser. It is hidden while
-- the browser is open and set back to osc_visibility (auto) when it closes (hide_osc=no leaves it alone).
MS.osc = function(hide)
    if not o.hide_osc then return end
    if hide then
        if MS.osc_off then return end
        MS.osc_off = true
        mp.commandv("script-message", "osc-visibility", "never", "no_osd")
        mp.commandv("script-message-to", "thumbfast", "clear")
    elseif MS.osc_off then
        MS.osc_off = nil
        mp.commandv("script-message", "osc-visibility", tostring(o.osc_visibility or "auto"), "no_osd")
    end
end
-- while the browser is open a press-and-move belongs to it (a row being dragged, the list's scroll bar), not to mpv's
-- window dragging (which takes the button away as soon as the pointer moves): an empty input section without
-- allow-vo-dragging that covers the window tells mpv so
function MS.nodrag(on)
    local name = "webdav_nodrag_" .. mp.get_script_name()
    if on == MS.nodrag_on then return end
    MS.nodrag_on = on
    if on then
        mp.commandv("define-section", name, "", "default")
        mp.commandv("enable-section", name, "allow-hide-cursor")
        if mp.input_set_section_mouse_area then mp.input_set_section_mouse_area(name, 0, 0, 99999, 99999) end
    else
        mp.commandv("disable-section", name)
    end
end
close_browser = function()
    MS.nodrag(false)
    if HV.XS.p then HV.XS.p.st.drag = nil; HV.XS.p = nil end
    HV.vsb_drag, HV.vsb_hot = nil, nil
    if HV.XA.exit then HV.XA.exit = nil; HV.XA.exit_keys_off() end
    HV.XA.rb = nil
    MS.osc(false)
    HV.SC.done("ax")
    MS.logo(true)
    browser_active = false
    if HV.TS.spec then HV.TS.draw() end
    HV.TR.stop(true)
    mp.commandv("script-message", "disable-elements", mp.get_script_name(), "")
    pcall(HV.AX.abandon)        -- an unfinished job leaves nothing behind (no waiting torrent, no rqbit download)
    if HV.AX.stage then
        HV.AX.unbind()
        if HV.AX.poll then HV.AX.poll:kill(); HV.AX.poll = nil end
        HV.AX.stage, HV.AX.job = nil, nil
        HV.mode = "home"
    end
    MS.drag = nil
    HV.HP.close()
    HV.GL.hide("bg")
    HV.TK.open, HV.TK.hole, HV.TK.closing = false, nil, nil
    HV.CM.open = false       -- a context menu left open came back (and took Enter) in the next session
    HV.DLC = nil             -- the download card (a stale one used to take over the keys of the next session)
    stop_anim()
    if MS.conf_timer then MS.conf_timer:kill(); MS.conf_timer = nil end
    if search_active then
        unbind_search()
        search_active = false
    end
    unbind_all()
    remove_background_blur()
    -- Flush any pending debounced write immediately instead of leaving it to fire later.
    if persist_debounce_timer then
        persist_debounce_timer:kill()
        persist_debounce_timer = nil
        save_persistence()
        save_dircache()
    end
    overlay:remove()
    HV.clear_text()
    MS.last_overlay_data = nil
    PS.hide()
    HV.clear()
    HV.hover = nil
    HV.mode, HV.tv.card, HV.q, HV.qa, HV.typing = "home", nil, nil, nil, false
    MS.view = nil
end

-- Two webdav-browser scripts can be installed side by side (different open keys). Whichever browser was
-- opened last "owns" playback; the other one closes itself, and the data file is re-read so watch history
-- written by the other script is not overwritten with stale data.
MS.active = true
local function reload_user_data(if_changed)
    local path = persist_status.path or history_file_path()
    if not path then return end
    if if_changed then
        -- this instance owns the data: what it changed and has not written yet goes to disk first (it is the newest),
        -- and the file is only read again when someone else wrote it since
        if MS.active ~= false and (MS.prog_dirty or MS.hist_dirty) then MS.hist_dirty = false; save_persistence() end
        if MS.disk_same(path) then return end
    end
    local data = try_load_json(path) or try_load_json(path .. ".bak")
    if not data then return end
    MS.disk_mark(path)
    watch_history = U.plain(data.history)
    watched_set   = U.plain(data.watched)
    sort_by_dir   = U.plain(data.sort)
    index_meta    = U.plain(data.index)
    MS.hints      = U.plain(data.hints)
    MS.tracks     = U.plain(data.tracks)
    MS.tracked    = U.plain(data.tracked)
    MS.rev        = tonumber(data.rev) or MS.rev
    mark_continue_dirty()
    if browser_active then render() end
end
-- Hand-over: the instance that loses ownership writes its data once, then tells the new owner to re-read it,
-- so whichever script saves last always holds everything. An inactive instance never writes on its own.
mp.register_script_message("webdav-browser-claim", function(who, how)
    if who == mp.get_script_name() then return end
    if how == "startup" and tostring(mp.get_script_name()) > tostring(who) then return end
    if MS.active then
        pcall(save_persistence, true)
        MS.active = false
        if browser_active then close_browser() end
        pcall(mp.commandv, "script-message-to", who, "webdav-browser-reload")
    end
end)
mp.register_script_message("webdav-browser-reload", function() if MS.active then reload_user_data() end end)

open_browser = function()
    if browser_active then HV.XA.dismiss(); return end
    pcall(HV.AX.offer_off)              -- the browser has its own keys (T among them)
    if HV.DR.open then HV.DR.close() end -- the setup check gives way to the browser
    local owner = MS.active
    MS.active = true
    reload_user_data(owner ~= false)
    mp.commandv("script-message", "webdav-browser-claim", mp.get_script_name())
    if o.url == "" then
        HV.say({ eyebrow = "WEBDAV-BROWSER", title = "Set url= in webdav-browser.conf", kind = "err" }, 4)
        return
    end

    MS.logo(false)
    MS.osc(true)
    browser_active = true
    MS.nodrag(true)
    if HV.TS.spec then HV.GL.hide("ts"); HV.TS.draw() end      -- a resting toast moves above the browser at once
    -- uosc draws its timeline / controls / top bar over the browser when the mouse comes near them and takes those
    -- clicks; they are switched off while the browser is open (a broadcast: nothing happens without uosc)
    mp.commandv("script-message", "disable-elements", mp.get_script_name(), "timeline,controls,volume,top_bar,window_border,idle_indicator,pause_indicator,buffering_indicator,audio_indicator")
    root_href = (o.start_path ~= "" and o.start_path or "/")
    tree = {}
    root_children = {}
    file_entries = {}
    listing_error = {}
    current_path = root_href
    focus_panel = "sidebar"
    sidebar_frac = want_sidebar_frac()
    sidebar_selected_index, selected_episode = 1, 1
    scroll_offset_folders, scroll_offset_episodes = 0, 0
    free_scroll.sidebar, free_scroll.episodes = false, false
    close_pending_for = nil
    search_active = false
    search_query = ""
    search_scope = nil
    search_results = {}

    MS.view = o.home_view and "home" or "browse"
    MS.from_home = o.home_view and true or false
    HV.mode, HV.tv.card, HV.saved, HV.pruned, HV.q, HV.qa, HV.typing = "home", nil, nil, false, nil, nil, false
    log_view(MS.view == "home" and "home" or "classic-list")
    HV.sig, HV.last_data, HV.r, HV.c, HV.top, HV.hover = nil, nil, 1, 1, 1, nil
    apply_background_blur()
    bind_all()
    load_root()
    render()
    IDX.maybe_autostart()
    if o.config_poll_secs and o.config_poll_secs > 0 then
        MS.conf_timer = mp.add_periodic_timer(o.config_poll_secs, function()
            if MS.conf_stamp() ~= MS.conf_sig then reload_config() end
        end)
    end
end

-- Key(s) that open/close the browser: open_key=ctrl+p   or several, separated by spaces/commas: open_key=ctrl+w ctrl+p
do
    local n = 0
    for key in (o.open_key_posters or "ctrl+p"):gmatch("[^%s,]+") do
        n = n + 1
        mp.add_forced_key_binding(key, n == 1 and "webdav_toggle" or ("webdav_toggle_" .. n), open_browser, { repeatable = false })
    end
    if n == 0 then mp.add_forced_key_binding("ctrl+p", "webdav_toggle", open_browser, { repeatable = false }) end
    -- gamepad / remote: the View button (or the remote's menu key) opens and closes the browser too
    if tostring(o.couch_mode):lower() ~= "no" and tostring(o.couch_mode):lower() ~= "false" then
        for key in tostring(o.couch_open_keys or ""):gmatch("[^%s,]+") do
            n = n + 1
            mp.add_forced_key_binding(key, "webdav_toggle_" .. n, function() HV.pad_used = true; open_browser() end, { repeatable = false })
        end
        if mp.get_property_native("input-gamepad") == false then pcall(mp.set_property, "input-gamepad", "yes") end
    end
end

-- ============================================================
-- PLAYBACK EVENTS
-- ============================================================
-- time-pos / duration are tracked continuously: by the time "end-file" fires mpv has often already
-- torn the values down, so reading them there returns nil.
mp.observe_property("time-pos", "number", function(_, v) if v then last_known_pos = v end end)
mp.observe_property("duration", "number", function(_, v) if v then last_known_dur = v end end)

-- Remember "what comes after this episode" in the history file itself, so Continue Watching does not depend on
-- the folder listing still being cached.
function MS.note_next_hint(href)
    local d = U.dirname(href)
    local nx = find_next_media_href(href)
    if nx then
        MS.hints[d] = { href = nx.href, name = nx.name, size = nx.size, ts = os.time() }
    elseif MS.hints[d] then
        MS.hints[d].ts = os.time()
    else
        MS.hints[d] = { ts = os.time() }
    end
end

-- Records progress for a file. Returns true if something was stored.
--   * past watched_threshold_pct / within watched_tail_secs of the end -> watched
--   * otherwise only counts as "in progress" after watch_min_secs AND watch_min_pct, so merely
--     opening a file for a few seconds doesn't leave an in-progress marker behind
local function record_progress(meta, pos, dur)
    if meta and meta.finished and dur then pos = dur end        -- left through the "Next episode" card: watched
    if not (meta and pos and dur and dur > 0) then return false end
    if meta.direct_url then return false end          -- a Real-Debrid link (add screen): not a library file, no history
    local pct = pos / dur * 100
    local prev = watch_history[meta.href]
    if pos >= dur - o.watched_tail_secs or pct >= o.watched_threshold_pct then
        if watched_set[meta.href] and not prev then return false end       -- watched already: nothing new
        watched_set[meta.href] = os.time()
        watch_history[meta.href] = nil
    elseif pos >= o.watch_min_secs and pct >= o.watch_min_pct then
        -- paused, or barely moved since the last snapshot: nothing new to keep (and no new "last played" either)
        if prev and prev.pos and math.abs(prev.pos - pos) < 5 and prev.duration == dur then return false end
        watch_history[meta.href] = {
            pos = pos, duration = dur, name = meta.name, dirpath = meta.dirpath, last_played = os.time(),
        }
    else
        return false
    end
    if watched_set[meta.href] then MS.note_next_hint(meta.href) end
    mark_continue_dirty()
    MS.prog_dirty = true
    return true
end

local function clear_start_over()
    mp.remove_key_binding("webdav_startover")
    if MS.resume_timer then MS.resume_timer:kill(); MS.resume_timer = nil end
end

-- mpv forgets the "path" of an entry that fails to open, so remember what it started loading.
mp.register_event("start-file", function()
    MS.starting_path = mp.get_property("path")
    MS.cur_path = nil
end)

-- ============================================================
-- PER-SHOW AUDIO / SUBTITLE LANGUAGE
-- ============================================================
-- Pick Japanese audio + English subtitles once in any Bleach episode and every Bleach episode starts that way.
-- Stored in the history file as tracks[show] = { a = audio language, s = subtitle language or "no" }.
-- The show is the nearest folder above the file that has a real title (season / disc folders are skipped).
MS.tracks = MS.tracks or {}
U.LANGS = { ja = "Japanese", jpn = "Japanese", en = "English", eng = "English", de = "German", ger = "German", deu = "German", fr = "French", fre = "French", fra = "French",
    es = "Spanish", spa = "Spanish", it = "Italian", ita = "Italian", pt = "Portuguese", por = "Portuguese", ko = "Korean", kor = "Korean", zh = "Chinese", chi = "Chinese", zho = "Chinese",
    ru = "Russian", rus = "Russian", ar = "Arabic", ara = "Arabic", hi = "Hindi", hin = "Hindi", nl = "Dutch", dut = "Dutch", nld = "Dutch", pl = "Polish", pol = "Polish", tr = "Turkish", tur = "Turkish",
    sv = "Swedish", swe = "Swedish", th = "Thai", tha = "Thai", id = "Indonesian", ind = "Indonesian", vi = "Vietnamese", vie = "Vietnamese", und = "unknown" }
function U.lang_name(code) return U.LANGS[tostring(code or ""):lower()] or tostring(code or "") end
function MS.show_key(href)
    if not href then return nil end
    local d = U.dirname(href)
    local rootn = tostring(root_href or "/"):gsub("/+$", "")
    for _ = 1, 4 do
        local dn = d:gsub("/+$", "")
        if dn == "" or dn == rootn then return nil end
        local name = U.basename(d)
        local fp = CT.parse_folder(name)
        local t = tostring((fp and fp.title) or name)
        local low = t:lower():gsub("^%s+", ""):gsub("%s+$", "")
        local generic = low == "" or low:match("^season") or low:match("^s%d+$") or low:match("^disc") or low:match("^dis[ck]%s*%d")
            or low:match("^specials?$") or low:match("^extras?$") or low:match("^%d+$") or low:match("^part%s*%d+$")
        if not generic then return (low:gsub("[^%w]+", "")) end
        d = U.dirname(d)
    end
    return nil
end

local function trk_lang(t)
    if type(t) ~= "table" then return nil end
    if t.lang and t.lang ~= "" then return tostring(t.lang):lower() end
    if t.title and t.title ~= "" then return "title:" .. tostring(t.title):lower() end
    return nil
end

-- Called from file-loaded: switch to the remembered languages (when this file has them).
function MS.tracks_apply(meta)
    MS.trk_loaded = mp.get_time()
    MS.trk_key = nil
    if not o.remember_tracks or not meta then return end
    local key = MS.show_key(meta.href)
    MS.trk_key = key
    local rec = key and MS.tracks[key]
    if type(rec) ~= "table" then return end
    local list = mp.get_property_native("track-list") or {}
    local function find(kind, want)
        local best
        for _, t in ipairs(list) do
            if t.type == kind and trk_lang(t) == want then
                local signs = tostring(t.title or ""):lower():find("sign") ~= nil
                if not best or (best.forced and not t.forced) or (best.signs and not signs) then
                    best = { id = t.id, forced = t.forced, signs = signs }
                end
            end
        end
        return best and best.id
    end
    local done = {}
    if rec.a then
        local id = find("audio", rec.a)
        if id and id ~= mp.get_property_number("aid") then mp.set_property_number("aid", id) end
        if id then done[#done + 1] = "audio " .. rec.a end
    end
    if rec.s == "no" then
        mp.set_property("sid", "no"); done[#done + 1] = "no subtitles"
    elseif rec.s then
        local id = find("sub", rec.s)
        if id and id ~= mp.get_property_number("sid") then mp.set_property_number("sid", id) end
        if id then done[#done + 1] = "subtitles " .. rec.s end
    end
    MS.trk_loaded = mp.get_time()
    if #done > 0 then msg.info("remembered tracks for " .. key .. ": " .. table.concat(done, ", ")) end
end

-- A track change by YOU (not mpv's own pick at load, not ours) is remembered for the show.
local function trk_changed(kind)
    if not o.remember_tracks or not now_playing or not MS.trk_key then return end
    if mp.get_time() - (MS.trk_loaded or 0) < 1.5 then return end
    local rec = MS.tracks[MS.trk_key] or {}
    if kind == "audio" then
        local l = trk_lang(mp.get_property_native("current-tracks/audio"))
        if not l or rec.a == l then return end
        rec.a = l
    else
        local sid = mp.get_property("sid")
        local l = (sid == "no" or sid == nil) and "no" or trk_lang(mp.get_property_native("current-tracks/sub"))
        if not l or rec.s == l then return end
        rec.s = l
    end
    rec.t = os.time()
    MS.tracks[MS.trk_key] = rec
    debounced_save_persistence(2)
end
mp.observe_property("aid", "string", function() trk_changed("audio") end)
mp.observe_property("sid", "string", function() trk_changed("sub") end)

mp.register_event("file-loaded", function()
    local path = mp.get_property("path")
    -- A blur filter must never outlive the browser: if one is still in the chain while the browser is
    -- closed (e.g. the previous file ended with the browser open), the new video would look soft/low-res.
    if not browser_active and blur_in_chain() then remove_background_blur() end
    if close_pending_for and (path == close_pending_for or (MS.close_t and mp.get_time() - MS.close_t < 45)) then
        close_pending_for, MS.close_t = nil, nil
        if browser_active then close_browser() end
    end
    clear_start_over()
    MS.cur_path = path
    if MS.fb.active and path ~= MS.fb.local_url then
        -- mpv moved on to the next episode by itself just as the failed one started downloading: hold the playlist
        -- there (the download plays in its place once enough has arrived)
        if not MS.fb.playing and MS.fb.pl_id and mp.get_time() - (MS.fb.t_start or 0) < 3 then
            mp.commandv("stop", "keep-playlist")
            return
        end
        MS.fb_stop(true)
    end
    local meta = path and pending_meta[path]
    if meta then meta.finished = nil end           -- (set when it was left through the Up next card)
    now_playing = meta
    pcall(MS.tracks_apply, meta)
    if meta and meta.name then status_line = "Playing: " .. meta.name end     -- also when the playlist moves on
    last_known_pos, last_known_dur = nil, nil
    if meta then
        retry_counts[meta.href] = nil              -- it opened fine: reset the retry budget
        loading_meta = nil
        local rec = watch_history[meta.href]
        if rec and rec.pos and rec.pos > o.resume_min_secs then
            pcall(mp.set_property_number, "time-pos", rec.pos)
            if o.resume_notice then
                local key = tostring(o.start_over_key or "b")
                HV.say_np({ eyebrow = "RESUMED AT", title = U.fmt_time(rec.pos), note = key:upper() .. "  start over",
                    note_rgb = TOAST.accent, key = "resume" }, o.resume_notice_secs, function(left)
                    -- the key works for as long as the pill says so
                    if MS.resume_timer then MS.resume_timer:kill() end
                    MS.resume_timer = mp.add_timeout(left, clear_start_over)
                end)
                safe_bind("webdav_startover", key, function()
                    MS.np_gen = (MS.np_gen or 0) + 1
                    clear_start_over()
                    pcall(mp.set_property_number, "time-pos", 0)
                    watch_history[meta.href] = nil
                    mark_continue_dirty()
                    HV.say({ eyebrow = "FROM THE START", title = "Starting from the beginning", key = "resume" }, 2.5)
                end, ONCE)
                MS.resume_timer = mp.add_timeout(o.resume_notice_secs + 3, clear_start_over)    -- until the pill shows
            end
        end
    end
end)

mp.register_event("end-file", function(event)
    clear_start_over()
    MS.np_gen = (MS.np_gen or 0) + 1        -- a resume pill still waiting belongs to this file
    local meta = now_playing

    local fb = MS.fb
    local ended = MS.cur_path or MS.starting_path
    MS.cur_path = nil
    local was_local = fb.active and fb.local_url and ended == fb.local_url
    if was_local then
        -- The growing local file ran dry (download slower than playback) or ended: reopen it where we were.
        if not fb.done and (fb.restarts or 0) < 30 and event.reason ~= "quit" and event.reason ~= "stop" then
            mp.add_timeout(2, function() if MS.fb == fb and fb.active and not fb.done then MS.fb_play() end end)
        end
    elseif event.reason == "error" then
        -- Works for files that failed to OPEN too (file-loaded never fired, so now_playing is nil):
        -- fall back to the entry mpv was loading.
        local failed = meta
        if not failed then
            failed = ended and pending_meta[ended]
            -- the file still being opened (a retry): only when it is the one that failed
            if not failed and loading_meta and ended and ended == file_stream_url(loading_meta.href) then failed = loading_meta end
        end
        if failed and not failed.direct_url then          -- (a Real-Debrid link has no WebDAV address to retry)
            local attempts = (retry_counts[failed.href] or 0) + 1
            retry_counts[failed.href] = attempts
            if o.fallback_download and attempts >= (tonumber(o.fallback_after_failures) or 1) and MS.fb_start(failed, "stream failed") then
                retry_counts[failed.href] = nil
                loading_meta = nil
                -- mpv goes on to the next episode by itself, and that used to end this download: the playlist waits here
                MS.fb.pl_id, MS.fb.t_start = event.playlist_entry_id, mp.get_time()
                if (mp.get_property_number("playlist-count") or 0) > 1 then mp.commandv("stop", "keep-playlist") end
                HV.say({ eyebrow = "STREAMING FAILED", title = "Downloading the file instead", kind = "wait" }, 4)
            elseif attempts <= o.max_retries then
                local retry_url = file_stream_url(failed.href)
                pending_meta[retry_url] = failed
                loading_meta = failed
                HV.say({ eyebrow = string.format("RETRYING  %d/%d", attempts, o.max_retries), title = failed.name, kind = "wait", key = "retry" }, 3)
                mp.add_timeout(o.retry_delay, function() queue_load(retry_url, "insert-next-play", failed.name) end)
            else
                retry_counts[failed.href] = nil
                loading_meta = nil
                HV.say({ eyebrow = "COULDN'T PLAY", title = failed.name, kind = "err", key = "retry",
                    extra = string.format("tried %d times%s", (tonumber(o.max_retries) or 0) + 1, event.file_error and ("  ·  " .. tostring(event.file_error)) or ""),
                    note = U.kname("doctor") .. "  setup check", note_rgb = TOAST.warn }, 7)
            end
        end
    end

    if meta then
        if not MS.active then reload_user_data() end          -- never overwrite the owner's newer data with ours
        if record_progress(meta, last_known_pos, last_known_dur) or MS.prog_dirty then
            save_persistence(true)
            if not MS.active then pcall(mp.commandv, "script-message", "webdav-browser-reload") end
        end
    end

    now_playing = nil
    last_known_pos, last_known_dur = nil, nil
    if browser_active then render() end
end)

-- Periodic watch-progress snapshot: memory every 15 s, the disk at most once a minute (and at once when a file ends
-- or mpv quits). Paused, nothing changes, so nothing is written.
mp.add_periodic_timer(15, function()
    if not (now_playing and MS.active) then return end
    record_progress(now_playing, last_known_pos, last_known_dur)
    if MS.prog_dirty and os.time() - (persist_status.last_save or 0) >= 55 then save_persistence() end
end)

-- One-ahead prefetch chain: buffers the NEXT episode once playback crosses prefetch_threshold_pct,
-- then repeats for the episode after that. The next file is inserted directly after the current one.
mp.add_periodic_timer(o.prefetch_check_interval_secs or 5, function()
    if not now_playing or not now_playing.next_item or now_playing.next_queued then return end

    local pos, dur = last_known_pos, last_known_dur        -- watched values (a direct read waits on a busy mpv)
    if not (pos and dur and dur > 0) then return end

    local threshold = math.max(0, math.min(100, tonumber(o.prefetch_threshold_pct) or 75)) / 100
    if (pos / dur) < threshold then
        local fully_buffered = false
        if o.prefetch_on_buffered then
            local ok, st = pcall(mp.get_property_native, "demuxer-cache-state")
            fully_buffered = ok and type(st) == "table" and st["eof-cached"] == true
        end
        if not fully_buffered then return end
    end

    now_playing.next_queued = true
    local next_item = now_playing.next_item
    local next_url = file_stream_url(next_item.href)

    local chained_next = find_next_media_href(next_item.href)
    pending_meta[next_url] = {
        href = next_item.href, name = next_item.name, dirpath = U.dirname(next_item.href),
        next_queued = false,
        next_item = (o.autoplay_next and chained_next) and { href = chained_next.href, name = chained_next.name } or nil,
    }

    queue_next(next_url, next_item.name)
    status_line = string.format("Buffering next: %s", next_item.name)
    if browser_active then render() end
end)

mp.add_periodic_timer(0.12, function()
    if browser_active and MS.view ~= "home" and (is_loading or IDX.running) then
        spinner_idx = (spinner_idx % #spinner_frames) + 1
        render()
    end
end)

-- Every 3 s while the browser is open: re-list the folders you are looking at that are still filling up, and give
-- each one a second look 3 s after its first listing this session (that is how a growing folder is noticed).
MS.inview = MS.inview or function() return { current_path } end
mp.add_periodic_timer(3, function()
    if not browser_active then return end
    local ok, list = pcall(MS.inview)
    if not ok or type(list) ~= "table" then return end
    local now = os.time()
    for _, href in ipairs(list) do
        local c = href and find_cached_dir(href)
        if c and type(c.entries) == "table" and not MS.inflight[href] then
            local again = MS.grow[href] ~= nil
            if not again and (MS.seen[href] or 0) == 1 and now - (c.ts or now) >= 3 then again = true end
            if again then fetch_listing(href, { silent = true }) end
        end
    end
    render()
end)


-- ============================================================
-- "NEXT EPISODE IN 10..." CARD
-- ============================================================
-- A card with the next episode's still (poster edition) and name, counting down while the next playlist entry is one
-- of ours. The countdown follows the playback position, so pausing pauses it. Esc keeps watching, Enter plays now.
-- When it is shown depends on the file's chapters and on whether a chapter-skip script is installed:
--   * credits: the card appears when the trailing ED / Ending / Credits / Preview chapters start; at 0 the next episode
--              starts (the rest of the credits is skipped and the episode counts as watched).
--   * before:  a skip script (op-ed-pv-skip and the like) jumps over those chapters - straight to the next file when they
--              are the last ones - so the countdown runs in the last seconds BEFORE them and ends where they begin.
--   * no named chapters: the last next_episode_secs of the file.
MS.ep_meta = MS.ep_meta or {}
local NX = { id = 60, shown = nil, dismissed = nil, ov = nil, bound = false }

-- Chapter names a skip script skips (the op-ed-pv-skip lists, plus "credits / ending / outro / preview" anywhere).
NX.EXACT = {}
for _, t in ipairs({ "op", "opening", "opening theme", " - op", "recap", "title", "#prologue", "intermission", "eye-catchers",
    "ed", "ending", " - ed", "ending credits", "credits", "ending theme", "pv", "preview", "next episode preview",
    "next ep. preview", "nextp ep. preview", "next", "next time", "endcard", " - ed card", "ed+cast", "cast" }) do NX.EXACT[t] = true end
NX.START = { "opening theme", "recap", "title", "eye-catchers", "intermission", "#prologue", "op by ", "ed song - ", "ending theme",
    "next episode preview" }
NX.END = { " (opening theme)", " (#prologue)", " (title)", " (eye-catchers)", " (intermission)", " (recap)", " (ending theme)",
    " (opening)", " - opening", " - op", " (ending)", "- ending", " - ed", " preview", " (next episode preview)" }
function NX.tail_name(title)
    local t = tostring(title or ""):lower()
    if NX.EXACT[t] then return true end
    for _, p in ipairs(NX.START) do if t:sub(1, #p) == p then return true end end
    for _, p in ipairs(NX.END) do if #t >= #p and t:sub(-#p) == p then return true end end
    return t:find("credits", 1, true) or t:find("ending", 1, true) or t:find("outro", 1, true) or t:find("preview", 1, true)
        or t:match("^ed[%s%d:%-]") ~= nil
end

-- Is a chapter-skip script loaded? (its key bindings show up in mpv's input-bindings list)
function NX.skipper()
    if NX.sk_t and mp.get_time() - NX.sk_t < 60 then return NX.sk end
    local ok, list = pcall(mp.get_property_native, "input-bindings")
    local found = false
    for _, b in ipairs(ok and type(list) == "table" and list or {}) do
        local c = (tostring(b.cmd or "") .. " " .. tostring(b.section or "")):lower()
        if c:find("op_ed_pv_skip", 1, true) or c:find("op-ed-pv-skip", 1, true) or c:find("chapterskip", 1, true)
            or c:find("chapter_skip", 1, true) or c:find("skip_intro", 1, true) or c:find("skipintro", 1, true)
            or c:find("autoskip", 1, true) then found = true; break end
    end
    NX.sk, NX.sk_t = found, mp.get_time()
    return found
end

-- Start of the trailing ED / credits / preview chapters (nil when the file has none in its second half).
function NX.tail_start(dur, skipper)
    local list = MS.prop("chapter-list")
    if type(list) ~= "table" then list = {} end
    local n = #list
    if n < 2 then return nil end
    local named = false
    for _, ch in ipairs(list) do
        local t = tostring(ch.title or "")
        if t ~= "" and not t:match("^Chapter ") then named = true; break end
    end
    local start
    if named then
        for i = n, 1, -1 do
            if NX.tail_name(list[i].title) and (list[i].time or 0) > dur * 0.5 then start = list[i].time else break end
        end
    elseif skipper then
        -- unnamed chapters: the skip script goes by length (PV 14-26 s as the last chapter, OP/ED 88-102 s)
        for i = n, math.max(1, n - 2), -1 do
            local len = ((list[i + 1] and list[i + 1].time) or dur) - (list[i].time or 0)
            local pv = (i == n and len >= 14 and len <= 26)
            if (pv or (len >= 88 and len <= 102)) and (list[i].time or 0) > dur * 0.5 then start = list[i].time else break end
        end
    end
    return start
end

function NX.next_entry()
    local pos = MS.prop("playlist-pos")
    local pl = MS.prop("playlist")
    if not (pos and type(pl) == "table") then return nil end
    local nx = pl[pos + 2]           -- playlist-pos is 0-based, Lua tables 1-based
    return nx and pending_meta[nx.filename]
end

function NX.hide()
    NX.last = nil
    if NX.shown then
        if NX.ov then NX.ov.data = ""; NX.ov:update() end
        pcall(mp.commandv, "overlay-remove", tostring(NX.id))
        NX.shown, NX.bmp = nil, nil
        HV.GL.hide("nx")
    end
    if NX.bound then
        for _, k in ipairs(NX.keys) do pcall(mp.remove_key_binding, "webdav_nx_" .. k) end
        NX.bound = false
    end
end

function NX.next()
    NX.hide()
    if now_playing then now_playing.finished = true end
    mp.command("playlist-next")
end

NX.keys = { "ESC", "ENTER", "KP_ENTER", "GAMEPAD_ACTION_DOWN", "GAMEPAD_ACTION_RIGHT", "s", "GAMEPAD_ACTION_UP" }
-- S on the card: skip the credits - to the preview when the file has one, else straight to the next episode
function NX.skip_credits()
    local list = mp.get_property_native("chapter-list") or {}
    local dur = mp.get_property_number("duration") or 0
    local pos = mp.get_property_number("time-pos") or 0
    local n = #list
    -- the last chapter a preview (14-26 s, or named so) after the current one: jump there
    if n >= 2 then
        local last = list[n]
        local len = dur - (last.time or 0)
        local nm = tostring(last.title or ""):lower()
        if (last.time or 0) > pos + 1 and (nm:find("preview", 1, true) or (len >= 14 and len <= 26)) then
            mp.commandv("seek", last.time, "absolute")
            NX.dismissed = now_playing and now_playing.href
            NX.hide()
            return
        end
    end
    NX.next()
end
function NX.bind(href)
    if NX.bound then return end
    NX.bound = true
    local function stay() NX.dismissed = href; NX.hide() end
    for _, k in ipairs(NX.keys) do
        local fn = (k == "ESC" or k == "GAMEPAD_ACTION_RIGHT") and stay or ((k == "s" or k == "GAMEPAD_ACTION_UP") and NX.skip_credits or NX.next)
        mp.add_forced_key_binding(k, "webdav_nx_" .. k, fn)
    end
end

-- ---- skip intro: a small card while a named OP chapter plays (S jumps past it) - unless a skip script is doing it ----
NX.intro = { on = false }
function NX.intro_hide()
    local I = NX.intro
    if not I.on then return end
    I.on = false
    pcall(mp.remove_key_binding, "webdav_nx_intro")
    pcall(mp.remove_key_binding, "webdav_nx_intro_pad")
    HV.TS.hide()
end
function NX.intro_skip()
    local I = NX.intro
    if I.on and I.to then mp.commandv("seek", I.to, "absolute") end
    NX.intro_hide()
end
mp.add_periodic_timer(0.5, function()
    local I = NX.intro
    if not o.skip_intro_card or not now_playing or browser_active or NX.shown then return NX.intro_hide() end
    local list, dur = MS.P["chapter-list"], last_known_dur
    if not (type(list) == "table" and #list > 0 and dur and dur > 120) then return NX.intro_hide() end
    -- the file's opening chapters, worked out once per chapter list
    if I.list ~= list or I.dur ~= dur then
        I.list, I.dur, I.ops = list, dur, {}
        for i, ch in ipairs(list) do
            local t0, t1 = ch.time or 0, (list[i + 1] and list[i + 1].time) or dur
            local nm = tostring(ch.title or ""):lower()
            local is_op = (nm == "op" or nm == "opening" or nm:find("opening", 1, true) or nm:match("^op[%s%d:%-]") or nm:find(" - op", 1, true) or nm:find("intro", 1, true)) and true or false
            if is_op and t0 < dur * 0.4 and t1 - t0 >= 45 and t1 - t0 <= 150 then I.ops[#I.ops + 1] = { t0 = t0, t1 = t1 } end
        end
    end
    if #I.ops == 0 then return NX.intro_hide() end
    local pos = last_known_pos
    local hit = nil
    for _, r in ipairs(I.ops) do if pos and pos >= r.t0 and pos < r.t1 - 1 then hit = r; break end end
    if not hit or NX.skipper() then return NX.intro_hide() end
    if I.on and I.to == hit.t1 then
        if not HV.TS.spec then HV.TS.show({ eyebrow = "INTRO", title = "Skip intro", note = "S", pos = o.next_card_position }, hit.t1 - pos + 0.5) end
        return
    end
    I.on, I.to = true, hit.t1
    mp.add_forced_key_binding("s", "webdav_nx_intro", NX.intro_skip)
    mp.add_forced_key_binding("GAMEPAD_ACTION_UP", "webdav_nx_intro_pad", NX.intro_skip)
    HV.TS.show({ eyebrow = "INTRO", title = "Skip intro", note = "S", pos = o.next_card_position }, hit.t1 - pos + 0.5)
end)

-- ---- glass: the video behind a card, blurred (vo=gpu-next; elsewhere the card is simply tinted darker) ----
-- A two-pass blur shader runs only inside the card's rounded rectangle and only while a card is on screen (//!WHEN).
-- The card moves its rectangle with glsl-shader-opts (live, no reload). Your own glsl-shaders are kept.
HV.GL = { owner = nil, sig = nil, dims = {}, slots = {}, N = 4, k = 36 }
-- the tint over the glass: one look for every glass card (the blurred video under it, else the same card darker)
HV.GL.TINT, HV.GL.SOLID = 46, 86
mp.observe_property("osd-dimensions", "native", function(_, v) if type(v) == "table" then HV.GL.dims = v end end)
HV.GL.FILE = "glass_v2.glsl"          -- (26.11: up to 4 cards blurred at once; v1 had one)
HV.GL.SHADER = [==[
// webdav-browser glass: blurs the video behind its on-screen cards (next episode, now playing, toasts, the
// help sheet...) - up to 4 at once, nothing else. Written by webdav-browser-posters.lua; both passes are skipped
// while no card is shown.
//!PARAM wb_on
//!TYPE DYNAMIC float
//!MINIMUM 0.0
//!MAXIMUM 1.0
0.0

//!PARAM wb_0x0
//!TYPE DYNAMIC float
//!MINIMUM -1.0
//!MAXIMUM 2.0
-1.0

//!PARAM wb_0y0
//!TYPE DYNAMIC float
//!MINIMUM -1.0
//!MAXIMUM 2.0
-1.0

//!PARAM wb_0x1
//!TYPE DYNAMIC float
//!MINIMUM -1.0
//!MAXIMUM 2.0
-1.0

//!PARAM wb_0y1
//!TYPE DYNAMIC float
//!MINIMUM -1.0
//!MAXIMUM 2.0
-1.0

//!PARAM wb_0r
//!TYPE DYNAMIC float
//!MINIMUM 0.0
//!MAXIMUM 500.0
0.0

//!PARAM wb_1x0
//!TYPE DYNAMIC float
//!MINIMUM -1.0
//!MAXIMUM 2.0
-1.0

//!PARAM wb_1y0
//!TYPE DYNAMIC float
//!MINIMUM -1.0
//!MAXIMUM 2.0
-1.0

//!PARAM wb_1x1
//!TYPE DYNAMIC float
//!MINIMUM -1.0
//!MAXIMUM 2.0
-1.0

//!PARAM wb_1y1
//!TYPE DYNAMIC float
//!MINIMUM -1.0
//!MAXIMUM 2.0
-1.0

//!PARAM wb_1r
//!TYPE DYNAMIC float
//!MINIMUM 0.0
//!MAXIMUM 500.0
0.0

//!PARAM wb_2x0
//!TYPE DYNAMIC float
//!MINIMUM -1.0
//!MAXIMUM 2.0
-1.0

//!PARAM wb_2y0
//!TYPE DYNAMIC float
//!MINIMUM -1.0
//!MAXIMUM 2.0
-1.0

//!PARAM wb_2x1
//!TYPE DYNAMIC float
//!MINIMUM -1.0
//!MAXIMUM 2.0
-1.0

//!PARAM wb_2y1
//!TYPE DYNAMIC float
//!MINIMUM -1.0
//!MAXIMUM 2.0
-1.0

//!PARAM wb_2r
//!TYPE DYNAMIC float
//!MINIMUM 0.0
//!MAXIMUM 500.0
0.0

//!PARAM wb_3x0
//!TYPE DYNAMIC float
//!MINIMUM -1.0
//!MAXIMUM 2.0
-1.0

//!PARAM wb_3y0
//!TYPE DYNAMIC float
//!MINIMUM -1.0
//!MAXIMUM 2.0
-1.0

//!PARAM wb_3x1
//!TYPE DYNAMIC float
//!MINIMUM -1.0
//!MAXIMUM 2.0
-1.0

//!PARAM wb_3y1
//!TYPE DYNAMIC float
//!MINIMUM -1.0
//!MAXIMUM 2.0
-1.0

//!PARAM wb_3r
//!TYPE DYNAMIC float
//!MINIMUM 0.0
//!MAXIMUM 500.0
0.0

//!PARAM wb_k
//!TYPE DYNAMIC float
//!MINIMUM 1.0
//!MAXIMUM 200.0
36.0

//!PARAM wb_sat
//!TYPE DYNAMIC float
//!MINIMUM 0.0
//!MAXIMUM 3.0
1.4

//!HOOK OUTPUT
//!BIND HOOKED
//!SAVE WBGLASS
//!WHEN wb_on
//!DESC webdav-browser glass (horizontal)
bool wb_near(vec2 p, vec2 a, vec2 b) {
    return !(p.y < a.y - wb_k - 2.0 || p.y > b.y + wb_k + 2.0 || p.x < a.x - 2.0 || p.x > b.x + 2.0);
}
vec4 hook() {
    vec2 p = HOOKED_pos * HOOKED_size;
    if (!(wb_near(p, vec2(wb_0x0, wb_0y0) * HOOKED_size, vec2(wb_0x1, wb_0y1) * HOOKED_size) ||
        wb_near(p, vec2(wb_1x0, wb_1y0) * HOOKED_size, vec2(wb_1x1, wb_1y1) * HOOKED_size) ||
        wb_near(p, vec2(wb_2x0, wb_2y0) * HOOKED_size, vec2(wb_2x1, wb_2y1) * HOOKED_size) ||
        wb_near(p, vec2(wb_3x0, wb_3y0) * HOOKED_size, vec2(wb_3x1, wb_3y1) * HOOKED_size)))
        return HOOKED_tex(HOOKED_pos);
    float s = wb_k / 12.0;
    vec4 acc = vec4(0.0);
    float wsum = 0.0;
    for (int i = -12; i <= 12; i++) {
        float x = float(i);
        float w = exp(-x * x / 50.0);
        acc += HOOKED_tex(HOOKED_pos + vec2(x * s, 0.0) * HOOKED_pt) * w;
        wsum += w;
    }
    return acc / wsum;
}

//!HOOK OUTPUT
//!BIND HOOKED
//!BIND WBGLASS
//!WHEN wb_on
//!DESC webdav-browser glass (vertical)
float wb_sdf(vec2 p, vec2 a, vec2 b, float r) {
    vec2 q = abs(p - (a + b) * 0.5) - (b - a) * 0.5 + r;
    return length(max(q, 0.0)) + min(max(q.x, q.y), 0.0) - r;
}
vec4 hook() {
    vec4 c = HOOKED_tex(HOOKED_pos);
    vec2 p = HOOKED_pos * HOOKED_size;
    float d = 1.0e9;
    d = min(d, wb_sdf(p, vec2(wb_0x0, wb_0y0) * HOOKED_size, vec2(wb_0x1, wb_0y1) * HOOKED_size, wb_0r));
    d = min(d, wb_sdf(p, vec2(wb_1x0, wb_1y0) * HOOKED_size, vec2(wb_1x1, wb_1y1) * HOOKED_size, wb_1r));
    d = min(d, wb_sdf(p, vec2(wb_2x0, wb_2y0) * HOOKED_size, vec2(wb_2x1, wb_2y1) * HOOKED_size, wb_2r));
    d = min(d, wb_sdf(p, vec2(wb_3x0, wb_3y0) * HOOKED_size, vec2(wb_3x1, wb_3y1) * HOOKED_size, wb_3r));
    if (d > 1.0)
        return c;
    float s = wb_k / 12.0;
    vec4 acc = vec4(0.0);
    float wsum = 0.0;
    for (int i = -12; i <= 12; i++) {
        float y = float(i);
        float w = exp(-y * y / 50.0);
        acc += WBGLASS_tex(WBGLASS_pos + vec2(0.0, y * s) * WBGLASS_pt) * w;
        wsum += w;
    }
    vec3 bl = (acc / wsum).rgb;
    float l = dot(bl, vec3(0.2126, 0.7152, 0.0722));
    bl = max(mix(vec3(l), bl, wb_sat), 0.0);
    return vec4(mix(c.rgb, bl, clamp(0.5 - d, 0.0, 1.0)), c.a);
}
]==]

-- the shader is in place (written once to the cache folder, appended to glsl-shaders): true / false
function HV.GL.ready()
    local G = HV.GL
    if not o.glass_blur or G.bad then return false end
    if MS.prop("current-vo") ~= "gpu-next" then return false end
    -- still in the list? (a shader-switching script may have replaced glsl-shaders: then it is added again)
    local list = MS.prop("glsl-shaders")
    if G.loaded and G.list == list then return true end
    for _, s in ipairs(type(list) == "table" and list or {}) do
        if tostring(s):find(G.FILE, 1, true) then G.loaded, G.list = true, list; return true end
    end
    local path = PS.dir() .. "/" .. G.FILE
    if not G.written and not utils.file_info(path) then
        PS.mkdir()
        local f = io.open(path, "wb")
        if not f then G.bad = true; return false end
        f:write(G.SHADER); f:close()
    end
    G.written = true
    if G.loaded then G.sig = nil end       -- it was taken out: back in, and its values set again
    G.loaded = mp.commandv("change-list", "glsl-shaders", "append", path) and true or false
    if not G.loaded then G.bad = true; msg.warn("glass: could not load the blur shader " .. path) end
    MS.P["glsl-shaders"], MS.Pq["glsl-shaders"], G.list = nil, nil, nil     -- the next look reads the new list once (it holds the shader)
    return G.loaded
end
-- blur behind window rectangle x1,y1-x2,y2 (corner radius r) for this card (owner): true when the blur is on. Each
-- card has a slot of its own (4), so a toast, the Now playing card and the help sheet are all glass at the same time
function HV.GL.show(owner, x1, y1, x2, y2, r, S)
    local G = HV.GL
    if not G.ready() then return false end
    local d = G.dims
    local ml, mt = tonumber(d.ml) or 0, tonumber(d.mt) or 0
    local vw = (tonumber(d.w) or 0) - ml - (tonumber(d.mr) or 0)
    local vh = (tonumber(d.h) or 0) - mt - (tonumber(d.mb) or 0)
    if vw < 16 or vh < 16 then G.hide(owner); return false end
    local sl = G.slots[owner]
    if not sl then
        local used = {}
        for _, v in pairs(G.slots) do used[v.i] = true end
        local free
        for i = 0, G.N - 1 do if not used[i] then free = i; break end end
        if not free then return false end           -- (all slots taken: this card is tinted instead)
        sl = { i = free }
        G.slots[owner] = sl
    end
    sl.v = { (x1 - ml) / vw, (y1 - mt) / vh, (x2 - ml) / vw, (y2 - mt) / vh, r }
    sl.k = math.max(8, 30 * (S or 1))
    G.owner = owner
    G.push()
    return true
end
-- every slot's values in ONE write: each write of glsl-shader-opts makes mpv reset its renderer (a dropped frame,
-- HDR peak detection starting over), so the cards also only move it when they come to rest
function HV.GL.push()
    local G = HV.GL
    local by, k = {}, 8
    for _, v in pairs(G.slots) do by[v.i] = v; k = math.max(k, v.k or 8) end
    local parts = {}
    for i = 0, G.N - 1 do
        local v = by[i] and by[i].v or { -1, -1, -1, -1, 0 }
        parts[#parts + 1] = string.format("wb_%dx0=%.4f,wb_%dy0=%.4f,wb_%dx1=%.4f,wb_%dy1=%.4f,wb_%dr=%.4f", i, v[1], i, v[2], i, v[3], i, v[4], i, v[5])
    end
    parts[#parts + 1] = string.format("wb_k=%.4f,wb_sat=1.4500,wb_on=1.0000", k)
    local sig = table.concat(parts, ",")
    if sig ~= G.sig then
        G.sig = sig
        G.put(sig)
    end
end
-- several values in one write: "add" takes them all on mpv 0.41; older versions warn about it in the terminal, so there
-- the whole list (anyone else's values kept) is set in one go instead
function HV.GL.put(s)
    local G = HV.GL
    if G.multi == nil then
        local a, b = tostring(mp.get_property("mpv-version") or ""):match("(%d+)%.(%d+)")
        G.multi = (tonumber(a) or 0) > 0 or (tonumber(b) or 0) >= 41
    end
    if G.multi then mp.commandv("change-list", "glsl-shader-opts", "add", s); return end
    local cur = mp.get_property_native("glsl-shader-opts")
    if type(cur) ~= "table" then cur = {} end
    for k, v in s:gmatch("([%w_]+)=([^,]+)") do cur[k] = v end
    mp.set_property_native("glsl-shader-opts", cur)
end
function HV.GL.hide(owner)
    local G = HV.GL
    if owner == nil or not G.slots[owner] then return end
    G.slots[owner] = nil
    if next(G.slots) == nil then
        G.owner, G.sig = nil, nil
        G.put("wb_on=0")
    else
        if G.owner == owner then G.owner = next(G.slots) end
        G.push()
    end
end
-- the card body: a soft shadow, tinted glass and a hairline edge
function HV.GL.frame(ev, x1, y1, x2, y2, rad, S, glass)
    local b = math.max(6, math.floor(14 * S))
    ev[#ev + 1] = string.format("{\\an7\\pos(0,0)\\bord0\\shad0\\blur%d\\1c&H000000&\\1a%s\\3a&HFF&\\p1}%s{\\p0}",
        b, U.ass_alpha(glass and 22 or 30), D.rounded_path(x1, y1 + b * 0.35, x2, y2 + b * 0.6, rad))
    ev[#ev + 1] = D.ev_rect(x1, y1, x2, y2, TOAST.fill, glass and HV.GL.TINT or HV.GL.SOLID, TOAST.edge, 17, math.max(1, math.floor(S + 0.5)), rad)
end
-- text in white at an opacity (0-100)
function HV.GL.txt(x, y, an, fs, op, bold, s)
    return D.ev_text(x, y, an, string.format("\\fs%d\\b%d\\c%s\\1a%s", fs, bold and 1 or 0, U.ass_color(TOAST.text), U.ass_alpha(op)), s)
end
-- a ring (frac 0-1 of it, clockwise from the top) for the countdown
function HV.GL.arc(cx, cy, r, th, frac, rgb, op)
    frac = math.max(0, math.min(0.9999, frac))
    if frac <= 0 then return "" end
    local n = math.max(6, math.ceil(72 * frac))
    local outer, inner = {}, {}
    for i = 0, n do
        local a = -math.pi / 2 + 2 * math.pi * frac * i / n
        local c, s = math.cos(a), math.sin(a)
        outer[#outer + 1] = string.format("%d %d", D.rd(cx + r * c), D.rd(cy + r * s))
        inner[#inner + 1] = string.format("%d %d", D.rd(cx + (r - th) * c), D.rd(cy + (r - th) * s))
    end
    local rev = {}
    for i = #inner, 1, -1 do rev[#rev + 1] = inner[i] end
    local path = "m " .. outer[1] .. " l " .. table.concat(outer, " ", 2) .. " " .. table.concat(rev, " ")
    return string.format("{\\an7\\pos(0,0)\\bord0\\shad0\\blur0.6\\1c%s\\1a%s\\3a&HFF&\\p1}%s{\\p0}", U.ass_color(rgb), U.ass_alpha(op), path)
end

-- Label ("S02E28"), episode name and show for a card: the title page's TMDB data when it was opened, else what the
-- Continue Watching lookup finds (TMDB still or the show's backdrop, episode name) - before, a card for an episode
-- started from Continue Watching had no picture and only the show's name.
function NX.art(meta)
    local em = MS.ep_meta[meta.href]
    if em and em.still and em.key then return em end
    NX.res = NX.res or {}
    local r = NX.res[meta.href]
    if r and (r.still or mp.get_time() - r.t < 2) then return r end
    local e = { href = meta.href, name = meta.name, dirpath = meta.dirpath or U.dirname(meta.href) }
    local ok, c = pcall(HV.card_for_resume, e)
    if not ok or type(c) ~= "table" then return em end
    pcall(HV.cw_still, c, e)
    r = { t = mp.get_time(), key = c.still and c.key or nil, still = c.still, name = c.ep_name, show = c.title,
          label = em and em.label }
    if c.need then pcall(TV.ensure_season, c.need.entry, c.need.s) end      -- the season's names and stills, for next time
    NX.res[meta.href] = r
    return r
end
function NX.info(meta, art)
    local em = MS.ep_meta[meta.href] or {}
    local cp = CT.parse(meta.name or "")
    local name = em.name or (art and art.name) or (cp and cp.ep)
    local show = em.show or (art and art.show) or (cp and cp.title)
    return em.label or (cp and cp.se), name, show
end
-- the still as a ready bitmap (nil while it downloads / converts)
function NX.img(art, sw, sh)
    if not (art and art.still and art.key and PS.enabled()) then return nil end
    local st = HV.items[art.key]
    if not st then st = { state = "new", bgra = {}, cq = {} }; HV.items[art.key] = st end
    TV.pump_still({ key = art.key, still = art.still, dw = sw, dh = sh }, st, nil)
    HV.convert_pump()
    return st.bgra[HV.skey(sw, sh)]
end

-- poster edition: the card's picture size (16:9)
function HV.next_card_size(h)
    local sh = math.floor(64 * HV.step_h(h or 1080) / 1080 + 0.5)
    return math.floor(sh * 16 / 9 + 0.5), sh
end
function NX.size()
    local _, oh = U.canvas_size()
    return HV.next_card_size(oh or 1080)
end

function NX.fit(s, max_px, fs, bold) return HV.fitw(s, max_px, fs, bold) end
-- Where a card or toast sits (next_card_position, now_playing_position, startup_toast_position): top-left, top,
-- top-right, bottom-left, bottom, bottom-right ("top-center" / "center" also work). Bottom keeps clear of the timeline.
HV.POS = { ["top-left"] = true, top = true, ["top-right"] = true, ["bottom-left"] = true, bottom = true, ["bottom-right"] = true, center = true }
function HV.pos_name(v, def)
    v = tostring(v or ""):lower():gsub("^%s+", ""):gsub("%s+$", ""):gsub("[%s_]+", "-"):gsub("centre", "center")
    v = v:gsub("^top%-center$", "top"):gsub("^bottom%-center$", "bottom"):gsub("^middle$", "center")
    return HV.POS[v] and v or def
end
function HV.corner(pos, cw, ch, S, def)
    local ww, wh = U.canvas_size()
    pos = HV.pos_name(pos, def)
    local mx, mt, mb = math.floor(36 * S), math.floor(40 * S), math.floor(108 * S)
    local x = pos:find("left") and mx or (pos:find("right") and (ww - cw - mx)) or math.floor((ww - cw) / 2)
    local y = pos:find("^top") and mt or ((pos == "center") and math.floor((wh - ch) / 2)) or (wh - ch - mb)
    return x, y, pos
end
-- A compact glass card: [still] UP NEXT · S01E04 / episode name / keys, and a ring counting down.
-- Shared with the now-playing card (HV.NP): which = "nx" | "np"; spec = { eyebrow, title, sub, frac, count, x = "left"|"right" }
function NX.card(which, spec, art, sw, sh, f)
    local ww, wh = U.canvas_size()
    if not ww or ww <= 0 then return end
    local S = wh / 1080
    local pad = math.floor(10 * S + 0.5)
    local gap = math.floor(12 * S + 0.5)
    local rad = math.floor(16 * S + 0.5)
    local fs1, fs2, fs3 = math.max(11, math.floor(12 * S)), math.max(14, math.floor(18 * S)), math.max(11, math.floor(13 * S))
    local with_img = art ~= nil and art.still ~= nil
    local rr = spec.frac and math.floor(19 * S + 0.5) or 0
    -- the text column is as wide as its longest line (within limits), so a short title leaves no empty glass
    local fsp = math.max(1, math.floor(S + 0.5))
    local w_title = HV.AX.tw(spec.title or "", fs2, true)
    local w_sub = (spec.sub and spec.sub ~= "") and HV.AX.tw(spec.sub, fs3) or 0
    local need = math.max(w_title, HV.AX.tw(spec.eyebrow or "", fs1, true) + U.utf8_len(spec.eyebrow or "") * fsp, w_sub)
    local tw = math.floor(math.max(150 * S, math.min((with_img and 300 or 460) * S, need + 6 * S)))
    local title = NX.fit(spec.title, tw, fs2, true)
    local sub = NX.fit(spec.sub, tw, fs3, false)
    local ch = sh + 2 * pad
    local cw = pad + (with_img and (sw + gap) or math.floor(6 * S)) + tw + (rr > 0 and (gap + 2 * rr) or 0) + pad + math.floor(4 * S)
    local x1, y1 = HV.corner(spec.pos, cw, ch, S, (spec.x == "left") and "bottom-left" or "bottom-right")
    local x2, y2 = x1 + cw, y1 + ch
    if which == "np" then
        local r0 = HV.NP.rect
        HV.NP.rect = { x1, y1, x2, y2 }
        if r0 and (r0[2] ~= y1 or r0[3] ~= x2 or r0[4] ~= y2) and HV.TS.spec and HV.TS.spec.beside == "np" then HV.TS.draw() end
    end
    local glass = HV.GL.show(which, x1, y1, x2, y2, rad, S)
    local ev = {}
    HV.GL.frame(ev, x1, y1, x2, y2, rad, S, glass)
    local ix, iy = x1 + pad, y1 + pad
    if with_img and not f then           -- still on its way: a quiet tile with the episode label, not an empty box
        ev[#ev + 1] = D.ev_rect(ix, iy, ix + sw, iy + sh, "FFFFFF", 8, nil, 0, 0, HV.R or 0)
        if spec.tag then ev[#ev + 1] = HV.GL.txt(ix + sw / 2, iy + sh / 2, 5, fs3, 45, true, U.ass_escape(spec.tag)) end
    end
    local tx = with_img and (ix + sw + gap) or (x1 + pad + math.floor(6 * S))
    local cy = (y1 + y2) / 2
    ev[#ev + 1] = HV.GL.txt(tx, cy - fs2 * 0.95, 4, fs1, 62, true, "{\\fsp" .. fsp .. "}" .. U.ass_escape(spec.eyebrow or ""))
    ev[#ev + 1] = HV.GL.txt(tx, cy + fs2 * 0.05, 4, fs2, 100, true, U.ass_escape(title))
    if sub and sub ~= "" then
        ev[#ev + 1] = HV.GL.txt(tx, cy + fs2 * 1.05, 4, fs3, 55, false, U.ass_escape(sub))
    end
    if rr > 0 then
        local rcx, rcy = x2 - pad - math.floor(4 * S) - rr, cy
        local th = math.max(2, math.floor(3 * S + 0.5))
        ev[#ev + 1] = HV.GL.arc(rcx, rcy, rr, th, 1, TOAST.text, 18)
        ev[#ev + 1] = HV.GL.arc(rcx, rcy, rr, th, spec.frac, TOAST.ring, 92)
        ev[#ev + 1] = HV.GL.txt(rcx, rcy, 5, fs2 - 1, 95, true, tostring(spec.count or ""))
    end
    local slot = (which == "np") and HV.NP or NX
    slot.ov = slot.ov or mp.create_osd_overlay("ass-events")
    slot.ov.res_x, slot.ov.res_y = ww, wh
    -- the card is drawn again a few times a second; mpv only hears about it when something on it changed
    local data = table.concat(ev, "\n")
    local key = data .. "|" .. ww .. "x" .. wh
    if not slot.shown or slot.last ~= key then slot.ov.data = data; slot.ov:update(); slot.last = key end
    if f then
        local sig = f .. "@" .. ix .. "," .. iy
        if slot.bmp ~= sig then
            slot.bmp = mp.commandv("overlay-add", tostring(slot.id), tostring(ix), tostring(iy), f, "0", "bgra",
                tostring(sw), tostring(sh), tostring(sw * 4)) and sig or nil
        end
    elseif slot.bmp then
        pcall(mp.commandv, "overlay-remove", tostring(slot.id)); slot.bmp = nil
    end
    slot.shown = true
end

function NX.draw(meta, left, art, sw, sh, f)
    local label, name, show = NX.info(meta, art)
    local secs = math.max(1, tonumber(o.next_episode_secs) or 10)
    NX.card("nx", {
        eyebrow = "UP NEXT" .. (label and ("  ·  " .. label) or ""),
        title = name or show or meta.name or "",
        sub = "Enter play  ·  S skip credits  ·  Esc stay",
        frac = math.max(0, math.min(1, left / secs)), count = math.max(0, math.ceil(left)),
        tag = label and label:match("E%d+$") or label, pos = o.next_card_position,
    }, art, sw, sh, f)
end

mp.add_periodic_timer(0.2, function()
    if not o.next_episode_card or not now_playing or browser_active or HV.DR.open then NX.hide(); return end
    local href = now_playing.href
    if NX.dismissed and NX.dismissed ~= href then NX.dismissed = nil end
    local pos, dur = last_known_pos, last_known_dur
    if not (pos and dur and dur > 60) or NX.dismissed == href then NX.hide(); return end
    local secs = math.max(3, tonumber(o.next_episode_secs) or 10)
    local timing = tostring(o.next_episode_timing or "auto"):lower()
    local skipper = NX.skipper()
    if timing ~= "credits" and timing ~= "before" then timing = skipper and "before" or "credits" end
    local tail = NX.tail_start(dur, skipper or timing == "before")
    local t0, t_go
    if tail and timing == "before" then t0, t_go = tail - secs, tail - 0.45   -- leave just before the skip script jumps
    elseif tail then t0, t_go = tail, tail + secs
    else t0 = dur - secs - 1 end
    if pos < t0 - 90 then NX.hide(); return end
    local meta = NX.next_entry()
    if not meta then NX.hide(); return end
    local sw, sh = NX.size()
    local art = NX.art(meta)
    local f = NX.img(art, sw, sh)                    -- starts early, so the still is ready when the card appears
    if pos < t0 or pos >= dur - 0.3 then NX.hide(); return end
    local left = (t_go or (t0 + secs)) - pos
    if left <= 0 then
        NX.hide()
        if t_go then NX.dismissed = href; NX.next() end
        return
    end
    if HV.NP.shown then HV.NP.hide() end
    NX.bind(href)
    NX.draw(meta, left, art, sw, sh, f)
end)

-- ---- now playing: a few seconds of the same card when a file starts from here (library, add-ons, torrent) ----
HV.NP = { id = 61, shown = nil, ov = nil, n = 0 }
function HV.NP.hide()
    HV.NP.rect, HV.NP.last = nil, nil
    local P = HV.NP
    P.n = P.n + 1                 -- a pending show / timer of the old file is void
    if P.shown then
        if P.ov then P.ov.data = ""; P.ov:update() end
        pcall(mp.commandv, "overlay-remove", tostring(P.id))
        P.shown, P.bmp = nil, nil
    end
    HV.GL.hide("np")
end
function HV.NP.start()
    local P = HV.NP
    P.hide()
    if not o.now_playing_card then return end
    local path = mp.get_property("path") or ""
    local meta = pending_meta[path]
    local AX = HV.AX
    local addon = AX.urls_playing[path]
    if not meta and not addon then return end                   -- not started from here: nothing to say
    local n = P.n
    local art, sw, sh = nil, NX.size()
    if meta and meta.href then art = NX.art(meta) end
    local t0 = mp.get_time()
    local function spec()
        local vp = MS.prop("video-params")
        if type(vp) ~= "table" then vp = {} end
        local hgt, wid = tonumber(vp.h) or 0, tonumber(vp.w) or 0       -- by width too: 1920x800 is a 1080p film
        local res = ((wid >= 3200 or hgt >= 1600) and "2160p") or ((wid >= 1800 or hgt >= 900) and "1080p")
            or ((wid >= 1200 or hgt >= 600) and "720p") or (hgt > 0 and (hgt .. "p")) or nil
        local parts = {}
        local label, name, show
        if meta and meta.href then label, name, show = NX.info(meta, art) end
        if show and name then parts[#parts + 1] = show end
        if res then parts[#parts + 1] = res end
        local src = (AX.t_of(path) and "torrent (rqbit)") or (path:find("real%-debrid") and "Real-Debrid")
            or (addon and "via add-on") or (meta and meta.direct_url and "downloading while it plays")
        if src then parts[#parts + 1] = src end
        local cp = CT.parse(addon or (meta and meta.name) or "")
        local am = addon and AX.np_meta[path]
        local yr = (am and tostring(am.year or "") ~= "" and tostring(am.year)) or (cp and cp.year)
        local base = (am and am.name) or (cp and cp.title)
        local ttl = name or show or (base and (base .. ((yr and not (am and am.kind == "tv")) and (" (" .. yr .. ")") or ""))) or addon or (meta and meta.name) or ""
        local lab = label or (cp and cp.se)
        return { eyebrow = "NOW PLAYING" .. (lab and ("  ·  " .. lab) or ""), title = ttl, sub = table.concat(parts, "  ·  "),
                 x = "left", pos = o.now_playing_position, tag = lab and lab:match("E%d+$") or lab }
    end
    local shown_at
    local function tick()
        if P.n ~= n then return end
        local now = mp.get_time()
        -- the browser closes itself once playback has really started: wait for that (a moment), then show
        if browser_active and not shown_at and now - t0 < 4 then mp.add_timeout(0.2, tick); return end
        if browser_active or NX.shown or HV.DR.open or MS.prop("idle-active") then P.hide(); return end
        local f = NX.img(art, sw, sh)
        -- wait up to a second for the picture (and the video size), so the card does not change shape
        if not shown_at and not f and art and art.still and now - t0 < 1.0 then mp.add_timeout(0.1, tick); return end
        shown_at = shown_at or now
        if now - shown_at >= math.max(1, tonumber(o.now_playing_secs) or 4) then P.hide(); return end
        NX.card("np", spec(), art, sw, sh, f)
        mp.add_timeout(0.25, tick)
    end
    mp.add_timeout(0.35, tick)
end
mp.register_event("file-loaded", function()
    local ok, err = pcall(HV.NP.start)
    if not ok then msg.warn("now-playing card: " .. tostring(err)) end
end)
mp.register_event("end-file", function() HV.NP.hide() end)

-- ---- setup check (F1 in the browser, or script-message webdav-browser-doctor): every service in one list ----
-- Each line tests one thing for real (a request, a start of the program) and says what to change when it fails.
-- Nothing secret is shown: no keys, tokens or passwords.
HV.DR = { open = false, rows = {}, ov = nil, gen = 0 }
-- state: "run" | "ok" | "warn" | "bad" | "off"
function HV.DR.set(id, state, detail)
    local R = HV.DR
    for _, r in ipairs(R.rows) do
        if r.id == id then r.state, r.detail = state, detail end
    end
    if R.open then R.draw() end
end
function HV.DR.host(u) return tostring(u or ""):match("^%a+://([^/]+)") or tostring(u or "") end
function HV.DR.writable(dir)
    PS.mkdir()
    local p = dir .. "/.webdav-browser-check"
    local f = io.open(p, "wb")
    if not f then
        pcall(mp.command_native, { name = "subprocess", playback_only = false, capture_stdout = true, capture_stderr = true,
            args = (package.config:sub(1, 1) == "\\") and { "cmd", "/c", "mkdir", (dir:gsub("/", "\\")) } or { "mkdir", "-p", dir } })
        f = io.open(p, "wb")
    end
    if not f then return false end
    f:write("ok"); f:close(); os.remove(p)
    return true
end

function HV.DR.run()
    local R, AX = HV.DR, HV.AX
    R.gen = R.gen + 1
    local gen = R.gen
    local function set(id, st, d) if R.gen == gen then R.set(id, st, d) end end
    R.rows = {
        { id = "dav", name = "WebDAV library" }, { id = "curl", name = "curl" }, { id = "tmdb", name = "TMDB (artwork, titles)" },
        { id = "conv", name = "Artwork converter" }, { id = "rd", name = "Real-Debrid account" }, { id = "addons", name = "Add-ons" },
        { id = "nyaa", name = "Nyaa.si" }, { id = "anilist", name = "AniList" }, { id = "rqbit", name = "Torrent streaming (rqbit)" },
        { id = "vo", name = "Video output" }, { id = "skip", name = "Chapter-skip script" }, { id = "cache", name = "Cache folder" },
        { id = "dl", name = "Downloads folder" },
    }
    for _, r in ipairs(R.rows) do r.state, r.detail = "run", "checking…" end
    R.draw()

    -- WebDAV: list the start folder
    if o.url == "" then set("dav", "bad", "url is empty - set url, user and pass in webdav-browser.conf")
    else
        local t0 = mp.get_time()
        MS.fetch_dir_now(o.start_path ~= "" and o.start_path or "/", function(entries, err)
            if type(entries) == "table" then
                set("dav", "ok", string.format("%s  ·  %d items in %s  ·  %d ms", R.host(o.url), #entries,
                    (o.start_path ~= "" and o.start_path or "/"), math.floor((mp.get_time() - t0) * 1000)))
            else
                local e = tostring(err or "no answer")
                set("dav", "bad", e .. ((e:find("401") or e:lower():find("password") or e:lower():find("unauthor")) and "  ·  check user / pass" or "  ·  check url and your connection"))
            end
        end)
    end
    -- curl
    PS.run({ o.curl_path, "--version" }, function(res)
        local v = res and res.status == 0 and tostring(res.stdout):match("^curl (%S+)")
        if v then set("curl", "ok", "curl " .. v .. (PS.H.par and "  ·  parallel requests" or ""))
        else set("curl", "bad", "'" .. tostring(o.curl_path) .. "' did not start - set curl_path to curl.exe's full path") end
    end)
    -- TMDB
    if tostring(o.tmdb_key or "") == "" then set("tmdb", "off", "no tmdb_key - folder names are shown instead of posters and titles")
    else
        PS.http(PS.tmdb_req("/configuration"), function(code)
            if code == 200 then set("tmdb", "ok", "key accepted")
            elseif code == 401 then set("tmdb", "bad", "the key was rejected - copy tmdb_key again from themoviedb.org > Settings > API")
            elseif code == 0 then set("tmdb", "bad", "no answer from api.themoviedb.org - check your connection")
            else set("tmdb", "warn", "HTTP " .. code) end
        end)
    end
    -- artwork converter (asks again until the ffmpeg probe has an answer)
    local function conv()
        if R.gen ~= gen then return end
        local mode = HV.conv_mode()
        if mode == nil then return mp.add_timeout(0.3, conv) end
        local base
        if mode == "ffmpeg" then base = { "ok", "ffmpeg" }
        elseif mode == "powershell" then base = { "warn", "PowerShell (slow) - install ffmpeg for much faster artwork" }
        else base = { "ok", tostring(mode) } end
        set("conv", base[1], base[2] .. "  ·  trying a picture…")
        -- a real conversion: a cached poster made into a wide picture (filled and cropped, as the cards need)
        HV.conv_try(mode, function(ok, why, ms)
            if ok == nil then return set("conv", base[1], base[2] .. "  ·  (no picture cached yet to try)") end
            if ok then set("conv", base[1], base[2] .. string.format("  ·  a test picture converted and cropped in %d ms", ms))
            else set("conv", "bad", tostring(mode) .. " could not convert a test picture: " .. tostring(why or "no output"):gsub("%s+", " "):sub(1, 140)) end
        end)
    end
    conv()
    -- Real-Debrid
    if not PS.rd_on() then set("rd", "off", "no rd_api_token - adding from add-ons and library repairs need it")
    else
        PS.rd_req("/user", nil, function(d, err, code)
            if type(d) == "table" and d.username then
                local days = tonumber(d.premium) and math.floor(tonumber(d.premium) / 86400) or nil
                if d.type == "premium" then
                    set("rd", (days and days < 7) and "warn" or "ok", tostring(d.username) .. "  ·  premium" .. (days and string.format("  ·  %d day%s left", days, days == 1 and "" or "s") or ""))
                else set("rd", "warn", tostring(d.username) .. "  ·  not premium - Real-Debrid links need a premium account") end
            elseif code == 401 then set("rd", "bad", "the token was rejected - copy it again from real-debrid.com/apitoken")
            else set("rd", "bad", "no answer (" .. tostring(err or ("HTTP " .. tostring(code))) .. ")") end
        end)
    end
    -- add-ons: each manifest
    local urls = AX.urls()
    if #urls == 0 then set("addons", "off", "no addon_urls - the add screen (N) needs at least one")
    else
        -- one row per add-on: its manifest, then a real stream question (The Shawshank Redemption) with the answer time
        local rows_ = {}
        for i, u in ipairs(urls) do
            local id = (#urls == 1) and "addons" or ("addon" .. i)
            if #urls > 1 then rows_[#rows_ + 1] = { id = id, name = (i == 1) and "Add-ons" or "", state = "run", detail = "checking…" } end
        end
        if #rows_ > 0 then
            local at
            for k, r in ipairs(R.rows) do if r.id == "addons" then at = k end end
            table.remove(R.rows, at)
            for k, r in ipairs(rows_) do table.insert(R.rows, at + k - 1, r) end
            R.draw()
        end
        for i, u in ipairs(urls) do
            local id = (#urls == 1) and "addons" or ("addon" .. i)
            PS.http({ url = u .. "/manifest.json", timeout = 15 }, function(code, body)
                local ok, d = pcall(utils.parse_json, body or "")
                if not (code == 200 and ok and type(d) == "table") then
                    return set(id, "bad", AX.host(u) .. "  ·  " .. (code == 0 and "no answer" or ("HTTP " .. code)) .. "  ·  check the manifest URL")
                end
                local name = tostring(d.name or AX.host(u))
                local t0 = mp.get_time()
                PS.http({ url = u .. "/stream/movie/tt0111161.json", timeout = 30 }, function(c2, b2)
                    local ok2, d2 = pcall(utils.parse_json, b2 or "")
                    local n = (c2 == 200 and ok2 and type(d2) == "table" and type(d2.streams) == "table") and #d2.streams or nil
                    local ms = math.floor((mp.get_time() - t0) * 1000)
                    if n == nil then set(id, "warn", string.format("%s  ·  manifest ok, but no stream answer (HTTP %d)", name, c2))
                    elseif n == 0 then set(id, "warn", string.format("%s  ·  answers, 0 streams for a known film  ·  %d ms  ·  check its filters / debrid key", name, ms))
                    else set(id, "ok", string.format("%s  ·  %d streams for a known film  ·  %d ms%s", name, n, ms, (o.aiostreams_password ~= "" and u:find("/stremio/", 1, true)) and "  ·  search API password set" or "")) end
                end)
            end)
        end
    end
    -- Nyaa
    PS.http({ url = AX.nyaa_base() .. "/?page=rss&q=&c=1_0&f=0", timeout = 15 }, function(code, body)
        if code == 200 and tostring(body or ""):find("<rss", 1, true) then set("nyaa", "ok", R.host(AX.nyaa_base()))
        else set("nyaa", "warn", R.host(AX.nyaa_base()) .. " - " .. (code == 0 and "no answer (blocked where you are? set nyaa_url to a mirror)" or ("HTTP " .. code))) end
    end)
    -- AniList
    PS.al_gql("{ Media(id: 1) { id } }", function(d, why)
        if type(d) == "table" and type(d.data) == "table" then set("anilist", "ok", R.host(o.anilist_api))
        else set("anilist", "warn", tostring(why or "no answer") .. " - anime matching falls back to TMDB") end
    end)
    -- rqbit: running? else can it be started?
    if not AX.t_on() then set("rqbit", "off", "torrent_client is empty")
    else
        AX.t_probe(function(ok, code)
            if ok then
                PS.http({ url = AX.t_base() .. "/", timeout = 3 }, function(_, body)
                    local okj, d = pcall(utils.parse_json, body or "")
                    local ver = okj and type(d) == "table" and d.version
                    PS.http({ url = AX.t_base() .. "/dht/stats", timeout = 3 }, function(c2, b2)
                        local ok2, d2 = pcall(utils.parse_json, b2 or "")
                        local nodes = c2 == 200 and ok2 and type(d2) == "table" and tonumber(d2.routing_table_size)
                        set("rqbit", (nodes == 0) and "warn" or "ok", "running" .. (ver and (" v" .. ver) or "") .. " on " .. R.host(AX.t_base())
                            .. (nodes and string.format("  ·  %d DHT nodes", nodes) or "") .. ((nodes == 0) and " - a firewall may block it" or ""))
                    end)
                end)
            elseif code == 401 or code ~= 0 then
                set("rqbit", "bad", string.format("port %d is taken by something else - set torrent_port to a free one", math.floor(tonumber(o.torrent_port) or 3030)))
            else
                mp.command_native_async({ name = "subprocess", playback_only = false, capture_stdout = true, capture_stderr = true,
                    args = { o.torrent_client, "--version" } }, function(success, res)
                    local v = success and res and res.status == 0 and tostring(res.stdout or ""):match("rqbit%s+(%S+)")
                    if v then set("rqbit", "ok", "rqbit " .. v .. " installed  ·  starts when you stream a torrent")
                    else set("rqbit", "bad", "'" .. tostring(o.torrent_client) .. "' not found - put rqbit.exe next to mpv.exe or set torrent_client to its full path") end
                end)
            end
        end)
    end
    -- video output (the glass blur needs gpu-next)
    local vo = tostring(mp.get_property("current-vo") or "")
    local hw = tostring(mp.get_property("hwdec-current") or "")
    if vo == "" then set("vo", "off", "starts with the first video")
    elseif vo == "gpu-next" then set("vo", "ok", "gpu-next" .. ((hw ~= "" and hw ~= "no") and ("  ·  hardware decoding " .. hw) or "") .. (o.glass_blur and "  ·  glass blur on" or ""))
    else set("vo", "warn", vo .. " - the cards are tinted instead of blurred (vo=gpu-next in mpv.conf for the glass)") end
    -- skip script
    NX.sk_t = nil
    if NX.skipper() then set("skip", "ok", "found  ·  the next-episode countdown ends where it skips the ending")
    else set("skip", "off", "none found  ·  the next-episode card counts down at the end credits") end
    -- folders
    local cw = R.writable(PS.dir())
    set("cache", cw and "ok" or "bad", PS.dir() .. (cw and "" or " - cannot write here: set poster_cache_dir"))
    local fb = MS.fb_dir()
    local fw = R.writable(fb)
    set("dl", fw and "ok" or "bad", fb .. (fw and "" or " - cannot write here: set fallback_dir"))
end

-- drawing never takes the browser down with it: a failure is logged once and the panel closes
function HV.DR.draw()
    local ok, err = pcall(HV.DR.paint)
    if not ok then
        msg.error("setup check: " .. tostring(err))
        if HV.DR.open then
            HV.DR.close()
            HV.TS.show({ eyebrow = "SETUP CHECK", title = "Couldn't open", extra = tostring(err):gsub("^.-:%d+: ", ""), note_rgb = TOAST.bad }, 8)
        end
    end
end
function HV.DR.paint()
    local R = HV.DR
    if not R.open then return end
    local ww, wh = U.canvas_size()
    if not ww or ww <= 0 then return end
    local S = wh / 1080
    local fs, fsn, fsd = math.floor(26 * S), math.floor(19 * S), math.floor(16 * S)
    local rowh = math.floor(fsn * 2.55)
    local pw = math.min(ww - 80 * S, 1180 * S)
    local ph = fs * 3.2 + #R.rows * rowh + fsd * 3.2
    local x1, y1 = (ww - pw) / 2, math.max(20 * S, (wh - ph) / 2)
    local x2, y2 = x1 + pw, y1 + ph
    local rad = math.floor(18 * S)
    local ev = {}
    ev[#ev + 1] = D.ev_rect(0, 0, ww, wh, "000000", browser_active and 55 or 35, nil, 0, 0, 0)
    local glass = (not browser_active) and HV.GL.show("dr", x1, y1, x2, y2, rad, S)
    HV.GL.frame(ev, x1, y1, x2, y2, rad, S, glass)
    if not glass then ev[#ev + 1] = D.ev_rect(x1, y1, x2, y2, THEME.bg_header, browser_active and 94 or 70, nil, 0, 0, rad) end
    local n = { ok = 0, warn = 0, bad = 0, run = 0 }
    for _, r in ipairs(R.rows) do n[r.state] = (n[r.state] or 0) + 1 end
    local summary = (n.run > 0) and string.format("checking %d…", n.run)
        or ((n.bad == 0 and n.warn == 0) and "Everything works")
        or table.concat((function()
            local t = {}
            if n.bad > 0 then t[#t + 1] = string.format("%d problem%s", n.bad, n.bad == 1 and "" or "s") end
            if n.warn > 0 then t[#t + 1] = string.format("%d warning%s", n.warn, n.warn == 1 and "" or "s") end
            return t
        end)(), "  ·  ")
    local px = x1 + 34 * S
    ev[#ev + 1] = HV.GL.txt(px, y1 + fs * 1.4, 4, fs, 100, true, "Setup check")
    -- buttons: ✕ in the corner, Check again and Copy the report at the bottom (the keys still work); a click outside closes
    R.rect, R.btns = { x1, y1, x2, y2 }, {}
    local function btn(bx1, by1, bx2, by2, id, act) R.btns[#R.btns + 1] = { bx1, by1, bx2, by2, id = id, act = act } end
    local xd = math.floor(fs * 1.25)
    local xcx, xcy = x2 - 34 * S - xd / 2, y1 + fs * 1.4
    btn(xcx - xd / 2, xcy - xd / 2, xcx + xd / 2, xcy + xd / 2, "x", function() R.close() end)
    ev[#ev + 1] = D.ev_rect(xcx - xd / 2, xcy - xd / 2, xcx + xd / 2, xcy + xd / 2, R.hot == "x" and THEME.bad or "FFFFFF", R.hot == "x" and 80 or 8, "FFFFFF", 20, 1, xd / 2)
    ev[#ev + 1] = D.ev_shape(D.cross_path(xcx, xcy, xd * 0.2, math.max(1, xd * 0.05)), R.hot == "x" and "FFFFFF" or THEME.text_muted, 100)
    ev[#ev + 1] = HV.GL.txt(xcx - xd / 2 - fsn * 0.8, y1 + fs * 1.4, 6, fsn, 70, false, U.ass_escape(summary))
    local col = { ok = THEME.good, warn = THEME.warn, bad = THEME.bad, off = "FFFFFF", run = "FFFFFF" }
    local glyph = { ok = "✓", warn = "!", bad = "✕", off = "–", run = "…" }
    local y = y1 + fs * 2.9
    local namew = 330 * S
    for _, r in ipairs(R.rows) do
        local cy = y + rowh / 2
        local c = col[r.state] or "FFFFFF"
        ev[#ev + 1] = D.ev_rect(px, cy - fsn * 0.62, px + fsn * 1.24, cy + fsn * 0.62, c, (r.state == "off" or r.state == "run") and 12 or 22, nil, 0, 0, fsn * 0.62)
        ev[#ev + 1] = D.ev_text(px + fsn * 0.62, cy, 5, string.format("\\b1\\fs%d\\c%s", fsd, U.ass_color(c)), glyph[r.state] or "?")
        ev[#ev + 1] = HV.GL.txt(px + fsn * 1.9, cy, 4, fsn, r.state == "off" and 55 or 95, true, U.ass_escape(r.name))
        local dx = px + fsn * 1.9 + namew
        ev[#ev + 1] = HV.GL.txt(dx, cy, 4, fsd, r.state == "off" and 45 or 70, false, U.ass_escape(U.fit_text(r.detail or "", x2 - 34 * S - dx, fsd)))
        y = y + rowh
    end
    do
        local by = y2 - fsd * 1.6
        local bh = math.floor(fsd * 2)
        local bx = px
        for _, b in ipairs({ { "r", "R", "Check again", R.run }, { "c", "C", "Copy the report", R.copy }, { "esc", "Esc", "Close", R.close } }) do
            local label = b[2] .. "  " .. b[3]
            local bw = math.floor(HV.AX.tw(label, fsd, true) + fsd * 2)
            local hot = R.hot == b[1]
            ev[#ev + 1] = D.ev_rect(bx, by - bh / 2, bx + bw, by + bh / 2, "FFFFFF", hot and 22 or 8, "FFFFFF", hot and 40 or 18, 1, bh / 2)
            ev[#ev + 1] = HV.GL.txt(bx + fsd, by, 4, fsd, hot and 100 or 80, true,
                string.format("%s{\\b0\\1a%s}  %s", U.ass_escape(b[2]), U.ass_alpha(hot and 90 or 60), U.ass_escape(b[3])))
            btn(bx, by - bh / 2, bx + bw, by + bh / 2, b[1], b[4])
            bx = bx + bw + math.floor(fsd * 0.8)
        end
        if R.copied then ev[#ev + 1] = HV.GL.txt(bx + fsd * 0.4, by, 4, fsd, 55, false, U.ass_escape(R.copied)) end
    end
    R.ov = R.ov or mp.create_osd_overlay("ass-events")
    -- its own layer, above everything of the browser: the browser is 3000, its animation layer 3001, toasts 3004, the
    -- status card 3005. At the same z as the browser (as before) mpv was free to draw the browser on top - on some
    -- systems the panel was there (keys bound, posters hidden) but invisible.
    R.ov.res_x, R.ov.res_y, R.ov.z = ww, wh, 3010
    R.ov.data = table.concat(ev, "\n")
    R.ov:update()
end

function HV.DR.show()
    local R, AX = HV.DR, HV.AX
    if R.open then return end
    if HV.HP and HV.HP.open then HV.HP.close() end
    R.open, R.t_open = true, mp.get_time()
    R.was_add = browser_active and HV.mode == "add"
    local ok, err = pcall(function()
        if R.was_add then AX.unbind() elseif browser_active then unbind_all() end
        -- one binding per key (the doctor key is often F1 itself); a close in the first moments is the same key
        -- press still arriving (key up / auto-repeat), not a second press
        local function close() if mp.get_time() - (R.t_open or 0) > 0.35 then R.close() end end
        R.keys = {}
        local seen = {}
        local function bind(k, fn)
            if seen[k] then return end
            seen[k] = true
            local name = "wb_dr_" .. (#R.keys + 1)
            R.keys[#R.keys + 1] = name
            mp.add_forced_key_binding(k, name, fn)
        end
        for _, k in ipairs(U.kb("doctor")) do bind(k, close) end
        for _, k in ipairs({ "ESC", "BS", "MBTN_RIGHT", "GAMEPAD_ACTION_RIGHT" }) do bind(k, close) end
        for _, k in ipairs({ "r", "R" }) do bind(k, function() R.run() end) end
        for _, k in ipairs({ "c", "C" }) do bind(k, function() R.copy() end) end
        bind("MBTN_LEFT", function() R.click() end)
        bind("MOUSE_MOVE", function() R.move() end)
        R.run()
    end)
    if not ok then
        msg.error("setup check: " .. tostring(err))
        R.close()
        HV.TS.show({ eyebrow = "SETUP CHECK", title = "Couldn't open", extra = tostring(err):gsub("^.-:%d+: ", ""), note_rgb = TOAST.bad }, 8)
        return
    end
    -- pictures are drawn above every text layer, so the browser's posters go while the panel is open (only now that
    -- the panel is up: if it could not be drawn, the browser stays as it was)
    if R.open and browser_active then HV.clear(); PS.hide() end
end
-- the report as text: every row, the versions, the options that matter (no passwords, no keys)
function HV.DR.report()
    local R = HV.DR
    local out = { "webdav-browser " .. SCRIPT_VERSION .. "  ·  mpv " .. tostring(mp.get_property("mpv-version") or "?") .. "  ·  " .. os.date("%Y-%m-%d %H:%M"), "" }
    for _, r in ipairs(R.rows) do
        local mark = ({ ok = "OK  ", warn = "WARN", bad = "FAIL", off = "off ", run = "... " })[r.state] or "?   "
        out[#out + 1] = string.format("%s  %-28s %s", mark, r.name, tostring(r.detail or ""))
    end
    out[#out + 1] = ""
    out[#out + 1] = string.format("url=%s  poster_converter=%s  theme=%s  glass bars=%s  vo=%s", R.host(o.url), tostring(o.poster_converter), tostring(o.theme),
        tostring(o.experimental_glass_bars), tostring(mp.get_property("current-vo")))
    return table.concat(out, "\n")
end
function HV.DR.copy()
    local R = HV.DR
    local txt = R.report()
    local path = PS.dir() .. "/setup-check.txt"
    pcall(atomic_write, path, txt)
    local how = nil
    -- mpv 0.40+: the clipboard property; else the system's own tool
    if pcall(mp.set_property, "clipboard/text", txt) and mp.get_property("clipboard/text") == txt then how = "copied"
    else
        local win = package.config:sub(1, 1) == "\\"
        local mac = not win and (os.getenv("HOME") or ""):match("^/Users/")
        local args = win and { "cmd", "/c", "clip" } or (mac and { "pbcopy" } or { "xclip", "-selection", "clipboard" })
        local res = mp.command_native({ name = "subprocess", args = args, stdin_data = txt, playback_only = false, capture_stdout = true, capture_stderr = true })
        if type(res) == "table" and res.status == 0 then how = "copied" end
    end
    R.copied = how and "✓ copied (and saved as setup-check.txt in the cache folder)" or "no clipboard here - saved as setup-check.txt in the cache folder"
    R.draw()
    mp.add_timeout(6, function() R.copied = nil; if R.open then R.draw() end end)
end
function HV.DR.hit()
    local R = HV.DR
    local mx, my = U.mouse_xy()
    if not mx then return nil, false end
    for _, b in ipairs(R.btns or {}) do
        if mx >= b[1] - 3 and mx <= b[3] + 3 and my >= b[2] - 3 and my <= b[4] + 3 then return b, true end
    end
    local r = R.rect
    return nil, r and mx >= r[1] and mx <= r[3] and my >= r[2] and my <= r[4]
end
function HV.DR.click()
    local R = HV.DR
    if mp.get_time() - (R.t_open or 0) < 0.35 then return end
    local b, inside = R.hit()
    if b then return b.act() end
    if not inside then R.close() end
end
function HV.DR.move()
    local R = HV.DR
    local b = R.hit()
    local hot = b and b.id or nil
    if hot ~= R.hot then R.hot = hot; R.draw() end
end
function HV.DR.close()
    local R, AX = HV.DR, HV.AX
    if not R.open then return end
    R.open = false
    R.gen = R.gen + 1                      -- answers still on their way are dropped
    for _, name in ipairs(R.keys or {}) do mp.remove_key_binding(name) end
    R.keys = {}
    if R.ov then R.ov.data = ""; R.ov:update() end
    HV.GL.hide("dr")
    if browser_active then
        if R.was_add and HV.mode == "add" then AX.bind() else bind_all() end
        HV.sig, HV.last_data, MS.last_overlay_data = nil, nil, nil
        render()
    end
end
mp.register_script_message("webdav-browser-doctor", function() if HV.DR.open then HV.DR.close() else HV.DR.show() end end)
-- the doctor key works everywhere, not only in the browser (while the browser is open its own binding answers).
-- Not forced: a binding for the same key in input.conf wins (then use: KEY script-binding webdav_browser_posters/webdav-doctor)
for i, k in ipairs(U.kb("doctor")) do
    mp.add_key_binding(k, (i == 1) and "webdav-doctor" or ("webdav-doctor-" .. i), function()
        if HV.DR.open then HV.DR.close() else HV.DR.show() end
    end)
end
mp.observe_property("osd-dimensions", "native", function() if HV.DR.open then HV.DR.draw() end end)

mp.register_event("shutdown", function()
    -- AniList / Real-Debrid answers waiting for their 2 s write
    for _, T in ipairs({ PS.AL, PS.RD }) do
        if T and T.save_t then T.save_t:kill(); T.save_t = nil; pcall(T == PS.AL and PS.al_save_now or PS.rd_save_now) end
    end
    -- journaled caches waiting for their 0.5 s timer
    if PS.idx_timer then PS.idx_timer:kill(); PS.idx_timer = nil; pcall(PS.flush_index) end
    if PS.eps_timer then local t = PS.eps_timer; PS.eps_timer = nil; t:kill()
        pcall(function() local p = PS.dir() .. "/episodes.json"; if not U.jl_sync(PS.epsj, p, PS.eps) then U.jl_compact(PS.epsj, p, PS.eps, PS.eps) end end) end
    index_stop()
    if MS.active then
        if now_playing then record_progress(now_playing, last_known_pos, last_known_dur) end
        save_persistence()
        if MS.cache_dirty then save_dircache() end
    end
    MS.fold_journals()
    if MS.fb.active then MS.fb_stop(true) end
    for pth in pairs(MS.fb_dirty_files) do pcall(os.remove, pth) end
    pcall(HV.AX.t_shutdown)
end)
MS.fb_purge()
HV.AX.t_purge()
mp.register_event("shutdown", remove_background_blur)

MS.debug = o.debug_overlay
MS.blur_state = "off"
MS.conf_sig = MS.conf_stamp()           -- what the conf looked like when it was read at the start
load_persistence()
mp.commandv("script-message", "webdav-browser-claim", mp.get_script_name(), "startup")   -- at startup the poster edition keeps the data; afterwards the one opened last
msg.info("webdav-browser " .. SCRIPT_VERSION .. " loaded (" .. tostring(o.open_key_posters) .. ")  - poster edition")
-- ---- toasts: one glass pill (the look of the cards), e.g. "WEBDAV LIBRARY  Ready  Ctrl+P to browse  ·  FFmpeg" ----
-- spec = { eyebrow, title, extra, note, note_rgb, pos }. It fades and slides in, then out; the newest one replaces the last.
HV.TS = { ov = nil, timer = nil, spec = nil, t0 = 0, secs = 3, wc = {} }
-- text width measured by libass at the toast's own size (the browser's measure needs the browser to have been open)
function HV.TS.tw(str, fs, bold, fsp, ww, wh)
    local T = HV.TS
    local key = table.concat({ str, fs, tostring(bold), fsp or 0, ww, wh }, "|")
    if T.wc[key] then return T.wc[key] end
    T.mo = T.mo or mp.create_osd_overlay("ass-events")
    local mo = T.mo
    mo.res_x, mo.res_y, mo.hidden, mo.compute_bounds = ww, wh, true, true
    mo.data = D.ev_text(0, wh / 2, 7, string.format("\\fs%d\\b%d%s", fs, bold and 1 or 0, fsp and ("\\fsp" .. fsp) or ""), U.ass_escape(str))
    local ok, r = pcall(mo.update, mo)
    local w = (ok and type(r) == "table" and r.x1) and (r.x1 - r.x0) or (U.utf8_len(str) * fs * (bold and 0.58 or 0.52) + (fsp or 0) * U.utf8_len(str))
    T.wn = (T.wn or 0) + 1
    if T.wn > 3000 then T.wc, T.wn = {}, 0 end       -- each width is a round trip to mpv: kept for many toasts
    T.wc[key] = w
    return w
end
function HV.TS.draw()
    local T = HV.TS
    local sp = T.spec
    local ww, wh = U.canvas_size()
    if not sp or not ww or ww <= 0 then return end
    local age = mp.get_time() - T.t0
    local left = T.secs - age
    if left <= 0 then return T.hide() end
    local a = math.min(1, age / 0.18, left / 0.3)
    local ease = 1 - (1 - math.min(1, age / 0.25)) ^ 3
    local S = wh / 1080
    local fs1, fs2 = math.max(11, math.floor(12 * S)), math.max(14, math.floor(17 * S))
    local pad, gap = math.floor(18 * S), math.floor(12 * S)
    local fsp = math.max(1, math.floor(S + 0.5))
    local tw = HV.TS.tw
    local w1 = sp.eyebrow and tw(sp.eyebrow, fs1, true, fsp, ww, wh) or 0
    local w2 = sp.title and tw(sp.title, fs2, true, nil, ww, wh) or 0
    local w3 = sp.extra and tw(sp.extra, fs2, false, nil, ww, wh) or 0
    local dot = math.max(3, math.floor(4 * S + 0.5))
    local w4 = sp.note and (dot * 2 + math.floor(8 * S) + tw(sp.note, fs2, false, nil, ww, wh)) or 0
    -- a long title (a file name) is shortened so the pill stays within the window
    local lead = (sp.kind == "wait") and (dot * 2 + math.floor(10 * S)) or 0
    local room = ww * 0.72 - pad * 2 - lead - w1 - w3 - w4 - gap * 4
    local title = sp.title
    if title and w2 > room and room > 60 * S then title = HV.scfit(title, room, fs2, true); w2 = tw(title, fs2, true, nil, ww, wh) end
    local parts = { w1, w2, w3, w4 }
    local cw = pad * 2 + lead
    local n = 0
    for _, v in ipairs(parts) do if v > 0 then cw = cw + v; n = n + 1 end end
    cw = math.min(ww - 40 * S, cw + gap * math.max(0, n - 1) + (sp.note and gap or 0))
    local ch = math.floor(44 * S)
    -- over the open browser: top centre (the corners hold its status pill and close button)
    local x1, y1, pos = HV.corner(sp.pos or (browser_active and "top" or nil), cw, ch, S, "top-right")
    -- over the open browser it sits ON the top bar's row (Home, the crumbs, Online): no picture is ever up there, so a
    -- backdrop or poster can't cut it off (pictures are always drawn above text and shapes)
    local m = browser_active and not sp.pos and HV.m
    if m and m.top_h then
        local cy = (m.glass and m.gm and m.gph) and (m.gm + m.gph / 2) or (m.top_h / 2)
        y1 = math.floor(cy - ch / 2)
        -- between the crumbs and the right-hand pills (a long title no longer runs under it)
        local fr = HV.top_free
        if fr and fr[2] - fr[1] > cw + 16 * S then
            x1 = math.floor(math.max(fr[1] + 8 * S, math.min(fr[2] - 8 * S - cw, x1)))
        elseif fr then
            x1 = math.floor(fr[2] - 8 * S - cw)
        end
    end
    -- beside the Now playing card, vertically centred on it (above it when there is no room to its right)
    local np = not browser_active and sp.beside == "np" and HV.NP.shown and HV.NP.rect
    if np then
        local gx = math.floor(12 * S)
        if np[3] + gx + cw <= ww - 20 * S then x1, y1 = np[3] + gx, math.floor((np[2] + np[4]) / 2 - ch / 2)
        else x1, y1 = np[1], np[2] - ch - gx end
        T.at = { x1, y1 }
    elseif sp.beside and T.at and not browser_active then x1, y1 = T.at[1], T.at[2] end
    local side = sp.beside and T.at ~= nil and not browser_active
    local sliding = ease < 1 or left < 0.3
    local rx, ry = math.floor(x1 + 0.5), math.floor(y1 + 0.5)        -- where it rests (the glass stays there)
    local settled = age >= (side and 0.32 or 0.25)
    if side then
        -- slides out from behind the card with a little overshoot, and back in as it leaves
        local k = math.min(1, age / 0.32)
        local back = 1 + 2.2 * (k - 1) ^ 3 + 1.2 * (k - 1) ^ 2
        x1 = x1 - (1 - back) * 26 * S - (1 - math.min(1, left / 0.3)) * 14 * S
    else
        y1 = y1 + (pos:find("^top") and -1 or 1) * (1 - ease) * 10 * S
    end
    -- a refusal shakes once as it arrives
    if sp.kind == "err" and age < 0.6 then
        local k = math.max(0, age - 0.15) / 0.45
        if k > 0 and k < 1 then x1 = x1 + math.sin(k * math.pi * 5) * 7 * S * (1 - k); sliding = true end
    end
    -- the same pill with new words (key): a short dip, so the change reads
    if T.swap_t then a = a * (0.45 + 0.55 * math.min(1, (mp.get_time() - T.swap_t) / 0.2)) end
    x1, y1 = math.floor(x1 + 0.5), math.floor(y1 + 0.5)
    local x2, y2 = x1 + cw, y1 + ch
    local rad = math.floor(ch / 2)
    T.hit = (browser_active and sp.act) and { rx, ry, rx + cw, ry + ch } or nil      -- a click on it (HV.TS.click)
    -- the blurred video behind it comes on once the pill has arrived (moving it with the pill would reset mpv's
    -- renderer every frame); the pill's tint thins out over it so it does not pop
    local glass = settled and (not browser_active) and HV.GL.show("ts", rx, ry, rx + cw, ry + ch, rad, S)
    if glass and not T.glass_t then T.glass_t = mp.get_time() end
    if not glass then T.glass_t = nil end
    local thin = glass and math.min(1, (mp.get_time() - T.glass_t) / 0.2) or 0
    local ev = {}
    local b = math.max(6, math.floor(14 * S))
    ev[#ev + 1] = string.format("{\\an7\\pos(0,0)\\bord0\\shad0\\blur%d\\1c&H000000&\\1a%s\\3a&HFF&\\p1}%s{\\p0}",
        b, U.ass_alpha(22 * a), D.rounded_path(x1, y1 + b * 0.35, x2, y2 + b * 0.6, rad, sliding))
    ev[#ev + 1] = D.ev_rect(x1, y1, x2, y2, TOAST.fill, (HV.GL.SOLID - (HV.GL.SOLID - HV.GL.TINT) * thin) * a, TOAST.edge, 17 * a, fsp, rad, sliding)
    local cy = (y1 + y2) / 2
    local x = x1 + pad
    if lead > 0 then         -- waiting: a dot breathing in front
        local br = 0.55 + 0.45 * math.sin(mp.get_time() * 5)
        ev[#ev + 1] = D.ev_rect(x, cy - dot, x + dot * 2, cy + dot, TOAST.accent, 100 * a * br, nil, 0, 0, dot)
        x = x + lead
    end
    local function txt(fs, op, bold, str, extra, rgb)
        ev[#ev + 1] = D.ev_text(x, cy, 4, string.format("\\fs%d\\b%d\\c%s\\1a%s%s", fs, bold and 1 or 0, U.ass_color(rgb or TOAST.text),
            U.ass_alpha(op * a), extra or ""), U.ass_escape(str))
    end
    if sp.eyebrow then txt(fs1, 62, true, sp.eyebrow, "\\fsp" .. fsp); x = x + w1 + gap end
    -- Tracked news decodes itself in (experimental_decode), in the toast's own frames
    if title then txt(fs2, 100, true, sp.decode and HV.XA.decode("ts", title, 0.6, false, T.t0) or title); x = x + w2 + gap end
    if sp.extra then txt(fs2, 60, false, sp.extra); x = x + w3 + gap end
    if sp.note then
        ev[#ev + 1] = D.ev_rect(x, cy - dot, x + dot * 2, cy + dot, sp.note_rgb or TOAST.good, 100 * a, nil, 0, 0, dot)
        x = x + dot * 2 + math.floor(8 * S)
        txt(fs2, 78, false, sp.note)
    end
    T.ov = T.ov or mp.create_osd_overlay("ass-events")
    T.ov.res_x, T.ov.res_y, T.ov.z = ww, wh, browser_active and 3004 or 2000     -- above the browser (3000) while it is open
    local data = table.concat(ev, "\n")
    local key = data .. "|" .. ww .. "x" .. wh .. "|" .. T.ov.z
    if key ~= T.last then T.ov.data = data; T.ov:update(); T.last = key end
    -- frames only while something moves (arriving, a shake, new words, the tint thinning, leaving, a breathing dot);
    -- a pill at rest is drawn once and woken again when it starts to leave
    local now = mp.get_time()
    local busy = age < 0.62 or left < 0.32 or (T.swap_t and now - T.swap_t < 0.22) or (glass and thin < 1)
    T.run(busy or lead > 0, busy and 60 or 24, left - 0.3)
end
-- a click on a toast that leads somewhere (Tracked news: the Tracked flyout); true when it took the click
function HV.TS.click(mx, my)
    local T = HV.TS
    local r = T.spec and T.hit
    if not (r and mx and mx >= r[1] and mx <= r[3] and my >= r[2] and my <= r[4]) then return false end
    if T.spec.act == "tracked" then
        T.hide()
        if not HV.TK.is_open() then HV.TK.toggle() end
    end
    return true
end
function HV.TS.run(on, fps, wake)
    local T = HV.TS
    if T.wake then T.wake:kill(); T.wake = nil end
    if on then
        if T.timer and T.fps ~= fps then T.timer:kill(); T.timer = nil end
        if not T.timer then T.timer, T.fps = mp.add_periodic_timer(1 / fps, T.draw), fps end
    else
        if T.timer then T.timer:kill(); T.timer = nil end
        T.wake = mp.add_timeout(math.max(0.02, wake or 0.5), T.draw)
    end
end
function HV.TS.hide()
    local T = HV.TS
    if T.timer then T.timer:kill(); T.timer = nil end
    if T.wake then T.wake:kill(); T.wake = nil end
    T.spec, T.last, T.glass_t = nil, nil, nil
    if T.ov then T.ov.data = ""; T.ov:update() end
    HV.GL.hide("ts")
end
function HV.TS.show(spec, secs)
    local T = HV.TS
    local now = mp.get_time()
    if T.spec and spec.key and T.spec.key == spec.key and now - T.t0 < T.secs - 0.3 then
        -- the same message again (a status that changes): it stays where it is and only its words change
        if T.spec.title ~= spec.title or T.spec.eyebrow ~= spec.eyebrow then T.swap_t = now end
        if T.spec.beside and spec.beside == nil then spec.beside = T.spec.beside end
        T.spec, T.secs = spec, (now - T.t0) + (secs or 3)
    else
        T.spec, T.t0, T.secs, T.at, T.swap_t = spec, now, secs or 3, nil, nil
    end
    T.draw()
end
mp.observe_property("osd-dimensions", "native", function() if HV.TS.spec then HV.TS.draw() end end)
HV.sctw = HV.TS.tw
-- messages while playing: a glass pill (playback_toasts), or mpv's plain text
function HV.say(spec, secs)
    if o.playback_toasts == false then
        local t = {}
        for _, k in ipairs({ "eyebrow", "title", "extra", "note" }) do if spec[k] and spec[k] ~= "" then t[#t + 1] = spec[k] end end
        mp.osd_message(table.concat(t, "  ·  "), secs or 3)
        return
    end
    HV.TS.show(spec, secs)
end
-- beside the Now playing card: waits a moment for the card (it appears once playback has started), then a beat more
function HV.say_np(spec, secs, on_shown)
    local t0 = mp.get_time()
    MS.np_gen = (MS.np_gen or 0) + 1
    local gen = MS.np_gen
    local function show()
        if MS.np_gen ~= gen then return end
        HV.say(spec, secs)
        if on_shown then on_shown(secs) end
    end
    local function try()
        if MS.np_gen ~= gen then return end
        if HV.NP.shown and HV.NP.rect then
            spec.beside = "np"
            mp.add_timeout(0.15, show)
        elseif mp.get_time() - t0 > 2.5 or not o.now_playing_card or o.playback_toasts == false then show()
        else mp.add_timeout(0.1, try) end
    end
    try()
end
MS.say = HV.say
mp.wb_on_bug = function(err)
    local short = tostring(err):gsub("^.-:%d+: ", ""):sub(1, 90)
    HV.TS.show({ eyebrow = "WEBDAV-BROWSER", title = "Hit a bug and carried on", extra = short, kind = "err" }, 6)
end

-- ---------- the status card: one compact floating glass card for every wait ----------
-- Real-Debrid preparing a release, a torrent buffering in rqbit, the download-while-playing fallback. A thin bar that
-- eases to its value, a light band sweeping while there is no number yet, a soft glow breathing at the bar's front edge,
-- a short shake when it fails; it slides in, and shrinks and fades away once playback starts (pulse=no: no motion).
-- spec = { owner, eyebrow, title, line, line_rgb, frac (0-1, nil = no number yet), right ("34 %"), sub, keys, err }
HV.SC = { ov = nil, timer = nil, spec = nil, t0 = 0, frac = 0, out = nil, last = 0 }
-- text fitted to a width (… when cut), measured like the toasts
function HV.scfit(s, max_px, fs, bold)
    s = tostring(s or "")
    local ww, wh = U.canvas_size()
    if s == "" or HV.sctw(s, fs, bold, nil, ww, wh) <= max_px then return s end
    local lo, hi = 1, U.utf8_len(s) - 1
    local function cut(n) return ((U.utf8_sub(s, n):gsub("…$", ""):gsub("[%s%p]+$", ""))) .. "…" end
    while lo < hi do
        local mid = math.ceil((lo + hi) / 2)
        if HV.sctw(cut(mid), fs, bold, nil, ww, wh) <= max_px then lo = mid else hi = mid - 1 end
    end
    return cut(lo)
end
function HV.SC.moving() return o.pulse ~= false end
function HV.SC.show(spec)
    local C = HV.SC
    if not spec then return C.hide() end
    local now = mp.get_time()
    if not C.spec or C.out then C.t0, C.out, C.frac = now, nil, spec.frac or 0 end
    if spec.err and not (C.spec and C.spec.err) then C.err_t = now end
    if not spec.err then C.err_t = nil end
    C.spec = spec
    if spec.secs then C.till = now + spec.secs else C.till = nil end
    -- mpv's idle logo would sit right behind a centred card: hidden while it shows
    if not browser_active and not C.logo and MS.prop("idle-active") and MS.logo then
        C.logo = true; MS.logo(false)
        mp.commandv("script-message", "disable-elements", mp.get_script_name() .. "-card", "idle_indicator")     -- uosc's logo
    end
    C.draw()
    C.pace()
end
-- the card's frames: 60 a second while something moves, 24 while only the bar's glow breathes
function HV.SC.pace()
    local C = HV.SC
    if not C.spec or not HV.SC.moving() then return end
    local fps = C.fast and 60 or 24
    if C.timer and C.fps ~= fps then C.timer:kill(); C.timer = nil end
    if not C.timer then C.timer, C.fps = mp.add_periodic_timer(1 / fps, function() C.draw(); C.pace() end), fps end
end
-- playback is starting: the card shrinks and fades away
function HV.SC.done(owner)
    local C = HV.SC
    if not C.spec or (owner and C.spec.owner ~= owner) then return end
    if not HV.SC.moving() then return C.hide() end
    if not C.out then C.out = mp.get_time() end
    C.fast = true
    C.pace()
end
function HV.SC.hide(owner)
    local C = HV.SC
    if owner and (not C.spec or C.spec.owner ~= owner) then return end
    if C.timer then C.timer:kill(); C.timer = nil end
    C.spec, C.out, C.rest, C.glass_t = nil, nil, nil, nil
    if C.ov then C.ov.data = ""; C.ov:update() end
    if C.logo then
        C.logo = nil
        if not browser_active and MS.logo then MS.logo(true) end
        mp.commandv("script-message", "disable-elements", mp.get_script_name() .. "-card", "")
    end
    HV.GL.hide("sc")
end
function HV.SC.draw()
    local C = HV.SC
    local sp = C.spec
    if not sp then return C.hide() end
    local now = mp.get_time()
    if C.till and now > C.till and not C.out then C.out = now end
    local ww, wh = U.canvas_size()
    local S = wh / 1080
    local moving = HV.SC.moving()
    local function ease(k) k = math.max(0, math.min(1, k)); return 1 - (1 - k) ^ 3 end
    local ain = moving and ease((now - C.t0) / 0.28) or 1
    local a, scale = ain, 1
    if C.out then
        local k = (now - C.out) / 0.32
        if k >= 1 then return C.hide() end
        a, scale = ain * (1 - ease(k)), 1 - 0.07 * ease(k)
    end
    -- the bar eases to its value instead of jumping once a second
    local dt = math.min(0.1, now - (C.last or now))
    C.last = now
    if sp.frac then
        local tgt = math.max(0, math.min(1, sp.frac))
        C.frac = moving and (C.frac + (tgt - C.frac) * math.min(1, dt * 7)) or tgt
        if math.abs(tgt - C.frac) < 0.001 then C.frac = tgt end
    end
    local fs1, fs2, fs3, fs4 = math.max(10, math.floor(12 * S)), math.max(13, math.floor(18 * S)),
        math.max(11, math.floor(14 * S)), math.max(10, math.floor(12.5 * S))
    local pad = math.floor(18 * S)
    local fsp = math.max(1, math.floor(S + 0.5))
    local cw = math.floor(math.min(ww - 40 * S, 560 * S) * scale)
    local bar_h = math.max(3, math.floor(4 * S + 0.5))
    local gap = math.floor(9 * S)
    local ch = pad + fs1 + gap + fs2 + math.floor(gap * 0.7) + fs3 + gap + bar_h + (sp.sub and (gap + fs4) or 0)
        + (sp.keys and (gap + fs4) or 0) + pad
    ch = math.floor(ch * scale)
    local x1, y1, pos = HV.corner(sp.pos or o.download_card_position, cw, ch, S, "center")
    local rest = (not C.out and ain >= 1) and { x1, y1, cw, ch } or C.rest         -- where the glass sits
    if not C.out then C.rest = rest; y1 = y1 + (1 - ain) * 14 * S * ((pos or ""):find("^top") and -1 or 1) end
    if C.err_t and moving then
        local k = now - C.err_t
        if k < 0.45 then x1 = x1 + math.sin(k * 42) * 7 * S * (1 - k / 0.45) end
    end
    local x2, y2 = x1 + cw, y1 + ch
    local rad = math.floor(18 * S)
    local glass = rest and (not browser_active) and HV.GL.show("sc", rest[1], rest[2], rest[1] + rest[3], rest[2] + rest[4], rad, S)
    if glass and not C.glass_t then C.glass_t = now end
    if not glass then C.glass_t = nil end
    local thin = glass and (moving and math.min(1, (now - C.glass_t) / 0.2) or 1) or 0      -- pulse=no: no frames to thin it in
    local ev = {}
    local b = math.max(6, math.floor(16 * S))
    ev[#ev + 1] = string.format("{\\an7\\pos(0,0)\\bord0\\shad0\\blur%d\\1c&H000000&\\1a%s\\3a&HFF&\\p1}%s{\\p0}",
        b, U.ass_alpha(30 * a), D.rounded_path(x1, y1 + b * 0.35, x2, y2 + b * 0.6, rad))
    ev[#ev + 1] = D.ev_rect(x1, y1, x2, y2, TOAST.fill, (HV.GL.SOLID - (HV.GL.SOLID - HV.GL.TINT) * thin) * a, TOAST.edge, 17 * a, fsp, rad)
    -- full frame rate while it arrives, shakes, leaves or its bar is still easing; the breathing glow alone needs less
    C.fast = (now - C.t0 < 0.3) or C.out ~= nil or (C.err_t ~= nil and now - C.err_t < 0.45) or (glass and thin < 1)
        or (sp.frac ~= nil and math.abs(math.max(0, math.min(1, sp.frac)) - C.frac) > 0.001)
    local function txt(x, y, an, fs, op, bold, s, rgb, extra)
        ev[#ev + 1] = D.ev_text(x, y, an, string.format("\\fs%d\\b%d\\c%s\\1a%s%s", fs, bold and 1 or 0, U.ass_color(rgb or TOAST.text),
            U.ass_alpha(op * a), extra or ""), U.ass_escape(s))
    end
    local tx, tr, tw = x1 + pad, x2 - pad, cw - 2 * pad
    local y = y1 + pad
    local right = sp.right or (sp.frac and not sp.err and string.format("%d %%", math.floor(C.frac * 100 + 0.5))) or nil
    local rw = right and HV.sctw(right, fs3, true, nil, ww, wh) or 0
    txt(tx, y + fs1 / 2, 4, fs1, 62, true, HV.scfit(sp.eyebrow or "", tw - rw - pad, fs1, true), nil, "\\fsp" .. fsp)
    if right then txt(tr, y + fs1 / 2, 6, fs3, 90, true, right, sp.err and TOAST.bad or TOAST.text) end
    y = y + fs1 + gap
    txt(tx, y + fs2 / 2, 4, fs2, 100, true, HV.scfit(sp.title or "", tw, fs2, true))
    y = y + fs2 + math.floor(gap * 0.7)
    txt(tx, y + fs3 / 2, 4, fs3, sp.err and 95 or 72, false, HV.scfit(sp.line or "", tw, fs3, false),
        sp.line_rgb or (sp.err and TOAST.bad) or nil)
    y = y + fs3 + gap
    -- the bar
    local bx1, bx2, by1, by2 = tx, tr, y, y + bar_h
    local r_ = bar_h / 2
    ev[#ev + 1] = D.ev_rect(bx1, by1, bx2, by2, TOAST.text, 14 * a, nil, 0, 0, r_)
    local col = sp.err and TOAST.bad or TOAST.accent
    if sp.err then
        ev[#ev + 1] = D.ev_rect(bx1, by1, bx1 + math.max(bar_h * 2, (bx2 - bx1) * math.max(C.frac, 0.02)), by2, col, 85 * a, nil, 0, 0, r_)
    elseif sp.frac then
        local fx = bx1 + math.max(bar_h * 2, (bx2 - bx1) * C.frac)
        ev[#ev + 1] = D.ev_rect(bx1, by1, fx, by2, col, 100 * a, nil, 0, 0, r_)
        if moving and C.frac < 0.999 then
            -- the front edge breathes: a soft glow, about once a second
            local p = 0.5 + 0.5 * math.sin(now * 2 * math.pi / 1.15)
            local gr = bar_h * (1.6 + 0.9 * p)
            ev[#ev + 1] = string.format("{\\an7\\pos(0,0)\\bord0\\shad0\\blur%s\\1c%s\\1a%s\\3a&HFF&\\p1}%s{\\p0}", D.fp(bar_h * 1.4),
                U.ass_color(col), U.ass_alpha((35 + 45 * p) * a), D.rounded_path(fx - gr, (by1 + by2) / 2 - gr, fx + gr, (by1 + by2) / 2 + gr, gr, true))
        end
    elseif moving then
        -- no number yet: a light band sweeps along the bar
        local ph = (now * 0.75) % 1.5 - 0.3
        local w_ = bx2 - bx1
        local s1, s2 = math.max(bx1, bx1 + ph * w_), math.min(bx2, bx1 + (ph + 0.3) * w_)
        if s2 > s1 then ev[#ev + 1] = D.ev_rect(s1, by1, s2, by2, col, 90 * a, nil, 0, 0, r_) end
    end
    y = by2
    if sp.sub then
        y = y + gap
        txt(tx, y + fs4 / 2, 4, fs4, sp.sub_rgb and 92 or 55, false, HV.scfit(sp.sub, tw, fs4, false), sp.sub_rgb)
        y = y + fs4
    end
    if sp.keys then
        y = y + gap
        -- "Esc   Back   T   Torrent": keys bright, what they do muted
        local out, first = {}, true
        for key, what in tostring(sp.keys):gmatch("([^:]+):([^|]+)|?") do
            out[#out + 1] = string.format("{\\b1\\1a%s}%s {\\b0\\1a%s}%s", U.ass_alpha(92 * a), U.ass_escape((first and "" or "     ") .. key),
                U.ass_alpha(55 * a), U.ass_escape(what))
            first = false
        end
        ev[#ev + 1] = D.ev_text(tx, y + fs4 / 2, 4, string.format("\\fs%d\\c%s", fs4, U.ass_color(TOAST.text)), table.concat(out))
    end
    C.ov = C.ov or mp.create_osd_overlay("ass-events")
    C.ov.res_x, C.ov.res_y, C.ov.z = ww, wh, 3005          -- above the browser (3000) and its animation layer
    C.ov.data = table.concat(ev, "\n")
    C.ov:update()
    if not moving and C.timer then C.timer:kill(); C.timer = nil end
end
mp.observe_property("osd-dimensions", "native", function() if HV.SC.spec then HV.SC.draw() end end)
MS.sc = HV.SC


-- the startup toast: ready, the key that opens it, and how the artwork is made
function HV.other_edition()
    local ok, list = pcall(mp.get_property_native, "input-bindings")
    for _, b in ipairs(ok and type(list) == "table" and list or {}) do
        if tostring(b.cmd or ""):find("script-binding webdav_browser/", 1, true) then return true end
    end
    return false
end
if o.startup_toast then
    mp.add_timeout(0.8, function()
        local tries = 0
        local function say()
            tries = tries + 1
            local mode = HV.conv_mode()
            if mode == nil and tries < 20 then return mp.add_timeout(0.3, say) end     -- still checking
            local key = U.knice((tostring(o.open_key_posters or "ctrl+p"):match("[^%s,]+")) or "ctrl+p")
            local extra = "Press " .. key .. " to browse"
            if HV.other_edition() then
                extra = key .. " posters  ·  " .. U.knice((tostring(o.open_key or "ctrl+w"):match("[^%s,]+")) or "ctrl+w") .. " list"
            end
            local spec = { eyebrow = "WEBDAV LIBRARY", title = "Ready", extra = extra, pos = o.startup_toast_position }
            if o.url == "" then
                spec.title, spec.extra = "Almost there", "add url, user and pass to webdav-browser.conf"
            elseif mode == "ffmpeg" then
                spec.note = "FFmpeg artwork"
            elseif mode ~= nil then
                spec.note, spec.note_rgb = ((mode == "powershell") and "PowerShell artwork  ·  add FFmpeg for speed" or (tostring(mode) .. " artwork")), TOAST.warn
            end
            HV.TS.show(spec, (spec.note_rgb or o.url == "") and 5 or 3)
        end
        say()
    end)
end

-- pictures cut off by older versions are cleaned out once, a little after start (cheap: a few bytes per file)
mp.add_timeout(6, function() if PS.enabled() then pcall(PS.sweep_broken) end end)
-- 26.10: wide pictures converted by older versions (possibly stretched) are made again once, cropped (HV.crop_migrate)
mp.add_timeout(0, function()
    local ok, err = pcall(HV.crop_migrate)
    if not ok then msg.warn("artwork: crop clean-up skipped: " .. tostring(err)) end
end)
